// Recursively flatten Beds24 V2 featureCodes / features into a clean
// deduped array of code strings. Beds24 returns this field in many shapes:
//   ["BALCONY", "POOL"]                                — flat string array
//   [["BALCONY"], ["POOL"]]                            — array of arrays
//   ['["BALCONY"]', '["POOL"]']                        — JSON-encoded strings
//   [{ code: 'BALCONY' }, { name: 'POOL' }]            — array of objects
//   "BALCONY,POOL"                                     — comma-separated string
// Without recursive unwrapping the downstream amenity-code mapping receives
// garbage like '["BALCONY"]' (with brackets and quotes) and finds no match.
function extractBeds24FeatureCodes(input) {
  const codes = new Set();
  const walk = (val) => {
    if (val == null) return;
    if (Array.isArray(val)) { val.forEach(walk); return; }
    if (typeof val === 'object') {
      if (val.code) walk(val.code);
      else if (val.name) walk(val.name);
      return;
    }
    if (typeof val !== 'string') return;
    const s = val.trim();
    if (!s) return;
    // Try to parse JSON-encoded arrays/strings the source may have stored.
    if ((s.startsWith('[') && s.endsWith(']')) || (s.startsWith('"') && s.endsWith('"'))) {
      try { walk(JSON.parse(s)); return; } catch { /* fall through */ }
    }
    // Otherwise split on commas (some sources comma-join multiple codes).
    s.split(',').forEach(part => {
      const cleaned = part.trim().replace(/^[\[\]"'\s]+|[\[\]"'\s]+$/g, '');
      if (cleaned) codes.add(cleaned);
    });
  };
  walk(input);
  return [...codes];
}

// Shared HTML sanitiser for room descriptions.
// Matches the client-side DOMPurify allowlist from Step 1.
function sanitizeRoomDescription(value) {
  if (value === null || value === undefined) return value;

  const descOpts = {
    allowedTags: ['strong', 'em', 'b', 'i', 'u', 'p', 'h2', 'h3', 'ul', 'li', 'br', 'a'],
    allowedAttributes: { a: ['href', 'target', 'rel'] },
    allowedSchemes: ['http', 'https', 'mailto'],
    transformTags: { 'div': 'p' }
  };

  if (typeof value === 'string') {
    let parsed;
    try {
      parsed = JSON.parse(value);
    } catch (e) {
      console.warn('[sanitizeRoomDescription] Malformed JSON, passing through unchanged:', value.substring(0, 80));
      return value;
    }
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const out = {};
      for (const lang of Object.keys(parsed)) {
        out[lang] = typeof parsed[lang] === 'string' ? sanitizeHtml(parsed[lang], descOpts) : parsed[lang];
      }
      return JSON.stringify(out);
    }
    return value;
  }

  if (typeof value === 'object' && !Array.isArray(value)) {
    const out = {};
    for (const lang of Object.keys(value)) {
      out[lang] = typeof value[lang] === 'string' ? sanitizeHtml(value[lang], descOpts) : value[lang];
    }
    return out;
  }

  return value;
}

