// Helper: extract plain string from a value that might be a multilingual object {"en":"..."} or a plain string
// Used whenever frontend sends multilingual data to a VARCHAR column
function mlStr(value) {
  if (!value) return value;
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && value !== null) {
    return value.en || value.fr || value.es || value.de || value.nl || value.ja || Object.values(value)[0] || '';
  }
  return String(value);
}

// Helper: check whether a voucher row matches a given property/room scope.
// Mirrors the SQL pattern used in pricing queries:
//   property_id IS NULL AND property_ids IS NULL → applies to all properties,
//     BUT only honoured when voucher.user_id matches the booked property's account
//     (otherwise globally-unscoped vouchers leak across accounts).
//   property_id matches OR property_ids includes  → matches.
// Same shape for rooms; room scope inherits the property-scope account check.
// propertyAccountId MUST be passed by the caller. If omitted/null, the
// applies-to-all arm is rejected — strictest possible default.
// Stripe expects amounts in the currency's smallest unit. For most currencies
// that's cents (USD 1.00 → 100). For zero-decimal currencies like JPY/KRW/VND
// 1 yen = 1 (no multiplier). Multiplying ¥10,953 by 100 would charge ¥1,095,300.
// Use this helper anywhere we send an amount to Stripe (payment_intents,
// refunds, checkout.sessions, transfers, etc).
const STRIPE_ZERO_DECIMAL_CURRENCIES = new Set([
  'BIF','CLP','DJF','GNF','JPY','KMF','KRW','MGA','PYG','RWF','UGX','VND','VUV','XAF','XOF','XPF'
]);
function toStripeAmount(amount, currency) {
  const code = String(currency || 'USD').toUpperCase();
  const n = Number(amount) || 0;
  if (STRIPE_ZERO_DECIMAL_CURRENCIES.has(code)) return Math.round(n);
  return Math.round(n * 100);
}
// Display-side rounding — yen has no fractional unit so an "accommodation
// price" of 10953.20 is a calculation artefact, never a real value.
// Zero-decimal currencies get Math.round; others stay at 2 decimal places.
function roundMoney(amount, currency) {
  const code = String(currency || 'USD').toUpperCase();
  const n = Number(amount) || 0;
  if (STRIPE_ZERO_DECIMAL_CURRENCIES.has(code)) return Math.round(n);
  return Math.round(n * 100) / 100;
}

function voucherMatchesScope(voucher, propertyId, roomId, propertyAccountId, roomAmenityIds) {
  const vPropIds = Array.isArray(voucher.property_ids) ? voucher.property_ids : [];
  const vRoomIds = Array.isArray(voucher.room_ids) ? voucher.room_ids : [];
  const vAmenityIds = Array.isArray(voucher.required_amenity_ids) ? voucher.required_amenity_ids : [];
  // "Applies to all properties on this account" — no property-level scope but
  // account_id matches the booking's property owner. Falls back to legacy
  // user_id === account match for older vouchers that pre-date the
  // account_id column.
  const propScopeEmpty = voucher.property_id == null && vPropIds.length === 0
    && propertyAccountId != null
    && (voucher.account_id === propertyAccountId
        || voucher.user_id === propertyAccountId);
  const roomScopeEmpty = voucher.room_id == null && vRoomIds.length === 0;
  const amenityScopeEmpty = vAmenityIds.length === 0;
  const propMatches = !propertyId || propScopeEmpty
    || voucher.property_id === propertyId
    || vPropIds.includes(propertyId);
  // Room + amenity combine as OR — either match satisfies the room-level check.
  // If BOTH are set and neither matches, reject.
  const roomListMatches = voucher.room_id === roomId || vRoomIds.includes(roomId);
  const amenityMatches = Array.isArray(roomAmenityIds)
    && roomAmenityIds.some(aid => vAmenityIds.includes(aid));
  const roomMatches = !roomId
    || (roomScopeEmpty && amenityScopeEmpty)      // no scope set at all → applies to any room on property
    || roomListMatches                             // explicit room match
    || (!amenityScopeEmpty && amenityMatches);     // amenity match
  return propMatches && roomMatches;
}

