// ─── User OAuth (for GA Admin / Data / Search Console) ───────────────────
// Used when GA UI rejects the service-account email — common with
// non-org-attached projects. The user grants GAS access once via standard
// OAuth, we keep their refresh token, and call GA APIs as that user.
const GOOGLE_OAUTH_SCOPES = [
  'https://www.googleapis.com/auth/userinfo.email',
  'https://www.googleapis.com/auth/userinfo.profile',
  'https://www.googleapis.com/auth/analytics.readonly',
  'https://www.googleapis.com/auth/analytics.edit',
  'https://www.googleapis.com/auth/webmasters',
  'https://www.googleapis.com/auth/siteverification'
];
const GOOGLE_OAUTH_CALLBACK = (process.env.PUBLIC_BASE_URL || 'https://admin.gas.travel') + '/api/admin/google-oauth/callback';

function buildOAuthClient() {
  const id = process.env.GOOGLE_OAUTH_CLIENT_ID;
  const secret = process.env.GOOGLE_OAUTH_CLIENT_SECRET;
  if (!id || !secret) return null;
  return new google.auth.OAuth2(id, secret, GOOGLE_OAUTH_CALLBACK);
}

// Returns an authenticated OAuth2 client using the stored user refresh
// token. Caller can pass this as `auth` to any google.* SDK constructor.
// Returns null when no user has connected — caller should fall back to SA.
async function getUserAuthClient() {
  const oauth = buildOAuthClient();
  if (!oauth) return null;
  const r = await pool.query(
    `SELECT refresh_token FROM google_oauth_tokens WHERE refresh_token IS NOT NULL ORDER BY updated_at DESC LIMIT 1`
  );
  if (!r.rows[0]) return null;
  oauth.setCredentials({ refresh_token: r.rows[0].refresh_token });
  return oauth;
}

async function getSearchConsoleClient() {
  // Legacy — returns whichever single client is available. Kept for
  // any older caller. New code should use _scQueryWithFallback below
  // which tries service account first, falls back to user OAuth on
  // per-property "sufficient permission" errors.
  if (searchConsole) return searchConsole;
  if (isUserOAuthRecentlyDead()) {
    const err = new Error('Google Search Console session expired — click Reconnect Google');
    err.needsReauth = true;
    throw err;
  }
  const userAuth = await getUserAuthClient();
  if (userAuth) return google.searchconsole({ version: 'v1', auth: userAuth });
  throw new Error('No Google auth configured');
}

// Query wrapper — tries service account first (permanent creds,
// never expires), falls back to user OAuth on 403 "sufficient
// permission" errors (service account not yet added as user on this
// specific property). Both auth paths coexist during the SA
// migration so sites not yet opted-in still work via user OAuth.
async function _scQueryWithFallback(siteUrl, requestBody) {
  let saErr = null;
  if (searchConsole) {
    try {
      return await searchConsole.searchanalytics.query({ siteUrl, requestBody });
    } catch (e) {
      // Property-permission error → fall through to user OAuth.
      // Any other error (429 rate-limit, network, etc.) → rethrow.
      if (!/sufficient permission/i.test(e?.message || '')) throw e;
      saErr = e;
    }
  }
  // Service account has no access to this property → try user OAuth
  if (isUserOAuthRecentlyDead()) {
    const err = new Error('Google Search Console session expired — click Reconnect Google');
    err.needsReauth = true;
    throw err;
  }
  const userAuth = await getUserAuthClient();
  if (!userAuth) {
    // Neither auth path can reach this property. Rethrow the SA
    // error so _scAuthError shows the "add service account as user"
    // banner with the exact email.
    throw saErr || new Error('No Google auth configured');
  }
  const userSc = google.searchconsole({ version: 'v1', auth: userAuth });
  try {
    return await userSc.searchanalytics.query({ siteUrl, requestBody });
  } catch (uErr) {
    // Detect dead user token → mark cache so we skip user OAuth
    // for the next 5 min. Rethrow so caller handles the response.
    if (/invalid_grant|invalid_request/i.test(uErr?.message || '')) markUserOAuthDead();
    throw uErr;
  }
}

// Same fallback pattern for sites.list() (used by /api/admin/seo/sites)
async function _scSitesListWithFallback() {
  const seen = new Map();
  if (searchConsole) {
    try {
      const r = await searchConsole.sites.list();
      (r.data.siteEntry || []).forEach(s => seen.set(s.siteUrl, { url: s.siteUrl, permission: s.permissionLevel, via: 'service_account' }));
    } catch (_) { /* fall through */ }
  }
  try {
    const userAuth = await getUserAuthClient();
    if (userAuth) {
      const uSc = google.searchconsole({ version: 'v1', auth: userAuth });
      const r = await uSc.sites.list();
      (r.data.siteEntry || []).forEach(s => {
        if (!seen.has(s.siteUrl)) seen.set(s.siteUrl, { url: s.siteUrl, permission: s.permissionLevel, via: 'user_oauth' });
      });
    }
  } catch (_) { /* swallow */ }
  return Array.from(seen.values());
}

// Central helper for the four SC endpoints — same detection everywhere.
// Distinguishes:
//   (a) TOKEN DEAD (invalid_grant / invalid_request / 401 unauthorized)
//       → user needs to reconnect. Marks cache, returns needs_reauth.
//   (b) PROPERTY NOT ACCESSIBLE (403 "sufficient permission" — the
//       token is FINE, the user just isn't added as a user on that
//       specific GSC property) → returns a clean "no access" error,
//       does NOT mark the token dead, does NOT show reauth banner.
//   (c) OTHER errors → passthrough to the caller's own handler.
function _scAuthError(res, error) {
  const msg = error?.message || '';
  const status = String(error?.code || error?.response?.status || '');

  // Property-permission error — auth is FINE, GAS just isn't a user on
  // this specific Search Console property. Since we now prefer the
  // service account (never expires, no user-OAuth juggling), the fix
  // is always "add the service-account email as a user on this GSC
  // property" — one-time per site, works forever.
  if (/sufficient permission/i.test(msg) || (status === '403' && !/invalid_grant|invalid_request|unauthorized/i.test(msg))) {
    return res.json({
      success: false,
      no_property_access: true,
      service_account_email: googleServiceAccountEmail,
      error: 'GAS is not added as a user on this site\'s Search Console property. Fix: open the property in Google Search Console → Settings → Users and permissions → Add user: ' + (googleServiceAccountEmail || 'gas-platform-service@zippy-chariot-313210.iam.gserviceaccount.com') + ' → Full → Save. One-time per site, then GAS reads work forever.',
    });
  }

  // Real token-dead / auth-failure — mark cache + tell frontend to reauth
  const looksAuthDead = error?.needsReauth
    || /invalid_grant|invalid_request|unauthorized/i.test(msg)
    || status === '401';
  if (looksAuthDead) {
    markUserOAuthDead();
    return res.json({
      success: false,
      needs_reauth: true,
      error: 'Google Search Console session expired — click Reconnect Google to fix.',
    });
  }
  return null;
}

// Tiny helper — cached-in-request-scope email lookup for error msgs.
// Cheap because google_oauth_tokens is a single row.
let _currentGoogleEmailCache = { at: 0, val: null };
function currentGoogleEmail() {
  if (Date.now() - _currentGoogleEmailCache.at < 30000) return _currentGoogleEmailCache.val;
  // fire-and-forget; on first call returns null, populates for next
  pool.query(`SELECT email FROM google_oauth_tokens WHERE refresh_token IS NOT NULL ORDER BY updated_at DESC LIMIT 1`)
    .then(r => { _currentGoogleEmailCache = { at: Date.now(), val: r.rows[0]?.email || null }; })
    .catch(() => {});
  return _currentGoogleEmailCache.val;
}

// PageSpeed cache — 6h TTL per site_url. Lighthouse takes 10-20s and
// its scores don't move minute-to-minute. Steve 2026-08-20 — monthly
// report was tripping Railway's upstream timeout when Lighthouse was
// slow; caching lets warm requests return in <1s.
const _pageSpeedCache = new Map();

// Short-lived cache: when user OAuth fails with invalid_grant, skip the
// user-side probe for the next 5 minutes. Otherwise every dashboard load
// re-does a doomed Google token-refresh round-trip (~1-3s each). Cleared
// when the operator successfully reconnects Google (see google-oauth
// connect handler).
let _userOAuthDeadUntil = 0;
function markUserOAuthDead() { _userOAuthDeadUntil = Date.now() + 5 * 60 * 1000; }
function isUserOAuthRecentlyDead() { return Date.now() < _userOAuthDeadUntil; }
function clearUserOAuthDeadCache() { _userOAuthDeadUntil = 0; }

// Pick the right GA4 Data client for a given property — probes SA-first
// because GAS-auto-created properties are owned by the service account.
// If SA is denied (operator manually pointed at an external GA4 they
// own, OR SA was rotated and dropped from the property's ACL), probes
// user OAuth. Returns BOTH errors when both fail so the caller can
// report the more actionable cause.
async function pickGa4DataClient(propertyId) {
  const probe = async (client) => client.properties.runReport({
    property: propertyId,
    requestBody: {
      dateRanges: [{ startDate: 'today', endDate: 'today' }],
      metrics: [{ name: 'activeUsers' }]
    }
  });
  const describe = (e) => ({
    code: String(e.code || e.response?.status || 'UNKNOWN'),
    reason: e.errors?.[0]?.reason || e.response?.data?.error?.status || null,
    message: e.message
  });

  let saErr = null;
  if (analyticsData) {
    try {
      await probe(analyticsData);
      return { client: analyticsData, source: 'service_account', sa_error: null, user_error: null };
    } catch (e) {
      saErr = describe(e);
      console.warn(`[pickGa4DataClient] SA probe failed for ${propertyId}: code=${saErr.code} reason=${saErr.reason} msg=${saErr.message}`);
    }
  }

  let userClient = null;
  let userErr = null;
  // Skip user OAuth probe entirely if it's been failing recently — every
  // probe pays a Google token-refresh round-trip, and 1-3s × every site
  // on the master overview adds up fast.
  if (isUserOAuthRecentlyDead()) {
    userErr = { code: 'CACHED', reason: 'recently_failed', message: 'user OAuth failed in last 5 min — probe skipped' };
  } else {
    const userAuth = await getUserAuthClient();
    if (userAuth) {
      userClient = google.analyticsdata({ version: 'v1beta', auth: userAuth });
      try {
        await probe(userClient);
        return { client: userClient, source: 'user_oauth', sa_error: saErr, user_error: null };
      } catch (e) {
        userErr = describe(e);
        console.warn(`[pickGa4DataClient] user OAuth probe failed for ${propertyId}: code=${userErr.code} reason=${userErr.reason} msg=${userErr.message}`);
        // Any 4xx auth-class error → cache the dead flag. invalid_grant
        // (refresh token expired/revoked) is the dominant case but 401
        // / 403 from the token endpoint also justify skipping.
        if (/invalid_grant|invalid_request|unauthorized/i.test(userErr.message || '') || ['400','401','403'].includes(String(userErr.code))) {
          markUserOAuthDead();
        }
      }
    }
  }

  // Neither client can read this property. Throw a synthetic error so
  // the dashboard catch surfaces a clear message. Prefer the SA error
  // (the property was probably GAS-created → SA should have access →
  // SA's reason is the actionable one).
  const chosen = saErr || userErr || { code: 'UNKNOWN', reason: null, message: 'No Google auth available' };
  const err = new Error(chosen.message);
  err.code = chosen.code;
  err.errors = chosen.reason ? [{ reason: chosen.reason }] : [];
  err.sa_error = saErr;
  err.user_error = userErr;
  throw err;
}

async function getSiteVerificationClient() {
  const userAuth = await getUserAuthClient();
  if (userAuth) return google.siteVerification({ version: 'v1', auth: userAuth });
  return siteVerification;
}

