    // Standard CM = cm_price × markup, with per-date operator override.
    // Override lives in its own column so the cron can freely recompute
    // standard_price on every cm_price write without stomping operator edits.
    try {
      await pool.query(`ALTER TABLE room_availability ADD COLUMN IF NOT EXISTS standard_price_override NUMERIC(10,2)`);
      console.log('✅ standard_price_override column ensured');
    } catch (e) {
      console.log('ℹ️  standard_price_override column:', e.message);
    }

    // Trigger: every cm_price write recomputes standard_price using the
    // room's markup rule, unless a per-date override is set.
    // Steve's model: Reference CM (cm_price) drives everything; Standard CM
    // (standard_price) is a derived copy. Operator opts out of the formula
    // per date by setting standard_price_override.
    try {
      await pool.query(`
        CREATE OR REPLACE FUNCTION recompute_standard_price() RETURNS TRIGGER AS $$
        DECLARE
          v_rule_type TEXT;
          v_rule_value NUMERIC;
          v_bpm NUMERIC;
        BEGIN
          IF NEW.standard_price_override IS NOT NULL THEN
            NEW.standard_price := NEW.standard_price_override;
            RETURN NEW;
          END IF;
          IF NEW.cm_price IS NULL THEN
            RETURN NEW;
          END IF;
          SELECT bu.price_rule_type, bu.price_rule_value, p.booking_page_multiplier
            INTO v_rule_type, v_rule_value, v_bpm
            FROM bookable_units bu
            LEFT JOIN properties p ON bu.property_id = p.id
            WHERE bu.id = NEW.room_id;
          IF v_rule_type = 'percentage' AND v_rule_value IS NOT NULL AND v_rule_value <> 0 THEN
            NEW.standard_price := ROUND(NEW.cm_price * (1 + v_rule_value / 100), 2);
          ELSIF v_rule_type = 'fixed' AND v_rule_value IS NOT NULL AND v_rule_value <> 0 THEN
            NEW.standard_price := ROUND(NEW.cm_price + v_rule_value, 2);
          ELSIF v_bpm IS NOT NULL AND v_bpm > 0 AND v_bpm <> 1 THEN
            NEW.standard_price := ROUND(NEW.cm_price * v_bpm, 2);
          ELSE
            NEW.standard_price := NEW.cm_price;
          END IF;
          RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
      `);
      await pool.query(`DROP TRIGGER IF EXISTS recompute_standard_price_trg ON room_availability`);
      await pool.query(`
        CREATE TRIGGER recompute_standard_price_trg
          BEFORE INSERT OR UPDATE OF cm_price, standard_price_override ON room_availability
          FOR EACH ROW
          EXECUTE FUNCTION recompute_standard_price();
      `);
      console.log('✅ standard_price recompute trigger installed');
    } catch (e) {
      console.log('ℹ️  standard_price trigger:', e.message);
    }
    
