app.get('/api/health/stripe', async (req, res) => {
  try {
    if (!process.env.STRIPE_SECRET_KEY) return res.status(500).json({ ok: false, error: 'STRIPE_SECRET_KEY not set' });
    const balance = await stripe.balance.retrieve();
    const sk = process.env.STRIPE_SECRET_KEY;
    const pk = process.env.STRIPE_PUBLISHABLE_KEY || '';
    res.json({
      ok: true,
      secret_key_prefix: sk.slice(0, 8) + '…' + sk.slice(-4),
      publishable_key_prefix: pk ? pk.slice(0, 8) + '…' + pk.slice(-4) : '(not set)',
      livemode: !!balance.livemode,
      currencies: (balance.available || []).map(b => b.currency)
    });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message, code: e.code || e.type });
  }
});

