// Update an individual unit — guest-facing rename + ops state.
app.put('/api/admin/individual-units/:id', async (req, res) => {
  try {
    const { unit_name, unit_number, notes, status, floor_number, building_name } = req.body;
    if (!unit_name || !unit_name.trim()) return res.json({ success: false, error: 'unit_name required' });
    const r = await pool.query(
      `UPDATE individual_units SET
         unit_name = $1,
         unit_number = COALESCE($2, unit_number),
         notes = $3,
         status = $4,
         floor_number = COALESCE($5, floor_number),
         building_name = COALESCE($6, building_name),
         updated_at = NOW()
       WHERE id = $7
       RETURNING *`,
      [unit_name.trim(), unit_number || null, notes || null, status || null, floor_number || null, building_name || null, req.params.id]
    );
    if (r.rows.length === 0) return res.json({ success: false, error: 'Unit not found' });
    res.json({ success: true, unit: r.rows[0] });
  } catch (error) {
    // unique constraint on (bookable_unit_id, unit_name)
    if (/duplicate key/.test(error.message)) {
      return res.json({ success: false, error: 'Another unit in this room already uses that name' });
    }
    res.json({ success: false, error: error.message });
  }
});

