// Start Stripe Connect OAuth flow
app.get('/api/stripe/connect/:accountId', async (req, res) => {
    try {
        const { accountId } = req.params;
        
        // Verify account exists
        const account = await pool.query('SELECT * FROM accounts WHERE id = $1', [accountId]);
        if (account.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Account not found' });
        }
        
        // Build Stripe OAuth URL
        const state = Buffer.from(JSON.stringify({ accountId })).toString('base64');
        
        const stripeConnectUrl = `https://connect.stripe.com/oauth/authorize?` +
            `response_type=code&` +
            `client_id=${process.env.STRIPE_CLIENT_ID}&` +
            `scope=read_write&` +
            `state=${state}&` +
            `redirect_uri=${encodeURIComponent('https://admin.gas.travel/api/stripe/callback')}`;
        
        res.redirect(stripeConnectUrl);
    } catch (error) {
        console.error('Stripe connect error:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

// Per-property Stripe Connect — OAuth-only alternative to the older
// paste-your-publishable-and-secret-keys flow. Client clicks the
// Connect Stripe button on GAS → their Stripe login → approves → we
// land back with stripe_user_id + publishable_key + access_token and
// write a payment_configurations row for the specified property.
//
// Barbara's Charles House was the trigger (2026-07-09 — accidental
// delete of her row exposed how painful the manual paste re-entry is).
// One-click OAuth = no keys ever seen or typed by the operator.
app.get('/api/admin/properties/:propertyId/stripe/connect', async (req, res) => {
    try {
        const propertyId = parseInt(req.params.propertyId, 10);
        // Accept token via query so a plain <a href> from the property
        // Payments UI can start the flow — matches the pattern used for
        // Channex + RemoteLock OAuth starts elsewhere in this file.
        if (req.query?.token && !req.headers.authorization) {
            req.headers.authorization = 'Bearer ' + String(req.query.token);
        }
        const decoded = await extractAccountFromToken(req);
        if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
        // Confirm the property belongs to the caller's account (master admins bypass).
        const prop = await pool.query('SELECT id, account_id, name FROM properties WHERE id = $1', [propertyId]);
        if (!prop.rows[0]) return res.status(404).json({ success: false, error: 'Property not found' });
        if (prop.rows[0].account_id !== (decoded.accountId || decoded.id) && decoded.role !== 'master_admin') {
            return res.status(403).json({ success: false, error: 'Not your property' });
        }
        const state = Buffer.from(JSON.stringify({
            propertyId,
            accountId: prop.rows[0].account_id,
            name: prop.rows[0].name,
            nonce: require('crypto').randomBytes(8).toString('hex'),
            issued: Date.now(),
        })).toString('base64url');
        const stripeConnectUrl = 'https://connect.stripe.com/oauth/authorize?' +
            'response_type=code&' +
            `client_id=${process.env.STRIPE_CLIENT_ID}&` +
            'scope=read_write&' +
            `state=${encodeURIComponent(state)}&` +
            // Reuse the existing account-level /api/stripe/callback so the
            // redirect URI is already whitelisted in the Stripe Connect
            // dashboard. The callback handler dispatches by state shape
            // (propertyId present → save to payment_configurations, else
            // save to accounts as before).
            `redirect_uri=${encodeURIComponent('https://admin.gas.travel/api/stripe/callback')}`;
        res.redirect(302, stripeConnectUrl);
    } catch (e) {
        console.error('[property stripe connect]', e);
        res.status(500).json({ success: false, error: e.message });
    }
});

// Callback lands here after the operator approves in Stripe's consent
// screen. Exchange the code for tokens, pull publishable_key + secret
// (access_token) + stripe_user_id, upsert into payment_configurations
// against the property carried in state.
app.get('/api/admin/properties/stripe/callback', async (req, res) => {
    try {
        const { code, state, error, error_description } = req.query;
        if (error) {
            return res.redirect('/gas-admin.html#properties?stripe_error=' + encodeURIComponent(error_description || error));
        }
        if (!code || !state) return res.status(400).send('Missing code or state');
        let stateData;
        try {
            stateData = JSON.parse(Buffer.from(String(state), 'base64url').toString());
        } catch (_) {
            return res.status(400).send('Invalid state');
        }
        const { propertyId, accountId, name } = stateData;
        if (!Number.isFinite(parseInt(propertyId, 10))) return res.status(400).send('Bad property in state');
        const oauth = await stripe.oauth.token({ grant_type: 'authorization_code', code });
        const credentials = {
            stripe_account_id: oauth.stripe_user_id,
            account_id: oauth.stripe_user_id,
            publishable_key: oauth.stripe_publishable_key || null,
            secret_key: oauth.access_token || null,
            refresh_token: oauth.refresh_token || null,
            scope: oauth.scope || 'read_write',
            connected_at: new Date().toISOString(),
        };
        // Upsert against (account_id, property_id, provider). Overwrites a
        // previously-connected row so re-connect on the same property
        // replaces the stale credentials without leaving orphans.
        const existing = await pool.query(
            `SELECT id FROM payment_configurations WHERE account_id = $1 AND property_id = $2 AND provider = 'stripe' LIMIT 1`,
            [accountId, propertyId]
        );
        if (existing.rows[0]) {
            await pool.query(
                `UPDATE payment_configurations SET credentials = $2::jsonb, is_enabled = true, test_mode = false, updated_at = NOW() WHERE id = $1`,
                [existing.rows[0].id, JSON.stringify(credentials)]
            );
        } else {
            await pool.query(
                `INSERT INTO payment_configurations
                    (account_id, property_id, provider, name, is_enabled, credentials, test_mode, is_default)
                 VALUES ($1, $2, 'stripe', $3, true, $4::jsonb, false, true)`,
                [accountId, propertyId, (name || 'Stripe').slice(0, 100), JSON.stringify(credentials)]
            );
        }
        console.log(`[property stripe connect] connected acct=${accountId} property=${propertyId} stripe=${oauth.stripe_user_id}`);
        res.redirect('/gas-admin.html#properties?stripe_connected=1&property_id=' + propertyId);
    } catch (e) {
        console.error('[property stripe callback]', e);
        res.redirect('/gas-admin.html#properties?stripe_error=' + encodeURIComponent(e.message));
    }
});

// Stripe OAuth callback
app.get('/api/stripe/callback', async (req, res) => {
    try {
        const { code, state, error, error_description } = req.query;
        
        // Handle user cancellation or errors
        if (error) {
            console.error('Stripe OAuth error:', error, error_description);
            return res.redirect('https://admin.gas.travel/gas-admin.html#accounts?stripe_error=' + encodeURIComponent(error_description || error));
        }
        
        // Decode state — supports two shapes:
        //   { accountId } — legacy account-level connect
        //   { propertyId, accountId, name } — per-property connect
        //     (Charles House pilot 2026-07-09).
        // base64url encoding is used by the new flow; legacy uses plain
        // base64. Try both so old links + new links both work.
        let stateData;
        try {
            stateData = JSON.parse(Buffer.from(state, 'base64url').toString());
        } catch (_) {
            try {
                stateData = JSON.parse(Buffer.from(state, 'base64').toString());
            } catch (e2) {
                return res.redirect('https://admin.gas.travel/gas-admin.html#accounts?stripe_error=invalid_state');
            }
        }
        const propertyId = stateData?.propertyId;
        const accountId = stateData?.accountId;

        // Exchange authorization code for access token
        const response = await stripe.oauth.token({
            grant_type: 'authorization_code',
            code: code
        });

        const connectedAccountId = response.stripe_user_id;

        // Per-property flow — write to payment_configurations, not accounts.
        if (Number.isFinite(parseInt(propertyId, 10))) {
            const credentials = {
                stripe_account_id: connectedAccountId,
                account_id: connectedAccountId,
                publishable_key: response.stripe_publishable_key || null,
                secret_key: response.access_token || null,
                refresh_token: response.refresh_token || null,
                scope: response.scope || 'read_write',
                connected_at: new Date().toISOString(),
            };
            const existing = await pool.query(
                `SELECT id FROM payment_configurations WHERE account_id = $1 AND property_id = $2 AND provider = 'stripe' LIMIT 1`,
                [accountId, propertyId]
            );
            if (existing.rows[0]) {
                await pool.query(
                    `UPDATE payment_configurations SET credentials = $2::jsonb, is_enabled = true, test_mode = false, updated_at = NOW() WHERE id = $1`,
                    [existing.rows[0].id, JSON.stringify(credentials)]
                );
            } else {
                await pool.query(
                    `INSERT INTO payment_configurations
                        (account_id, property_id, provider, name, is_enabled, credentials, test_mode, is_default)
                     VALUES ($1, $2, 'stripe', $3, true, $4::jsonb, false, true)`,
                    [accountId, propertyId, (stateData.name || 'Stripe').slice(0, 100), JSON.stringify(credentials)]
                );
            }
            console.log(`✅ Property Stripe connected — acct ${accountId} · property ${propertyId} · stripe ${connectedAccountId}`);
            return res.redirect('https://admin.gas.travel/gas-admin.html#properties?stripe_connected=1&property_id=' + propertyId);
        }
        
        // Update account with Stripe connected account ID
        await pool.query(`
            UPDATE accounts 
            SET stripe_account_id = $1,
                stripe_account_status = 'active',
                stripe_onboarding_complete = true,
                updated_at = NOW()
            WHERE id = $2
        `, [connectedAccountId, accountId]);
        
        console.log(`✅ Stripe connected for account ${accountId}: ${connectedAccountId}`);
        
        // Redirect back to admin accounts page with success
        res.redirect('https://admin.gas.travel/gas-admin.html#accounts?stripe_connected=true');
        
    } catch (error) {
        console.error('Stripe callback error:', error);
        res.redirect('https://admin.gas.travel/gas-admin.html#accounts?stripe_error=' + encodeURIComponent(error.message));
    }
});

// Get Stripe connection status for an account
app.get('/api/accounts/:accountId/stripe-status', async (req, res) => {
    try {
        const { accountId } = req.params;

        // Check account-level keys
        const result = await pool.query(`
            SELECT stripe_account_id, stripe_account_status, stripe_onboarding_complete,
                   stripe_publishable_key, stripe_secret_key, stripe_name
            FROM accounts WHERE id = $1
        `, [accountId]);

        if (result.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Account not found' });
        }

        const account = result.rows[0];
        let source = null;
        let publishableKey = null;
        let connected = false;

        // Level 1: Account-level keys
        if (account.stripe_secret_key || account.stripe_account_id) {
            source = 'account';
            publishableKey = account.stripe_publishable_key || null;
            connected = true;
        }

        // Level 2: Payment configurations table
        if (!connected) {
            const pcResult = await pool.query(`
                SELECT credentials FROM payment_configurations
                WHERE account_id = $1 AND provider = 'stripe' AND is_enabled = true
                ORDER BY property_id NULLS FIRST LIMIT 1
            `, [accountId]);
            if (pcResult.rows.length > 0) {
                source = 'payment_config';
                publishableKey = pcResult.rows[0].credentials?.publishable_key || null;
                connected = true;
            }
        }

        // Level 3: Legacy property-level keys
        if (!connected) {
            const propResult = await pool.query(`
                SELECT stripe_publishable_key, stripe_secret_key, name
                FROM properties
                WHERE account_id = $1 AND stripe_secret_key IS NOT NULL
                LIMIT 1
            `, [accountId]);
            if (propResult.rows.length > 0) {
                source = 'property';
                publishableKey = propResult.rows[0].stripe_publishable_key || null;
                connected = true;
            }
        }

        res.json({
            success: true,
            connected,
            source,
            stripe_account_id: account.stripe_account_id,
            stripe_name: account.stripe_name,
            status: account.stripe_account_status,
            onboarding_complete: account.stripe_onboarding_complete,
            has_keys: connected,
            publishable_key: publishableKey
        });

    } catch (error) {
        console.error('Error getting Stripe status:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

// Disconnect Stripe account
// Save Stripe API keys for an account (manual entry)
app.post('/api/accounts/:accountId/stripe-keys', async (req, res) => {
  try {
    const { accountId } = req.params;
    const { stripe_publishable_key, stripe_secret_key, stripe_name, payment_methods } = req.body;
    
    if (!stripe_secret_key) {
      return res.status(400).json({ success: false, error: 'Secret key is required' });
    }
    
    // Ensure columns exist
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS stripe_publishable_key TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS stripe_secret_key TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS stripe_name VARCHAR(255)`);
    
    // Validate the key by making a test API call
    try {
      const testStripe = new (require('stripe'))(stripe_secret_key);
      await testStripe.balance.retrieve();
    } catch (e) {
      return res.status(400).json({ success: false, error: 'Invalid Stripe key - could not authenticate: ' + e.message });
    }
    
    // Save keys
    await pool.query(`
      UPDATE accounts 
      SET stripe_publishable_key = $1,
          stripe_secret_key = $2,
          stripe_name = $3,
          stripe_account_status = 'active',
          stripe_onboarding_complete = true,
          updated_at = NOW()
      WHERE id = $4
    `, [stripe_publishable_key || null, stripe_secret_key, stripe_name || null, accountId]);
    
    // Save payment methods in account settings
    if (payment_methods) {
      await pool.query(`
        UPDATE accounts 
        SET settings = COALESCE(settings, '{}'::jsonb) || $1::jsonb
        WHERE id = $2
      `, [JSON.stringify({ payment_methods }), accountId]);
    }
    
    console.log(`✅ Stripe keys saved for account ${accountId}`);
    res.json({ success: true });
  } catch (error) {
    console.error('Save Stripe keys error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

app.post('/api/accounts/:accountId/stripe-disconnect', async (req, res) => {
    try {
        const { accountId } = req.params;
        
        // Get current stripe account ID
        const account = await pool.query('SELECT stripe_account_id FROM accounts WHERE id = $1', [accountId]);
        
        if (account.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Account not found' });
        }
        
        const stripeAccountId = account.rows[0].stripe_account_id;
        
        // Revoke access if connected.
        // Fallback pattern: platform rotated its Connect client_id
        // (2026-07-09). Connections issued under the OLD client_id must
        // be deauthed against that ID, not the new one, or Stripe returns
        // "application does not have access". Try current, then legacy.
        if (stripeAccountId) {
            const deauthClientIds = [
                process.env.STRIPE_CLIENT_ID,
                process.env.STRIPE_CLIENT_ID_LEGACY,
            ].filter(Boolean);
            let deauthed = false;
            for (const cid of deauthClientIds) {
                try {
                    await stripe.oauth.deauthorize({
                        client_id: cid,
                        stripe_user_id: stripeAccountId
                    });
                    deauthed = true;
                    break;
                } catch (e) {
                    console.log(`Stripe deauthorize warning (client_id ${cid.slice(0,10)}…):`, e.message);
                }
            }
            if (!deauthed) {
                console.log('Stripe deauthorize failed on all known client_ids — proceeding with local disconnect');
            }
        }
        
        // Clear Stripe fields in database
        await pool.query(`
            UPDATE accounts 
            SET stripe_account_id = NULL,
                stripe_account_status = NULL,
                stripe_onboarding_complete = false,
                stripe_publishable_key = NULL,
                stripe_secret_key = NULL,
                stripe_name = NULL,
                updated_at = NOW()
            WHERE id = $1
        `, [accountId]);
        
        res.json({ success: true, message: 'Stripe disconnected' });

    } catch (error) {
        console.error('Error disconnecting Stripe:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

// =====================================================
// SQUARE OAUTH INTEGRATION (Phase 1 — connect flow)
// =====================================================
// Mirrors Stripe Connect: per-account OAuth so each operator's funds land in
// their own Square dashboard. Sandbox vs production gated by SQUARE_ENVIRONMENT.
// Phase 1 ships connect + status + disconnect only — checkout / charge / card-on-
// file land in later phases.

function getSquareEnv() {
    const env = (process.env.SQUARE_ENVIRONMENT || 'sandbox').toLowerCase();
    const isProd = env === 'production';
    return {
        env: isProd ? 'production' : 'sandbox',
        webBase: isProd ? 'https://connect.squareup.com' : 'https://connect.squareupsandbox.com',
        apiBase: isProd ? 'https://connect.squareup.com' : 'https://connect.squareupsandbox.com',
    };
}

const SQUARE_SCOPES = [
    'MERCHANT_PROFILE_READ',
    'PAYMENTS_READ',
    'PAYMENTS_WRITE',
    'CUSTOMERS_READ',
    'CUSTOMERS_WRITE',
    'ORDERS_READ',
    'ORDERS_WRITE',
].join('+');

// Ensure square_* columns exist on accounts + bookings (idempotent — safe to re-run).
async function ensureSquareSchema() {
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_merchant_id VARCHAR(50)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_access_token TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_refresh_token TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_token_expires_at TIMESTAMP`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_environment VARCHAR(20)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_business_name VARCHAR(255)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_onboarding_complete BOOLEAN DEFAULT false`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_status VARCHAR(50)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS square_location_id VARCHAR(50)`);
    // Per-booking Square payment artifacts. Mirror of stripe_payment_intent_id /
    // stripe_customer_id shape so existing reporting + reconciliation can extend.
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS square_payment_id VARCHAR(100)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS square_customer_id VARCHAR(100)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS square_card_id VARCHAR(100)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS square_location_id VARCHAR(50)`);
}
ensureSquareSchema().catch((e) => console.error('Square schema migration failed:', e.message));

// Cache: merchant location keyed by accountId. Square requires a location_id
// on every Payments API call; for simplicity we always use the first location.
// We also cache the location's currency — Square merchants are single-currency
// and reject payments in any other (e.g. a GBP-only sandbox seller can't be
// charged USD even though the property is priced in USD). In-process cache,
// 1h TTL.
const _squareLocationCache = new Map(); // accountId -> { id, currency, fetched_at }
async function getSquareLocationForAccount(accountId) {
    const cached = _squareLocationCache.get(accountId);
    if (cached && (Date.now() - cached.fetched_at) < 60 * 60 * 1000) {
        return { id: cached.id, currency: cached.currency };
    }
    const r = await pool.query(
        `SELECT square_access_token, square_environment, square_location_id
           FROM accounts WHERE id = $1`,
        [accountId]
    );
    if (r.rows.length === 0 || !r.rows[0].square_access_token) return null;
    const row = r.rows[0];
    // Always hit /v2/locations on first call (or after TTL) so we capture the
    // currency too. Once cached we skip the API.
    const accessToken = await refreshSquareTokenIfNeeded(accountId) || row.square_access_token;
    const sq = (row.square_environment === 'production')
        ? { apiBase: 'https://connect.squareup.com' }
        : { apiBase: 'https://connect.squareupsandbox.com' };
    const resp = await fetch(`${sq.apiBase}/v2/locations`, {
        headers: { 'Authorization': `Bearer ${accessToken}`, 'Square-Version': '2024-12-18' },
    });
    const body = await resp.json();
    if (!resp.ok || !Array.isArray(body.locations) || body.locations.length === 0) {
        console.error(`[Square] Could not fetch locations for account ${accountId}:`, body);
        return null;
    }
    const loc = body.locations[0];
    const locationId = loc.id;
    const currency = loc.currency || 'USD';
    // Persist the id only; currency stays in process cache (it's tied to the
    // Square account, which is fixed per merchant — no need to denormalise).
    if (!row.square_location_id || row.square_location_id !== locationId) {
        await pool.query(`UPDATE accounts SET square_location_id = $1, updated_at = NOW() WHERE id = $2`,
            [locationId, accountId]);
    }
    _squareLocationCache.set(accountId, { id: locationId, currency, fetched_at: Date.now() });
    return { id: locationId, currency };
}

// Refresh access_token if it expires within 7 days. Square access_tokens last 30
// days, refresh_tokens last 90 (rolling). Called by status check + before any
// outbound API call. No-op if no refresh token, or if account isn't connected.
async function refreshSquareTokenIfNeeded(accountId) {
    const r = await pool.query(
        `SELECT square_access_token, square_refresh_token, square_token_expires_at, square_environment
           FROM accounts WHERE id = $1`,
        [accountId]
    );
    if (r.rows.length === 0) return null;
    const row = r.rows[0];
    if (!row.square_refresh_token) return row.square_access_token || null;
    const expiresAt = row.square_token_expires_at ? new Date(row.square_token_expires_at) : null;
    const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
    if (expiresAt && (expiresAt.getTime() - Date.now() > sevenDaysMs)) {
        return row.square_access_token;
    }
    // Refresh against the same environment the token was issued for.
    const sq = (row.square_environment === 'production')
        ? { apiBase: 'https://connect.squareup.com' }
        : { apiBase: 'https://connect.squareupsandbox.com' };
    try {
        const resp = await fetch(`${sq.apiBase}/oauth2/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Square-Version': '2024-12-18' },
            body: JSON.stringify({
                client_id: process.env.SQUARE_CLIENT_ID,
                client_secret: process.env.SQUARE_CLIENT_SECRET,
                refresh_token: row.square_refresh_token,
                grant_type: 'refresh_token',
            }),
        });
        const body = await resp.json();
        if (!resp.ok) {
            console.error(`[Square] Token refresh failed for account ${accountId}:`, body);
            return null;
        }
        await pool.query(
            `UPDATE accounts
                SET square_access_token = $1,
                    square_refresh_token = COALESCE($2, square_refresh_token),
                    square_token_expires_at = $3,
                    square_status = 'active',
                    updated_at = NOW()
              WHERE id = $4`,
            [body.access_token, body.refresh_token || null, body.expires_at || null, accountId]
        );
        console.log(`[Square] Refreshed access token for account ${accountId}`);
        return body.access_token;
    } catch (e) {
        console.error(`[Square] Token refresh error for account ${accountId}:`, e.message);
        return null;
    }
}

// Start Square OAuth flow
app.get('/api/square/connect/:accountId', async (req, res) => {
    try {
        const { accountId } = req.params;
        if (!process.env.SQUARE_CLIENT_ID) {
            return res.status(500).send('Square is not configured on this server (missing SQUARE_CLIENT_ID).');
        }
        const account = await pool.query('SELECT id FROM accounts WHERE id = $1', [accountId]);
        if (account.rows.length === 0) return res.status(404).send('Account not found');

        const sq = getSquareEnv();
        const state = Buffer.from(JSON.stringify({ accountId, env: sq.env, nonce: Date.now() })).toString('base64');
        const redirectUri = process.env.SQUARE_REDIRECT_URI || 'https://admin.gas.travel/api/square/callback';
        const authUrl = `${sq.webBase}/oauth2/authorize?` +
            `client_id=${encodeURIComponent(process.env.SQUARE_CLIENT_ID)}` +
            `&scope=${SQUARE_SCOPES}` +
            `&session=false` +
            `&state=${encodeURIComponent(state)}` +
            `&redirect_uri=${encodeURIComponent(redirectUri)}`;
        res.redirect(authUrl);
    } catch (error) {
        console.error('Square connect error:', error);
        res.status(500).send('Square connect error: ' + error.message);
    }
});

// Square OAuth callback
app.get('/api/square/callback', async (req, res) => {
    try {
        const { code, state, response_type, error: oauthErr, error_description } = req.query;
        if (oauthErr) {
            console.error('Square OAuth error:', oauthErr, error_description);
            return res.redirect('https://admin.gas.travel/gas-admin.html#accounts?square_error=' + encodeURIComponent(error_description || oauthErr));
        }
        let accountId, env;
        try {
            const stateData = JSON.parse(Buffer.from(state, 'base64').toString());
            accountId = stateData.accountId;
            env = stateData.env;
        } catch (e) {
            return res.redirect('https://admin.gas.travel/gas-admin.html#accounts?square_error=invalid_state');
        }
        if (!code) {
            return res.redirect('https://admin.gas.travel/gas-admin.html#accounts?square_error=missing_code');
        }
        const sq = (env === 'production')
            ? { apiBase: 'https://connect.squareup.com' }
            : { apiBase: 'https://connect.squareupsandbox.com' };
        const redirectUri = process.env.SQUARE_REDIRECT_URI || 'https://admin.gas.travel/api/square/callback';
        const tokenResp = await fetch(`${sq.apiBase}/oauth2/token`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Square-Version': '2024-12-18' },
            body: JSON.stringify({
                client_id: process.env.SQUARE_CLIENT_ID,
                client_secret: process.env.SQUARE_CLIENT_SECRET,
                code,
                grant_type: 'authorization_code',
                redirect_uri: redirectUri,
            }),
        });
        const tokenBody = await tokenResp.json();
        if (!tokenResp.ok) {
            console.error('Square token exchange failed:', tokenBody);
            return res.redirect('https://admin.gas.travel/gas-admin.html#accounts?square_error=' + encodeURIComponent(tokenBody.message || 'token_exchange_failed'));
        }

        // Pull merchant profile for the business name (nice-to-have, non-fatal).
        let businessName = null;
        try {
            const profResp = await fetch(`${sq.apiBase}/v2/merchants/${encodeURIComponent(tokenBody.merchant_id)}`, {
                headers: {
                    'Authorization': `Bearer ${tokenBody.access_token}`,
                    'Square-Version': '2024-12-18',
                },
            });
            const profBody = await profResp.json();
            if (profResp.ok) businessName = profBody?.merchant?.business_name || null;
        } catch (e) {
            console.warn('[Square] merchant profile fetch failed (non-fatal):', e.message);
        }

        await pool.query(
            `UPDATE accounts
                SET square_merchant_id = $1,
                    square_access_token = $2,
                    square_refresh_token = $3,
                    square_token_expires_at = $4,
                    square_environment = $5,
                    square_business_name = $6,
                    square_onboarding_complete = true,
                    square_status = 'active',
                    updated_at = NOW()
              WHERE id = $7`,
            [
                tokenBody.merchant_id,
                tokenBody.access_token,
                tokenBody.refresh_token,
                tokenBody.expires_at || null,
                env || 'sandbox',
                businessName,
                accountId,
            ]
        );
        console.log(`✅ Square connected for account ${accountId}: merchant ${tokenBody.merchant_id} (${env})`);
        res.redirect('https://admin.gas.travel/gas-admin.html#accounts?square_connected=true');
    } catch (error) {
        console.error('Square callback error:', error);
        res.redirect('https://admin.gas.travel/gas-admin.html#accounts?square_error=' + encodeURIComponent(error.message));
    }
});

// Get Square connection status for an account
app.get('/api/accounts/:accountId/square-status', async (req, res) => {
    try {
        const { accountId } = req.params;
        const result = await pool.query(
            `SELECT square_merchant_id, square_token_expires_at, square_environment,
                    square_business_name, square_onboarding_complete, square_status
               FROM accounts WHERE id = $1`,
            [accountId]
        );
        if (result.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Account not found' });
        }
        const a = result.rows[0];
        const connected = !!(a.square_merchant_id && a.square_status === 'active');
        const sq = getSquareEnv();
        res.json({
            success: true,
            connected,
            merchant_id: a.square_merchant_id,
            business_name: a.square_business_name,
            environment: a.square_environment,
            status: a.square_status,
            onboarding_complete: a.square_onboarding_complete,
            token_expires_at: a.square_token_expires_at,
            server_environment: sq.env,
            client_id_present: !!process.env.SQUARE_CLIENT_ID,
        });
    } catch (error) {
        console.error('Error getting Square status:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

// Disconnect Square account
app.post('/api/accounts/:accountId/square-disconnect', async (req, res) => {
    try {
        const { accountId } = req.params;
        const account = await pool.query(
            `SELECT square_merchant_id, square_access_token, square_environment
               FROM accounts WHERE id = $1`,
            [accountId]
        );
        if (account.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Account not found' });
        }
        const { square_merchant_id, square_access_token, square_environment } = account.rows[0];
        if (square_merchant_id && square_access_token) {
            try {
                const sq = (square_environment === 'production')
                    ? { apiBase: 'https://connect.squareup.com' }
                    : { apiBase: 'https://connect.squareupsandbox.com' };
                await fetch(`${sq.apiBase}/oauth2/revoke`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Client ${process.env.SQUARE_CLIENT_SECRET}`,
                        'Square-Version': '2024-12-18',
                    },
                    body: JSON.stringify({
                        client_id: process.env.SQUARE_CLIENT_ID,
                        access_token: square_access_token,
                        merchant_id: square_merchant_id,
                    }),
                });
            } catch (e) {
                console.log('Square revoke warning:', e.message);
            }
        }
        await pool.query(
            `UPDATE accounts
                SET square_merchant_id = NULL,
                    square_access_token = NULL,
                    square_refresh_token = NULL,
                    square_token_expires_at = NULL,
                    square_business_name = NULL,
                    square_onboarding_complete = false,
                    square_status = NULL,
                    updated_at = NOW()
              WHERE id = $1`,
            [accountId]
        );
        res.json({ success: true, message: 'Square disconnected' });
    } catch (error) {
        console.error('Error disconnecting Square:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

// Public — checkout reads this to decide whether to render the Square card
// form. Returns the merchant's application_id + location_id (sandbox or
// production), the property's currency, and the per-property accepted flag.
app.get('/api/public/property/:propertyId/square-info', async (req, res) => {
    try {
        const { propertyId } = req.params;
        const prop = await pool.query(
            `SELECT p.id, p.account_id, p.currency,
                    a.square_merchant_id, a.square_access_token, a.square_environment,
                    a.square_status, a.square_location_id,
                    pps.accepted_methods
               FROM properties p
               JOIN accounts a ON a.id = p.account_id
          LEFT JOIN property_payment_settings pps ON pps.property_id = p.id
              WHERE p.id = $1`,
            [propertyId]
        );
        if (prop.rows.length === 0) return res.status(404).json({ success: false, error: 'Property not found' });
        const row = prop.rows[0];
        const am = row.accepted_methods || [];
        const accepted = Array.isArray(am)
            ? am.indexOf('square') !== -1
            : !!am.square;
        const connected = !!(row.square_merchant_id && row.square_status === 'active' && row.square_access_token);
        if (!accepted || !connected) {
            return res.json({
                success: true,
                square_enabled: false,
                accepted,
                connected,
            });
        }
        const loc = await getSquareLocationForAccount(row.account_id);
        if (!loc || !loc.id) {
            return res.json({
                success: true,
                square_enabled: false,
                accepted: true,
                connected: true,
                error: 'Square merchant has no location configured',
            });
        }
        // The Square account is single-currency — that's the currency used at
        // /v2/payments, not the property's. Returning it here lets the test
        // page show "you'll be charged in {currency}" and helps us detect
        // currency mismatches before tokenising.
        res.json({
            success: true,
            square_enabled: true,
            application_id: process.env.SQUARE_CLIENT_ID || null,
            location_id: loc.id,
            environment: row.square_environment || 'sandbox',
            currency: loc.currency || 'USD',
            property_currency: (row.currency || 'USD').toUpperCase(),
        });
    } catch (error) {
        console.error('Square info error:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

// =====================================================
// ACCESS WORLDPAY INTEGRATION (Phase 1 — connect + status)
// =====================================================
// Mirror of the Square block above: per-account credentials so each operator's
// charges settle at THEIR Worldpay merchant. Access Worldpay uses HTTP Basic
// Auth (username + password) plus an Entity Reference per call — no OAuth, so
// the connect flow is a credential-paste form rather than a redirect.
// Phase 1 ships schema + connect + status + disconnect + webhook skeleton.
// Phases 2-6 add: tokenize-at-checkout, charge, refund, card-on-file, payment
// link mandate UX.

function getWorldpayConfig(env) {
    const e = (env || process.env.WORLDPAY_DEFAULT_ENV || 'sandbox').toLowerCase();
    const isProd = e === 'production';
    return {
        env: isProd ? 'production' : 'sandbox',
        apiBase: isProd ? 'https://access.worldpay.com' : 'https://try.access.worldpay.com',
    };
}

// Ensure worldpay_* columns exist on accounts + bookings (idempotent — safe to re-run).
async function ensureWorldpaySchema() {
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_entity_reference VARCHAR(100)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_username VARCHAR(100)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_password TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_environment VARCHAR(20)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_merchant_name VARCHAR(255)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_status VARCHAR(50)`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_onboarding_complete BOOLEAN DEFAULT false`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_webhook_secret TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_last_error TEXT`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_last_error_at TIMESTAMP`);
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_connected_at TIMESTAMP`);
    // Checkout ID — required by Worldpay's Access Checkout Web SDK init
    // call (Worldpay.checkout.init({ id: ... })). Distinct from
    // username/password + entity_reference. Operator copies it from the
    // Worldpay Dashboard's Checkout section.
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS worldpay_checkout_id VARCHAR(120)`);
    // Per-booking Worldpay payment artifacts. Mirror of stripe_payment_intent_id /
    // square_payment_id so reporting + reconciliation extend naturally.
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_payment_id VARCHAR(100)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_payment_token TEXT`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_3ds_session_id VARCHAR(100)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_card_last_four VARCHAR(4)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_card_brand VARCHAR(20)`);
    // Hosted Payment Pages — public-side flow. transaction_ref is the
    // dedupe key Worldpay echoes back on webhooks + payment-query lookups;
    // query_url is the HATEOAS link returned at HPP creation so we can
    // fetch the outcome on customer-return without a fresh listing call.
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_hpp_transaction_ref VARCHAR(120)`);
    await pool.query(`ALTER TABLE bookings ADD COLUMN IF NOT EXISTS worldpay_hpp_query_url TEXT`);
}
ensureWorldpaySchema().catch((e) => console.error('Worldpay schema migration failed:', e.message));

// Build the auth header + base URL for a given account's Worldpay creds. Returns
// null if the account isn't connected. All outbound Worldpay calls go through this.
async function getWorldpayAuthForAccount(accountId) {
    const r = await pool.query(
        `SELECT worldpay_username, worldpay_password, worldpay_entity_reference, worldpay_environment
           FROM accounts WHERE id = $1`,
        [accountId]
    );
    if (r.rows.length === 0) return null;
    const row = r.rows[0];
    if (!row.worldpay_username || !row.worldpay_password) return null;
    const basic = Buffer.from(`${row.worldpay_username}:${row.worldpay_password}`).toString('base64');
    const cfg = getWorldpayConfig(row.worldpay_environment);
    return {
        apiBase: cfg.apiBase,
        env: cfg.env,
        entityReference: row.worldpay_entity_reference || 'default',
        headers: {
            'Authorization': `Basic ${basic}`,
            'Accept': 'application/vnd.worldpay.payments-v7+json',
            'Content-Type': 'application/vnd.worldpay.payments-v7+json',
        },
    };
}

// POST /api/admin/worldpay/connect — save creds + verify against /service-discovery.
// Body: { account_id, username, password, entity_reference, environment, merchant_name, checkout_id? }
app.post('/api/admin/worldpay/connect', async (req, res) => {
    try {
        const { account_id, username, password, entity_reference, environment, merchant_name, checkout_id } = req.body;
        const decoded = await extractAccountFromToken(req);
        if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
        if (decoded.role !== 'master_admin' && String(decoded.id) !== String(account_id)) {
            return res.status(403).json({ success: false, error: 'Not authorized' });
        }
        if (!username || !password) {
            return res.status(400).json({ success: false, error: 'username and password required' });
        }
        const cfg = getWorldpayConfig(environment);
        const basic = Buffer.from(`${username}:${password}`).toString('base64');
        // Service discovery — Worldpay's "ping": returns the API root if creds OK.
        const ping = await fetch(`${cfg.apiBase}/`, {
            headers: {
                'Authorization': `Basic ${basic}`,
                'Accept': 'application/vnd.worldpay.api-discovery-v1+json',
            },
        });
        if (!ping.ok) {
            const errText = await ping.text().catch(() => '');
            await pool.query(
                `UPDATE accounts
                   SET worldpay_last_error = $1, worldpay_last_error_at = NOW(), worldpay_status = 'error'
                 WHERE id = $2`,
                [`Connect failed (HTTP ${ping.status}): ${errText.substring(0, 200)}`, account_id]
            );
            return res.status(400).json({ success: false, error: 'Invalid credentials or environment', status: ping.status });
        }
        await pool.query(
            `UPDATE accounts
               SET worldpay_username = $1,
                   worldpay_password = $2,
                   worldpay_entity_reference = $3,
                   worldpay_environment = $4,
                   worldpay_merchant_name = $5,
                   worldpay_checkout_id = $6,
                   worldpay_status = 'connected',
                   worldpay_onboarding_complete = true,
                   worldpay_connected_at = NOW(),
                   worldpay_last_error = NULL,
                   worldpay_last_error_at = NULL,
                   updated_at = NOW()
             WHERE id = $7`,
            [username, password, entity_reference || 'default', cfg.env, merchant_name || null, checkout_id || null, account_id]
        );
        res.json({ success: true, environment: cfg.env, entity_reference: entity_reference || 'default', checkout_id: checkout_id || null });
    } catch (err) {
        console.error('[Worldpay] connect error:', err);
        res.status(500).json({ success: false, error: err.message });
    }
});

// GET /api/admin/worldpay/status/:accountId — connection state for the UI badge.
app.get('/api/admin/worldpay/status/:accountId', async (req, res) => {
    try {
        const accountId = req.params.accountId;
        const decoded = await extractAccountFromToken(req);
        if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
        if (decoded.role !== 'master_admin' && String(decoded.id) !== String(accountId)) {
            return res.status(403).json({ success: false, error: 'Not authorized' });
        }
        const r = await pool.query(
            `SELECT worldpay_entity_reference, worldpay_environment, worldpay_merchant_name,
                    worldpay_checkout_id,
                    worldpay_status, worldpay_onboarding_complete, worldpay_last_error,
                    worldpay_last_error_at, worldpay_connected_at,
                    worldpay_username IS NOT NULL AS has_username
               FROM accounts WHERE id = $1`,
            [accountId]
        );
        if (r.rows.length === 0) return res.status(404).json({ success: false, error: 'Account not found' });
        const row = r.rows[0];
        res.json({
            success: true,
            connected: !!row.has_username && row.worldpay_status === 'connected',
            entity_reference: row.worldpay_entity_reference,
            environment: row.worldpay_environment,
            merchant_name: row.worldpay_merchant_name,
            checkout_id: row.worldpay_checkout_id || null,
            status: row.worldpay_status,
            onboarding_complete: row.worldpay_onboarding_complete,
            connected_at: row.worldpay_connected_at,
            last_error: row.worldpay_last_error,
            last_error_at: row.worldpay_last_error_at,
        });
    } catch (err) {
        console.error('[Worldpay] status error:', err);
        res.status(500).json({ success: false, error: err.message });
    }
});

// POST /api/admin/worldpay/checkout-id — set/update the Checkout ID
// without re-entering the API password. Required because the operator
// gets the Checkout ID from a different Worldpay Dashboard section
// (the Checkout / Web SDK area) after they've already connected the
// API credentials. Single column write.
app.post('/api/admin/worldpay/checkout-id', async (req, res) => {
    try {
        const { account_id, checkout_id } = req.body || {};
        const decoded = await extractAccountFromToken(req);
        if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
        if (decoded.role !== 'master_admin' && String(decoded.id) !== String(account_id)) {
            return res.status(403).json({ success: false, error: 'Not authorized' });
        }
        if (!account_id) return res.status(400).json({ success: false, error: 'account_id required' });
        await pool.query(
            `UPDATE accounts SET worldpay_checkout_id = $1, updated_at = NOW() WHERE id = $2`,
            [checkout_id || null, account_id]
        );
        res.json({ success: true, checkout_id: checkout_id || null });
    } catch (err) {
        console.error('[Worldpay] checkout-id save error:', err);
        res.status(500).json({ success: false, error: err.message });
    }
});

// POST /api/admin/worldpay/disconnect/:accountId — clear creds.
