// Restore webhooks for account 210 (easylandlord) ONLY — one-time fix
app.post('/api/admin/beds24/restore-webhooks', async (req, res) => {
    try {
        const { account_id, webhook_urls } = req.body;

        // HARDCODED: Only account 210 allowed
        if (parseInt(account_id) !== 210) {
            return res.status(403).json({ error: 'This endpoint is restricted to account 210 only' });
        }

        if (!webhook_urls?.length) {
            return res.status(400).json({ error: 'webhook_urls array required' });
        }

        const webhookString = webhook_urls.join('\n');
        const token = await getBeds24Token(account_id);

        // Get all properties for this account
        const propsResponse = await axios.get('https://beds24.com/api/v2/properties', {
            headers: { 'token': token }
        });
        const properties = propsResponse.data?.data || propsResponse.data || [];

        let results = { success: 0, failed: 0, skipped: 0, properties: [] };

        for (const prop of properties) {
            try {
                // Check current webhook
                const currentUrl = prop.webhooks?.url || '';

                // Skip if all URLs already present
                const allPresent = webhook_urls.every(url => currentUrl.includes(url));
                if (allPresent) {
                    results.skipped++;
                    results.properties.push({ id: prop.id, status: 'skipped - already set' });
                    continue;
                }

                // Restore the webhooks
                await axios.post('https://beds24.com/api/v2/properties',
                    [{
                        id: prop.id,
                        webhooks: {
                            version: 'twoWithPersonalData',
                            url: webhookString,
                            additionalData: 'none',
                            customHeader: ''
                        }
                    }],
                    {
                        headers: {
                            'token': token,
                            'Content-Type': 'application/json',
                            'accept': 'application/json'
                        }
                    }
                );

                results.success++;
                results.properties.push({ id: prop.id, status: 'restored' });
                console.log(`[BEDS24-RESTORE] Restored webhooks for property ${prop.id}`);

            } catch (propErr) {
                results.failed++;
                results.properties.push({ id: prop.id, status: 'failed', error: propErr.message });
                console.error(`[BEDS24-RESTORE] Failed for property ${prop.id}:`, propErr.message);
            }
        }

        res.json({ success: true, results });
    } catch (err) {
        console.error('[BEDS24-RESTORE] Error:', err);
        res.status(500).json({ error: err.message });
    }
});

// Sync properties and rooms from Beds24 for an account
app.post('/api/accounts/:id/beds24/sync', async (req, res) => {
  try {
    const { id } = req.params;
    const token = await getBeds24Token(id);

    // Fetch all properties
    const propResponse = await axios.get('https://beds24.com/api/v2/properties', {
      headers: { 'token': token },
      params: { includeAllRooms: true }
    });

    const properties = propResponse.data?.data || propResponse.data || [];

    if (!Array.isArray(properties) || properties.length === 0) {
      return res.json({ success: true, message: 'No properties found', properties: 0, rooms: 0 });
    }

    let totalRooms = 0;
    let totalProps = 0;

    for (const prop of properties) {
      const propId = prop.id || prop.propertyId;
      const propName = prop.name || 'Unnamed Property';
      const rooms = prop.roomTypes || prop.rooms || [];
      const roomCount = rooms.length || 0;

      totalProps++;
      totalRooms += roomCount;

      // Upsert property
      await pool.query(`
        INSERT INTO account_properties (account_id, beds24_property_id, name, address, city, country, room_count, synced_at)
        VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
        ON CONFLICT (account_id, beds24_property_id) DO UPDATE SET
          name = EXCLUDED.name,
          address = EXCLUDED.address,
          city = EXCLUDED.city,
          country = EXCLUDED.country,
          room_count = EXCLUDED.room_count,
          synced_at = NOW()
      `, [id, propId, propName, prop.address || '', prop.city || '', prop.country || '', roomCount]);

      // Get the property record
      const propRecord = await pool.query(
        'SELECT id FROM account_properties WHERE account_id = $1 AND beds24_property_id = $2',
        [id, propId]
      );

      if (propRecord.rows.length > 0) {
        const apId = propRecord.rows[0].id;

        // Upsert rooms
        for (const room of rooms) {
          const roomId = room.id || room.roomId;
          const roomName = room.name || 'Room';
          const maxGuests = room.maxGuests || room.maxPeople || 2;

          await pool.query(`
            INSERT INTO account_rooms (account_id, property_id, beds24_room_id, name, max_guests, synced_at)
            VALUES ($1, $2, $3, $4, $5, NOW())
            ON CONFLICT (property_id, beds24_room_id) DO UPDATE SET
              name = EXCLUDED.name,
              max_guests = EXCLUDED.max_guests,
              synced_at = NOW()
          `, [id, apId, roomId, roomName, maxGuests]);
        }
      }
    }

    // Update account totals
    await pool.query(`
      UPDATE accounts SET
        total_properties = $1,
        total_units = $2,
        beds24_last_sync = NOW(),
        updated_at = NOW()
      WHERE id = $3
    `, [totalProps, totalRooms, id]);

    // Auto-calculate AI Website subscription price
    await calculateAccountPricing(id);

    res.json({
      success: true,
      properties: totalProps,
      rooms: totalRooms,
      message: `Synced ${totalProps} properties with ${totalRooms} rooms/units`
    });
  } catch (error) {
    console.error('Beds24 sync error:', error.response?.data || error.message);
    res.json({ success: false, error: error.response?.data?.error || error.message });
  }
});

