// Get Beds24 connection status for an account
app.get('/api/accounts/:id/beds24/status', async (req, res) => {
  try {
    const { id } = req.params;

    const result = await pool.query(`
      SELECT beds24_connected, beds24_account_id, beds24_last_sync,
             total_properties, total_units
      FROM accounts WHERE id = $1
    `, [id]);

    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Account not found' });
    }

    const acct = result.rows[0];

    // If not connected via new system, check gas_sync_connections for existing Beds24 connection
    if (!acct.beds24_connected) {
      const existingConn = await pool.query(`
        SELECT id, access_token, refresh_token, status, external_account_id
        FROM gas_sync_connections
        WHERE account_id = $1 AND adapter_code = 'beds24' AND status != 'deleted'
        ORDER BY created_at DESC LIMIT 1
      `, [id]);

      if (existingConn.rows.length > 0) {
        const conn = existingConn.rows[0];
        const hasToken = !!(conn.access_token || conn.refresh_token);

        if (hasToken) {
          // Migrate credentials to the new account fields
          await pool.query(`
            UPDATE accounts SET
              beds24_token = COALESCE($1, beds24_token),
              beds24_refresh_token = COALESCE($2, beds24_refresh_token),
              beds24_connected = true,
              beds24_account_id = $3,
              updated_at = NOW()
            WHERE id = $4
          `, [conn.access_token, conn.refresh_token, conn.external_account_id, id]);

          acct.beds24_connected = true;
          acct.beds24_account_id = conn.external_account_id;
          acct.gas_sync_connection_id = conn.id;
        }
      }
    }

    res.json({ success: true, ...acct });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});


// =====================================================
// 3. PRICING CALCULATION
// =====================================================

// Calculate tiered AI Website price for a given unit count
function calculateAIWebsitePrice(units) {
  let price = 19.00; // base fee
  if (units <= 0) return price;

  const tiers = [
    { max: 50, rate: 2.50 },
    { max: 100, rate: 2.00 },
    { max: 250, rate: 1.50 },
    { max: 500, rate: 1.00 },
    { max: Infinity, rate: 0.50 }
  ];

  let remaining = units;
  let prevMax = 0;

  for (const tier of tiers) {
    const tierUnits = Math.min(remaining, tier.max - prevMax);
    if (tierUnits <= 0) break;
    price += tierUnits * tier.rate;
    remaining -= tierUnits;
    prevMax = tier.max;
    if (remaining <= 0) break;
  }

  return Math.round(price * 100) / 100;
}

// Calculate tiered Reviews price
function calculateReviewsPrice(apps) {
  if (apps <= 0) return 0;
  let price = 0;
  const tiers = [
    { max: 9, rate: 5.00 },
    { max: 49, rate: 3.00 },
    { max: Infinity, rate: 1.50 }
  ];

  let remaining = apps;
  let prevMax = 0;

  for (const tier of tiers) {
    const tierUnits = Math.min(remaining, tier.max - prevMax);
    if (tierUnits <= 0) break;
    price += tierUnits * tier.rate;
    remaining -= tierUnits;
    prevMax = tier.max;
    if (remaining <= 0) break;
  }

  return Math.round(price * 100) / 100;
}

// Auto-calculate and update pricing for an account
async function calculateAccountPricing(accountId) {
  const acct = await pool.query('SELECT total_units FROM accounts WHERE id = $1', [accountId]);
  if (acct.rows.length === 0) return;

  const units = acct.rows[0].total_units || 0;
  const aiWebsitePrice = calculateAIWebsitePrice(units);

  // Upsert AI Website subscription
  await pool.query(`
    INSERT INTO account_subscriptions (account_id, product, tier, quantity, monthly_price, currency, status)
    VALUES ($1, 'ai_website', 1, $2, $3, 'EUR', 'active')
    ON CONFLICT (account_id, product) DO UPDATE SET
      quantity = EXCLUDED.quantity,
      monthly_price = EXCLUDED.monthly_price,
      updated_at = NOW()
  `, [accountId, units, aiWebsitePrice]);
}

