// Setup knowledge base tables
app.get('/api/setup-knowledge-base', async (req, res) => {
  try {
    // Categories for organizing knowledge
    await pool.query(`
      CREATE TABLE IF NOT EXISTS kb_categories (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        slug VARCHAR(255) UNIQUE NOT NULL,
        description TEXT,
        icon VARCHAR(50),
        sort_order INTEGER DEFAULT 0,
        parent_id INTEGER REFERENCES kb_categories(id),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    
    // Main knowledge articles
    await pool.query(`
      CREATE TABLE IF NOT EXISTS kb_articles (
        id SERIAL PRIMARY KEY,
        category_id INTEGER REFERENCES kb_categories(id),
        title VARCHAR(500) NOT NULL,
        slug VARCHAR(500) UNIQUE NOT NULL,
        summary TEXT,
        content TEXT NOT NULL,
        keywords TEXT[],
        related_articles INTEGER[],
        status VARCHAR(50) DEFAULT 'published',
        views INTEGER DEFAULT 0,
        helpful_yes INTEGER DEFAULT 0,
        helpful_no INTEGER DEFAULT 0,
        created_by INTEGER,
        updated_by INTEGER,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    
    // Track questions the AI couldn't answer
    await pool.query(`
      CREATE TABLE IF NOT EXISTS kb_unanswered (
        id SERIAL PRIMARY KEY,
        question TEXT NOT NULL,
        user_context TEXT,
        account_id INTEGER,
        session_id VARCHAR(255),
        times_asked INTEGER DEFAULT 1,
        status VARCHAR(50) DEFAULT 'new',
        resolved_article_id INTEGER REFERENCES kb_articles(id),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    
    // Chat history for context
    await pool.query(`
      CREATE TABLE IF NOT EXISTS kb_chat_history (
        id SERIAL PRIMARY KEY,
        session_id VARCHAR(255) NOT NULL,
        account_id INTEGER,
        role VARCHAR(50) NOT NULL,
        message TEXT NOT NULL,
        articles_used INTEGER[],
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    
    // Insert default categories if empty
    const catCheck = await pool.query('SELECT COUNT(*) FROM kb_categories');
    if (parseInt(catCheck.rows[0].count) === 0) {
      await pool.query(`
        INSERT INTO kb_categories (name, slug, description, icon, sort_order) VALUES
        ('Getting Started', 'getting-started', 'New to GAS? Start here', '🚀', 1),
        ('Channel Managers', 'channel-managers', 'Connecting Beds24, Hostaway, Smoobu and more', '🔗', 2),
        ('Properties & Rooms', 'properties-rooms', 'Managing your properties and units', '🏨', 3),
        ('Images', 'images', 'Uploading and managing photos', '📷', 4),
        ('Pricing & Offers', 'pricing-offers', 'Setting prices, creating offers and discounts', '💰', 5),
        ('Availability', 'availability', 'Calendar and booking management', '📅', 6),
        ('Vouchers', 'vouchers', 'Creating and managing vouchers', '🎟️', 7),
        ('Upsells & Fees', 'upsells-fees', 'Additional charges and upsell options', '➕', 8),
        ('Taxes', 'taxes', 'Tourist taxes and regional charges', '📋', 9),
        ('Content & SEO', 'content-seo', 'Descriptions, pages, and search optimization', '✏️', 10),
        ('Website & Plugins', 'website-plugins', 'WordPress plugin and website integration', '🌐', 11),
        ('Travel Agents', 'travel-agents', 'Information for travel agents and tour operators', '✈️', 12),
        ('Account & Billing', 'account-billing', 'Managing your account and payments', '👤', 13),
        ('Troubleshooting', 'troubleshooting', 'Common issues and solutions', '🔧', 14)
      `);
    }

    // Seed KB article: "Do I need a Google Translate button on my site?"
    // Rationale: Steve rejected shipping a Google/Microsoft translate widget
    // in favour of documenting the browser fallback (2026-07-06). Idempotent
    // — ON CONFLICT (slug) DO NOTHING means re-runs on every boot are a no-op
    // after the first fill. Sits under Website & Plugins category.
    await pool.query(`
      INSERT INTO kb_articles (category_id, title, slug, summary, content, keywords, status)
      SELECT c.id,
             'Do I need a Google Translate button on my site?',
             'browser-translate-fallback',
             'Short answer: no. Every modern browser already offers to translate foreign-language pages. GAS''s multilingual editor handles the languages you actively market in — the browser handles the long tail for free.',
             $1,
             ARRAY['translate','translation','google translate','multilingual','languages','browser','chrome','safari','edge'],
             'published'
        FROM kb_categories c
       WHERE c.slug = 'website-plugins'
      ON CONFLICT (slug) DO NOTHING
    `, [
      "Short answer: no. Every modern browser already handles this for free.\n\n" +
      "**Chrome, Edge, Safari, and Firefox (with add-on) all auto-detect foreign-language pages and offer a translate banner** when a visitor's browser language doesn't match the site's language. That's the same underlying Google Translate engine you'd get from bolting on a widget — served by the visitor's browser at zero code cost, zero third-party JS, and no \"Powered by Google\" branding on your site.\n\n" +
      "## When to use GAS's built-in multilingual editor instead\n\n" +
      "Use the multilingual editor (Web Builder → Language Settings) for the languages you actively market in. For example, a French Riviera villa markets in EN + FR + DE + IT — those get proper, hand-crafted translations that are:\n\n" +
      "- Indexed by search engines (SEO)\n" +
      "- Under your editorial control\n" +
      "- Accurate for brand and legal wording\n" +
      "- Rendered as real HTML, not a browser overlay\n\n" +
      "## When to rely on the browser fallback\n\n" +
      "The long tail — a Japanese visitor who happens to land on a Spanish hotel site. Their Chrome will offer to translate. You don't need to install anything.\n\n" +
      "## What we deliberately don't ship\n\n" +
      "- A Google Translate widget — Google has deprecated it for new signups and it only duplicates what the browser does. Adds a \"Powered by Google\" bar to your site.\n" +
      "- A Microsoft Translator widget — same tradeoffs as Google.\n" +
      "- A paid drop-in service like Weglot — genuinely competes with our multilingual editor, and per-site pricing scales badly across the estate. Recommend to clients as a self-purchase add-on if they specifically ask.\n\n" +
      "## What to tell a client who asks for a translate button\n\n" +
      "\"Every visitor's browser already offers to translate your site into their language. Modern Chrome, Edge, and Safari do this automatically for any page in a language that isn't the browser's default — it's the same Google Translate engine but with no third-party script on your site and no branding. If you want *curated* translations that show up in Google search results, use the multilingual editor in Web Builder for those specific languages.\""
    ]);

    // Walkthroughs — Supademo-backed video knowledge base
    await pool.query(`
      CREATE TABLE IF NOT EXISTS walkthroughs (
        id SERIAL PRIMARY KEY,
        title VARCHAR(500) NOT NULL,
        description TEXT,
        demo_id VARCHAR(100) NOT NULL,
        view VARCHAR(100),
        tags TEXT[],
        kb_article_id INTEGER REFERENCES kb_articles(id) ON DELETE SET NULL,
        sort_order INTEGER DEFAULT 0,
        is_active BOOLEAN DEFAULT true,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);

    res.json({ success: true, message: 'Knowledge base tables created!' });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Supademo proxy — returns list of demos for admin walkthrough system
app.get('/api/supademo/demos', async (req, res) => {
  try {
    const apiKey = process.env.SUPADEMO_API_KEY;
    if (!apiKey) return res.status(500).json({ error: 'SUPADEMO_API_KEY not configured' });
    const response = await axios.get('https://api.supademo.com/v1/demos', {
      headers: { 'Authorization': `Bearer ${apiKey}` },
      timeout: 10000
    });
    res.json({ success: true, demos: response.data });
  } catch (error) {
    console.error('Supademo API error:', error.response?.status, error.message);
    res.status(error.response?.status || 500).json({
      success: false,
      error: error.response?.data || error.message
    });
  }
});

