// Get all articles (with optional filters)
app.get('/api/kb/articles', async (req, res) => {
  try {
    const { category_id, status, search } = req.query;
    let query = `
      SELECT a.*, c.name as category_name, c.icon as category_icon,
             w.id as walkthrough_id, w.demo_id as walkthrough_demo_id, w.title as walkthrough_title
      FROM kb_articles a
      LEFT JOIN kb_categories c ON a.category_id = c.id
      LEFT JOIN walkthroughs w ON w.kb_article_id = a.id AND w.is_active = true
      WHERE 1=1
    `;
    const params = [];
    
    if (category_id) {
      params.push(category_id);
      query += ` AND a.category_id = $${params.length}`;
    }
    
    if (status) {
      params.push(status);
      query += ` AND a.status = $${params.length}`;
    }
    
    if (search) {
      params.push(`%${search}%`);
      query += ` AND (a.title ILIKE $${params.length} OR a.content ILIKE $${params.length} OR a.summary ILIKE $${params.length})`;
    }
    
    query += ' ORDER BY a.category_id, a.title';
    
    const result = await pool.query(query, params);
    res.json({ success: true, data: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

