const VPS_DEPLOY_URL = 'https://sites.gas.travel/gas-deploy.php';
const VPS_DEPLOY_API_KEY = process.env.VPS_DEPLOY_API_KEY || 'gas-deploy-2024-secure-key';

// Create deployed_sites table
app.get('/api/setup-deploy', async (req, res) => {
  try {
    await pool.query(`
      CREATE TABLE IF NOT EXISTS deployed_sites (
        id SERIAL PRIMARY KEY,
        property_id INTEGER REFERENCES properties(id) ON DELETE SET NULL,
        property_ids JSONB DEFAULT '[]',
        room_ids JSONB DEFAULT '[]',
        account_id INTEGER REFERENCES accounts(id) ON DELETE SET NULL,
        blog_id INTEGER,
        site_url VARCHAR(255),
        admin_url VARCHAR(255),
        slug VARCHAR(100),
        site_name VARCHAR(255),
        status VARCHAR(50) DEFAULT 'pending',
        wp_username VARCHAR(100),
        wp_password_temp VARCHAR(100),
        deployed_at TIMESTAMP,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `);
    
    // Add columns if they don't exist (for existing tables)
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS property_ids JSONB DEFAULT '[]'`);
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS room_ids JSONB DEFAULT '[]'`);
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS site_name VARCHAR(255)`);
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS custom_domain VARCHAR(255)`);
    // One-shot backfill for Le Macassar — DNS + nginx were set up manually
    // outside the connectCustomDomain wizard, so the row was never given a
    // custom_domain and the View Site button was landing on
    // sites.gas.travel/wp-signup.php (dead subsite mapping). Idempotent:
    // only touches rows where custom_domain is still NULL. Matches either
    // by account_id (79 per migration b2151e68) OR by site_url containing
    // 'lemacassar' — belt and braces in case ownership was moved to a
    // sub-account after that migration.
    await pool.query(`
      UPDATE deployed_sites
         SET custom_domain = 'lemacassar.com', updated_at = NOW()
       WHERE custom_domain IS NULL
         AND (account_id = 79 OR site_url ILIKE '%lemacassar%' OR site_name ILIKE '%macassar%')
    `);
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS template VARCHAR(50) DEFAULT 'developer-light'`);
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS ga4_measurement_id VARCHAR(50)`);
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS ga4_property_id VARCHAR(100)`);
    
    // Pricing tier support - allows different pricing for different client types (corporate, wholesale, etc.)
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS pricing_tier VARCHAR(50) DEFAULT 'standard'`);
    
    // Per-site billing columns
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS site_type VARCHAR(20) DEFAULT 'standard'`).catch(() => {}); // owner, agent, plugin, custom
    await pool.query(`ALTER TABLE deployed_sites ALTER COLUMN site_type SET DEFAULT 'owner'`).catch(() => {});
    await pool.query(`UPDATE deployed_sites SET site_type = 'owner' WHERE site_type = 'standard'`).catch(() => {});
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS monthly_fee DECIMAL(10,2)`).catch(() => {}); // override auto-calc, or custom site monthly
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS setup_fee DECIMAL(10,2) DEFAULT 0`).catch(() => {}); // one-off fee for custom sites
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS setup_fee_invoiced BOOLEAN DEFAULT false`).catch(() => {}); // track if one-off already billed
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS discount_type VARCHAR(10) DEFAULT 'none'`).catch(() => {}); // none, percentage, fixed
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS discount_value DECIMAL(10,2) DEFAULT 0`).catch(() => {}); 
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS billing_enabled BOOLEAN DEFAULT true`).catch(() => {});

    // Site protection — 'development' (default, unprotected), 'live' (unprotected, visual), 'frozen' (all writes blocked)
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS site_status VARCHAR(20) DEFAULT 'development'`).catch(() => {});

    // Agency → client share: when set, this sub-account also sees + can edit the site
    await pool.query(`ALTER TABLE deployed_sites ADD COLUMN IF NOT EXISTS client_account_id INTEGER`).catch(() => {});

    await pool.query(`ALTER TABLE offers ADD COLUMN IF NOT EXISTS pricing_tier VARCHAR(50) DEFAULT 'standard'`);
    await pool.query(`ALTER TABLE offers ADD COLUMN IF NOT EXISTS replaces_standard BOOLEAN DEFAULT false`);
    await pool.query(`ALTER TABLE offers ADD COLUMN IF NOT EXISTS hide_discount_badge BOOLEAN DEFAULT false`);

    // Add website_url column to bookable_units if it doesn't exist
    await pool.query(`ALTER TABLE bookable_units ADD COLUMN IF NOT EXISTS website_url VARCHAR(255)`);

    // Travel Agent: site_properties junction table
    await pool.query(`
      CREATE TABLE IF NOT EXISTS site_properties (
        id SERIAL PRIMARY KEY,
        site_id INTEGER REFERENCES deployed_sites(id) ON DELETE CASCADE,
        property_id INTEGER REFERENCES properties(id) ON DELETE CASCADE,
        added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(site_id, property_id)
      )
    `).catch(() => {});

    res.json({ success: true, message: 'Deployed sites table created/updated with room_ids support' });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

