// GET settings for a deployed site
// Comms Phase 2 — team assignments (entity_site_assignments)
// GET /api/admin/deployed-sites/:id/team — list accounts + users assigned to this site.
// Also returns candidate lists (unassigned sub-accounts, unassigned users on the owning account).
app.get('/api/admin/deployed-sites/:id/team', async (req, res) => {
  try {
    const siteId = parseInt(req.params.id, 10);
    const site = await pool.query('SELECT id, account_id FROM deployed_sites WHERE id = $1', [siteId]);
    if (!site.rows[0]) return res.json({ success: false, error: 'Site not found' });
    const ownerAccountId = site.rows[0].account_id;
    const assigned = await pool.query(
      `SELECT entity_type, entity_id, created_at FROM entity_site_assignments WHERE deployed_site_id = $1`,
      [siteId]
    );
    const asgAccountIds = assigned.rows.filter(r => r.entity_type === 'account').map(r => r.entity_id);
    const asgUserIds = assigned.rows.filter(r => r.entity_type === 'user').map(r => r.entity_id);
    // Hydrate account rows
    let assignedAccounts = [];
    if (asgAccountIds.length) {
      const q = await pool.query('SELECT id, name, email FROM accounts WHERE id = ANY($1::int[])', [asgAccountIds]);
      assignedAccounts = q.rows;
    }
    let assignedUsers = [];
    if (asgUserIds.length) {
      const q = await pool.query('SELECT id, email, first_name, last_name FROM users WHERE id = ANY($1::int[])', [asgUserIds]);
      assignedUsers = q.rows;
    }
    // Candidates — sub-accounts of the owning account + all users
    // belonging to the owning account. `accounts` has no deleted_at
    // column; deletion is marked via status='deleted' where used.
    const subAccts = await pool.query(
      `SELECT id, name, email FROM accounts
        WHERE parent_id = $1
          AND (status IS NULL OR status != 'deleted')
        ORDER BY name`,
      [ownerAccountId]
    ).catch(() => ({ rows: [] }));
    const users = await pool.query(
      `SELECT id, email, first_name, last_name FROM users WHERE account_id = $1 ORDER BY email`,
      [ownerAccountId]
    ).catch(() => ({ rows: [] }));
    res.json({
      success: true,
      assigned: { accounts: assignedAccounts, users: assignedUsers },
      candidates: {
        accounts: subAccts.rows.filter(a => !asgAccountIds.includes(a.id)),
        users: users.rows.filter(u => !asgUserIds.includes(u.id))
      }
    });
  } catch (e) {
    console.error('[team GET]', e);
    res.json({ success: false, error: e.message });
  }
});

// POST /api/admin/deployed-sites/:id/team/assign — { entity_type: 'account'|'user', entity_id }
app.post('/api/admin/deployed-sites/:id/team/assign', async (req, res) => {
  try {
    const siteId = parseInt(req.params.id, 10);
    const { entity_type, entity_id } = req.body || {};
    if (!['account', 'user'].includes(entity_type) || !Number.isFinite(parseInt(entity_id, 10))) {
      return res.json({ success: false, error: 'entity_type must be account|user and entity_id required' });
    }
    // Validate the referenced entity actually exists so we don't leave dangling rows
    const check = entity_type === 'account'
      ? await pool.query('SELECT id FROM accounts WHERE id = $1', [entity_id])
      : await pool.query('SELECT id FROM users WHERE id = $1', [entity_id]);
    if (!check.rows[0]) return res.json({ success: false, error: entity_type + ' not found' });
    await pool.query(
      `INSERT INTO entity_site_assignments (entity_type, entity_id, deployed_site_id)
       VALUES ($1, $2, $3)
       ON CONFLICT (entity_type, entity_id, deployed_site_id) DO NOTHING`,
      [entity_type, entity_id, siteId]
    );
    res.json({ success: true });
  } catch (e) {
    console.error('[team assign]', e);
    res.json({ success: false, error: e.message });
  }
});

// DELETE /api/admin/deployed-sites/:id/team/:entityType/:entityId
app.delete('/api/admin/deployed-sites/:id/team/:entityType/:entityId', async (req, res) => {
  try {
    const siteId = parseInt(req.params.id, 10);
    const { entityType, entityId } = req.params;
    if (!['account', 'user'].includes(entityType)) {
      return res.json({ success: false, error: 'invalid entity type' });
    }
    await pool.query(
      `DELETE FROM entity_site_assignments WHERE deployed_site_id = $1 AND entity_type = $2 AND entity_id = $3`,
      [siteId, entityType, parseInt(entityId, 10)]
    );
    res.json({ success: true });
  } catch (e) {
    console.error('[team unassign]', e);
    res.json({ success: false, error: e.message });
  }
});

// Returns the set of deployed_site_ids an entity can access.
// null return = unrestricted (no assignments — full account access).
// Empty array return = restricted but assigned to zero sites (edge case,
// treat as "can access nothing" — different from full access).
async function getEntityAccessibleSiteIds(entityType, entityId) {
  if (!entityType || !Number.isFinite(parseInt(entityId, 10))) return null;
  try {
    const q = await pool.query(
      `SELECT deployed_site_id FROM entity_site_assignments WHERE entity_type = $1 AND entity_id = $2`,
      [entityType, entityId]
    );
    if (q.rows.length === 0) return null;   // no assignments = unrestricted (backwards compat)
    return q.rows.map(r => r.deployed_site_id);
  } catch (_) { return null; }
}

app.get('/api/deployed-sites/:id/settings/:section', async (req, res) => {
  try {
    const deployedSiteId = parseInt(req.params.id);
    const section = req.params.section;
    
    // Verify deployed site exists and get template
    const siteResult = await pool.query(
      'SELECT id, account_id, template, site_name FROM deployed_sites WHERE id = $1',
      [deployedSiteId]
    );
    
    if (siteResult.rows.length === 0) {
      return res.json({ success: false, error: 'Deployed site not found' });
    }
    
    const site = siteResult.rows[0];
    
    // Try to get per-site settings first
    let result = await pool.query(`
      SELECT settings, variant, is_enabled, display_order, updated_at
      FROM website_settings
      WHERE deployed_site_id = $1 AND section = $2
    `, [deployedSiteId, section]);
    
    if (result.rows.length > 0) {
      console.log(`Loaded ${section} settings for deployed site ${deployedSiteId}`);
      return res.json({ 
        success: true, 
        settings: result.rows[0].settings,
        source: 'deployed_site',
        template: site.template
      });
    }
    
    // Fall back to account-based settings (legacy)
    result = await pool.query(`
      SELECT settings, variant, is_enabled, display_order, updated_at
      FROM website_settings
      WHERE account_id = $1 AND section = $2 AND deployed_site_id IS NULL
      ORDER BY updated_at DESC
      LIMIT 1
    `, [site.account_id, section]);
    
    if (result.rows.length > 0) {
      console.log(`Loaded ${section} settings from account ${site.account_id} for deployed site ${deployedSiteId}`);
      return res.json({ 
        success: true, 
        settings: result.rows[0].settings,
        source: 'account_fallback',
        template: site.template
      });
    }
    
    // No settings found, return SECTION_DEFAULTS so the theme gets correct values
    console.log(`No ${section} settings found for deployed site ${deployedSiteId}, using SECTION_DEFAULTS`);
    res.json({
      success: true,
      settings: (typeof SECTION_DEFAULTS !== 'undefined' && SECTION_DEFAULTS[section]) ? SECTION_DEFAULTS[section] : null,
      source: 'section_defaults',
      template: site.template
    });
    
  } catch (error) {
    console.error('Get deployed site settings error:', error);
    res.json({ success: false, error: error.message });
  }
});

// GET all settings for a deployed site
app.get('/api/deployed-sites/:id/settings', async (req, res) => {
  try {
    const deployedSiteId = parseInt(req.params.id);
    
    // Verify deployed site exists
    const siteResult = await pool.query(
      'SELECT id, account_id, template, site_name, site_url FROM deployed_sites WHERE id = $1',
      [deployedSiteId]
    );
    
    if (siteResult.rows.length === 0) {
      return res.json({ success: false, error: 'Deployed site not found' });
    }
    
    const site = siteResult.rows[0];
    
    // Get all per-site settings
    const result = await pool.query(`
      SELECT section, settings, updated_at
      FROM website_settings
      WHERE deployed_site_id = $1
    `, [deployedSiteId]);
    
    const allSettings = {};
    result.rows.forEach(row => {
      allSettings[row.section] = row.settings;
    });
    
    res.json({ 
      success: true, 
      site: {
        id: site.id,
        name: site.site_name,
        template: site.template,
        site_url: site.site_url
      },
      settings: allSettings,
      sections_saved: Object.keys(allSettings)
    });
    
  } catch (error) {
    console.error('Get all deployed site settings error:', error);
    res.json({ success: false, error: error.message });
  }
});

// --- Site Protection helpers ---
async function checkSiteFrozen(deployedSiteId) {
  const result = await pool.query('SELECT site_status FROM deployed_sites WHERE id = $1', [parseInt(deployedSiteId)]);
  if (result.rows.length === 0) return { frozen: false, error: 'Site not found' };
  return { frozen: result.rows[0].site_status === 'frozen' };
}
async function checkSiteFrozenByBlogId(blogId) {
  const result = await pool.query('SELECT site_status FROM deployed_sites WHERE blog_id = $1', [parseInt(blogId)]);
  if (result.rows.length === 0) return { frozen: false };
  return { frozen: result.rows[0].site_status === 'frozen' };
}

// Log settings change to history table for audit/recovery
async function logSettingsHistory(deployedSiteId, accountId, section, oldSettings, newSettings, syncSource) {
  try {
    // Find which fields actually changed
    const changedFields = [];
    const old = oldSettings || {};
    const nw = newSettings || {};
    for (const key of new Set([...Object.keys(old), ...Object.keys(nw)])) {
      if (JSON.stringify(old[key]) !== JSON.stringify(nw[key])) {
        changedFields.push(key);
      }
    }
    if (changedFields.length === 0) return; // No actual changes
    await pool.query(`
      INSERT INTO website_settings_history (deployed_site_id, account_id, section, old_settings, new_settings, changed_fields, sync_source)
      VALUES ($1, $2, $3, $4, $5, $6, $7)
    `, [deployedSiteId, accountId, section, JSON.stringify(old), JSON.stringify(nw), changedFields, syncSource || 'unknown']);
  } catch (e) {
    console.error('Failed to log settings history:', e.message);
  }
}

// Remap partner settings to account's primary language
// Partners send fields like headline-en, title-en etc. If the account's primary
// language is DE, we remap headline-en → headline-de so content lands in the right field.
// Fields that already have the correct suffix or are non-text (colours, URLs, booleans) pass through.
async function remapPartnerLanguageFields(settings, deployedSiteId) {
  try {
    const acctResult = await pool.query(
      'SELECT a.settings FROM accounts a JOIN deployed_sites ds ON ds.account_id = a.id WHERE ds.id = $1',
      [deployedSiteId]
    );
    if (acctResult.rows.length === 0) return settings;
    const primaryLang = acctResult.rows[0].settings?.primary_language || 'en';
    if (primaryLang === 'en') return settings; // No remapping needed

    // Known language suffixes
    const langCodes = ['en', 'fr', 'es', 'de', 'nl', 'it', 'pt', 'pl', 'ru', 'ja', 'zh'];
    const langSuffixRegex = new RegExp(`-(${langCodes.join('|')})$`);

    // Keys that should NOT be remapped (non-text: colours, urls, images, booleans, numbers)
    const skipPatterns = ['color', 'bg', 'url', 'image', 'logo', 'icon', 'font', 'size', 'width',
      'height', 'radius', 'opacity', 'spacing', 'offset', 'scale', 'duration', 'transition',
      'max-guests', 'enabled', 'show-', 'position', 'layout', 'style', 'type', 'config', 'categories'];

    const remapped = {};
    for (const [key, value] of Object.entries(settings)) {
      // Only remap fields ending in -en (the default partner sends)
      if (key.endsWith('-en')) {
        const baseKey = key.slice(0, -3); // Remove -en
        // Skip non-text fields
        const isSkip = skipPatterns.some(p => baseKey.includes(p));
        if (isSkip) {
          remapped[key] = value;
          continue;
        }
        // Check if partner also sent the primary lang version — if so, don't overwrite
        const primaryKey = baseKey + '-' + primaryLang;
        if (settings[primaryKey] !== undefined) {
          remapped[key] = value; // Keep the -en version as-is
        } else {
          // Remap: headline-en → headline-de (and don't keep -en copy)
          remapped[primaryKey] = value;
          console.log(`[Partner lang remap] ${key} → ${primaryKey} (primary: ${primaryLang})`);
        }
      } else {
        remapped[key] = value;
      }
    }
    return remapped;
  } catch (e) {
    console.error('Partner language remap error:', e.message);
    return settings; // Fall back to original on error
  }
}

// SAVE settings for a deployed site
app.post('/api/deployed-sites/:id/settings/:section', async (req, res) => {
  try {
    const deployedSiteId = parseInt(req.params.id);
    const section = req.params.section;
    const { settings, clear_keys } = req.body;

    if (!settings) {
      return res.json({ success: false, error: 'Settings object required' });
    }

    // clear_keys: keys the user explicitly cleared via a × delete button.
    // The merge guard below preserves existing image/url/logo values when an empty
    // string is incoming (defends against stale-form blank submissions). clear_keys
    // overrides that guard for fields the user actually intended to remove.
    const explicitlyCleared = Array.isArray(clear_keys) ? clear_keys : [];

    // Site protection — block writes to frozen sites
    const frozenCheck = await checkSiteFrozen(deployedSiteId);
    if (frozenCheck.frozen) {
      return res.json({ success: false, error: 'This site is frozen. Unfreeze it before making changes.' });
    }

    // Verify deployed site exists and get info for WordPress push
    const siteResult = await pool.query(
      'SELECT id, account_id, template, site_name, site_url, blog_id FROM deployed_sites WHERE id = $1',
      [deployedSiteId]
    );

    if (siteResult.rows.length === 0) {
      return res.json({ success: false, error: 'Deployed site not found' });
    }

    const site = siteResult.rows[0];

    console.log(`Saving ${section} settings for deployed site ${deployedSiteId} (${site.site_name})`);
    console.log('Settings:', JSON.stringify(settings, null, 2));

    // MERGE: Load existing settings first so we don't wipe fields the UI didn't send
    const existingResult = await pool.query(
      'SELECT settings FROM website_settings WHERE deployed_site_id = $1 AND section = $2',
      [deployedSiteId, section]
    );

    // Cross-site URL guard — reject any incoming field whose URL embeds a
    // different deployed_site_id than this route's target. Catches the DOM-
    // staleness bleed bug where switching sites in Web Builder leaves stale
    // image/slide URLs in hidden inputs.
    // Pattern matches /website/hero/<id>/, /website/hero-slide-N/<id>/, etc.
    // GRANDFATHER: if the SAME URL is already saved in the existing settings,
    // it's pre-existing (e.g. from a migration that kept the original path).
    // Only reject when the URL is NEW. Stops the guard from blocking saves
    // of fields that were already cross-tagged before this guard existed.
    {
      const heroUrlPathPattern = /\/website\/hero[a-zA-Z0-9-]*\/(\d+)\//;
      const existingSettings = existingResult.rows[0]?.settings || {};
      for (const [key, value] of Object.entries(settings)) {
        if (typeof value !== 'string' || !value) continue;
        const m = value.match(heroUrlPathPattern);
        if (m) {
          const urlSiteId = parseInt(m[1]);
          if (urlSiteId !== deployedSiteId) {
            // Grandfather: same value already on file → not a fresh
            // contamination, just a re-save of pre-existing state.
            if (existingSettings[key] === value) {
              console.log(`[cross-site-guard] grandfathered ${key} (pre-existing url_site=${urlSiteId})`);
              continue;
            }
            console.warn(`[CROSS_SITE_URL_REJECTED] field=${key} url_site=${urlSiteId} target=${deployedSiteId} value=${value.substring(0,120)}`);
            return res.status(400).json({
              success: false,
              error_code: 'CROSS_SITE_URL_REJECTED',
              error: `Field "${key}" contains a URL belonging to deployed_site_id ${urlSiteId}, but this save targets deployed_site_id ${deployedSiteId}. Likely a stale form value from another site — re-upload the image from this site's media library to fix.`,
              field: key,
              url_site_id: urlSiteId,
              target_site_id: deployedSiteId
            });
          }
        }
      }
    }
    // SAFETY GUARD — custom-pages index data loss prevention.
    // updateCustomPageParent / updateCustomPageExternalUrl in
    // gas-admin.html re-POST the whole pages[] on every edit. A race
    // where customPages was reset to [] (site-switch, page reload
    // mid-edit, stale tab) would otherwise wipe every saved sub-page
    // for every account that hit it — confirmed 2026-06-24 across
    // Lehmann, Mornington, Hotel Balduin, Moon River, Walnut Canyon.
    // Real deletes go via DELETE /api/deployed-sites/:id/custom-pages/:slug,
    // not by posting an empty pages array, so this guard never blocks
    // a legitimate flow.
    if (section === 'custom-pages' && existingResult.rows.length > 0 && existingResult.rows[0].settings) {
      const existingPages = Array.isArray(existingResult.rows[0].settings.pages) ? existingResult.rows[0].settings.pages : [];
      const incomingPages = settings && settings.pages;
      if (existingPages.length > 0 && Array.isArray(incomingPages) && incomingPages.length === 0) {
        console.warn(`[custom-pages guard] REFUSED empty pages[] overwrite for site ${deployedSiteId} — existing has ${existingPages.length}. Likely race from updateCustomPageParent / ExternalUrl after a site switch.`);
        return res.json({
          success: false,
          error: `Refused to overwrite ${existingPages.length} existing page(s) with an empty list. Use DELETE /api/deployed-sites/:id/custom-pages/:slug to remove individual pages.`
        });
      }
      // Belt-and-braces: also refuse a write that removes slugs without
      // an explicit allow_remove_slugs flag. A partial wipe (e.g. 5→3)
      // would otherwise still leak through. Pages are removed via the
      // dedicated DELETE route, never via this endpoint.
      if (existingPages.length > 0 && Array.isArray(incomingPages)) {
        const existingSlugs = new Set(existingPages.map(p => p && p.slug).filter(Boolean));
        const incomingSlugs = new Set(incomingPages.map(p => p && p.slug).filter(Boolean));
        const dropped = [...existingSlugs].filter(s => !incomingSlugs.has(s));
        if (dropped.length > 0 && !req.body.allow_remove_slugs) {
          console.warn(`[custom-pages guard] REFUSED slug-drop for site ${deployedSiteId}: ${dropped.join(', ')}. Use DELETE route.`);
          return res.json({
            success: false,
            error: `Refused to drop page slug(s) [${dropped.join(', ')}] via this endpoint. Use DELETE /api/deployed-sites/:id/custom-pages/:slug to remove individual pages.`
          });
        }
      }
    }

    // Colour normalisation: any incoming string value that looks like a
    // corrupted hex ('##RRGGBB', '#RRGGBB#extra', etc) gets stripped to
    // exactly '#RRGGBB' before storage. Belt to the client-side sanitiser's
    // braces so no path can persist '##' pollution again (easystays
    // 2026-07-28 cta-bg / underline-color kept getting double-hashed).
    for (const [k, v] of Object.entries(settings || {})) {
      if (typeof v === 'string' && /^#{1,}[0-9A-Fa-f]/.test(v)) {
        const hex = v.replace(/[^0-9A-Fa-f]/g, '').slice(0, 6);
        if (hex.length === 6) settings[k] = '#' + hex;
      }
    }

    let mergedSettings = settings;
    if (existingResult.rows.length > 0 && existingResult.rows[0].settings) {
      const existing = existingResult.rows[0].settings;
      mergedSettings = { ...existing };
      // Hardcoded JS defaults in gas-admin.html that have ZERO meaning beyond
      // "the input was never populated". If the form submits one of these for
      // a styles field where the existing saved value is something else, that's
      // almost certainly the load/save race (load hadn't finished fetching saved
      // values when the user clicked Save). Belt to the client-side __wbLoadingKeys
      // braces — catches direct API calls and any race that slips through.
      const styleDefaultSentinels = new Set([
        '#2563eb', '#7c3aed', '#f59e0b', '#10b981',
        '#1e293b', '#475569', '#64748b', '#94a3b8'
      ]);
      // Apply incoming values — but don't let empty strings overwrite non-empty image/url fields
      // unless the user explicitly cleared them via clear_keys (× delete button).
      for (const [key, value] of Object.entries(settings)) {
        if (value === '' && existing[key] && (key.includes('image') || key.includes('url') || key.includes('logo')) && !explicitlyCleared.includes(key)) {
          // Skip — don't blank out image/url/logo fields with empty strings
          console.log(`[Settings merge] Preserving existing ${key}: ${existing[key]}`);
          continue;
        }
        // ALL SECTIONS: refuse to overwrite a populated colour/bg/font/btn field
        // with an EMPTY string. The load/save race that wiped global styles
        // also hit per-page colour fields on page-blog, page-attractions,
        // page-contact, header, hero, etc. — every section that loads values
        // into wb-{section}-*-color inputs shares the same risk when the
        // form is saved before its values have hydrated from the API.
        //
        // Sentinel-value matching was REMOVED 2026-06-25: it wrongly blocked
        // legitimate brand colours that happen to match a JS picker default
        // (e.g. Chester House client setting buttons to #f59e0b — the
        // accent-color picker's default). Empty-string protection alone
        // catches the original load/save race; client-side __wbLoadingKeys
        // guard prevents the rest.
        if (
          existing[key] &&
          existing[key] !== value &&
          !explicitlyCleared.includes(key) &&
          /color|bg|text|font|btn|primary|secondary|accent|link|radius/i.test(key) &&
          (value === '' || value === null || value === undefined)
        ) {
          console.warn(`[colour merge guard] ${section}.${key} preserved (incoming empty, existing=${JSON.stringify(existing[key])})`);
          continue;
        }
        mergedSettings[key] = value;
      }
      // Force-clear explicitly cleared keys (covers cases where the key isn't in `settings`
      // at all, e.g. the field wasn't collected because its DOM container wasn't visible)
      for (const key of explicitlyCleared) {
        if (Object.prototype.hasOwnProperty.call(mergedSettings, key)) {
          mergedSettings[key] = '';
          console.log(`[Settings merge] Explicitly cleared ${key}`);
        }
      }
    }

    // Log history before overwriting
    const oldSettings = existingResult.rows.length > 0 ? existingResult.rows[0].settings : null;
    await logSettingsHistory(deployedSiteId, site.account_id, section, oldSettings, mergedSettings, 'gas');

    // UPSERT: Try update first, then insert
    const updateResult = await pool.query(`
      UPDATE website_settings
      SET settings = $1, updated_at = CURRENT_TIMESTAMP, sync_source = 'gas'
      WHERE deployed_site_id = $2 AND section = $3
    `, [JSON.stringify(mergedSettings), deployedSiteId, section]);
    
    if (updateResult.rowCount === 0) {
      // No existing row, insert new one
      await pool.query(`
        INSERT INTO website_settings (deployed_site_id, account_id, section, settings, sync_source, updated_at)
        VALUES ($1, $2, $3, $4, 'gas', CURRENT_TIMESTAMP)
      `, [deployedSiteId, site.account_id, section, JSON.stringify(settings)]);
      console.log(`Inserted new ${section} settings for deployed site ${deployedSiteId}`);
    } else {
      console.log(`Updated ${section} settings for deployed site ${deployedSiteId}`);
    }
    
    // Push to WordPress if site has URL
    let wpPushResult = null;
    if (site.site_url) {
      wpPushResult = await pushSettingsToWordPress(site.site_url, section, settings);
    }

    // Clear API settings transient caches so changes appear immediately.
    // Developer themes (developer-light/dark) use gas_api_settings_{blog_id}.
    // The burger theme uses gas_booking_pro_settings_{blog_id} (Pro Builder).
    // Both must be flushed on every settings save — missing the second one was
    // why Pro Builder Settings appeared to have no effect for up to 5 minutes
    // (the burger plugin's transient TTL).
    if (site.blog_id && site.site_url) {
      const flushKeys = [
        'gas_api_settings_' + site.blog_id,
        'gas_booking_pro_settings_' + site.blog_id,
        'gas_booking_seo_' + site.blog_id
      ];
      for (const tk of flushKeys) {
        try {
          await fetch('https://sites.gas.travel/gas-api.php', {
            method: 'POST',
            headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'flush_transient', site_url: site.site_url, transient_key: tk })
          });
          console.log(`Flushed ${tk} for blog ${site.blog_id}`);
        } catch (e) {
          console.log(`Cache bust failed for ${tk}: ${e.message}`);
        }
      }

      // Settings changes affect every cached HTML page on the site (header, menus,
      // colours, page-specific content, etc.), so bust the entire SuperCache dir
      // for this host. Without this, edits in the Web Builder appear to "not
      // render" — DB + transients are fresh but visitors still get stale HTML.
      fetch('https://sites.gas.travel/gas-api.php', {
        method: 'POST',
        headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'flush_page_cache', site_url: site.site_url, paths: [''] })
      }).catch(e => console.log(`Page-cache flush failed: ${e.message}`));

      // Sync pages & menu order to WordPress when a page section is saved
      if (section.startsWith('page-') || section === 'custom-pages') {
        try {
          const siteHost = new URL(site.site_url).origin;
          await fetch(`${siteHost}/wp-json/gas-booking/v1/sync-pages`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({})
          });
          console.log(`Menu sync triggered for ${site.site_url}`);
        } catch (e) {
          console.log(`Menu sync failed for ${site.site_url}: ${e.message}`);
        }
      }
    }

    res.json({
      success: true,
      message: 'Settings saved',
      deployed_site_id: deployedSiteId,
      section,
      wordpress_push: wpPushResult
    });
    
  } catch (error) {
    console.error('Save deployed site settings error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Helper function to push settings to WordPress
