// Share a deployed site with a sub-account (or unshare with null).
// Validates the target sub-account is a child of the site's owning account
// so an agency can only share with its own clients.
app.put('/api/deployed-sites/:id/client-account', async (req, res) => {
  try {
    const { id } = req.params;
    const { client_account_id } = req.body;

    const siteResult = await pool.query(
      'SELECT id, account_id FROM deployed_sites WHERE id = $1',
      [id]
    );
    if (siteResult.rows.length === 0) {
      return res.json({ success: false, error: 'Deployed site not found' });
    }
    const site = siteResult.rows[0];

    if (client_account_id !== null && client_account_id !== undefined) {
      const childCheck = await pool.query(
        'SELECT id, parent_id FROM accounts WHERE id = $1',
        [client_account_id]
      );
      if (childCheck.rows.length === 0) {
        return res.json({ success: false, error: 'Client account not found' });
      }
      if (childCheck.rows[0].parent_id !== site.account_id) {
        return res.json({ success: false, error: 'Client account must be a sub-account of the site owner' });
      }
    }

    const newValue = (client_account_id === null || client_account_id === undefined || client_account_id === '')
      ? null
      : parseInt(client_account_id);

    const updated = await pool.query(`
      UPDATE deployed_sites SET client_account_id = $2, updated_at = NOW()
      WHERE id = $1
      RETURNING id, account_id, client_account_id, site_name
    `, [id, newValue]);

    res.json({ success: true, site: updated.rows[0] });
  } catch (error) {
    console.error('Update deployed site client_account_id error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Connect custom domain to deployed site
app.post('/api/deployed-sites/connect-domain', async (req, res) => {
  // SSH-based provision flow: identical to /api/admin/deployed-sites/:id/provision-custom-domain.
  // Bubbles real per-stage errors (certbot failures, DNS issues, etc.) instead of the legacy
  // VPS gas-api.php path that silently swallowed shell_exec stderr.
  try {
    const { site_id, domain } = req.body;

    if (!site_id || !domain) {
      return res.json({ success: false, error: 'site_id and domain are required' });
    }
    const cleanDomain = domain.toLowerCase().replace(/^(https?:\/\/)?(www\.)?/, '').replace(/\/$/, '');
    const safeDomain = cleanDomain.replace(/[^a-z0-9.-]/gi, '');

    const siteResult = await pool.query('SELECT id, blog_id, site_name FROM deployed_sites WHERE id = $1', [site_id]);
    if (siteResult.rows.length === 0) return res.json({ success: false, error: 'Deployed site not found' });
    const site = siteResult.rows[0];
    if (!site.blog_id) return res.json({ success: false, error: 'Site has no blog_id — cannot map WP multisite' });

    // Pre-flight DNS check — covers BOTH the SSH and legacy gas-api.php
    // paths below. Saves operators from chasing certbot failures that
    // are really just "A record points at the wrong IP".
    const pre = await _preflightDomainDns(safeDomain);
    if (!pre.ok) return res.json({ success: false, error: pre.error, dns_check: pre.dns_check });

    // Fallback path — used when VPS_SSH_KEY env var isn't set on Railway. Delegates
    // nginx/certbot/wp-options to gas-api.php's connect-custom-domain action. The
    // legacy action used shell_exec(... 2>&1) without capturing output so cert
    // failures used to silently return success — we mitigate by doing a post-
    // provision HTTPS probe and treating a non-2xx response as a failure.
    if (!VPS_SSH_AVAILABLE) {
      try {
        const vpsResp = await fetch('https://sites.gas.travel/gas-api.php', {
          method: 'POST',
          headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'connect-custom-domain', blog_id: site.blog_id, domain: safeDomain }),
          signal: AbortSignal.timeout(120000)
        });
        const vpsData = await vpsResp.json();
        if (!vpsData?.success) {
          return res.json({ success: false, error: vpsData?.error || 'VPS connect-custom-domain failed' });
        }
        // Probe — confirm HTTPS actually works before reporting success
        let probeOk = false;
        for (let i = 0; i < 3; i++) {
          try {
            const probe = await fetch(`https://${safeDomain}/`, { method: 'HEAD', redirect: 'manual', signal: AbortSignal.timeout(8000) });
            if (probe.status >= 200 && probe.status < 400) { probeOk = true; break; }
          } catch {}
          await new Promise(r => setTimeout(r, 2000));
        }
        if (!probeOk) {
          return res.json({ success: false, error: 'Provisioning ran but HTTPS probe failed — DNS may not yet resolve to the VPS, or certbot failed silently. Verify DNS A records point to 72.61.207.109 and retry.' });
        }
        await pool.query(
          `UPDATE deployed_sites SET custom_domain = $1, site_url = $2, site_status = 'live', updated_at = NOW() WHERE id = $3`,
          [safeDomain, `https://${safeDomain}/`, site_id]
        );
        // Activate cache for the new host
        try {
          await fetch('https://sites.gas.travel/gas-api.php', { method: 'POST', headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'set_cache_host', site_url: `https://${safeDomain}/`, custom_domain: safeDomain, enable: true }) });
          await fetch('https://sites.gas.travel/gas-api.php', { method: 'POST', headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'toggle_plugin', site_url: `https://${safeDomain}/`, plugin: 'wp-super-cache', toggle: 'activate' }) });
        } catch {}
        return res.json({ success: true, domain: safeDomain, url: `https://${safeDomain}`, message: 'Domain connected (via legacy path — add VPS_SSH_KEY env var on Railway for per-stage error detail)' });
      } catch (e) {
        return res.json({ success: false, error: 'Legacy provisioning failed: ' + e.message });
      }
    }

    const { execSync } = require('child_process');
    const vpsKey = getVpsSshKeyPath();
    const vpsHost = 'root@72.61.207.109';
    const sshOpts = `-i ${vpsKey} -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o LogLevel=ERROR`;
    // Single-quote wrap — bash treats anything inside '...' literally (no escape
    // interpretation), so embedded double quotes, backslashes, pipes etc. survive
    // intact. Only single-quote itself needs handling: 'foo' → 'foo' (untouched);
    // a literal ' is encoded as '\'' (close-quote, escaped quote, reopen-quote).
    const ssh = (cmd, timeout = 30000) => execSync(`ssh ${sshOpts} ${vpsHost} '${cmd.replace(/'/g, "'\\''")}'`, { timeout }).toString();
    const steps = [];

    // Stage 1: nginx vhost
    let hasNginx = false;
    try { ssh(`test -f /etc/nginx/sites-enabled/${safeDomain}`, 10000); hasNginx = true; steps.push({ stage: 'nginx', status: 'already-present' }); } catch {}
    if (!hasNginx) {
      const nginxConf = `server {
    listen 80;
    server_name ${safeDomain} www.${safeDomain};
    root /var/www/wordpress;
    index index.php;
    client_max_body_size 64M;
    location / { try_files $uri $uri/ /index.php?$args; }
    location ~ \\.php$ { include snippets/fastcgi-php.conf; fastcgi_pass unix:/var/run/php/php8.3-fpm.sock; }
    location ~ /\\.ht { deny all; }
}`;
      try {
        // base64 transport — see incident comment in the older path above.
        const nginxConfB64_b = Buffer.from(nginxConf).toString('base64');
        execSync(
          `ssh ${sshOpts} ${vpsHost} 'echo ${nginxConfB64_b} | base64 -d > /etc/nginx/sites-available/${safeDomain} && ln -sf /etc/nginx/sites-available/${safeDomain} /etc/nginx/sites-enabled/${safeDomain} && nginx -t && systemctl reload nginx'`,
          { timeout: 30000 }
        );
        steps.push({ stage: 'nginx', status: 'created' });
      } catch (e) {
        steps.push({ stage: 'nginx', status: 'failed', error: (e.stderr?.toString() || e.message).slice(0, 400) });
        return res.json({ success: false, error: 'nginx setup failed', domain: safeDomain, steps });
      }
    }

    // Stage 2: SSL cert
    let hasCert = false;
    try { ssh(`test -d /etc/letsencrypt/live/${safeDomain}`, 10000); hasCert = true; steps.push({ stage: 'cert', status: 'already-present' }); } catch {}
    if (!hasCert) {
      try {
        ssh(`certbot --nginx -d ${safeDomain} -d www.${safeDomain} --non-interactive --agree-tos --email admin@gas.travel --redirect`, 120000);
        steps.push({ stage: 'cert', status: 'issued' });
      } catch (e) {
        steps.push({ stage: 'cert', status: 'failed', error: (e.stderr?.toString() || e.message).slice(0, 400) });
        return res.json({ success: false, error: 'certbot failed', domain: safeDomain, steps });
      }
    }

    // Stage 3: WP multisite mapping + siteurl/home (idempotent).
    // ssh helper now wraps the remote command in single quotes, so embedded
    // double quotes around SQL survive unmolested.
    try {
      ssh(`cd /var/www/wordpress && wp db query "UPDATE wp_blogs SET domain='${safeDomain}', path='/' WHERE blog_id=${site.blog_id}" --allow-root`, 20000);
      ssh(`cd /var/www/wordpress && wp option update siteurl https://${safeDomain} --url=https://${safeDomain} --allow-root`, 20000);
      ssh(`cd /var/www/wordpress && wp option update home https://${safeDomain} --url=https://${safeDomain} --allow-root`, 20000);
      steps.push({ stage: 'wp-options', status: 'applied' });
    } catch (e) {
      steps.push({ stage: 'wp-options', status: 'failed', error: (e.stderr?.toString() || e.message).slice(0, 400) });
    }

    // Stage 4: deployed_sites — also flip to 'live' so WP Super Cache + cache gate engage
    await pool.query(
      `UPDATE deployed_sites SET custom_domain = $1, site_url = $2, site_status = 'live', updated_at = NOW() WHERE id = $3`,
      [safeDomain, `https://${safeDomain}/`, site_id]
    );
    steps.push({ stage: 'db', status: 'updated', site_status: 'live' });

    // Stage 5: enable WP Super Cache for the new host (gas-live-hosts gate + plugin)
    try {
      await fetch('https://sites.gas.travel/gas-api.php', {
        method: 'POST',
        headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'set_cache_host', site_url: `https://${safeDomain}/`, custom_domain: safeDomain, enable: true })
      });
      await fetch('https://sites.gas.travel/gas-api.php', {
        method: 'POST',
        headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'toggle_plugin', site_url: `https://${safeDomain}/`, plugin: 'wp-super-cache', toggle: 'activate' })
      });
      steps.push({ stage: 'cache', status: 'enabled' });
    } catch (e) {
      steps.push({ stage: 'cache', status: 'failed', error: e.message.slice(0, 200) });
    }

    return res.json({ success: true, domain: safeDomain, url: `https://${safeDomain}`, steps, message: 'Domain connected and cache enabled' });
  } catch (error) {
    console.error('[Custom Domain] Error connecting domain:', error);
    res.json({ success: false, error: error.message });
  }
});

// Remove custom domain from deployed site
// =====================================================
// Cloudflare Origin Certificate flow
// =====================================================
// When a custom domain sits behind Cloudflare's proxy (orange cloud),
// Let's Encrypt's HTTP-01 challenge can't reach the origin. The
// workaround: customer creates a 15-year Cloudflare Origin Certificate
// (free, lives in their Cloudflare dashboard under SSL/TLS → Origin
// Server), pastes the cert + private key into a self-service form
// (link below), and GAS installs it on the multisite VPS.
//
// Two ways to install:
//   (a) Master operator pastes cert + key directly via POST below
//   (b) Generate a one-off token, send the link to the customer, they
//       paste it themselves at /custom-ssl/:token (no GAS Admin login
//       needed). Token expires after 24h.

// Cloudflare IP ranges — used to auto-detect proxied domains during
// the Connect Domain flow so we can branch the UX.
// https://www.cloudflare.com/ips/
const CLOUDFLARE_V4_RANGES = [
  '173.245.48.0/20', '103.21.244.0/22', '103.22.200.0/22', '103.31.4.0/22',
  '141.101.64.0/18', '108.162.192.0/18', '190.93.240.0/20', '188.114.96.0/20',
  '197.234.240.0/22', '198.41.128.0/17', '162.158.0.0/15', '104.16.0.0/13',
  '104.24.0.0/14', '172.64.0.0/13', '131.0.72.0/22'
];
function _ipInCidr(ip, cidr) {
  const [base, bitsStr] = cidr.split('/');
  const bits = parseInt(bitsStr, 10);
  const ipNum = ip.split('.').reduce((acc, oct) => (acc << 8) + parseInt(oct, 10), 0) >>> 0;
  const baseNum = base.split('.').reduce((acc, oct) => (acc << 8) + parseInt(oct, 10), 0) >>> 0;
  const mask = bits === 0 ? 0 : (~0 << (32 - bits)) >>> 0;
  return (ipNum & mask) === (baseNum & mask);
}
function _isCloudflareIp(ip) {
  return CLOUDFLARE_V4_RANGES.some(cidr => _ipInCidr(ip, cidr));
}

app.get('/api/admin/sites/:id/dns-check', async (req, res) => {
  try {
    const r = await pool.query('SELECT id, custom_domain FROM deployed_sites WHERE id = $1', [req.params.id]);
    const domain = req.query.domain || r.rows[0]?.custom_domain;
    if (!domain) return res.json({ success: false, error: 'no domain to check' });
    const dns = require('dns').promises;
    let ips = [];
    try { ips = await dns.resolve4(domain); } catch (e) {}
    const cf = ips.some(_isCloudflareIp);
    res.json({ success: true, domain, ips, cloudflare: cf, vps_ip: '72.61.207.109', points_to_vps: ips.includes('72.61.207.109') });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

// Generate a one-off token for customer self-service Origin Cert install.
// Default 7 days — customer typically takes a few days to get round to it.
// Operator can pass expires_in_days in the body to override (e.g., 14 for
// "they're on holiday" or 1 for a tight rollout).
app.post('/api/admin/sites/:id/cf-origin-token', async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const r = await pool.query('SELECT id, site_url, custom_domain FROM deployed_sites WHERE id = $1', [id]);
    if (!r.rows[0]) return res.json({ success: false, error: 'site not found' });
    const { domain, expires_in_days } = req.body || {};
    const targetDomain = (domain || r.rows[0].custom_domain || '').toLowerCase().replace(/^(https?:\/\/)?(www\.)?/, '').replace(/\/$/, '');
    if (!targetDomain) return res.json({ success: false, error: 'domain required (no custom_domain on the site yet — pass via body)' });
    const days = Math.max(1, Math.min(30, parseInt(expires_in_days, 10) || 7));
    const token = require('crypto').randomBytes(20).toString('hex');
    await pool.query(`
      UPDATE deployed_sites
      SET cf_origin_token = $2,
          cf_origin_token_expires_at = NOW() + ($4 || ' days')::interval,
          custom_domain = COALESCE(custom_domain, $3)
      WHERE id = $1
    `, [id, token, targetDomain, days]);
    const base = process.env.PUBLIC_BASE_URL || 'https://admin.gas.travel';
    res.json({ success: true, token, link: `${base}/custom-ssl/${token}`, domain: targetDomain, expires_in_days: days });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

