// Public install endpoint — authenticates via the token rather than a logged-in session
app.post('/api/public/install-origin-cert', async (req, res) => {
  try {
    const { token, cert, key } = req.body || {};
    if (!token || !cert || !key) return res.json({ success: false, error: 'token, cert, and key required' });
    const r = await pool.query(`
      SELECT id, blog_id, custom_domain
      FROM deployed_sites
      WHERE cf_origin_token = $1 AND cf_origin_token_expires_at > NOW()
      LIMIT 1
    `, [token]);
    if (!r.rows[0]) return res.json({ success: false, error: 'token expired or invalid' });
    const site = r.rows[0];
    const domain = site.custom_domain;
    if (!cert.includes('BEGIN CERTIFICATE')) return res.json({ success: false, error: 'certificate block looks malformed' });
    if (!key.includes('BEGIN PRIVATE KEY') && !key.includes('BEGIN RSA PRIVATE KEY')) return res.json({ success: false, error: 'private key block looks malformed' });

    if (!VPS_SSH_AVAILABLE) return res.json({ success: false, error: 'VPS SSH not configured on this Railway instance' });

    const { execSync } = require('child_process');
    const sshOpts = `-i ${VPS_SSH_KEY_PATH} -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o BatchMode=yes`;
    const vpsHost = 'root@72.61.207.109';
    const ssh = (cmd, timeout = 30000) => execSync(`ssh ${sshOpts} ${vpsHost} '${cmd.replace(/'/g, "'\\''")}'`, { timeout }).toString();

    const certDir = `/etc/letsencrypt/live/${domain}`;
    // Write cert + key via stdin (avoids shell quoting issues with PEM blocks)
    const { spawnSync } = require('child_process');
    const writeFile = (remotePath, contents) => {
      const r = spawnSync('ssh', [sshOpts.split(' ').filter(Boolean), vpsHost, `mkdir -p ${certDir} && cat > ${remotePath} && chmod 600 ${remotePath}`].flat(), {
        input: contents,
        timeout: 30000
      });
      if (r.status !== 0) throw new Error(`ssh write ${remotePath} failed: ${r.stderr.toString()}`);
    };
    writeFile(`${certDir}/fullchain.pem`, cert + '\n');
    writeFile(`${certDir}/privkey.pem`, key + '\n');

    // Make sure Nginx vhost exists and references the cert. Re-emit a clean
    // vhost rather than trying to patch an existing one.
    const nginxConf = `server {
    listen 80;
    listen 443 ssl;
    server_name ${domain} www.${domain};
    ssl_certificate ${certDir}/fullchain.pem;
    ssl_certificate_key ${certDir}/privkey.pem;
    root /var/www/wordpress;
    index index.php;
    client_max_body_size 64M;
    location / { try_files $uri $uri/ /index.php?$args; }
    location ~ \\.php$ { include snippets/fastcgi-php.conf; fastcgi_pass unix:/var/run/php/php8.3-fpm.sock; }
}`;
    // base64 transport — see incident comment in the older path above.
    // The previous JSON.stringify+echo path also wrote literal "\n" because
    // bash echo doesn't interpret escape sequences by default.
    const nginxConfB64_c = Buffer.from(nginxConf).toString('base64');
    ssh(`echo ${nginxConfB64_c} | base64 -d > /etc/nginx/sites-available/${domain} && ln -sf /etc/nginx/sites-available/${domain} /etc/nginx/sites-enabled/${domain} && nginx -t && systemctl reload nginx`, 30000);

    // Tell WordPress multisite that this domain maps to the blog_id
    const wpPath = '/var/www/wordpress';
    ssh(`cd ${wpPath} && wp db query "UPDATE wp_blogs SET domain='${domain}', path='/' WHERE blog_id=${site.blog_id}" --allow-root`, 15000);
    ssh(`cd ${wpPath} && wp option update siteurl 'https://${domain}' --url=https://${domain} --allow-root && wp option update home 'https://${domain}' --url=https://${domain} --allow-root`, 30000);

    // Update GAS DB + clear the token so the link can't be reused
    await pool.query(`
      UPDATE deployed_sites
      SET custom_domain = $2, ssl_provider = 'cloudflare_origin', cf_origin_token = NULL, cf_origin_token_expires_at = NULL
      WHERE id = $1
    `, [site.id, domain]);

    res.json({ success: true, domain, message: 'SSL installed. Customer should set Cloudflare SSL/TLS mode to Full (strict).' });
  } catch (e) {
    console.error('[install-origin-cert]', e);
    res.json({ success: false, error: e.message });
  }
});

app.post('/api/deployed-sites/remove-domain', async (req, res) => {
  try {
    const { site_id } = req.body;
    
    if (!site_id) {
      return res.json({ success: false, error: 'site_id is required' });
    }
    
    // Get the deployed site
    const siteResult = await pool.query('SELECT * FROM deployed_sites WHERE id = $1', [site_id]);
    if (siteResult.rows.length === 0) {
      return res.json({ success: false, error: 'Deployed site not found' });
    }
    
    const site = siteResult.rows[0];
    const customDomain = site.custom_domain;
    
    if (!customDomain) {
      return res.json({ success: false, error: 'No custom domain configured' });
    }
    
    console.log(`[Custom Domain] Removing ${customDomain} from site ${site_id}`);
    
    // Call VPS API to remove the domain mapping
    const SITES_VPS_URL = 'https://sites.gas.travel/gas-api.php';
    
    const vpsResponse = await fetch(SITES_VPS_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': VPS_DEPLOY_API_KEY
      },
      body: JSON.stringify({
        action: 'remove-custom-domain',
        blog_id: site.blog_id,
        domain: customDomain
      })
    });
    
    const vpsData = await vpsResponse.json();
    
    // Update database regardless of VPS response
    await pool.query(`
      UPDATE deployed_sites 
      SET custom_domain = NULL, updated_at = NOW()
      WHERE id = $1
    `, [site_id]);
    
    res.json({ 
      success: true, 
      message: 'Domain removed'
    });
  } catch (error) {
    console.error('[Custom Domain] Error removing domain:', error);
    res.json({ success: false, error: error.message });
  }
});

// Manually set custom domain (for already configured sites)
// Diagnostic: probes whether the auto-provision SSH path actually works.
// Hit this BEFORE pushing a custom domain — gives a quick yes/no on
// whether VPS_SSH_KEY is set up correctly. Read-only on the VPS.
app.get('/api/admin/test-vps-ssh', async (req, res) => {
  if (!VPS_SSH_AVAILABLE) {
    return res.json({
      success: false,
      ready: false,
      reason: 'VPS_SSH_KEY env var not set on Railway and no /root/.ssh/id_ed25519 fallback. Custom-domain auto-provisioning will fail.',
      fix: 'Add VPS_SSH_KEY env var on Railway with the OpenSSH private key contents (the same key Steve uses locally to SSH to the VPS).'
    });
  }
  try {
    const { execSync } = require('child_process');
    const sshOpts = `-i ${getVpsSshKeyPath()} -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o LogLevel=ERROR -o ConnectTimeout=10`;
    const out = execSync(`ssh ${sshOpts} root@72.61.207.109 "hostname && nginx -v 2>&1 && certbot --version 2>&1 && wp --version --allow-root --path=/var/www/wordpress 2>&1"`, { timeout: 15000 }).toString();
    res.json({ success: true, ready: true, vps_response: out.trim().split('\n') });
  } catch (e) {
    res.json({
      success: false,
      ready: false,
      reason: 'SSH attempt failed',
      error: e.message,
      stderr: e.stderr ? e.stderr.toString().slice(0, 500) : null
    });
  }
});

app.post('/api/deployed-sites/set-custom-domain', async (req, res) => {
  try {
    const { site_id, domain } = req.body;

    if (!site_id) {
      return res.json({ success: false, error: 'site_id is required' });
    }

    const cleanDomain = domain ? domain.toLowerCase().replace(/^(https?:\/\/)?(www\.)?/, '').replace(/\/$/, '') : null;

    // Get site details for VPS provisioning
    const site = await pool.query('SELECT blog_id, slug, custom_domain FROM deployed_sites WHERE id = $1', [site_id]);
    if (!site.rows.length) return res.json({ success: false, error: 'Site not found' });
    const siteData = site.rows[0];

    // Save to database
    await pool.query(`
      UPDATE deployed_sites
      SET custom_domain = $1, site_url = $2, updated_at = NOW()
      WHERE id = $3
    `, [cleanDomain, cleanDomain ? `https://${cleanDomain}/` : `https://${siteData.slug}.sites.gas.travel/`, site_id]);

    // Provision on VPS — Nginx config + SSL + WordPress domain mapping
    let vpsResult = null;
    if (cleanDomain && siteData.blog_id) {
      try {
        const vpsResponse = await fetch(`${VPS_DEPLOY_URL}?action=setup-custom-domain`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-API-Key': VPS_DEPLOY_API_KEY },
          body: JSON.stringify({ domain: cleanDomain, blog_id: siteData.blog_id })
        });
        vpsResult = await vpsResponse.json();
        console.log('[Custom Domain] VPS setup result:', vpsResult);
      } catch (vpsErr) {
        console.error('[Custom Domain] VPS setup error:', vpsErr.message);
        vpsResult = { success: false, error: vpsErr.message };
      }
    } else if (!cleanDomain && siteData.custom_domain && siteData.blog_id) {
      // Removing custom domain — revert to multisite subdomain
      try {
        const vpsResponse = await fetch(`${VPS_DEPLOY_URL}?action=remove-custom-domain`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-API-Key': VPS_DEPLOY_API_KEY },
          body: JSON.stringify({ domain: siteData.custom_domain, blog_id: siteData.blog_id, slug: siteData.slug })
        });
        vpsResult = await vpsResponse.json();
        console.log('[Custom Domain] VPS removal result:', vpsResult);
      } catch (vpsErr) {
        console.error('[Custom Domain] VPS removal error:', vpsErr.message);
      }
    }

    res.json({
      success: true,
      domain: cleanDomain,
      message: cleanDomain ? `Custom domain set to ${cleanDomain}` : 'Custom domain removed',
      vps: vpsResult
    });
  } catch (error) {
    console.error('[Custom Domain] Error setting domain:', error);
    res.json({ success: false, error: error.message });
  }
});

// Delete a deployed site
app.delete('/api/deploy/:id', async (req, res) => {
  try {
    const deployId = req.params.id;
    const forceDelete = req.query.force === 'true';
    
    // Get deployment record
    const result = await pool.query('SELECT * FROM deployed_sites WHERE id = $1', [deployId]);
    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Deployment not found' });
    }
    
    const deployment = result.rows[0];
    let vpsDeleted = false;
    let vpsError = null;
    
    // Try to delete from VPS (but don't fail if it doesn't work)
    try {
      const response = await fetch(`${VPS_DEPLOY_URL}?action=delete-site`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-API-Key': VPS_DEPLOY_API_KEY
        },
        body: JSON.stringify({
          blog_id: deployment.blog_id,
          confirm: 'DELETE'
        })
      });
      const data = await response.json();
      vpsDeleted = data.success;
      if (!data.success) vpsError = data.error;
    } catch (e) {
      vpsError = e.message;
    }
    
    // Always delete from database if VPS succeeded, force=true, or site already marked deleted
    if (vpsDeleted || forceDelete || deployment.status === 'deleted') {
      await pool.query('DELETE FROM deployed_sites WHERE id = $1', [deployId]);
      
      // Clear website URL from property
      await pool.query(
        'UPDATE properties SET website_url = NULL WHERE id = $1',
        [deployment.property_id]
      );
      
      // Clear website URL from rooms
      const roomIds = typeof deployment.room_ids === 'string' 
        ? JSON.parse(deployment.room_ids || '[]') 
        : (deployment.room_ids || []);
      for (const roomId of roomIds) {
        await pool.query(
          'UPDATE bookable_units SET website_url = NULL WHERE id = $1',
          [roomId]
        );
      }
      
      res.json({ 
        success: true, 
        message: 'Site deleted from database',
        vps_deleted: vpsDeleted,
        vps_error: vpsError
      });
    } else {
      // VPS failed but not force - mark as deleted instead
      await pool.query(
        'UPDATE deployed_sites SET status = $1, updated_at = NOW() WHERE id = $2',
        ['deleted', deployId]
      );
      res.json({ 
        success: true, 
        message: 'Marked as deleted (VPS site may still exist). Use ?force=true to remove from database.',
        vps_error: vpsError
      });
    }
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

