// ── Rate-aware deposit rule selector ──
// A property/account can have several active deposit_rules (e.g. a 20%
// refundable rule AND a 100% non-refundable rule). The right one for a
// given booking depends on the chosen offer's refund_policy. Picking the
// wrong rule means billing the wrong deposit % or scheduling the balance
// charge on the wrong day — which is exactly how the 2026-05-31 incident
// happened (LIMIT 1 ORDER BY created_at DESC always returned the same
// rule regardless of the rate chosen).
//
// Selection priority:
//   1. Property-scoped rule matching refund_policy
//   2. Account-default rule matching refund_policy
//   3. Property-scoped rule with any policy (graceful fallback)
//   4. Account-default rule with any policy
// Short-term booking window: any booking arriving within this many days
// of "now" is treated as non-refundable regardless of the chosen offer.
// Matches the established Account Default rule ("80% balance due 30 days
// before check-in"): if we're already inside the 30-day window, the
// guest must pay in full and is non-refundable.
const SHORT_TERM_NON_REFUNDABLE_DAYS = 30;

async function resolveDepositRule(pool, propertyId, accountId, offerRefundPolicy, arrivalDate, bookingDate) {
  let withinShortTermWindow = false;
  if (arrivalDate) {
    const arrival = new Date(arrivalDate);
    const booking = new Date(bookingDate || new Date());
    const daysUntil = Math.floor((arrival - booking) / 86400000);
    withinShortTermWindow = daysUntil >= 0 && daysUntil <= SHORT_TERM_NON_REFUNDABLE_DAYS;
  }

  const wantsNonRefundable = offerRefundPolicy === 'non_refundable' || withinShortTermWindow;

  const result = await pool.query(`
    SELECT dr.*
    FROM deposit_rules dr
    WHERE dr.is_active = true
      AND (dr.property_id = $1 OR (dr.property_id IS NULL AND dr.account_id = $2))
    ORDER BY (dr.property_id IS NOT NULL) DESC, dr.created_at DESC
  `, [propertyId, accountId]);

  if (result.rows.length === 0) return null;

  const wantedMatch = result.rows.find(r => {
    const policy = r.refund_policy || '';
    return wantsNonRefundable ? policy === 'non_refundable' : policy !== 'non_refundable';
  });

  return wantedMatch || result.rows[0];
}

// ── Payment Schedule: helper to calculate multi-tier schedule for a booking ──
function calculatePaymentScheduleForBooking(rule, totalAmount, arrivalDate, bookingDate) {
  // ── Critical: ONLY schedule_mode='schedule' generates booking_payment_schedule rows. ──
  //
  // For schedule_mode='basic' (or null), the deposit+balance flow is handled by
  // bookings.deposit_amount / balance_amount and processAutoChargePayments. If we
  // ALSO synthesize tier rows here, both crons (processAutoChargePayments AND
  // processScheduledTierPayments) end up firing on the same balance — with
  // different idempotency keys (`auto-charge-{booking}-{date}` vs
  // `tier-charge-{tier}-{date}`) — so Stripe creates TWO charges. That's the
  // 2026-05-31 double-charge incident (bookings 215/225/145913 disarmed manually).
  //
  // For basic mode this function still computes the right charge_now_amount
  // (deposit %) for /api/payments/calculate-deposit, but `tiers` stays empty
  // so nothing gets inserted into booking_payment_schedule.
  let tiers = [];
  let basicModeDepositAmount = 0;

  if (rule.schedule_mode === 'schedule' && rule.payment_schedule && Array.isArray(rule.payment_schedule)) {
    // Multi-tier schedule from JSONB — this is the only path that produces tiers.
    tiers = rule.payment_schedule.map(t => ({ ...t }));
  } else {
    // Basic mode: compute deposit % for caller, do NOT synthesize tiers.
    const pct = parseFloat(rule.deposit_percentage);
    if (!isNaN(pct) && pct > 0) {
      basicModeDepositAmount = Math.round((totalAmount * pct / 100) * 100) / 100;
    }
  }

  // Sort by order
  tiers.sort((a, b) => a.order - b.order);

  const arrival = new Date(arrivalDate);
  const booking = new Date(bookingDate || new Date());
  const msPerDay = 86400000;
  const daysUntilCheckin = Math.floor((arrival - booking) / msPerDay);

  // 2026-07-23 Steve — Basic-mode inside-balance-window override.
  // When schedule_mode='basic' and the guest books INSIDE the auto-charge
  // window (daysUntilCheckin <= balance_due_days), the balance is already
  // technically due. Historically basic mode ignored this and only
  // charged the deposit % — for a rule with deposit=0% (like Charles
  // House Windsor) that meant £0 captured at booking and the full
  // balance handed off to the cron. The cron fires OFF-SESSION though,
  // so cards requiring SCA (all UK Visa/MC now) decline with
  // requires_payment_method and the operator has to chase manually.
  // (Lisa Scudieri GAS-439833 22 Jul 2026: same-day arrival, cron
  // decline, Barbara ran manual charge next morning.)
  // Fix: if we're inside the window, roll the WHOLE amount into the
  // immediate booking charge. The card is still on-session at that
  // point, SCA works, and the money captures cleanly.
  // This mirrors the 'hasPassed' rollup multi-tier schedules already
  // do below; both paths now behave the same for inside-window bookings.
  if (tiers.length === 0) {
    const balanceDueDays = parseInt(rule.balance_due_days ?? rule.auto_charge_days_before ?? 14);
    if (Number.isFinite(daysUntilCheckin) && Number.isFinite(balanceDueDays) && daysUntilCheckin <= balanceDueDays) {
      basicModeDepositAmount = Math.round(totalAmount * 100) / 100;
    }
  }

  let rolledUpPercentage = 0;
  const result = [];

  for (const tier of tiers) {
    const tierDaysBefore = tier.days_before; // null = at booking
    const isAtBooking = tierDaysBefore === null || tierDaysBefore === undefined;
    const hasPassed = !isAtBooking && daysUntilCheckin <= tierDaysBefore;

    if (isAtBooking || hasPassed) {
      // Roll up into booking charge
      rolledUpPercentage += parseFloat(tier.percentage);
      result.push({
        tier_order: tier.order,
        percentage: parseFloat(tier.percentage),
        amount: Math.round((totalAmount * parseFloat(tier.percentage) / 100) * 100) / 100,
        days_before: tier.days_before,
        due_date: null,
        status: isAtBooking ? 'charge_now' : 'rolled_up'
      });
    } else {
      // Schedule for future auto-charge
      const dueDate = new Date(arrival);
      dueDate.setDate(dueDate.getDate() - tierDaysBefore);
      result.push({
        tier_order: tier.order,
        percentage: parseFloat(tier.percentage),
        amount: Math.round((totalAmount * parseFloat(tier.percentage) / 100) * 100) / 100,
        days_before: tier.days_before,
        due_date: dueDate.toISOString().split('T')[0],
        status: 'pending'
      });
    }
  }

  // Calculate the total charge at booking (all charge_now + rolled_up).
  // For basic mode (tiers === []), this is the deposit_percentage of total —
  // computed above without synthesizing tier rows that would feed the
  // multi-step cron.
  const chargeNowAmount = tiers.length === 0
    ? basicModeDepositAmount
    : result
        .filter(t => t.status === 'charge_now' || t.status === 'rolled_up')
        .reduce((sum, t) => sum + t.amount, 0);

  return {
    tiers: result,
    charge_now_amount: Math.round(chargeNowAmount * 100) / 100,
    charge_now_percentage: rolledUpPercentage,
    total_amount: totalAmount
  };
}

// Calculate deposit for a booking
app.post('/api/payments/calculate-deposit', async (req, res) => {
  try {
    const { property_id, total_amount, arrival_date, booking_date, offer_id } = req.body;

    if (arrival_date) {
      // Rate-aware rule selection — see resolveDepositRule.
      let offerRefundPolicy = null;
      if (offer_id) {
        const offerLookup = await pool.query(
          'SELECT refund_policy FROM offers WHERE id = $1',
          [parseInt(offer_id)]
        );
        const policy = offerLookup.rows[0]?.refund_policy;
        if (policy && policy !== 'inherit') offerRefundPolicy = policy;
      }
      const propLookup = await pool.query(
        'SELECT account_id FROM properties WHERE id = $1',
        [property_id]
      );
      const propAccountId = propLookup.rows[0]?.account_id;
      const rule = await resolveDepositRule(pool, property_id, propAccountId, offerRefundPolicy, arrival_date, booking_date || new Date().toISOString());

      if (rule) {
        const schedule = calculatePaymentScheduleForBooking(rule, total_amount, arrival_date, booking_date || new Date().toISOString());
        return res.json({
          success: true,
          data: {
            total: total_amount,
            deposit: schedule.charge_now_amount,
            balance: Math.round((total_amount - schedule.charge_now_amount) * 100) / 100,
            schedule_mode: rule.schedule_mode || 'basic',
            schedule: schedule.tiers,
            deposit_type: rule.deposit_type,
            deposit_setting: rule.deposit_percentage,
            balance_due_days: rule.balance_due_days,
            currency: rule.currency || 'GBP'
          }
        });
      }
    }

    // Legacy fallback: property_payment_settings
    const settingsResult = await pool.query(`
      SELECT * FROM property_payment_settings WHERE property_id = $1
    `, [property_id]);

    const settings = settingsResult.rows[0] || {
      deposit_type: 'percentage',
      deposit_amount: 25,
      balance_due_days: 14,
      currency: 'GBP'
    };

    let depositAmount;
    if (settings.deposit_type === 'percentage') {
      depositAmount = (total_amount * settings.deposit_amount) / 100;
    } else {
      depositAmount = Math.min(settings.deposit_amount, total_amount);
    }

    const balanceAmount = total_amount - depositAmount;

    res.json({
      success: true,
      data: {
        total: total_amount,
        deposit: Math.round(depositAmount * 100) / 100,
        balance: Math.round(balanceAmount * 100) / 100,
        schedule_mode: 'basic',
        deposit_type: settings.deposit_type,
        deposit_setting: settings.deposit_amount,
        balance_due_days: settings.balance_due_days,
        currency: settings.currency
      }
    });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

