app.get('/api/db/properties', async (req, res) => {
  try {
    const clientId = req.query.client_id;
    const accountId = req.query.account_id;
    // Skip the agency-walk / parent-walk when the caller only wants
    // properties directly owned by account_id (Marie / Lehmann shop
    // product picker 2026-07-11 — she's an agency but per-account
    // shop products shouldn't offer cross-account property scope).
    const ownOnly = req.query.own_only === 'true' || req.query.own_only === '1';
    let result;

    // Ensure portfolio_order column exists
    await pool.query('ALTER TABLE properties ADD COLUMN IF NOT EXISTS portfolio_order INTEGER DEFAULT 0').catch(() => {});

    if (accountId) {
      // Check the account's position in the tree:
      //  - agency_admin / has sub-accounts → walk DOWN (already worked)
      //  - submaster_admin / any account with a parent_id → walk UP to
      //    include the parent's properties (e.g. Hotel Caracas 265 →
      //    its property lives on Lorenzo Properties 224)
      //  - standalone → just own properties
      const accountCheck = await pool.query(`
        SELECT a.role, a.parent_id,
               (SELECT COUNT(*) FROM accounts WHERE parent_id = a.id) as sub_account_count
        FROM accounts a WHERE a.id = $1
      `, [accountId]);

      const isAgency = accountCheck.rows.length > 0 && accountCheck.rows[0].role === 'agency_admin';
      const hasSubAccounts = accountCheck.rows.length > 0 && parseInt(accountCheck.rows[0].sub_account_count) > 0;
      const parentId = accountCheck.rows[0]?.parent_id || null;

      if (ownOnly) {
        // Bypass the tree walk — direct-owned properties only.
        result = await pool.query(
          'SELECT * FROM properties WHERE account_id = $1 ORDER BY COALESCE(portfolio_order, 999999), name',
          [accountId]
        );
      } else if (isAgency || hasSubAccounts) {
        result = await pool.query(`
          SELECT p.*, a.name as owner_account_name FROM properties p
          LEFT JOIN accounts a ON p.account_id = a.id
          WHERE p.account_id = $1
             OR a.managed_by_id = $1
             OR a.parent_id = $1
          ORDER BY COALESCE(p.portfolio_order, 999999), p.name
        `, [accountId]);
      } else if (parentId) {
        // Sub-account with parent: include own properties + the parent's.
        result = await pool.query(
          'SELECT * FROM properties WHERE account_id = ANY($1::int[]) ORDER BY COALESCE(portfolio_order, 999999), name',
          [[parseInt(accountId), parentId]]
        );
      } else {
        // Standalone OR property-owner sub-account (managed_by_id points at
        // an aggregator but they hold no properties in account_id). Owners
        // see only the units they own via properties.owner_account_id.
        // 2026-08-08 — added for the aggregator property-owner persona
        // (EasyLandlord's individual gîte owners).
        result = await pool.query(
          `SELECT * FROM properties
            WHERE account_id = $1 OR owner_account_id = $1
            ORDER BY COALESCE(portfolio_order, 999999), name`,
          [accountId]
        );
      }
    } else if (clientId) {
      result = await pool.query('SELECT * FROM properties WHERE client_id = $1 ORDER BY COALESCE(portfolio_order, 999999), name', [clientId]);
    } else {
      result = await pool.query('SELECT * FROM properties ORDER BY COALESCE(portfolio_order, 999999), name');
    }

    // Attach accepted_methods from property_payment_settings so the Properties
    // list can render payment-method chips inline (Stripe / Direct / etc).
    if (result.rows.length > 0) {
      const ids = result.rows.map(r => r.id);
      const pps = await pool.query(
        `SELECT property_id, accepted_methods FROM property_payment_settings WHERE property_id = ANY($1::int[])`,
        [ids]
      );
      const byId = new Map(pps.rows.map(r => [r.property_id, r.accepted_methods]));
      for (const row of result.rows) {
        const am = byId.get(row.id);
        row.accepted_methods = Array.isArray(am) ? am : (typeof am === 'string' ? (() => { try { return JSON.parse(am); } catch { return []; } })() : []);
      }
    }

    res.json({ success: true, data: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Update a single property's accepted payment methods (chip toggle in Properties list).
// Surgical: touches only accepted_methods on property_payment_settings + mirrored
// account.settings.payment_methods. Does NOT touch Stripe credentials.
app.patch('/api/property/:propertyId/accepted-methods', async (req, res) => {
  try {
    const propertyId = req.params.propertyId;
    const { accepted_methods } = req.body;
    if (!Array.isArray(accepted_methods)) {
      return res.status(400).json({ success: false, error: 'accepted_methods must be an array' });
    }
    const allowed = ['card', 'square', 'pay_at_property', 'card_guarantee', 'paypal', 'airwallex'];
    const cleaned = accepted_methods.filter(m => allowed.includes(m));

    // UPSERT — preserve every other column
    await pool.query(`
      INSERT INTO property_payment_settings (property_id, accepted_methods, payment_enabled, updated_at)
      VALUES ($1, $2::jsonb, true, NOW())
      ON CONFLICT (property_id) DO UPDATE SET
        accepted_methods = EXCLUDED.accepted_methods,
        payment_enabled = true,
        updated_at = NOW()
    `, [propertyId, JSON.stringify(cleaned)]);

    res.json({ success: true, data: { property_id: Number(propertyId), accepted_methods: cleaned } });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

// Bulk update accepted_methods across many properties (Properties list bulk action).
// Body: { property_ids: number[], accepted_methods: string[] }
app.post('/api/admin/properties/bulk-accepted-methods', async (req, res) => {
  try {
    const { property_ids, accepted_methods } = req.body;
    if (!Array.isArray(property_ids) || property_ids.length === 0) {
      return res.status(400).json({ success: false, error: 'property_ids must be a non-empty array' });
    }
    if (!Array.isArray(accepted_methods)) {
      return res.status(400).json({ success: false, error: 'accepted_methods must be an array' });
    }
    const allowed = ['card', 'square', 'pay_at_property', 'card_guarantee', 'paypal', 'airwallex'];
    const cleaned = accepted_methods.filter(m => allowed.includes(m));
    const ids = property_ids.map(Number).filter(Number.isInteger);

    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      for (const pid of ids) {
        await client.query(`
          INSERT INTO property_payment_settings (property_id, accepted_methods, payment_enabled, updated_at)
          VALUES ($1, $2::jsonb, true, NOW())
          ON CONFLICT (property_id) DO UPDATE SET
            accepted_methods = EXCLUDED.accepted_methods,
            payment_enabled = true,
            updated_at = NOW()
        `, [pid, JSON.stringify(cleaned)]);
      }
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK');
      throw e;
    } finally {
      client.release();
    }

    res.json({ success: true, data: { updated: ids.length, accepted_methods: cleaned } });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

// Bulk Payment modal: toggle a single payment method on/off across properties.
// Surgical — only mutates property_payment_settings.accepted_methods. Stripe
// credentials in payment_configurations are NEVER touched here. The dedicated
// Disconnect button is the only path that removes credentials.
app.post('/api/admin/property-payment-methods/bulk-toggle', async (req, res) => {
  try {
    const { method, enable, property_ids } = req.body;
    const allowed = ['card', 'square', 'pay_at_property', 'card_guarantee', 'paypal', 'airwallex'];
    if (!allowed.includes(method)) return res.json({ success: false, error: 'invalid method' });
    if (!Array.isArray(property_ids) || property_ids.length === 0) {
      return res.json({ success: false, error: 'property_ids must be a non-empty array' });
    }
    const propIds = property_ids.map(id => parseInt(id, 10)).filter(n => Number.isFinite(n));
    if (propIds.length === 0) return res.json({ success: false, error: 'no valid property ids' });
    const updated = [];
    for (const pid of propIds) {
      // Read current methods (default to []), add or remove the target method.
      const existing = await pool.query(
        'SELECT accepted_methods FROM property_payment_settings WHERE property_id = $1',
        [pid]
      );
      const current = (existing.rows[0]?.accepted_methods || []).filter(m => m !== method);
      const next = enable ? [...current, method] : current;
      await pool.query(`
        INSERT INTO property_payment_settings (property_id, accepted_methods, payment_enabled, updated_at)
        VALUES ($1, $2::jsonb, true, NOW())
        ON CONFLICT (property_id) DO UPDATE SET accepted_methods = $2::jsonb, updated_at = NOW()
      `, [pid, JSON.stringify(next)]);
      updated.push({ property_id: pid, accepted_methods: next });
    }
    res.json({ success: true, data: updated });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

// GET properties with account payment settings (for bulk payment modal)
app.get('/api/db/properties-payment-status', async (req, res) => {
  try {
    const accountId = req.query.account_id;
    // When the operator (e.g. an agency_admin) has "Opened" a specific
    // managed client via the header dropdown, the frontend passes that
    // client's public_id here. We MUST scope to that client only and
    // skip the agency-broadening branch below — otherwise Marie at
    // Lehmann opens Mornington Rose and sees every property across all
    // 9 of her managed clients (2026-06-21 ticket).
    const clientPublicId = req.query.client_public_id;
    let whereClause = '';
    let params = [];

    if (clientPublicId) {
      const cRes = await pool.query(
        'SELECT id FROM accounts WHERE public_id = $1 LIMIT 1',
        [clientPublicId]
      );
      if (cRes.rows.length > 0) {
        whereClause = 'WHERE p.account_id = $1';
        params = [cRes.rows[0].id];
      }
      // If the public_id doesn't resolve we fall through to the empty-
      // whereClause path (returns nothing) rather than silently widen
      // back to the agency view — fail closed, not open.
    } else if (accountId) {
      const accountCheck = await pool.query(`
        SELECT a.role,
               (SELECT COUNT(*) FROM accounts WHERE parent_id = a.id) as sub_account_count
        FROM accounts a WHERE a.id = $1
      `, [accountId]);

      const isAgency = accountCheck.rows.length > 0 && accountCheck.rows[0].role === 'agency_admin';
      const hasSubAccounts = accountCheck.rows.length > 0 && parseInt(accountCheck.rows[0].sub_account_count) > 0;

      if (isAgency || hasSubAccounts) {
        whereClause = 'WHERE p.account_id = $1 OR a.managed_by_id = $1 OR a.parent_id = $1';
      } else {
        whereClause = 'WHERE p.account_id = $1';
      }
      params = [accountId];
    }

    const query = `
      SELECT p.id, p.name, p.city, p.country, p.account_id, p.stripe_secret_key,
             a.settings as account_settings,
             a.stripe_secret_key as account_stripe_secret_key,
             a.stripe_account_id as account_stripe_connect_id,
             a.stripe_onboarding_complete as account_stripe_onboarding,
             (SELECT COUNT(*) FROM payment_configurations pc
              WHERE (pc.property_id = p.id OR (pc.property_id IS NULL AND pc.account_id = p.account_id))
              AND pc.provider = 'stripe' AND pc.is_enabled = true) > 0 as has_payment_config,
             (SELECT pc.name FROM payment_configurations pc
              WHERE (pc.property_id = p.id OR (pc.property_id IS NULL AND pc.account_id = p.account_id))
              AND pc.provider = 'stripe' AND pc.is_enabled = true LIMIT 1) as stripe_config_name,
             (SELECT RIGHT(pc.credentials->>'publishable_key', 8) FROM payment_configurations pc
              WHERE (pc.property_id = p.id OR (pc.property_id IS NULL AND pc.account_id = p.account_id))
              AND pc.provider = 'stripe' AND pc.is_enabled = true LIMIT 1) as stripe_key_hint,
             pps.accepted_methods
      FROM properties p
      LEFT JOIN accounts a ON p.account_id = a.id
      LEFT JOIN property_payment_settings pps ON pps.property_id = p.id
      ${whereClause}
      ORDER BY p.name
    `;

    const result = await pool.query(query, params);

    // Parse and return
    const data = result.rows.map(row => {
      let settings = {};
      if (row.account_settings) {
        settings = typeof row.account_settings === 'string' ? JSON.parse(row.account_settings) : row.account_settings;
      }
      
      // Determine Stripe connection from any source
      const hasStripe = !!(row.stripe_secret_key || row.account_stripe_secret_key || row.has_payment_config || (row.account_stripe_connect_id && row.account_stripe_onboarding));
      
      // Parse accepted_methods
      let acceptedMethods = {};
      if (row.accepted_methods) {
        const methods = typeof row.accepted_methods === 'string' ? JSON.parse(row.accepted_methods) : row.accepted_methods;
        if (Array.isArray(methods)) {
          acceptedMethods = { card: methods.includes('card'), pay_at_property: methods.includes('pay_at_property'), card_guarantee: methods.includes('card_guarantee') };
        } else {
          acceptedMethods = methods;
        }
      }
      
      return {
        id: row.id,
        name: row.name,
        city: row.city,
        country: row.country,
        account_id: row.account_id,
        stripe_secret_key: row.stripe_secret_key,
        account_stripe_secret_key: row.account_stripe_secret_key,
        has_payment_config: row.has_payment_config,
        has_stripe: hasStripe,
        stripe_config_name: row.stripe_config_name || null,
        stripe_key_hint: row.stripe_key_hint || null,
        has_pay_at_property: !!acceptedMethods.pay_at_property,
        direct_mode: acceptedMethods.pay_at_property ? (settings.pay_property_mode || 'no_payment') : null,
        direct_bank_details: settings.bank_details || null,
        has_card_guarantee: !!acceptedMethods.card_guarantee,
        guarantee_enabled: !!acceptedMethods.card_guarantee,
        accepted_methods: acceptedMethods
      };
    });

    res.json({ success: true, data });
  } catch (error) {
    console.error('Properties payment status error:', error);
    res.json({ success: false, error: error.message });
  }
});

