// GET all bookable units/rooms
app.get('/api/db/bookable-units', async (req, res) => {
  try {
    const clientId = req.query.client_id;
    const accountId = req.query.account_id;
    const propertyId = req.query.property_id;
    const includeHidden = req.query.include_hidden === 'true';
    const lightweight = req.query.fields === 'id,name,display_name';
    let result;

    // Build hidden filter - exclude hidden rooms unless include_hidden=true
    const hiddenFilter = includeHidden ? '' : 'AND (bu.is_hidden = false OR bu.is_hidden IS NULL)';
    const selectCols = lightweight ? 'bu.id, bu.name, bu.display_name, bu.property_id, bu.max_guests, bu.room_type' : 'bu.*';

    // Sort: accommodation rooms first, then bike_storage cabinets, then
    // generic companion units (bike storage parent, pet fees etc.), each
    // group ordered by name so "Bike Shed Store 1..7" lines up properly
    // on the Availability page instead of falling out in creation order
    // (was the legacy ORDER BY created_at, which was effectively id ASC
    // and showed 4,5,6,7,1,2,3 after Hebden's bike rename).
    const ROLE_ORDER = `CASE
      WHEN bu.unit_role = 'bike_storage' THEN 1
      WHEN bu.unit_role = 'companion' THEN 2
      ELSE 0
    END`;
    // Ordering: role first (rooms → bike_storage → companion), then the
    // operator-set display_order (nulls sentinel-last so unranked units
    // fall through to name-ASC), then name for stable tie-break. Drag-
    // and-drop on the Rooms page writes display_order via
    // /api/admin/bookable-units/reorder.
    const DO_ORDER = `COALESCE(bu.display_order, 999999)`;
    if (propertyId) {
      result = await pool.query(`
        SELECT ${selectCols} FROM bookable_units bu
        WHERE bu.property_id = $1 ${hiddenFilter}
        ORDER BY ${ROLE_ORDER}, ${DO_ORDER}, bu.name
      `, [propertyId]);
    } else if (accountId) {
      result = await pool.query(`
        SELECT ${selectCols} FROM bookable_units bu
        JOIN properties p ON bu.property_id = p.id
        WHERE p.account_id = $1 ${hiddenFilter}
        ORDER BY p.name, ${ROLE_ORDER}, ${DO_ORDER}, bu.name
      `, [accountId]);
    } else if (clientId) {
      result = await pool.query(`
        SELECT bu.* FROM bookable_units bu
        JOIN properties p ON bu.property_id = p.id
        WHERE p.client_id = $1 ${hiddenFilter}
        ORDER BY p.name, ${ROLE_ORDER}, ${DO_ORDER}, bu.name
      `, [clientId]);
    } else {
      result = await pool.query(`SELECT bu.* FROM bookable_units bu WHERE 1=1 ${hiddenFilter} ORDER BY bu.property_id, ${ROLE_ORDER}, ${DO_ORDER}, bu.name`);
    }

    res.json({ success: true, data: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Persist a drag-and-drop reorder of rooms within a single property.
// Body: { property_id, ordered_ids: [...] } — order is 0-indexed left→right
// (or top→bottom). All ids must belong to property_id (server verifies).
// Master admin OR admin on the owning account. Runs as a transaction so a
// partial failure doesn't leave a half-reordered list.
app.post('/api/admin/bookable-units/reorder', async (req, res) => {
  const client = await pool.connect();
  try {
    const user = await authenticateUser(req, res);
    if (!user) { client.release(); return; }

    const propertyId = parseInt(req.body?.property_id);
    const orderedIds = Array.isArray(req.body?.ordered_ids) ? req.body.ordered_ids.map(x => parseInt(x)).filter(Number.isFinite) : null;
    if (!propertyId || !orderedIds || orderedIds.length === 0) {
      client.release();
      return res.status(400).json({ success: false, error: 'property_id and ordered_ids (non-empty array) required' });
    }

    // Scope check — every id must belong to property_id, and the caller
    // must own the property (or be master admin).
    const scope = await client.query(
      `SELECT bu.id, p.account_id
         FROM bookable_units bu JOIN properties p ON p.id = bu.property_id
        WHERE bu.property_id = $1 AND bu.id = ANY($2::int[])`,
      [propertyId, orderedIds]
    );
    if (scope.rows.length !== orderedIds.length) {
      client.release();
      return res.status(400).json({ success: false, error: 'One or more ids do not belong to property_id (possible foreign-property write attempt)' });
    }
    const propertyAccountId = scope.rows[0]?.account_id;
    if (user.role !== 'master_admin' && propertyAccountId !== (user.accountId || user.id)) {
      client.release();
      return res.status(403).json({ success: false, error: 'Not your property' });
    }

    await client.query('BEGIN');
    for (let i = 0; i < orderedIds.length; i++) {
      await client.query(
        `UPDATE bookable_units SET display_order = $1, updated_at = NOW() WHERE id = $2 AND property_id = $3`,
        [i, orderedIds[i], propertyId]
      );
    }
    await client.query('COMMIT');

    return res.json({ success: true, updated: orderedIds.length, property_id: propertyId });
  } catch (e) {
    try { await client.query('ROLLBACK'); } catch (_) {}
    console.error('[bookable-units/reorder]', e.message);
    return res.status(500).json({ success: false, error: e.message });
  } finally {
    client.release();
  }
});

