// Booking rules — GET returns saved GAS rules + cached CM rules for the
// divergence display. Modal calls this on open. Cached values come from
// gas_sync_room_types (populated by syncHostfullyRoomRules every 6h);
// ?refresh=1 forces a live re-fetch from Hostfully per sub-unit first so
// the operator always sees current values — the 6h cache is only for
// per-booking preflight cost saving, not human display.
app.get('/api/admin/properties/:id/booking-rules', async (req, res) => {
  try {
    const propertyId = parseInt(req.params.id, 10);
    const propR = await pool.query(`
      SELECT id, name, standard_check_in_days, standard_check_out_days,
             standard_min_stay, standard_max_stay, standard_lead_hours,
             standard_rules_pushed_at, standard_rules_push_error
        FROM properties WHERE id = $1
    `, [propertyId]);
    if (!propR.rows[0]) return res.json({ success: false, error: 'property not found' });

    const hostfullyR = await pool.query(`
      SELECT rt.id AS rt_id, rt.external_id AS sub_unit_uid,
             rt.check_in_days, rt.min_stay_nights, rt.max_stay_nights,
             rt.booking_lead_hours, rt.rules_synced_at, bu.name AS room_name,
             c.credentials
        FROM gas_sync_room_types rt
        JOIN gas_sync_properties sp ON sp.id = rt.sync_property_id
        JOIN gas_sync_connections c ON c.id = sp.connection_id
        JOIN bookable_units bu ON bu.id = rt.gas_room_id
       WHERE bu.property_id = $1
         AND c.adapter_code = 'hostfully'
         AND c.status = 'connected'
         AND rt.external_id IS NOT NULL
    `, [propertyId]);

    // Live refresh from Hostfully — only when ?refresh=1. Awaited so the
    // response reflects the fresh values. Failures leave the cache alone.
    if (req.query.refresh === '1' && hostfullyR.rows.length > 0) {
      const axios = require('axios');
      await Promise.all(hostfullyR.rows.map(async (r) => {
        try {
          const creds = typeof r.credentials === 'string' ? JSON.parse(r.credentials || '{}') : (r.credentials || {});
          if (!creds.apiKey) return;
          const resp = await axios.get(`https://platform.hostfully.com/api/v3/properties/${r.sub_unit_uid}`, {
            headers: { 'X-HOSTFULLY-APIKEY': creds.apiKey }, timeout: 12000,
          });
          const av = resp.data?.property?.availability || {};
          const checkInDays = Array.isArray(av.daysOfTheWeekToCheckInOn) ? av.daysOfTheWeekToCheckInOn : null;
          const minStay = Number.isFinite(parseInt(av.minimumStay, 10)) && parseInt(av.minimumStay, 10) > 0 ? parseInt(av.minimumStay, 10) : null;
          const maxStay = Number.isFinite(parseInt(av.maximumStay, 10)) && parseInt(av.maximumStay, 10) > 0 ? parseInt(av.maximumStay, 10) : null;
          const leadHours = Number.isFinite(parseInt(av.bookingLeadTime, 10)) ? parseInt(av.bookingLeadTime, 10) : null;
          await pool.query(`
            UPDATE gas_sync_room_types
               SET check_in_days = $1, min_stay_nights = $2, max_stay_nights = $3,
                   booking_lead_hours = $4, rules_synced_at = NOW()
             WHERE id = $5
          `, [checkInDays ? JSON.stringify(checkInDays) : null, minStay, maxStay, leadHours, r.rt_id]);
          // Mutate the in-memory row so the response reflects the fresh values.
          r.check_in_days = checkInDays;
          r.min_stay_nights = minStay;
          r.max_stay_nights = maxStay;
          r.booking_lead_hours = leadHours;
          r.rules_synced_at = new Date().toISOString();
        } catch (e) {
          console.warn('[booking-rules refresh] sub', r.sub_unit_uid, 'failed:', e.response?.status, e.message);
        }
      }));
    }

    const hostfully = hostfullyR.rows.map(r => ({
      sub_unit_uid: r.sub_unit_uid,
      room_name: r.room_name,
      check_in_days: r.check_in_days,
      min_stay: r.min_stay_nights,
      max_stay: r.max_stay_nights,
      lead_hours: r.booking_lead_hours,
      rules_synced_at: r.rules_synced_at,
    }));

    // Channex mapping detection — GAS is the PMS so we don't need to pull
    // rules from Channex. Just tell the modal a Channex connection exists
    // so it can show the green "Channex connected — rules push on save"
    // banner instead of the amber "no CM found" one.
    const channexR = await pool.query(`
      SELECT COUNT(DISTINCT rp.external_id)::int AS rate_plans,
             COUNT(DISTINCT sp.external_id)::int AS properties
        FROM gas_sync_rate_plans rp
        JOIN gas_sync_room_types rt ON rt.id = rp.sync_room_type_id
        JOIN gas_sync_properties sp ON sp.id = rt.sync_property_id
        JOIN gas_sync_connections c ON c.id = sp.connection_id
        JOIN bookable_units bu ON bu.id = rt.gas_room_id
       WHERE bu.property_id = $1
         AND c.adapter_code = 'channex'
         AND c.status = 'connected'
         AND rp.external_id IS NOT NULL
    `, [propertyId]);
    const channex = {
      connected: (channexR.rows[0]?.rate_plans || 0) > 0,
      rate_plans: channexR.rows[0]?.rate_plans || 0,
      properties: channexR.rows[0]?.properties || 0,
    };

    res.json({
      success: true,
      property: propR.rows[0],
      cms: { hostfully, channex }
    });
  } catch (e) {
    console.error('[booking-rules GET]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// PUT — saves GAS rules and fires the Hostfully push in the same request
// (awaited so the operator sees success/failure immediately in the modal).
// Push failure does NOT roll back the DB save — GAS-side enforcement is
// the important half; the CM push aligns as a follow-up. Error surfaces
// via standard_rules_push_error for the next modal open.
app.put('/api/admin/properties/:id/booking-rules', async (req, res) => {
  try {
    const propertyId = parseInt(req.params.id, 10);
    const {
      standard_check_in_days,
      standard_check_out_days,
      standard_min_stay,
      standard_max_stay,
      standard_lead_hours,
      push_to_hostfully  // default true — modal sets false if operator wants GAS-only
    } = req.body || {};

    const normDays = (v) => {
      if (!Array.isArray(v) || v.length === 0 || v.length === 7) return null;
      const upper = ['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'];
      const filtered = v.map(d => String(d).toUpperCase()).filter(d => upper.includes(d));
      return filtered.length === 0 ? null : filtered;
    };
    const normInt = (v) => {
      const n = parseInt(v, 10);
      return Number.isFinite(n) && n > 0 ? n : null;
    };

    const checkInDays = normDays(standard_check_in_days);
    const checkOutDays = normDays(standard_check_out_days);
    const minStay = normInt(standard_min_stay);
    const maxStay = normInt(standard_max_stay);
    const leadHours = normInt(standard_lead_hours);

    await pool.query(`
      UPDATE properties
         SET standard_check_in_days = $1::jsonb,
             standard_check_out_days = $2::jsonb,
             standard_min_stay = $3,
             standard_max_stay = $4,
             standard_lead_hours = $5,
             updated_at = NOW()
       WHERE id = $6
    `, [
      checkInDays ? JSON.stringify(checkInDays) : null,
      checkOutDays ? JSON.stringify(checkOutDays) : null,
      minStay, maxStay, leadHours, propertyId
    ]);

    let hostfullyResult = null;
    if (push_to_hostfully !== false) {
      hostfullyResult = await pushBookingRulesToHostfully(propertyId);
    }
    // Channex writeback — GAS is the PMS so we always push, no pull needed.
    // Idempotent + safely skipped when no Channex mapping exists.
    const channexResult = await pushBookingRulesToChannex(propertyId);

    res.json({ success: true, hostfully: hostfullyResult, channex: channexResult });
  } catch (e) {
    console.error('[booking-rules PUT]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

