// UPDATE property
app.put('/api/db/properties/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const {
      name, description, address, city, country, property_type, status,
      district, state, zip_code, latitude, longitude, account_id, currency,
      display_name, show_on_portfolio, portfolio_display,
      standard_rate_name, standard_rate_description, standard_rate_features,
      same_day_cutoff_time, min_advance_hours,
      // 2026-08-04 — property-level phone + timezone. Needed by the
      // GAS→Channex content push so Google Hotel Search accepts the
      // property (both are required Channex fields for that channel).
      phone, timezone,
      // Hotel policy inputs + facilities (all pushed to Channex).
      check_in_time, check_out_time, house_rules, facilities
    } = req.body;

    // If only account_id provided, do simple update
    if (account_id && Object.keys(req.body).length === 1) {
      const result = await pool.query(
        'UPDATE properties SET account_id = $1, updated_at = NOW() WHERE id = $2 RETURNING *',
        [account_id, id]
      );
      return res.json({ success: true, data: result.rows[0] });
    }

    // If only show_on_portfolio provided, do simple update
    if (show_on_portfolio !== undefined && Object.keys(req.body).length === 1) {
      try {
        const result = await pool.query(
          'UPDATE properties SET show_on_portfolio = $1, updated_at = NOW() WHERE id = $2 RETURNING *',
          [show_on_portfolio, id]
        );
        return res.json({ success: true, data: result.rows[0] });
      } catch (colErr) {
        if (colErr.message && colErr.message.includes('does not exist')) {
          return res.json({ success: true, data: { id }, message: 'Column not yet migrated' });
        }
        throw colErr;
      }
    }

    // description + house_rules columns are JSONB (multi-language shape).
    // The edit modal exposes a plain-text textarea so convert to
    // {"en": "..."} before saving. Empty/undefined skips the update.
    const descJson = (description !== undefined && description !== null)
      ? (typeof description === 'string' ? JSON.stringify({ en: description }) : JSON.stringify(description))
      : null;
    const houseRulesJson = (house_rules !== undefined && house_rules !== null)
      ? (typeof house_rules === 'string' ? JSON.stringify({ en: house_rules }) : JSON.stringify(house_rules))
      : null;

    let result;
    try {
      result = await pool.query(
        `UPDATE properties SET
          name = COALESCE($1, name),
          description = COALESCE($2::jsonb, description),
          address = COALESCE($3, address), 
          city = COALESCE($4, city), 
          country = COALESCE($5, country), 
          property_type = COALESCE($6, property_type),
          status = COALESCE($7, status),
          state = COALESCE($8, state),
          latitude = COALESCE($9, latitude),
          longitude = COALESCE($10, longitude),
          account_id = COALESCE($11, account_id),
          currency = COALESCE($12, currency),
          district = COALESCE($13, district),
          zip_code = COALESCE($14, zip_code),
          display_name = $15,
          show_on_portfolio = COALESCE($16, show_on_portfolio),
          portfolio_display = COALESCE($17::jsonb, portfolio_display),
          standard_rate_name = COALESCE($18, standard_rate_name),
          standard_rate_description = COALESCE($19, standard_rate_description),
          standard_rate_features = COALESCE($20::jsonb, standard_rate_features),
          same_day_cutoff_time = CASE WHEN $24::bool THEN $22::time ELSE same_day_cutoff_time END,
          min_advance_hours    = CASE WHEN $25::bool THEN $23::integer ELSE min_advance_hours END,
          phone           = COALESCE($26, phone),
          timezone        = COALESCE($27, timezone),
          check_in_time   = COALESCE($28, check_in_time),
          check_out_time  = COALESCE($29, check_out_time),
          house_rules     = COALESCE($30::jsonb, house_rules),
          facilities      = COALESCE($31::jsonb, facilities),
          updated_at = NOW()
        WHERE id = $21
        RETURNING *`,
        [name, descJson, address, city, country, property_type, status,
         state, latitude, longitude, account_id, currency, district, zip_code,
         display_name || null, show_on_portfolio,
         portfolio_display ? JSON.stringify(portfolio_display) : null,
         standard_rate_name ?? null,
         standard_rate_description ?? null,
         standard_rate_features !== undefined ? JSON.stringify(standard_rate_features) : null,
         id,
         // Cutoffs — the CASE flags let a caller that doesn't send the
         // field leave the existing DB value alone (a plain COALESCE
         // wouldn't let us clear back to NULL). Callers that DO send
         // either a value or explicit null both update the column.
         (same_day_cutoff_time && String(same_day_cutoff_time).trim()) || null,
         (min_advance_hours === null || min_advance_hours === '' || min_advance_hours === undefined) ? null : (parseInt(min_advance_hours, 10) || null),
         req.body.hasOwnProperty('same_day_cutoff_time'),
         req.body.hasOwnProperty('min_advance_hours'),
         phone !== undefined ? (phone && String(phone).trim() ? String(phone).trim() : null) : null,
         timezone !== undefined ? (timezone && String(timezone).trim() ? String(timezone).trim() : null) : null,
         check_in_time !== undefined ? (check_in_time || null) : null,
         check_out_time !== undefined ? (check_out_time || null) : null,
         houseRulesJson,
         facilities !== undefined ? JSON.stringify(Array.isArray(facilities) ? facilities : []) : null]
      );
    } catch (queryErr) {
      // Fallback if new columns don't exist yet (pre-migration)
      if (queryErr.message && queryErr.message.includes('does not exist')) {
        console.log('Falling back to base property update (new columns not yet migrated)');
        result = await pool.query(
          `UPDATE properties SET 
            name = COALESCE($1, name), 
            description = COALESCE($2, description), 
            address = COALESCE($3, address), 
            city = COALESCE($4, city), 
            country = COALESCE($5, country), 
            property_type = COALESCE($6, property_type),
            status = COALESCE($7, status),
            state = COALESCE($8, state),
            latitude = COALESCE($9, latitude),
            longitude = COALESCE($10, longitude),
            account_id = COALESCE($11, account_id),
            currency = COALESCE($12, currency),
            district = COALESCE($13, district),
            zip_code = COALESCE($14, zip_code),
            display_name = $15,
            updated_at = NOW()
          WHERE id = $16
          RETURNING *`,
          [name, description, address, city, country, property_type, status,
           state, latitude, longitude, account_id, currency, district, zip_code,
           display_name || null, id]
        );
      } else {
        throw queryErr;
      }
    }

    // If the operator changed cutoffs, fire the Channex close-out for this
    // property immediately — don't make them wait up to an hour for the
    // scheduled sweep. Same helper as the hourly cron, just scoped to one
    // property so it's cheap. Fire-and-forget: the response goes back
    // straight away, close-out runs in the background.
    if (req.body.hasOwnProperty('same_day_cutoff_time') || req.body.hasOwnProperty('min_advance_hours')) {
      runBookingCutoffCloseOutForProperty(id).catch(err => {
        console.warn(`[property-cutoff-save] close-out for property ${id} failed:`, err && err.message);
      });
    }

    // Auto-push property content to Channex — GAS is the source of truth,
    // Channex is the mirror. Only fires when a content field was actually
    // in the request (avoids pointless pushes on non-content saves like
    // owner-linking / show-on-portfolio toggle). Fire-and-forget so the
    // save response isn't held up by Channex API latency. Steve 2026-08-04
    // — replaces the manual "Push content to Channex" button for the
    // common case; the button stays for on-demand re-sync.
    const _contentFields = ['description', 'phone', 'timezone', 'check_in_time', 'check_out_time', 'house_rules', 'facilities', 'name', 'address', 'city', 'country', 'zip_code'];
    if (_contentFields.some(k => req.body.hasOwnProperty(k))) {
      setImmediate(() => autoPushPropertyContentIfChannexConnected(id).catch(err => {
        console.warn(`[property-save channex auto-push] property ${id} failed:`, err && err.message);
      }));
    }

    res.json({ success: true, data: result.rows[0] });
  } catch (error) {
    console.error('Update error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Manual trigger — POST /api/admin/properties/:id/push-cutoffs-to-channex
// so operators can force-run the close-out for a single property without
// waiting for the hourly cron. Also used by the property save path above.
app.post('/api/admin/properties/:id/push-cutoffs-to-channex', async (req, res) => {
  try {
    const result = await runBookingCutoffCloseOutForProperty(req.params.id);
    res.json({ success: true, ...result });
  } catch (e) {
    console.error('[push-cutoffs-to-channex]', e);
    res.json({ success: false, error: e.message });
  }
});

