// Copy images from gas_sync_images to room_images for a GAS property
app.post('/api/admin/properties/:propertyId/copy-sync-images', async (req, res) => {
  try {
    const { propertyId } = req.params;
    
    // Get all rooms for this property
    const roomsResult = await pool.query(`
      SELECT id, name, beds24_room_id FROM bookable_units WHERE property_id = $1
    `, [propertyId]);
    
    if (roomsResult.rows.length === 0) {
      return res.json({ success: false, error: 'No rooms found for this property' });
    }
    
    // Optional: clear existing room_images first (for re-import through R2)
    const { clearFirst } = req.body || {};
    if (clearFirst) {
      const roomIds = roomsResult.rows.map(r => r.id);
      const delResult = await pool.query('DELETE FROM room_images WHERE room_id = ANY($1)', [roomIds]);
      console.log(`[Copy Sync Images] Cleared ${delResult.rowCount} existing room_images for property ${propertyId}`);
    }
    
    let totalCopied = 0;
    let totalSkipped = 0;
    const roomResults = [];
    
    for (const room of roomsResult.rows) {
      // Find images in gas_sync_images matching this room's beds24_room_id
      // Also include property-level images (room_type_external_id IS NULL) that haven't been assigned
      const syncPropertyId = await pool.query(
        `SELECT sp.id FROM gas_sync_properties sp WHERE sp.gas_property_id = $1 LIMIT 1`, [propertyId]
      );
      const spId = syncPropertyId.rows[0]?.id;
      
      const syncImages = await pool.query(`
        SELECT * FROM gas_sync_images 
        WHERE (room_type_external_id = $1 
               OR (room_type_external_id IS NULL AND sync_property_id = $2))
        ORDER BY sort_order
      `, [String(room.beds24_room_id), spId]);
      
      let copied = 0;
      let skipped = 0;
      
      for (const img of syncImages.rows) {
        // Check if already exists
        const existing = await pool.query(`
          SELECT id FROM room_images WHERE room_id = $1 AND (image_url = $2 OR image_key = $3)
        `, [room.id, img.original_url, img.external_id || `beds24-${room.beds24_room_id}-${img.sort_order || 0}`]);
        
        if (existing.rows.length > 0) {
          skipped++;
          continue;
        }
        
        // Try to download, compress via Sharp, and upload to R2
        let imageUrl = img.original_url;
        let thumbnailUrl = img.thumbnail_url || img.original_url;
        let imageKey = img.external_id || `beds24-${room.beds24_room_id}-${img.sort_order || 0}`;
        
        try {
          const imgResponse = await axios.get(img.original_url, { 
            responseType: 'arraybuffer', 
            timeout: 30000,
            maxContentLength: 100 * 1024 * 1024
          });
          const buffer = Buffer.from(imgResponse.data);
          const originalSizeKB = (buffer.length / 1024).toFixed(0);
          
          const urlPath = new URL(img.original_url).pathname;
          const filename = path.basename(urlPath) || `beds24-${room.beds24_room_id}-${img.sort_order || 0}.jpg`;
          
          const r2Result = await processAndUploadImage(buffer, 'room', room.id, filename);
          
          imageUrl = r2Result.large || r2Result.original;
          thumbnailUrl = r2Result.thumbnail || r2Result.medium || imageUrl;
          imageKey = r2Result.imageKey || imageKey;
          
          console.log(`[Copy Sync Images] Room ${room.id}: compressed ${originalSizeKB}KB -> R2`);
        } catch (dlErr) {
          console.warn(`[Copy Sync Images] Room ${room.id}: using original URL: ${dlErr.message}`);
        }
        
        // Insert
        await pool.query(`
          INSERT INTO room_images (room_id, image_key, image_url, thumbnail_url, caption, display_order, upload_source, is_active, is_primary, created_at)
          VALUES ($1, $2, $3, $4, $5, $6, 'beds24_sync', true, $7, NOW())
        `, [
          room.id,
          imageKey,
          imageUrl,
          thumbnailUrl,
          img.caption || '',
          img.sort_order || 0,
          img.sort_order === 0
        ]);
        copied++;
      }
      
      totalCopied += copied;
      totalSkipped += skipped;
      roomResults.push({ roomId: room.id, name: room.name, copied, skipped, syncImagesFound: syncImages.rows.length });
    }
    
    res.json({ success: true, totalCopied, totalSkipped, rooms: roomResults });
  } catch (error) {
    console.error('Copy sync images error:', error);
    res.json({ success: false, error: error.message });
  }
});

