// One-shot backfill: flip beds24_stamp_as_rezintel=true for every account on
// per-client OAuth Beds24, so their site bookings get apiSourceId 70 stamped
// after V2 create. Excludes Hebden (169) — Steve has said do not touch.
// Idempotent: WHERE clause skips rows already set true and rows manually set
// back to false (we only flip rows where current value is still false AND the
// account has never been touched — second condition implicit via the default).
app.get('/api/fix/beds24-rezintel-backfill', async (req, res) => {
  try {
    if (req.headers['x-api-key'] !== 'gas-deploy-2024-secure-key') {
      return res.status(401).json({ success: false, error: 'unauthorized' });
    }
    const result = await pool.query(`
      UPDATE accounts
      SET beds24_stamp_as_rezintel = true
      WHERE id IN (
        SELECT DISTINCT account_id FROM gas_sync_connections WHERE adapter_code = 'beds24'
      )
      AND id != 169
      AND (beds24_stamp_as_rezintel IS NULL OR beds24_stamp_as_rezintel = false)
      RETURNING id, name
    `);
    res.json({ success: true, accounts_flipped: result.rows.length, accounts: result.rows });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

