// Get all offers
app.get('/api/admin/offers', async (req, res) => {
  try {
    const { account_id } = req.query;

    let query = `
      SELECT o.*, p.name as property_name, bu.name as room_name
      FROM offers o
      LEFT JOIN properties p ON o.property_id = p.id
      LEFT JOIN bookable_units bu ON o.room_id = bu.id
    `;
    const params = [];

    // Filter by account_id if provided
    if (account_id) {
      query += ` WHERE o.account_id = $1`;
      params.push(account_id);
    }

    query += ` ORDER BY o.priority DESC, o.created_at DESC`;

    const result = await pool.query(query, params);
    res.json({ success: true, data: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Applicable offers for a specific room+dates+guest count — powers the
// Rate/Offer picker in the admin Add Booking modal. Returns Standard Rate
// as the first entry, then every offer whose conditions pass. Each entry
// carries a computed_price (what to auto-fill into booking-total) plus a
// computed_discount (delta vs standard) for the UI.
//
// Filters mirror the offers-modal condition set (scope, min/max nights,
// min/max guests, valid_from/until, min/max advance days, allowed_checkin_days
// bitmap, active, available_agents) — a superset of the older
// POST /api/pricing/calculate filter which the public booking flow uses.
app.get('/api/admin/offers/applicable', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });

    const roomId   = parseInt(req.query.room_id, 10);
    const checkIn  = String(req.query.check_in || '');
    const checkOut = String(req.query.check_out || '');
    const adults   = Math.max(1, parseInt(req.query.adults || '1', 10));
    const children = Math.max(0, parseInt(req.query.children || '0', 10));
    if (!roomId || !checkIn || !checkOut) {
      return res.json({ success: false, error: 'room_id, check_in, check_out required' });
    }

    // Resolve room → property → account, scope-check unless master admin.
    const rp = await pool.query(
      `SELECT bu.id AS room_id, bu.property_id, p.account_id
         FROM bookable_units bu
         JOIN properties p ON p.id = bu.property_id
        WHERE bu.id = $1`,
      [roomId]
    );
    if (!rp.rows[0]) return res.status(404).json({ success: false, error: 'Room not found' });
    const { property_id: propertyId, account_id: accountId } = rp.rows[0];
    const isMaster = decoded.role === 'master_admin';
    if (!isMaster && accountId !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    // Base pricing per day — same query the public pricing endpoint uses.
    const avail = await pool.query(
      `SELECT date, cm_price, standard_price
         FROM room_availability
        WHERE room_id = $1 AND date >= $2::date AND date < $3::date
        ORDER BY date`,
      [roomId, checkIn, checkOut]
    );
    const nights = avail.rows.length;
    if (nights === 0) return res.json({ success: false, error: 'No availability rows for that range' });

    let standardTotal = 0;
    for (const d of avail.rows) {
      const std = parseFloat(d.standard_price) || parseFloat(d.cm_price) || 0;
      standardTotal += std;
    }
    standardTotal = Math.round(standardTotal * 100) / 100;

    // Advance-days check — how many days from now to check-in.
    const todayMs = new Date().setHours(0,0,0,0);
    const arrivalMs = new Date(checkIn + 'T00:00:00Z').getTime();
    const advanceDays = Math.max(0, Math.round((arrivalMs - todayMs) / 86400000));

    // Day-of-week of check-in / (last night's) checkout — for bitmap gating.
    const dow = (dStr) => new Date(dStr + 'T00:00:00Z').getUTCDay(); // 0=Sun
    const inDow  = String(dow(checkIn));
    const outDow = String(dow(checkOut));

    // Currency — from the property (best-effort).
    const propCur = await pool.query('SELECT currency FROM properties WHERE id = $1', [propertyId]);
    const currency = (propCur.rows[0]?.currency || 'GBP').toUpperCase();

    // Fetch all candidate offers — WHERE clause matches the offers list
    // (property_id array or single, room_id array or single). Do the fine
    // filtering (day-of-week bitmap, advance window) in JS since the CSV
    // bitmap doesn't index cleanly in SQL.
    const rows = await pool.query(
      `SELECT * FROM offers
        WHERE active = true
          AND account_id = $1
          AND ( property_id IS NULL OR property_id = $2
                OR (property_ids IS NOT NULL AND $2 = ANY(property_ids)) )
          AND ( room_id IS NULL OR room_id = $3
                OR (room_ids IS NOT NULL AND $3 = ANY(room_ids)) )
          AND (min_nights IS NULL OR min_nights <= $4)
          AND (max_nights IS NULL OR max_nights >= $4)
          AND (min_guests IS NULL OR min_guests <= $5)
          AND (max_guests IS NULL OR max_guests >= $5)
          AND (valid_from IS NULL OR valid_from <= $6::date)
          AND (valid_until IS NULL OR valid_until >= $7::date)
          AND (min_advance_days IS NULL OR min_advance_days <= $8)
          AND (max_advance_days IS NULL OR max_advance_days >= $8)
        ORDER BY priority DESC, id`,
      [accountId, propertyId, roomId, nights, adults + children, checkIn, checkOut, advanceDays]
    );

    // JS-side gates + price compute.
    const applicable = [];
    for (const o of rows.rows) {
      // Day-of-week bitmap gates (CSV like '0,1,2,3,4,5,6')
      const inDays  = (o.allowed_checkin_days  || '0,1,2,3,4,5,6').split(',').map(s => s.trim());
      const outDays = (o.allowed_checkout_days || '0,1,2,3,4,5,6').split(',').map(s => s.trim());
      if (!inDays.includes(inDow) || !outDays.includes(outDow)) continue;

      // Extras — per-adult (over base_occupancy) + per-child, per night.
      const baseOcc = parseInt(o.base_occupancy, 10) || 0;
      const extraAdultN = baseOcc > 0 ? Math.max(0, adults - baseOcc) : 0;
      const extraAdultTotal = extraAdultN * (parseFloat(o.extra_person_amount) || 0) * nights;
      const extraChildTotal = children * (parseFloat(o.extra_child_amount) || 0) * nights;
      const extrasTotal = Math.round((extraAdultTotal + extraChildTotal) * 100) / 100;

      let baseCharge;
      if (o.replaces_standard && o.price_per_night != null) {
        // Flat rate — ignore standardTotal, use price_per_night × nights.
        baseCharge = (parseFloat(o.price_per_night) || 0) * nights;
      } else if (o.discount_type === 'percentage') {
        const pct = parseFloat(o.discount_value) || 0;
        baseCharge = standardTotal * (1 - pct / 100);
      } else if (o.discount_type === 'fixed_amount') {
        baseCharge = Math.max(0, standardTotal - (parseFloat(o.discount_value) || 0));
      } else {
        baseCharge = standardTotal;
      }
      baseCharge = Math.round(baseCharge * 100) / 100;

      const computed_price = Math.round((baseCharge + extrasTotal) * 100) / 100;
      const computed_discount = Math.round((standardTotal + extrasTotal - computed_price) * 100) / 100;

      applicable.push({
        id: o.id,
        name: o.name,
        description: o.description,
        discount_type: o.discount_type,
        discount_value: o.discount_value != null ? Number(o.discount_value) : null,
        price_per_night: o.price_per_night != null ? Number(o.price_per_night) : null,
        replaces_standard: !!o.replaces_standard,
        priority: o.priority,
        computed_price,
        computed_discount,
        extras_total: extrasTotal
      });
    }

    // Standard rate goes first — always available as the default option.
    const standardExtras = 0; // base rate extras handled by the room's own pricing
    const standard = {
      id: null,
      name: 'Standard rate',
      description: null,
      discount_type: null,
      discount_value: null,
      price_per_night: null,
      replaces_standard: false,
      priority: 9999,
      computed_price: standardTotal,
      computed_discount: 0,
      extras_total: standardExtras
    };

    res.json({
      success: true,
      currency,
      nights,
      standard_total: standardTotal,
      offers: [standard, ...applicable]
    });
  } catch (error) {
    console.error('offers/applicable error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

