// Toggle a single offer's website visibility. Lightweight PATCH so the
// Offers list eye-icon doesn't have to round-trip the full PUT payload
// (which would re-serialize daily_prices etc.). Used by the "Show on
// site" toggle next to each offer name.
app.patch('/api/admin/offers/:id/website-visibility', async (req, res) => {
  try {
    const visible = req.body?.visible;
    if (typeof visible !== 'boolean') {
      return res.status(400).json({ success: false, error: 'visible (boolean) required' });
    }
    const r = await pool.query(
      `UPDATE offers SET available_website = $1, updated_at = NOW()
       WHERE id = $2 RETURNING id, available_website, account_id`,
      [visible, req.params.id]
    );
    if (r.rowCount === 0) return res.status(404).json({ success: false, error: 'Offer not found' });
    // Fire-and-forget WP Super Cache flush for every live site under
    // this account so visibility change reflects on the next page
    // load — without this, the widget keeps reading the cached HTML's
    // baked-in script ?ver= and serves stale offers indefinitely.
    const accountId = r.rows[0]?.account_id;
    if (accountId) {
      pool.query(
        `SELECT site_url FROM deployed_sites WHERE account_id = $1 AND site_status = 'live'`,
        [accountId]
      ).then(sites => {
        for (const s of (sites.rows || [])) {
          if (!s.site_url) continue;
          fetch('https://sites.gas.travel/gas-api.php', {
            method: 'POST',
            headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'flush_page_cache', site_url: s.site_url, paths: [''] })
          }).catch(e => console.log(`[offer-visibility] cache flush ${s.site_url}:`, e.message));
        }
      }).catch(() => {});
    }
    res.json({ success: true, data: r.rows[0] });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Get all vouchers
app.get('/api/admin/vouchers', async (req, res) => {
  try {
    const accountId = req.query.account_id;
    const propertyId = req.query.property_id;
    let result;
    
    if (propertyId) {
      // Defensive: the requested property MUST belong to the requesting account.
      // Without this gate, an authenticated caller could enumerate other accounts'
      // vouchers by guessing sequential property IDs.
      if (!accountId) {
        return res.json({ success: false, error: 'account_id required when filtering by property_id' });
      }
      // Three match arms:
      //   1. legacy v.property_id column matches
      //   2. property_ids[] contains the property
      //   3. wildcard — voucher belongs to the account and has no property
      //      scope at all (applies to every property on the account)
      // Without arm 3 the per-property list view hides "All Properties"-
      // scoped vouchers from the operator, even though they apply at
      // checkout. See voucherMatchesScope (server.js:250).
      result = await pool.query(`
        SELECT v.*, vn.name as vendor_name FROM vouchers v
        LEFT JOIN vendors vn ON v.vendor_id = vn.id
        WHERE (
            v.property_id = $1
            OR $1 = ANY(v.property_ids)
            OR (
              v.account_id = $2
              AND v.property_id IS NULL
              AND COALESCE(array_length(v.property_ids, 1), 0) = 0
            )
          )
          AND $1 IN (SELECT id FROM properties WHERE account_id = $2)
        ORDER BY v.created_at DESC
      `, [propertyId, accountId]);
    } else if (accountId) {
      // Three arms (any match):
      //   1. account_id column matches directly — the canonical scope as of 2026-05-25
      //   2. legacy property_id column points at a property owned by this account
      //   3. property_ids[] contains a property owned by this account
      // Without arm 1, vouchers created with "all properties" (property_ids=NULL)
      // were invisible to account-filtered lists — they existed but the user
      // thought creation had failed.
      result = await pool.query(`
        SELECT DISTINCT v.*, vn.name as vendor_name FROM vouchers v
        LEFT JOIN properties p ON v.property_id = p.id
        LEFT JOIN vendors vn ON v.vendor_id = vn.id
        WHERE v.account_id = $1
           OR p.account_id = $1
           OR EXISTS (
             SELECT 1 FROM properties p2
             WHERE p2.id = ANY(v.property_ids) AND p2.account_id = $1
           )
        ORDER BY v.created_at DESC
      `, [accountId]);
    } else {
      result = await pool.query(`
        SELECT v.*, vn.name as vendor_name FROM vouchers v
        LEFT JOIN vendors vn ON v.vendor_id = vn.id
        ORDER BY v.created_at DESC
      `);
    }
    res.json({ success: true, data: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

