// =====================================================
// TAXES API (Tourist/City Taxes)
// =====================================================

app.get('/api/admin/taxes', async (req, res) => {
  try {
    const accountId = req.query.account_id;
    const propertyId = req.query.property_id;
    const roomId = req.query.room_id;
    let result;
    
    if (propertyId) {
      // Defensive: the requested property MUST belong to the requesting account.
      // Without this gate, an authenticated caller could enumerate other accounts'
      // taxes by guessing sequential property IDs.
      if (!accountId) {
        return res.json({ success: false, error: 'account_id required when filtering by property_id' });
      }
      // Three things should show in the per-property view:
      //  1) property-scoped taxes (property_id = X)
      //  2) multi-property scoped taxes (property_ids contains X)
      //  3) account-wide taxes (no property_id + no property_ids + same user_id)
      // The old query missed (3) so a tax saved with "All properties" was invisible.
      result = await pool.query(`
        SELECT t.*, p.name as property_name
        FROM taxes t
        LEFT JOIN properties p ON t.property_id = p.id
        WHERE (
            t.property_id = $1
            OR $1 = ANY(t.property_ids)
            OR (t.property_id IS NULL
                AND (t.property_ids IS NULL OR cardinality(t.property_ids) = 0)
                AND t.user_id = $2)
          )
          AND $1 IN (SELECT id FROM properties WHERE account_id = $2)
        ORDER BY t.name
      `, [propertyId, accountId]);
    } else if (accountId) {
      // Show taxes that:
      // 1. Have user_id matching this account, OR
      // 2. Are linked to properties owned by this account
      result = await pool.query(`
        SELECT DISTINCT t.*, p.name as property_name 
        FROM taxes t
        LEFT JOIN properties p ON t.property_id = p.id
        WHERE t.user_id = $1 
           OR p.account_id = $1
        ORDER BY t.name
      `, [accountId]);
    } else {
      result = await pool.query(`
        SELECT t.*, p.name as property_name 
        FROM taxes t
        LEFT JOIN properties p ON t.property_id = p.id
        ORDER BY t.name
      `);
    }
    res.json({ success: true, data: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

