// Property Marketplace interest capture — the marketplace isn't live yet
// so the dashboard card + sub-links intercept clicks with a "Coming Soon"
// modal that pipes through here when the client says "yes I'm interested".
// Fires a master notification so Steve knows to reach out; also stamps a
// boolean flag on the accounts row so a follow-up dashboard can show
// the interest list. Idempotent — repeat clicks are fine, notification
// only fires the first time per session (client-side confirm gate).
app.post('/api/admin/marketplace-interest', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const accountId = decoded.accountId || decoded.id;
    if (!accountId) return res.status(400).json({ success: false, error: 'No account context' });
    // Best-effort column add — the migration runs once, subsequent calls no-op.
    try {
      await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS marketplace_interest BOOLEAN DEFAULT false`);
      await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS marketplace_interest_at TIMESTAMP`);
    } catch (_) { /* silent */ }
    const already = await pool.query(`SELECT name, marketplace_interest FROM accounts WHERE id = $1`, [accountId]);
    if (!already.rows.length) return res.status(404).json({ success: false, error: 'Account not found' });
    const wasAlready = !!already.rows[0].marketplace_interest;
    const accName = already.rows[0].name || `Account ${accountId}`;
    await pool.query(
      `UPDATE accounts SET marketplace_interest = true, marketplace_interest_at = COALESCE(marketplace_interest_at, NOW()) WHERE id = $1`,
      [accountId]
    );
    if (!wasAlready && typeof sendMasterNotification === 'function') {
      try {
        await sendMasterNotification({
          title: 'Property Marketplace interest',
          body: `${accName} (account ${accountId}) registered interest in Property Marketplace via the dashboard card.`,
          severity: 'info',
          metadata: { account_id: accountId, feature: 'marketplace' }
        });
      } catch (_) { /* non-blocking */ }
    }
    res.json({ success: true, already: wasAlready });
  } catch (e) {
    console.error('[marketplace-interest]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

