// Cancel booking
app.post('/api/bookings/:id/cancel', async (req, res) => {
  const client = await pool.connect();
  try {
    const { id } = req.params;
    
    await client.query('BEGIN');
    
    // Get booking details. beds24_property_id pulled so the cancel push
    // below uses the org-token path that created the booking (apiSourceId
    // 70 / Rezintel) — auto-actions are tied to that stamp.
    const result = await client.query(`
      SELECT b.*, bu.beds24_room_id, bu.hostaway_listing_id, p.beds24_property_id
      FROM bookings b
      LEFT JOIN bookable_units bu ON b.bookable_unit_id = bu.id
      LEFT JOIN properties p ON b.property_id = p.id
      WHERE b.id = $1
    `, [id]);
    
    if (result.rows.length === 0) {
      await client.query('ROLLBACK');
      return res.json({ success: false, error: 'Booking not found' });
    }
    
    const booking = result.rows[0];
    
    // Update booking status + cancelled_time. cancelled_time is the
    // "GAS-cancelled lock" — the Beds24 sync UPSERT respects it and
    // skips status overwrite when set (see _processBeds24Booking ON
    // CONFLICT clause). Without this, a stale Beds24 sync row reverts
    // status back to 'pending' within seconds of the cancel committing.
    // DEBUG sentinel: cancellation_reason set to a known string so we can
    // verify deployed code is running this version (remove once confirmed).
    // Cancelled bookings owe nothing further — zero the balance so
    // the booking detail "Balance Due" line stops nagging the operator
    // and Auto Messages don't fire a balance-chase email on it.
    const updRes = await client.query(`
      UPDATE bookings
         SET status = 'cancelled',
             cancelled_time = NOW(),
             balance_amount = 0,
             balance_due = 0,
             cancellation_reason = 'GAS-CANCEL-V2-' || NOW()::text
       WHERE id = $1
       RETURNING id, status, cancelled_time
    `, [id]);
    console.log('[cancel]', id, 'UPDATE result:', updRes.rows[0]);

    // Free the booked dates. UPSERT to is_available=true so a stale 'beds24'
    // sync row (which overwrites source within minutes of booking creation)
    // doesn't leave the date wrongly blocked. The next Beds24 sync re-blocks
    // if Beds24 still considers the date taken for some other reason.
    // Uses arrival_date/departure_date (the real column names) — previous
    // version referenced check_in/check_out which don't exist on bookings.
    await client.query(`
      INSERT INTO room_availability (room_id, date, is_available, is_blocked, source, updated_at)
      SELECT $1, gs::date, true, false, 'cancelled', NOW()
        FROM generate_series($2::date, ($3::date - INTERVAL '1 day')::date, '1 day') gs
      ON CONFLICT (room_id, date) DO UPDATE
        SET is_available = true, is_blocked = false, source = 'cancelled', updated_at = NOW()
    `, [booking.bookable_unit_id, booking.arrival_date, booking.departure_date]);

    // Channex: re-open the booked dates on the channel manager so all
    // connected OTAs see the room available again. mirrorBookingToChannex
    // reads arrival_date/departure_date from the bookings row directly
    // (the previous inline code referenced booking.check_in / check_out
    // which don't exist on the bookings table — so cancellations have
    // been silently dropping the Channex push for everyone).
    await mirrorBookingToChannex(booking.id, 'cancelled');

    // Cancel in Beds24. Use the property-specific token resolver so we
    // talk to the right Beds24 account — previously this used the global
    // getBeds24AccessToken which always returned the first connection in
    // channel_connections (Lehmann's stale Dec-2025 token), causing 401
    // for every cancel on properties owned by other accounts.
    if (booking.beds24_booking_id) {
      try {
        const accessToken = await getBeds24AccessTokenForProperty(
          pool, booking.property_id, booking.bookable_unit_id
        );
        if (accessToken) {
          let cancelResponse = await axios.post('https://beds24.com/api/v2/bookings', [{
            id: parseInt(booking.beds24_booking_id),
            status: 'cancelled',
            allowWebhooks: true
          }], {
            headers: getBeds24BookingHeaders(booking.beds24_property_id, accessToken)
          });
          console.log('Beds24 cancellation response:', JSON.stringify(cancelResponse.data));

          // Per-room enrolment fallback — see /api/public/book and
          // DELETE /api/bookings/:id for the matching create/delete
          // logic. The Rezintel org-token can't modify rooms outside
          // its Marketplace whitelist; per-client OAuth can.
          const firstErr = cancelResponse.data?.[0]?.errors?.[0]?.message || '';
          if (!cancelResponse.data?.[0]?.success && /access denied|invalid roomid/i.test(firstErr)) {
            console.log('[Beds24 cancel] org-token rejected — retrying with per-client OAuth');
            try {
              cancelResponse = await axios.post('https://beds24.com/api/v2/bookings', [{
                id: parseInt(booking.beds24_booking_id),
                status: 'cancelled',
                allowWebhooks: true
              }], { headers: { 'Content-Type': 'application/json', token: accessToken } });
              console.log('[Beds24 cancel] fallback response:', JSON.stringify(cancelResponse.data));
            } catch (fbErr) {
              console.error('[Beds24 cancel] fallback error:', fbErr.response?.data || fbErr.message);
            }
          }

          // Buyout cascade cancel — release every block this master spawned
          // so the Beds24 calendar opens back up on all underlying rooms.
          // Per-client OAuth (the blocks were created with it).
          const blocks = Array.isArray(booking.buyout_block_beds24_ids)
            ? booking.buyout_block_beds24_ids
            : (typeof booking.buyout_block_beds24_ids === 'string'
                ? JSON.parse(booking.buyout_block_beds24_ids || '[]')
                : []);
          for (const block of blocks) {
            try {
              await axios.post('https://beds24.com/api/v2/bookings', [{
                id: parseInt(block.beds24_id),
                status: 'cancelled',
                allowWebhooks: false
              }], { headers: { 'Content-Type': 'application/json', token: accessToken } });
              console.log(`[Buyout cascade] cancelled block ${block.beds24_id} on room ${block.room_id}`);
            } catch (e) {
              console.warn(`[Buyout cascade] cancel error on ${block.beds24_id}:`, e.response?.data || e.message);
            }
          }
        } else {
          console.warn('[cancel] No Beds24 token resolved for property', booking.property_id, '— skipping Beds24 cancel');
        }
      } catch (err) {
        console.error('Beds24 cancel error:', err.response?.data || err.message);
      }
    }

    // Cancel in Hostaway
    if (booking.hostaway_reservation_id) {
      try {
        const hostawayToken = process.env.HOSTAWAY_API_KEY;
        if (hostawayToken) {
          await fetch(`https://api.hostaway.com/v1/reservations/${booking.hostaway_reservation_id}`, {
            method: 'PUT',
            headers: {
              'Authorization': `Bearer ${hostawayToken}`,
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ status: 'cancelled' })
          });
        }
      } catch (err) {
        console.error('Hostaway cancel error:', err);
      }
    }

    // ── Cascade: cancel any companion children. Companion bookings live on
    // their own bookable_units and have their own CM IDs, so each one needs
    // the same status/availability/CM-cancel treatment as the parent. We
    // do this BEFORE COMMIT so the whole cascade is atomic. Errors on a
    // single child are logged but don't abort — owner can retry manually
    // via the failed booking row. ──
    let cascadedChildren = [];
    try {
      const childrenResult = await client.query(`
        SELECT b.id, b.bookable_unit_id, b.arrival_date, b.departure_date,
               b.beds24_booking_id, b.hostaway_reservation_id, b.smoobu_booking_id,
               p.beds24_property_id
        FROM bookings b
        LEFT JOIN properties p ON b.property_id = p.id
        WHERE b.parent_booking_id = $1
          AND COALESCE(b.status, '') != 'cancelled'
      `, [id]);
      cascadedChildren = childrenResult.rows;

      for (const child of cascadedChildren) {
        try {
          await client.query(`UPDATE bookings SET status = 'cancelled', updated_at = NOW() WHERE id = $1`, [child.id]);

          // Free the child's dates with an UPSERT (same fix as the parent
          // cancel — DELETE-by-source misses rows after a Beds24 sync).
          await client.query(`
            INSERT INTO room_availability (room_id, date, is_available, is_blocked, source, updated_at)
            SELECT $1, gs::date, true, false, 'cancelled', NOW()
              FROM generate_series($2::date, ($3::date - INTERVAL '1 day')::date, '1 day') gs
            ON CONFLICT (room_id, date) DO UPDATE
              SET is_available = true, is_blocked = false, source = 'cancelled', updated_at = NOW()
          `, [child.bookable_unit_id, child.arrival_date, child.departure_date]);

          if (child.beds24_booking_id) {
            try {
              const accessToken = await getBeds24AccessToken(pool);
              if (accessToken) {
                await axios.post('https://beds24.com/api/v2/bookings', [{
                  id: parseInt(child.beds24_booking_id),
                  status: 'cancelled',
                  allowWebhooks: true
                }], { headers: getBeds24BookingHeaders(child.beds24_property_id, accessToken) });
                console.log(`[Cascade] Beds24 cancel sent for companion ${child.id} (beds24 id ${child.beds24_booking_id})`);
              }
            } catch (e) {
              console.error(`[Cascade] Beds24 cancel failed for companion ${child.id}:`, e.response?.data || e.message);
            }
          }

          if (child.hostaway_reservation_id) {
            try {
              const hostawayToken = process.env.HOSTAWAY_API_KEY;
              if (hostawayToken) {
                await fetch(`https://api.hostaway.com/v1/reservations/${child.hostaway_reservation_id}`, {
                  method: 'PUT',
                  headers: { 'Authorization': `Bearer ${hostawayToken}`, 'Content-Type': 'application/json' },
                  body: JSON.stringify({ status: 'cancelled' })
                });
                console.log(`[Cascade] Hostaway cancel sent for companion ${child.id}`);
              }
            } catch (e) {
              console.error(`[Cascade] Hostaway cancel failed for companion ${child.id}:`, e.message);
            }
          }

          if (child.smoobu_booking_id) {
            try {
              const smoobuKeyRes = await client.query(`
                SELECT cs.setting_value
                FROM bookings b
                JOIN bookable_units bu ON b.bookable_unit_id = bu.id
                JOIN properties p ON bu.property_id = p.id
                JOIN client_settings cs ON cs.client_id = p.account_id
                WHERE b.id = $1 AND cs.setting_key = 'smoobu_api_key'
                LIMIT 1
              `, [child.id]);
              const smoobuApiKey = smoobuKeyRes.rows[0]?.setting_value;
              if (smoobuApiKey) {
                await axios.delete(`https://login.smoobu.com/api/reservations/${child.smoobu_booking_id}`, {
                  headers: { 'Api-Key': smoobuApiKey }
                });
                console.log(`[Cascade] Smoobu cancel sent for companion ${child.id}`);
              }
            } catch (e) {
              console.error(`[Cascade] Smoobu cancel failed for companion ${child.id}:`, e.response?.data || e.message);
            }
          }
        } catch (childErr) {
          console.error(`[Cascade] Failed cancelling companion ${child.id}:`, childErr.message);
        }
      }
    } catch (cascadeErr) {
      console.error('[Cascade] Companion lookup failed (parent cancel preserved):', cascadeErr.message);
    }

    await client.query('COMMIT');

    // Belt-and-braces post-commit lock. The transaction above already set
    // status='cancelled' + cancelled_time, BUT we've observed cases where
    // either the transaction silently rolls back or a parallel Beds24
    // sync UPSERT reverts the row between COMMIT and now. Issue a second
    // independent UPDATE via the pool to guarantee the cancellation
    // lands and is visible to the next Beds24 sync's ON CONFLICT clause.
    try {
      await pool.query(
        `UPDATE bookings SET status = 'cancelled', cancelled_time = COALESCE(cancelled_time, NOW()) WHERE id = $1 AND status <> 'cancelled'`,
        [id]
      );
    } catch (lockErr) {
      console.error('[cancel] post-commit lock failed for', id, ':', lockErr.message);
    }

    // ========== SEND PARTNER CANCELLATION WEBHOOK ==========
    try {
      const webhookResult = await sendPartnerBookingWebhook(id, 'booking.cancelled');
      if (webhookResult.sent) {
        console.log(`[Webhook] Sent booking.cancelled for booking ${id}`);
      }
    } catch (webhookError) {
      console.error(`[Webhook] Error sending cancellation webhook for booking ${id}:`, webhookError.message);
      // Don't fail the cancellation if webhook fails
    }
    // Fire per-child cancellation webhooks too — partners track these as
    // first-class bookings (they got booking.created for each one in
    // Commit 4's submit path), so they need the matching cancelled event.
    for (const child of cascadedChildren) {
      try {
        const w = await sendPartnerBookingWebhook(child.id, 'booking.cancelled');
        if (w.sent) console.log(`[Webhook] Sent booking.cancelled for companion ${child.id}`);
      } catch (e) {
        console.error(`[Webhook] Companion ${child.id} cancelled webhook failed:`, e.message);
      }
    }
    // ========== END PARTNER WEBHOOK ==========

    // ========== WHATSAPP LIFECYCLE — booking cancelled ==========
    // Fire-and-forget. Pulls booking + property details for the template
    // params. No-op when account hasn't enabled lifecycle or template
    // name isn't set.
    try {
      const cancelledRow = (await pool.query(
        `SELECT b.*, p.name AS property_name, p.account_id
           FROM bookings b LEFT JOIN properties p ON p.id = b.property_id
          WHERE b.id = $1`, [id])).rows[0];
      if (cancelledRow) {
        sendBookingLifecycleWhatsApp(cancelledRow, 'cancelled')
          .then(r => {
            if (r?.success) console.log(`[whatsapp] cancellation sent for booking ${id}: ${r.messageId}`);
            else if (r?.skipped) console.log(`[whatsapp] cancellation skipped for booking ${id}: ${r.skipped}`);
            else console.warn(`[whatsapp] cancellation FAILED for booking ${id}: ${r?.error || 'unknown'}`);
          })
          .catch(e => console.error(`[whatsapp] cancellation threw for booking ${id}:`, e.message));
      }
    } catch (waErr) {
      console.error(`[whatsapp] cancellation wiring failure for booking ${id}:`, waErr.message);
    }
    // ========== END WHATSAPP ==========

    res.json({ success: true, message: 'Booking cancelled' });

  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Cancel booking error:', error);
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

// Validate voucher code (for booking widget)
app.post('/api/vouchers/validate', async (req, res) => {
  try {
    const { code, property_id, room_id, nights, total, guest_email } = req.body;
    
    const result = await pool.query(`
      SELECT * FROM vouchers
      WHERE code = $1 AND active = true
      AND (valid_from IS NULL OR valid_from <= CURRENT_DATE)
      AND (valid_until IS NULL OR valid_until >= CURRENT_DATE)
      AND (max_uses IS NULL OR uses_count < max_uses)
      ORDER BY id ASC
    `, [code.toUpperCase()]);

    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Invalid or expired voucher code' });
    }

    // Look up the booked property's account_id once — used by the scope
    // helper for every candidate row.
    let propertyAccountId = null;
    if (property_id) {
      const propRes = await pool.query('SELECT account_id FROM properties WHERE id = $1', [property_id]);
      propertyAccountId = propRes.rows[0]?.account_id || null;
    }

    // Pick the FIRST row whose scope matches the booking. Previously this
    // function used rows[0] unconditionally — when two vouchers shared a
    // code (e.g. one per property), the wrong row would be chosen and the
    // guest got "Voucher not valid for this property" even when another
    // row of the same code DID match. Steve hit this on VIP_TENOFF
    // 2026-05-21 (Atlas + Avocado).
    const voucher = result.rows.find(v => voucherMatchesScope(v, property_id, room_id, propertyAccountId));
    if (!voucher) {
      return res.json({ success: false, error: 'Voucher not valid for this property or room' });
    }

    // Check min nights
    if (voucher.min_nights && nights < voucher.min_nights) {
      return res.json({ success: false, error: `Minimum ${voucher.min_nights} nights required` });
    }

    // Check min total
    if (voucher.min_total && total < voucher.min_total) {
      return res.json({ success: false, error: `Minimum total of $${voucher.min_total} required` });
    }
    
    // Check single use per guest
    if (voucher.single_use_per_guest && guest_email) {
      const used = await pool.query(
        'SELECT id FROM voucher_uses WHERE voucher_id = $1 AND guest_email = $2',
        [voucher.id, guest_email]
      );
      if (used.rows.length > 0) {
        return res.json({ success: false, error: 'You have already used this voucher' });
      }
    }
    
    // Calculate discount
    let discount = 0;
    if (voucher.discount_type === 'percentage') {
      discount = total * (voucher.discount_value / 100);
    } else {
      discount = voucher.discount_value;
    }
    
    res.json({
      success: true,
      voucher: {
        id: voucher.id,
        code: voucher.code,
        name: voucher.name,
        discount_type: voucher.discount_type,
        discount_value: voucher.discount_value,
        discount_amount: Math.min(discount, total)
      }
    });
    
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Calculate price with offers (for booking widget)
app.post('/api/pricing/calculate', async (req, res) => {
  try {
    const { room_id, check_in, check_out, guests, voucher_code } = req.body;
    
    // Get room availability and base prices
    const availResult = await pool.query(`
      SELECT date, cm_price, standard_price, direct_price
      FROM room_availability
      WHERE room_id = $1 AND date >= $2 AND date < $3
      ORDER BY date
    `, [room_id, check_in, check_out]);
    
    const nights = availResult.rows.length;
    
    // Get the room's property_id AND account_id for offer filtering
    const roomPropertyResult = await pool.query(`
      SELECT bu.property_id, p.account_id, p.client_id 
      FROM bookable_units bu 
      LEFT JOIN properties p ON bu.property_id = p.id 
      WHERE bu.id = $1
    `, [room_id]);
    const roomPropertyId = roomPropertyResult.rows[0]?.property_id;
    const roomAccountId = roomPropertyResult.rows[0]?.account_id || roomPropertyResult.rows[0]?.client_id;
    
    // Get applicable offers - MUST match account_id to prevent cross-account bleeding
    const offersResult = await pool.query(`
      SELECT * FROM offers
      WHERE active = true
      AND account_id = $7
      AND (property_id IS NULL OR property_id = $6)
      AND (room_id IS NULL OR room_id = $1)
      AND (min_nights IS NULL OR min_nights <= $2)
      AND (max_nights IS NULL OR max_nights >= $2)
      AND (min_guests IS NULL OR min_guests <= $3)
      AND (max_guests IS NULL OR max_guests >= $3)
      AND (valid_from IS NULL OR valid_from <= $4)
      AND (valid_until IS NULL OR valid_until >= $5)
      ORDER BY priority DESC
    `, [room_id, nights, guests, check_in, check_out, roomPropertyId, roomAccountId]);
    
    // Calculate pricing
    let baseTotal = 0;
    let standardTotal = 0;
    const dailyPrices = [];
    
    for (const day of availResult.rows) {
      const refPrice = parseFloat(day.cm_price) || 0;
      const stdPrice = parseFloat(day.standard_price) || refPrice;
      baseTotal += refPrice;
      standardTotal += stdPrice;
      dailyPrices.push({
        date: day.date,
        reference_price: refPrice,
        standard_price: stdPrice
      });
    }
    
    // Apply best offer
    let offerDiscount = 0;
    let appliedOffer = null;
    
    for (const offer of offersResult.rows) {
      let discount = 0;
      if (offer.discount_type === 'percentage') {
        discount = standardTotal * (offer.discount_value / 100);
      } else {
        discount = offer.discount_value;
      }
      
      if (discount > offerDiscount) {
        offerDiscount = discount;
        appliedOffer = offer;
      }
    }
    
    let finalTotal = standardTotal - offerDiscount;
    
    // Apply voucher if provided
    let voucherDiscount = 0;
    let appliedVoucher = null;
    
    if (voucher_code) {
      const voucherResult = await pool.query(`
        SELECT * FROM vouchers 
        WHERE code = $1 AND active = true
        AND (valid_from IS NULL OR valid_from <= CURRENT_DATE)
        AND (valid_until IS NULL OR valid_until >= CURRENT_DATE)
      `, [voucher_code.toUpperCase()]);
      
      if (voucherResult.rows.length > 0) {
        const voucher = voucherResult.rows[0];
        if (voucher.discount_type === 'percentage') {
          voucherDiscount = finalTotal * (voucher.discount_value / 100);
        } else {
          voucherDiscount = voucher.discount_value;
        }
        appliedVoucher = voucher;
        finalTotal -= voucherDiscount;
      }
    }
    
    res.json({
      success: true,
      pricing: {
        nights,
        reference_total: baseTotal,
        standard_total: standardTotal,
        offer_discount: offerDiscount,
        applied_offer: appliedOffer ? { id: appliedOffer.id, name: appliedOffer.name } : null,
        voucher_discount: voucherDiscount,
        applied_voucher: appliedVoucher ? { id: appliedVoucher.id, code: appliedVoucher.code } : null,
        final_total: Math.max(0, finalTotal),
        daily_prices: dailyPrices
      }
    });
    
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

