// Update unit
app.put('/api/admin/units/:id', async (req, res) => {
  try {
    const { id } = req.params;
    console.log('PUT /api/admin/units/' + id, 'body:', JSON.stringify(req.body));
    
    const { quantity, status, room_type, max_guests, max_adults, max_children, display_name, short_description, full_description, repuso_widget_id, book_via_master_key, unit_role, external_booking_url, default_access_code, reference_code, show_reference, min_rate } = req.body;

    // Per-room minimum rate floor (Beds24-style). Nothing gets pushed to any
    // OTA below this. Feeds the Channex extender's floor guard + prevents
    // Expedia Warning 7021 (rate below verification threshold). NULL = no
    // operator-set floor; the global £15 (in extender) still applies. Empty
    // string clears; a valid number saves; undefined leaves the row alone.
    if (min_rate !== undefined) {
      const parsed = min_rate === '' || min_rate === null ? null : parseFloat(min_rate);
      if (parsed !== null && (isNaN(parsed) || parsed < 0)) {
        return res.status(400).json({ success: false, error: 'min_rate must be a non-negative number or blank' });
      }
      await pool.query('UPDATE bookable_units SET min_rate = $1 WHERE id = $2', [parsed, id]);
      // Propagate the new property-wide min to Channex's property.settings.
      // min_price (the field the Channex UI shows as minimum). Uses the MAX
      // across all rooms on this property. Fire-and-forget — save shouldn't
      // block on Channex; the drain loop is idempotent if this fails.
      try {
        const propR = await pool.query('SELECT property_id FROM bookable_units WHERE id = $1', [id]);
        const gasPropId = propR.rows[0]?.property_id;
        if (gasPropId) {
          const { pushChannexPropertyMinPrice } = require('./gas-sync/channex-outbox');
          setImmediate(() => pushChannexPropertyMinPrice(pool, gasPropId).catch(e => console.warn('[units min_rate → channex]', e.message)));
        }
      } catch (e) { console.warn('[units min_rate → channex trigger]', e.message); }
    }

    // Ensure repuso_widget_id column exists
    await pool.query('ALTER TABLE bookable_units ADD COLUMN IF NOT EXISTS repuso_widget_id VARCHAR(255)').catch(() => {});

    // External booking URL — set on the unit when the room's "Book Now" should
    // redirect to e.g. ResNexus, Airbnb, etc. instead of going through the
    // GAS checkout. Only update when explicitly sent.
    if (external_booking_url !== undefined) {
      const val = external_booking_url && String(external_booking_url).trim() ? String(external_booking_url).trim() : null;
      await pool.query('UPDATE bookable_units SET external_booking_url = $1 WHERE id = $2', [val, id]);
    }

    // Default access code (door / lockbox / safe) — Auto Messages templates
    // referencing {access_code} use this when a booking has no per-booking
    // override. Only update when explicitly sent so other save paths can't
    // accidentally wipe it.
    if (default_access_code !== undefined) {
      const val = default_access_code && String(default_access_code).trim() ? String(default_access_code).trim() : null;
      await pool.query('UPDATE bookable_units SET default_access_code = $1 WHERE id = $2', [val, id]);
    }

    // Operator-typed reference code + visibility toggle. Operators paste
    // their CM room id / postcode / internal SKU here — anything they
    // recognise. When show_reference is on the front page renders
    // "Ref: {code}" under the title. Only update when explicitly sent.
    if (reference_code !== undefined) {
      const val = reference_code && String(reference_code).trim() ? String(reference_code).trim() : null;
      await pool.query('UPDATE bookable_units SET reference_code = $1 WHERE id = $2', [val, id]);
    }
    if (show_reference !== undefined) {
      await pool.query('UPDATE bookable_units SET show_reference = $1 WHERE id = $2', [!!show_reference, id]);
    }

    // Master-admin-only toggle: route booking writes via V1 channel-partner
    // master key for this room. Only applied when payload explicitly includes
    // the field (so non-master save paths can't clobber it).
    if (book_via_master_key !== undefined) {
      await pool.query('UPDATE bookable_units SET book_via_master_key = $1 WHERE id = $2', [!!book_via_master_key, id]);
    }

    // Master-admin-only: listing behaviour. Only applied when explicitly sent.
    // bike_storage is a TTLock-paired cabinet (Hebden's 7 bike sheds and any
    // future ski lockers / kayak racks / parking slots on the same pattern).
    if (unit_role !== undefined && ['room', 'exclusive_hire', 'companion', 'bike_storage'].includes(unit_role)) {
      await pool.query('UPDATE bookable_units SET unit_role = $1 WHERE id = $2', [unit_role, id]);
    }

    // Rooms modal owns the stated occupancy values. Amenities owns the
    // bed_config and writes its derived sum to the CACHE columns
    // (max_guests_from_beds + beds_from_amenities) — never overwrites the
    // operator's values. When the two disagree, Site Health and the modal
    // surface the mismatch so the operator can reconcile.
    //
    // Max Adults defaults to == max_guests so a 6-sleeper room sells to 6
    // adults out of the box. Operator can override down (e.g. "this is a
    // family room, max 4 adults"); typing a value in the Max Adults field
    // sets max_adults_locked=true so future max_guests changes won't bump
    // it back up.
    //
    // Clamps: max_adults ∈ [1, max_guests] and max_children ∈ [0, max_guests-1]
    // so a booking can never be "all kids, no adult" regardless of what's
    // typed or pushed from a CM.
    const targetMaxGuests = max_guests == null ? null : (parseInt(max_guests) || 0);
    let clampedAdults = max_adults == null ? null : parseInt(max_adults);
    let clampedChildren = max_children == null ? null : parseInt(max_children);

    // Pull current row so we can compute the effective ceiling AND know
    // whether max_adults is locked (operator-overridden) — both feed the
    // logic below.
    const curRow = (await pool.query(
      'SELECT max_guests, max_adults, max_adults_locked FROM bookable_units WHERE id = $1',
      [id]
    )).rows[0] || {};
    const ceiling = targetMaxGuests != null ? targetMaxGuests : (curRow.max_guests || 0);

    // If the caller explicitly typed Max Adults, treat that as a manual
    // override — clamp to [1, ceiling] and stamp the lock.
    // Special case: `_unlock_max_adults: true` (sent by the Amenities reset
    // link) clears the lock + forces auto-follow.
    let adultsLocked = null;
    if (req.body._unlock_max_adults === true) {
      adultsLocked = false;
      clampedAdults = targetMaxGuests != null ? targetMaxGuests : (curRow.max_guests || null);
    } else if (clampedAdults != null) {
      clampedAdults = Math.max(1, Math.min(clampedAdults, Math.max(1, ceiling)));
      adultsLocked = true;
    } else if (targetMaxGuests != null && !curRow.max_adults_locked) {
      // Max Guests is changing AND adults aren't locked → auto-follow.
      clampedAdults = targetMaxGuests;
    }
    if (clampedChildren != null) {
      clampedChildren = Math.max(0, Math.min(clampedChildren, Math.max(0, ceiling - 1)));
    }
    // COALESCE on every field so partial PUTs (single-field saves from the
    // Amenities side-by-side panel) don't silently reset other columns.
    // Pre-2026-05-31 evening these used `|| 1` / `|| 'available'` / `||
    // 'double'` which trampled real values when the field was missing.
    const result = await pool.query(`
      UPDATE bookable_units
      SET quantity = COALESCE($1, quantity),
          status = COALESCE($2, status),
          unit_type = COALESCE($3, unit_type),
          max_guests = COALESCE($4, max_guests),
          max_adults = COALESCE($5, max_adults),
          max_children = COALESCE($6, max_children),
          max_adults_locked = COALESCE($7, max_adults_locked),
          updated_at = NOW()
      WHERE id = $8
      RETURNING id, name, display_name, quantity, status, unit_type, max_guests, max_adults, max_children, max_adults_locked, short_description, full_description
    `, [
      quantity == null ? null : (parseInt(quantity) || 1),
      status == null ? null : status,
      room_type == null ? null : room_type,
      targetMaxGuests,
      clampedAdults,
      clampedChildren,
      adultsLocked,
      id
    ]);
    
    // Update display_name separately if provided (handles both string and object)
    if (display_name !== undefined) {
      try {
        let jsonValue = null;
        if (display_name && typeof display_name === 'object') {
          // Already a multilingual object
          jsonValue = JSON.stringify(display_name);
        } else if (display_name && typeof display_name === 'string' && display_name.trim()) {
          // Plain string - wrap in object
          jsonValue = JSON.stringify({ en: display_name.trim() });
        }
        await pool.query(
          `UPDATE bookable_units SET display_name = $1 WHERE id = $2`,
          [jsonValue, id]
        );
      } catch (e) {
        console.log('display_name update skipped:', e.message);
      }
    }
    
    // Update short_description separately if provided (handles both string and object)
    if (short_description !== undefined) {
      try {
        let jsonValue = null;
        if (short_description && typeof short_description === 'object') {
          jsonValue = JSON.stringify(short_description);
        } else if (short_description && typeof short_description === 'string') {
          jsonValue = JSON.stringify({ en: short_description });
        }
        await pool.query(
          `UPDATE bookable_units SET short_description = $1 WHERE id = $2`,
          [jsonValue, id]
        );
      } catch (e) {
        console.log('short_description update skipped:', e.message);
      }
    }
    
    // Update full_description separately if provided (handles both string and object)
    if (full_description !== undefined) {
      try {
        let jsonValue = null;
        if (full_description && typeof full_description === 'object') {
          jsonValue = JSON.stringify(full_description);
        } else if (full_description && typeof full_description === 'string') {
          jsonValue = JSON.stringify({ en: full_description });
        }
        await pool.query(
          `UPDATE bookable_units SET full_description = $1 WHERE id = $2`,
          [sanitizeRoomDescription(jsonValue), id]
        );
      } catch (e) {
        console.log('full_description update skipped:', e.message);
      }
    }
    
    // Update num_bedrooms if provided
    if (req.body.num_bedrooms !== undefined) {
      // Allow explicit 0 (Studio marker) and explicit null (unset) — only
      // skip the assignment when the caller didn't send the field at all.
      try {
        const v = req.body.num_bedrooms;
        await pool.query(
          `UPDATE bookable_units SET num_bedrooms = $1 WHERE id = $2`,
          [v === null || v === '' ? null : parseInt(v, 10), id]
        );
      } catch (e) {
        console.log('num_bedrooms update skipped:', e.message);
      }
    }

    // Update num_bathrooms if provided (preserve 0 and null)
    if (req.body.num_bathrooms !== undefined) {
      try {
        const v = req.body.num_bathrooms;
        await pool.query(
          `UPDATE bookable_units SET num_bathrooms = $1 WHERE id = $2`,
          [v === null || v === '' ? null : parseFloat(v), id]
        );
      } catch (e) {
        console.log('num_bathrooms update skipped:', e.message);
      }
    }

    // Update beds (total bed count, used as a fallback when Bedroom
    // Configuration is empty). Preserves 0 and null.
    if (req.body.beds !== undefined) {
      try {
        const v = req.body.beds;
        await pool.query(
          `UPDATE bookable_units SET beds = $1 WHERE id = $2`,
          [v === null || v === '' ? null : parseInt(v, 10), id]
        );
      } catch (e) {
        console.log('beds update skipped:', e.message);
      }
    }

    // Update repuso_widget_id if provided
    if (repuso_widget_id !== undefined) {
      try {
        await pool.query(
          `UPDATE bookable_units SET repuso_widget_id = $1 WHERE id = $2`,
          [repuso_widget_id || null, id]
        );
      } catch (e) {
        console.log('repuso_widget_id update skipped:', e.message);
      }
    }

    // Fetch final result
    const finalResult = await pool.query(
      `SELECT id, name, display_name, quantity, status, unit_type, max_guests, max_adults, max_children, short_description, full_description, num_bedrooms, num_bathrooms, repuso_widget_id FROM bookable_units WHERE id = $1`,
      [id]
    );
    
    console.log('Update success:', finalResult.rows[0]);
    res.json({ success: true, data: finalResult.rows[0] });
  } catch (error) {
    console.error('Unit update error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Delete unit - REQUIRES no bookings attached
app.delete('/api/admin/units/:id', async (req, res) => {
  try {
    const { id } = req.params;
    
    // Check if unit has any bookings
    const bookingsCheck = await pool.query(
      'SELECT COUNT(*) as count FROM bookings WHERE bookable_unit_id = $1',
      [id]
    );
    
    if (parseInt(bookingsCheck.rows[0].count) > 0) {
      return res.json({ 
        success: false, 
        error: 'Cannot delete room: This room has ' + bookingsCheck.rows[0].count + ' booking(s) attached. Cancel or reassign bookings first.'
      });
    }
    
    // Safe to delete - remove related records first
    await pool.query('DELETE FROM bookable_unit_images WHERE bookable_unit_id = $1', [id]);
    await pool.query('DELETE FROM bookable_unit_amenities WHERE bookable_unit_id = $1', [id]);
    
    // Delete the unit
    await pool.query('DELETE FROM bookable_units WHERE id = $1', [id]);
    
    res.json({ success: true, message: 'Room deleted successfully' });
  } catch (error) {
    console.error('Unit delete error:', error.message);
    res.json({ success: false, error: error.message });
  }
});

