// Per-account filter-amenity selection.
//   GET → list of selected codes + which codes are available to pick from
//   PUT → replace the selection wholesale (body: { codes: [...], marketing_codes: [...] })
//
// Available codes = master_amenities where is_filter_eligible = true, plus
// the marketing-tags catalog. Empty selection on either side = show all
// available codes in that group (sensible default).
app.get('/api/admin/accounts/:id/filter-amenities', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const accountId = parseInt(req.params.id);
    const isMaster = decoded.role === 'master_admin';
    if (!isMaster && accountId !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }
    const acc = await pool.query('SELECT filter_amenity_codes, marketing_filter_codes FROM accounts WHERE id = $1', [accountId]);
    if (!acc.rows[0]) return res.status(404).json({ success: false, error: 'Account not found' });

    // Show the operator EVERY amenity their rooms actually have — not a
    // platform-curated whitelist. Operator ticks any subset to surface in
    // their site's filter. Previously we filtered by is_filter_eligible
    // (master-admin gatekeeping) which left operators unable to even pick
    // common things like Hot Tub / Fireplace despite their rooms having
    // them. Steve flagged this on Cotswolds 2026-05-21.
    const eligible = await pool.query(
      `SELECT ma.amenity_code,
              ma.amenity_name,
              ma.category,
              ma.icon,
              ma.display_order,
              COUNT(DISTINCT bu.id)::int AS room_count
         FROM master_amenities ma
         JOIN room_amenity_selections ras ON ras.amenity_id = ma.id
         JOIN bookable_units bu ON bu.id = ras.room_id AND bu.status IN ('active','available')
         JOIN properties p ON p.id = bu.property_id
        WHERE ma.is_active = true
          AND p.account_id = $1
        GROUP BY ma.amenity_code, ma.amenity_name, ma.category, ma.icon, ma.display_order
        ORDER BY room_count DESC, ma.category, ma.display_order, ma.amenity_code`,
      [accountId]
    );
    const countByCode = {};
    eligible.rows.forEach(r => { countByCode[r.amenity_code] = r.room_count; });

    // Same for marketing tags — count distinct properties/rooms tagged on
    // property_features with each marketing code.
    const marketingCounts = await pool.query(
      `SELECT pf.feature_name AS code,
              COUNT(DISTINCT pf.id) AS tag_count
         FROM property_features pf
         JOIN properties p ON p.id = pf.property_id
        WHERE p.account_id = $1
        GROUP BY pf.feature_name`,
      [accountId]
    );
    const marketingCountByCode = {};
    marketingCounts.rows.forEach(r => { marketingCountByCode[r.code] = parseInt(r.tag_count) || 0; });

    // Marketing tags section removed entirely — operator just wants the
    // amenities list. No tags, no catalog, no marketing categories.
    const availableMarketing = [];

    res.json({
      success: true,
      selected_codes: acc.rows[0].filter_amenity_codes || [],
      available: eligible.rows.map(a => ({
        amenity_code: a.amenity_code,
        amenity_name: a.amenity_name,
        category: a.category,
        icon: a.icon,
        display_order: a.display_order,
        room_count: a.room_count
      })),
      selected_marketing_codes: acc.rows[0].marketing_filter_codes || [],
      available_marketing: availableMarketing,
    });
  } catch (err) {
    console.error('filter-amenities get error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

app.put('/api/admin/accounts/:id/filter-amenities', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const accountId = parseInt(req.params.id);
    const isMaster = decoded.role === 'master_admin';
    if (!isMaster && accountId !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }
    const codes = Array.isArray(req.body.codes) ? req.body.codes.map(String).slice(0, 200) : [];
    const marketingCodes = Array.isArray(req.body.marketing_codes) ? req.body.marketing_codes.map(String).slice(0, 200) : [];
    // Accept any amenity code that AT LEAST ONE of the account's own rooms
    // has tagged. Drops the platform `is_filter_eligible` whitelist so
    // operators can tick anything their rooms actually offer (Hot Tub,
    // Fireplace, Fishing etc. — Cotswolds 2026-05-21 trap).
    const valid = await pool.query(
      `SELECT DISTINCT ma.amenity_code
         FROM master_amenities ma
         JOIN room_amenity_selections ras ON ras.amenity_id = ma.id
         JOIN bookable_units bu ON bu.id = ras.room_id
         JOIN properties p ON p.id = bu.property_id
        WHERE ma.is_active = true
          AND p.account_id = $1
          AND ma.amenity_code = ANY($2)`,
      [accountId, codes]
    );
    const validSet = new Set(valid.rows.map(r => r.amenity_code));
    const filtered = codes.filter(c => validSet.has(c));
    const filteredMarketing = marketingCodes.filter(c => MARKETING_TAGS_CODE_SET.has(c));
    await pool.query(
      'UPDATE accounts SET filter_amenity_codes = $2, marketing_filter_codes = $3, updated_at = NOW() WHERE id = $1',
      [accountId, filtered, filteredMarketing]
    );
    res.json({
      success: true,
      selected_codes: filtered,
      rejected: codes.filter(c => !validSet.has(c)),
      selected_marketing_codes: filteredMarketing,
      rejected_marketing: marketingCodes.filter(c => !MARKETING_TAGS_CODE_SET.has(c)),
    });
  } catch (err) {
    console.error('filter-amenities put error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// Toggle whether an amenity is eligible for the booking-app filter dropdown.
// Master admin only — this is a platform-wide curation decision.
app.patch('/api/admin/amenities/:id/filter-eligible', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    if (decoded.role !== 'master_admin') return res.status(403).json({ success: false, error: 'Master admin only' });
    const id = parseInt(req.params.id);
    const flag = !!req.body.is_filter_eligible;
    const r = await pool.query(
      'UPDATE master_amenities SET is_filter_eligible = $2, updated_at = NOW() WHERE id = $1 RETURNING id, amenity_code, is_filter_eligible',
      [id, flag]
    );
    if (!r.rows[0]) return res.status(404).json({ success: false, error: 'Amenity not found' });
    res.json({ success: true, amenity: r.rows[0] });
  } catch (err) {
    console.error('amenity filter-eligible update error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

