// ========================================
// AVAILABILITY & PRICING ENDPOINTS
// ========================================

// Get availability for a room (PUBLIC API)
app.get('/api/availability/:roomId', async (req, res) => {
  try {
    const { roomId } = req.params;
    const { from, to } = req.query;

    if (!from || !to) {
      return res.json({ success: false, error: 'from and to dates required' });
    }

    // Get room info including property currency + quantity for multi-qty rooms.
    // quantity drives per-sub-unit allocation downstream: when > 1 and the
    // account isn't on the pool model, we render N sub-rows and compute
    // units_available per date as quantity - bookings_count instead of
    // cascading the room-level is_available flag onto every sub-unit.
    const roomInfo = await pool.query(`
      SELECT bu.id, bu.name, bu.property_id, bu.quantity, COALESCE(p.currency, a.default_currency) as currency, p.country, p.booking_page_multiplier, p.round_prices_up
      FROM bookable_units bu
      JOIN properties p ON bu.property_id = p.id
      LEFT JOIN accounts a ON p.account_id = a.id
      WHERE bu.id = $1
    `, [roomId]);

    // Booking cutoffs — single source of truth. Compute the blocked-
    // arrival-date set for THIS property in the requested range, then
    // stamp cutoff_blocked=true onto every affected day in the response.
    // Every consumer (admin availability grid, WP widget flatpickr,
    // Channex outbox availability push, /api/public/book gate) reads this
    // same field. Zero client-side date math.
    const _propId = roomInfo.rows[0]?.property_id;
    let _cutoffBlocked = new Set();
    if (_propId) {
      const _cfg = await loadPropertyCutoffs(pool, _propId);
      if (_cfg) {
        _cutoffBlocked = computeCutoffBlockedDates(
          _cfg.min_advance_hours, _cfg.same_day_cutoff_time, _cfg.tz, from, to
        );
      }
    }

    // Per-date channel visibility overrides — stamp otas_hidden=true on any
    // day where the operator has toggled OTA visibility off. Grid renderer
    // uses this to paint a distinct "website-only" colour. Steve 2026-08-04.
    let _otasHiddenDates = new Set();
    try {
      const vr = await pool.query(
        `SELECT to_char(date, 'YYYY-MM-DD') AS date FROM unit_channel_daily_visibility
          WHERE bookable_unit_id = $1 AND channel = 'channex' AND is_visible = false
            AND date >= $2 AND date <= $3`,
        [roomId, from, to]);
      _otasHiddenDates = new Set(vr.rows.map(r => r.date));
    } catch (_) { /* table may not exist in dev — soft-fail */ }

    const currency = roomInfo.rows[0]?.currency || null;
    const currencySymbol = currency ? getCurrencySymbol(currency) : '';

    // ── Pool-model branch ────────────────────────────────────────────
    // For accounts on the new inventory_model='pool', availability is the
    // pool cascade query, not room_availability + bookings. Prices still
    // come from room_availability (Beds24 sync writes them there). The
    // is_booked / is_blocked / is_available fields are derived from the
    // pool counter — selling one bed in a 4-bed dorm leaves three bookable.
    //
    // Falls through to the legacy code path if:
    //   - account isn't on pool model
    //   - or no listing has source_bookable_unit_id = roomId (unmapped unit)
    const poolAcctRow = await pool.query(`
      SELECT a.inventory_model
        FROM bookable_units bu
        JOIN properties p ON p.id = bu.property_id
        JOIN accounts a   ON a.id = p.account_id
       WHERE bu.id = $1
    `, [roomId]);
    if (poolAcctRow.rows[0]?.inventory_model === 'pool') {
      const listingRow = await pool.query(`
        SELECT id FROM bookable_listings
         WHERE source_bookable_unit_id = $1
           AND COALESCE(active, true) = true
         ORDER BY id LIMIT 1
      `, [roomId]);
      const listingId = listingRow.rows[0]?.id;
      if (listingId) {
        // Cascade math: for each date in [from, to], MIN over the listing's
        // pools of FLOOR((cap - sold) / units_consumed). Capacity is the
        // same MIN ignoring sold — gives "how many can this listing ever
        // sell on this date" so the UI can render "N of M available".
        const cascade = await pool.query(`
          WITH dates AS (
            SELECT d::date AS date
              FROM generate_series($2::date, $3::date, '1 day') d
          )
          SELECT dates.date,
                 ra.cm_price, ra.standard_price, ra.direct_price,
                 ra.direct_discount_percent, ra.min_stay, ra.cm_min_stay,
                 ra.min_stay_override, ra.source,
                 -- Beds24 manual blocks (operator stops sell in Beds24 for
                 -- maintenance, owner stays, off-platform bookings) live in
                 -- room_availability.is_blocked / is_available=false. The
                 -- pool cascade doesn't know about them; surfacing here so
                 -- the response forces available_count=0 on blocked dates.
                 COALESCE(ra.is_blocked, false) AS ra_blocked,
                 COALESCE(ra.is_available, true) AS ra_available,
                 COALESCE((
                   SELECT MIN(FLOOR(
                     (COALESCE(pd.capacity, ip.default_capacity) - COALESCE(pd.sold, 0))::float
                     / GREATEST(lpc.units_consumed, 1)
                   )::int)
                     FROM listing_pool_consumption lpc
                     JOIN inventory_pools ip ON ip.id = lpc.pool_id
                     LEFT JOIN inventory_pool_dates pd
                       ON pd.pool_id = ip.id AND pd.date = dates.date
                    WHERE lpc.listing_id = $4
                 ), 0) AS available_count,
                 COALESCE((
                   SELECT MIN(FLOOR(
                     ip.default_capacity::float
                     / GREATEST(lpc.units_consumed, 1)
                   )::int)
                     FROM listing_pool_consumption lpc
                     JOIN inventory_pools ip ON ip.id = lpc.pool_id
                    WHERE lpc.listing_id = $4
                 ), 0) AS capacity
            FROM dates
            LEFT JOIN room_availability ra
              ON ra.room_id = $1 AND ra.date = dates.date
           ORDER BY dates.date
        `, [roomId, from, to, listingId]);

        // Bookings overlapping the range, scoped to *every listing that draws
        // from this unit's pool(s)*. Was: filtered by bookable_unit_id so a
        // whole-room-private or buyout booking on a sibling unit never showed
        // up on this unit's calendar even though it had consumed the shared
        // pool's capacity. Now we follow the consumption graph.
        //
        // units_consumed = the worst-case slice this booking takes from a
        // pool we care about. We expand the booking into N sub-row entries
        // downstream so a 6-bed-consumed whole-room booking paints all 6
        // beds in the dorm's sub-row view, not just one.
        // Excludes 'inquiry' to match the trigger (Beds24 inquiry semantics —
        // soft hold, doesn't consume inventory). Multiplies units_consumed
        // by num_adults for listing_kind='bed' so a Gary-style booking
        // (3 adults on a 1-bed listing) shows his name across 3 beds in
        // the calendar's per-bed sub-rows.
        const poolBookings = await pool.query(`
          WITH unit_pools AS (
            SELECT pool_id FROM listing_pool_consumption WHERE listing_id = $3
          )
          SELECT b.id AS booking_id,
                 b.arrival_date AS check_in,
                 b.departure_date AS check_out,
                 COALESCE(b.guest_first_name, '') || ' ' || COALESCE(b.guest_last_name, '') AS guest_name,
                 b.individual_unit_id, b.booking_source, b.status, b.bookable_unit_id,
                 MAX(lpc.units_consumed) * (CASE
                   WHEN MAX(bl.listing_kind) = 'bed' AND COALESCE(b.num_adults, 1) > 1
                     THEN COALESCE(b.num_adults, 1)
                   ELSE 1
                 END) AS units_consumed
            FROM bookings b
            JOIN listing_pool_consumption lpc
              ON lpc.listing_id = b.listing_id
             AND lpc.pool_id IN (SELECT pool_id FROM unit_pools)
            LEFT JOIN bookable_listings bl ON bl.id = b.listing_id
           WHERE b.status NOT IN ('cancelled', 'rejected', 'declined', 'expired', 'inquiry')
             AND b.arrival_date <= $2
             AND b.departure_date >= $1
           GROUP BY b.id
        `, [from, to, listingId]);

        // individual_units (per-bed / per-room sub-rows) — fetched up-front
        // so we can allocate pool-model bookings (which carry a NULL
        // individual_unit_id at the DB level) to a specific sub-row at
        // response time. The DB row stays NULL; the calendar gets a
        // deterministic visual placement.
        let poolIndividualUnits = [];
        try {
          const iu = await pool.query(
            `SELECT id, unit_name, unit_number, status FROM individual_units
              WHERE bookable_unit_id = $1`,
            [roomId]
          );
          poolIndividualUnits = (iu.rows || []).slice().sort((a, b) => {
            const an = parseInt(String(a.unit_number || '').replace(/\D/g, ''), 10);
            const bn = parseInt(String(b.unit_number || '').replace(/\D/g, ''), 10);
            if (!Number.isNaN(an) && !Number.isNaN(bn)) return an - bn;
            return String(a.unit_name || '').localeCompare(String(b.unit_name || ''));
          });
        } catch (e) {
          console.warn('[pool individual_units]', e.message);
        }
        const orderedBedIds = poolIndividualUnits.map(u => u.id);

        // Expand each booking by units_consumed — a whole-room booking that
        // takes 6 beds becomes 6 entries on each night of its stay. Only the
        // first copy retains the original individual_unit_id (if any); the
        // rest are NULL so the allocator below assigns them to free beds.
        //
        // Visibility rule: the guest name renders ONLY on the unit the
        // booking was actually placed against. Bookings on OTHER units that
        // share this pool still drive the cascade-blocked state (via the
        // availability query above), but they don't get expanded into bed
        // sub-rows here. A guest booking the Private 6 Bed shouldn't have
        // their name painted across the Mixed Dorm beds, and vice versa.
        const roomIdInt = parseInt(roomId, 10);
        // Sub-row count for this unit. A whole-room booking on a unit with
        // no individual_units (e.g. Private 6 Bed Ensuite) should render as
        // ONE marker on its single calendar row, not be expanded by the
        // pool's bed count. Cap expansion at the unit's actual sub-row
        // capacity (or 1 when there are none).
        const subRowCount = Math.max(1, orderedBedIds.length);
        const bookingsByDate = {};
        poolBookings.rows.forEach(b => {
          if (parseInt(b.bookable_unit_id, 10) !== roomIdInt) return;
          const ci = new Date(b.check_in);
          const co = new Date(b.check_out);
          const rawUnits = Math.max(1, parseInt(b.units_consumed, 10) || 1);
          const units = Math.min(rawUnits, subRowCount);
          for (let d = new Date(ci); d < co; d.setDate(d.getDate() + 1)) {
            const k = d.toISOString().split('T')[0];
            if (!bookingsByDate[k]) bookingsByDate[k] = [];
            for (let i = 0; i < units; i++) {
              bookingsByDate[k].push({
                booking_id: b.booking_id,
                guest_name: b.guest_name,
                individual_unit_id: i === 0 ? b.individual_unit_id : null,
                booking_source: b.booking_source
              });
            }
          }
        });

        // Per-date bed allocation for pool-model bookings: any booking row
        // with a real individual_unit_id keeps its slot; the rest get
        // assigned round-robin to the first free bed. Stable across calls
        // because we sort by booking_id before walking the unfilled list.
        for (const dateStr of Object.keys(bookingsByDate)) {
          const dayBookings = bookingsByDate[dateStr];
          const taken = new Set(
            dayBookings
              .filter(b => b.individual_unit_id != null)
              .map(b => b.individual_unit_id)
          );
          const unfilled = dayBookings
            .filter(b => b.individual_unit_id == null)
            .sort((a, b) => (a.booking_id || 0) - (b.booking_id || 0));
          for (const b of unfilled) {
            const free = orderedBedIds.find(id => !taken.has(id));
            if (free != null) {
              b.individual_unit_id = free;
              taken.add(free);
            }
          }
        }

        const result = cascade.rows.map(row => {
          const dateStr = toDateStr(row.date);
          let effectiveDirectPrice = row.direct_price;
          if (!effectiveDirectPrice && row.cm_price && row.direct_discount_percent) {
            effectiveDirectPrice = row.cm_price * (1 - row.direct_discount_percent / 100);
          }
          const rawAvailCount = parseInt(row.available_count, 10) || 0;
          // Beds24 manual block beats pool capacity: if the source unit is
          // blocked / not available on this date, the listing can't sell
          // regardless of how many pool units remain.
          const blockedByBeds24 = row.ra_blocked === true || row.ra_available === false;
          const availCount = blockedByBeds24 ? 0 : rawAvailCount;
          const cap = parseInt(row.capacity, 10) || 0;
          const dateBookings = bookingsByDate[dateStr] || [];
          return {
            date: dateStr,
            cm_price: row.cm_price,
            standard_price: row.standard_price || row.cm_price,
            standard_price_raw: row.standard_price || null,
            direct_price: effectiveDirectPrice || row.cm_price,
            direct_discount_percent: row.direct_discount_percent,
            is_available: !blockedByBeds24 && availCount > 0,
            is_blocked: blockedByBeds24,
            is_booked: !blockedByBeds24 && availCount === 0 && cap > 0,
            has_bookings: dateBookings.length > 0,
            min_stay: row.min_stay,
            cm_min_stay: row.cm_min_stay,
            min_stay_override: row.min_stay_override,
            effective_min_stay: row.min_stay_override || row.cm_min_stay || row.min_stay || 1,
            source: row.source || 'pool',
            available_count: availCount,
            capacity: cap,
            inventory_model: 'pool',
            listing_id: listingId,
            guest_name: dateBookings[0]?.guest_name || null,
            booking_id: dateBookings[0]?.booking_id || null,
            _bookings: dateBookings
          };
        });

        // Stamp cutoff_blocked from the shared helper — pool branch.
        if (_cutoffBlocked.size > 0) {
          for (const d of result) if (_cutoffBlocked.has(d.date)) d.cutoff_blocked = true;
        }
        if (_otasHiddenDates.size > 0) {
          for (const d of result) if (_otasHiddenDates.has(d.date)) d.otas_hidden = true;
        }

        const multiplier = parseFloat(roomInfo.rows[0]?.booking_page_multiplier) || null;
        const roundUp = roomInfo.rows[0]?.round_prices_up || false;
        return res.json({
          success: true,
          availability: result,
          individual_units: poolIndividualUnits,
          currency,
          currency_symbol: currencySymbol,
          booking_page_multiplier: multiplier,
          round_prices_up: roundUp,
          inventory_model: 'pool',
          listing_id: listingId
        });
      }
      // Unmapped pool-model unit — fall through to legacy so we still return
      // *something* sensible rather than an empty calendar.
    }

    // Get availability data - include standard_price and min_stay fields if they exist.
    // Also compute effective_price = same priority used by /api/public/calculate-price:
    //   override (ra.standard_price) → cm × markup (unit rule or property bpm) → raw cm.
    let availability;
    try {
      availability = await pool.query(`
        SELECT
          ra.date,
          ra.cm_price,
          ra.standard_price,
          ra.direct_price,
          ra.direct_discount_percent,
          ra.is_available,
          ra.is_blocked,
          ra.min_stay,
          ra.cm_min_stay,
          ra.min_stay_override,
          ra.source,
          ra.notes,
          CASE
            WHEN ra.standard_price IS NOT NULL THEN ra.standard_price
            WHEN bu.price_rule_type = 'percentage' AND bu.price_rule_value > 0
              THEN ROUND(ra.cm_price * (1 + bu.price_rule_value / 100), 2)
            WHEN bu.price_rule_type = 'fixed' AND bu.price_rule_value > 0
              THEN ra.cm_price + bu.price_rule_value
            WHEN COALESCE(p.booking_page_multiplier, 1) <> 1
              THEN ROUND(ra.cm_price * p.booking_page_multiplier, 2)
            ELSE ra.cm_price
          END AS effective_price,
          -- rule_price = what the price would be from the % rule alone,
          -- ignoring any per-date override. Lets the calendar show the
          -- override AND the underlying rule price (Beds24-style two-line
          -- render: bold override above faded rule price).
          CASE
            WHEN bu.price_rule_type = 'percentage' AND bu.price_rule_value > 0
              THEN ROUND(ra.cm_price * (1 + bu.price_rule_value / 100), 2)
            WHEN bu.price_rule_type = 'fixed' AND bu.price_rule_value > 0
              THEN ra.cm_price + bu.price_rule_value
            WHEN COALESCE(p.booking_page_multiplier, 1) <> 1
              THEN ROUND(ra.cm_price * p.booking_page_multiplier, 2)
            ELSE ra.cm_price
          END AS rule_price
        FROM room_availability ra
        JOIN bookable_units bu ON bu.id = ra.room_id
        JOIN properties p ON p.id = bu.property_id
        WHERE ra.room_id = $1
          AND ra.date >= $2
          AND ra.date <= $3
        ORDER BY ra.date
      `, [roomId, from, to]);
    } catch (e) {
      // Fallback if new columns don't exist
      availability = await pool.query(`
        SELECT 
          date,
          cm_price,
          cm_price as standard_price,
          direct_price,
          direct_discount_percent,
          is_available,
          is_blocked,
          min_stay,
          min_stay as cm_min_stay,
          NULL as min_stay_override,
          source,
          notes
        FROM room_availability
        WHERE room_id = $1 
          AND date >= $2 
          AND date <= $3
        ORDER BY date
      `, [roomId, from, to]);
    }
    
    // Build availability map
    const availMap = {};
    availability.rows.forEach(a => {
      const dateStr = toDateStr(a.date);
      // Calculate effective direct price
      let effectiveDirectPrice = a.direct_price;
      if (!effectiveDirectPrice && a.cm_price && a.direct_discount_percent) {
        effectiveDirectPrice = a.cm_price * (1 - a.direct_discount_percent / 100);
      }
      
      availMap[dateStr] = {
        date: dateStr,
        cm_price: a.cm_price,
        standard_price: a.standard_price || a.cm_price, // Use saved standard_price, fallback to cm_price
        standard_price_raw: a.standard_price || null, // Raw DB value — null means not manually set
        // effective_price is the same priority calculate-price uses for
        // the booking widget. Calendar + rate grid show THIS so the
        // operator always sees what the guest sees.
        effective_price: a.effective_price ? parseFloat(a.effective_price) : null,
        // rule_price = the rule-computed value ignoring any override.
        // Calendar renders this faded under the override price so the
        // operator sees both (Beds24-style override display).
        rule_price: a.rule_price ? parseFloat(a.rule_price) : null,
        direct_price: effectiveDirectPrice || a.cm_price,
        direct_discount_percent: a.direct_discount_percent,
        is_available: a.is_available,
        is_blocked: a.is_blocked,
        min_stay: a.min_stay,
        cm_min_stay: a.cm_min_stay,
        min_stay_override: a.min_stay_override,
        effective_min_stay: a.min_stay_override || a.cm_min_stay || a.min_stay || 1,
        source: a.source
      };
    });
    
    // Try to get bookings - but don't fail if table structure is different
    try {
      // First check what columns exist in bookings table
      const columnsResult = await pool.query(`
        SELECT column_name FROM information_schema.columns 
        WHERE table_name = 'bookings'
      `);
      
      const allCols = columnsResult.rows.map(r => r.column_name);
      
      // Find check-in column
      let checkInCol = allCols.find(c => c === 'check_in') ||
                       allCols.find(c => c === 'check_in_date') ||
                       allCols.find(c => c === 'checkin') ||
                       allCols.find(c => c === 'arrival_date') ||
                       allCols.find(c => c === 'start_date');
      
      // Find check-out column                 
      let checkOutCol = allCols.find(c => c === 'check_out') ||
                        allCols.find(c => c === 'check_out_date') ||
                        allCols.find(c => c === 'checkout') ||
                        allCols.find(c => c === 'departure_date') ||
                        allCols.find(c => c === 'end_date');
      
      // Find room ID column
      let roomIdCol = allCols.find(c => c === 'room_id') ||
                      allCols.find(c => c === 'bookable_unit_id') ||
                      allCols.find(c => c === 'unit_id');
      
      if (!checkInCol || !checkOutCol) {
        throw new Error('Booking columns not found');
      }
      
      if (!roomIdCol) {
        throw new Error('Room ID column not found');
      }
      
      const bookings = await pool.query(`
        SELECT
          id as booking_id,
          "${checkInCol}" as check_in,
          "${checkOutCol}" as check_out,
          COALESCE(guest_first_name, '') || ' ' || COALESCE(guest_last_name, '') as guest_name,
          individual_unit_id,
          booking_source,
          status
        FROM bookings
        WHERE "${roomIdCol}" = $1
          AND status NOT IN ('cancelled', 'rejected')
          AND "${checkInCol}" <= $3
          AND "${checkOutCol}" >= $2
      `, [roomId, from, to]);

      // Mark booked dates — top-level availMap reflects the room as a whole;
      // bookings_by_date keyed on (date,unit_id) is what the multi-unit grid needs.
      bookings.rows.forEach(b => {
        const checkIn = new Date(b.check_in);
        const checkOut = new Date(b.check_out);

        for (let d = new Date(checkIn); d < checkOut; d.setDate(d.getDate() + 1)) {
          const dateStr = d.toISOString().split('T')[0];
          if (!availMap[dateStr]) {
            availMap[dateStr] = { date: dateStr };
          }
          // Aggregate flag for the legacy single-row renderer
          availMap[dateStr].is_booked = true;
          availMap[dateStr].guest_name = b.guest_name;
          availMap[dateStr].booking_id = b.booking_id;
          // Per-unit-per-date list — the multi-row renderer reads this
          if (!availMap[dateStr]._bookings) availMap[dateStr]._bookings = [];
          availMap[dateStr]._bookings.push({
            booking_id: b.booking_id,
            guest_name: b.guest_name,
            individual_unit_id: b.individual_unit_id,
            booking_source: b.booking_source
          });
        }
      });
    } catch (bookingErr) {
      console.log('Bookings query skipped:', bookingErr.message);
      // Continue without bookings data
    }

    // ── Multi-qty per-sub-unit allocation (non-pool path) ──────────────────
    // Pool-model rooms (Hebden) are handled by the dedicated branch above and
    // never reach this code. Everyone else with quantity > 1 lands here.
    //
    // Problem we're fixing: Beds24's per-room `is_available` is a single
    // boolean per (room_id, date). When ANY booking exists, is_available
    // becomes false for the whole bookable_unit. The calendar's sub-row
    // cascade-block branch then paints every sub-unit red — even on a 50-unit
    // hotel room with only 3 guests for the night. Operator can't see the
    // 47 genuinely-free units.
    //
    // Fix: for each date with bookings, count actual overlaps, compute
    // units_available = max(0, quantity - count), and override the
    // is_available / is_booked flags. Then round-robin allocate NULL-iu
    // bookings to individual_units so the per-unit cell renders the right
    // guest in the right sub-row. Pinned bookings (Beds24 sync wrote their
    // individual_unit_id) keep their slot.
    let individualUnits = [];
    try {
      const iu = await pool.query(
        `SELECT id, unit_name, unit_number, status FROM individual_units
         WHERE bookable_unit_id = $1
         ORDER BY NULLIF(regexp_replace(unit_number, '\\D', '', 'g'), '')::int NULLS LAST, unit_name`,
        [roomId]
      );
      individualUnits = iu.rows;
    } catch (_) { /* table may not exist on some installs */ }

    const buQuantity = parseInt(roomInfo.rows[0]?.quantity, 10) || 1;
    if (buQuantity > 1) {
      const orderedBedIds = individualUnits.map(u => u.id);
      for (const dateStr of Object.keys(availMap)) {
        const dayData = availMap[dateStr];
        const dayBookings = Array.isArray(dayData._bookings) ? dayData._bookings : [];
        const taken = new Set(dayBookings.filter(b => b.individual_unit_id != null).map(b => b.individual_unit_id));
        const unfilled = dayBookings
          .filter(b => b.individual_unit_id == null)
          .sort((a, b) => (a.booking_id || 0) - (b.booking_id || 0));
        for (const b of unfilled) {
          const free = orderedBedIds.find(id => !taken.has(id));
          if (free != null) { b.individual_unit_id = free; taken.add(free); }
        }
        const bookingsCount = dayBookings.length;
        const unitsAvailable = Math.max(0, buQuantity - bookingsCount);
        dayData.capacity = buQuantity;
        dayData.bookings_count = bookingsCount;
        dayData.units_available = unitsAvailable;
        // For multi-qty rooms the is_blocked flag from beds24_webhook is a
        // false positive — it flips true whenever ANY single booking lands
        // (webhook has no notion of quantity). Treating it as a full-room
        // stop-sell makes the widget say "no availability" while 49/50 units
        // are actually free (Hotel Caracas 2026-07-20). Multi-qty rooms
        // trust the units_available calc unconditionally. Real stop-sells
        // (maintenance, owner stay) belong on individual_units or an
        // explicit operator block, not a webhook-derived flag.
        dayData.is_available = unitsAvailable > 0;
        dayData.is_booked = unitsAvailable === 0 && bookingsCount > 0;
        dayData.is_blocked = false;
      }
    }

    // Convert to array and fill missing dates
    const result = [];
    const startDate = new Date(from);
    const endDate = new Date(to);

    for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      result.push(availMap[dateStr] || {
        date: dateStr,
        is_available: true,
        is_booked: false,
        is_blocked: false
      });
    }

    // Stamp cutoff_blocked from the shared helper — legacy branch.
    if (_cutoffBlocked.size > 0) {
      for (const d of result) if (_cutoffBlocked.has(d.date)) d.cutoff_blocked = true;
    }
    if (_otasHiddenDates.size > 0) {
      for (const d of result) if (_otasHiddenDates.has(d.date)) d.otas_hidden = true;
    }

    const multiplier = parseFloat(roomInfo.rows[0]?.booking_page_multiplier) || null;
    const roundUp = roomInfo.rows[0]?.round_prices_up || false;

    res.json({
      success: true,
      availability: result,
      individual_units: individualUnits,
      currency,
      currency_symbol: currencySymbol,
      booking_page_multiplier: multiplier,
      round_prices_up: roundUp
    });
  } catch (error) {
    console.error('Availability error:', error);
    res.json({ success: false, error: error.message });
  }
});

