// POST /api/admin/bookings/:id/force-reset-outbox
// Flip any 'processing' outbox rows for this booking back to 'pending'
// with next_try_at=NOW(). Attempts counter is left alone so we still
// see how many retries have happened. Steve report 2026-07-07: booking
// 331637 outbox row stuck in 'processing' with 0 attempts because a
// Railway restart mid-tick left it claimed but never completed. The
// worker's 2-minute reaper should catch this but wasn't. Manual poke.
app.post('/api/admin/bookings/:id/force-reset-outbox', async (req, res) => {
  try {
    if (!await requireMasterAdmin(req, res)) return;
    const { id } = req.params;
    const r = await pool.query(`
      UPDATE gas_channex_outbox
         SET status = 'pending', next_try_at = NOW(), last_error = 'force-reset by master admin'
       WHERE payload->>'gasBookingId' = $1
         AND status = 'processing'
       RETURNING id, status
    `, [String(id)]);
    res.json({
      success: true,
      reset_count: r.rows.length,
      rows: r.rows,
      message: r.rows.length > 0
        ? `${r.rows.length} outbox row(s) reset to pending. Worker will pick them up on next tick (usually 30s).`
        : 'No processing rows found for this booking. It may already have succeeded or failed cleanly.'
    });
  } catch (err) {
    console.error('[force-reset-outbox]', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/admin/properties/:id/latest-channex-status
// Combined diagnostic: finds the most recent bookings for a property,
// runs the outbox-status check on the latest one, returns everything
// in one shot so we don't need to pass booking IDs around.
app.get('/api/admin/properties/:id/latest-channex-status', async (req, res) => {
  try {
    if (!await requireMasterAdmin(req, res)) return;
    const { id } = req.params;
    const recent = await pool.query(`
      SELECT b.id, b.status, b.payment_status, b.booking_source,
             b.arrival_date::text, b.departure_date::text,
             b.guest_first_name, b.guest_last_name, b.currency,
             b.channex_booking_id, b.beds24_booking_id,
             b.created_at,
             bu.name AS room_name
        FROM bookings b
        LEFT JOIN bookable_units bu ON bu.id = b.bookable_unit_id
       WHERE b.property_id = $1
       ORDER BY b.created_at DESC
       LIMIT 5
    `, [id]);
    if (recent.rows.length === 0) return res.json({ success: false, error: 'No bookings found for this property' });

    const latest = recent.rows[0];
    const outbox = await pool.query(`
      SELECT id, connection_id, change_type, status, attempts,
             next_try_at, processed_at, last_error, channex_task_id,
             created_at
        FROM gas_channex_outbox
       WHERE payload->>'gasBookingId' = $1
       ORDER BY created_at DESC
       LIMIT 10
    `, [String(latest.id)]);

    let verdict;
    if (outbox.rows.length === 0) {
      verdict = `Latest booking GAS-${latest.id} has NO outbox row. enqueueBookingPush either was never called or returned false silently. Check Railway logs for [channex-outbox] enqueue messages for booking id ${latest.id}.`;
    } else {
      const r0 = outbox.rows[0];
      if (r0.status === 'succeeded') {
        verdict = `Latest booking GAS-${latest.id} outbox row SUCCEEDED at ${r0.processed_at}. channex_task_id=${r0.channex_task_id}. If Channex UI still shows nothing, refresh Channex or wait ~30s for their indexing.`;
      } else if (r0.status === 'failed') {
        verdict = `Latest booking GAS-${latest.id} outbox row FAILED. last_error=${r0.last_error}. attempts=${r0.attempts}. Fix the underlying issue and re-enqueue via /push-to-channex.`;
      } else if (r0.status === 'processing') {
        verdict = `Latest booking GAS-${latest.id} outbox row is PROCESSING right now. Give it 30s.`;
      } else if (r0.status === 'pending') {
        verdict = `Latest booking GAS-${latest.id} outbox row is PENDING. next_try_at=${r0.next_try_at}, attempts=${r0.attempts}. last_error=${r0.last_error || '(none)'}. Worker will retry on next tick.`;
      } else {
        verdict = `Latest booking GAS-${latest.id} outbox row has unknown status: ${r0.status}`;
      }
    }

    res.json({
      success: true,
      latest_booking: latest,
      recent_bookings: recent.rows,
      outbox_rows: outbox.rows,
      verdict
    });
  } catch (err) {
    console.error('[latest-channex-status]', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/admin/bookings/:id/channex-outbox-status
// Reads gas_channex_outbox rows for this booking so we can see whether
// the outbox worker succeeded, failed, or hasn't picked the row up yet.
// Booking 331467 report 2026-07-07: dates blocked in Channex but no
// reservation record — need to see if outbox has last_error text.
app.get('/api/admin/bookings/:id/channex-outbox-status', async (req, res) => {
  try {
    if (!await requireMasterAdmin(req, res)) return;
    const { id } = req.params;
    const rows = await pool.query(`
      SELECT id, connection_id, change_type, status, attempts, next_try_at,
             processed_at, last_error, channex_task_id, created_at,
             payload->>'gasBookingId' AS payload_gas_booking_id
        FROM gas_channex_outbox
       WHERE payload->>'gasBookingId' = $1
       ORDER BY created_at DESC
       LIMIT 20
    `, [String(id)]);

    // Also fetch the current bookings.channex_booking_id to cross-check.
    const bk = await pool.query(
      `SELECT id, channex_booking_id, status, arrival_date::text, departure_date::text
         FROM bookings WHERE id = $1`,
      [id]
    );

    let verdict;
    if (rows.rows.length === 0) {
      verdict = 'No outbox row for this booking. enqueueBookingPush never inserted one — probably the pre-commit visibility bug (fixed in 41ddaa1e). Try /push-to-channex to force-retry.';
    } else {
      const latest = rows.rows[0];
      if (latest.status === 'succeeded') {
        verdict = `Outbox row succeeded at ${latest.processed_at}. channex_task_id=${latest.channex_task_id}. If Channex UI still doesn't show a reservation, the API accepted it but Channex's own indexing might be lagging — refresh Channex.`;
      } else if (latest.status === 'failed') {
        verdict = `Outbox row FAILED after ${latest.attempts} attempts. last_error: ${latest.last_error || '(none)'}. Fix the underlying cause then re-enqueue via /push-to-channex.`;
      } else if (latest.status === 'processing') {
        verdict = `Outbox row is being processed right now. Give it 30s and re-check.`;
      } else if (latest.status === 'pending') {
        verdict = `Outbox row is pending with next_try_at=${latest.next_try_at}. attempts=${latest.attempts}. last_error: ${latest.last_error || '(none)'}. Worker will pick it up on next tick.`;
      } else {
        verdict = `Unknown outbox status: ${latest.status}`;
      }
    }

    res.json({
      success: true,
      booking: bk.rows[0] || null,
      outbox_rows: rows.rows,
      verdict
    });
  } catch (err) {
    console.error('[channex-outbox-status]', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// POST /api/admin/bookings/:id/push-to-channex
// Manual re-push for a booking whose original enqueue didn't stick.
// Fires the same enqueueBookingPush the admin booking endpoint uses at
// save time. Booking 331446 diagnosis 2026-07-07 showed the mapping is
// correct but channex_booking_id is null — this endpoint lets Steve
// force-retry without touching the DB.
app.post('/api/admin/bookings/:id/push-to-channex', async (req, res) => {
  try {
    if (!await requireMasterAdmin(req, res)) return;
    const { id } = req.params;
    const { enqueueBookingPush } = require('./gas-sync/channex-outbox');
    const queued = await enqueueBookingPush(pool, id, 'booking_create');
    if (!queued) {
      return res.json({ success: false, error: 'enqueueBookingPush returned false — call /why-not-channex to see why' });
    }
    res.json({ success: true, queued: true, message: 'Booking queued to Channex — outbox will POST it within a few seconds' });
  } catch (err) {
    console.error('[push-to-channex]', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// Set availability for date range (ADMIN)
// POST /api/admin/availability/force-clear-orphan-blocks
// One-shot cleanup: find room_availability rows that are blocked / unavailable
// but NO active booking covers them. These are usually residue from a
// cancel that ran before commit 29e09ef2 (the cancel endpoint now
// UPSERTs is_available=true properly, but pre-existing junk is still
// there). Free them.
//
// Optional filters:
//   ?room_id=X       — only that room's rows
//   ?dry_run=1       — return the list of would-be-freed rows without writing
//
// Steve report 2026-07-07: Elizabeth Room 15 Aug (and probably other
// residue on Charles House Windsor). Master admin only.
app.post('/api/admin/availability/force-clear-orphan-blocks', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded || decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Master admin only' });
    }
    const roomId = req.query.room_id ? parseInt(req.query.room_id, 10) : null;
    const dryRun = String(req.query.dry_run || '').match(/^(1|true|yes)$/i);

    // Candidates: room_availability rows currently marked unavailable OR
    // blocked, from today onwards. We ONLY free rows with NO active booking
    // for that room × date.
    const params = [];
    let where = `(ra.is_blocked = true OR ra.is_available = false) AND ra.date >= CURRENT_DATE`;
    if (roomId) { params.push(roomId); where += ` AND ra.room_id = $${params.length}`; }

    // SAFETY: only touch rows whose block came from a BOOKING / CM sync —
    // never rows an operator manually blocked (maintenance, owner stay).
    // The source field is our audit trail here. Manual blocks are typically
    // written with source IN ('manual', NULL) from the rate edit modal, or
    // 'owner-stay' / anything not on the whitelist below. If we can't tell
    // the row came from a booking, we leave it alone. Steve report 2026-07-07
    // — 'what if people deliberately blocked them'.
    const BOOKING_SOURCED = [
      'booking',        // legacy /api/public/book
      'beds24',         // Beds24 sync
      'beds24_sync',
      'beds24_webhook',
      'beds24_inventory',
      'channex',
      'channex_webhook',
      'hostaway',
      'hostaway_webhook',
      'smoobu',
      'smoobu_webhook',
    ];

    // Anti-join against bookings.arrival_date/departure_date. departure_date
    // is exclusive (departure day is NOT a night), matching how the calendar
    // treats stays. Filter out cancelled / rejected / declined / expired /
    // inquiry — same set used by /api/availability's bookings query.
    const rows = await pool.query(`
      SELECT ra.room_id, ra.date, ra.source, ra.is_blocked, ra.is_available
        FROM room_availability ra
       WHERE ${where}
         AND ra.source = ANY($${params.length + 1})
         AND NOT EXISTS (
           SELECT 1 FROM bookings b
            WHERE b.bookable_unit_id = ra.room_id
              AND b.arrival_date <= ra.date
              AND b.departure_date > ra.date
              AND b.status NOT IN ('cancelled', 'rejected', 'declined', 'expired', 'inquiry')
         )
       ORDER BY ra.room_id, ra.date
       LIMIT 5000
    `, [...params, BOOKING_SOURCED]);

    if (dryRun) {
      return res.json({
        success: true,
        dry_run: true,
        would_clear: rows.rows.length,
        rows: rows.rows.slice(0, 200)
      });
    }

    let cleared = 0;
    for (const r of rows.rows) {
      await pool.query(`
        UPDATE room_availability
           SET is_available = true, is_blocked = false,
               source = 'orphan-cleanup', updated_at = NOW()
         WHERE room_id = $1 AND date = $2
      `, [r.room_id, r.date]);
      cleared++;
    }

    res.json({
      success: true,
      cleared,
      room_id: roomId || 'all',
      sample: rows.rows.slice(0, 20)
    });
  } catch (err) {
    console.error('[force-clear-orphan-blocks]', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

app.post('/api/admin/availability', async (req, res) => {
  const client = await pool.connect();
  // Collect Channex outbox enqueues to run after commit — keeps the SQL
  // transaction lean and prevents outbox writes if the main update rolls back.
  const channexEvents = [];
  try {
    const { room_id, from_date, to_date, status, price, discount_percent, standard_price, min_stay_override } = req.body;

    await client.query('BEGIN');

    const startDate = new Date(from_date);
    const endDate = new Date(to_date);
    let daysUpdated = 0;

    for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];

      if (standard_price !== undefined) {
        // Operator per-date override. Writes to standard_price_override so
        // the cm_price recompute trigger respects it. Passing null clears
        // the override and falls back to cm_price × markup.
        //
        // Steve 2026-08-23 — was HARDCODING is_available=true, is_blocked=
        // false which silently ignored any status flag sent alongside a
        // price override. That meant ticking "Block this date" in the
        // per-cell Edit Rate modal did nothing when the cell already had
        // a price override (No5 Sept 4/5 didn't save). Now: when status
        // is explicitly passed, honour it; when omitted, default to
        // available/unblocked (previous behaviour).
        const _wantBlocked = status === 'blocked';
        const _wantAvailable = status !== 'blocked';
        await client.query(`
          INSERT INTO room_availability (room_id, date, standard_price_override, is_available, is_blocked)
          VALUES ($1, $2, $3, $4, $5)
          ON CONFLICT (room_id, date)
          DO UPDATE SET
            standard_price_override = $3,
            is_available = EXCLUDED.is_available,
            is_blocked = EXCLUDED.is_blocked,
            updated_at = NOW()
        `, [room_id, dateStr, standard_price || null, _wantAvailable, _wantBlocked]);
        // Channex: rate change for this date
        if (standard_price != null) {
          channexEvents.push({ kind: 'rate', date: dateStr, payload: { date: dateStr, rate: Number(standard_price) } });
        }
        // Also mirror the block/unblock to Channex when status was passed
        // — otherwise a block via this branch wouldn't close OTA channels.
        if (status === 'blocked' || status === 'available') {
          channexEvents.push({
            kind: 'availability',
            date: dateStr,
            payload: { date: dateStr, count: _wantBlocked ? 0 : 1 },
          });
        }
      } else if (discount_percent) {
        // Apply percentage discount
        await client.query(`
          INSERT INTO room_availability (room_id, date, direct_discount_percent, is_available, is_blocked)
          VALUES ($1, $2, $3, $4, $5)
          ON CONFLICT (room_id, date) 
          DO UPDATE SET 
            direct_discount_percent = $3,
            direct_price = NULL,
            is_available = $4,
            is_blocked = $5,
            updated_at = NOW()
        `, [room_id, dateStr, discount_percent, status === 'available', status === 'blocked']);
      } else {
        // Set fixed direct price
        await client.query(`
          INSERT INTO room_availability (room_id, date, direct_price, is_available, is_blocked)
          VALUES ($1, $2, $3, $4, $5)
          ON CONFLICT (room_id, date)
          DO UPDATE SET
            direct_price = COALESCE($3, room_availability.direct_price),
            direct_discount_percent = NULL,
            is_available = $4,
            is_blocked = $5,
            updated_at = NOW()
        `, [room_id, dateStr, price || null, status === 'available', status === 'blocked']);
        // Channex: block/unblock via /availability (count=0 / count=1).
        // channex-adapter.js:554 warns /restrictions with null
        // rate_plan_id returns 2xx and silently no-ops — Barbara's
        // manual blocks were succeeding at the API level but the room
        // stayed open on B.com/Airbnb. Switching to availability=0 is
        // the universal "no rooms" signal every channel honours; no
        // rate plan needed.
        channexEvents.push({
          kind: 'availability',
          date: dateStr,
          payload: { date: dateStr, count: status === 'blocked' ? 0 : 1 },
        });
      }

      // Min-stay override is independent of price/status — apply on every day
      // in the range when the field is explicitly passed (null clears the
      // override and falls back to CM / property min_stay).
      if (min_stay_override !== undefined) {
        const ms = (min_stay_override === null || min_stay_override === '') ? null : parseInt(min_stay_override, 10);
        await client.query(`
          INSERT INTO room_availability (room_id, date, min_stay_override, is_available)
          VALUES ($1, $2, $3, true)
          ON CONFLICT (room_id, date)
          DO UPDATE SET min_stay_override = $3, updated_at = NOW()
        `, [room_id, dateStr, ms]);
        // Outbox worker (channex-outbox.js:287) reads minStayArrival +
        // minStayThrough from the payload — sending just `minStay` was a
        // silent no-op. Steve 2026-07-28.
        channexEvents.push({
          kind: 'restriction',
          date: dateStr,
          payload: { date: dateStr, minStayArrival: ms, minStayThrough: ms }
        });
      }

      daysUpdated++;
    }

    await client.query('COMMIT');

    // Post-commit: emit Channex outbox events (no-op if room not mapped to Channex)
    if (channexEvents.length > 0) {
      try {
        const { enqueueAvailabilityForRoom, enqueueRestrictionForRoom } = require('./gas-sync/channex-outbox');
        for (const ev of channexEvents) {
          if (ev.kind === 'availability') {
            await enqueueAvailabilityForRoom(pool, room_id, ev.date, ev.payload.count);
          } else {
            await enqueueRestrictionForRoom(pool, room_id, ev.payload, ev.kind);
          }
        }
      } catch (e) {
        console.error('[channex-outbox] enqueue (availability) failed:', e.message);
      }
    }

    // Post-commit: emit Beds24 outbox events (no-op if room not mapped to Beds24)
    // Closes the gap where Quick Edit blocks landed in GAS but Beds24 still
    // showed the dates as available — OTAs could double-book. Outbox worker
    // batches per-room and pushes via POST /api/v2/inventory/rooms with
    // numAvail=0 (block) / numAvail=1 (unblock).
    if (channexEvents.length > 0) {
      try {
        const { enqueueAvailabilityForRoom: enqueueBeds24Avail } = require('./gas-sync/beds24-outbox');
        for (const ev of channexEvents) {
          if (ev.kind === 'availability') {
            // ev.payload.count = 1 (unblock) or 0 (handled via 'restriction' branch below)
            await enqueueBeds24Avail(pool, room_id, ev.date, ev.payload.count);
          } else if (ev.kind === 'restriction' && ev.payload && ev.payload.stopSell) {
            // Block = numAvail=0 on Beds24
            await enqueueBeds24Avail(pool, room_id, ev.date, 0);
          }
          // Min-stay / other restriction events: not pushed to Beds24 yet
          // (out of scope — only availability for now).
        }
      } catch (e) {
        console.error('[beds24-outbox] enqueue (availability) failed:', e.message);
      }
    }

    res.json({ success: true, days_updated: daysUpdated });
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Set availability error:', error);
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

// Batch save standard prices (up to 365 days)
app.post('/api/admin/availability/batch-standard-prices', async (req, res) => {
  const client = await pool.connect();
  const channexEvents = [];
  try {
    const { room_id, prices } = req.body;
    if (!room_id || !Array.isArray(prices) || prices.length === 0) {
      return res.json({ success: false, error: 'room_id and prices array required' });
    }
    if (prices.length > 400) {
      return res.json({ success: false, error: 'Maximum 400 prices per batch' });
    }

    await client.query('BEGIN');
    let saved = 0;

    for (const { date, price } of prices) {
      if (!date) continue;
      const parsed = price != null ? parseFloat(price) : null;
      // Rate calendar batch save = per-date operator overrides. Goes to
      // standard_price_override; trigger sets standard_price = override.
      // Pass null to clear an override (falls back to cm_price × markup).
      await client.query(`
        INSERT INTO room_availability (room_id, date, standard_price_override, is_available, is_blocked)
        VALUES ($1, $2, $3, true, false)
        ON CONFLICT (room_id, date)
        DO UPDATE SET standard_price_override = $3, updated_at = NOW()
      `, [room_id, date, parsed]);
      if (parsed != null) {
        channexEvents.push({ date, rate: parsed });
      }
      saved++;
    }

    await client.query('COMMIT');

    // Cert-critical: tests 4 + 8 watch for ONE batched API call across many
    // dates. The outbox worker takes care of that — we just enqueue one row
    // per date and the next tick groups them into one /restrictions call.
    if (channexEvents.length > 0) {
      try {
        const { enqueueRestrictionForRoom } = require('./gas-sync/channex-outbox');
        for (const ev of channexEvents) {
          await enqueueRestrictionForRoom(pool, room_id, { date: ev.date, rate: ev.rate }, 'rate');
        }
      } catch (e) {
        console.error('[channex-outbox] enqueue (batch-prices) failed:', e.message);
      }
    }

    res.json({ success: true, saved });
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Batch standard price save error:', error);
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

// Reset standard prices to CM prices for a room. Clears any per-date
// operator overrides AND nulls cm_price → so the next trigger pass
// (on the next cron tick) repopulates standard_price from cm_price ×
// markup. Use this when wiping stale yield-management leftovers.
app.post('/api/admin/availability/reset-to-cm', async (req, res) => {
  try {
    const { room_id } = req.body;
    if (!room_id) return res.json({ success: false, error: 'room_id required' });
    // Setting standard_price_override fires the BEFORE UPDATE OF trigger,
    // which recomputes standard_price = cm_price × markup. Works even when
    // override was already NULL (Postgres fires on column-in-SET, not on
    // value-change).
    const result = await pool.query(
      `UPDATE room_availability
         SET standard_price_override = NULL,
             updated_at = NOW()
       WHERE room_id = $1`,
      [room_id]
    );
    res.json({ success: true, rows_updated: result.rowCount });
  } catch (error) {
    console.error('Reset to CM prices error:', error);
    res.json({ success: false, error: error.message });
  }
});

// GET/PUT price rule for a room
app.get('/api/admin/rooms/:roomId/price-rule', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT price_rule_type, price_rule_value FROM bookable_units WHERE id = $1',
      [req.params.roomId]
    );
    if (result.rows.length === 0) return res.json({ success: false, error: 'Room not found' });
    res.json({ success: true, data: result.rows[0] });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

app.put('/api/admin/rooms/:roomId/price-rule', async (req, res) => {
  try {
    const { price_rule_type, price_rule_value } = req.body;
    const roomId = parseInt(req.params.roomId);

    // Validate
    if (price_rule_type && !['percentage', 'fixed'].includes(price_rule_type)) {
      return res.json({ success: false, error: 'price_rule_type must be percentage or fixed' });
    }

    // Save rule
    await pool.query(
      'UPDATE bookable_units SET price_rule_type = $1, price_rule_value = $2 WHERE id = $3',
      [price_rule_type || null, price_rule_value || null, roomId]
    );

    // Clean stale bulk-import overrides. The frontend renders per-date
    // standard_price overrides in priority over the rule-computed value —
    // so when standard_price was mass-imported equal to cm_price (a common
    // artefact from pre-2026-06-09 sync passes), changing the rule has no
    // visible effect. NULL those out so the rule takes visible effect.
    // CRITICAL: only touches rows where standard_price = cm_price EXACTLY
    // — a real operator override (different value) is preserved. Steve
    // 2026-07-20 "DO NOT EFFECT any selection made by people."
    const cleaned = await pool.query(
      `UPDATE room_availability
          SET standard_price = NULL, updated_at = NOW()
        WHERE room_id = $1
          AND standard_price IS NOT NULL
          AND cm_price IS NOT NULL
          AND standard_price = cm_price`,
      [roomId]
    );

    // Apply rule (retired 2026-06-09 — see applyPriceRules for context)
    let applied = 0;
    if (price_rule_type && price_rule_value > 0) {
      applied = await applyPriceRules(roomId);
    }

    res.json({
      success: true,
      message: `Price rule saved. Cleared ${cleaned.rowCount} stale overrides (standard_price = cm_price).`,
      applied,
      overrides_cleared: cleaned.rowCount
    });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Migration: Create room_availability table
app.post('/api/admin/migrate-availability', async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    
    await client.query(`
      CREATE TABLE IF NOT EXISTS room_availability (
        id SERIAL PRIMARY KEY,
        room_id INTEGER NOT NULL REFERENCES bookable_units(id) ON DELETE CASCADE,
        date DATE NOT NULL,
        cm_price DECIMAL(10,2),
        direct_price DECIMAL(10,2),
        direct_discount_percent INTEGER,
        is_available BOOLEAN DEFAULT true,
        is_blocked BOOLEAN DEFAULT false,
        min_stay INTEGER DEFAULT 1,
        source VARCHAR(20) DEFAULT 'manual',
        notes TEXT,
        created_at TIMESTAMP DEFAULT NOW(),
        updated_at TIMESTAMP DEFAULT NOW(),
        UNIQUE(room_id, date)
      )
    `);
    
    await client.query('CREATE INDEX IF NOT EXISTS idx_room_avail_room ON room_availability(room_id)');
    await client.query('CREATE INDEX IF NOT EXISTS idx_room_avail_date ON room_availability(date)');
    await client.query('CREATE INDEX IF NOT EXISTS idx_room_avail_room_date ON room_availability(room_id, date)');
    
    // Add new columns if table already exists
    try {
      await client.query('ALTER TABLE room_availability ADD COLUMN IF NOT EXISTS cm_price DECIMAL(10,2)');
      await client.query('ALTER TABLE room_availability ADD COLUMN IF NOT EXISTS direct_price DECIMAL(10,2)');
      await client.query('ALTER TABLE room_availability ADD COLUMN IF NOT EXISTS direct_discount_percent INTEGER');
      await client.query('ALTER TABLE room_availability ADD COLUMN IF NOT EXISTS source VARCHAR(20) DEFAULT \'manual\'');
      // Extend source column to VARCHAR(50) if it's too short
      await client.query('ALTER TABLE room_availability ALTER COLUMN source TYPE VARCHAR(50)').catch(() => {});
      // Migrate old price column to cm_price
      await client.query('UPDATE room_availability SET cm_price = price WHERE cm_price IS NULL AND price IS NOT NULL');
    } catch (e) {
      console.log('Column migration note:', e.message);
    }
    
    await client.query('COMMIT');
    
    res.json({ success: true, message: 'room_availability table updated with cm_price and direct_price' });
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Migration error:', error);
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

// Migration: Add content columns to properties and rooms
app.post('/api/admin/migrate-content-columns', async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    
    // First, check if description is JSONB and convert to TEXT
    try {
      // Try to alter the column type - this will fail if it's already TEXT
      await client.query(`
        ALTER TABLE properties 
        ALTER COLUMN description TYPE TEXT 
        USING CASE 
          WHEN description IS NULL THEN NULL
          WHEN description::text LIKE '{%' THEN description::jsonb->>'en'
          ELSE description::text
        END
      `);
      console.log('   ✓ Converted description to TEXT');
    } catch (e) {
      console.log('   - description column OK or conversion not needed');
    }
    
    // Add columns to properties table
    const propertyColumns = [
      'location_description TEXT',
      'house_rules TEXT',
      'cancellation_policy TEXT',
      'terms_conditions TEXT'
    ];
    
    for (const col of propertyColumns) {
      const colName = col.split(' ')[0];
      try {
        await client.query(`ALTER TABLE properties ADD COLUMN IF NOT EXISTS ${col}`);
        console.log(`   ✓ Added ${colName} to properties`);
      } catch (e) {
        // Column might already exist
      }
    }
    
    // Add columns to bookable_units table
    const roomColumns = [
      'short_description TEXT',
      'full_description TEXT'
    ];
    
    for (const col of roomColumns) {
      const colName = col.split(' ')[0];
      try {
        await client.query(`ALTER TABLE bookable_units ADD COLUMN IF NOT EXISTS ${col}`);
        console.log(`   ✓ Added ${colName} to bookable_units`);
      } catch (e) {
        // Column might already exist
      }
    }
    
    await client.query('COMMIT');
    
    res.json({
      success: true,
      message: 'Content columns added successfully',
      columns: {
        properties: ['description (converted)', ...propertyColumns],
        rooms: roomColumns
      }
    });
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Migration error:', error);
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

