// =========================================================
// IMAGE PROCESSING HELPER FUNCTIONS
// =========================================================

/**
 * Validate image meets minimum aspect ratio (1.2:1 or wider)
 * Allows images that are at least 20% wider than tall
 */
async function validateLandscape(buffer) {
  const metadata = await sharp(buffer).metadata();
  const ratio = metadata.width / metadata.height;
  
  if (ratio < 1.2) {
    throw new Error('Images must be at least 1.2:1 ratio (width:height). Portrait and square images are not accepted.');
  }
  
  return metadata;
}

/**
 * Clean external image URLs — strip CDN compression/resize params
 * so we always store the highest quality original.
 * Covers Airbnb (muscache.com aki_policy), Booking.com (max300/square60 etc)
 */
function cleanImageUrl(url) {
  if (!url || typeof url !== 'string') return url;
  try {
    const u = new URL(url);
    // Airbnb / muscache — aki_policy forces compression
    if (u.hostname.includes('muscache.com')) {
      u.searchParams.delete('aki_policy');
    }
    // Booking.com — /max300/ /square60/ etc in path force resize
    if (u.hostname.includes('bstatic.com')) {
      u.pathname = u.pathname.replace(/\/(max\d+|square\d+)\//g, '/');
    }
    return u.toString();
  } catch (e) {
    return url; // not a valid URL, return as-is
  }
}

/**
 * Process and upload image to R2 in multiple sizes
 * Returns URLs for all variants
 */
// Upload an arbitrary file (PDF, DOCX, etc.) to R2 — no Sharp processing,
// just direct put. Used for lead-magnet downloads on lead forms. Returns
// the public URL.
async function uploadFileToR2(buffer, type, entityId, filename, contentType) {
  const ext = path.extname(filename).toLowerCase() || '';
  const safeBase = path.basename(filename, ext).replace(/[^a-zA-Z0-9._-]/g, '-').slice(0, 80);
  const uniqueId = uuidv4();
  const key = `${type}/${entityId}/${uniqueId}-${safeBase}${ext}`;
  await r2Client.send(new PutObjectCommand({
    Bucket: R2_BUCKET,
    Key: key,
    Body: buffer,
    ContentType: contentType || 'application/octet-stream',
    CacheControl: 'public, max-age=31536000',
    ContentDisposition: `inline; filename="${safeBase}${ext}"`
  }));
  return `${R2_PUBLIC_URL}/${key}`;
}

async function processAndUploadImage(buffer, type, entityId, filename) {
  const ext = path.extname(filename).toLowerCase();
  const baseFilename = path.basename(filename, ext);
  const uniqueId = uuidv4();
  
  const sizes = {
    large: { width: 1920, quality: 85 },
    medium: { width: 1200, quality: 85 },
    thumbnail: { width: 400, quality: 80 }
  };
  
  const results = {
    original: null,
    large: null,
    medium: null,
    thumbnail: null
  };
  
  // Convert to WebP and upload each size
  for (const [sizeName, config] of Object.entries(sizes)) {
    const key = `${type}/${entityId}/${sizeName}/${uniqueId}-${baseFilename}.webp`;
    
    const processedBuffer = await sharp(buffer)
      .resize(config.width, null, { 
        fit: 'inside',
        withoutEnlargement: true 
      })
      .webp({ quality: config.quality })
      .toBuffer();
    
    // Upload to R2
    await r2Client.send(new PutObjectCommand({
      Bucket: R2_BUCKET,
      Key: key,
      Body: processedBuffer,
      ContentType: 'image/webp',
      CacheControl: 'public, max-age=31536000' // 1 year cache
    }));
    
    results[sizeName] = `${R2_PUBLIC_URL}/${key}`;
  }
  
  // Also create JPG fallback for original
  const originalKey = `${type}/${entityId}/original/${uniqueId}-${baseFilename}.jpg`;
  const jpgBuffer = await sharp(buffer)
    .jpeg({ quality: 90 })
    .toBuffer();
  
  await r2Client.send(new PutObjectCommand({
    Bucket: R2_BUCKET,
    Key: originalKey,
    Body: jpgBuffer,
    ContentType: 'image/jpeg',
    CacheControl: 'public, max-age=31536000'
  }));
  
  results.original = `${R2_PUBLIC_URL}/${originalKey}`;
  results.imageKey = originalKey;
  
  return results;
}

/**
 * Delete image and all variants from R2
 */
async function deleteImageFromR2(imageKey) {
  try {
    // Extract base path
    const parts = imageKey.split('/');
    const type = parts[0];
    const entityId = parts[1];
    const filename = parts[3];
    const baseFilename = path.basename(filename, path.extname(filename));
    
    // Delete all variants
    const keys = [
      imageKey, // original
      `${type}/${entityId}/large/${baseFilename}.webp`,
      `${type}/${entityId}/medium/${baseFilename}.webp`,
      `${type}/${entityId}/thumbnail/${baseFilename}.webp`
    ];
    
    for (const key of keys) {
      await r2Client.send(new DeleteObjectCommand({
        Bucket: R2_BUCKET,
        Key: key
      }));
    }
  } catch (error) {
    console.error('Error deleting from R2:', error);
    // Don't throw - image might already be deleted
  }
}

