// Bulk delete empty/broken image records across all tables for an account
app.delete('/api/admin/accounts/:accountId/empty-images', async (req, res) => {
  const client = await pool.connect();
  try {
    const accountId = parseInt(req.params.accountId);
    const { checkBroken } = req.query; // ?checkBroken=true to also test URLs for 404s

    await client.query('BEGIN');

    // Delete property_images with empty/null URLs (both url and image_url must be empty)
    const propResult = await client.query(`
      DELETE FROM property_images
      WHERE property_id IN (SELECT id FROM properties WHERE account_id = $1)
        AND (url IS NULL OR url = '')
        AND (image_url IS NULL OR image_url = '')
    `, [accountId]);

    // Delete room_images with empty/null URLs
    const roomResult = await client.query(`
      DELETE FROM room_images
      WHERE room_id IN (SELECT id FROM bookable_units WHERE property_id IN (SELECT id FROM properties WHERE account_id = $1))
        AND (image_url IS NULL OR image_url = '')
    `, [accountId]);

    // Delete gas_sync_images with empty/null URLs
    // gas_sync_properties links to account via connection_id → gas_sync_connections.account_id
    const syncResult = await client.query(`
      DELETE FROM gas_sync_images
      WHERE sync_property_id IN (
        SELECT gsp.id FROM gas_sync_properties gsp
        JOIN gas_sync_connections gsc ON gsp.connection_id = gsc.id
        WHERE gsc.account_id = $1
      )
      AND (original_url IS NULL OR original_url = '')
    `, [accountId]);

    // If checkBroken flag, also test URLs that exist but return 404
    let brokenCount = 0;
    if (checkBroken === 'true') {
      // Get all gas_sync_images with URLs for this account
      const allSyncImages = await client.query(`
        SELECT gsi.id, gsi.original_url FROM gas_sync_images gsi
        WHERE gsi.sync_property_id IN (
          SELECT gsp.id FROM gas_sync_properties gsp
          JOIN gas_sync_connections gsc ON gsp.connection_id = gsc.id
          WHERE gsc.account_id = $1
        )
        AND gsi.original_url IS NOT NULL AND gsi.original_url != ''
      `, [accountId]);

      // Check URLs in batches — HEAD request with timeout
      const brokenIds = [];
      for (const img of allSyncImages.rows) {
        try {
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 5000);
          const resp = await fetch(img.original_url, { method: 'HEAD', signal: controller.signal });
          clearTimeout(timeout);
          if (resp.status === 404 || resp.status === 410) {
            brokenIds.push(img.id);
          }
        } catch (e) {
          // Network error or timeout — treat as broken
          brokenIds.push(img.id);
        }
      }

      if (brokenIds.length > 0) {
        await client.query(`DELETE FROM gas_sync_images WHERE id = ANY($1)`, [brokenIds]);
        brokenCount = brokenIds.length;
      }
    }

    await client.query('COMMIT');

    res.json({
      success: true,
      deleted: {
        property_images: propResult.rowCount,
        room_images: roomResult.rowCount,
        gas_sync_images: syncResult.rowCount,
        broken_url_images: brokenCount,
        total: propResult.rowCount + roomResult.rowCount + syncResult.rowCount + brokenCount
      }
    });
  } catch (error) {
    await client.query('ROLLBACK');
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

// Reimport room images via R2 compression - clears existing and re-copies from gas_sync_images
app.post('/api/admin/rooms/:id/reimport-images', async (req, res) => {
  try {
    const roomId = parseInt(req.params.id);
    
    // Get room info
    const roomResult = await pool.query(
      'SELECT id, name, beds24_room_id, property_id FROM bookable_units WHERE id = $1', [roomId]
    );
    if (roomResult.rows.length === 0) {
      return res.json({ success: false, error: 'Room not found' });
    }
    const room = roomResult.rows[0];
    
    // Find sync property ID for property-level image fallback
    const spResult = await pool.query(
      'SELECT sp.id FROM gas_sync_properties sp WHERE sp.gas_property_id = $1 LIMIT 1', [room.property_id]
    );
    const spId = spResult.rows[0]?.id;
    
    // Get sync images for this room (by beds24_room_id) + property-level images
    let syncImages;
    if (room.beds24_room_id) {
      syncImages = await pool.query(`
        SELECT * FROM gas_sync_images 
        WHERE (room_type_external_id = $1 
               OR (room_type_external_id IS NULL AND sync_property_id = $2))
        ORDER BY sort_order
      `, [String(room.beds24_room_id), spId]);
    } else {
      syncImages = await pool.query(`
        SELECT * FROM gas_sync_images 
        WHERE room_type_external_id IS NULL AND sync_property_id = $1
        ORDER BY sort_order
      `, [spId]);
    }
    
    if (syncImages.rows.length === 0) {
      return res.json({ success: false, error: 'No sync images found for this room', beds24_room_id: room.beds24_room_id });
    }
    
    // Deduplicate by original_url - same image can appear in both property-level and room-level
    const seenUrls = new Set();
    const uniqueImages = syncImages.rows.filter(img => {
      if (!img.original_url || seenUrls.has(img.original_url)) return false;
      seenUrls.add(img.original_url);
      return true;
    });
    
    // Clear existing room_images for this room
    const delResult = await pool.query('DELETE FROM room_images WHERE room_id = $1', [roomId]);
    console.log(`[Reimport] Cleared ${delResult.rowCount} existing images for room ${roomId} (${uniqueImages.length} unique of ${syncImages.rows.length} total)`);
    
    let imported = 0;
    let failed = 0;
    const results = [];
    
    for (const img of uniqueImages) {
      let imageUrl = img.original_url;
      let thumbnailUrl = img.thumbnail_url || img.original_url;
      let imageKey = img.external_id || `beds24-${room.beds24_room_id}-${img.sort_order || 0}`;
      let compressed = false;
      
      try {
        const imgResponse = await axios.get(img.original_url, { 
          responseType: 'arraybuffer', 
          timeout: 30000,
          maxContentLength: 100 * 1024 * 1024
        });
        const buffer = Buffer.from(imgResponse.data);
        const originalSizeKB = (buffer.length / 1024).toFixed(0);
        
        const urlPath = new URL(img.original_url).pathname;
        const filename = path.basename(urlPath) || `beds24-${roomId}-${img.sort_order || 0}.jpg`;
        
        const r2Result = await processAndUploadImage(buffer, 'room', roomId, filename);
        
        imageUrl = r2Result.large || r2Result.original;
        thumbnailUrl = r2Result.thumbnail || r2Result.medium || imageUrl;
        imageKey = r2Result.imageKey || imageKey;
        compressed = true;
        
        console.log(`[Reimport] Room ${roomId}: ${originalSizeKB}KB -> R2: ${imageUrl.substring(0, 80)}`);
      } catch (dlErr) {
        console.warn(`[Reimport] Room ${roomId}: failed to compress, using original: ${dlErr.message}`);
        failed++;
      }
      
      await pool.query(`
        INSERT INTO room_images (room_id, image_key, image_url, thumbnail_url, caption, display_order, upload_source, is_active, is_primary, created_at)
        VALUES ($1, $2, $3, $4, $5, $6, 'beds24_r2', true, $7, NOW())
      `, [roomId, imageKey, imageUrl, thumbnailUrl, img.caption || '', img.sort_order || 0, img.sort_order === 0]);
      
      imported++;
      results.push({ sort_order: img.sort_order, compressed, url: imageUrl.substring(0, 80) });
    }
    
    res.json({ 
      success: true, 
      room_id: roomId,
      room_name: room.name,
      cleared: delResult.rowCount,
      imported,
      failed,
      images: results
    });
  } catch (error) {
    console.error('Reimport images error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Reimport ALL room images for a property via R2 compression - runs in background
app.post('/api/admin/properties/:propertyId/reimport-all-images', async (req, res) => {
  try {
    const propertyId = parseInt(req.params.propertyId);
    
    // Get all rooms for this property
    const roomsResult = await pool.query(
      'SELECT id, name, beds24_room_id FROM bookable_units WHERE property_id = $1 ORDER BY id', [propertyId]
    );
    
    if (roomsResult.rows.length === 0) {
      return res.json({ success: false, error: 'No rooms found for this property' });
    }
    
    const rooms = roomsResult.rows.filter(r => r.beds24_room_id);
    
    // Respond immediately
    res.json({ 
      success: true, 
      message: `Processing ${rooms.length} rooms in background`,
      rooms: rooms.map(r => ({ id: r.id, name: r.name, beds24_room_id: r.beds24_room_id }))
    });
    
    // Process rooms sequentially in the background
    const spResult = await pool.query(
      'SELECT sp.id FROM gas_sync_properties sp WHERE sp.gas_property_id = $1 LIMIT 1', [propertyId]
    );
    const spId = spResult.rows[0]?.id;
    
    for (const room of rooms) {
      try {
        console.log(`[Batch Reimport] Starting room ${room.id} (${room.name})...`);
        
        // Get sync images for this room + property-level
        const syncImages = await pool.query(`
          SELECT * FROM gas_sync_images 
          WHERE (room_type_external_id = $1 
                 OR (room_type_external_id IS NULL AND sync_property_id = $2))
          ORDER BY sort_order
        `, [String(room.beds24_room_id), spId]);
        
        // Deduplicate by original_url
        const seenUrls = new Set();
        const uniqueImages = syncImages.rows.filter(img => {
          if (!img.original_url || seenUrls.has(img.original_url)) return false;
          seenUrls.add(img.original_url);
          return true;
        });
        
        if (uniqueImages.length === 0) {
          console.log(`[Batch Reimport] Room ${room.id}: no sync images, skipping`);
          continue;
        }
        
        // Clear existing
        const delResult = await pool.query('DELETE FROM room_images WHERE room_id = $1', [room.id]);
        
        let imported = 0;
        let failed = 0;
        
        for (const img of uniqueImages) {
          let imageUrl = img.original_url;
          let thumbnailUrl = img.thumbnail_url || img.original_url;
          let imageKey = img.external_id || `beds24-${room.beds24_room_id}-${img.sort_order || 0}`;
          
          try {
            const imgResponse = await axios.get(img.original_url, { 
              responseType: 'arraybuffer', 
              timeout: 60000,
              maxContentLength: 100 * 1024 * 1024
            });
            const buffer = Buffer.from(imgResponse.data);
            
            const urlPath = new URL(img.original_url).pathname;
            const filename = path.basename(urlPath) || `beds24-${room.id}-${img.sort_order || 0}.jpg`;
            
            const r2Result = await processAndUploadImage(buffer, 'room', room.id, filename);
            
            imageUrl = r2Result.large || r2Result.original;
            thumbnailUrl = r2Result.thumbnail || r2Result.medium || imageUrl;
            imageKey = r2Result.imageKey || imageKey;
          } catch (dlErr) {
            console.warn(`[Batch Reimport] Room ${room.id}: download failed: ${dlErr.message}`);
            failed++;
          }
          
          await pool.query(`
            INSERT INTO room_images (room_id, image_key, image_url, thumbnail_url, caption, display_order, upload_source, is_active, is_primary, created_at)
            VALUES ($1, $2, $3, $4, $5, $6, 'beds24_r2', true, $7, NOW())
          `, [room.id, imageKey, imageUrl, thumbnailUrl, img.caption || '', img.sort_order || 0, img.sort_order === 0]);
          
          imported++;
        }
        
        console.log(`[Batch Reimport] Room ${room.id} (${room.name}): cleared ${delResult.rowCount}, imported ${imported}, failed ${failed}`);
        
      } catch (roomErr) {
        console.error(`[Batch Reimport] Room ${room.id} error:`, roomErr.message);
      }
    }
    
    console.log(`[Batch Reimport] Property ${propertyId}: ALL ROOMS COMPLETE`);
    
  } catch (error) {
    console.error('Batch reimport error:', error);
    if (!res.headersSent) {
      res.json({ success: false, error: error.message });
    }
  }
});

// Nuke and reimport ALL images for ALL properties in a deployed site
app.post('/api/admin/sites/:deployedSiteId/reimport-all-images', async (req, res) => {
  try {
    const deployedSiteId = parseInt(req.params.deployedSiteId);
    
    // Get all properties for this site's account
    const siteResult = await pool.query(
      'SELECT account_id, site_name FROM deployed_sites WHERE id = $1', [deployedSiteId]
    );
    if (!siteResult.rows[0]) {
      return res.json({ success: false, error: 'Site not found' });
    }
    const accountId = siteResult.rows[0].account_id;
    const siteName = siteResult.rows[0].site_name;
    
    // Get all properties for this account
    const propsResult = await pool.query(
      'SELECT id, name FROM properties WHERE account_id = $1 OR client_id = $1 ORDER BY id', [accountId]
    );
    
    if (propsResult.rows.length === 0) {
      return res.json({ success: false, error: 'No properties found' });
    }
    
    // Get all rooms across all properties
    const propertyIds = propsResult.rows.map(p => p.id);
    const roomsResult = await pool.query(
      'SELECT id, name, property_id, beds24_room_id FROM bookable_units WHERE property_id = ANY($1) AND beds24_room_id IS NOT NULL ORDER BY property_id, id',
      [propertyIds]
    );
    
    // Respond immediately
    res.json({
      success: true,
      message: `Processing ${propsResult.rows.length} properties, ${roomsResult.rows.length} rooms for site "${siteName}" in background`,
      properties: propsResult.rows.map(p => ({ id: p.id, name: p.name })),
      total_rooms: roomsResult.rows.length
    });
    
    // Process each property's rooms in background
    for (const prop of propsResult.rows) {
      const propRooms = roomsResult.rows.filter(r => r.property_id === prop.id);
      if (propRooms.length === 0) {
        console.log(`[Site Reimport] Property ${prop.id} (${prop.name}): no rooms with beds24, skipping`);
        continue;
      }
      
      const spResult = await pool.query(
        'SELECT id FROM gas_sync_properties WHERE gas_property_id = $1 LIMIT 1', [prop.id]
      );
      const spId = spResult.rows[0]?.id;
      
      console.log(`[Site Reimport] Property ${prop.id} (${prop.name}): ${propRooms.length} rooms`);
      
      for (const room of propRooms) {
        try {
          const syncImages = await pool.query(`
            SELECT * FROM gas_sync_images 
            WHERE (room_type_external_id = $1 
                   OR (room_type_external_id IS NULL AND sync_property_id = $2))
            ORDER BY sort_order
          `, [String(room.beds24_room_id), spId]);
          
          // Deduplicate by original_url
          const seenUrls = new Set();
          const uniqueImages = syncImages.rows.filter(img => {
            if (!img.original_url || seenUrls.has(img.original_url)) return false;
            seenUrls.add(img.original_url);
            return true;
          });
          
          if (uniqueImages.length === 0) {
            console.log(`[Site Reimport] Room ${room.id} (${room.name}): no sync images, skipping`);
            continue;
          }
          
          // Clear existing
          const delResult = await pool.query('DELETE FROM room_images WHERE room_id = $1', [room.id]);
          
          let imported = 0;
          let failed = 0;
          
          for (const img of uniqueImages) {
            let imageUrl = img.original_url;
            let thumbnailUrl = img.thumbnail_url || img.original_url;
            let imageKey = img.external_id || `beds24-${room.beds24_room_id}-${img.sort_order || 0}`;
            
            try {
              const imgResponse = await axios.get(img.original_url, { 
                responseType: 'arraybuffer', 
                timeout: 60000,
                maxContentLength: 100 * 1024 * 1024
              });
              const buffer = Buffer.from(imgResponse.data);
              
              const urlPath = new URL(img.original_url).pathname;
              const filename = path.basename(urlPath) || `beds24-${room.id}-${img.sort_order || 0}.jpg`;
              
              const r2Result = await processAndUploadImage(buffer, 'room', room.id, filename);
              
              imageUrl = r2Result.large || r2Result.original;
              thumbnailUrl = r2Result.thumbnail || r2Result.medium || imageUrl;
              imageKey = r2Result.imageKey || imageKey;
            } catch (dlErr) {
              console.warn(`[Site Reimport] Room ${room.id}: download failed for ${img.original_url}: ${dlErr.message}`);
              failed++;
            }
            
            await pool.query(`
              INSERT INTO room_images (room_id, image_key, image_url, thumbnail_url, caption, display_order, upload_source, is_active, is_primary, created_at)
              VALUES ($1, $2, $3, $4, $5, $6, 'beds24_r2', true, $7, NOW())
            `, [room.id, imageKey, imageUrl, thumbnailUrl, img.caption || '', img.sort_order || 0, img.sort_order === 0]);
            
            imported++;
          }
          
          console.log(`[Site Reimport] Room ${room.id} (${room.name}): cleared ${delResult.rowCount}, imported ${imported}, failed ${failed}`);
          
        } catch (roomErr) {
          console.error(`[Site Reimport] Room ${room.id} error:`, roomErr.message);
        }
      }
      
      console.log(`[Site Reimport] Property ${prop.id} (${prop.name}): COMPLETE`);
    }
    
    console.log(`[Site Reimport] Site ${deployedSiteId} (${siteName}): ALL PROPERTIES COMPLETE`);
    
  } catch (error) {
    console.error('Site reimport error:', error);
    if (!res.headersSent) {
      res.json({ success: false, error: error.message });
    }
  }
});

// Set primary property image
app.put('/api/admin/properties/:propertyId/images/:imageId/primary', async (req, res) => {
  const client = await pool.connect();
  try {
    const { propertyId, imageId } = req.params;
    
    await client.query('BEGIN');
    
    // Remove primary from all images for this property
    await client.query(
      'UPDATE property_images SET is_primary = false WHERE property_id = $1',
      [propertyId]
    );
    
    // Set new primary
    await client.query(
      'UPDATE property_images SET is_primary = true WHERE id = $1',
      [imageId]
    );
    
    await client.query('COMMIT');
    
    res.json({ success: true, message: 'Primary image updated' });
  } catch (error) {
    await client.query('ROLLBACK');
    res.json({ success: false, error: error.message });
  } finally {
    client.release();
  }
});

