// =====================================================

// POST /api/rooms/:id/calculate-occupancy-price - Calculate price for specific occupancy
app.post('/api/rooms/:id/calculate-occupancy-price', async (req, res) => {
  try {
    const roomId = req.params.id;
    const { standard_price, adults, children } = req.body;
    
    // Get room occupancy settings
    const roomResult = await pool.query(`
      SELECT 
        bu.*,
        p.child_max_age
      FROM bookable_units bu
      JOIN properties p ON bu.property_id = p.id
      WHERE bu.id = $1
    `, [roomId]);
    
    if (roomResult.rows.length === 0) {
      return res.json({ success: false, error: 'Room not found' });
    }
    
    const room = roomResult.rows[0];
    const basePrice = parseFloat(standard_price) || 0;
    
    // If per_room mode, just return standard price
    if (room.pricing_mode === 'per_room') {
      return res.json({
        success: true,
        price: basePrice,
        breakdown: {
          standard_price: basePrice,
          adjustments: [],
          final_price: basePrice
        }
      });
    }
    
    // Calculate occupancy-adjusted price
    const baseOccupancy = room.base_occupancy || 2;
    const numAdults = parseInt(adults) || 1;
    const numChildren = parseInt(children) || 0;
    
    let adjustedPrice = basePrice;
    const adjustments = [];
    
    // Single occupancy discount
    if (numAdults === 1 && numChildren === 0 && parseFloat(room.single_discount_value) > 0) {
      let discount = 0;
      if (room.single_discount_type === 'percent') {
        discount = basePrice * (parseFloat(room.single_discount_value) / 100);
      } else {
        discount = parseFloat(room.single_discount_value);
      }
      adjustedPrice -= discount;
      adjustments.push({
        type: 'single_discount',
        description: 'Single occupancy discount',
        amount: -discount
      });
    }
    
    // Extra adults charge
    const extraAdults = Math.max(0, numAdults - baseOccupancy);
    if (extraAdults > 0 && parseFloat(room.extra_adult_charge) > 0) {
      let extraCharge = 0;
      if (room.extra_adult_type === 'percent') {
        extraCharge = basePrice * (parseFloat(room.extra_adult_charge) / 100) * extraAdults;
      } else {
        extraCharge = parseFloat(room.extra_adult_charge) * extraAdults;
      }
      adjustedPrice += extraCharge;
      adjustments.push({
        type: 'extra_adults',
        description: `${extraAdults} extra adult(s)`,
        amount: extraCharge
      });
    }
    
    // Children charge
    if (numChildren > 0 && room.child_charge_type !== 'free' && parseFloat(room.child_charge) > 0) {
      let childCharge = 0;
      if (room.child_charge_type === 'percent') {
        childCharge = basePrice * (parseFloat(room.child_charge) / 100) * numChildren;
      } else {
        childCharge = parseFloat(room.child_charge) * numChildren;
      }
      adjustedPrice += childCharge;
      adjustments.push({
        type: 'children',
        description: `${numChildren} child(ren)`,
        amount: childCharge
      });
    }
    
    res.json({
      success: true,
      price: Math.round(adjustedPrice * 100) / 100,
      breakdown: {
        standard_price: basePrice,
        base_occupancy: baseOccupancy,
        adults: numAdults,
        children: numChildren,
        adjustments,
        final_price: Math.round(adjustedPrice * 100) / 100
      }
    });
  } catch (error) {
    console.error('Error calculating occupancy price:', error);
    res.json({ success: false, error: error.message });
  }
});

// =========================================================
// BEDS24 WEBHOOK - Receive real-time updates
// =========================================================
// Configure this URL in Beds24: Settings > Account > Webhooks
// URL: https://your-domain.railway.app/api/webhooks/beds24

// Webhook financial-refresh debounce queue.
// A single Beds24-side modification often fires 2-5 webhook events in quick
// succession. We coalesce them by booking ID with a 10s timer: each event
// resets the timer; refreshBeds24Booking runs once when the burst quiets.
// In-memory only — webhook events are a hint, not the source of truth; if
// the server restarts mid-burst the daily cron picks up anything missed.
const _webhookRefreshTimers = new Map(); // beds24BookingId → setTimeout handle
const WEBHOOK_REFRESH_DEBOUNCE_MS = 10_000;
function scheduleBeds24FinancialRefresh(beds24BookingId, options = {}) {
  if (!beds24BookingId) return;
  const key = parseInt(beds24BookingId);
  if (!key) return;
  const existing = _webhookRefreshTimers.get(key);
  if (existing) clearTimeout(existing);
  const t = setTimeout(async () => {
    _webhookRefreshTimers.delete(key);
    try {
      const result = await refreshBeds24Booking(key, options);
      console.log(`[Beds24 webhook] refreshed b${key}: gas=${result.gas_booking_id} pay=${result.payments} upd=${result.updated} imp=${result.imported}`);
    } catch (err) {
      console.warn(`[Beds24 webhook] refresh failed for b${key}:`, err.message);
    }
  }, WEBHOOK_REFRESH_DEBOUNCE_MS);
  _webhookRefreshTimers.set(key, t);
}

app.post('/api/webhooks/beds24', async (req, res) => {
  // Log EVERYTHING that comes in
  console.log('=== BEDS24 WEBHOOK RECEIVED ===');
  console.log('Headers:', JSON.stringify(req.headers));
  console.log('Body:', JSON.stringify(req.body));
  console.log('Query:', JSON.stringify(req.query));
  console.log('===============================');

  // Always respond 200 OK immediately so Beds24 doesn't retry
  res.status(200).json({ success: true, received: true });

  // Schedule a debounced financial refresh — runs in background, doesn't
  // block the response. The existing availability/cancel logic below runs
  // in parallel, both feeding off the same payload.
  try {
    const payload = req.body || {};
    const inner = payload.booking || payload;
    const bookingId = inner.id || inner.bookingId || payload.bookingId;
    const roomId = inner.roomId || payload.roomId;
    if (bookingId) scheduleBeds24FinancialRefresh(bookingId, { roomId });
  } catch (e) {
    console.warn('[Beds24 webhook] schedule refresh failed:', e.message);
  }

  // Wrap pool.connect() in try/catch — when Railway/Postgres has a wobble
  // (e.g. the 2026-05-20 build-queue incident) connect() throws, and
  // because we've already sent the 200 response, the rejection has no
  // route handler to catch it → process exits → 502 loop on every retry.
  let client;
  try {
    client = await pool.connect();
  } catch (connectErr) {
    console.error('[Beds24 webhook] pool.connect failed, dropping payload:', connectErr.message);
    return;
  }
  try {
    const webhookData = req.body;
    
    // Beds24 v2 webhook format may have booking data directly or nested
    const booking = webhookData.booking || webhookData;
    
    const eventType = webhookData.action || webhookData.type || webhookData.event || 'unknown';
    const bookingId = booking.id || booking.bookingId || webhookData.bookingId;
    const roomId = booking.roomId || webhookData.roomId;
    const propertyId = booking.propertyId || webhookData.propertyId;
    const status = booking.status || webhookData.status;
    
    console.log(`Webhook parsed - event: ${eventType}, bookingId: ${bookingId}, roomId: ${roomId}, status: ${status}`);
    
    // Handle different scenarios
    // If status is cancelled, re-open dates. Otherwise block them.
    // Beds24 V2 may send status as: 'cancelled', 'Cancelled', 0, '0', or 'black'
    const statusStr = String(status).toLowerCase();
    const eventStr = String(eventType).toLowerCase();
    const isCancelled = statusStr === 'cancelled' || statusStr === '0' || status === 0 ||
                        statusStr === 'black' || statusStr === 'deleted' ||
                        eventStr === 'cancel' || eventStr === 'delete' || eventStr === 'cancelled';
    console.log(`Webhook cancel check - status: '${status}' (type: ${typeof status}), statusStr: '${statusStr}', isCancelled: ${isCancelled}`);
    
    if (roomId) {
      // Find our room by beds24_room_id
      const roomResult = await client.query(`
        SELECT id FROM bookable_units WHERE beds24_room_id = $1
      `, [roomId]);
      
      if (roomResult.rows.length > 0) {
        const ourRoomId = roomResult.rows[0].id;
        const arrival = booking.arrival || booking.firstNight || webhookData.arrival;
        const departure = booking.departure || booking.lastNight || webhookData.departure;
        
        console.log(`Found our room ${ourRoomId}, arrival: ${arrival}, departure: ${departure}, cancelled: ${isCancelled}`);
        
        if (arrival && departure) {
          const startDate = new Date(arrival);
          const endDate = new Date(departure);
          
          await client.query('BEGIN');
          
          // If cancelled, update the GAS booking status
          let updateResult = null;
          if (isCancelled && bookingId) {
            updateResult = await client.query(`
              UPDATE bookings
              SET status = 'cancelled', cancelled_time = NOW(), updated_at = NOW()
              WHERE beds24_booking_id = $1 AND status != 'cancelled'
              RETURNING id, property_id, bookable_unit_id, buyout_block_beds24_ids
            `, [bookingId.toString()]);

            if (updateResult.rowCount > 0) {
              const gasBookingId = updateResult.rows[0].id;
              console.log(`✅ Cancelled GAS booking ${gasBookingId} via webhook (Beds24 booking ${bookingId})`);

              // Buyout cascade release on webhook-driven cancel — when the
              // master gets cancelled from Beds24's UI (operator clicks
              // cancel inside Beds24), our local cancel route never runs,
              // so the block bookings are still on the calendar. Release
              // them here so the dorms/privates open back up too. Per-
              // client OAuth (the blocks were created with it).
              const blocks = Array.isArray(updateResult.rows[0].buyout_block_beds24_ids)
                ? updateResult.rows[0].buyout_block_beds24_ids
                : (typeof updateResult.rows[0].buyout_block_beds24_ids === 'string'
                    ? JSON.parse(updateResult.rows[0].buyout_block_beds24_ids || '[]')
                    : []);
              if (blocks.length) {
                try {
                  const accessToken = await getBeds24AccessTokenForProperty(
                    pool,
                    updateResult.rows[0].property_id,
                    updateResult.rows[0].bookable_unit_id
                  );
                  if (accessToken) {
                    for (const block of blocks) {
                      try {
                        await axios.post('https://beds24.com/api/v2/bookings', [{
                          id: parseInt(block.beds24_id),
                          status: 'cancelled',
                          allowWebhooks: false
                        }], { headers: { 'Content-Type': 'application/json', token: accessToken } });
                        console.log(`[Buyout cascade webhook] cancelled block ${block.beds24_id} on room ${block.room_id}`);
                      } catch (e) {
                        console.warn(`[Buyout cascade webhook] error on ${block.beds24_id}:`, e.response?.data || e.message);
                      }
                    }
                  }
                } catch (e) {
                  console.warn('[Buyout cascade webhook] access token lookup failed:', e.message);
                }
              }
            }
          }
          
          for (let d = new Date(startDate); d < endDate; d.setDate(d.getDate() + 1)) {
            const dateStr = d.toISOString().split('T')[0];
            
            if (isCancelled) {
              // Re-open the dates (include 'booking' source from GAS bookings)
              await client.query(`
                UPDATE room_availability 
                SET is_available = true, is_blocked = false, source = 'beds24_cancel', updated_at = NOW()
                WHERE room_id = $1 AND date = $2 AND source IN ('booking', 'beds24_sync', 'beds24_webhook', 'beds24_inventory', 'beds24_cancel')
              `, [ourRoomId, dateStr]);
            } else {
              // Block the dates. Both is_available=false AND is_blocked=true
              // — the previous INSERT set is_blocked=false and the ON CONFLICT
              // never touched it, creating a mixed state (unavailable but
              // "not blocked") that some readers mis-interpret. Aligns with
              // /api/public/book (server.js:99867) and the Channex webhook
              // fix (2026-07-20).
              await client.query(`
                INSERT INTO room_availability (room_id, date, is_available, is_blocked, source)
                VALUES ($1, $2, false, true, 'beds24_webhook')
                ON CONFLICT (room_id, date)
                DO UPDATE SET is_available = false, is_blocked = true, source = 'beds24_webhook', updated_at = NOW()
              `, [ourRoomId, dateStr]);
            }
          }
          
          await client.query('COMMIT');
          console.log(`✅ Webhook processed: ${isCancelled ? 'UNBLOCKED' : 'BLOCKED'} room ${ourRoomId} from ${arrival} to ${departure}`);
          
          // ========== SEND PARTNER WEBHOOK FOR BEDS24 CANCELLATION ==========
          if (isCancelled && updateResult && updateResult.rowCount > 0) {
            try {
              const gasBookingId = updateResult.rows[0].id;
              const webhookResult = await sendPartnerBookingWebhook(gasBookingId, 'booking.cancelled');
              if (webhookResult.sent) {
                console.log(`[Webhook] Sent booking.cancelled for Beds24-cancelled booking ${gasBookingId}`);
              }
            } catch (webhookError) {
              console.error(`[Webhook] Error sending Beds24 cancellation webhook:`, webhookError.message);
              // Don't fail the webhook processing if partner webhook fails
            }
          }
          // ========== END PARTNER WEBHOOK ==========
        }
      } else {
        console.log(`⚠️ No matching room found for beds24_room_id: ${roomId}`);
      }
    } else {
      console.log('⚠️ No roomId in webhook payload');
    }
    
  } catch (error) {
    console.error('Webhook processing error:', error);
  } finally {
    client.release();
  }
});

