// Mailgun tracking webhook — receives 'opened' and 'clicked' events for
// every email sent via sendEmail. Payload shape (Mailgun v3):
//   { signature: { timestamp, token, signature },
//     event-data: { event: 'opened'|'clicked'|..., message: { headers: { message-id } }, recipient, timestamp } }
// We match by Message-Id (stored in guest_communications.provider_message_id
// wrapped in angle brackets when sent) and set opened_at / clicked_at on
// first occurrence. Signature verified via HMAC-SHA256(api_key, timestamp+token)
// — rejects unsigned/forged payloads. Configure the webhook URL in the
// Mailgun dashboard: https://admin.gas.travel/api/webhooks/mailgun
app.post('/api/webhooks/mailgun', express.json({ limit: '1mb' }), async (req, res) => {
  try {
    const body = req.body || {};
    const sig = body.signature || {};
    const ev = body['event-data'] || {};

    // Verify signature — reject if HMAC doesn't match. Guards against forged
    // "opened" events. Skipped only if MAILGUN_WEBHOOK_SIGNING_KEY isn't
    // configured yet (dev env / initial rollout) — in that case log a warning
    // but accept, so opens tracking starts working before the key is added.
    if (process.env.MAILGUN_WEBHOOK_SIGNING_KEY) {
      const crypto = require('crypto');
      const expected = crypto.createHmac('sha256', process.env.MAILGUN_WEBHOOK_SIGNING_KEY)
        .update(String(sig.timestamp) + String(sig.token))
        .digest('hex');
      if (expected !== sig.signature) {
        console.warn('[mailgun webhook] signature mismatch, rejecting');
        return res.status(401).json({ ok: false, error: 'invalid signature' });
      }
    } else {
      console.warn('[mailgun webhook] MAILGUN_WEBHOOK_SIGNING_KEY not set — accepting unverified payload');
    }

    // Ack fast — Mailgun retries on non-2xx. Process async.
    res.status(200).json({ ok: true });

    const event = String(ev.event || '').toLowerCase();
    // Handled event set:
    //   opened / clicked           → opened_at / clicked_at (engagement)
    //   delivered / accepted       → delivered_at (Mailgun accepted + delivered to recipient MTA)
    //   failed / permanent_fail /  → failed_at + failed_reason + status='failed'
    //   temporary_fail / rejected /   (Mailgun couldn't deliver; guest didn't get it)
    //   bounced
    // Unknown events are logged and ignored.
    const EVENT_TO_COL = {
      opened: 'opened_at',
      clicked: 'clicked_at',
      delivered: 'delivered_at',
      accepted: 'delivered_at'
    };
    const FAIL_EVENTS = new Set(['failed', 'permanent_fail', 'permanent-failure', 'temporary_fail', 'temporary-failure', 'rejected', 'bounced']);
    const isFail = FAIL_EVENTS.has(event);
    const engagementCol = EVENT_TO_COL[event];
    if (!engagementCol && !isFail) {
      console.log(`[mailgun webhook] unhandled event=${event}, ignoring`);
      return;
    }

    // Mailgun's message-id header carries the id without angle brackets;
    // provider_message_id in our DB was stored with the wrapping from the
    // send response (e.g. <20260720100027.19c...@mg.gas.travel>). Match both.
    const rawId = ev.message?.headers?.['message-id'] || ev.message?.headers?.['Message-Id'] || null;
    if (!rawId) {
      console.warn('[mailgun webhook] no message-id in payload, event=' + event);
      return;
    }
    const id1 = String(rawId);
    const id2 = '<' + id1.replace(/^<|>$/g, '') + '>';
    const ts = ev.timestamp || Math.floor(Date.now() / 1000);

    let upd;
    if (isFail) {
      // Reason string — Mailgun includes different fields per event kind:
      //   permanent_fail:  delivery-status.description  OR  reason
      //   bounced:         severity + reason + delivery-status
      //   rejected:        reject.reason
      const reason = ev['delivery-status']?.description
        || ev['delivery-status']?.message
        || ev.reject?.reason
        || ev.reason
        || (event === 'bounced' ? 'Recipient mailbox bounced' : `Mailgun ${event}`);
      upd = await pool.query(
        `UPDATE guest_communications
            SET failed_at = COALESCE(failed_at, to_timestamp($2)),
                failed_reason = COALESCE(failed_reason, $4),
                status = 'failed'
          WHERE provider_message_id = $1 OR provider_message_id = $3
          RETURNING id, booking_id`,
        [id1, ts, id2, String(reason).slice(0, 500)]
      );
    } else {
      upd = await pool.query(
        `UPDATE guest_communications
            SET ${engagementCol} = COALESCE(${engagementCol}, to_timestamp($2))
          WHERE provider_message_id = $1 OR provider_message_id = $3
          RETURNING id, booking_id`,
        [id1, ts, id2]
      );
    }
    if (upd.rowCount > 0) {
      console.log(`[mailgun webhook] ${event} matched comm id=${upd.rows[0].id} booking=${upd.rows[0].booking_id}`);
    } else {
      console.log(`[mailgun webhook] ${event} no matching guest_communications row for message-id ${rawId}`);
    }
  } catch (e) {
    console.error('[mailgun webhook] error:', e.message);
    if (!res.headersSent) res.status(200).json({ ok: false });
  }
});

// =========================================================
// ELEVATE PMS PARTNER API
// =========================================================
// Elevate is a partner (account 92) who manages multiple client sub-accounts
// All partner API calls use: /api/partner/:apiKey/...

const PARTNER_MASTER_ACCOUNT_ID = 92;

// Validate Elevate Partner API key (master account level)
async function validatePartnerKey(apiKey) {
  // Check if this API key belongs to the Elevate master account
  const result = await pool.query(
    'SELECT id, api_key FROM accounts WHERE id = $1 AND api_key = $2 AND status = $3',
    [PARTNER_MASTER_ACCOUNT_ID, apiKey, 'active']
  );
  
  if (result.rows.length > 0) {
    return { valid: true, accountId: PARTNER_MASTER_ACCOUNT_ID };
  }
  
  // Fallback format check
  if (apiKey && apiKey.startsWith('gas_') && apiKey.length > 20) {
    const accountCheck = await pool.query(
      'SELECT id FROM accounts WHERE id = $1 AND api_key = $2',
      [PARTNER_MASTER_ACCOUNT_ID, apiKey]
    );
    if (accountCheck.rows.length > 0) {
      return { valid: true, accountId: PARTNER_MASTER_ACCOUNT_ID };
    }
  }
  
  console.log('[Elevate Partner] API key validation failed');
  return { valid: false };
}

// =====================================================
// AMENITY MATCHING HELPER FUNCTION
// =====================================================

// Amenity matching helper function - matches incoming amenities to master_amenities
async function matchAmenity(rawName, source = 'unknown') {
  const normalized = rawName.toLowerCase().trim();
  
  // 1. Exact match on amenity_code
  let match = await pool.query(`
    SELECT id, amenity_code, amenity_name, category, icon 
    FROM master_amenities 
    WHERE LOWER(amenity_code) = $1 AND is_active = true
  `, [normalized]);
  
  if (match.rows.length > 0) {
    return { matched: true, amenity: match.rows[0], match_type: 'exact_code' };
  }
  
  // 2. Exact match on amenity_name (JSONB contains)
  match = await pool.query(`
    SELECT id, amenity_code, amenity_name, category, icon 
    FROM master_amenities 
    WHERE LOWER(amenity_name::text) LIKE $1 AND is_active = true
  `, [`%${normalized}%`]);
  
  if (match.rows.length > 0) {
    return { matched: true, amenity: match.rows[0], match_type: 'exact_name' };
  }
  
  // 3. Alias match
  match = await pool.query(`
    SELECT id, amenity_code, amenity_name, category, icon 
    FROM master_amenities 
    WHERE aliases IS NOT NULL 
    AND aliases::text ILIKE $1 
    AND is_active = true
  `, [`%${normalized}%`]);
  
  if (match.rows.length > 0) {
    return { matched: true, amenity: match.rows[0], match_type: 'alias' };
  }
  
  // 4. Fuzzy match using similarity (if pg_trgm extension is available)
  try {
    match = await pool.query(`
      SELECT id, amenity_code, amenity_name, category, icon,
             similarity(LOWER(amenity_code), $1) as code_sim,
             similarity(LOWER(amenity_name::text), $1) as name_sim
      FROM master_amenities 
      WHERE is_active = true
      AND (similarity(LOWER(amenity_code), $1) > 0.3 
           OR similarity(LOWER(amenity_name::text), $1) > 0.3)
      ORDER BY GREATEST(similarity(LOWER(amenity_code), $1), similarity(LOWER(amenity_name::text), $1)) DESC
      LIMIT 1
    `, [normalized]);
    
    if (match.rows.length > 0) {
      return { matched: true, amenity: match.rows[0], match_type: 'fuzzy', confidence: Math.max(match.rows[0].code_sim, match.rows[0].name_sim) };
    }
  } catch (e) {
    // pg_trgm extension not installed, skip fuzzy matching
  }
  
  // 5. No match - log for manual mapping
  try {
    await pool.query(`
      INSERT INTO unmatched_amenities (source, raw_name, last_seen) 
      VALUES ($1, $2, NOW())
      ON CONFLICT (source, raw_name) DO UPDATE SET 
        occurrence_count = unmatched_amenities.occurrence_count + 1,
        last_seen = NOW()
    `, [source, rawName]);
  } catch (e) {
    // Table might not exist yet, ignore
  }
  
  return { matched: false, raw_name: rawName };
}

// =====================================================
// PARTNER API - TENANT MANAGEMENT
// =====================================================
// New Partner API for Elevate to manage tenants (Sub Masters)
// Base URL: /api/partner/...
// Authentication: X-API-Key header with Elevate's API key

// Validate Partner API key from header
async function validatePartnerApiKey(req) {
  const apiKey = req.headers['x-api-key'];
  if (apiKey) {
    // Check if this API key belongs to an agency_admin account
    const result = await pool.query(
      `SELECT id, name, role, booking_webhook_url, webhook_secret FROM accounts
       WHERE api_key = $1 AND status = 'active' AND role = 'agency_admin'`,
      [apiKey]
    );

    if (result.rows.length > 0) {
      return {
        valid: true,
        partnerId: result.rows[0].id,
        partnerName: result.rows[0].name,
        webhookUrl: result.rows[0].booking_webhook_url,
        webhookSecret: result.rows[0].webhook_secret
      };
    }
    return { valid: false, error: 'Invalid API key' };
  }

  // Fallback: Bearer token auth (admin panel)
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.split(' ')[1];
    const session = await pool.query(
      'SELECT account_id FROM account_sessions WHERE token = $1 AND expires_at > NOW()',
      [token]
    );
    if (session.rows.length > 0) {
      const adminAccountId = session.rows[0].account_id;
      const adminAccount = await pool.query('SELECT id, name, role FROM accounts WHERE id = $1', [adminAccountId]);
      if (adminAccount.rows.length > 0) {
        const role = adminAccount.rows[0].role;
        // Admin users: resolve partnerId from the website being accessed
        if ((role === 'master_admin' || role === 'agency_admin') && req.params.websiteId) {
          const site = await pool.query('SELECT account_id FROM deployed_sites WHERE id = $1', [req.params.websiteId]);
          if (site.rows.length > 0) {
            return { valid: true, partnerId: site.rows[0].account_id, partnerName: adminAccount.rows[0].name };
          }
        }
        // Non-admin or no websiteId: use own account_id
        return { valid: true, partnerId: adminAccountId, partnerName: adminAccount.rows[0].name };
      }
    }
    return { valid: false, error: 'Invalid or expired session' };
  }

  return { valid: false, error: 'Missing X-API-Key header or Authorization token' };
}

// =====================================================
// PARTNER API - URL PATTERN ALIAS
// Elevate calls /api/partner/{apiKey}/{websiteId}/endpoint but website
// management routes use /api/partner/websites/{websiteId}/endpoint with
// the API key in the X-API-Key header. This middleware rewrites the URL
// so both patterns work.
const partnerWebsiteEndpoints = new Set([
  'contact-page', 'styles', 'hero', 'icons', 'logo', 'header',
  'rooms-page', 'services', 'domain', 'status', 'subdomain',
  'name', 'credentials', 'analytics', 'deploy', 'rooms', 'pages',
  'content', 'upload'
]);
app.use((req, res, next) => {
  const m = req.path.match(/^\/api\/partner\/([^/]+)\/(\d+)\/(.+)$/);
  if (m && m[1].startsWith('gas_')) {
    const topLevel = m[3].split('/')[0];
    if (partnerWebsiteEndpoints.has(topLevel)) {
      req.headers['x-api-key'] = req.headers['x-api-key'] || m[1];
      req.url = `/api/partner/websites/${m[2]}/${m[3]}${req.url.includes('?') ? req.url.substring(req.url.indexOf('?')) : ''}`;
    }
  }
  next();
});

