// Get client info by public_id (for setup page - public endpoint)
app.get('/api/client/setup/:publicId', async (req, res) => {
  try {
    const { publicId } = req.params;
    
    // Validate UUID format
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(publicId)) {
      return res.json({ success: false, error: 'Invalid setup link' });
    }
    
    const result = await pool.query(`
      SELECT id, public_id, name, business_name, email, plan, status, created_at
      FROM clients 
      WHERE public_id = $1
    `, [publicId]);
    
    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Account not found' });
    }
    
    res.json({ success: true, client: result.rows[0] });
  } catch (error) {
    console.error('Client setup error:', error);
    res.json({ success: false, error: 'Unable to load account' });
  }
});

// Get all clients (admin view) - excludes clients that are agencies
app.get('/api/admin/clients', async (req, res) => {
  // Source: accounts table (modern). The legacy 'clients' table is no
  // longer the source of truth for the agency-client relationship — the
  // master-admin UI sets accounts.managed_by_id when assigning an agency.
  // Return shape keeps the legacy 'agency_id' alias (mapped from
  // managed_by_id) so existing front-end filters / id-matching keep
  // working without re-writing the UI.
  try {
    const result = await pool.query(`
      SELECT
        a.id,
        a.name,
        a.email,
        a.phone,
        a.business_name,
        a.role,
        a.public_id,
        a.created_at,
        a.managed_by_id AS agency_id,
        (SELECT COUNT(*) FROM properties p WHERE p.account_id = a.id)::int AS property_count,
        (SELECT COUNT(*) FROM bookable_units bu
           JOIN properties p2 ON p2.id = bu.property_id
          WHERE p2.account_id = a.id)::int AS room_count,
        0 AS total_bookings
      FROM accounts a
      WHERE a.role IN ('admin', 'submaster_admin')
      ORDER BY a.created_at DESC
    `);

    res.json({ success: true, clients: result.rows });
  } catch (error) {
    console.error('Get clients error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Get single client with details
app.get('/api/admin/clients/:id', async (req, res) => {
  try {
    const { id } = req.params;
    
    const client = await pool.query(`SELECT * FROM clients WHERE id = $1`, [id]);
    
    if (client.rows.length === 0) {
      return res.json({ success: false, error: 'Client not found' });
    }
    
    // Get client's properties
    const properties = await pool.query(`
      SELECT p.*, COUNT(r.id) as room_count
      FROM properties p
      LEFT JOIN rooms r ON r.property_id = p.id
      WHERE p.client_id = $1
      GROUP BY p.id
      ORDER BY p.name
    `, [id]);
    
    // Get client's users
    const users = await pool.query(`
      SELECT id, email, first_name, last_name, role, status, last_login_at, created_at
      FROM client_users
      WHERE client_id = $1
      ORDER BY role, created_at
    `, [id]);
    
    res.json({ 
      success: true, 
      client: client.rows[0],
      properties: properties.rows,
      users: users.rows,
      connections: []
    });
  } catch (error) {
    console.error('Get client error:', error);
    res.json({ success: false, error: error.message });
  }
});

