// AI Generate Blog Post from Keyword
app.post('/api/admin/blog/generate', async (req, res) => {
    try {
        const { keyword, property_id, language = 'en', event_date, event_location, event_description, account_id } = req.body;

        if (!keyword) {
            return res.json({ success: false, error: 'keyword is required' });
        }

        // Freemium gate: 3 free blog generations (Master Build Plan Step 11)
        if (account_id) {
            const access = await checkGASAccess(account_id, 'blog');
            if (!access.allowed) {
                const countResult = await pool.query('SELECT blog_preview_count FROM accounts WHERE id = $1', [account_id]);
                const count = countResult.rows[0]?.blog_preview_count || 0;
                if (count >= 3) {
                    return res.json({ success: false, error: 'freemium_limit', message: 'You have used your 3 free blog generations. Subscribe to Blog + Attractions AI to continue.', preview_count: count });
                }
                await pool.query('UPDATE accounts SET blog_preview_count = blog_preview_count + 1 WHERE id = $1', [account_id]);
            }
        }

        // Get property details for context
        let propertyContext = '';
        let propertyName = '';
        if (property_id) {
            const propResult = await pool.query(`
                SELECT p.*, a.name as account_name 
                FROM properties p 
                LEFT JOIN accounts a ON p.client_id = a.id 
                WHERE p.id = $1
            `, [property_id]);
            
            if (propResult.rows[0]) {
                const prop = propResult.rows[0];
                propertyName = prop.name;
                propertyContext = `
Property: ${prop.name}
Location: ${prop.address || ''}, ${prop.city || ''}, ${prop.state || ''}, ${prop.country || ''}
Type: ${prop.property_type || 'Holiday accommodation'}
Description: ${prop.description || ''}
`;
            }
        }
        
        // Build event context if this is about an event
        let eventContext = '';
        if (event_date) {
            const eventDateObj = new Date(event_date);
            const formattedDate = eventDateObj.toLocaleDateString('en-US', { 
                weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' 
            });
            eventContext = `
EVENT INFORMATION:
- Event Date: ${formattedDate}
- Event Location: ${event_location || 'See event details'}
- Event Details: ${event_description || 'Local event'}

IMPORTANT: This is a blog post about an upcoming event. Make sure to:
- Prominently mention the event date (${formattedDate}) early in the article
- Include practical information for visitors attending this event
- Suggest booking accommodation at the property for this event
- Create urgency around booking before the event date
`;
        }
        
        // Get nearby attractions for context
        let attractionsContext = '';
        if (property_id) {
            const attractionsResult = await pool.query(`
                SELECT name, description, category 
                FROM attractions 
                WHERE property_id = $1 AND is_published = true
                LIMIT 5
            `, [property_id]);
            
            if (attractionsResult.rows.length > 0) {
                attractionsContext = '\nNearby Attractions:\n' + 
                    attractionsResult.rows.map(a => `- ${a.name} (${a.category}): ${a.description || ''}`).join('\n');
            }
        }
        
        const languageNames = {
            'en': 'English',
            'es': 'Spanish',
            'de': 'German',
            'fr': 'French',
            'it': 'Italian',
            'nl': 'Dutch',
            'pt': 'Portuguese',
            'pl': 'Polish'
        };
        
        const languageName = languageNames[language] || 'English';
        
        console.log(`Generating blog post for keyword: "${keyword}" in ${languageName}${event_date ? ' (EVENT: ' + event_date + ')' : ''}`);
        
        const prompt = `You are a professional travel and hospitality content writer. Write an engaging, SEO-optimized blog post about the following topic.

Keyword to target: "${keyword}"
Language: ${languageName}
${propertyContext}
${eventContext}
${attractionsContext}

Requirements:
1. Write a compelling title that includes the keyword naturally
2. Write 600-800 words of high-quality, engaging content
3. Include the keyword naturally 3-5 times throughout the article
4. Structure with clear headings (H2, H3)
5. Include practical tips or information visitors would find useful
6. End with a subtle call-to-action encouraging booking
7. Write in ${languageName}
8. Include 3-5 FAQ questions and answers based on the content
${event_date ? '9. IMPORTANT: Mention the specific event date prominently in the content' : ''}

Return your response in this exact JSON format:
{
    "title": "The blog post title",
    "excerpt": "A 150-character summary for SEO",
    "content": "The full blog post content in HTML format with <h2>, <h3>, <p> tags",
    "meta_title": "SEO title (max 60 chars)",
    "meta_description": "SEO description (max 160 chars)",
    "suggested_tags": ["tag1", "tag2", "tag3"],
    "faq": [
        {"question": "Question 1?", "answer": "Answer 1"},
        {"question": "Question 2?", "answer": "Answer 2"},
        {"question": "Question 3?", "answer": "Answer 3"}
    ]
}`;

        const claudeResponse = await axios.post('https://api.anthropic.com/v1/messages', {
            model: 'claude-sonnet-4-6',
            max_tokens: 2000,
            messages: [{ role: 'user', content: prompt }]
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01'
            }
        });
        
        const responseText = claudeResponse.data.content[0].text;
        console.log('AI Response (first 500 chars):', responseText.substring(0, 500));
        
        // Parse the JSON response
        let blogData;
        try {
            // Extract JSON from response (handle markdown code blocks)
            let cleanText = responseText;
            // Remove markdown code fences if present
            cleanText = cleanText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
            
            // Try direct parse first
            try {
                blogData = JSON.parse(cleanText);
            } catch (e1) {
                // Try extracting JSON object
                const jsonMatch = cleanText.match(/\{[\s\S]*\}/);
                if (jsonMatch) {
                    try {
                        blogData = JSON.parse(jsonMatch[0]);
                    } catch (e2) {
                        // Fix common JSON issues: unescaped newlines and quotes in content
                        let fixedJson = jsonMatch[0];
                        // Replace literal newlines inside strings
                        fixedJson = fixedJson.replace(/(?<=":[ ]*")([\s\S]*?)(?="[ ]*[,}])/g, function(match) {
                            return match.replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t');
                        });
                        try {
                            blogData = JSON.parse(fixedJson);
                        } catch (e3) {
                            // Last resort: extract fields manually
                            console.error('All JSON parse attempts failed, trying field extraction');
                            const titleMatch = cleanText.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
                            const excerptMatch = cleanText.match(/"excerpt"\s*:\s*"((?:[^"\\]|\\.)*)"/);
                            const contentMatch = cleanText.match(/"content"\s*:\s*"([\s\S]*?)"\s*,\s*"meta_title"/);
                            const metaTitleMatch = cleanText.match(/"meta_title"\s*:\s*"((?:[^"\\]|\\.)*)"/);
                            const metaDescMatch = cleanText.match(/"meta_description"\s*:\s*"((?:[^"\\]|\\.)*)"/);
                            
                            if (titleMatch && contentMatch) {
                                blogData = {
                                    title: titleMatch[1],
                                    excerpt: excerptMatch ? excerptMatch[1] : '',
                                    content: contentMatch[1].replace(/\\n/g, '\n').replace(/\\"/g, '"'),
                                    meta_title: metaTitleMatch ? metaTitleMatch[1] : titleMatch[1].substring(0, 60),
                                    meta_description: metaDescMatch ? metaDescMatch[1] : (excerptMatch ? excerptMatch[1] : ''),
                                    suggested_tags: [],
                                    faq: []
                                };
                            } else {
                                throw new Error('Could not extract blog fields from response');
                            }
                        }
                    }
                } else {
                    throw new Error('No JSON found in response');
                }
            }
        } catch (parseError) {
            console.error('Failed to parse AI response:', parseError);
            console.error('Raw response:', responseText.substring(0, 1000));
            return res.json({ success: false, error: 'Failed to parse AI response' });
        }
        
        res.json({
            success: true,
            blog: {
                title: blogData.title,
                excerpt: blogData.excerpt,
                content: blogData.content,
                meta_title: blogData.meta_title,
                meta_description: blogData.meta_description,
                suggested_tags: blogData.suggested_tags || [],
                keyword: keyword,
                property_id: property_id,
                property_name: propertyName,
                language: language,
                faq: blogData.faq || [],
                faq_schema: blogData.faq && blogData.faq.length > 0 ? {
                    "@context": "https://schema.org",
                    "@type": "FAQPage",
                    "mainEntity": blogData.faq.map(item => ({
                        "@type": "Question",
                        "name": item.question,
                        "acceptedAnswer": {
                            "@type": "Answer",
                            "text": item.answer
                        }
                    }))
                } : null
            }
        });
        
    } catch (error) {
        console.error('AI Blog generation error:', error);
        res.json({ success: false, error: error.message });
    }
});

// Regenerate FAQ schema from existing content (blog or attraction)
app.post('/api/admin/regenerate-faqs', async (req, res) => {
    try {
        const { title, content, type } = req.body;
        if (!content) {
            return res.json({ success: false, error: 'Content is required' });
        }

        const prompt = `Based on the following ${type || 'article'} content, generate 3-5 FAQ questions and answers that would be useful for readers/visitors.

Title: ${title || 'Untitled'}

Content:
${typeof content === 'string' ? content.replace(/<[^>]+>/g, ' ').substring(0, 3000) : ''}

Return ONLY a JSON array of FAQ objects in this format:
[
    {"question": "Question 1?", "answer": "Answer 1"},
    {"question": "Question 2?", "answer": "Answer 2"},
    {"question": "Question 3?", "answer": "Answer 3"}
]`;

        const claudeResponse = await axios.post('https://api.anthropic.com/v1/messages', {
            model: 'claude-sonnet-4-6',
            max_tokens: 1000,
            messages: [{ role: 'user', content: prompt }]
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01'
            }
        });

        const responseText = claudeResponse.data.content[0].text;
        let cleanText = responseText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
        let faqs;
        try {
            faqs = JSON.parse(cleanText);
        } catch (e) {
            const jsonMatch = cleanText.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                faqs = JSON.parse(jsonMatch[0]);
            } else {
                throw new Error('Could not parse FAQ response');
            }
        }

        const faqSchema = {
            "@context": "https://schema.org",
            "@type": "FAQPage",
            "mainEntity": faqs.map(item => ({
                "@type": "Question",
                "name": item.question,
                "acceptedAnswer": {
                    "@type": "Answer",
                    "text": item.answer
                }
            }))
        };

        res.json({ success: true, faq: faqs, faq_schema: faqSchema });
    } catch (error) {
        console.error('FAQ regeneration error:', error);
        res.json({ success: false, error: error.message });
    }
});

// Get blog topic suggestions for a property
app.get('/api/admin/blog/suggestions', async (req, res) => {
    try {
        const { property_id } = req.query;
        
        // Get property info for variable replacement
        let propertyData = { city: '', region: '', country: '' };
        if (property_id) {
            const propResult = await pool.query(
                'SELECT name, city, state, country, property_type FROM properties WHERE id = $1',
                [property_id]
            );
            if (propResult.rows[0]) {
                propertyData = propResult.rows[0];
            }
        }
        
        // Get all active templates
        const templates = await pool.query(
            'SELECT * FROM blog_topic_templates WHERE is_active = true ORDER BY sort_order, category'
        );
        
        // Replace variables in templates
        const suggestions = templates.rows.map(t => {
            let topic = t.template;
            topic = topic.replace(/{city}/g, propertyData.city || 'your area');
            topic = topic.replace(/{region}/g, propertyData.state || 'the region');
            topic = topic.replace(/{country}/g, propertyData.country || '');
            topic = topic.replace(/{location}/g, propertyData.city || propertyData.state || 'your location');
            
            return {
                id: t.id,
                category: t.category,
                topic: topic,
                template: t.template,
                description: t.description
            };
        });
        
        // Group by category
        const grouped = {};
        suggestions.forEach(s => {
            if (!grouped[s.category]) grouped[s.category] = [];
            grouped[s.category].push(s);
        });
        
        // Get existing attractions for this property as additional suggestions
        let attractionSuggestions = [];
        if (property_id) {
            const attractions = await pool.query(
                'SELECT name, category FROM attractions WHERE property_id = $1 LIMIT 10',
                [property_id]
            );
            attractionSuggestions = attractions.rows.map(a => ({
                category: 'attractions',
                topic: `Guide to ${a.name}`,
                description: `Write about the ${a.category} attraction`
            }));
        }
        
        res.json({ 
            success: true, 
            suggestions: grouped,
            attractionSuggestions,
            propertyData
        });
    } catch (error) {
        console.error('Blog suggestions error:', error);
        res.json({ success: false, error: error.message });
    }
});

