// Get Search Console site summary (totals)
app.get('/api/admin/seo/summary', async (req, res) => {
    try {
        const sc = await getSearchConsoleClient();
        if (!sc) {
            return res.json({ success: false, error: 'Google APIs not configured' });
        }

        const { site_url, start_date, end_date } = req.query;

        if (!site_url) {
            return res.json({ success: false, error: 'site_url required' });
        }

        const endDate = end_date || new Date().toISOString().split('T')[0];
        const startDate = start_date || new Date(Date.now() - 28 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

        // Get current period
        const currentResponse = await _scQueryWithFallback(site_url, {
            startDate: startDate,
            endDate: endDate,
            dataState: 'final'
        });

        // Get previous period for comparison
        const daysDiff = Math.round((new Date(endDate) - new Date(startDate)) / (1000 * 60 * 60 * 24));
        const prevEndDate = new Date(new Date(startDate).getTime() - 1 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        const prevStartDate = new Date(new Date(prevEndDate).getTime() - daysDiff * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

        const prevResponse = await _scQueryWithFallback(site_url, {
            startDate: prevStartDate,
            endDate: prevEndDate,
            dataState: 'final'
        });
        
        const current = currentResponse.data.rows?.[0] || { clicks: 0, impressions: 0, ctr: 0, position: 0 };
        const previous = prevResponse.data.rows?.[0] || { clicks: 0, impressions: 0, ctr: 0, position: 0 };
        
        res.json({ 
            success: true,
            current: {
                clicks: current.clicks || 0,
                impressions: current.impressions || 0,
                ctr: ((current.ctr || 0) * 100).toFixed(2),
                position: (current.position || 0).toFixed(1)
            },
            previous: {
                clicks: previous.clicks || 0,
                impressions: previous.impressions || 0,
                ctr: ((previous.ctr || 0) * 100).toFixed(2),
                position: (previous.position || 0).toFixed(1)
            },
            change: {
                clicks: current.clicks - (previous.clicks || 0),
                impressions: current.impressions - (previous.impressions || 0),
                ctr: (((current.ctr || 0) - (previous.ctr || 0)) * 100).toFixed(2),
                position: ((previous.position || 0) - (current.position || 0)).toFixed(1) // Inverted: lower is better
            },
            period: { 
                current: { start: startDate, end: endDate },
                previous: { start: prevStartDate, end: prevEndDate }
            }
        });
    } catch (error) {
        console.error('Search Console summary error:', error);
        if (_scAuthError(res, error)) return;
        res.json({ success: false, error: error.message });
    }
});

// List sites in Search Console
app.get('/api/admin/seo/sites', async (req, res) => {
    try {
        if (!searchConsole) {
            return res.json({ success: false, error: 'Google APIs not configured' });
        }

        const { account_id } = req.query;

        // Query both auth sources and merge — service account first
        // (owns properties it created), user OAuth as fallback (owns
        // properties Steve imported/verified himself). De-dupe on URL.
        const collected = new Map();
        try {
            const saResp = await searchConsole.sites.list();
            (saResp.data.siteEntry || []).forEach(s => {
                collected.set(s.siteUrl, { url: s.siteUrl, permission: s.permissionLevel, via: 'service_account' });
            });
        } catch (e) { /* swallow — user OAuth may still have properties */ }
        try {
            const userAuth = await getUserAuthClient();
            if (userAuth) {
                const userSc = google.searchconsole({ version: 'v1', auth: userAuth });
                const uResp = await userSc.sites.list();
                (uResp.data.siteEntry || []).forEach(s => {
                    if (!collected.has(s.siteUrl)) {
                        collected.set(s.siteUrl, { url: s.siteUrl, permission: s.permissionLevel, via: 'user_oauth' });
                    }
                });
            }
        } catch (e) { /* swallow — service-account list may already cover it */ }

        let sites = Array.from(collected.values());

        // Filter out only sites.gas.travel parent — keep sc-domain:
        // properties so domain-verified sites appear in the dropdown.
        // (Previous filter dropped them silently; Steve 2026-08-19.)
        sites = sites.filter(site =>
            site.url !== 'https://sites.gas.travel/' &&
            site.url !== 'https://sites.gas.travel'
        );
        
        // Get all active deployed sites from database
        const activeSitesQuery = account_id && account_id !== 'null'
            ? await pool.query(
                'SELECT site_url FROM deployed_sites WHERE account_id = $1 AND status != $2',
                [account_id, 'deleted']
              )
            : await pool.query(
                'SELECT site_url FROM deployed_sites WHERE status != $1',
                ['deleted']
              );
        
        const activeUrls = activeSitesQuery.rows.map(r => r.site_url?.replace(/\/$/, ''));
        
        // Only show sites that exist in deployed_sites (not deleted)
        sites = sites.filter(site => {
            const siteUrlClean = site.url.replace(/\/$/, '').replace('https://', '').replace('http://', '');
            return activeUrls.some(url => {
                const urlClean = url?.replace('https://', '').replace('http://', '');
                return urlClean && (siteUrlClean.includes(urlClean) || urlClean.includes(siteUrlClean));
            });
        });
        
        res.json({ success: true, sites });
    } catch (error) {
        console.error('Search Console sites error:', error);
        res.json({ success: false, error: error.message });
    }
});

// Diagnostic: dump every GSC property + probe each URL variant to see
// which one has data. Master-only. Add ?site=moonriverbedandbreakfast.com
// (bare host — we test all variants). Steve 2026-08-19 — Moonriver
// dashboard shows blanks despite verified/sitemap-live for 40+ days.
// This endpoint deliberately BYPASSES the dead-token cache — it's a
// diagnostic tool, and it should probe the live token state fresh
// even when the cache says the token was dead 30s ago.
app.get('/api/admin/seo/debug-site', async (req, res) => {
    try {
        // Force-clear dead cache so we probe the actual current token
        clearUserOAuthDeadCache();
        const userAuth = await getUserAuthClient();
        const sc = userAuth
            ? google.searchconsole({ version: 'v1', auth: userAuth })
            : searchConsole;
        if (!sc) return res.json({ error: 'Google APIs not configured' });
        const bareHost = (req.query.site || '').replace(/^https?:\/\//, '').replace(/\/$/, '');
        if (!bareHost) return res.json({ error: 'pass ?site=hostname (no protocol)' });

        // 1. All properties this OAuth account can see (UNFILTERED)
        const sitesList = await sc.sites.list();
        const allProps = (sitesList.data.siteEntry || []).map(s => ({
            url: s.siteUrl,
            permission: s.permissionLevel,
        }));

        // 2. Just the ones matching this host (any variant)
        const matching = allProps.filter(p => p.url.includes(bareHost));

        // 3. Probe every URL variant with a 90-day searchanalytics query
        const endDate = new Date().toISOString().split('T')[0];
        const startDate = new Date(Date.now() - 90 * 86400000).toISOString().split('T')[0];
        const variants = [
            `https://${bareHost}/`,
            `https://${bareHost}`,
            `http://${bareHost}/`,
            `https://www.${bareHost}/`,
            `sc-domain:${bareHost}`,
        ];
        const probes = [];
        for (const v of variants) {
            try {
                const r = await sc.searchanalytics.query({
                    siteUrl: v,
                    requestBody: { startDate, endDate, dimensions: ['query'], rowLimit: 3, dataState: 'final' },
                });
                probes.push({
                    variant: v,
                    ok: true,
                    rowCount: (r.data.rows || []).length,
                    sampleTopKeyword: r.data.rows?.[0]?.keys?.[0] || null,
                    totalClicks: (r.data.rows || []).reduce((n, row) => n + (row.clicks || 0), 0),
                });
            } catch (e) {
                probes.push({ variant: v, ok: false, error: e.message });
            }
        }

        res.json({
            bareHost,
            allProps,
            matching,
            probes,
            period: { start: startDate, end: endDate },
        });
    } catch (e) {
        res.json({ error: e.message });
    }
});

// Get SEO opportunities (keywords ranking 5-20 with high impressions)
app.get('/api/admin/seo/opportunities', async (req, res) => {
    try {
        const sc = await getSearchConsoleClient();
        if (!sc) {
            return res.json({ success: false, error: 'Google APIs not configured' });
        }

        const { site_url } = req.query;

        if (!site_url) {
            return res.json({ success: false, error: 'site_url required' });
        }

        const endDate = new Date().toISOString().split('T')[0];
        const startDate = new Date(Date.now() - 28 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

        const response = await _scQueryWithFallback(site_url, {
            startDate: startDate,
            endDate: endDate,
            dimensions: ['query'],
            rowLimit: 500,
            dataState: 'final'
        });

        // Filter for opportunities: position 5-20 with decent impressions
        const opportunities = (response.data.rows || [])
            .filter(row => row.position >= 5 && row.position <= 20 && row.impressions >= 10)
            .sort((a, b) => b.impressions - a.impressions)
            .slice(0, 20)
            .map(row => ({
                keyword: row.keys[0],
                clicks: row.clicks,
                impressions: row.impressions,
                ctr: (row.ctr * 100).toFixed(2),
                position: row.position.toFixed(1),
                potential: Math.round(row.impressions * 0.1) // Estimated clicks if moved to top 3
            }));
        
        res.json({ 
            success: true, 
            opportunities,
            suggestion: 'These keywords rank 5-20 with good impressions. Create content to boost rankings!'
        });
    } catch (error) {
        console.error('Search Console opportunities error:', error);
        if (_scAuthError(res, error)) return;
        res.json({ success: false, error: error.message });
    }
});

// Auto-create GA4 property for a new site
const GA4_ACCOUNT_ID = '378182832';

app.post('/api/admin/seo/create-property', async (req, res) => {
    try {
        if (!analyticsAdmin) {
            return res.json({ success: false, error: 'Google APIs not configured' });
        }
        
        const { property_name, site_url, timezone = 'Europe/London', currency = 'GBP' } = req.body;
        
        if (!property_name || !site_url) {
            return res.json({ success: false, error: 'property_name and site_url are required' });
        }
        
        console.log(`Creating GA4 property: ${property_name} for ${site_url}`);
        
        // Step 1: Create the GA4 property
        const propertyResponse = await analyticsAdmin.properties.create({
            requestBody: {
                parent: `accounts/${GA4_ACCOUNT_ID}`,
                displayName: property_name,
                timeZone: timezone,
                currencyCode: currency,
                industryCategory: 'TRAVEL',
                propertyType: 'PROPERTY_TYPE_ORDINARY'
            }
        });
        
        const propertyId = propertyResponse.data.name; // Format: properties/123456789
        console.log(`Created GA4 property: ${propertyId}`);
        
        // Step 2: Create a web data stream
        const streamResponse = await analyticsAdmin.properties.dataStreams.create({
            parent: propertyId,
            requestBody: {
                type: 'WEB_DATA_STREAM',
                displayName: `${property_name} - Website`,
                webStreamData: {
                    defaultUri: site_url
                }
            }
        });
        
        const measurementId = streamResponse.data.webStreamData?.measurementId;
        console.log(`Created data stream with Measurement ID: ${measurementId}`);
        
        res.json({ 
            success: true, 
            property_id: propertyId,
            measurement_id: measurementId,
            message: `GA4 property created: ${measurementId}`
        });
        
    } catch (error) {
        console.error('Create GA4 property error:', error);
        res.json({ success: false, error: error.message });
    }
});

/**
 * Backfill GA4 + Search Console for every deployed_site that's missing a
 * ga4_measurement_id. Mirrors the auto-setup block in the deploy flow but
 * runs on demand for sites deployed before that flow existed.
 * Master admin only. Idempotent: skips sites that already have an ID.
 */
app.post('/api/admin/seo/backfill-ga4', async (req, res) => {
    try {
        if (!await requireMasterAdmin(req, res)) return;
        if (!analyticsAdmin || !searchConsole) {
            return res.json({ success: false, error: 'Google APIs not configured' });
        }

        const missingSites = await pool.query(`
            SELECT ds.id, ds.site_url, ds.account_id, a.name AS account_name
            FROM deployed_sites ds
            LEFT JOIN accounts a ON a.id = ds.account_id
            WHERE (ds.ga4_measurement_id IS NULL OR ds.ga4_measurement_id = '')
              AND ds.site_url IS NOT NULL
              AND ds.site_url <> ''
            ORDER BY ds.id
        `);

        const results = [];
        for (const row of missingSites.rows) {
            const siteUrl = row.site_url;
            // Display name shown in the GA4 UI — account name if we have it,
            // otherwise the host stripped from the URL.
            let displayName = row.account_name;
            if (!displayName) {
                try { displayName = new URL(siteUrl).hostname; } catch { displayName = siteUrl; }
            }

            const result = { site_url: siteUrl, account_id: row.account_id, deployed_site_id: row.id };
            try {
                const propertyResponse = await analyticsAdmin.properties.create({
                    requestBody: {
                        parent: `accounts/${GA4_ACCOUNT_ID}`,
                        displayName,
                        timeZone: 'Europe/London',
                        currencyCode: 'GBP',
                        industryCategory: 'TRAVEL',
                        propertyType: 'PROPERTY_TYPE_ORDINARY'
                    }
                });
                const propertyId = propertyResponse.data.name;

                const streamResponse = await analyticsAdmin.properties.dataStreams.create({
                    parent: propertyId,
                    requestBody: {
                        type: 'WEB_DATA_STREAM',
                        displayName: `${displayName} - Website`,
                        webStreamData: { defaultUri: siteUrl }
                    }
                });
                const measurementId = streamResponse.data.webStreamData?.measurementId;

                await pool.query(
                    'UPDATE deployed_sites SET ga4_measurement_id = $1, ga4_property_id = $2 WHERE id = $3',
                    [measurementId, propertyId, row.id]
                );

                // Search Console add — non-fatal if it fails (e.g. site not reachable yet).
                try {
                    await searchConsole.sites.add({ siteUrl });
                    result.search_console = 'added';
                } catch (scErr) {
                    result.search_console = `failed: ${scErr.message}`;
                }

                result.success = true;
                result.property_id = propertyId;
                result.measurement_id = measurementId;
                console.log(`[Backfill GA4] ${siteUrl} → ${measurementId}`);
            } catch (e) {
                result.success = false;
                result.error = e.message;
                console.error(`[Backfill GA4] ${siteUrl} failed:`, e.message);
            }
            results.push(result);
        }

        res.json({
            success: true,
            total: results.length,
            created: results.filter(r => r.success).length,
            failed: results.filter(r => !r.success).length,
            results
        });
    } catch (error) {
        console.error('Backfill GA4 error:', error);
        res.status(500).json({ success: false, error: error.message });
    }
});

