// Start OAuth — redirects user to Google consent screen.
app.get('/api/admin/google-oauth/start', async (req, res) => {
    const oauth = buildOAuthClient();
    if (!oauth) return res.status(500).send('OAuth not configured — set GOOGLE_OAUTH_CLIENT_ID and GOOGLE_OAUTH_CLIENT_SECRET');
    const url = oauth.generateAuthUrl({
        access_type: 'offline',  // gets us a refresh_token
        prompt: 'consent',        // forces a refresh_token even on re-consent
        scope: GOOGLE_OAUTH_SCOPES,
        include_granted_scopes: true
    });
    res.redirect(url);
});

// OAuth callback — exchanges code for tokens, stores refresh token.
app.get('/api/admin/google-oauth/callback', async (req, res) => {
    try {
        const oauth = buildOAuthClient();
        if (!oauth) return res.status(500).send('OAuth not configured');
        const code = req.query.code;
        if (!code) return res.status(400).send('Missing code');
        const { tokens } = await oauth.getToken(code);
        // Get the user's email from the id_token / userinfo
        oauth.setCredentials(tokens);
        let email = null;
        try {
            const oauth2 = google.oauth2({ version: 'v2', auth: oauth });
            const info = await oauth2.userinfo.get();
            email = info.data?.email || null;
        } catch (e) { /* not fatal */ }
        await pool.query(`
            INSERT INTO google_oauth_tokens (email, access_token, refresh_token, token_expiry, scopes, updated_at)
            VALUES ($1, $2, $3, $4, $5, NOW())
            ON CONFLICT (email) DO UPDATE SET
                access_token = EXCLUDED.access_token,
                refresh_token = COALESCE(EXCLUDED.refresh_token, google_oauth_tokens.refresh_token),
                token_expiry = EXCLUDED.token_expiry,
                scopes = EXCLUDED.scopes,
                updated_at = NOW()
        `, [
            email,
            tokens.access_token || null,
            tokens.refresh_token || null,
            tokens.expiry_date ? new Date(tokens.expiry_date) : null,
            tokens.scope ? tokens.scope.split(' ') : null
        ]);
        // Fresh token — invalidate the "user OAuth dead" picker cache
        // so the next dashboard load probes user OAuth immediately
        // instead of waiting for the 5-min TTL to expire.
        clearUserOAuthDeadCache();
        // Send a tiny HTML page that closes the popup / shows success.
        res.send(`<!doctype html><html><body style="font-family:system-ui;padding:24px;text-align:center;">
            <h2>✓ Google connected${email ? ' as ' + email : ''}</h2>
            <p>You can close this window.</p>
            <script>setTimeout(()=>{try{window.close()}catch(e){}},1500)</script></body></html>`);
    } catch (e) {
        console.error('OAuth callback error:', e);
        res.status(500).send('OAuth failed: ' + e.message);
    }
});

