// ─── Personal Gmail channels for the GAS Inbox ───────────────────────────────
// Separate scope set from the analytics OAuth above — Gmail-only so we don't
// over-grant. Each connection becomes a row in inbox_channels with
// owner_user_id = the authenticated caller, channel_type = 'gmail'. One row
// per mailbox so Steve (or any future master) can attach multiple Gmail
// accounts to his personal inbox view.
const GMAIL_INBOX_SCOPES = [
  'https://www.googleapis.com/auth/userinfo.email',
  'https://www.googleapis.com/auth/userinfo.profile',
  'https://www.googleapis.com/auth/gmail.readonly',
  'https://www.googleapis.com/auth/gmail.send'
];
const GMAIL_INBOX_CALLBACK = (process.env.PUBLIC_BASE_URL || 'https://admin.gas.travel') + '/api/inbox/channels/gmail/callback';

function buildGmailInboxOAuthClient() {
    const id = process.env.GOOGLE_OAUTH_CLIENT_ID;
    const secret = process.env.GOOGLE_OAUTH_CLIENT_SECRET;
    if (!id || !secret) return null;
    return new google.auth.OAuth2(id, secret, GMAIL_INBOX_CALLBACK);
}

// Start the OAuth flow. Caller must be authenticated — the state carries the
// caller's user id so the callback knows which inbox_channels row to create.
// Browser navigation can't send Bearer headers, so this endpoint also accepts
// the API key as ?token=… for the redirect path.
app.get('/api/inbox/channels/gmail/start', async (req, res) => {
    try {
        let user = null;

        // Try Bearer header first (in case this is ever called via fetch).
        if (req.headers.authorization) {
            user = await authenticateUser(req, res);
            if (!user) return;
        } else if (req.query.token) {
            // Fallback: session token passed as query param (browser nav case).
            const token = String(req.query.token);
            const session = await pool.query(`
                SELECT a.id, a.role, a.email FROM account_sessions s
                JOIN accounts a ON a.id = s.account_id
                WHERE s.token = $1 AND s.expires_at > NOW()
            `, [token]);
            if (session.rows.length === 0) {
                return res.status(401).send('Invalid or expired token — please log in to GAS Admin first, then retry from the Personal Channels modal');
            }
            user = session.rows[0];
        } else {
            return res.status(401).send('Authentication required');
        }

        if (user.role !== 'master_admin') return res.status(403).send('Master admin only');

        const oauth = buildGmailInboxOAuthClient();
        if (!oauth) return res.status(500).send('OAuth not configured — set GOOGLE_OAUTH_CLIENT_ID and GOOGLE_OAUTH_CLIENT_SECRET');

        // State is just an identifier of the calling user — they can only ever
        // attach a mailbox to themselves, so spoofing it has no value (the
        // attacker would be attaching their own Gmail to their own GAS row).
        const state = Buffer.from(JSON.stringify({ uid: user.id, t: Date.now() })).toString('base64url');

        const url = oauth.generateAuthUrl({
            access_type: 'offline',
            prompt: 'consent',
            scope: GMAIL_INBOX_SCOPES,
            include_granted_scopes: true,
            state
        });
        res.redirect(url);
    } catch (e) {
        console.error('[GMAIL-INBOX] start error:', e);
        res.status(500).send('Failed to start OAuth: ' + e.message);
    }
});

// Callback — exchange the code, persist credentials + a new inbox_channels row.
app.get('/api/inbox/channels/gmail/callback', async (req, res) => {
    try {
        const oauth = buildGmailInboxOAuthClient();
        if (!oauth) return res.status(500).send('OAuth not configured');
        const code = req.query.code;
        const state = req.query.state;
        if (!code) return res.status(400).send('Missing code');
        if (!state) return res.status(400).send('Missing state');

        let ownerUserId;
        try {
            const decoded = JSON.parse(Buffer.from(String(state), 'base64url').toString('utf-8'));
            ownerUserId = parseInt(decoded.uid);
            if (!ownerUserId) throw new Error('No uid in state');
        } catch (e) {
            return res.status(400).send('Invalid state');
        }

        const { tokens } = await oauth.getToken(String(code));
        oauth.setCredentials(tokens);

        // Pull the mailbox email so we can persist it as channel_address.
        let email = null;
        try {
            const oauth2 = google.oauth2({ version: 'v2', auth: oauth });
            const info = await oauth2.userinfo.get();
            email = info.data?.email || null;
        } catch (e) { /* non-fatal */ }

        // Persist as one inbox_channels row per (owner, address). Re-connecting
        // the same mailbox replaces the existing row's tokens so refresh tokens
        // never go stale silently.
        const credentials = {
            access_token: tokens.access_token || null,
            refresh_token: tokens.refresh_token || null,
            token_expiry: tokens.expiry_date ? new Date(tokens.expiry_date).toISOString() : null,
            scopes: tokens.scope ? tokens.scope.split(' ') : null
        };
        // Upsert by (owner_user_id, channel_address) — the unique index
        // uq_inbox_channels_owner_address makes this atomic. Pre-fix this
        // was a bare INSERT + a follow-up UPDATE, which produced duplicate
        // channels because the original ON CONFLICT DO NOTHING had no
        // target constraint to fire against. (Cleanup of pre-fix dupes:
        // see 2026-06-01 DB migration that merged + dropped channel id 2.)
        await pool.query(`
            INSERT INTO inbox_channels
                (owner_user_id, channel_type, channel_address, display_name, credentials, active, created_at)
            VALUES ($1, 'gmail', $2, $3, $4, true, NOW())
            ON CONFLICT (owner_user_id, channel_address) WHERE owner_user_id IS NOT NULL
            DO UPDATE SET
                credentials = EXCLUDED.credentials,
                display_name = COALESCE(inbox_channels.display_name, EXCLUDED.display_name),
                active = true,
                last_error = NULL
        `, [ownerUserId, email, email, JSON.stringify(credentials)]);

        res.send(`<!doctype html><html><body style="font-family:system-ui;padding:24px;text-align:center;">
            <h2>✓ Gmail connected${email ? ' as ' + email : ''}</h2>
            <p>This mailbox is now flowing into your GAS Inbox.</p>
            <p>You can close this window.</p>
            <script>setTimeout(()=>{try{window.close()}catch(e){}},1500)</script></body></html>`);
    } catch (e) {
        console.error('[GMAIL-INBOX] callback error:', e);
        res.status(500).send('OAuth failed: ' + e.message);
    }
});

