// =========================================================
// PROPERTY OWNERS — sub-account persona (2026-08-08)
// A "property owner" is an accounts row with managed_by_id pointing at
// an aggregator (e.g. EasyLandlord). They own one or more of the
// aggregator's units via properties.owner_account_id. On login they see
// only their own units — the /api/db/properties query at server.js:55700+
// picks them up via the WHERE ... OR owner_account_id = self branch.
//
// These endpoints let an aggregator (or master admin operating on their
// behalf) list and create owner sub-accounts. Credentials reuse the same
// magic-link flow that Team Members use (buildCredentialsEmail +
// generateTeamMemberResetToken adapted for accounts — but for the owner
// persona the account IS the login so we generate an account-level reset
// token via the existing /api/accounts/forgot-password infra).
// =========================================================

// Resolve which account we're operating on behalf of. Same rules as team
// endpoints: master/agency can pass ?account_id=; client is pinned to
// their own account.
function resolveOwnersAccountId(user, req) {
  return resolveTeamAccountId(user, req);
}

// GET /api/owners — list every accounts row where managed_by_id = current
// account. Includes the property_ids each owner holds (via
// properties.owner_account_id) for the UI's summary line.
app.get('/api/owners', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountId = resolveOwnersAccountId(user, req);
    if (!accountId) return res.status(400).json({ success: false, error: 'No account in scope' });
    const r = await pool.query(`
      SELECT o.id, o.name, o.email, o.phone, o.contact_name, o.status,
             o.last_login_at, o.created_at,
             COALESCE(
               (SELECT array_agg(p.id ORDER BY p.name) FROM properties p WHERE p.owner_account_id = o.id),
               '{}'::int[]
             ) AS property_ids,
             COALESCE(
               (SELECT array_agg(p.name ORDER BY p.name) FROM properties p WHERE p.owner_account_id = o.id),
               '{}'::text[]
             ) AS property_names
        FROM accounts o
       WHERE o.managed_by_id = $1
       ORDER BY o.name
    `, [accountId]);
    res.json({ success: true, owners: r.rows });
  } catch (e) {
    console.error('[owners GET]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /api/owners — create a property-owner sub-account under the current
// account. Sets managed_by_id, optionally assigns owner_account_id on the
// picked properties, and optionally emails credentials (temp password +
// magic set-password link, 24h expiry).
app.post('/api/owners', async (req, res) => {
  const client = await pool.connect();
  try {
    const user = await authenticateUser(req, res); if (!user) { client.release(); return; }
    const aggregatorAccountId = resolveOwnersAccountId(user, req);
    if (!aggregatorAccountId) return res.status(400).json({ success: false, error: 'No account in scope' });

    const name = (req.body?.name || '').trim();
    const email = (req.body?.email || '').trim().toLowerCase();
    const phone = (req.body?.phone || '').trim() || null;
    const contact_name = (req.body?.contact_name || '').trim() || null;
    const property_ids = Array.isArray(req.body?.property_ids)
      ? req.body.property_ids.map(Number).filter(Number.isFinite)
      : [];
    if (!name)  return res.status(400).json({ success: false, error: 'Name is required' });
    if (!email) return res.status(400).json({ success: false, error: 'Email is required' });

    // Password — owner-supplied or auto-generated. sha256 to match the
    // existing accounts.password_hash convention (see POST /api/accounts).
    let plainPassword = (req.body?.password || '').trim();
    if (!plainPassword) plainPassword = generateTempPassword();
    if (plainPassword.length < 8) return res.status(400).json({ success: false, error: 'Password must be at least 8 characters' });
    const passwordHash = crypto.createHash('sha256').update(plainPassword).digest('hex');

    await client.query('BEGIN');

    // Guard: don't clobber an existing accounts row on that email.
    const dup = await client.query('SELECT id, managed_by_id, name FROM accounts WHERE LOWER(email) = LOWER($1) LIMIT 1', [email]);
    if (dup.rows.length) {
      await client.query('ROLLBACK');
      return res.status(409).json({ success: false, error: `An account already exists for ${email} (${dup.rows[0].name || 'no name'}). Use "Reassign existing owner" instead.` });
    }

    // Guard: every picked property must belong to the aggregator or be
    // already-owned via owner_account_id back at them. Prevents an
    // aggregator from stealing another aggregator's property.
    if (property_ids.length) {
      const owned = await client.query(
        `SELECT id FROM properties WHERE id = ANY($1::int[]) AND (account_id = $2 OR owner_account_id IS NULL)`,
        [property_ids, aggregatorAccountId]
      );
      if (owned.rows.length !== property_ids.length) {
        await client.query('ROLLBACK');
        return res.status(403).json({ success: false, error: 'One or more properties are not yours to assign' });
      }
    }

    // Create the owner account. role='admin' + managed_by_id = aggregator.
    const ins = await client.query(`
      INSERT INTO accounts (name, email, phone, contact_name, role, status, password_hash, managed_by_id, created_at)
      VALUES ($1, $2, $3, $4, 'admin', 'active', $5, $6, NOW())
      RETURNING id, name, email
    `, [name, email, phone, contact_name, passwordHash, aggregatorAccountId]);
    const ownerId = ins.rows[0].id;

    // Assign owner_account_id on the picked properties.
    if (property_ids.length) {
      await client.query(
        `UPDATE properties SET owner_account_id = $1, updated_at = NOW() WHERE id = ANY($2::int[])`,
        [ownerId, property_ids]
      );
    }

    await client.query('COMMIT');

    // Optional credentials email — mirrors the team_members flow. Uses the
    // shared password_reset_tokens table for the magic link (account_id
    // branch since owners ARE accounts).
    let emailSent = false;
    let emailError = null;
    if (req.body?.send_credentials === true) {
      try {
        const aggR = await pool.query('SELECT name FROM accounts WHERE id = $1', [aggregatorAccountId]);
        const aggregatorName = aggR.rows[0]?.name || 'GAS';
        // Generate a 24h magic reset token bound to this accounts row.
        const resetToken = crypto.randomBytes(32).toString('hex');
        const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
        await pool.query(
          `INSERT INTO password_reset_tokens (account_id, token, expires_at) VALUES ($1, $2, $3)`,
          [ownerId, resetToken, expiresAt]
        );
        const base = process.env.GAS_ADMIN_URL || 'https://admin.gas.travel';
        const resetUrl = `${base.replace(/\/$/, '')}/reset-password.html?token=${resetToken}`;
        const loginUrl = base;
        const html = buildCredentialsEmail({
          memberName: name,
          memberEmail: email,
          password: plainPassword,
          roleLabel: 'Property Owner',
          accountName: aggregatorName,
          loginUrl,
          resetUrl
        });
        const sendResult = await sendEmail({
          to: email,
          subject: `Welcome to ${aggregatorName}`,
          html,
          accountId: aggregatorAccountId,
          context: {
            accountId: aggregatorAccountId,
            eventType: 'owner_credentials',
            autoCreateGuest: false,
            metadata: { owner_account_id: ownerId, aggregator_account_id: aggregatorAccountId }
          }
        });
        if (sendResult.success !== false) emailSent = true;
        else emailError = sendResult.error || 'send returned success:false';
      } catch (e) {
        emailError = e.message;
        console.warn('[owners POST send_credentials]', e.message);
      }
    }

    res.json({
      success: true,
      owner: { id: ownerId, name, email, property_ids },
      password: plainPassword,
      email_sent: emailSent,
      email_error: emailError
    });
  } catch (e) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('[owners POST]', e.message);
    res.status(500).json({ success: false, error: e.message });
  } finally {
    client.release();
  }
});

app.get('/api/team', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountId = resolveTeamAccountId(user, req);
    if (!accountId) return res.status(400).json({ success: false, error: 'No account in scope' });
    const r = await pool.query(`
      SELECT
        ua.id              AS assignment_id,
        ua.member_id,
        u.email,
        u.full_name,
        u.phone,
        u.last_login_at,
        u.credentials_sent_at,
        u.must_change_password,
        u.status           AS user_status,
        ua.role,
        ua.property_ids,
        ua.unit_ids,
        ua.permissions,
        ua.status          AS assignment_status,
        ua.invited_at,
        ua.accepted_at,
        ua.invited_by
      FROM team_assignments ua
      JOIN team_members u ON u.id = ua.member_id
      WHERE ua.account_id = $1
        AND ua.status != 'deleted'
      ORDER BY ua.invited_at DESC
    `, [accountId]);
    res.json({ success: true, members: r.rows, role_catalog: Object.entries(TEAM_ROLES).map(([slug, m]) => ({ slug, ...m })) });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/team', async (req, res) => {
  const client = await pool.connect();
  try {
    const user = await authenticateUser(req, res); if (!user) { client.release(); return; }
    const accountId = resolveTeamAccountId(user, req);
    if (!accountId) return res.status(400).json({ success: false, error: 'No account in scope' });

    const email = (req.body?.email || '').trim().toLowerCase();
    const full_name = (req.body?.full_name || '').trim();
    const phone = (req.body?.phone || '').trim() || null;
    const role = (req.body?.role || '').trim();
    const property_ids = Array.isArray(req.body?.property_ids) ? req.body.property_ids.map(Number).filter(Boolean) : [];
    const unit_ids = Array.isArray(req.body?.unit_ids) ? req.body.unit_ids.map(Number).filter(Boolean) : [];
    // Per-user permission overrides on top of the role default bundle. Keys
    // are CAPABILITIES entries; values are true (add) / false (remove from
    // default). See getEffectivePermissions() for the merge semantics.
    const permissions = (req.body?.permissions && typeof req.body.permissions === 'object' && !Array.isArray(req.body.permissions)) ? req.body.permissions : {};

    // Owner-set initial password (or generated). Hashed before storage; the
    // plaintext is returned ONCE in the response so the modal can show it
    // back to the owner for copy + later send-credentials.
    let plainPassword = (req.body?.password || '').trim();
    if (!plainPassword) plainPassword = generateTempPassword();
    if (plainPassword.length < 6) return res.status(400).json({ success: false, error: 'Password must be at least 6 characters' });

    if (!email)       return res.status(400).json({ success: false, error: 'Email is required' });
    if (!full_name)   return res.status(400).json({ success: false, error: 'Full name is required' });
    if (!TEAM_ROLES[role]) return res.status(400).json({ success: false, error: 'Unknown role: ' + role });

    const bcrypt = require('bcryptjs');
    const passwordHash = await bcrypt.hash(plainPassword, 10);

    await client.query('BEGIN');

    // Find or create the team_members row. Email is the global identity.
    let memberRow = (await client.query(
      'SELECT id, email, full_name FROM team_members WHERE lower(email) = lower($1)',
      [email]
    )).rows[0];

    if (!memberRow) {
      const ins = await client.query(
        `INSERT INTO team_members (email, full_name, phone, password_hash, must_change_password, status, created_by)
         VALUES ($1, $2, $3, $4, true, 'active', $5)
         RETURNING id, email, full_name`,
        [email, full_name, phone, passwordHash, user.id || user.accountId]
      );
      memberRow = ins.rows[0];
    } else {
      // Existing member — owner is adding them to another account or with a
      // new role. Update password + name only if owner explicitly supplied
      // them; never silently change a working login.
      const updates = [];
      const updateArgs = [memberRow.id];
      if (full_name && !memberRow.full_name) { updateArgs.push(full_name); updates.push(`full_name = $${updateArgs.length}`); }
      if (phone) { updateArgs.push(phone); updates.push(`phone = COALESCE($${updateArgs.length}, phone)`); }
      if (req.body?.password) {
        updateArgs.push(passwordHash); updates.push(`password_hash = $${updateArgs.length}`);
        updates.push('must_change_password = true');
      }
      if (updates.length) {
        updates.push('updated_at = NOW()');
        await client.query(`UPDATE team_members SET ${updates.join(', ')} WHERE id = $1`, updateArgs);
      }
    }

    // Reactivate a previously soft-deleted assignment if one exists, otherwise insert fresh.
    // Without this, deleting then re-adding the same person/role throws 23505 because the
    // soft-deleted row holds the (member, account, role) slot.
    const existingDeleted = await client.query(
      `SELECT id FROM team_assignments
       WHERE member_id = $1 AND account_id = $2 AND role = $3 AND status = 'deleted'
       LIMIT 1`,
      [memberRow.id, accountId, role]
    );

    let a;
    try {
      if (existingDeleted.rows.length > 0) {
        a = await client.query(
          `UPDATE team_assignments
           SET status = 'active', property_ids = $2, unit_ids = $3, permissions = $4::jsonb,
               invited_by = $5, invited_at = NOW(), updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [existingDeleted.rows[0].id, property_ids, unit_ids, JSON.stringify(permissions), user.id || user.accountId]
        );
      } else {
        a = await client.query(
          `INSERT INTO team_assignments (member_id, account_id, role, property_ids, unit_ids, permissions, status, invited_by)
           VALUES ($1, $2, $3, $4, $5, $6::jsonb, 'active', $7)
           RETURNING *`,
          [memberRow.id, accountId, role, property_ids, unit_ids, JSON.stringify(permissions), user.id || user.accountId]
        );
      }
      await client.query('COMMIT');

      // Optional: send the credentials email inline so the owner doesn't
      // have to click a second button. Defaults to false for backwards
      // compat; the Add Team Member modal ticks the box by default.
      // Stamps credentials_sent_at only when the email actually goes.
      // 2026-08-08 — Steve asked for the "Also email now" checkbox on Add.
      let emailSent = false;
      let emailError = null;
      if (req.body?.send_credentials === true) {
        try {
          const acctR = await pool.query('SELECT name FROM accounts WHERE id = $1', [accountId]);
          const accountName = acctR.rows[0]?.name || 'GAS';
          const roleLabel = (TEAM_ROLES[role] && TEAM_ROLES[role].label) || role;
          const loginUrl = process.env.GAS_ADMIN_URL || 'https://admin.gas.travel/';
          // Magic link so the recipient can skip the temp-password step and
          // set their own password straight away. 24h expiry.
          let resetUrl = null;
          try { resetUrl = await generateTeamMemberResetToken(memberRow.id); }
          catch (e) { console.warn('[team POST reset-token]', e.message); }
          const html = buildCredentialsEmail({
            memberName: full_name || '',
            memberEmail: email,
            password: plainPassword,
            roleLabel,
            accountName,
            loginUrl,
            resetUrl
          });
          const sendResult = await sendEmail({
            to: email,
            subject: `Welcome to ${accountName} on GAS`,
            html,
            accountId,
            context: {
              accountId,
              eventType: 'team_member_credentials',
              autoCreateGuest: false,
              metadata: { team_assignment_id: a.rows[0].id, role, first_add: true }
            }
          });
          if (sendResult.success !== false) {
            emailSent = true;
            await pool.query(`UPDATE team_members SET credentials_sent_at = NOW() WHERE id = $1`, [memberRow.id]).catch(() => {});
          } else {
            emailError = sendResult.error || 'send returned success:false';
          }
        } catch (e) {
          emailError = e.message;
          console.warn('[team POST send_credentials]', e.message);
        }
      }

      res.json({
        success: true,
        member: { ...a.rows[0], email: memberRow.email, full_name: memberRow.full_name },
        // Owner needs to see the plaintext password once so they can copy
        // it before triggering the credentials email later.
        password: plainPassword,
        email_sent: emailSent,
        email_error: emailError,
      });
    } catch (e) {
      if (e.code === '23505') {
        await client.query('ROLLBACK');
        return res.status(409).json({ success: false, error: 'That person already has this role on this account.' });
      }
      throw e;
    }
  } catch (e) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('[team POST]', e.message);
    res.status(500).json({ success: false, error: e.message });
  } finally {
    client.release();
  }
});

// Send the team member their credentials. For now this is the "Reset
// password + email" flow — owner sets a new temp password (or we generate),
// must_change_password flips to true, email goes out. Plaintext is shown
// back to the owner in the response so they can also copy/paste it.
app.post('/api/team/:assignment_id/send-credentials', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountFilter = resolveTeamAssignmentFilter(user, req);
    const id = parseInt(req.params.assignment_id);
    if (!id) return res.status(400).json({ success: false, error: 'Bad assignment id' });

    // Resolve the assignment + member + account name in one query.
    const lookup = await pool.query(`
      SELECT
        ta.id AS assignment_id, ta.role, ta.account_id,
        tm.id AS member_id, tm.email, tm.full_name,
        a.name AS account_name
      FROM team_assignments ta
      JOIN team_members tm ON tm.id = ta.member_id
      LEFT JOIN accounts a ON a.id = ta.account_id
      WHERE ta.id = $1 AND ($2::int IS NULL OR ta.account_id = $2) AND ta.status != 'deleted'
    `, [id, accountFilter]);
    if (lookup.rows.length === 0) return res.status(404).json({ success: false, error: 'Assignment not found' });
    const row = lookup.rows[0];
    // accountId here is the assignment's actual account — used for the
    // sendEmail's per-account branding, not for the access check.
    const accountId = row.account_id;

    // Owner can either supply a new password or let us generate one.
    let plainPassword = (req.body?.password || '').trim();
    if (!plainPassword) plainPassword = generateTempPassword();
    if (plainPassword.length < 6) return res.status(400).json({ success: false, error: 'Password must be at least 6 characters' });

    const bcrypt = require('bcryptjs');
    const passwordHash = await bcrypt.hash(plainPassword, 10);

    // Whether to email the plaintext to the member. Default true (preserves
    // pre-2026-07-30 behaviour); pass email:false for "reset password only,
    // I'll deliver it via WhatsApp/text/verbally". credentials_sent_at is
    // only stamped when we actually emailed — so a silent reset doesn't
    // pretend the user was notified.
    const shouldEmail = req.body?.email !== false;

    await pool.query(
      `UPDATE team_members SET password_hash = $1, must_change_password = true${shouldEmail ? ', credentials_sent_at = NOW()' : ''}, updated_at = NOW() WHERE id = $2`,
      [passwordHash, row.member_id]
    );

    const roleLabel = (TEAM_ROLES[row.role] && TEAM_ROLES[row.role].label) || row.role;
    const accountName = row.account_name || 'GAS';
    const loginUrl = process.env.GAS_ADMIN_URL || 'https://admin.gas.travel/';
    let sendResult = { success: true };
    if (shouldEmail) {
      // Magic link — recipient can bypass typing the temp password and set
      // their own straight away. 24h expiry.
      let resetUrl = null;
      try { resetUrl = await generateTeamMemberResetToken(row.member_id); }
      catch (e) { console.warn('[team send-credentials reset-token]', e.message); }
      const html = buildCredentialsEmail({
        memberName: row.full_name || '',
        memberEmail: row.email,
        password: plainPassword,
        roleLabel,
        accountName,
        loginUrl,
        resetUrl
      });
      sendResult = await sendEmail({
        to: row.email,
        subject: `Welcome to ${accountName} on GAS`,
        html,
        accountId,
        context: {
          accountId,
          eventType: 'team_member_credentials',
          autoCreateGuest: false,
          metadata: { team_assignment_id: row.assignment_id, role: row.role }
        }
      });
    }

    res.json({
      success: shouldEmail ? sendResult.success !== false : true,
      email_sent: shouldEmail && sendResult.success !== false,
      sent_to: row.email,
      password: plainPassword,         // owner sees once
      error: sendResult.error || null
    });
  } catch (e) {
    console.error('[team send-credentials]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// Load a single assignment with member details and the merged effective
// permission set. Used by the Edit modal to pre-populate the checkbox grid.
app.get('/api/team/:assignment_id', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountFilter = resolveTeamAssignmentFilter(user, req);
    const id = parseInt(req.params.assignment_id);
    if (!id) return res.status(400).json({ success: false, error: 'Bad assignment id' });
    const r = await pool.query(`
      SELECT
        ta.id AS assignment_id, ta.member_id, ta.account_id, ta.role,
        ta.property_ids, ta.unit_ids, ta.permissions,
        ta.status AS assignment_status, ta.invited_at, ta.accepted_at, ta.invited_by,
        tm.email, tm.full_name, tm.phone,
        tm.last_login_at, tm.credentials_sent_at, tm.must_change_password,
        tm.status AS user_status
      FROM team_assignments ta
      JOIN team_members tm ON tm.id = ta.member_id
      WHERE ta.id = $1 AND ($2::int IS NULL OR ta.account_id = $2) AND ta.status != 'deleted'
    `, [id, accountFilter]);
    if (r.rows.length === 0) return res.status(404).json({ success: false, error: 'Assignment not found' });
    const row = r.rows[0];
    row.effective_permissions = getEffectivePermissions(row.role, row.permissions);
    row.default_permissions = ROLE_DEFAULTS[row.role] || {};
    res.json({ success: true, assignment: row, capabilities: CAPABILITIES });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

app.put('/api/team/:assignment_id', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountFilter = resolveTeamAssignmentFilter(user, req);
    const id = parseInt(req.params.assignment_id);
    if (!id) return res.status(400).json({ success: false, error: 'Bad assignment id' });

    const updatable = {};
    if (req.body?.role !== undefined) {
      if (!TEAM_ROLES[req.body.role]) return res.status(400).json({ success: false, error: 'Unknown role' });
      updatable.role = req.body.role;
    }
    if (req.body?.status !== undefined) updatable.status = req.body.status;
    if (Array.isArray(req.body?.property_ids)) updatable.property_ids = req.body.property_ids.map(Number).filter(Boolean);
    if (Array.isArray(req.body?.unit_ids))     updatable.unit_ids     = req.body.unit_ids.map(Number).filter(Boolean);
    if (req.body?.permissions !== undefined)   updatable.permissions  = req.body.permissions;

    if (Object.keys(updatable).length === 0) return res.status(400).json({ success: false, error: 'Nothing to update' });

    const sets = [];
    const args = [id, accountFilter];
    for (const [k, v] of Object.entries(updatable)) {
      args.push(v);
      sets.push(`${k} = $${args.length}`);
    }
    sets.push('updated_at = NOW()');

    const r = await pool.query(
      `UPDATE team_assignments SET ${sets.join(', ')}
       WHERE id = $1 AND ($2::int IS NULL OR account_id = $2)
       RETURNING *`,
      args
    );
    if (r.rows.length === 0) return res.status(404).json({ success: false, error: 'Assignment not found' });
    res.json({ success: true, assignment: r.rows[0] });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

app.delete('/api/team/:assignment_id', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountFilter = resolveTeamAssignmentFilter(user, req);
    const id = parseInt(req.params.assignment_id);
    if (!id) return res.status(400).json({ success: false, error: 'Bad assignment id' });
    // Soft delete — keep the audit trail rather than dropping the row.
    const r = await pool.query(
      `UPDATE team_assignments SET status = 'deleted', updated_at = NOW()
       WHERE id = $1 AND ($2::int IS NULL OR account_id = $2) RETURNING id`,
      [id, accountFilter]
    );
    if (r.rows.length === 0) return res.status(404).json({ success: false, error: 'Assignment not found' });
    res.json({ success: true });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

// =========================================================
// AUTO MESSAGES — endpoints
// =========================================================
// Templates + Rules CRUD, plus a /run-now path for manual testing. All
// scoped to the caller's account_id; master_admin can see/edit any
// account by passing ?account_id=N.

// Resolve the effective account_id for an Auto-Messages request. Clients
// see their own account; master can pass ?account_id= to scope.
function resolveAutoMsgAccountId(user, req) {
  const q = parseInt(req.query.account_id || req.body?.account_id);
  if (user.role === 'master_admin' && q) return q;
  return user.id || user.accountId;
}

