// Manual evaluation — useful for testing a rule against current bookings.
// Honours dedupe, so re-running won't double-send.
app.post('/api/auto-messages/rules/:id/run-now', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountId = resolveAutoMsgAccountId(user, req);
    const id = parseInt(req.params.id);
    const r = await pool.query(`SELECT * FROM outbound_rules WHERE id = $1 AND account_id = $2`, [id, accountId]);
    if (r.rows.length === 0) return res.status(404).json({ success: false, error: 'Rule not found' });
    // Widen window to 365 days for manual run so historical matches can be tested.
    const stats = await evaluateRule(r.rows[0], { windowMinutes: 60 * 24 * 365 });
    res.json({ success: true, stats });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

// Preview — render a template+rule against a specific booking without sending.
app.post('/api/auto-messages/preview', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountId = resolveAutoMsgAccountId(user, req);
    const { booking_id, rule_id, template_id, lang } = req.body || {};
    if (!booking_id) return res.status(400).json({ success: false, error: 'booking_id required' });
    const bRes = await pool.query(
      `SELECT b.*, p.account_id AS account_id,
              p.name AS _property_name, p.address AS _property_address,
              p.timezone AS _property_timezone, p.country AS _property_country,
              bu.name AS _unit_name, bu.default_access_code AS _unit_default_access_code,
              pt.checkin_from AS _checkin_from, pt.checkout_by AS _checkout_by
       FROM bookings b
       JOIN properties p ON p.id = b.property_id
       LEFT JOIN bookable_units bu ON bu.id = b.bookable_unit_id
       LEFT JOIN property_terms pt ON pt.property_id = b.property_id
       WHERE b.id = $1 AND p.account_id = $2`,
      [booking_id, accountId]
    );
    if (bRes.rows.length === 0) return res.status(404).json({ success: false, error: 'Booking not found' });
    const booking = bRes.rows[0];
    const vars = await buildTemplateVars(booking);
    let subject_ml = {}, body_ml = {};
    if (rule_id) {
      const r = await pool.query(`SELECT * FROM outbound_rules WHERE id = $1 AND account_id = $2`, [rule_id, accountId]);
      if (r.rows[0]) {
        const resolved = await resolveRuleContent(r.rows[0], lang || 'en');
        return res.json({ success: true, vars, subject: renderTemplate(resolved.subject, vars), body: renderTemplate(resolved.body, vars) });
      }
    }
    if (template_id) {
      const t = await pool.query(`SELECT subject_ml, body_ml FROM outbound_templates WHERE id = $1 AND account_id = $2`, [template_id, accountId]);
      if (t.rows[0]) { subject_ml = t.rows[0].subject_ml; body_ml = t.rows[0].body_ml; }
    }
    res.json({
      success: true, vars,
      subject: renderTemplate(pickMlValue(subject_ml, lang || 'en'), vars),
      body:    renderTemplate(pickMlValue(body_ml, lang || 'en'), vars)
    });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

