// Upcoming fires preview — given a rule, return the bookings that will
// trigger it in the next N days, ordered by fire time. Confidence-builder
// so operators can see "this rule will email X tomorrow at noon" before
// it actually happens. Dedupe-aware: skips bookings already in
// outbound_rule_fires.
app.get('/api/auto-messages/rules/:id/upcoming', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const accountId = resolveAutoMsgAccountId(user, req);
    const id = parseInt(req.params.id);
    const days = Math.min(parseInt(req.query.days) || 30, 90);

    const ruleRes = await pool.query(`SELECT * FROM outbound_rules WHERE id = $1 AND account_id = $2`, [id, accountId]);
    if (ruleRes.rows.length === 0) return res.status(404).json({ success: false, error: 'Rule not found' });
    const rule = ruleRes.rows[0];

    const { sql, params } = bookingsInScopeSql(rule);
    const bookings = (await pool.query(sql, params)).rows;

    const now = Date.now();
    const horizon = now + days * 24 * 60 * 60 * 1000;
    const upcoming = [];

    // Build a set of (rule_id, booking_id) already-fired
    const alreadyFired = new Set(
      (await pool.query('SELECT booking_id FROM outbound_rule_fires WHERE rule_id = $1', [id])).rows
        .map(r => r.booking_id)
    );

    for (const b of bookings) {
      if (alreadyFired.has(b.id)) continue;
      if (!bookingPassesFilters(rule, b)) continue;
      const t = computeRuleFireTime(rule, b);
      if (!t) continue;
      const tms = t.getTime();
      if (tms < now - 60 * 60 * 1000) continue; // > 1h in past = already missed
      if (tms > horizon) continue;
      upcoming.push({
        booking_id: b.id,
        guest_first_name: b.guest_first_name,
        guest_last_name: b.guest_last_name,
        guest_email: b.guest_email,
        arrival_date: b.arrival_date,
        property_name: b._property_name,
        unit_name: b._unit_name,
        fire_at: t.toISOString(),
      });
    }
    upcoming.sort((a, b) => new Date(a.fire_at) - new Date(b.fire_at));
    res.json({ success: true, count: upcoming.length, upcoming: upcoming.slice(0, 50) });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

