// List messages across the caller's personal channels (master admin only).
app.get('/api/inbox/personal/messages', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        if (user.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });

        const { channel_id, status, search, limit = 50, offset = 0 } = req.query;

        // Personal-inbox list query — joins the channel for source labels
        // and the linked account (if Layer 1 triage matched one) so the UI
        // can render "→ Cotswolds" chips without a second roundtrip.
        let query = `
            SELECT m.*, c.channel_address, c.display_name as channel_display_name,
                   la.name as linked_account_name, la.business_name as linked_account_business
            FROM inbox_messages m
            JOIN inbox_channels c ON c.id = m.channel_id
            LEFT JOIN accounts la ON la.id = m.linked_account_id
            WHERE c.owner_user_id = $1
        `;
        const params = [user.id];
        let p = 2;

        if (channel_id) {
            query += ` AND m.channel_id = $${p++}`;
            params.push(parseInt(channel_id));
        }
        if (status && status !== 'all') {
            query += ` AND m.status = $${p++}`;
            params.push(status);
        }
        if (search) {
            query += ` AND (m.subject ILIKE $${p} OR m.body ILIKE $${p} OR m.from_name ILIKE $${p} OR m.from_handle ILIKE $${p})`;
            params.push(`%${search}%`);
            p++;
        }
        // Hide promo by default unless the caller asks. Promo mail is kept
        // in the DB for "did I sign up for X?" lookups, just dropped from
        // the main timeline.
        if (req.query.show_promo !== 'true') {
            query += ` AND COALESCE(m.is_promo, false) = false`;
        }
        query += ` ORDER BY m.created_at DESC LIMIT $${p++} OFFSET $${p++}`;
        params.push(parseInt(limit), parseInt(offset));

        const result = await pool.query(query, params);

        const countsResult = await pool.query(`
            SELECT m.channel_id, COUNT(*) as count
            FROM inbox_messages m
            JOIN inbox_channels c ON c.id = m.channel_id
            WHERE c.owner_user_id = $1 AND m.status = 'unread'
            GROUP BY m.channel_id
        `, [user.id]);
        const unreadByChannel = {};
        let totalUnread = 0;
        countsResult.rows.forEach(r => { unreadByChannel[r.channel_id] = parseInt(r.count); totalUnread += parseInt(r.count); });

        res.json({
            success: true,
            messages: result.rows,
            total: result.rows.length,
            unread: { total: totalUnread, byChannel: unreadByChannel }
        });
    } catch (e) {
        console.error('Personal inbox messages error:', e);
        res.status(500).json({ error: e.message });
    }
});

// Manually relink (or unlink) a message to a client account or a prospect.
// Mutually exclusive — passing both account_id and prospect_id picks the
// account (paying client wins). Auto-trains the appropriate alias table
// off the manual link so the NEXT message from the same domain gets
// auto-linked by Rule E without another manual step.
app.put('/api/inbox/messages/:id/link', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        if (user.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });

        const { id } = req.params;
        const { account_id, prospect_id, booking_id, guest_id } = req.body || {};

        // If both are passed, prefer the account — operator action gets
        // routed to the more concrete entity.
        const finalAccountId = account_id || null;
        const finalProspectId = !finalAccountId ? (prospect_id || null) : null;

        await pool.query(`
            UPDATE inbox_messages
            SET linked_account_id = $1,
                linked_prospect_id = $2,
                linked_booking_id = $3,
                linked_guest_id = $4,
                link_source = 'manual'
            WHERE id = $5
        `, [finalAccountId, finalProspectId, booking_id || null, guest_id || null, id]);

        // Train the alias table off this manual link. Account → account_domain_aliases;
        // prospect → prospect_domain_aliases. Generic providers (gmail.com etc.)
        // skipped — we'd never want to auto-route every gmail address by domain.
        // Soft-fail on any DB error so the user's link still succeeds.
        if (finalAccountId || finalProspectId) {
            try {
                const senderRow = await pool.query(`SELECT from_handle FROM inbox_messages WHERE id = $1`, [id]);
                const handle = senderRow.rows[0]?.from_handle || '';
                if (handle.includes('@')) {
                    const domain = handle.split('@')[1].toLowerCase().trim();
                    if (domain && !GENERIC_EMAIL_PROVIDERS.includes(domain)) {
                        if (finalAccountId) {
                            await pool.query(`
                                INSERT INTO account_domain_aliases (account_id, domain, source, created_by)
                                VALUES ($1, $2, 'auto_from_manual_link', $3)
                                ON CONFLICT (account_id, domain) DO NOTHING
                            `, [finalAccountId, domain, user.id]);
                        } else if (finalProspectId) {
                            await pool.query(`
                                INSERT INTO prospect_domain_aliases (prospect_id, domain, source, created_by)
                                VALUES ($1, $2, 'auto_from_manual_link', $3)
                                ON CONFLICT (prospect_id, domain) DO NOTHING
                            `, [finalProspectId, domain, user.id]);
                        }
                    }
                }
            } catch (e) {
                console.warn('[INBOX-LINK] alias training failed (non-fatal):', e.message);
            }
        }

        res.json({ success: true });
    } catch (e) {
        res.json({ success: false, error: e.message });
    }
});

