// List prospects with message-count + latest-contact summary so the
// list view doesn't need a second roundtrip.
app.get('/api/admin/prospects', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        if (user.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });

        const includeConverted = req.query.include_converted === 'true';
        const r = await pool.query(`
            SELECT p.id, p.name, p.business_name, p.email, p.phone, p.source,
                   p.status, p.property_count, p.current_cm, p.notes,
                   p.owner_user_id, p.converted_to_account_id, p.converted_at,
                   p.created_at, p.updated_at,
                   COALESCE(mc.message_count, 0) AS message_count,
                   mc.latest_at AS latest_message_at
            FROM prospects p
            LEFT JOIN (
                SELECT linked_prospect_id, COUNT(*) AS message_count, MAX(created_at) AS latest_at
                FROM inbox_messages
                WHERE linked_prospect_id IS NOT NULL
                GROUP BY linked_prospect_id
            ) mc ON mc.linked_prospect_id = p.id
            WHERE ($1 OR p.converted_to_account_id IS NULL)
            ORDER BY COALESCE(mc.latest_at, p.created_at) DESC
        `, [includeConverted]);
        res.json({ success: true, prospects: r.rows });
    } catch (e) {
        console.error('[PROSPECTS] list error:', e);
        res.json({ success: false, error: e.message });
    }
});

