app.put('/api/admin/prospects/:id', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        if (user.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });
        const fields = ['name', 'business_name', 'email', 'phone', 'source', 'status',
                        'property_count', 'current_cm', 'notes', 'owner_user_id'];
        const sets = [];
        const params = [];
        let p = 1;
        for (const f of fields) {
            if (req.body && Object.prototype.hasOwnProperty.call(req.body, f)) {
                sets.push(`${f} = $${p++}`);
                params.push(req.body[f]);
            }
        }
        if (sets.length === 0) return res.status(400).json({ error: 'No fields to update' });
        sets.push(`updated_at = NOW()`);
        params.push(req.params.id);
        const r = await pool.query(`
            UPDATE prospects SET ${sets.join(', ')}
            WHERE id = $${p} RETURNING *
        `, params);
        if (r.rows.length === 0) return res.status(404).json({ error: 'Prospect not found' });
        res.json({ success: true, prospect: r.rows[0] });
    } catch (e) {
        res.json({ success: false, error: e.message });
    }
});

