// Convert a prospect to a paying client account. Clean rewrite:
// - Creates an accounts row from prospect fields
// - Stamps accounts.converted_from_prospect_id for the audit trail
// - Re-points every prospect_domain_aliases row to account_domain_aliases
// - Re-points every inbox_messages.linked_prospect_id to linked_account_id
// - Marks the prospect converted_to_account_id + converted_at
// All in a single transaction.
app.post('/api/admin/prospects/:id/convert', async (req, res) => {
    const client = await pool.connect();
    try {
        const user = await authenticateUser(req, res);
        if (!user) { client.release(); return; }
        if (user.role !== 'master_admin') { client.release(); return res.status(403).json({ error: 'Master admin only' }); }

        const overrides = req.body || {};
        await client.query('BEGIN');

        const pRow = await client.query(`SELECT * FROM prospects WHERE id = $1 FOR UPDATE`, [req.params.id]);
        if (pRow.rows.length === 0) { await client.query('ROLLBACK'); client.release(); return res.status(404).json({ error: 'Prospect not found' }); }
        const p = pRow.rows[0];
        if (p.converted_to_account_id) {
            await client.query('ROLLBACK'); client.release();
            return res.status(400).json({ error: 'Already converted', account_id: p.converted_to_account_id });
        }

        // Required accounts fields: name, email, role. Caller can override.
        const accName = overrides.name || p.name;
        const accEmail = overrides.email || p.email;
        if (!accEmail) {
            await client.query('ROLLBACK'); client.release();
            return res.status(400).json({ error: 'Prospect has no email and no override provided' });
        }

        const accIns = await client.query(`
            INSERT INTO accounts (name, business_name, email, role, converted_from_prospect_id, created_at)
            VALUES ($1, $2, $3, 'admin', $4, NOW())
            RETURNING id
        `, [accName, overrides.business_name || p.business_name || null, accEmail, p.id]);
        const newAccountId = accIns.rows[0].id;

        // Migrate aliases (skip dup on conflict so re-running is safe).
        const aliasMig = await client.query(`
            INSERT INTO account_domain_aliases (account_id, domain, source, notes, created_by, created_at)
            SELECT $1, domain, 'migrated_from_prospect', notes, created_by, created_at
            FROM prospect_domain_aliases WHERE prospect_id = $2
            ON CONFLICT (account_id, domain) DO NOTHING
            RETURNING id
        `, [newAccountId, p.id]);

        // Re-point inbox messages.
        const msgMig = await client.query(`
            UPDATE inbox_messages
            SET linked_account_id = $1, linked_prospect_id = NULL,
                link_source = 'rule_prospect_converted'
            WHERE linked_prospect_id = $2
            RETURNING id
        `, [newAccountId, p.id]);

        // Stamp the prospect.
        await client.query(`
            UPDATE prospects
            SET converted_to_account_id = $1, converted_at = NOW(), status = 'won', updated_at = NOW()
            WHERE id = $2
        `, [newAccountId, p.id]);

        await client.query('COMMIT');
        client.release();
        res.json({
            success: true,
            account_id: newAccountId,
            aliases_migrated: aliasMig.rows.length,
            messages_migrated: msgMig.rows.length
        });
    } catch (e) {
        try { await client.query('ROLLBACK'); } catch (_) {}
        client.release();
        console.error('[PROSPECTS] convert error:', e);
        res.status(500).json({ success: false, error: e.message });
    }
});

// Allocate a domain OR single address to a prospect — sibling to
// allocate-domain. Same address/domain dual-shape support.
app.post('/api/inbox/allocate-prospect-domain', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        if (user.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });
        const { prospect_id, domain, notes, retroactive = true } = req.body || {};
        if (!prospect_id || !domain) return res.status(400).json({ error: 'prospect_id and domain required' });

        const parsed = _cleanAliasValue(domain);
        if (!parsed) return res.status(400).json({ error: 'Invalid domain or email' });
        const { cleaned, isAddress } = parsed;

        await pool.query(`
            INSERT INTO prospect_domain_aliases (prospect_id, domain, source, notes, created_by)
            VALUES ($1, $2, 'triage_queue', $3, $4)
            ON CONFLICT (prospect_id, domain) DO UPDATE SET notes = EXCLUDED.notes
        `, [prospect_id, cleaned, notes || null, user.id]);

        let retroLinked = 0;
        if (retroactive) {
            const upd = await pool.query(
                isAddress
                    ? `UPDATE inbox_messages
                       SET linked_prospect_id = $1, link_source = 'rule_prospect_alias'
                       WHERE linked_account_id IS NULL
                         AND linked_prospect_id IS NULL
                         AND LOWER(from_handle) = $2
                       RETURNING id`
                    : `UPDATE inbox_messages
                       SET linked_prospect_id = $1, link_source = 'rule_prospect_alias'
                       WHERE linked_account_id IS NULL
                         AND linked_prospect_id IS NULL
                         AND from_handle ILIKE '%@%'
                         AND (LOWER(split_part(from_handle, '@', 2)) = $2
                              OR LOWER(split_part(from_handle, '@', 2)) LIKE '%.' || $2)
                       RETURNING id`,
                [prospect_id, cleaned]
            );
            retroLinked = upd.rows.length;
        }
        res.json({ success: true, retroLinked, mode: isAddress ? 'address' : 'domain' });
    } catch (e) {
        console.error('[ALLOCATE-PROSPECT-DOMAIN] error:', e);
        res.status(500).json({ success: false, error: e.message });
    }
});

