// Add a new alias. Domain is normalised to lowercase, leading "www." and
// "@" stripped so an operator pasting either "@ioucreationcentre.org" or
// "www.ioucreationcentre.org" both store cleanly as "ioucreationcentre.org".
app.post('/api/inbox/account-aliases', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        if (user.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });
        const { account_id, domain, notes } = req.body || {};
        if (!account_id || !domain) return res.status(400).json({ error: 'account_id and domain required' });
        const cleaned = String(domain).trim().toLowerCase().replace(/^@/, '').replace(/^www\./, '');
        if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(cleaned)) return res.status(400).json({ error: 'Invalid domain format' });
        const r = await pool.query(`
            INSERT INTO account_domain_aliases (account_id, domain, source, notes, created_by)
            VALUES ($1, $2, 'manual', $3, $4)
            ON CONFLICT (account_id, domain) DO UPDATE SET notes = EXCLUDED.notes
            RETURNING id, account_id, domain, source, notes, created_at
        `, [account_id, cleaned, notes || null, user.id]);
        res.json({ success: true, alias: r.rows[0] });
    } catch (e) {
        res.json({ success: false, error: e.message });
    }
});

