// =========================================================
// GAS UNIFIED INBOX — Phase 0 (internal channel only)
// =========================================================
// Steve ↔ operator messaging. Same `inbox_messages` schema other channels
// (WhatsApp, web chat, email, Facebook) will plug into later. For now only
// `channel='internal'` is implemented. Thread is one-per-account-pair:
// thread_id = `internal-acct{operatorAccountId}` so all Steve↔operator
// messages naturally group into a single conversation.
//
// Direction convention (relative to the account inbox the message lives in):
//   - master_admin → operator   = direction 'in'  (incoming TO operator)
//   - operator     → master_admin = direction 'out' (outgoing FROM operator)
// =========================================================

// POST /api/admin/inbox/messages — send a message
app.post('/api/admin/inbox/messages', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const { account_id, body, subject, thread_id: threadIdIn, sheet_status } = req.body;
    if (!account_id || !body) return res.json({ success: false, error: 'account_id and body required' });

    const senderId = decoded.id || decoded.accountId;
    const senderRole = decoded.role;

    if (senderRole !== 'master_admin' && parseInt(account_id) !== senderId) {
      return res.status(403).json({ success: false, error: 'Operators can only reply to their own inbox' });
    }

    const direction = senderRole === 'master_admin' ? 'in' : 'out';

    // 2026-08-07 — thread_id now accepted from client so replies APPEND
    // to the existing thread (was always creating a fresh internal
    // thread, orphaning sheet-sourced conversations). Also detects sheet
    // threads and writes the reply back to Karl's Google Sheet reply
    // column so the client sees it in their own surface without logging
    // into GAS.
    let threadId = threadIdIn || `internal-acct${parseInt(account_id)}`;
    let channel = 'internal';
    let sheetChannelId = null;
    let convType = null;

    if (threadIdIn) {
      // Look up existing thread to determine channel + sheet metadata +
      // conversation_type (so the reply lands in the same bucket as
      // whatever the parent thread was classified as — otherwise the
      // reply gets filtered out of both buttons and the thread appears
      // broken).
      const existing = await pool.query(
        `SELECT channel, metadata, conversation_type FROM inbox_messages WHERE thread_id = $1 ORDER BY created_at ASC LIMIT 1`,
        [threadIdIn]
      );
      if (existing.rows.length) {
        channel = existing.rows[0].channel;
        convType = existing.rows[0].conversation_type || null;
        if (channel === 'google_sheets') {
          sheetChannelId = existing.rows[0].metadata?.sheet_channel_id || null;
        }
      }
    }
    // Fallback: internal/new threads default to owner_to_gas (that's
    // what the Messages compose flow was historically for).
    if (!convType) convType = 'owner_to_gas';

    const result = await pool.query(`
      INSERT INTO inbox_messages
        (account_id, channel, thread_id, from_name, from_handle, subject, body, direction, status, conversation_type, created_at)
      VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'unread', $9, NOW())
      RETURNING *
    `, [parseInt(account_id), channel, threadId, decoded.name || 'Unknown', decoded.email || '', subject || null, body, direction, convType]);

    // Sheet writeback — best effort; failure doesn't block the reply from landing in GAS.
    // We now capture the actual write results and surface them in the response so
    // the frontend can distinguish "landed in GAS + sheet" vs "landed in GAS only".
    let sheetReplyWrite = null;
    let sheetStatusWrite = null;
    if (sheetChannelId && typeof writeReplyToClientSheet === 'function') {
      try {
        const origR = await pool.query(
          `SELECT id FROM inbox_messages WHERE thread_id = $1 AND direction = 'out' ORDER BY created_at ASC LIMIT 1`,
          [threadIdIn]
        );
        if (origR.rows[0]) {
          if (body && body !== '(status update)') {
            try {
              sheetReplyWrite = await writeReplyToClientSheet(origR.rows[0].id, body);
              if (!sheetReplyWrite?.success) console.warn('[inbox reply → sheet reply]', sheetReplyWrite?.error);
            } catch (e) {
              sheetReplyWrite = { success: false, error: e.message };
              console.warn('[inbox reply → sheet reply]', e.message);
            }
          }
          if (sheet_status && String(sheet_status).trim() && typeof writeStatusToClientSheet === 'function') {
            try {
              sheetStatusWrite = await writeStatusToClientSheet(origR.rows[0].id, String(sheet_status).trim());
              if (!sheetStatusWrite?.success) console.warn('[inbox reply → sheet status]', sheetStatusWrite?.error);
            } catch (e) {
              sheetStatusWrite = { success: false, error: e.message };
              console.warn('[inbox reply → sheet status]', e.message);
            }
          }
        } else {
          sheetReplyWrite = { success: false, error: 'no original sheet-import row found for this thread — cannot map to a sheet row' };
        }
      } catch (e) {
        sheetReplyWrite = { success: false, error: e.message };
        console.warn('[inbox reply → sheet writeback]', e.message);
      }
    }
    // Mark the thread's original inbound message as replied
    if (threadIdIn) {
      await pool.query(
        `UPDATE inbox_messages SET replied_at = NOW(), status = 'replied' WHERE thread_id = $1 AND id != $2 AND direction = 'out' AND replied_at IS NULL`,
        [threadIdIn, result.rows[0].id]
      ).catch(() => {});
      // If a status was set alongside the reply, update the metadata on the
      // original row too so the UI shows the new status right away (without
      // having to wait for the next sheet sync tick to pull it back).
      if (sheet_status && String(sheet_status).trim()) {
        await pool.query(
          `UPDATE inbox_messages
              SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{sheet_status}', to_jsonb($2::text))
            WHERE thread_id = $1 AND direction = 'out'`,
          [threadIdIn, String(sheet_status).trim()]
        ).catch(() => {});
      }
    }

    res.json({
      success: true,
      message: result.rows[0],
      sheet_reply_write: sheetReplyWrite,
      sheet_status_write: sheetStatusWrite,
    });
  } catch (error) {
    console.error('Inbox send error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// GET /api/admin/inbox/threads — list threads (1 per operator for master, 1 max for operator)
app.get('/api/admin/inbox/threads', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });

    // 2026-08-07 — include google_sheets channel so Google Sheet snags/
    // requests flow into the same client↔GAS-team inbox rather than
    // being buried in the master's unified inbox. Each sheet row is its
    // own thread_id (composite hash) so they list as separate
    // conversations — exactly the shape operators expect for snag
    // tracking. 'internal' = direct compose from master or client.
    const CLIENT_INBOX_CHANNELS = "('internal', 'google_sheets')";
    const isMaster = decoded.role === 'master_admin';
    const query = isMaster
      ? `SELECT m.account_id, a.name AS account_name, m.thread_id, m.channel,
                COUNT(*) FILTER (WHERE m.direction = 'out' AND m.read_at IS NULL)::int AS unread_count,
                MAX(m.created_at) AS last_message_at,
                (SELECT body FROM inbox_messages WHERE thread_id = m.thread_id ORDER BY created_at DESC LIMIT 1) AS last_body,
                (SELECT direction FROM inbox_messages WHERE thread_id = m.thread_id ORDER BY created_at DESC LIMIT 1) AS last_direction,
                (SELECT subject FROM inbox_messages WHERE thread_id = m.thread_id ORDER BY created_at DESC LIMIT 1) AS last_subject
         FROM inbox_messages m
         JOIN accounts a ON a.id = m.account_id
         WHERE m.channel IN ${CLIENT_INBOX_CHANNELS}
         GROUP BY m.account_id, a.name, m.thread_id, m.channel
         ORDER BY last_message_at DESC`
      : `SELECT m.account_id, m.thread_id, m.channel,
                COUNT(*) FILTER (WHERE m.direction = 'in' AND m.read_at IS NULL)::int AS unread_count,
                MAX(m.created_at) AS last_message_at,
                (SELECT body FROM inbox_messages WHERE thread_id = m.thread_id ORDER BY created_at DESC LIMIT 1) AS last_body,
                (SELECT direction FROM inbox_messages WHERE thread_id = m.thread_id ORDER BY created_at DESC LIMIT 1) AS last_direction,
                (SELECT subject FROM inbox_messages WHERE thread_id = m.thread_id ORDER BY created_at DESC LIMIT 1) AS last_subject
         FROM inbox_messages m
         WHERE m.channel IN ${CLIENT_INBOX_CHANNELS} AND m.account_id = $1
         GROUP BY m.account_id, m.thread_id, m.channel
         ORDER BY last_message_at DESC`;

    const result = isMaster ? await pool.query(query) : await pool.query(query, [decoded.id || decoded.accountId]);
    res.json({ success: true, threads: result.rows });
  } catch (error) {
    console.error('Inbox threads error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// POST /api/admin/inbox/threads/:threadId/close — Phase A of the request-to-task
// pipeline (2026-08-07). Marks a thread done: sets every message in the thread
// to status='closed', and if the thread's source channel is 'google_sheets',
// writes 'Done' back to the sheet's status column so the client sees the same
// state in their own sheet. Optional note is written as a final reply first
// (so 'Done — passed to accounts' shows in both places).
app.post('/api/admin/inbox/threads/:threadId/close', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const { threadId } = req.params;
    const { note, status_text } = req.body || {};

    // Auth via first-message account_id (same pattern as thread-messages endpoint)
    const first = await pool.query(
      `SELECT id, account_id, channel, metadata, conversation_type FROM inbox_messages
        WHERE thread_id = $1 AND direction = 'out'
        ORDER BY created_at ASC LIMIT 1`,
      [threadId]
    );
    if (first.rows.length === 0) return res.status(404).json({ success: false, error: 'thread not found' });
    const threadAccountId = first.rows[0].account_id;
    if (decoded.role !== 'master_admin' && (decoded.id || decoded.accountId) !== threadAccountId) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    // Optional final note as a reply — writes to sheet reply column too via the
    // same code path as sendInboxReply.
    if (note && String(note).trim()) {
      const noteBody = String(note).trim();
      const noteConvType = first.rows[0].conversation_type || 'owner_to_gas';
      await pool.query(`
        INSERT INTO inbox_messages (account_id, channel, thread_id, from_name, from_handle, subject, body, direction, status, conversation_type, created_at)
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'unread', $9, NOW())
      `, [threadAccountId, first.rows[0].channel, threadId, decoded.name || 'Steve', decoded.email || '', null, noteBody, decoded.role === 'master_admin' ? 'in' : 'out', noteConvType]);
      if (first.rows[0].channel === 'google_sheets') {
        try { await writeReplyToClientSheet(first.rows[0].id, noteBody); } catch (e) { console.warn('[close-thread reply writeback]', e.message); }
      }
    }

    // Set every message in the thread to status='closed'
    await pool.query(
      `UPDATE inbox_messages SET status = 'closed', replied_at = COALESCE(replied_at, NOW()) WHERE thread_id = $1`,
      [threadId]
    );

    // For google_sheets threads, write 'Done' (or custom status_text) to the sheet status column
    let sheetWrite = null;
    const targetStatus = String(status_text || 'Done').trim();
    if (first.rows[0].channel === 'google_sheets') {
      try {
        sheetWrite = await writeStatusToClientSheet(first.rows[0].id, targetStatus);
      } catch (e) {
        sheetWrite = { success: false, error: e.message };
      }
      // On successful sheet write, refresh our local metadata cache so the
      // chip re-renders immediately without waiting for the next 15-min sync.
      // 2026-08-08 — Steve reported Mark Done writing to the sheet but the
      // chip stayed at the old status because metadata was stale.
      if (sheetWrite?.success) {
        await pool.query(
          `UPDATE inbox_messages
              SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{sheet_status}', to_jsonb($2::text))
            WHERE thread_id = $1 AND direction = 'out'`,
          [threadId, targetStatus]
        ).catch(() => {});
      }
    }

    res.json({ success: true, threadId, sheet_write: sheetWrite });
  } catch (error) {
    console.error('Inbox close-thread error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// GET /api/admin/inbox/threads/:threadId/messages — fetch thread + mark as read
app.get('/api/admin/inbox/threads/:threadId/messages', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const { threadId } = req.params;

    // 2026-08-07 — was hardcoded to accept only 'internal-acctN' pattern
    // (rejected sheet-{chan}-{hash} IDs from google_sheets imports).
    // Now format-agnostic: fetch the thread's account_id from the DB and
    // authorise on that. Works for internal, google_sheets, and any
    // future channels that populate the app-inbox surface.
    const messages = await pool.query(
      `SELECT * FROM inbox_messages WHERE thread_id = $1 ORDER BY created_at ASC`,
      [threadId]
    );
    if (messages.rows.length === 0) return res.json({ success: true, messages: [] });
    const threadAccountId = messages.rows[0].account_id;
    if (decoded.role !== 'master_admin' && (decoded.id || decoded.accountId) !== threadAccountId) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    // Mark messages addressed TO the current viewer as read.
    // Client viewing: mark 'in' (inbound to them — internal composes + sheet imports both count).
    // Master viewing: mark 'out' (outbound to a client, awaiting master's reply is 'in').
    const directionForMe = decoded.role === 'master_admin' ? 'out' : 'in';
    await pool.query(
      `UPDATE inbox_messages SET read_at = NOW(), status = 'read'
       WHERE thread_id = $1 AND direction = $2 AND read_at IS NULL`,
      [threadId, directionForMe]
    );

    res.json({ success: true, messages: messages.rows });
  } catch (error) {
    console.error('Inbox thread messages error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

