// Get content ideas
app.get('/api/admin/content-ideas', async (req, res) => {
    try {
        let { client_id, property_id, content_type, status, account_id, feed_id } = req.query;

        let query = `
            SELECT ci.*, p.name as property_name
            FROM content_ideas ci
            LEFT JOIN properties p ON ci.property_id = p.id
            WHERE 1=1
        `;
        const params = [];
        let paramIndex = 1;

        if (client_id && client_id !== 'null' && client_id !== 'undefined') {
            query += ` AND ci.client_id = $${paramIndex}`;
            params.push(parseInt(client_id));
            paramIndex++;
        }

        if (account_id && account_id !== 'null' && account_id !== 'undefined') {
            query += ` AND ci.client_id = $${paramIndex}`;
            params.push(parseInt(account_id));
            paramIndex++;
        }

        if (property_id) {
            query += ` AND ci.property_id = $${paramIndex}`;
            params.push(parseInt(property_id));
            paramIndex++;
        }

        if (feed_id && feed_id !== 'null' && feed_id !== 'undefined') {
            query += ` AND ci.feed_id = $${paramIndex}`;
            params.push(parseInt(feed_id));
            paramIndex++;
        }

        if (content_type) {
            query += ` AND ci.content_type = $${paramIndex}`;
            params.push(content_type);
            paramIndex++;
        }

        if (status) {
            // Handle comma-separated statuses
            const statuses = status.split(',').map(s => s.trim());
            if (statuses.length === 1) {
                query += ` AND ci.status = $${paramIndex}`;
                params.push(statuses[0]);
                paramIndex++;
            } else {
                query += ` AND ci.status = ANY($${paramIndex})`;
                params.push(statuses);
                paramIndex++;
            }
        }
        
        query += ` ORDER BY ci.created_at DESC`;
        
        const result = await pool.query(query, params);
        res.json({ success: true, ideas: result.rows });
    } catch (error) {
        console.error('Get content ideas error:', error);
        res.json({ success: false, error: error.message });
    }
});

// ============================================================
// Shared helper: pull rich property context for AI prompts
// ============================================================
async function getPropertyContextForAI(pool, { account_id, property_id, deployed_site_id }) {
  const ctx = {
    propertyName: '', location: '', address: '', propertyType: '',
    description: '', starRating: null,
    rooms: [], amenities: [], topAmenities: '',
    pageContent: '',
    checkinFrom: '', checkoutBy: '', checkinInstructions: '', checkoutInstructions: '',
    cancellationPolicy: '',
    contactEmail: '', contactPhone: '',
    attractions: [],
    reviewCount: 0, avgRating: null, reviewHighlights: [],
    blogTopics: [],
    priceRange: ''
  };

  try {
    // 1. Property basics — for multi-property accounts, use account name as brand
    let allPropertyIds = [];
    let propId = null;

    if (property_id) {
      const propResult = await pool.query('SELECT id, name, address, city, state, country, district, property_type, description, star_rating, contact_email, contact_phone FROM properties WHERE id = $1', [property_id]);
      if (propResult.rows[0]) {
        const p = propResult.rows[0];
        propId = p.id;
        allPropertyIds = [p.id];
        ctx.propertyName = p.name || '';
        ctx.address = p.address || '';
        ctx.location = [p.city, p.state, p.country].filter(Boolean).join(', ');
        ctx.propertyType = p.property_type || 'accommodation';
        ctx.description = (p.description || '').substring(0, 500);
        ctx.starRating = p.star_rating;
        ctx.contactEmail = p.contact_email || '';
        ctx.contactPhone = p.contact_phone || '';
      }
    } else if (account_id) {
      // Get ALL properties for the account
      const allProps = await pool.query(
        'SELECT id, name, address, city, state, country, district, property_type, description, star_rating, contact_email, contact_phone FROM properties WHERE account_id = $1 ORDER BY id',
        [account_id]
      );
      allPropertyIds = allProps.rows.map(p => p.id);

      if (allProps.rows.length > 0) {
        propId = allProps.rows[0].id;
        // Use account name as brand for multi-property accounts
        if (allProps.rows.length > 1) {
          const accResult = await pool.query('SELECT name FROM accounts WHERE id = $1', [account_id]);
          ctx.propertyName = accResult.rows[0]?.name || allProps.rows[0].name || '';
        } else {
          ctx.propertyName = allProps.rows[0].name || '';
        }
        // Collect unique locations across all properties
        const locations = new Set();
        allProps.rows.forEach(p => {
          const loc = [p.city, p.country].filter(Boolean).join(', ');
          if (loc) locations.add(loc);
        });
        ctx.location = [...locations].join(' & ');
        ctx.address = allProps.rows[0].address || '';
        ctx.propertyType = allProps.rows[0].property_type || 'accommodation';
        // Combine descriptions
        const descriptions = allProps.rows.map(p => p.description).filter(Boolean);
        ctx.description = descriptions.length > 0 ? descriptions[0].substring(0, 500) : '';
        ctx.starRating = allProps.rows[0].star_rating;
        ctx.contactEmail = allProps.rows.find(p => p.contact_email)?.contact_email || '';
        ctx.contactPhone = allProps.rows.find(p => p.contact_phone)?.contact_phone || '';
      }
    }
    if (!propId) return ctx;

    // 2. Rooms — names, capacity, pricing (from all properties in account)
    const propIdsForRooms = allPropertyIds.length > 0 ? allPropertyIds : [propId];
    const rooms = await pool.query(
      "SELECT name, display_name, max_guests, num_bedrooms, num_bathrooms, base_price, currency, short_description FROM bookable_units WHERE property_id = ANY($1::int[]) AND status != 'deleted' ORDER BY id LIMIT 15",
      [propIdsForRooms]
    );
    ctx.rooms = rooms.rows.map(r => {
      let displayName = r.name;
      if (r.display_name) {
        try {
          const dn = typeof r.display_name === 'string' ? JSON.parse(r.display_name) : r.display_name;
          displayName = dn.en || Object.values(dn)[0] || r.name;
        } catch(e) {}
      }
      return {
        name: displayName,
        guests: r.max_guests,
        bedrooms: r.num_bedrooms,
        bathrooms: r.num_bathrooms,
        price: r.base_price ? parseFloat(r.base_price) : null,
        currency: r.currency || 'EUR',
        description: (r.short_description || '').substring(0, 150)
      };
    });

    // Price range
    const prices = ctx.rooms.map(r => r.price).filter(Boolean);
    if (prices.length > 0) {
      const curr = ctx.rooms[0]?.currency || 'EUR';
      const sym = { EUR: '€', GBP: '£', USD: '$', CHF: 'CHF ' }[curr] || curr + ' ';
      const min = Math.min(...prices);
      const max = Math.max(...prices);
      ctx.priceRange = min === max ? `${sym}${min}/night` : `${sym}${min}–${sym}${max}/night`;
    }

    // 3. Amenities (across all properties)
    const amenities = await pool.query(
      `SELECT DISTINCT ma.amenity_name, ma.category FROM master_amenities ma
       JOIN property_amenities pa ON ma.id = pa.amenity_id
       WHERE pa.property_id = ANY($1::int[]) AND ma.is_active = true
       ORDER BY ma.category, ma.amenity_name LIMIT 30`,
      [propIdsForRooms]
    );
    ctx.amenities = amenities.rows.map(a => {
      const name = typeof a.amenity_name === 'object' ? (a.amenity_name.en || Object.values(a.amenity_name)[0]) : a.amenity_name;
      return { name, category: a.category };
    });
    ctx.topAmenities = ctx.amenities.slice(0, 12).map(a => a.name).join(', ');

    // 4. Terms — check-in/out, cancellation (first property that has them)
    const terms = await pool.query(
      'SELECT checkin_from, checkout_by, check_in_instructions, check_out_instructions, cancellation_policy FROM property_terms WHERE property_id = ANY($1::int[]) LIMIT 1',
      [propIdsForRooms]
    );
    if (terms.rows[0]) {
      ctx.checkinFrom = terms.rows[0].checkin_from || '';
      ctx.checkoutBy = terms.rows[0].checkout_by || '';
      ctx.checkinInstructions = (terms.rows[0].check_in_instructions || '').substring(0, 200);
      ctx.checkoutInstructions = (terms.rows[0].check_out_instructions || '').substring(0, 200);
      ctx.cancellationPolicy = (terms.rows[0].cancellation_policy || '').substring(0, 300);
    }

    // 5. Reviews summary (across all properties)
    const reviews = await pool.query(
      'SELECT rating, title, comment FROM reviews WHERE property_id = ANY($1::int[]) AND is_public = true ORDER BY review_date DESC LIMIT 10',
      [propIdsForRooms]
    );
    ctx.reviewCount = reviews.rows.length;
    if (reviews.rows.length > 0) {
      const ratings = reviews.rows.map(r => parseFloat(r.rating)).filter(r => !isNaN(r));
      ctx.avgRating = ratings.length > 0 ? (ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(1) : null;
      ctx.reviewHighlights = reviews.rows.filter(r => r.title || r.comment).slice(0, 3).map(r => (r.title || r.comment || '').substring(0, 100));
    }

    // 6. Attractions (across all properties)
    const attractions = await pool.query(
      "SELECT DISTINCT ON (name) name, category, distance_text FROM attractions WHERE property_id = ANY($1::int[]) AND is_published = true ORDER BY name, display_order LIMIT 10",
      [propIdsForRooms]
    );
    ctx.attractions = attractions.rows.map(a => ({ name: a.name, category: a.category, distance: a.distance_text }));

    // 7. Blog topics (across all properties + account-level)
    const blogs = await pool.query(
      "SELECT title, category FROM blog_posts WHERE (property_id = ANY($1::int[]) OR client_id = $2) AND is_published = true ORDER BY published_at DESC LIMIT 5",
      [propIdsForRooms, account_id || 0]
    );
    ctx.blogTopics = blogs.rows.map(b => b.title);

    // 8. Website content from Web Builder (the actual text on the site)
    if (deployed_site_id) {
      const ws = await pool.query(
        'SELECT section, settings FROM website_settings WHERE deployed_site_id = $1',
        [deployed_site_id]
      );
      const contentParts = [];
      ws.rows.forEach(row => {
        const s = row.settings;
        if (!s || typeof s !== 'object') return;
        const texts = [];
        for (const [k, v] of Object.entries(s)) {
          // Only grab English text fields (titles, text, subtitles, item texts, headlines)
          if (typeof v === 'string' && v.length > 10 &&
              (k.endsWith('-en') || k === 'headline-en' || k === 'subheadline-en') &&
              !k.includes('color') && !k.includes('url') && !k.includes('image') &&
              !k.includes('font') && !k.includes('icon') && !k.includes('label') &&
              !k.includes('placeholder') && !k.includes('btn-text')) {
            texts.push(v.substring(0, 200));
          }
        }
        if (texts.length > 0) {
          contentParts.push(`[${row.section}] ${texts.join(' | ')}`);
        }
      });
      if (contentParts.length > 0) {
        ctx.pageContent = contentParts.join('\n');
      }
    }

  } catch (e) {
    console.error('getPropertyContextForAI error:', e.message);
  }
  return ctx;
}

// Build a context block string for AI prompts from property data
function buildContextBlock(ctx) {
  let block = `PROPERTY DETAILS:
- Name: ${ctx.propertyName}
- Location: ${ctx.location || 'not specified'}
- Type: ${ctx.propertyType}`;

  if (ctx.address) block += `\n- Address: ${ctx.address}`;
  if (ctx.starRating) block += `\n- Star rating: ${ctx.starRating}`;
  if (ctx.description) block += `\n- Description: ${ctx.description}`;
  if (ctx.priceRange) block += `\n- Price range: ${ctx.priceRange}`;
  if (ctx.topAmenities) block += `\n- Key amenities: ${ctx.topAmenities}`;
  if (ctx.checkinFrom) block += `\n- Check-in from: ${ctx.checkinFrom}`;
  if (ctx.checkoutBy) block += `\n- Check-out by: ${ctx.checkoutBy}`;
  if (ctx.cancellationPolicy) block += `\n- Cancellation policy: ${ctx.cancellationPolicy}`;
  if (ctx.contactEmail) block += `\n- Contact email: ${ctx.contactEmail}`;
  if (ctx.contactPhone) block += `\n- Contact phone: ${ctx.contactPhone}`;
  block += `\n- Booking: Online booking available via the website's "Book Now" page. Guests can select dates, choose a room, and book directly online.`;

  if (ctx.rooms.length > 0) {
    block += '\n\nROOMS/UNITS:';
    ctx.rooms.forEach(r => {
      let line = `- ${r.name}`;
      if (r.guests) line += ` (up to ${r.guests} guests`;
      if (r.bedrooms) line += `, ${r.bedrooms} bed`;
      if (r.bathrooms) line += `, ${r.bathrooms} bath`;
      if (r.guests) line += ')';
      if (r.price) line += ` — from ${r.currency} ${r.price}/night`;
      block += '\n' + line;
    });
  }

  if (ctx.avgRating) {
    block += `\n\nREVIEWS: ${ctx.avgRating}/5 average from ${ctx.reviewCount} reviews`;
    if (ctx.reviewHighlights.length > 0) {
      block += '\nRecent highlights: ' + ctx.reviewHighlights.map(h => `"${h}"`).join('; ');
    }
  }

  if (ctx.attractions.length > 0) {
    block += '\n\nNEARBY ATTRACTIONS:';
    ctx.attractions.slice(0, 5).forEach(a => {
      block += `\n- ${a.name}${a.distance ? ` (${a.distance})` : ''}${a.category ? ` [${a.category}]` : ''}`;
    });
  }

  if (ctx.blogTopics.length > 0) {
    block += '\n\nBLOG TOPICS: ' + ctx.blogTopics.join(', ');
  }

  if (ctx.pageContent) {
    block += '\n\nWEBSITE CONTENT (actual text displayed on the site):\n' + ctx.pageContent;
  }

  return block;
}

// Generate SEO Meta Title & Description with AI
app.post('/api/admin/generate-seo-meta', async (req, res) => {
    try {
        const { page_type, business_name, account_id, property_id, page_content, deployed_site_id } = req.body;

        if (!page_type) {
            return res.json({ success: false, error: 'Page type required' });
        }

        const ctx = await getPropertyContextForAI(pool, { account_id, property_id, deployed_site_id });
        if (business_name && !ctx.propertyName) ctx.propertyName = business_name;
        const contextBlock = buildContextBlock(ctx);

        // Page-specific focus instructions
        const pageFocus = {
            'homepage': `Focus on the overall value proposition. Mention the location, property type, and key selling points (e.g. "${ctx.topAmenities || 'great amenities'}"). Include a booking CTA.`,
            'accommodation/rooms': `Focus on the accommodation offering. Mention ${ctx.rooms.length} room${ctx.rooms.length !== 1 ? 's' : ''}/unit${ctx.rooms.length !== 1 ? 's' : ''} available${ctx.priceRange ? ` starting from ${ctx.priceRange}` : ''}. Highlight room features and capacity. CTA: "Book your stay".`,
            'about us': `Focus on what makes this property unique. Mention the location${ctx.description ? ' and character' : ''}. CTA: "Learn more about us".`,
            'photo gallery': `Focus on the visual experience. Mention what guests can expect to see — the rooms, surroundings, and facilities. CTA: "View our gallery".`,
            'blog': `Focus on travel tips, local guides, and things to do${ctx.location ? ' in ' + ctx.location : ''}. Position as a local knowledge resource. CTA: "Read our latest posts".`,
            'local attractions and things to do': `Focus on ${ctx.attractions.length > 0 ? 'the ' + ctx.attractions.length + ' attractions and activities nearby' : 'nearby attractions and activities'}. Mention specific places if available. CTA: "Explore the area".`,
            'restaurant and dining': `Focus on the dining experience — on-site restaurant, local restaurants, food culture${ctx.location ? ' in ' + ctx.location : ''}. CTA: "Discover dining options".`,
            'contact information': `Focus on how to get in touch and make enquiries. ${ctx.contactEmail ? 'Mention email availability. ' : ''}${ctx.contactPhone ? 'Mention phone availability. ' : ''}CTA: "Get in touch".`,
            'terms and conditions': `Keep it simple and professional. Mention booking terms, ${ctx.cancellationPolicy ? 'cancellation policy, ' : ''}and guest responsibilities.`,
            'privacy policy': `Keep it simple and professional. Mention data protection and guest privacy commitment.`,
            'reviews': `Focus on guest satisfaction. ${ctx.avgRating ? 'Mention ' + ctx.avgRating + '/5 average rating. ' : ''}${ctx.reviewCount > 0 ? 'Mention ' + ctx.reviewCount + ' guest reviews. ' : ''}CTA: "See what our guests say".`,
            'special offers': `Focus on deals and value. Mention current offers and savings available. CTA: "View special offers".`,
            'properties': `Focus on the range of properties available. Mention ${ctx.rooms.length} properties${ctx.location ? ' in ' + ctx.location : ''}. CTA: "Browse all properties".`
        };

        const focus = pageFocus[page_type] || `Focus on the ${page_type} content. Be specific to this property.`;

        const prompt = `Generate an SEO-optimized meta title and meta description for the "${page_type}" page of "${ctx.propertyName}".

${contextBlock}
${page_content ? `\nPAGE CONTENT:\n${page_content.substring(0, 500)}` : ''}

PAGE-SPECIFIC FOCUS:
${focus}

RULES:
- Meta Title: 50-60 characters. MUST include "${ctx.propertyName}"${ctx.location ? ' and "' + ctx.location.split(',')[0].trim() + '"' : ''}. Example format: "Rooms & Rates | ${ctx.propertyName}${ctx.location ? ', ' + ctx.location.split(',')[0].trim() : ''}".
- Meta Description: 150-160 characters. MUST mention the location${ctx.location ? ' (' + ctx.location + ')' : ''}. Must be UNIQUE to this page.
- ALWAYS use the location, address, and other facts from the data above — they are real. Do NOT be vague about location when it is provided.
- NEVER invent additional amenities, policies, prices, or features not listed in the data.
- Use the EXACT property name and location — do not change or abbreviate them.
- Write for humans first, search engines second. Be compelling, not stuffed with keywords.
- Each page must have a distinctly different description that reflects its specific content.

Return ONLY valid JSON with this exact structure, no other text:
{"meta_title": "Your title here", "meta_description": "Your description here"}`;

        const claudeResponse = await axios.post('https://api.anthropic.com/v1/messages', {
            model: 'claude-sonnet-4-6',
            max_tokens: 500,
            messages: [{ role: 'user', content: prompt }]
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01'
            }
        });

        const responseText = claudeResponse.data.content[0].text;

        let result;
        try {
            result = JSON.parse(responseText);
        } catch (e) {
            const jsonMatch = responseText.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                result = JSON.parse(jsonMatch[0]);
            } else {
                throw new Error('Could not parse response');
            }
        }

        res.json({
            success: true,
            meta_title: result.meta_title,
            meta_description: result.meta_description
        });

    } catch (error) {
        console.error('Error generating SEO meta:', error);
        res.json({ success: false, error: error.message });
    }
});

// Generate FAQ schemas with AI
app.post('/api/admin/generate-faqs', async (req, res) => {
    try {
        const { page_type, business_name, account_id, property_id, deployed_site_id } = req.body;

        if (!page_type) {
            return res.json({ success: false, error: 'Page type required' });
        }

        const ctx = await getPropertyContextForAI(pool, { account_id, property_id, deployed_site_id });
        if (business_name && !ctx.propertyName) ctx.propertyName = business_name;
        const contextBlock = buildContextBlock(ctx);

        // Build a list of AVAILABLE data points so the AI only writes about what we have
        const availableData = [];
        if (ctx.propertyName) availableData.push(`Property name: ${ctx.propertyName}`);
        if (ctx.location) availableData.push(`Location: ${ctx.location}`);
        if (ctx.address) availableData.push(`Address: ${ctx.address}`);
        if (ctx.rooms.length > 0) availableData.push(`${ctx.rooms.length} rooms/units: ${ctx.rooms.map(r => r.name + (r.guests ? ' (up to ' + r.guests + ' guests)' : '')).join(', ')}`);
        if (ctx.priceRange) availableData.push(`Pricing: ${ctx.priceRange}`);
        if (ctx.topAmenities) availableData.push(`Amenities: ${ctx.topAmenities}`);
        if (ctx.checkinFrom) availableData.push(`Check-in: from ${ctx.checkinFrom}`);
        if (ctx.checkoutBy) availableData.push(`Check-out: by ${ctx.checkoutBy}`);
        if (ctx.cancellationPolicy) availableData.push(`Cancellation policy: ${ctx.cancellationPolicy}`);
        if (ctx.contactEmail) availableData.push(`Email: ${ctx.contactEmail}`);
        if (ctx.contactPhone) availableData.push(`Phone: ${ctx.contactPhone}`);
        if (ctx.avgRating) availableData.push(`Guest rating: ${ctx.avgRating}/5 from ${ctx.reviewCount} reviews`);
        if (ctx.attractions.length > 0) availableData.push(`Nearby: ${ctx.attractions.map(a => a.name).join(', ')}`);
        availableData.push('Online booking available via the Book Now page');
        if (ctx.pageContent) availableData.push(`\nWEBSITE CONTENT (actual text on the site):\n${ctx.pageContent}`);

        const pageTopics = {
            'homepage': 'the property overall — what it is, where it is, what it offers, how to book',
            'accommodation/rooms': 'the rooms and accommodation — room types, what is included, capacity, how to book',
            'about us': 'the property story, character, location, and what makes it unique',
            'photo gallery': 'the property appearance, rooms, surroundings, and facilities',
            'blog': 'the local area, things to do, travel tips, and seasonal activities',
            'local attractions and things to do': 'nearby places to visit, activities, and getting around',
            'restaurant and dining': 'dining options, kitchens, local restaurants, and food',
            'contact information': 'how to get in touch, make enquiries, and find the property',
            'terms and conditions': 'booking terms, payment, cancellation, and house rules',
            'privacy policy': 'data protection, privacy rights, and how guest data is handled',
            'reviews': 'guest experiences, ratings, and feedback',
            'special offers': 'deals, discounts, and best rates',
            'properties': 'the range of properties available and what each offers'
        };

        const topic = pageTopics[page_type] || `the ${page_type} page content`;

        const prompt = `Generate exactly 5 FAQs for the "${page_type}" page of "${ctx.propertyName}". These will be used as FAQ schema markup for SEO.

PAGE TOPIC: This page is about ${topic}.

AVAILABLE DATA (use ONLY these facts in your answers):
${availableData.map(d => '• ' + d).join('\n')}

ABSOLUTE RULES:
- ONLY create questions that can be answered using the AVAILABLE DATA listed above.
- NEVER create a question if the answer would be "not available", "not specified", "contact the property", or any variation of "we don't have that information". If you can't answer it from the data above, DO NOT include that question.
- Use the data CONFIDENTLY. If it says "Location: Lindau, CH" then say "located in Lindau, Switzerland". If it says "6 rooms" then say "offers 6 apartments". Do not hedge.
- Use the EXACT property name "${ctx.propertyName}".
- Answers must be 2-4 sentences. Specific, confident, helpful.
- Questions must be natural — what a real person would search on Google.
- All 5 FAQs must be relevant to the "${page_type}" page specifically.

Return ONLY a valid JSON array, no other text:
[
  {"question": "Question here?", "answer": "Answer here."},
  {"question": "Question here?", "answer": "Answer here."}
]`;

        const claudeResponse = await axios.post('https://api.anthropic.com/v1/messages', {
            model: 'claude-sonnet-4-6',
            max_tokens: 2000,
            messages: [{ role: 'user', content: prompt }]
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01'
            }
        });

        const responseText = claudeResponse.data.content[0].text;

        let faqs;
        try {
            faqs = JSON.parse(responseText);
        } catch (e) {
            const jsonMatch = responseText.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                faqs = JSON.parse(jsonMatch[0]);
            } else {
                throw new Error('Could not parse FAQ response');
            }
        }

        if (!Array.isArray(faqs)) {
            throw new Error('Invalid FAQ format');
        }

        res.json({ success: true, faqs });

    } catch (error) {
        console.error('Error generating FAQs:', error);
        res.json({ success: false, error: error.message });
    }
});

// Generate website content with AI (intro, about sections)
app.post('/api/admin/ai/generate-website-content', async (req, res) => {
    try {
        const { type, business_name, location, title, account_id, property_id } = req.body;

        if (!type) {
            return res.json({ success: false, error: 'Content type required' });
        }

        // ── Enrich context from PROPERTY data (not account) ──
        let propertyName = business_name || 'Our Property';
        let locationContext = location || '';
        let propertyType = '';
        let propertyDescription = '';
        let roomSummary = '';

        // 1. Fetch property
        const propQuery = property_id
            ? pool.query('SELECT id, name, address, city, state, country, property_type, description FROM properties WHERE id = $1', [property_id])
            : account_id
              ? pool.query('SELECT id, name, address, city, state, country, property_type, description FROM properties WHERE account_id = $1 LIMIT 1', [account_id])
              : null;

        let propId = null;
        if (propQuery) {
            const propResult = await propQuery;
            if (propResult.rows[0]) {
                const prop = propResult.rows[0];
                propId = prop.id;
                if (!business_name && prop.name) propertyName = prop.name;
                if (!location) {
                    const parts = [prop.city, prop.state, prop.country].filter(Boolean);
                    if (parts.length) locationContext = parts.join(', ');
                }
                propertyType = prop.property_type || '';
                propertyDescription = prop.description || '';
            }
        }

        // 2. Fallback to accounts table if property gave no location
        if (!locationContext && account_id) {
            const accResult = await pool.query('SELECT name, city, country FROM accounts WHERE id = $1', [account_id]);
            if (accResult.rows[0]) {
                const acc = accResult.rows[0];
                if (propertyName === 'Our Property' && acc.name) propertyName = acc.name;
                const parts = [acc.city, acc.country].filter(Boolean);
                if (parts.length) locationContext = parts.join(', ');
            }
        }

        // 3. Fetch rooms for richer context
        if (propId) {
            const roomsResult = await pool.query(
                "SELECT name, display_name FROM bookable_units WHERE property_id = $1 AND status != 'deleted' LIMIT 10",
                [propId]
            );
            if (roomsResult.rows.length > 0) {
                const names = roomsResult.rows.map(r => {
                    if (r.display_name) {
                        try {
                            const dn = typeof r.display_name === 'string' ? JSON.parse(r.display_name) : r.display_name;
                            return dn.en || Object.values(dn)[0] || r.name;
                        } catch(e) { return r.name; }
                    }
                    return r.name;
                });
                roomSummary = names.join(', ');
            }
        }

        // 4. Build context block injected into every prompt
        const contextBlock = `PROPERTY DETAILS:
- Name: ${propertyName}
- Location: ${locationContext || 'not specified'}
- Type: ${propertyType || 'accommodation'}
${propertyDescription ? `- Description: ${propertyDescription.substring(0, 300)}` : ''}
${roomSummary ? `- Rooms: ${roomSummary}` : ''}

IMPORTANT: Use the EXACT property name "${propertyName}" and location "${locationContext || 'not specified'}" — do not guess or change them.`;

        let prompt = '';
        
        switch(type) {
            case 'intro_title':
                prompt = `Generate a welcoming, engaging title for the introduction section of a vacation rental website.

${contextBlock}

Requirements:
- Short and impactful (3-6 words)
- Welcoming and inviting tone
- Reference the actual location or property experience
- Do NOT include quotes around the text
- Do NOT include any explanation, just the title text

Generate ONE title only, nothing else:`;
                break;
                
            case 'intro_text':
                prompt = `Generate welcoming introduction text for a vacation rental website.

${contextBlock}
Section Title: ${title || 'Welcome'}

Requirements:
- 2-3 sentences (40-60 words)
- Warm, inviting, and professional tone
- Highlight the experience guests can expect
- Mention the actual location and what makes it special
- Do NOT include quotes around the text
- Do NOT include any explanation or labels

Generate the intro paragraph only, nothing else:`;
                break;
                
            case 'about_title':
                prompt = `Generate an engaging title for the "About Us" section of a vacation rental website.

${contextBlock}

Requirements:
- Short and compelling (3-6 words)
- Should convey experience, quality, or hospitality
- Can reference the location or property character
- Do NOT use "About Us" literally
- Do NOT include quotes around the text
- Do NOT include any explanation

Generate ONE title only, nothing else:`;
                break;
                
            case 'about_text':
                prompt = `Generate compelling "About Us" text for a vacation rental website.

${contextBlock}
Section Title: ${title || 'About Us'}

Requirements:
- 3-4 sentences (60-100 words)
- Professional yet warm tone
- Highlight what makes this specific property special
- Mention the actual location and its appeal
- Reference the type of accommodation and rooms if known
- Do NOT include quotes around the text
- Do NOT include any explanation or labels

Generate the about paragraph only, nothing else:`;
                break;
                
            case 'page_about_title':
                prompt = `Generate an engaging page title for a standalone "About Us" page on a vacation rental website.

${contextBlock}

Requirements:
- 2-5 words
- More formal/professional than homepage section titles
- Can be creative but clear
- Do NOT just use "About Us" - make it unique
- Do NOT include quotes around the text

Generate ONE title only, nothing else:`;
                break;
                
            case 'page_about_content':
                prompt = `Generate comprehensive content for a standalone "About Us" page on a vacation rental website.

${contextBlock}
Page Title: ${title || 'About Us'}

Requirements:
- 3-4 paragraphs (200-300 words total)
- Professional yet warm and personal tone
- Include: the story/history, what makes you unique, your commitment to guests
- Reference the actual location, property type, and rooms/accommodation offered
- Make it feel authentic and specific to this property
- Do NOT use headers or bullet points - just flowing paragraphs
- Do NOT include quotes around the text
- Separate paragraphs with blank lines

Generate the page content only, nothing else:`;
                break;

            case 'property_description':
                // 2026-08-04 — used by the Property edit modal's ✨ AI Generate
                // button. Pushes to Channex → OTAs / Google Hotel Search as the
                // property-level description. Must be plain-text (no HTML),
                // one flowing paragraph, ~120-180 words. Tone: welcoming,
                // travel-guide style, mentions actual location + property type.
                prompt = `Generate a property-level description for a booking website + OTA distribution (Booking.com, Google Hotel Search, Airbnb).

${contextBlock}

Requirements:
- 120-180 words in one flowing paragraph (no line breaks, no headings, no lists)
- Plain text only — no HTML tags, no markdown
- Third person, travel-guide voice (not "we welcome you"; instead "Guests find…")
- Highlight the location's appeal AND what the property offers
- Reference the actual property name, city, and room mix if known
- Avoid marketing clichés ("nestled", "hidden gem", "boutique jewel")
- Do NOT include quotes around the text
- Do NOT include any explanation, header, or label — output the paragraph only

Generate the description now:`;
                break;

            default:
                return res.json({ success: false, error: 'Unknown content type' });
        }
        
        const claudeResponse = await axios.post('https://api.anthropic.com/v1/messages', {
            model: 'claude-sonnet-4-6',
            max_tokens: 1000,
            messages: [{ role: 'user', content: prompt }]
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01'
            }
        });
        
        let content = claudeResponse.data.content[0].text.trim();
        
        // Clean up any quotes or extra formatting
        content = content.replace(/^["']|["']$/g, '').trim();
        
        console.log(`Generated ${type} content:`, content);
        
        res.json({ success: true, content, type });
        
    } catch (error) {
        console.error('Error generating website content:', error);
        res.json({ success: false, error: error.message });
    }
});

// Generate content ideas with AI
app.post('/api/admin/content-ideas/generate', async (req, res) => {
    try {
        const { property_id, content_type, category, count, client_id } = req.body;
        
        if (!property_id) {
            return res.json({ success: false, error: 'Property ID required' });
        }
        
        // Get property info for context (use account_id to join to accounts)
        const propResult = await pool.query(`
            SELECT p.*, a.city as account_city, a.country as account_country,
                   COALESCE(p.account_id, p.client_id) as effective_client_id
            FROM properties p 
            LEFT JOIN accounts a ON p.account_id = a.id
            WHERE p.id = $1
        `, [property_id]);
        
        if (propResult.rows.length === 0) {
            return res.json({ success: false, error: 'Property not found' });
        }
        
        const property = propResult.rows[0];
        const propertyClientId = property.effective_client_id || property.account_id || property.client_id || client_id;
        const location = `${property.city || property.account_city || 'the area'}, ${property.country || property.account_country || ''}`.trim().replace(/,\s*$/, '');
        
        // Current date for time-relevant content
        const now = new Date();
        const currentMonth = now.toLocaleString('en-US', { month: 'long' });
        const currentYear = now.getFullYear();
        const next3Months = [];
        for (let i = 0; i < 3; i++) {
            const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
            next3Months.push(d.toLocaleString('en-US', { month: 'long', year: 'numeric' }));
        }
        
        // Build prompt based on content type
        let prompt = '';
        const numIdeas = count || 10;

        // Pull existing titles for this property + content_type + category so we can
        // tell the AI what to skip. Without this, Find Places / blog ideas keep
        // surfacing the same handful of places every time the user clicks.
        // We also pull from the published table (attractions / blog_posts) since
        // some entries may have skipped the ideas flow entirely.
        let existingTitles = [];
        try {
            const ideaTitles = await pool.query(
                `SELECT DISTINCT title FROM content_ideas
                 WHERE property_id = $1 AND content_type = $2 AND ($3::text IS NULL OR category = $3)`,
                [property_id, content_type, category || null]
            );
            existingTitles = ideaTitles.rows.map(r => r.title);
            if (content_type === 'attraction') {
                const attrTitles = await pool.query(
                    `SELECT DISTINCT name AS title FROM attractions
                     WHERE property_id = $1 AND ($2::text IS NULL OR category = $2)`,
                    [property_id, category || null]
                );
                existingTitles = existingTitles.concat(attrTitles.rows.map(r => r.title));
            } else if (content_type === 'blog') {
                const blogTitles = await pool.query(
                    `SELECT DISTINCT title FROM blog_posts WHERE property_id = $1`,
                    [property_id]
                );
                existingTitles = existingTitles.concat(blogTitles.rows.map(r => r.title));
            }
            // Dedupe + cap to avoid blowing the prompt
            existingTitles = Array.from(new Set(existingTitles.filter(Boolean))).slice(0, 200);
        } catch (e) {
            console.warn('[content-ideas] could not load existing titles for exclusion:', e.message);
        }
        const exclusionBlock = existingTitles.length
            ? `\nDO NOT REPEAT any of these — they have already been suggested or published:\n${existingTitles.map(t => `- ${t}`).join('\n')}\n`
            : '';

        // System instruction prefix with current date context
        const systemPrefix = `You are a local travel expert and content strategist. Today's date is ${currentMonth} ${now.getDate()}, ${currentYear}.

IMPORTANT: Generate content about REAL, ACTUAL places and events. Do not make up fictional events or places.
Always respond with a valid JSON array only, no other text.
${exclusionBlock}`;
        
        if (content_type === 'blog') {
            // Parse category - format is "category_subcategory" like "events_sports" or "attractions_museums"
            const [mainCategory, subCategory] = (category || '').split('_');
            
            let categoryContext = '';
            let topicFocus = '';
            
            if (mainCategory === 'attractions') {
                const subCategoryPrompts = {
                    'museums': 'museums, galleries, and cultural institutions',
                    'landmarks': 'famous landmarks, monuments, and iconic buildings',
                    'parks': 'parks, gardens, nature reserves, and outdoor spaces',
                    'beaches': 'beaches, coastline, and waterfront areas',
                    'restaurants': 'restaurants, local cuisine, and dining experiences',
                    'cafes': 'cafes, coffee shops, and bakeries',
                    'nightlife': 'bars, clubs, pubs, and evening entertainment',
                    'shopping': 'shopping districts, markets, and retail areas',
                    'nature': 'hiking trails, nature walks, and outdoor activities',
                    'daytrips': 'day trip destinations and nearby towns to explore'
                };
                topicFocus = subCategoryPrompts[subCategory] || 'local attractions and places to visit';
                categoryContext = `Write about REAL ${topicFocus} in and around ${location}.
Include actual place names, addresses where known, and what makes each place special.`;
            } else if (mainCategory === 'events') {
                const subCategoryPrompts = {
                    'festivals': 'festivals, cultural celebrations, and annual events',
                    'concerts': 'concerts, live music performances, and music venues',
                    'theater': 'theater performances, shows, and performing arts',
                    'sports': 'sporting events, matches, games, and sports venues',
                    'markets': 'markets, fairs, craft shows, and pop-up events',
                    'cultural': 'cultural events, exhibitions, and community gatherings',
                    'seasonal': 'seasonal activities and events for the current time of year',
                    'holidays': 'holiday events, celebrations, and special occasions',
                    'family': 'family-friendly events and activities for children'
                };
                topicFocus = subCategoryPrompts[subCategory] || 'local events and happenings';
                categoryContext = `Write about UPCOMING ${topicFocus} in ${location}.

CRITICAL: Focus on events happening in the NEXT 3 MONTHS (${next3Months.join(', ')}).
Include:
- Actual event names and venues
- Approximate dates or typical timing
- What visitors can expect
- Why it's worth attending

For sports events, think about:
- Local football/soccer teams and their home matches
- Rugby, cricket, or other popular local sports
- Major sporting venues in the area
- Annual sporting events or tournaments

DO NOT include past events or make up fictional events.`;
            } else {
                categoryContext = `Write about travel tips, local guides, and helpful information for visitors to ${location}.`;
            }
            
            prompt = systemPrefix + `Generate ${numIdeas} unique blog post ideas for a vacation rental property.

Property: ${property.name}
Location: ${location}
Current Date: ${currentMonth} ${currentYear}

TOPIC FOCUS: ${topicFocus}

${categoryContext}

For each idea, provide:
1. A compelling, SEO-friendly title (50-60 characters ideal)
2. A brief description of what the post should cover (1-2 sentences)

Format as JSON array:
[
  {"title": "Blog Title Here", "description": "Brief description of the content"},
  ...
]

Make titles specific to ${location}. Use REAL place names and events.`;

        } else if (content_type === 'attraction') {
            // Parse category for attractions
            const attractionType = category || 'general';
            
            const typePrompts = {
                'museums': 'museums, galleries, and cultural institutions',
                'landmarks': 'historical landmarks, monuments, and famous buildings',
                'parks': 'parks, gardens, and green spaces',
                'beaches': 'beaches and coastal areas',
                'restaurants': 'popular restaurants and dining spots',
                'cafes': 'cafes and coffee shops',
                'nightlife': 'bars, pubs, and nightlife venues',
                'shopping': 'shopping areas and markets',
                'nature': 'nature spots and outdoor areas',
                'family': 'family-friendly attractions and activities'
            };
            
            const focusType = typePrompts[attractionType] || 'local attractions';
            
            prompt = systemPrefix + `Generate ${numIdeas} REAL local ${focusType} to add to a vacation rental website.

Property: ${property.name}
Location: ${location}

Generate ideas for ACTUAL, REAL ${focusType} near ${location} that guests would want to visit.

For each attraction, provide:
1. The REAL name of the place (actual business/venue name)
2. A brief description of what it is and why guests should visit (1-2 sentences)

Format as JSON array:
[
  {"title": "Real Place Name", "description": "Brief description of the attraction"},
  ...
]

IMPORTANT: Only include REAL places that actually exist in ${location}. Be specific with actual names.
If you're not certain a place exists, don't include it.`;

        } else {
            // Fallback for any other type
            prompt = systemPrefix + `Generate ${numIdeas} unique blog post ideas for a vacation rental website.

Property: ${property.name}
Location: ${location}

Format as JSON array:
[
  {"title": "Content Topic", "description": "Brief description of the content"},
  ...
]`;
        }
        
        // Call Claude API (same as blog generator)
        const claudeResponse = await axios.post('https://api.anthropic.com/v1/messages', {
            model: 'claude-sonnet-4-6',
            max_tokens: 2000,
            messages: [{ role: 'user', content: prompt }]
        }, {
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': process.env.ANTHROPIC_API_KEY,
                'anthropic-version': '2023-06-01'
            }
        });
        
        const responseText = claudeResponse.data.content[0].text;
        
        // Parse AI response
        let ideas = [];
        try {
            // Extract JSON from response (handle markdown code blocks)
            const jsonMatch = responseText.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
                ideas = JSON.parse(jsonMatch[0]);
            } else {
                throw new Error('No JSON array found in response');
            }
        } catch (parseError) {
            console.error('Parse error:', parseError);
            return res.json({ success: false, error: 'Failed to parse AI response' });
        }
        
        // Save ideas to database
        const savedIdeas = [];
        for (const idea of ideas) {
            const insertResult = await pool.query(`
                INSERT INTO content_ideas (client_id, property_id, title, description, content_type, category, status)
                VALUES ($1, $2, $3, $4, $5, $6, 'active')
                RETURNING *
            `, [propertyClientId, property_id, idea.title, idea.description, content_type, category]);
            savedIdeas.push(insertResult.rows[0]);
        }
        
        res.json({ success: true, ideas: savedIdeas, count: savedIdeas.length });
        
    } catch (error) {
        console.error('Generate content ideas error:', error);
        res.json({ success: false, error: error.message });
    }
});

// Update idea status
app.put('/api/admin/content-ideas/:id/status', async (req, res) => {
    try {
        const { id } = req.params;
        const { status } = req.body;
        
        if (!['active', 'used', 'archived'].includes(status)) {
            return res.json({ success: false, error: 'Invalid status' });
        }
        
        const result = await pool.query(`
            UPDATE content_ideas 
            SET status = $1, updated_at = CURRENT_TIMESTAMP
            WHERE id = $2
            RETURNING *
        `, [status, id]);
        
        if (result.rows.length === 0) {
            return res.json({ success: false, error: 'Idea not found' });
        }
        
        res.json({ success: true, idea: result.rows[0] });
    } catch (error) {
        console.error('Update idea status error:', error);
        res.json({ success: false, error: error.message });
    }
});

// Update content idea (category, title, description, etc)
app.put('/api/admin/content-ideas/:id', async (req, res) => {
    try {
        const { id } = req.params;
        const { category, title, description, subcategory, event_date, event_location } = req.body;
        
        // Build dynamic update query
        const updates = [];
        const params = [];
        let paramIndex = 1;
        
        if (category !== undefined) {
            updates.push(`category = $${paramIndex++}`);
            params.push(category);
        }
        if (title !== undefined) {
            updates.push(`title = $${paramIndex++}`);
            params.push(title);
        }
        if (description !== undefined) {
            updates.push(`description = $${paramIndex++}`);
            params.push(description);
        }
        if (subcategory !== undefined) {
            updates.push(`subcategory = $${paramIndex++}`);
            params.push(subcategory);
        }
        if (event_date !== undefined) {
            updates.push(`event_date = $${paramIndex++}`);
            params.push(event_date);
        }
        if (event_location !== undefined) {
            updates.push(`event_location = $${paramIndex++}`);
            params.push(event_location);
        }
        
        updates.push(`updated_at = NOW()`);
        
        if (updates.length === 1) {
            return res.json({ success: false, error: 'No fields to update' });
        }
        
        params.push(id);
        const result = await pool.query(`
            UPDATE content_ideas SET ${updates.join(', ')} WHERE id = $${paramIndex} RETURNING *
        `, params);
        
        if (result.rows.length === 0) {
            return res.json({ success: false, error: 'Idea not found' });
        }
        
        res.json({ success: true, idea: result.rows[0] });
    } catch (error) {
        console.error('Update idea error:', error);
        res.json({ success: false, error: error.message });
    }
});

