// Publish attraction
app.put('/api/admin/attractions/:id/publish', async (req, res) => {
    try {
        const { id } = req.params;
        const result = await pool.query(`
            UPDATE attractions 
            SET is_published = true, updated_at = NOW()
            WHERE id = $1
            RETURNING *
        `, [id]);
        
        if (result.rows.length === 0) {
            return res.json({ success: false, error: 'Attraction not found' });
        }

        const a = result.rows[0];
        notifySearchEnginesForAccount(a.client_id, [`/attractions/${a.slug}/`]).catch(() => {});
        res.json({ success: true, attraction: a });
    } catch (error) {
        console.error('Publish attraction error:', error);
        res.json({ success: false, error: error.message });
    }
});

