// Contact form submission (public)
app.post('/api/public/client/:clientId/contact-form', async (req, res) => {
    try {
        const { clientId } = req.params;
        const { name, email, subject, message, page_url, website_url, turnstile_token } = req.body;

        // Honeypot: theme's contact form has a hidden "website_url" field
        // positioned off-screen. Real humans don't see it, bots that fill
        // every field do. Silent 200 — return success so the bot moves on
        // instead of retrying. Steve 2026-08-22 (Dwellfort spam surge).
        if (website_url && String(website_url).trim() !== '') {
            console.log(`[contact-form] honeypot tripped, silently dropping. clientId=${clientId} ip=${req.ip}`);
            return res.json({ success: true });
        }

        if (!name || !email || !message) {
            return res.status(400).json({ success: false, error: 'Name, email and message are required' });
        }

        // Basic email validation
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            return res.status(400).json({ success: false, error: 'Invalid email address' });
        }

        // Turnstile verification — only when the site has "Extra spam
        // protection" enabled in Web Builder → Contact AND the secret
        // env var is configured. Steve 2026-08-22.
        const _turnstileSecret = process.env.CLOUDFLARE_TURNSTILE_SECRET_KEY;
        try {
            const _tsSettings = await pool.query(
                `SELECT settings FROM website_settings ws
                   JOIN deployed_sites ds ON ds.id = ws.deployed_site_id
                  WHERE ds.account_id = $1 AND ws.section = 'page-contact'`,
                [clientId]
            );
            const _tsEnabled = !!(_tsSettings.rows[0]?.settings?.['turnstile-enabled']);
            if (_tsEnabled && _turnstileSecret) {
                if (!turnstile_token) {
                    return res.status(400).json({ success: false, error: 'Missing spam-protection token' });
                }
                const params = new URLSearchParams();
                params.append('secret', _turnstileSecret);
                params.append('response', String(turnstile_token));
                if (req.ip) params.append('remoteip', String(req.ip));
                const verify = await axios.post(
                    'https://challenges.cloudflare.com/turnstile/v0/siteverify',
                    params.toString(),
                    { headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, timeout: 10000 }
                ).catch(e => ({ data: { success: false, error: e.message } }));
                if (!verify.data?.success) {
                    console.warn(`[contact-form] turnstile verify failed. clientId=${clientId} ip=${req.ip} errors=${JSON.stringify(verify.data?.['error-codes'] || verify.data?.error)}`);
                    return res.status(400).json({ success: false, error: 'Spam-protection check failed' });
                }
            }
        } catch (tsErr) {
            // Never let a Turnstile-lookup DB failure block a legit contact
            // submission — log and continue. The honeypot still applies above.
            console.warn(`[contact-form] turnstile setting lookup failed: ${tsErr.message}`);
        }

        // Look up deployed site and account
        const siteResult = await pool.query(
            `SELECT ds.id, ds.account_id, ds.site_url, a.email as admin_email, a.name as account_name
             FROM deployed_sites ds
             JOIN accounts a ON a.id = ds.account_id
             WHERE ds.account_id = $1 ORDER BY ds.id LIMIT 1`, [clientId]
        );

        if (siteResult.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Site not found' });
        }

        const site = siteResult.rows[0];
        const deployedSiteId = site.id;

        // Get page-contact settings to find form-email recipient
        const settingsResult = await pool.query(
            `SELECT settings FROM website_settings WHERE deployed_site_id = $1 AND section = 'page-contact'`,
            [deployedSiteId]
        );

        const contactSettings = settingsResult.rows.length > 0 ? settingsResult.rows[0].settings : {};

        // Recipient priority: form-email > contact email > account admin email
        const recipientEmail = contactSettings['form-email'] || contactSettings['email'] || site.admin_email;

        if (!recipientEmail) {
            console.log(`Contact form for account ${clientId}: no recipient email found`);
            return res.status(500).json({ success: false, error: 'No recipient configured' });
        }

        const siteName = site.account_name || site.site_url || 'Your Website';
        const subjectLine = subject ? `Contact Form: ${subject}` : `New message from ${name} via ${siteName}`;

        await sendEmail({
            to: recipientEmail,
            subject: subjectLine,
            html: `
                <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto;">
                    <div style="background: #1e293b; color: white; padding: 20px 24px; border-radius: 12px 12px 0 0;">
                        <h2 style="margin: 0; font-size: 18px;">New Contact Form Message</h2>
                        <p style="margin: 4px 0 0; opacity: 0.7; font-size: 13px;">${siteName}</p>
                    </div>
                    <div style="background: #f8fafc; padding: 24px; border: 1px solid #e2e8f0; border-top: none; border-radius: 0 0 12px 12px;">
                        <table style="width: 100%; border-collapse: collapse;">
                            <tr><td style="padding: 8px 0; color: #64748b; width: 80px; vertical-align: top;">Name:</td><td style="padding: 8px 0; font-weight: 600;">${name}</td></tr>
                            <tr><td style="padding: 8px 0; color: #64748b; vertical-align: top;">Email:</td><td style="padding: 8px 0;"><a href="mailto:${email}" style="color: #2563eb;">${email}</a></td></tr>
                            ${subject ? `<tr><td style="padding: 8px 0; color: #64748b; vertical-align: top;">Subject:</td><td style="padding: 8px 0;">${subject}</td></tr>` : ''}
                        </table>
                        <div style="margin-top: 16px; padding: 16px; background: white; border-radius: 8px; border: 1px solid #e2e8f0;">
                            <p style="margin: 0; color: #64748b; font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 8px;">Message</p>
                            <p style="margin: 0; white-space: pre-wrap; color: #1e293b; line-height: 1.6;">${message.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</p>
                        </div>
                        <p style="margin: 16px 0 0; font-size: 12px; color: #94a3b8;">Sent from ${page_url || site.site_url || 'contact page'}</p>
                    </div>
                </div>
            `
        });

        console.log(`Contact form sent for account ${clientId} to ${recipientEmail}`);
        res.json({ success: true });
    } catch (error) {
        console.error('Contact form error:', error);
        res.status(500).json({ success: false, error: 'Failed to send message' });
    }
});

// Get blog posts (public)
app.get('/api/public/client/:clientId/blog', async (req, res) => {
    try {
        const { clientId } = req.params;
        const { category, property_id, limit = 10, offset = 0, lang = 'en' } = req.query;
        
        console.log('Public blog API called:', { clientId, property_id, category, limit, lang });
        // is_unlisted column is guaranteed by the startup schema block —
        // moved out of this handler to save a DB metadata round-trip on
        // every public /blog hit (Steve 2026-08-19 speed pass).
        // LEFT JOIN so site-wide posts (no property_id) still appear.
        // is_unlisted filter: GAS Fire drafts default to unlisted so they
        // stay out of the operator's curated /blog listing while still
        // being indexed via sitemap.xml. Direct-slug endpoint below does
        // NOT filter unlisted — pages remain accessible by URL.
        let query = `
            SELECT bp.id, bp.title, bp.slug, bp.excerpt, bp.featured_image_url, bp.category,
                   bp.author_name, bp.read_time_minutes, bp.published_at, bp.client_id, bp.property_id,
                   bp.title_ml, bp.excerpt_ml, bp.meta_title_ml, bp.meta_description_ml,
                   p.name as property_name
            FROM blog_posts bp
            LEFT JOIN properties p ON bp.property_id = p.id
            WHERE bp.is_published = true
              AND (bp.is_unlisted = false OR bp.is_unlisted IS NULL)
              AND bp.client_id = $1
        `;
        const params = [clientId];
        let paramIndex = 2;
        
        // Optional additional property filter
        if (property_id) {
            query += ` AND bp.property_id = $${paramIndex}`;
            params.push(property_id);
            paramIndex++;
        }
        
        if (category) {
            // Slug-based exact match — normalise DB category to the same
            // slug shape as the incoming URL param. "General" → `general`,
            // "General Blogs" → `general-blogs`, "Events & Concerts" →
            // `events-concerts`. Prevents the earlier partial-regex from
            // bleeding "general" into "general blogs" (Steve 2026-07-29).
            query += ` AND LOWER(REGEXP_REPLACE(bp.category, '[^a-zA-Z0-9]+', '-', 'g')) = $${paramIndex}`;
            params.push(category.toLowerCase().replace(/^-+|-+$/g, ''));
            paramIndex++;
        }
        
        // Search filter (title or excerpt)
        if (req.query.search) {
            query += ` AND (bp.title ILIKE $${paramIndex} OR bp.excerpt ILIKE $${paramIndex})`;
            params.push('%' + req.query.search + '%');
            paramIndex++;
        }

        // Total count (same filters, no LIMIT/OFFSET) for pagination
        const countQuery = query.replace(/SELECT[\s\S]+?FROM/, 'SELECT COUNT(*) FROM');
        const countResult = await pool.query(countQuery, params);
        const total = parseInt(countResult.rows[0].count);

        query += ` ORDER BY bp.published_at DESC LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
        params.push(parseInt(limit), parseInt(offset));

        const result = await pool.query(query, params);

        // Apply language-specific content
        const posts = result.rows.map(post => {
            return {
                ...post,
                title: post.title_ml?.[lang] || post.title_ml?.en || post.title,
                excerpt: post.excerpt_ml?.[lang] || post.excerpt_ml?.en || post.excerpt,
                meta_title: post.meta_title_ml?.[lang] || post.meta_title_ml?.en || post.meta_title,
                meta_description: post.meta_description_ml?.[lang] || post.meta_description_ml?.en || post.meta_description,
                category_label: getCategoryLabel(post.category, lang)
            };
        });

        const parsedLimit = parseInt(limit);
        const parsedOffset = parseInt(offset);
        const hasMore = (parsedOffset + parsedLimit) < total;

        // Speed pass (Steve 2026-08-19) — 30s browser cache + 60s
        // stale-while-revalidate. Blog content doesn't change second
        // by second; editor edits show up within 30s of save. Big
        // repeat-visitor + subpage-nav win. Vary by lang because the
        // response body is language-specific.
        res.set('Cache-Control', 'public, max-age=30, stale-while-revalidate=60');
        res.set('Vary', 'Accept-Language');
        res.json({ success: true, posts, total, has_more: hasMore });
    } catch (error) {
        console.error('Public blog API error:', error);
        res.json({ success: false, error: error.message });
    }
});

// Get single blog post (public)
app.get('/api/public/client/:clientId/blog/:slug', async (req, res) => {
    try {
        const { clientId, slug } = req.params;
        const { lang = 'en' } = req.query;
        
        const result = await pool.query(`
            SELECT bp.*, p.name as property_name
            FROM blog_posts bp
            LEFT JOIN properties p ON bp.property_id = p.id
            WHERE bp.client_id = $1 AND bp.slug = $2 AND bp.is_published = true
        `, [clientId, slug]);
        
        if (result.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Post not found' });
        }
        
        const post = result.rows[0];
        
        // Apply language-specific content
        const localizedPost = {
            ...post,
            title: post.title_ml?.[lang] || post.title_ml?.en || post.title,
            excerpt: post.excerpt_ml?.[lang] || post.excerpt_ml?.en || post.excerpt,
            content: post.content_ml?.[lang] || post.content_ml?.en || post.content,
            meta_title: post.meta_title_ml?.[lang] || post.meta_title_ml?.en || post.meta_title,
            meta_description: post.meta_description_ml?.[lang] || post.meta_description_ml?.en || post.meta_description
        };
        
        // Speed pass — 30s cache + 60s SWR (matches blog list endpoint).
        res.set('Cache-Control', 'public, max-age=30, stale-while-revalidate=60');
        res.set('Vary', 'Accept-Language');
        res.json({ success: true, post: localizedPost });
    } catch (error) {
        res.json({ success: false, error: error.message });
    }
});

// GET /api/public/faqs/:clientId/schema — Aggregated FAQ schema from published blog posts
app.get('/api/public/faqs/:clientId/schema', async (req, res) => {
  try {
    const { clientId } = req.params;
    const result = await pool.query(
      `SELECT faq_schema FROM blog_posts
       WHERE client_id = $1 AND is_published = true AND faq_schema IS NOT NULL
       ORDER BY published_at DESC`,
      [clientId]
    );

    if (result.rows.length === 0) {
      return res.json({});
    }

    // Aggregate all FAQ mainEntity items into one FAQPage schema
    const allQuestions = [];
    for (const row of result.rows) {
      const schema = typeof row.faq_schema === 'string' ? JSON.parse(row.faq_schema) : row.faq_schema;
      if (schema && schema.mainEntity && Array.isArray(schema.mainEntity)) {
        allQuestions.push(...schema.mainEntity);
      }
    }

    if (allQuestions.length === 0) {
      return res.json({});
    }

    res.json({
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": allQuestions
    });
  } catch (error) {
    console.error('FAQ schema error:', error);
    res.json({});
  }
});

// Get attractions (public)
app.get('/api/public/client/:clientId/attractions', async (req, res) => {
    try {
        const { clientId } = req.params;
        const { category, property_id, limit, lang = 'en' } = req.query;

        const { offset = 0 } = req.query;

        // LEFT JOIN so site-wide attractions (no property_id) still appear
        let query = `
            SELECT a.id, a.name, a.slug, a.short_description, a.featured_image_url, a.category,
                   a.address, a.city, a.distance_text, a.rating, a.price_range,
                   a.name_ml, a.short_description_ml, a.meta_title_ml, a.meta_description_ml,
                   p.name as property_name
            FROM attractions a
            LEFT JOIN properties p ON a.property_id = p.id
            WHERE a.client_id = $1 AND a.is_published = true
        `;
        const params = [clientId];
        let paramIndex = 2;

        if (property_id) {
            query += ` AND a.property_id = $${paramIndex}`;
            params.push(property_id);
            paramIndex++;
        }

        if (category) {
            const categoryPattern = category.replace(/-/g, '[- &]*');
            query += ` AND LOWER(a.category) ~* $${paramIndex}`;
            params.push(categoryPattern.toLowerCase());
            paramIndex++;
        }

        // Search filter
        if (req.query.search) {
            query += ` AND (a.name ILIKE $${paramIndex} OR a.short_description ILIKE $${paramIndex})`;
            params.push('%' + req.query.search + '%');
            paramIndex++;
        }

        // Total count for pagination
        const countQuery = query.replace(/SELECT[\s\S]+?FROM/, 'SELECT COUNT(*) FROM');
        const countResult = await pool.query(countQuery, params);
        const total = parseInt(countResult.rows[0].count);

        query += ` ORDER BY a.display_order, a.name`;

        const parsedLimit = limit ? parseInt(limit) : 50;
        const parsedOffset = parseInt(offset);
        query += ` LIMIT $${paramIndex} OFFSET $${paramIndex + 1}`;
        params.push(parsedLimit, parsedOffset);

        const result = await pool.query(query, params);

        // Apply language-specific content
        const attractions = result.rows.map(a => ({
            ...a,
            name: a.name_ml?.[lang] || a.name_ml?.en || a.name,
            short_description: a.short_description_ml?.[lang] || a.short_description_ml?.en || a.short_description,
            meta_title: a.meta_title_ml?.[lang] || a.meta_title_ml?.en || a.meta_title,
            meta_description: a.meta_description_ml?.[lang] || a.meta_description_ml?.en || a.meta_description,
            category_label: getCategoryLabel(a.category, lang)
        }));

        const hasMore = (parsedOffset + parsedLimit) < total;
        res.set('Cache-Control', 'public, max-age=30, stale-while-revalidate=60');
        res.set('Vary', 'Accept-Language');
        res.json({ success: true, attractions, total, has_more: hasMore });
    } catch (error) {
        res.json({ success: false, error: error.message });
    }
});

// Get single attraction (public)
app.get('/api/public/client/:clientId/attractions/:slug', async (req, res) => {
    try {
        const { clientId, slug } = req.params;
        const { lang = 'en' } = req.query;
        
        const result = await pool.query(`
            SELECT a.*, p.name as property_name
            FROM attractions a
            LEFT JOIN properties p ON a.property_id = p.id
            WHERE a.client_id = $1 AND a.slug = $2 AND a.is_published = true
        `, [clientId, slug]);
        
        if (result.rows.length === 0) {
            return res.status(404).json({ success: false, error: 'Attraction not found' });
        }
        
        // Get images
        const imagesResult = await pool.query(`
            SELECT image_url, alt_text, caption FROM attraction_images 
            WHERE attraction_id = $1 AND is_active = true
            ORDER BY is_primary DESC, display_order
        `, [result.rows[0].id]);
        
        const a = result.rows[0];
        
        // Apply language-specific content
        const attraction = {
            ...a,
            name: a.name_ml?.[lang] || a.name_ml?.en || a.name,
            short_description: a.short_description_ml?.[lang] || a.short_description_ml?.en || a.short_description,
            description: a.description_ml?.[lang] || a.description_ml?.en || a.description,
            meta_title: a.meta_title_ml?.[lang] || a.meta_title_ml?.en || a.meta_title,
            meta_description: a.meta_description_ml?.[lang] || a.meta_description_ml?.en || a.meta_description,
            images: imagesResult.rows
        };
        
        res.set('Cache-Control', 'public, max-age=30, stale-while-revalidate=60');
        res.set('Vary', 'Accept-Language');
        res.json({ success: true, attraction });
    } catch (error) {
        res.json({ success: false, error: error.message });
    }
});

// =========================================================
// SITEMAP & ROBOTS.TXT - SEO ENDPOINTS
// =========================================================

// Generate sitemap XML for a client. Shared by the per-client and host-based endpoints.
async function buildSitemapXml(clientId, baseUrl) {
    const siteUrl = baseUrl.replace(/\/$/, '');
    // rooms table has no slug/updated_at columns and there are no per-room
    // URLs on the multisite themes — the /book-now/ index covers them all.
    const [pagesResult, blogResult, attractionsResult] = await Promise.all([
        pool.query(`SELECT page_type, slug, updated_at FROM client_pages WHERE client_id = $1 AND is_published = true`, [clientId]),
        pool.query(`SELECT slug, updated_at FROM blog_posts WHERE client_id = $1 AND is_published = true ORDER BY published_at DESC`, [clientId]),
        pool.query(`SELECT slug, updated_at FROM attractions WHERE client_id = $1 AND is_published = true`, [clientId])
    ]);
    const roomsResult = { rows: [] };
        
        const urls = [];
        const now = new Date().toISOString().split('T')[0];
        
        // Homepage - highest priority
        urls.push({
            loc: siteUrl + '/',
            lastmod: now,
            changefreq: 'daily',
            priority: '1.0'
        });
        
        // Book Now / Rooms page
        urls.push({
            loc: siteUrl + '/book-now/',
            lastmod: now,
            changefreq: 'daily',
            priority: '0.9'
        });
        
        // Individual rooms
        roomsResult.rows.forEach(room => {
            urls.push({
                loc: siteUrl + '/room/' + room.slug + '/',
                lastmod: room.updated_at ? new Date(room.updated_at).toISOString().split('T')[0] : now,
                changefreq: 'weekly',
                priority: '0.8'
            });
        });
        
        // Static pages (about, contact, etc.)
        const pageMap = {
            'about': '/about/',
            'contact': '/contact/',
            'gallery': '/gallery/',
            'dining': '/dining/',
            'terms': '/terms/',
            'privacy': '/privacy/',
            'faq': '/faq/'
        };
        
        pagesResult.rows.forEach(page => {
            if (pageMap[page.page_type]) {
                urls.push({
                    loc: siteUrl + pageMap[page.page_type],
                    lastmod: page.updated_at ? new Date(page.updated_at).toISOString().split('T')[0] : now,
                    changefreq: 'monthly',
                    priority: '0.6'
                });
            }
        });
        
        // Blog posts
        if (blogResult.rows.length > 0) {
            urls.push({
                loc: siteUrl + '/blog/',
                lastmod: now,
                changefreq: 'weekly',
                priority: '0.7'
            });
            
            blogResult.rows.forEach(post => {
                urls.push({
                    loc: siteUrl + '/blog/' + post.slug + '/',
                    lastmod: post.updated_at ? new Date(post.updated_at).toISOString().split('T')[0] : now,
                    changefreq: 'monthly',
                    priority: '0.6'
                });
            });
        }
        
        // Attractions
        if (attractionsResult.rows.length > 0) {
            urls.push({
                loc: siteUrl + '/attractions/',
                lastmod: now,
                changefreq: 'weekly',
                priority: '0.7'
            });
            
            attractionsResult.rows.forEach(attraction => {
                urls.push({
                    loc: siteUrl + '/attractions/' + attraction.slug + '/',
                    lastmod: attraction.updated_at ? new Date(attraction.updated_at).toISOString().split('T')[0] : now,
                    changefreq: 'monthly',
                    priority: '0.5'
                });
            });
        }
        
        // Build XML
        let xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
        xml += '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
        
        urls.forEach(url => {
            xml += '  <url>\n';
            xml += '    <loc>' + url.loc + '</loc>\n';
            xml += '    <lastmod>' + url.lastmod + '</lastmod>\n';
            xml += '    <changefreq>' + url.changefreq + '</changefreq>\n';
            xml += '    <priority>' + url.priority + '</priority>\n';
            xml += '  </url>\n';
        });
        
        xml += '</urlset>';
    return xml;
}

app.get('/api/public/client/:clientId/sitemap.xml', async (req, res) => {
    try {
        const { clientId } = req.params;
        const { baseUrl } = req.query;
        if (!baseUrl) return res.status(400).send('<!-- baseUrl query parameter required -->');
        const xml = await buildSitemapXml(clientId, baseUrl);
        res.set('Content-Type', 'application/xml');
        res.send(xml);
    } catch (error) {
        console.error('Sitemap error:', error);
        res.status(500).send('<!-- Error generating sitemap: ' + error.message + ' -->');
    }
});

