// =========================================================
// SEO — host-based sitemap, IndexNow, Google sitemap submit
// =========================================================
// One unified sitemap (WP pages + GAS blog + attractions + rooms + custom pages)
// is served by the gas-booking plugin at https://<site>/sitemap.xml. The plugin
// proxies these three endpoints via host lookup so it doesn't need to know
// client_id. Search engines are notified two ways:
//   • IndexNow ping (covers Bing, Yandex, DuckDuckGo, Yep, Seznam, Naver) —
//     fires within seconds, no API key needed beyond the per-site key file.
//   • Google Search Console sitemaps.submit — Google does not participate in
//     IndexNow so we have to call them separately.

// Resolve a deployed_site by either its primary host or its custom domain.
async function resolveSiteByHost(host) {
    if (!host) return null;
    const h = host.toLowerCase().replace(/^www\./, '').replace(/\/$/, '');
    const r = await pool.query(
        `SELECT id, account_id, site_url, custom_domain, indexnow_key
         FROM deployed_sites
         WHERE LOWER(REGEXP_REPLACE(site_url, '^https?://(www\\.)?', '')) LIKE $1
            OR LOWER(custom_domain) = $2
            OR LOWER(custom_domain) = $3
         LIMIT 1`,
        [h + '%', h, 'https://' + h]
    );
    return r.rows[0] || null;
}

// Host-based sitemap — gas-booking plugin proxies here via header Host or query.
app.get('/api/public/sitemap.xml', async (req, res) => {
    try {
        const host = (req.query.host || req.headers['x-forwarded-host'] || req.headers.host || '').toString().replace(/^https?:\/\//, '').replace(/\/$/, '');
        const site = await resolveSiteByHost(host);
        if (!site) return res.status(404).set('Content-Type', 'application/xml').send('<!-- unknown host -->');
        const xml = await buildSitemapXml(site.account_id, 'https://' + host);
        res.set('Content-Type', 'application/xml');
        res.send(xml);
    } catch (error) {
        console.error('Host sitemap error:', error);
        res.status(500).set('Content-Type', 'application/xml').send('<!-- error -->');
    }
});

// IndexNow key file served at https://<site>/<key>.txt — the plugin proxies the
// request after verifying the URL matches its stored key.
app.get('/api/public/indexnow-key', async (req, res) => {
    const host = (req.query.host || '').toString();
    const site = await resolveSiteByHost(host);
    if (!site || !site.indexnow_key) return res.status(404).send('not found');
    res.set('Content-Type', 'text/plain');
    res.send(site.indexnow_key);
});

// Submit changed URLs to IndexNow (covers Bing, Yandex, DuckDuckGo, Yep,
// Seznam, Naver in one POST). Non-blocking, swallows errors — SEO pings
// must never fail user-facing operations.
async function pingIndexNow(siteUrl, urls) {
    try {
        if (!siteUrl || !urls || !urls.length) return;
        const host = siteUrl.replace(/^https?:\/\//, '').replace(/\/$/, '').toLowerCase();
        const site = await resolveSiteByHost(host);
        if (!site || !site.indexnow_key) return;
        const body = {
            host,
            key: site.indexnow_key,
            keyLocation: `https://${host}/${site.indexnow_key}.txt`,
            urlList: urls
        };
        const r = await fetch('https://api.indexnow.org/IndexNow', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json; charset=utf-8' },
            body: JSON.stringify(body)
        });
        console.log(`[IndexNow] ${host} ← ${urls.length} urls → ${r.status}`);
        if (r.status >= 200 && r.status < 300) {
            pool.query(
                `UPDATE deployed_sites SET last_indexnow_ping_at = NOW(), last_indexnow_ping_count = $1 WHERE id = $2`,
                [urls.length, site.id]
            ).catch(() => {});
        }
    } catch (e) {
        console.log('[IndexNow] error:', e.message);
    }
}

// Submit the sitemap to Google Search Console. Google ignores IndexNow so this
// is the only way to give them a fresh pointer. Non-blocking.
async function submitSitemapToGoogle(siteUrl) {
    try {
        const sc = await getSearchConsoleClient();
        if (!sc || !siteUrl) return;
        const base = siteUrl.replace(/\/$/, '');
        await sc.sitemaps.submit({
            siteUrl: base + '/',
            feedpath: base + '/sitemap.xml'
        });
        console.log(`[GSC] sitemap submitted: ${base}/sitemap.xml`);
        // Record the timestamp so the SEO Status card can show it.
        pool.query(
            `UPDATE deployed_sites SET last_sitemap_submitted_at = NOW() WHERE LOWER(site_url) = $1 OR LOWER(custom_domain) = $2`,
            [siteUrl.toLowerCase(), base.toLowerCase().replace(/^https?:\/\//, '')]
        ).catch(() => {});
    } catch (e) {
        // 404 means the site isn't claimed yet — sites.add() likely hasn't
        // succeeded for this URL. That's fine; sitemap will be picked up via
        // robots.txt once verification completes.
        console.log(`[GSC] sitemap submit failed (${e.code || ''}):`, e.message);
    }
}

// Get a verification meta tag token from Google for this URL. The token
// looks like `<meta name="google-site-verification" content="ABC...">`.
// The gas-booking plugin injects this in <head> via the existing
// inject_seo_meta path, then ensureSiteVerified() tells Google to verify.
async function ensureGSCSiteAdded(siteUrl) {
    const sc = await getSearchConsoleClient();
    if (!sc || !siteUrl) return false;
    try {
        await sc.sites.add({ siteUrl });
        return true;
    } catch (e) {
        // 409 = already added — which is fine.
        if (e.code === 409 || /already added/i.test(e.message)) return true;
        console.log(`[GSC] sites.add(${siteUrl}) failed: ${e.message}`);
        return false;
    }
}

async function getVerificationToken(siteUrl) {
    const sv = await getSiteVerificationClient();
    if (!sv || !siteUrl) return { error: 'siteVerification not initialised (connect Google in SEO panel or check GOOGLE_SERVICE_ACCOUNT env)' };
    try {
        const r = await sv.webResource.getToken({
            requestBody: {
                site: { type: 'SITE', identifier: siteUrl },
                verificationMethod: 'META'
            }
        });
        const tag = r.data.token || '';
        const m = tag.match(/content="([^"]+)"/);
        return { token: m ? m[1] : tag };
    } catch (e) {
        const detail = e.response?.data?.error?.message || e.message;
        console.log(`[GSV] getToken(${siteUrl}) failed: ${detail}`);
        // invalid_grant = the stored refresh token was revoked or expired.
        // Mark the user-OAuth cache dead so downstream probes stop paying the
        // round-trip cost, and surface a specific, actionable error so the
        // UI can say "Reconnect Google in the SEO panel" instead of a raw
        // OAuth string.
        if (/invalid_grant/i.test(detail)) {
            try { markUserOAuthDead(); } catch (_) {}
            return { error: 'Google connection expired (invalid_grant). Click Disconnect Google, then Connect Google again in the SEO panel to refresh the OAuth token.', code: 'invalid_grant' };
        }
        return { error: detail };
    }
}

// Ask Google to verify ownership now. The meta tag must already be live on
// the site — pushSeoVerificationToWordPress() handles that.
async function verifyGSCOwnership(siteUrl) {
    const sv = await getSiteVerificationClient();
    if (!sv || !siteUrl) return false;
    try {
        await sv.webResource.insert({
            verificationMethod: 'META',
            requestBody: {
                site: { type: 'SITE', identifier: siteUrl }
            }
        });
        return true;
    } catch (e) {
        console.log(`[GSV] verify(${siteUrl}) failed: ${e.message}`);
        return false;
    }
}

// Push the verification meta tag content to the WP plugin via existing settings
// sync. The plugin already reads SEO settings and renders <head> tags.
async function pushSeoVerificationToWordPress(siteUrl, token) {
    if (!siteUrl || !token) return false;
    try {
        await pushSettingsToWordPress(siteUrl, 'seo', { 'google_site_verification': token });
        return true;
    } catch (e) {
        console.log(`[GSV push] ${siteUrl} failed: ${e.message}`);
        return false;
    }
}

// Orchestrator: notify every search engine we can about content changes for
// an account. Called from blog/attraction/custom-page CRUD endpoints.
async function notifySearchEnginesForAccount(accountId, changedUrls = null) {
    try {
        if (!accountId) return;
        const sites = await pool.query(
            `SELECT site_url, custom_domain FROM deployed_sites WHERE account_id = $1 AND site_url IS NOT NULL`,
            [accountId]
        );
        for (const s of sites.rows) {
            const targets = [];
            if (s.site_url) targets.push(s.site_url.replace(/\/$/, ''));
            if (s.custom_domain) {
                const cd = s.custom_domain.startsWith('http') ? s.custom_domain : 'https://' + s.custom_domain;
                targets.push(cd.replace(/\/$/, ''));
            }
            for (const t of targets) {
                const urls = changedUrls && changedUrls.length
                    ? changedUrls.map(u => u.startsWith('http') ? u : t + (u.startsWith('/') ? u : '/' + u))
                    : [t + '/', t + '/blog/', t + '/attractions/'];
                pingIndexNow(t, urls).catch(() => {});
                submitSitemapToGoogle(t).catch(() => {});
            }
        }
    } catch (e) {
        console.log('[notifySearchEngines] error:', e.message);
    }
}

