// Documents library — MUST be registered BEFORE the /:section catch-all
// below or Express matches 'documents' as if it were a section name and
// returns 'account_id required' (Steve 2026-07-13 hit this).
app.get('/api/admin/website-builder/documents', async (req, res) => {
  try {
    const siteId = parseInt(req.query.deployed_site_id || req.query.client_id, 10);
    const acctId = parseInt(req.query.account_id, 10);
    if (!siteId && !acctId) return res.json({ success: true, documents: [] });
    let r;
    if (siteId) {
      r = await pool.query(
        `SELECT id, filename, url, size_bytes, content_type, uploaded_at
           FROM deployed_site_documents
          WHERE deployed_site_id = $1 AND deleted_at IS NULL
          ORDER BY uploaded_at DESC`,
        [siteId]
      );
    } else {
      r = await pool.query(
        `SELECT id, filename, url, size_bytes, content_type, uploaded_at
           FROM deployed_site_documents dsd
           JOIN deployed_sites ds ON ds.id = dsd.deployed_site_id
          WHERE ds.account_id = $1 AND dsd.deleted_at IS NULL
          ORDER BY dsd.uploaded_at DESC`,
        [acctId]
      );
    }
    res.json({ success: true, documents: r.rows });
  } catch (e) {
    console.error('[GET documents]', e);
    res.json({ success: false, error: e.message });
  }
});

