// Upload image for website builder (hero, about, etc.)
// Documents library — Steve 2026-07-12. Persistent list of PDFs uploaded
// via the Web Builder Files & Documents card. Table auto-created on first
// hit so no migration needed.
async function _ensureDeployedSiteDocumentsTable() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS deployed_site_documents (
      id             SERIAL PRIMARY KEY,
      deployed_site_id INTEGER NOT NULL,
      filename       VARCHAR(500) NOT NULL,
      url            TEXT NOT NULL,
      size_bytes     BIGINT,
      content_type   VARCHAR(100),
      uploaded_at    TIMESTAMPTZ DEFAULT NOW(),
      deleted_at     TIMESTAMPTZ
    );
    CREATE INDEX IF NOT EXISTS idx_dsd_site_active
      ON deployed_site_documents (deployed_site_id) WHERE deleted_at IS NULL;
  `).catch(e => console.warn('[deployed_site_documents] ensure failed:', e.message));
}
_ensureDeployedSiteDocumentsTable();

app.post('/api/admin/website-builder/upload-image', (req, res, next) => {
  upload.single('image')(req, res, (err) => {
    if (err) {
      console.error('Website image upload multer error:', err.message);
      return res.status(400).json({ success: false, error: err.message });
    }
    next();
  });
}, async (req, res) => {
  try {
    const { account_id, client_id, deployed_site_id, section } = req.body;
    
    if (!req.file) {
      return res.json({ success: false, error: 'No image uploaded' });
    }
    
    // IMPORTANT: Use client_id for website images (maps to deployed site)
    // Fall back to deployed_site_id, then account_id for backwards compatibility
    const entityId = client_id || deployed_site_id || account_id;
    
    if (!entityId) {
      return res.json({ success: false, error: 'client_id, deployed_site_id, or account_id required' });
    }
    
    console.log(`Website image upload: section=${section}, client_id=${client_id}, deployed_site_id=${deployed_site_id}, account_id=${account_id}, using entityId=${entityId}`);
    
    // Check R2 is configured
    if (!r2Client) {
      return res.status(500).json({ success: false, error: 'R2 storage not configured. Check R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY, R2_ENDPOINT env vars.' });
    }
    
    // PDF uploads: skip Sharp (doesn't support PDFs), upload raw file
    // to R2. Used by T&Cs / Privacy "upload PDF" controls in Web Builder.
    if (req.file.mimetype === 'application/pdf') {
      const safeName = (req.file.originalname || 'document.pdf').replace(/[^a-zA-Z0-9._-]/g, '_');
      const key = `documents/${entityId}/${uuidv4()}-${safeName}`;
      await r2Client.send(new PutObjectCommand({
        Bucket: R2_BUCKET,
        Key: key,
        Body: req.file.buffer,
        ContentType: 'application/pdf',
        CacheControl: 'public, max-age=31536000',
        ContentDisposition: `inline; filename="${safeName}"`
      }));
      const url = `${R2_PUBLIC_URL}/${key}`;
      // Steve 2026-07-12 — persist to the documents library so the Web
      // Builder can show a running list. Best-effort: if the INSERT fails
      // the upload still succeeds (URL is returned regardless).
      const _librarySiteId = parseInt(deployed_site_id || client_id, 10);
      if (_librarySiteId) {
        try {
          await pool.query(
            `INSERT INTO deployed_site_documents (deployed_site_id, filename, url, size_bytes, content_type)
             VALUES ($1, $2, $3, $4, $5)`,
            [_librarySiteId, req.file.originalname || safeName, url, req.file.size || null, 'application/pdf']
          );
        } catch (e) { console.warn('[documents library insert]', e.message); }
      }
      // Steve 2026-08-15 — also mirror to gas_media_library so PDFs show
      // up in the Media tab (previously PDFs vanished — uploaded fine but
      // only visible via the Link Builder tab that specifically reads
      // deployed_site_documents). Best-effort insert.
      try {
        await pool.query(
          `INSERT INTO gas_media_library
             (account_id, deployed_site_id, file_url, file_name, file_type, file_size)
           VALUES ($1, $2, $3, $4, 'pdf', $5)`,
          [
            parseInt(account_id, 10) || null,
            _librarySiteId || null,
            url,
            req.file.originalname || safeName,
            req.file.size || null,
          ]
        );
      } catch (e) { console.warn('[gas_media_library pdf insert]', e.message); }
      return res.json({ success: true, url, urls: { original: url, large: url, medium: url, thumbnail: url } });
    }

    // Favicon/icon uploads: skip Sharp (doesn't support .ico), upload raw file directly
    const isIcon = section === 'header-favicon' || section === 'header-apple-icon';
    if (isIcon) {
      const ext = path.extname(req.file.originalname).toLowerCase();
      const uniqueId = uuidv4();
      const key = `website/${section}/${entityId}/${uniqueId}-favicon${ext}`;
      const contentType = ext === '.ico' ? 'image/x-icon' : (ext === '.svg' ? 'image/svg+xml' : req.file.mimetype);

      await r2Client.send(new PutObjectCommand({
        Bucket: R2_BUCKET,
        Key: key,
        Body: req.file.buffer,
        ContentType: contentType,
        CacheControl: 'public, max-age=31536000'
      }));

      const url = `${R2_PUBLIC_URL}/${key}`;
      return res.json({ success: true, url, urls: { original: url, large: url, medium: url, thumbnail: url } });
    }

    // Process and upload to R2
    const results = await processAndUploadImage(
      req.file.buffer,
      `website/${section || 'general'}`,
      entityId,
      req.file.originalname
    );

    // Log to media library
    try {
      const acctId = account_id || req.user?.account_id;
      if (acctId) {
        await pool.query(`INSERT INTO gas_media_library (account_id, deployed_site_id, file_url, file_name, file_type, file_size, thumbnail_url)
          VALUES ($1, $2, $3, $4, 'image', $5, $6)`,
          [acctId, deployed_site_id || null, results.large, req.file.originalname, req.file.size, results.thumbnail || null]);
      }
    } catch (mlErr) { console.error('Media library log error:', mlErr.message); }

    res.json({
      success: true,
      url: results.large, // Use large size for hero images
      urls: results
    });
  } catch (error) {
    console.error('Website image upload error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

