// GET /api/admin/media-library — list media for account
app.get('/api/admin/media-library', async (req, res) => {
  try {
    const accountId = req.query.account_id || req.user?.account_id;
    if (!accountId) return res.status(400).json({ success: false, error: 'account_id required' });

    const { deployed_site_id, file_type, search, limit = 50, offset = 0 } = req.query;

    let where = 'WHERE m.account_id = $1';
    const params = [accountId];
    let paramIdx = 2;

    if (deployed_site_id) {
      where += ` AND (m.deployed_site_id = $${paramIdx} OR m.deployed_site_id IS NULL)`;
      params.push(deployed_site_id);
      paramIdx++;
    }
    if (file_type && file_type !== 'all') {
      where += ` AND m.file_type = $${paramIdx}`;
      params.push(file_type);
      paramIdx++;
    }
    if (search) {
      where += ` AND (m.file_name ILIKE $${paramIdx} OR m.alt_text ILIKE $${paramIdx})`;
      params.push('%' + search + '%');
      paramIdx++;
    }

    params.push(parseInt(limit), parseInt(offset));
    const result = await pool.query(
      `SELECT m.*, ds.site_url FROM gas_media_library m LEFT JOIN deployed_sites ds ON m.deployed_site_id = ds.id
       ${where} ORDER BY m.created_at DESC LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`, params
    );

    // Also get count
    const countResult = await pool.query(
      `SELECT COUNT(*) as total FROM gas_media_library m ${where}`, params.slice(0, paramIdx - 1)
    );

    res.json({ success: true, media: result.rows, total: parseInt(countResult.rows[0].total) });
  } catch (error) {
    console.error('Media library list error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// GET /api/admin/media-library/property-images — get property images for media picker
app.get('/api/admin/media-library/property-images', async (req, res) => {
  try {
    const accountId = req.query.account_id || req.user?.account_id;
    if (!accountId) return res.status(400).json({ success: false, error: 'account_id required' });

    const result = await pool.query(
      `SELECT ri.id, ri.url as file_url, ri.caption as alt_text, r.name as room_name, p.name as property_name, p.id as property_id
       FROM room_images ri
       JOIN rooms r ON ri.room_id = r.id
       JOIN properties p ON r.property_id = p.id
       WHERE p.account_id = $1
       ORDER BY p.name, r.name, ri.sort_order`, [accountId]
    );

    res.json({ success: true, images: result.rows });
  } catch (error) {
    console.error('Property images error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// DELETE /api/admin/media-library/:id — delete media item.
// Cascades:
//   1. gas_media_library row (the tab reads from here)
//   2. deployed_site_documents row (Link Builder tab reads from here — kept
//      in sync via the mirror insert on upload; delete both sides so PDFs
//      don't reappear in Link Builder after they're removed from Media)
//   3. R2 object (avoids storage leak — R2 is billed on bytes stored)
// R2 + sibling table failures are logged but never block the response so
// a stuck row can still be cleared from the UI.
app.delete('/api/admin/media-library/:id', async (req, res) => {
  try {
    const accountId = req.query.account_id || req.user?.account_id;
    const result = await pool.query(
      'DELETE FROM gas_media_library WHERE id = $1 AND account_id = $2 RETURNING *',
      [req.params.id, accountId]
    );
    if (result.rows.length === 0) return res.status(404).json({ success: false, error: 'Not found' });
    const row = result.rows[0];
    const fileUrl = row.file_url || '';

    // Mirror-delete from deployed_site_documents (PDFs live in both tables).
    if (fileUrl) {
      try {
        await pool.query('DELETE FROM deployed_site_documents WHERE url = $1', [fileUrl]);
      } catch (e) { console.warn('[media-library delete] documents mirror:', e.message); }
    }

    // Delete the R2 object. Key is the URL path after R2_PUBLIC_URL.
    if (fileUrl && r2Client && process.env.R2_PUBLIC_URL) {
      try {
        const key = fileUrl.startsWith(process.env.R2_PUBLIC_URL + '/')
          ? fileUrl.slice(process.env.R2_PUBLIC_URL.length + 1)
          : null;
        if (key) {
          await r2Client.send(new DeleteObjectCommand({ Bucket: R2_BUCKET, Key: key }));
        } else {
          console.warn('[media-library delete] cannot derive R2 key from url:', fileUrl);
        }
      } catch (e) { console.warn('[media-library delete] R2 delete:', e.message); }
    }

    res.json({ success: true });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

// PUT /api/admin/media-library/:id — update alt text / tags
app.put('/api/admin/media-library/:id', async (req, res) => {
  try {
    const accountId = req.query.account_id || req.user?.account_id;
    const { alt_text, tags } = req.body;
    const result = await pool.query(
      'UPDATE gas_media_library SET alt_text = COALESCE($1, alt_text), tags = COALESCE($2, tags) WHERE id = $3 AND account_id = $4 RETURNING *',
      [alt_text, tags ? JSON.stringify(tags) : null, req.params.id, accountId]
    );
    if (result.rows.length === 0) return res.status(404).json({ success: false, error: 'Not found' });
    res.json({ success: true, media: result.rows[0] });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

// Video upload for website builder (hero backgrounds, etc.)
const videoUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 100 * 1024 * 1024 }, // 100MB max
  fileFilter: (req, file, cb) => {
    if (file.mimetype.startsWith('video/')) {
      cb(null, true);
    } else {
      cb(new Error('Only video files allowed'), false);
    }
  }
});

app.post('/api/admin/website-builder/upload-video', (req, res, next) => {
  videoUpload.single('video')(req, res, (err) => {
    if (err) {
      console.error('Website video upload multer error:', err.message);
      return res.status(400).json({ success: false, error: err.message });
    }
    next();
  });
}, async (req, res) => {
  try {
    const { account_id, client_id, deployed_site_id, section } = req.body;
    
    if (!req.file) {
      return res.json({ success: false, error: 'No video uploaded' });
    }
    
    // IMPORTANT: Use client_id for website videos (maps to deployed site)
    // Fall back to deployed_site_id, then account_id for backwards compatibility
    const entityId = client_id || deployed_site_id || account_id;
    
    if (!entityId) {
      return res.json({ success: false, error: 'client_id, deployed_site_id, or account_id required' });
    }
    
    console.log(`Website video upload: section=${section}, client_id=${client_id}, using entityId=${entityId}`);
    
    // Generate unique filename
    const ext = req.file.originalname.split('.').pop().toLowerCase();
    const filename = `video-${Date.now()}-${uuidv4().slice(0, 8)}.${ext}`;
    const key = `website/${section || 'hero'}/client-${entityId}/${filename}`;
    
    // Upload directly to R2 (no processing needed for video)
    await r2Client.send(new PutObjectCommand({
      Bucket: R2_BUCKET,
      Key: key,
      Body: req.file.buffer,
      ContentType: req.file.mimetype
    }));
    
    // Construct public URL
    const publicUrl = `${process.env.R2_PUBLIC_URL || 'https://images.gas.travel'}/${key}`;
    
    console.log(`Video uploaded: ${publicUrl}`);
    
    res.json({ 
      success: true, 
      url: publicUrl
    });
  } catch (error) {
    console.error('Website video upload error:', error);
    res.json({ success: false, error: error.message });
  }
});

// Save website builder section settings
app.post('/api/admin/website-builder/:section', async (req, res) => {
  try {
    const { section } = req.params;
    const { account_id, client_id, settings } = req.body;
    const accountId = account_id || client_id;
    
    if (!accountId) {
      return res.json({ success: false, error: 'account_id required' });
    }
    
    // Try update first — only touch account-level rows, never site-specific ones
    const updateResult = await pool.query(
      'UPDATE website_settings SET settings = $1, updated_at = CURRENT_TIMESTAMP WHERE account_id = $2 AND section = $3 AND deployed_site_id IS NULL',
      [JSON.stringify(settings), accountId, section]
    );
    
    if (updateResult.rowCount === 0) {
      // No existing row, insert new one
      await pool.query(
        'INSERT INTO website_settings (account_id, section, settings, updated_at) VALUES ($1, $2, $3, CURRENT_TIMESTAMP)',
        [accountId, section, JSON.stringify(settings)]
      );
      console.log(`Inserted website_settings for account ${accountId}, section ${section}`);
    } else {
      console.log(`Updated ${updateResult.rowCount} website_settings row(s) for account ${accountId}, section ${section}`);
    }
    
    res.json({ success: true, message: 'Settings saved' });
  } catch (error) {
    console.error('Save website settings error:', error);
    res.json({ success: false, error: error.message });
  }
});

