// Find sync property by GAS property ID (for resync)
app.get('/api/gas-sync/properties/by-gas-property/:gasPropertyId', async (req, res) => {
  try {
    const { gasPropertyId } = req.params;
    console.log('Resync lookup for GAS property:', gasPropertyId);
    
    // First try by gas_property_id link
    let result = await pool.query(`
      SELECT sp.*, c.adapter_code
      FROM gas_sync_properties sp
      JOIN gas_sync_connections c ON sp.connection_id = c.id
      WHERE sp.gas_property_id = $1
    `, [gasPropertyId]);
    
    console.log('Direct link result:', result.rows.length, 'rows');
    
    // If not found, try matching by property name
    if (result.rows.length === 0) {
      const propResult = await pool.query('SELECT name, account_id FROM properties WHERE id = $1', [gasPropertyId]);
      console.log('Property lookup:', propResult.rows[0] || 'NOT FOUND');
      
      if (propResult.rows.length > 0) {
        const propName = propResult.rows[0].name;
        const accountId = propResult.rows[0].account_id;
        
        if (!accountId) {
          console.log('Property has no account_id');
          return res.json({ success: false, error: 'Property has no account assigned' });
        }
        
        // Try exact match first
        result = await pool.query(`
          SELECT sp.*, c.adapter_code
          FROM gas_sync_properties sp
          JOIN gas_sync_connections c ON sp.connection_id = c.id
          WHERE sp.name = $1 AND c.account_id = $2
        `, [propName, accountId]);
        
        console.log('Exact name match result:', result.rows.length, 'rows');
        
        // If not found, try partial match (property name contains sync name or vice versa)
        if (result.rows.length === 0) {
          result = await pool.query(`
            SELECT sp.*, c.adapter_code
            FROM gas_sync_properties sp
            JOIN gas_sync_connections c ON sp.connection_id = c.id
            WHERE c.account_id = $1 
            AND ($2 ILIKE '%' || sp.name || '%' OR sp.name ILIKE '%' || $2 || '%')
          `, [accountId, propName]);
          
          console.log('Partial name match result:', result.rows.length, 'rows');
        }
        
        // If found by name, update the link for future
        if (result.rows.length > 0) {
          await pool.query('UPDATE gas_sync_properties SET gas_property_id = $1 WHERE id = $2', [gasPropertyId, result.rows[0].id]);
          console.log('Updated link for future');
        }
      }
    }
    
    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'No sync property found for this GAS property' });
    }
    
    res.json({ success: true, syncProperty: result.rows[0] });
  } catch (error) {
    console.error('Resync lookup error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// Download images for a property (Beds24 V1)
// Debug: show raw Beds24 image data for a sync property
app.get('/api/gas-sync/properties/:propertyId/debug-images', async (req, res) => {
  try {
    const { propertyId } = req.params;
    
    const propResult = await pool.query(`
      SELECT p.connection_id, p.external_id, p.prop_key, c.adapter_code
      FROM gas_sync_properties p
      JOIN gas_sync_connections c ON p.connection_id = c.id
      WHERE p.id = $1
    `, [propertyId]);
    
    if (propResult.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'Property not found' });
    }
    
    const { connection_id, external_id, prop_key, adapter_code } = propResult.rows[0];
    
    const adapter = await syncManager.getAdapterForConnection(connection_id);
    adapter.propKey = prop_key;
    
    // Get raw V1 response - request ALL available data
    const rawResponse = await adapter.v1Request('/getPropertyContent', { 
      images: true,
      bookingData: true,
      texts: true,
      roomIds: true,
      includeAirbnb: true,
      includeVrbo: true
    });
    const content = rawResponse.data?.getPropertyContent?.[0];
    
    const hosted = content?.images?.hosted || {};
    const external = content?.images?.external || {};
    
    // Summarise per room
    const roomSummary = {};
    const processCollection = (collection, source) => {
      for (const [key, img] of Object.entries(collection)) {
        const mappings = img.map || [];
        if (mappings.length === 0) {
          roomSummary['unmapped'] = (roomSummary['unmapped'] || 0) + 1;
        }
        for (const m of mappings) {
          const label = `room_${m.roomId || 'none'}_offer_${m.offerId || 0}`;
          roomSummary[label] = (roomSummary[label] || 0) + 1;
        }
      }
    };
    processCollection(hosted, 'hosted');
    processCollection(external, 'external');
    
    // Show unmapped images detail
    const unmappedImages = [];
    const checkUnmapped = (collection, source) => {
      for (const [key, img] of Object.entries(collection)) {
        if (!img.map || img.map.length === 0) {
          unmappedImages.push({ key, source, url: img.url?.substring(0, 80), fields: Object.keys(img) });
        }
      }
    };
    checkUnmapped(hosted, 'hosted');
    checkUnmapped(external, 'external');
    
    // Show ALL top-level keys in the content response and image structure
    const contentKeys = Object.keys(content || {});
    const imageKeys = Object.keys(content?.images || {});
    
    // Check for room-level image data anywhere in the response
    const roomLevelData = {};
    for (const [topKey, topVal] of Object.entries(content || {})) {
      if (topKey === 'images') continue;
      if (typeof topVal === 'object' && topVal !== null) {
        roomLevelData[topKey] = typeof topVal === 'object' ? 
          (Array.isArray(topVal) ? `array[${topVal.length}]` : `object{${Object.keys(topVal).slice(0,5).join(',')}}`) : typeof topVal;
      }
    }
    
    // Check all sub-keys under images
    const imageSubStructure = {};
    for (const [imgKey, imgVal] of Object.entries(content?.images || {})) {
      if (typeof imgVal === 'object' && imgVal !== null) {
        const count = Object.keys(imgVal).length;
        const sampleKey = Object.keys(imgVal)[0];
        const sampleVal = imgVal[sampleKey];
        imageSubStructure[imgKey] = {
          count,
          sampleFields: sampleVal ? Object.keys(sampleVal) : [],
          sampleUrl: sampleVal?.url?.substring(0, 60) || null
        };
      } else {
        imageSubStructure[imgKey] = imgVal;
      }
    }
    
    res.json({
      success: true,
      external_id,
      hosted_count: Object.keys(hosted).length,
      external_count: Object.keys(external).length,
      total_images: Object.keys(hosted).length + Object.keys(external).length,
      content_top_level_keys: contentKeys,
      image_sub_keys: imageKeys,
      image_sub_structure: imageSubStructure,
      room_level_data: roomLevelData,
      room_summary: roomSummary,
      unmapped_count: unmappedImages.length,
      unmapped_sample: unmappedImages.slice(0, 3),
      sample_hosted: Object.entries(hosted).slice(0, 2).map(([k, v]) => ({ key: k, url: v.url?.substring(0, 80), allFields: Object.keys(v), map: v.map })),
      sample_external: Object.entries(external).slice(0, 2).map(([k, v]) => ({ key: k, url: v.url?.substring(0, 80), allFields: Object.keys(v), map: v.map })),
      // Inspect roomIds structure - might contain per-room image assignments
      roomIds_keys: Object.keys(content?.roomIds || {}),
      roomIds_sample_fields: (() => {
        const rid = content?.roomIds || {};
        const firstKey = Object.keys(rid)[0];
        return firstKey && typeof rid[firstKey] === 'object' ? Object.keys(rid[firstKey]) : 'not an object';
      })(),
      room_100952_data: (() => {
        const r = (content?.roomIds || {})['100952'];
        if (!r) return null;
        // Show all keys and truncate values
        const summary = {};
        for (const [k, v] of Object.entries(r)) {
          if (k === 'images') {
            // Show full image data for this room
            summary[k] = v;
          } else if (typeof v === 'string') summary[k] = v.substring(0, 100);
          else if (Array.isArray(v)) summary[k] = `array[${v.length}]`;
          else if (typeof v === 'object' && v !== null) summary[k] = `object{${Object.keys(v).slice(0,5).join(',')}}`;
          else summary[k] = v;
        }
        return summary;
      })()
    });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

app.post('/api/gas-sync/properties/:propertyId/download-images', async (req, res) => {
  try {
    const { propertyId } = req.params;
    
    const propResult = await pool.query(`
      SELECT p.connection_id, p.external_id, p.prop_key, c.adapter_code
      FROM gas_sync_properties p
      JOIN gas_sync_connections c ON p.connection_id = c.id
      WHERE p.id = $1
    `, [propertyId]);
    
    if (propResult.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'Property not found' });
    }
    
    const { connection_id, external_id, prop_key, adapter_code } = propResult.rows[0];
    
    if (adapter_code !== 'beds24') {
      return res.status(400).json({ 
        success: false, 
        error: 'Image download only supported for Beds24' 
      });
    }
    
    if (!prop_key) {
      return res.status(400).json({
        success: false,
        error: 'Property has no prop_key set. Use /set-prop-key first.'
      });
    }
    
    const adapter = await syncManager.getAdapterForConnection(connection_id);
    
    // Set the property-specific propKey on the adapter
    adapter.propKey = prop_key;
    
    const imagesResult = await adapter.getImages(external_id);
    
    if (!imagesResult.success) {
      return res.status(400).json({ success: false, error: imagesResult.error });
    }
    
    let downloadedCount = 0;
    for (const image of imagesResult.data) {
      // Use adapter's method to properly save room_type_external_id
      await adapter.syncImageToDatabase(image, external_id);
      downloadedCount++;
    }
    
    res.json({ 
      success: true, 
      message: `Downloaded ${downloadedCount} images`,
      images: imagesResult.data
    });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

