app.patch('/api/admin/ghl/settings', async (req, res) => {
  try {
    const { account_id, location_id, private_token } = req.body || {};
    if (!account_id) return res.json({ success: false, error: 'account_id required' });
    const updates = [];
    const params = [account_id];
    if (location_id !== undefined) {
      params.push(String(location_id).trim() || null);
      updates.push(`ghl_location_id = $${params.length}`);
    }
    if (private_token !== undefined) {
      params.push(String(private_token).trim() || null);
      updates.push(`ghl_private_token = $${params.length}`);
    }
    if (updates.length === 0) return res.json({ success: false, error: 'no updates' });
    await pool.query(`UPDATE accounts SET ${updates.join(', ')} WHERE id = $1`, params);
    res.json({ success: true });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

