// Distinct tags across an account's contacts — feeds the tag dropdowns in
// the Action editor and the Contacts filter.
app.get('/api/admin/contacts/tag-list', async (req, res) => {
  try {
    const { account_id } = req.query;
    if (!account_id) return res.json({ success: false, error: 'account_id required' });
    const r = await pool.query(`
      SELECT DISTINCT trim(tag) AS tag
      FROM contacts, unnest(tags) AS tag
      WHERE account_id = $1 AND tag IS NOT NULL AND trim(tag) <> ''
      ORDER BY tag
    `, [account_id]);
    res.json({ success: true, tags: r.rows.map(row => row.tag) });
  } catch (e) { res.json({ success: false, error: e.message }); }
});

// Composite action templates — per-account saved chains
app.get('/api/admin/gas-actions/templates', async (req, res) => {
  try {
    const { account_id } = req.query;
    if (!account_id) return res.json({ success: false, error: 'account_id required' });
    const r = await pool.query(
      `SELECT id, name, icon, description, jsonb_array_length(steps) AS step_count, created_at FROM action_templates WHERE account_id = $1 ORDER BY created_at DESC`,
      [account_id]
    );
    res.json({ success: true, templates: r.rows });
  } catch (e) { res.json({ success: false, error: e.message }); }
});

app.get('/api/admin/gas-actions/templates/:id', async (req, res) => {
  try {
    const r = await pool.query(`SELECT * FROM action_templates WHERE id = $1`, [req.params.id]);
    if (!r.rows[0]) return res.json({ success: false, error: 'not found' });
    res.json({ success: true, template: r.rows[0] });
  } catch (e) { res.json({ success: false, error: e.message }); }
});

app.post('/api/admin/gas-actions/templates', async (req, res) => {
  try {
    const { account_id, name, icon, description, steps } = req.body || {};
    if (!account_id || !name || !Array.isArray(steps) || steps.length === 0) {
      return res.json({ success: false, error: 'account_id, name, and at least one step required' });
    }
    const r = await pool.query(`
      INSERT INTO action_templates (account_id, name, icon, description, steps)
      VALUES ($1, $2, $3, $4, $5::jsonb)
      ON CONFLICT (account_id, name) DO UPDATE SET
        icon = EXCLUDED.icon, description = EXCLUDED.description, steps = EXCLUDED.steps, updated_at = NOW()
      RETURNING id
    `, [account_id, name.trim(), icon || '🧩', description || null, JSON.stringify(steps)]);
    res.json({ success: true, id: r.rows[0].id });
  } catch (e) { res.json({ success: false, error: e.message }); }
});

app.delete('/api/admin/gas-actions/templates/:id', async (req, res) => {
  try {
    await pool.query(`DELETE FROM action_templates WHERE id = $1`, [req.params.id]);
    res.json({ success: true });
  } catch (e) { res.json({ success: false, error: e.message }); }
});

// Per-contact timeline — what happened to this person across every workflow
// they touched. Phase 5 view.
app.get('/api/admin/contacts/:contactId/timeline', async (req, res) => {
  try {
    const contactId = parseInt(String(req.params.contactId).replace(/^c-/, '').replace(/^g-/, ''), 10);
    if (!contactId) return res.json({ success: false, error: 'invalid contact id' });
    const r = await pool.query(`
      SELECT
        wr.id, wr.workflow_id, wr.step_index, wr.status, wr.channel,
        wr.target_email, wr.subject, wr.error, wr.test_run,
        wr.sent_at, wr.next_run_at,
        w.name AS workflow_name, w.recipe_key
      FROM workflow_runs wr
      LEFT JOIN workflows w ON w.id = wr.workflow_id
      WHERE wr.contact_id = $1
      ORDER BY wr.sent_at DESC
      LIMIT 200
    `, [contactId]);
    res.json({ success: true, events: r.rows });
  } catch (e) { res.json({ success: false, error: e.message }); }
});

