// Public — used by the WP plugin to fetch a Spark by slug + site host.
// Resolves the account from the deployed site, then returns the live
// Spark plus the resolved CTA target (offer details / shop product / room).
app.get('/api/public/sparks/by-slug/:slug', async (req, res) => {
  try {
    const { slug } = req.params;
    const { site_url, host } = req.query;
    let accountId = null;
    if (site_url || host) {
      const siteRow = await pool.query(
        `SELECT account_id FROM deployed_sites
         WHERE site_url ILIKE $1 OR custom_domain ILIKE $2
         LIMIT 1`,
        [`%${site_url || host}%`, `%${(host || site_url || '').replace(/^https?:\/\//, '').replace(/\/$/, '')}%`]
      );
      accountId = siteRow.rows[0]?.account_id;
    }
    if (!accountId) return res.json({ success: false, error: 'site not found' });

    // Match by primary slug OR by being in redirect_from_urls (redirect case)
    const r = await pool.query(`
      SELECT * FROM sparks
      WHERE account_id = $1 AND is_published = true
        AND (slug = $2 OR $2 = ANY(redirect_from_urls))
      LIMIT 1
    `, [accountId, slug]);
    if (!r.rows[0]) return res.json({ success: false, error: 'spark not found' });
    const spark = r.rows[0];

    // If matched via redirect_from_urls, signal a 301 to the canonical slug.
    if (spark.slug !== slug) {
      return res.json({ success: true, redirect_to: spark.slug });
    }

    // Resolve CTA target — only include the detail the renderer actually needs.
    let cta = null;
    if (spark.cta_type === 'offer' && spark.linked_offer_id) {
      const o = await pool.query(`SELECT id, name, description, discount_type, discount_value FROM offers WHERE id = $1`, [spark.linked_offer_id]);
      if (o.rows[0]) cta = { type: 'offer', ...o.rows[0], book_url: `/book-now/?offer=${o.rows[0].id}` };
    } else if (spark.cta_type === 'shop_product' && spark.linked_shop_product_id) {
      // gas-shop's rewrite is /shop/{slug}/ — see gas-shop.php add_rewrite_rule.
      // The previous /shop/?product={id} pattern isn't recognised: the plugin
      // ignored the query string and rendered the shop landing grid instead
      // of the picked product. If the product carries an external_url (POS /
      // Eventbrite / whatever) the shop plugin sends grid card clicks straight
      // there, so mirror that here so the Spark CTA does the same.
      const sp = await pool.query(`SELECT id, name, description, price, image_url, slug, external_url FROM shop_products WHERE id = $1`, [spark.linked_shop_product_id]);
      if (sp.rows[0]) {
        const row = sp.rows[0];
        const buy_url = row.external_url
          ? row.external_url
          : (row.slug ? `/shop/${row.slug}/` : `/shop/`);
        cta = { type: 'shop_product', ...row, buy_url };
      }
    } else if (spark.cta_type === 'room' && spark.linked_room_id) {
      const rm = await pool.query(`SELECT bu.id, bu.name, p.id AS property_id FROM bookable_units bu LEFT JOIN properties p ON p.id = bu.property_id WHERE bu.id = $1`, [spark.linked_room_id]);
      if (rm.rows[0]) cta = { type: 'room', ...rm.rows[0], book_url: `/book-now/?room=${rm.rows[0].id}` };
    } else if (spark.cta_type === 'external_url') {
      cta = { type: 'external_url', url: spark.external_url };
    } else if (spark.cta_type === 'form_embed') {
      cta = { type: 'form_embed', html: spark.form_embed_html };
    } else if (spark.cta_type === 'lead_form' && spark.linked_lead_form_id) {
      // Return enough for the WP renderer to draw a native GAS form and
      // POST to /api/public/forms/{account}/{slug}/submit. Mirrors the
      // shape of GET /api/public/forms/:account/:slug.
      const f = await pool.query(
        `SELECT id, account_id, slug, title, description, fields,
                success_message, post_submit_action, redirect_url
           FROM lead_forms
          WHERE id = $1 AND account_id = $2 AND active = true`,
        [spark.linked_lead_form_id, accountId]
      );
      if (f.rows[0]) {
        cta = { type: 'lead_form', form: f.rows[0] };
      }
    }

    // Sparks with Section Builder sections (Steve 2026-07-10) are rendered
    // by the theme's own gas_render_page_sections helper — the WP plugin
    // just calls that with the spark's slug and the page-sections API
    // endpoint above serves sparks.blocks under the same shape as
    // page_sections. Zero rendering happens on this endpoint.
    res.json({ success: true, spark, cta });
  } catch (e) {
    console.error('[sparks public fetch]', e);
    res.json({ success: false, error: e.message });
  }
});

// Render a Spark's blocks as { body_html, head_html } for the WP plugin to
// splice into its page. body_html is a container div with all the section
// markup + inline CSS. head_html is the OG / Twitter / canonical / JSON-LD
// block the plugin drops into <head>.

// Public — Spark funnel event ingest. Called from the WP plugin's Spark
// page on view + CTA click. Fire-and-forget from the client: any failure
// still returns 200 so bad data never blocks the visitor's next action.
// Rate-limit / spam protection is deliberately light for a first pass —
// the endpoint refuses events for Sparks whose site doesn't match the
// caller's site_url (defends against another host logging into your
// account's funnel), and drops unknown event_types.
const SPARK_EVENT_TYPES = new Set(['view', 'click', 'purchase_started', 'purchased']);
app.post('/api/public/spark-event', async (req, res) => {
  try {
    const { site_url, host, spark_id, event_type, session_id, referrer, metadata } = req.body || {};
    if (!spark_id || !event_type || !SPARK_EVENT_TYPES.has(event_type)) return res.json({ success: true, dropped: 'invalid' });

    // Resolve account from the caller's host so we can verify the Spark
    // actually belongs to it before writing an event row.
    const hostArg = (host || site_url || '').replace(/^https?:\/\//, '').replace(/\/$/, '');
    let accountId = null;
    if (hostArg) {
      const siteRow = await pool.query(
        `SELECT account_id FROM deployed_sites WHERE site_url ILIKE $1 OR custom_domain ILIKE $2 LIMIT 1`,
        [`%${hostArg}%`, `%${hostArg}%`]
      );
      accountId = siteRow.rows[0]?.account_id;
    }
    if (!accountId) return res.json({ success: true, dropped: 'unresolved_site' });

    const sparkRow = await pool.query(`SELECT id, account_id FROM sparks WHERE id = $1 AND account_id = $2`, [spark_id, accountId]);
    if (!sparkRow.rows[0]) return res.json({ success: true, dropped: 'spark_not_owned' });

    // Best-effort IP capture for future rate-limiting / dedupe. Truncated
    // to fit the column and drops the "::ffff:" IPv4-in-IPv6 prefix.
    const rawIp = (req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '').toString().split(',')[0].trim().replace(/^::ffff:/, '').slice(0, 63);

    await pool.query(
      `INSERT INTO spark_events (account_id, spark_id, event_type, session_id, referrer, metadata, ip)
       VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7)`,
      [accountId, spark_id, event_type, (session_id || '').slice(0, 63) || null, (referrer || '').slice(0, 2048) || null, JSON.stringify(metadata || {}), rawIp || null]
    );
    res.json({ success: true });
  } catch (e) {
    console.warn('[spark-event]', e.message);
    res.json({ success: true, dropped: 'error' });
  }
});

// Admin — quick funnel snapshot for a single Spark. Powers the counts strip
