// Settings GET/PATCH for the Blog Settings panel
app.get('/api/admin/ai-content/settings', async (req, res) => {
  try {
    const { account_id } = req.query;
    if (!account_id) return res.json({ success: false, error: 'account_id required' });
    // Guarantee ai_content_hide_from_blog column exists before selecting
    // — the migration lives inside /setup-accounts-billing which needs a
    // manual hit; without this the SELECT 500s and the UI's Light-the-fire
    // tick reverts on load (Moonriver 2026-07-14).
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS ai_content_hide_from_blog BOOLEAN DEFAULT true`).catch(() => {});
    const r = await pool.query(
      `SELECT ai_content_enabled, ai_content_post_count, ai_content_last_run_at,
              seo_notification_email, ai_content_hide_from_blog
       FROM accounts WHERE id = $1`,
      [account_id]
    );
    if (!r.rows[0]) return res.json({ success: false, error: 'account not found' });
    // Site base + sitemap URL so the settings panel can link them
    // (Steve wants the sitemap right next to Light the fire so
    // operators can prove Google's indexing the unlisted drafts).
    const site = await pool.query(
      `SELECT site_url, custom_domain FROM deployed_sites
        WHERE account_id = $1 AND COALESCE(site_status,'development') = 'live'
        ORDER BY id LIMIT 1`,
      [account_id]
    );
    let sitemap_url = null;
    if (site.rows[0]) {
      const raw = site.rows[0].custom_domain || site.rows[0].site_url;
      if (raw) {
        const base = raw.startsWith('http') ? raw.replace(/\/$/, '') : ('https://' + raw.replace(/^\/+|\/+$/g, ''));
        sitemap_url = base + '/sitemap.xml';
      }
    }
    res.json({ success: true, settings: r.rows[0], sitemap_url });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

app.patch('/api/admin/ai-content/settings', async (req, res) => {
  try {
    const { account_id, enabled, post_count, seo_notification_email, hide_from_blog } = req.body || {};
    if (!account_id) return res.json({ success: false, error: 'account_id required' });
    // Same defensive migration as the GET — if this column doesn't
    // exist the whole UPDATE fails silently and the tick reverts.
    await pool.query(`ALTER TABLE accounts ADD COLUMN IF NOT EXISTS ai_content_hide_from_blog BOOLEAN DEFAULT true`).catch(() => {});
    const updates = [];
    const params = [account_id];
    if (typeof enabled === 'boolean') {
      params.push(enabled);
      updates.push(`ai_content_enabled = $${params.length}`);
    }
    if (post_count !== undefined) {
      params.push(Math.min(10, Math.max(1, parseInt(post_count, 10) || 5)));
      updates.push(`ai_content_post_count = $${params.length}`);
    }
    if (seo_notification_email !== undefined) {
      // Empty string -> NULL so the column reads as "not set" rather than ""
      const cleaned = String(seo_notification_email || '').trim();
      params.push(cleaned || null);
      updates.push(`seo_notification_email = $${params.length}`);
    }
    if (typeof hide_from_blog === 'boolean') {
      params.push(hide_from_blog);
      updates.push(`ai_content_hide_from_blog = $${params.length}`);
    }
    if (updates.length === 0) return res.json({ success: false, error: 'no updates' });
    // Return the updated row so the client can verify what actually
    // landed in the DB — the 'Light the fire' checkbox was reverting
    // to unticked; this makes any silent PATCH failure visible.
    const upd = await pool.query(
      `UPDATE accounts SET ${updates.join(', ')} WHERE id = $1
         RETURNING id, ai_content_enabled, ai_content_post_count, ai_content_hide_from_blog`,
      params
    );
    res.json({ success: true, settings: upd.rows[0] || null });
  } catch (e) {
    res.json({ success: false, error: e.message });
  }
});

// Shared helper — any auto-SEO subsystem (GAS Fire, sitemap re-submit,
// indexing checks, etc.) calls this so the SEO manager hears about it.
async function notifySeoManager(accountId, subject, html) {
  try {
    const r = await pool.query(`SELECT seo_notification_email FROM accounts WHERE id = $1`, [accountId]);
    const to = r.rows[0]?.seo_notification_email;
    if (!to) return { success: false, skipped: 'no_email_configured' };
    return await sendEmail({ to, subject, html, accountId, localPart: 'seo' });
  } catch (e) {
    console.warn('[notifySeoManager]', e.message);
    return { success: false, error: e.message };
  }
}

