// Debug: Test calendar API with connection token
app.get('/api/admin/debug/beds24-calendar/:connectionId/:roomId', async (req, res) => {
  try {
    const { connectionId, roomId } = req.params;
    
    // Get connection with token - same approach as main sync
    const result = await pool.query('SELECT * FROM gas_sync_connections WHERE id = $1', [connectionId]);
    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Connection not found' });
    }
    
    const conn = result.rows[0];
    let accessToken = conn.access_token;
    
    // Refresh token if needed - same as main sync
    if (conn.refresh_token) {
      try {
        const tokenResponse = await axios.get('https://beds24.com/api/v2/authentication/token', {
          headers: { 'refreshToken': conn.refresh_token }
        });
        accessToken = tokenResponse.data.token;
        await pool.query('UPDATE gas_sync_connections SET access_token = $1 WHERE id = $2', [accessToken, connectionId]);
      } catch (e) {
        // If refresh fails, try existing token
        console.log(`[Debug] Token refresh failed for connection ${connectionId}, trying stored token`);
      }
    }
    
    if (!accessToken) {
      return res.json({ success: false, error: 'No access token and refresh failed' });
    }
    
    const startDate = req.query.startDate || new Date().toISOString().split('T')[0];
    const endDate = req.query.endDate || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    
    // Use EXACT same params as the real sync
    const calResponse = await axios.get('https://beds24.com/api/v2/inventory/rooms/calendar', {
      headers: { 'token': accessToken },
      params: { 
        roomId: parseInt(roomId), 
        startDate, 
        endDate,
        includeNumAvail: true,
        includePrices: true,
        includeMinStay: true,
        includeMultiplier: true
      }
    });
    
    const calendarData = calResponse.data.data?.[0]?.calendar || [];
    
    // Extract ALL unique field names across all entries
    const allFields = new Set();
    calendarData.forEach(entry => {
      Object.keys(entry).forEach(key => allFields.add(key));
    });
    
    // Flag which entries have price2 or other price fields
    const priceFieldSummary = {};
    allFields.forEach(field => {
      if (field.toLowerCase().includes('price')) {
        const nonNullCount = calendarData.filter(e => e[field] !== null && e[field] !== undefined && e[field] !== 0).length;
        priceFieldSummary[field] = { total: calendarData.length, nonNull: nonNullCount };
      }
    });
    
    res.json({
      success: true,
      connectionId,
      roomId,
      startDate,
      endDate,
      tokenRefreshed: !!conn.refresh_token,
      totalEntries: calendarData.length,
      allFieldsFound: [...allFields].sort(),
      priceFieldSummary,
      rawEntries: calendarData,
      rawApiResponse: calResponse.data
    });
  } catch (error) {
    res.json({ success: false, error: error.message, details: error.response?.data });
  }
});

// Admin: Resync a single room from Beds24 (BASE price × room multiplier + own min_stay)
app.post('/api/admin/debug/beds24-resync-room/:connectionId/:beds24RoomId', async (req, res) => {
  try {
    const { connectionId, beds24RoomId } = req.params;
    const days = parseInt(req.query.days) || 365;
    
    const connResult = await pool.query('SELECT * FROM gas_sync_connections WHERE id = $1', [connectionId]);
    if (connResult.rows.length === 0) return res.json({ success: false, error: 'Connection not found' });
    const conn = connResult.rows[0];
    
    // Refresh token
    let accessToken = conn.access_token;
    if (conn.refresh_token) {
      const tokenResponse = await axios.get('https://beds24.com/api/v2/authentication/token', {
        headers: { 'refreshToken': conn.refresh_token }
      });
      accessToken = tokenResponse.data.token;
      await pool.query('UPDATE gas_sync_connections SET access_token = $1 WHERE id = $2', [accessToken, connectionId]);
    }
    
    // Find GAS room ID and price linking
    const roomResult = await pool.query(`
      SELECT rt.gas_room_id, rt.price_linking, rt.name, rt.external_id
      FROM gas_sync_room_types rt
      JOIN gas_sync_properties sp ON sp.id = rt.sync_property_id
      WHERE sp.connection_id = $1 AND rt.external_id = $2
    `, [connectionId, beds24RoomId]);
    
    if (roomResult.rows.length === 0) return res.json({ success: false, error: 'Room not found in sync mappings' });
    const room = roomResult.rows[0];
    const linking = room.price_linking ? (typeof room.price_linking === 'string' ? JSON.parse(room.price_linking) : room.price_linking) : null;
    
    const startDate = new Date().toISOString().split('T')[0];
    const endDate = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    
    // Step 1: Fetch this room's own calendar (multiplier, min_stay, availability)
    const calResponse = await axios.get('https://beds24.com/api/v2/inventory/rooms/calendar', {
      headers: { 'token': accessToken },
      params: { roomId: parseInt(beds24RoomId), startDate, endDate, includeNumAvail: true, includePrices: true, includeMinStay: true, includeMultiplier: true }
    });
    const calendarData = calResponse.data.data?.[0]?.calendar || [];
    
    // Build per-day map from room's own calendar
    const roomDayMap = {};
    for (const entry of calendarData) {
      const from = new Date(entry.from);
      const to = new Date(entry.to);
      for (let d = new Date(from); d <= to; d.setDate(d.getDate() + 1)) {
        const dateStr = d.toISOString().split('T')[0];
        roomDayMap[dateStr] = {
          multiplier: entry.multiplier || 1,
          minStay: entry.minStay || 1,
          numAvail: entry.numAvail || 0,
          ownPrice: (entry.price1 !== undefined && entry.price1 !== null) ? entry.price1 : (entry.price2 !== undefined && entry.price2 !== null) ? entry.price2 : null
        };
      }
    }
    
    await new Promise(resolve => setTimeout(resolve, 2000)); // Rate limit between API calls
    
    // Step 2: Get BASE prices - either from source room API or this room's own prices
    let baseDayMap = {};
    let priceSource = 'direct';
    
    if (linking && linking.sourceRoomId) {
      // Fetch BASE room calendar for prices
      priceSource = 'base-x-multiplier';
      const baseCalResponse = await axios.get('https://beds24.com/api/v2/inventory/rooms/calendar', {
        headers: { 'token': accessToken },
        params: { roomId: parseInt(linking.sourceRoomId), startDate, endDate, includePrices: true }
      });
      const baseCalendar = baseCalResponse.data.data?.[0]?.calendar || [];
      
      for (const entry of baseCalendar) {
        const from = new Date(entry.from);
        const to = new Date(entry.to);
        for (let d = new Date(from); d <= to; d.setDate(d.getDate() + 1)) {
          baseDayMap[d.toISOString().split('T')[0]] = (entry.price1 !== undefined && entry.price1 !== null) ? entry.price1 : (entry.price2 !== undefined && entry.price2 !== null) ? entry.price2 : null;
        }
      }
    }
    
    // Step 3: Write prices to room_availability
    let daysUpdated = 0;
    let samplePrices = [];
    
    for (const [dateStr, day] of Object.entries(roomDayMap)) {
      let finalPrice = null;
      
      if (linking && linking.sourceRoomId && baseDayMap[dateStr]) {
        // Linked room: BASE price × this room's multiplier
        finalPrice = Math.round(parseFloat(baseDayMap[dateStr]) * day.multiplier * 100) / 100;
      } else if (day.ownPrice) {
        // Direct room or no base price: use own price × multiplier
        finalPrice = Math.round(parseFloat(day.ownPrice) * day.multiplier * 100) / 100;
      }
      
      if (samplePrices.length < 5) {
        samplePrices.push({ date: dateStr, basePrice: baseDayMap[dateStr] || null, multiplier: day.multiplier, finalPrice, minStay: day.minStay });
      }
      
      await pool.query(`
        INSERT INTO room_availability (room_id, date, price, cm_price, direct_price, is_available, is_blocked, min_stay, cm_min_stay, source, updated_at)
        VALUES ($1, $2, $3, $3, $3, $4, $5, $6, $6, 'beds24-offers', NOW())
        ON CONFLICT (room_id, date) DO UPDATE SET
          price = CASE WHEN $3 IS NOT NULL THEN $3 ELSE room_availability.price END,
          cm_price = CASE WHEN $3 IS NOT NULL THEN $3 ELSE room_availability.cm_price END,
          direct_price = COALESCE($3, room_availability.direct_price),
          is_available = $4, is_blocked = $5,
          min_stay = CASE WHEN room_availability.min_stay_override IS NOT NULL THEN room_availability.min_stay ELSE $6 END,
          cm_min_stay = $6, source = 'beds24-offers', updated_at = NOW()
      `, [room.gas_room_id, dateStr, finalPrice, day.numAvail > 0 && finalPrice !== null, day.numAvail === 0, day.minStay]);
      daysUpdated++;
    }
    
    res.json({
      success: true,
      room: { gas_id: room.gas_room_id, beds24_id: beds24RoomId, name: room.name },
      pricing: { method: priceSource, sourceRoomId: linking?.sourceRoomId || null },
      samplePrices,
      daysUpdated,
      dateRange: { startDate, endDate }
    });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

