// GET /api/turbines/availability-gaps - Find gaps in availability for campaign targeting
app.get('/api/turbines/availability-gaps', async (req, res) => {
  try {
    const { account_id, property_id, min_gap_nights = 3, days_ahead = 90 } = req.query;
    
    if (!account_id) {
      return res.status(400).json({ success: false, error: 'account_id required' });
    }
    
    // Get all rooms for the account/property
    let roomQuery = `
      SELECT bu.id, bu.name, bu.property_id, p.name as property_name
      FROM bookable_units bu
      JOIN properties p ON p.id = bu.property_id
      WHERE p.account_id = $1
    `;
    const roomParams = [account_id];
    
    if (property_id) {
      roomQuery += ' AND bu.property_id = $2';
      roomParams.push(property_id);
    }
    
    const rooms = await pool.query(roomQuery, roomParams);
    
    const gaps = [];
    const startDate = new Date();
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + parseInt(days_ahead));
    
    for (const room of rooms.rows) {
      // Get bookings for this room in the date range
      const bookings = await pool.query(`
        SELECT check_in, check_out FROM bookings
        WHERE room_id = $1 AND status != 'cancelled'
        AND check_in <= $2 AND check_out >= $3
        ORDER BY check_in
      `, [room.id, endDate, startDate]);
      
      // Find gaps between bookings
      let currentDate = new Date(startDate);
      
      for (const booking of bookings.rows) {
        const bookingStart = new Date(booking.check_in);
        const gapNights = Math.floor((bookingStart - currentDate) / (1000 * 60 * 60 * 24));
        
        if (gapNights >= parseInt(min_gap_nights)) {
          gaps.push({
            room_id: room.id,
            room_name: room.name,
            property_id: room.property_id,
            property_name: room.property_name,
            gap_start: currentDate.toISOString().split('T')[0],
            gap_end: bookingStart.toISOString().split('T')[0],
            nights: gapNights
          });
        }
        
        currentDate = new Date(booking.check_out);
      }
      
      // Check gap after last booking
      const gapNights = Math.floor((endDate - currentDate) / (1000 * 60 * 60 * 24));
      if (gapNights >= parseInt(min_gap_nights)) {
        gaps.push({
          room_id: room.id,
          room_name: room.name,
          property_id: room.property_id,
          property_name: room.property_name,
          gap_start: currentDate.toISOString().split('T')[0],
          gap_end: endDate.toISOString().split('T')[0],
          nights: gapNights
        });
      }
    }
    
    res.json({ success: true, gaps: gaps.sort((a, b) => new Date(a.gap_start) - new Date(b.gap_start)) });
  } catch (error) {
    console.error('Get availability gaps error:', error);
    res.json({ success: false, error: error.message });
  }
});

// ============================================


// ============================================
// FACEBOOK OAUTH - TURBINE CONNECTIONS
// ============================================

// ─── WhatsApp Embedded Signup ──────────────────────────────────────────────
// Multi-tenant WABA onboarding via Meta's Embedded Signup flow. Each client
// account clicks "Connect WhatsApp" → FB.login popup → Meta walks them
// through business + phone-number selection → returns auth code + waba_id
// + phone_number_id directly to our complete endpoint. We exchange the code
// for a system-user token, persist to gas_whatsapp_configs(account_id),
// and programmatically subscribe our app to that WABA's webhooks.
//
// Required env vars:
//   FACEBOOK_APP_ID       — your Meta app ID (shared with Turbine FB OAuth)
//   FACEBOOK_APP_SECRET   — your Meta app secret (shared with Turbine FB OAuth)
//   FB_WHATSAPP_CONFIG_ID — the Configuration ID Meta provides after
//                          Embedded Signup setup in your WhatsApp Business
//                          Platform product. Found at:
//                            app dashboard → WhatsApp → Configuration → ESU

// Returns the public values the frontend's FB SDK needs to launch the
// Embedded Signup popup. App ID is public (it gets embedded in browsers
// anyway); app secret stays server-side and only touches the token
// exchange. Config ID is also safe to expose.
app.get('/api/whatsapp/embedded-signup/config', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        // Both master AND account admins can see the config — the UI on
        // each account's settings page calls this before launching FB.
        const appId = process.env.FACEBOOK_APP_ID;
        const configId = process.env.FB_WHATSAPP_CONFIG_ID;
        if (!appId || !configId) {
            return res.status(500).json({
                error: 'WhatsApp Embedded Signup not configured on the server',
                missing: [
                    !appId ? 'FACEBOOK_APP_ID' : null,
                    !configId ? 'FB_WHATSAPP_CONFIG_ID' : null
                ].filter(Boolean)
            });
        }
        res.json({
            success: true,
            app_id: appId,
            config_id: configId,
            graph_version: 'v22.0'
        });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

// Completes the Embedded Signup flow. Frontend FB.login resolves with:
//   { authResponse: { code }, ...,
//     extras: { fbCallbackData: { phone_number_id, waba_id, business_id } } }
// We POST those server-side here. The code is exchanged for a token via
// Graph; the WABA's webhook subscription is registered against our app.
app.post('/api/whatsapp/embedded-signup/complete', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        const { account_id, code, waba_id, phone_number_id, business_id, display_name } = req.body || {};
        if (!account_id || !code || !waba_id || !phone_number_id) {
            return res.status(400).json({ error: 'account_id, code, waba_id, phone_number_id all required' });
        }
        // Master can onboard any account; non-master can only onboard
        // their own.
        const callerAccountId = user.id || user.accountId;
        if (user.role !== 'master_admin' && parseInt(account_id) !== parseInt(callerAccountId)) {
            return res.status(403).json({ error: 'You can only connect WhatsApp for your own account' });
        }

        const FACEBOOK_APP_ID = process.env.FACEBOOK_APP_ID;
        const FACEBOOK_APP_SECRET = process.env.FACEBOOK_APP_SECRET;
        if (!FACEBOOK_APP_ID || !FACEBOOK_APP_SECRET) {
            return res.status(500).json({ error: 'FACEBOOK_APP_ID / FACEBOOK_APP_SECRET not set' });
        }
        const GRAPH = 'https://graph.facebook.com/v22.0';

        // Step 1: exchange the code for a short-lived business user token.
        // For Embedded Signup the redirect_uri is the magic empty-string
        // value Meta expects — the FB SDK handles the actual redirect.
        const tokenRes = await fetch(`${GRAPH}/oauth/access_token?` +
            `client_id=${FACEBOOK_APP_ID}` +
            `&client_secret=${FACEBOOK_APP_SECRET}` +
            `&code=${encodeURIComponent(code)}`);
        const tokenData = await tokenRes.json();
        if (tokenData.error) {
            console.error('[WA-ESU] token exchange failed:', tokenData.error);
            return res.status(400).json({ error: 'Token exchange failed: ' + tokenData.error.message });
        }
        const accessToken = tokenData.access_token;
        if (!accessToken) return res.status(400).json({ error: 'No access token returned' });

        // Step 2: subscribe our app to this WABA's webhooks. Without this
        // step, the inbound /api/webhooks/whatsapp endpoint will never
        // receive events for this number. The subscribed_apps endpoint
        // uses the access token we just minted.
        const subRes = await fetch(`${GRAPH}/${waba_id}/subscribed_apps`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            }
        });
        const subData = await subRes.json();
        if (subData.error) {
            console.error('[WA-ESU] webhook subscription failed:', subData.error);
            return res.status(400).json({ error: 'Webhook subscription failed: ' + subData.error.message });
        }

        // Step 3: persist to gas_whatsapp_configs. Generate a random
        // webhook verify token per account so the inbound webhook can
        // route to the right config.
        const verifyToken = require('crypto').randomBytes(24).toString('hex');
        const upsert = await pool.query(`
            INSERT INTO gas_whatsapp_configs
                (account_id, waba_id, phone_number_id, display_name,
                 access_token, app_id, app_secret, webhook_verify_token,
                 is_active, notes, created_at, updated_at)
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8, true, 'Connected via Embedded Signup', NOW(), NOW())
            ON CONFLICT (account_id) WHERE account_id IS NOT NULL
            DO UPDATE SET
                waba_id = EXCLUDED.waba_id,
                phone_number_id = EXCLUDED.phone_number_id,
                display_name = COALESCE(EXCLUDED.display_name, gas_whatsapp_configs.display_name),
                access_token = EXCLUDED.access_token,
                app_id = EXCLUDED.app_id,
                app_secret = EXCLUDED.app_secret,
                webhook_verify_token = EXCLUDED.webhook_verify_token,
                is_active = true,
                updated_at = NOW()
            RETURNING id, account_id, waba_id, phone_number_id, display_name
        `, [account_id, waba_id, phone_number_id, display_name || null,
            accessToken, FACEBOOK_APP_ID, FACEBOOK_APP_SECRET, verifyToken]);

        res.json({ success: true, config: upsert.rows[0] });
    } catch (e) {
        console.error('[WA-ESU] complete error:', e);
        res.status(500).json({ error: e.message });
    }
});

// EMERGENCY: clear GAS-side standard rules on a property. Blanks the
// standard_check_in_days / check_out_days / min_stay / max_stay / lead_hours
// so no cron / push has reason to override manual Channex state. Read the
// stamp fields too so we know exactly what got cleared. Master-only.
app.post('/api/admin/properties/:id/clear-standard-rules', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user || user.role !== 'master_admin') return res.status(403).json({ error: 'master only' });
        const propertyId = parseInt(req.params.id, 10);
        const before = await pool.query(`SELECT standard_check_in_days, standard_check_out_days, standard_min_stay, standard_max_stay, standard_lead_hours FROM properties WHERE id = $1`, [propertyId]);
        await pool.query(`
            UPDATE properties
               SET standard_check_in_days = NULL,
                   standard_check_out_days = NULL,
                   standard_min_stay = NULL,
                   standard_max_stay = NULL,
                   standard_lead_hours = NULL,
                   standard_rules_pushed_at = NULL,
                   standard_rules_push_error = NULL,
                   updated_at = NOW()
             WHERE id = $1
        `, [propertyId]);
        res.json({ success: true, property_id: propertyId, cleared: before.rows[0] });
    } catch (e) {
        console.error('[properties/clear-standard-rules]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// EMERGENCY freeze — master-only. Toggles sync_enabled on every Channex
// connection for the given account_id. When frozen, no cron (extender,
// outbox, safety) pushes ARI to Channex — the operator's manual state
// on Channex UI is preserved. Used to stop GAS overwriting a manual
// stop-sell while we reconcile.
app.post('/api/admin/channex/freeze-sync', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user || user.role !== 'master_admin') return res.status(403).json({ error: 'master only' });
        const accountId = parseInt(req.body?.account_id, 10);
        const enabled = req.body?.enabled === true; // false = freeze, true = thaw
        if (!accountId) return res.status(400).json({ error: 'account_id required' });
        const r = await pool.query(`
            UPDATE gas_sync_connections SET sync_enabled = $1, updated_at = NOW()
             WHERE account_id = $2 AND adapter_code = 'channex'
            RETURNING id, sync_enabled
        `, [enabled, accountId]);
        res.json({ success: true, action: enabled ? 'thaw' : 'freeze', connections: r.rows });
    } catch (e) {
        console.error('[channex/freeze-sync]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// EMERGENCY stop-sell — master-only. Sets stop_sell:true on every date
// for the next N days for the given room IDs. Blocks all new OTA bookings
// via Channex. Steve 2026-07-28 — used when the rules push wiped
// availability blocks and BDC is about to accept bookings on dates that
// should be closed. Read from operator's own Channex API key.
app.post('/api/admin/channex/emergency-stop-sell', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user || user.role !== 'master_admin') return res.status(403).json({ error: 'master only' });
        const roomIds = (req.body?.room_ids || []).map(r => parseInt(r, 10)).filter(Boolean);
        const days = Math.min(parseInt(req.body?.days, 10) || 400, 730);
        const undo = req.body?.undo === true; // when true, sets stop_sell:false to unblock
        if (roomIds.length === 0) return res.status(400).json({ error: 'room_ids required' });

        const plansR = await pool.query(`
            SELECT rp.external_id AS rate_plan_id, sp.external_id AS channex_property_id,
                   c.credentials, c.id AS connection_id, rt.gas_room_id,
                   rt.external_id AS channex_room_type_id
              FROM gas_sync_rate_plans rp
              JOIN gas_sync_room_types rt ON rt.id = rp.sync_room_type_id
              JOIN gas_sync_properties sp ON sp.id = rt.sync_property_id
              JOIN gas_sync_connections c ON c.id = sp.connection_id
             WHERE rt.gas_room_id = ANY($1::int[])
               AND c.adapter_code = 'channex'
               AND c.status = 'connected'
               AND rp.external_id IS NOT NULL
        `, [roomIds]);
        if (plansR.rows.length === 0) return res.json({ success: false, error: 'no Channex rate plans mapped' });

        const { ChannexAdapter } = require('./gas-sync/adapters/channex-adapter');
        const byConn = {};
        for (const r of plansR.rows) {
            if (!byConn[r.connection_id]) byConn[r.connection_id] = { creds: r.credentials, plans: [] };
            byConn[r.connection_id].plans.push(r);
        }
        const startDate = new Date();
        startDate.setUTCHours(0, 0, 0, 0);
        const summary = [];
        for (const [connId, group] of Object.entries(byConn)) {
            const creds = typeof group.creds === 'string' ? JSON.parse(group.creds) : (group.creds || {});
            const apiKey = creds.apiKey || creds.v1ApiKey;
            if (!apiKey) { summary.push({ connection_id: connId, error: 'no api key' }); continue; }
            const adapter = new ChannexAdapter({ apiKey });
            const values = [];
            for (let i = 0; i < days; i++) {
                const d = new Date(startDate.getTime() + i * 86400000);
                const dateStr = d.toISOString().slice(0, 10);
                for (const plan of group.plans) {
                    values.push({
                        property_id: plan.channex_property_id,
                        rate_plan_id: plan.rate_plan_id,
                        date: dateStr,
                        stop_sell: !undo,
                    });
                }
            }
            // Chunk to 500 rows per request.
            let pushed = 0, failed = 0, lastError = null;
            for (let i = 0; i < values.length; i += 500) {
                const slice = values.slice(i, i + 500);
                try {
                    const resp = await adapter.request('/restrictions', 'POST', { values: slice });
                    if (resp.success) pushed += slice.length;
                    else { failed += slice.length; lastError = resp.error || 'unknown'; }
                } catch (e) { failed += slice.length; lastError = e.message; }
            }
            // Belt-and-braces — also push availability:0 (or restore) on
            // every date for every room_type. stop_sell prevents new
            // bookings but some OTAs display the availability count
            // separately — Steve 2026-07-28 saw "1" on BDC even after
            // stop_sell. Setting availability to 0 removes any doubt.
            // On stop-sell: also push availability:0 so OTAs that display
            // the count separately (BDC) show closed. On undo: DON'T touch
            // availability — we don't know what the original count was,
            // and pushing 1 might undercount a multi-unit room.
            let availPushed = 0, availFailed = 0;
            const roomTypesInGroup = [...new Set(group.plans.map(p => p.channex_room_type_id).filter(Boolean))];
            if (!undo && roomTypesInGroup.length > 0) {
                const availValues = [];
                for (let i = 0; i < days; i++) {
                    const d = new Date(startDate.getTime() + i * 86400000);
                    const dateStr = d.toISOString().slice(0, 10);
                    for (const rtId of roomTypesInGroup) {
                        availValues.push({
                            property_id: group.plans[0].channex_property_id,
                            room_type_id: rtId,
                            date: dateStr,
                            availability: 0,
                        });
                    }
                }
                for (let i = 0; i < availValues.length; i += 500) {
                    const slice = availValues.slice(i, i + 500);
                    try {
                        const resp = await adapter.request('/availability', 'POST', { values: slice });
                        if (resp.success) availPushed += slice.length;
                        else { availFailed += slice.length; lastError = resp.error || 'unknown'; }
                    } catch (e) { availFailed += slice.length; lastError = e.message; }
                }
            }
            summary.push({ connection_id: connId, restrictions_pushed: pushed, restrictions_failed: failed, availability_pushed: availPushed, availability_failed: availFailed, plans: group.plans.length, room_types: roomTypesInGroup.length, last_error: lastError });
        }
        res.json({ success: true, action: undo ? 'unblock' : 'stop-sell', days, summary });
    } catch (e) {
        console.error('[channex/emergency-stop-sell]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// Channex restrictions inspector — master-only diagnostic. Takes room IDs,
// resolves their Channex rate plans, GETs current restrictions from Channex
// for the next N days, and returns a per-date summary so we can spot when
// GAS says 2-night min-stay but Channex still has 1. Read-only, no writes.
app.get('/api/admin/channex/inspect-restrictions', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user || user.role !== 'master_admin') return res.status(403).json({ error: 'master only' });
        const roomIds = String(req.query.room_ids || '').split(',').map(s => parseInt(s.trim(), 10)).filter(Boolean);
        if (roomIds.length === 0) return res.status(400).json({ error: 'room_ids query param required (comma-separated int list)' });
        const days = Math.min(parseInt(req.query.days, 10) || 14, 60);

        // Resolve every Channex rate plan mapped under any of the given rooms.
        const plansR = await pool.query(`
            SELECT rp.external_id AS rate_plan_id, sp.external_id AS channex_property_id,
                   rt.gas_room_id, bu.name AS room_name, bu.property_id AS gas_property_id,
                   c.credentials, c.id AS connection_id
              FROM gas_sync_rate_plans rp
              JOIN gas_sync_room_types rt ON rt.id = rp.sync_room_type_id
              JOIN gas_sync_properties sp ON sp.id = rt.sync_property_id
              JOIN gas_sync_connections c ON c.id = sp.connection_id
              JOIN bookable_units bu ON bu.id = rt.gas_room_id
             WHERE rt.gas_room_id = ANY($1::int[])
               AND c.adapter_code = 'channex'
               AND c.status = 'connected'
               AND rp.external_id IS NOT NULL
        `, [roomIds]);
        if (plansR.rows.length === 0) return res.json({ success: false, error: 'no Channex rate plans mapped for those rooms' });

        // Grab GAS-side saved rules per distinct property so we can compare.
        const propIds = [...new Set(plansR.rows.map(r => r.gas_property_id))];
        const gasRulesR = await pool.query(`
            SELECT id, name, standard_check_in_days, standard_min_stay, standard_max_stay, standard_lead_hours,
                   standard_rules_pushed_at
              FROM properties WHERE id = ANY($1::int[])
        `, [propIds]);
        const gasRulesByProp = {};
        for (const r of gasRulesR.rows) gasRulesByProp[r.id] = r;

        const startDate = new Date();
        startDate.setUTCHours(0, 0, 0, 0);
        const startStr = startDate.toISOString().slice(0, 10);
        const endStr = new Date(startDate.getTime() + days * 86400000).toISOString().slice(0, 10);

        // Fetch from Channex per-connection so we hit the operator's actual API,
        // not the platform master key. GET /restrictions?filter[rate_plan_id][]=..
        const { ChannexAdapter } = require('./gas-sync/adapters/channex-adapter');
        const byConn = {};
        for (const r of plansR.rows) {
            if (!byConn[r.connection_id]) byConn[r.connection_id] = { creds: r.credentials, plans: [] };
            byConn[r.connection_id].plans.push(r);
        }
        const perPlan = [];
        for (const [connId, group] of Object.entries(byConn)) {
            const creds = typeof group.creds === 'string' ? JSON.parse(group.creds) : (group.creds || {});
            const apiKey = creds.apiKey || creds.v1ApiKey;
            if (!apiKey) { perPlan.push({ connection_id: connId, error: 'no api key' }); continue; }
            const adapter = new ChannexAdapter({ apiKey });
            for (const p of group.plans) {
                try {
                    const path = `/restrictions?filter[rate_plan_id]=${p.rate_plan_id}&filter[date][gte]=${startStr}&filter[date][lt]=${endStr}&limit=200`;
                    const resp = await adapter.request(path, 'GET');
                    const rows = resp?.data?.data || resp?.data || [];
                    perPlan.push({
                        room_id: p.gas_room_id,
                        room_name: p.room_name,
                        gas_property_id: p.gas_property_id,
                        gas_saved_min_stay: gasRulesByProp[p.gas_property_id]?.standard_min_stay || null,
                        gas_rules_pushed_at: gasRulesByProp[p.gas_property_id]?.standard_rules_pushed_at || null,
                        channex_property_id: p.channex_property_id,
                        rate_plan_id: p.rate_plan_id,
                        channex_restrictions: rows.map(x => ({
                            date: x.attributes?.date || x.date,
                            min_stay_arrival: x.attributes?.min_stay_arrival ?? x.min_stay_arrival,
                            min_stay_through: x.attributes?.min_stay_through ?? x.min_stay_through,
                            closed_to_arrival: x.attributes?.closed_to_arrival ?? x.closed_to_arrival,
                            closed_to_departure: x.attributes?.closed_to_departure ?? x.closed_to_departure,
                            stop_sell: x.attributes?.stop_sell ?? x.stop_sell,
                        })),
                    });
                } catch (e) {
                    perPlan.push({ room_id: p.gas_room_id, rate_plan_id: p.rate_plan_id, error: e.message });
                }
            }
        }
        res.json({ success: true, days, results: perPlan });
    } catch (e) {
        console.error('[channex/inspect-restrictions]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// Widget config — CORS-open public endpoint. Returns the WhatsApp number
// + branding for one account so the vanilla-JS widget on client sites
// (or GAS Admin, or gas.travel) can deep-link to wa.me/{number}. Falls
// back to the platform default (account_id=NULL) when the requested
// account has no own WABA connected. Live-fetches display_phone_number
// from Meta the first time we don't have it cached, then persists it
// for future requests. Never exposes the access token or webhook secret.
app.get('/api/public/whatsapp-widget/config', async (req, res) => {
    res.set('Access-Control-Allow-Origin', '*');
    res.set('Cache-Control', 'public, max-age=60');
    try {
        const accountId = parseInt(req.query.account_id, 10);
        // Try the requested account first, fall back to platform default.
        // NULLS LAST orders 'account matches' before 'platform default'.
        const r = await pool.query(`
            SELECT id, account_id, waba_id, phone_number_id, display_name,
                   display_phone_number, access_token
              FROM gas_whatsapp_configs
             WHERE is_active = true
               AND (account_id = $1 OR account_id IS NULL)
             ORDER BY account_id NULLS LAST
             LIMIT 1
        `, [Number.isFinite(accountId) ? accountId : null]);
        const cfg = r.rows[0];
        if (!cfg) return res.json({ success: false, error: 'no WhatsApp configured' });

        let phone = cfg.display_phone_number;
        if (!phone && cfg.phone_number_id && cfg.access_token) {
            // Live-fetch from Meta once, then cache. Failure is silent —
            // widget just doesn't render (safer than a broken deep link).
            try {
                const metaResp = await fetch(
                    `https://graph.facebook.com/v25.0/${cfg.phone_number_id}?fields=display_phone_number`,
                    { headers: { Authorization: `Bearer ${cfg.access_token}` } }
                );
                const metaJson = await metaResp.json();
                if (metaJson.display_phone_number) {
                    phone = metaJson.display_phone_number;
                    await pool.query(
                        `UPDATE gas_whatsapp_configs SET display_phone_number = $1, updated_at = NOW() WHERE id = $2`,
                        [phone, cfg.id]
                    ).catch(() => {});
                }
            } catch (e) {
                console.warn('[whatsapp-widget/config] Meta lookup failed:', e.message);
            }
        }
        if (!phone) return res.json({ success: false, error: 'no phone number available' });

        // Strip everything except digits — wa.me only accepts pure digits.
        const digits = String(phone).replace(/[^0-9]/g, '');
        res.json({
            success: true,
            phone_number: digits,
            display_name: cfg.display_name || 'Chat with us',
            scope: cfg.account_id === accountId ? 'account' : 'platform-default',
        });
    } catch (e) {
        console.error('[whatsapp-widget/config]', e.message);
        res.status(500).json({ success: false, error: e.message });
    }
});

// Platform default WABA — upsert (master-only). This is the row with
// account_id IS NULL that catches inbound messages to GAS's own support
// number (Steve's, in v1). Also used as fallback for lifecycle messages
// when an account hasn't done Embedded Signup yet. Steve pastes his four
// values from the Meta API Setup page + a random verify token he picked.
app.post('/api/admin/whatsapp/platform-default', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user || user.role !== 'master_admin') return res.status(403).json({ error: 'master only' });
        const { waba_id, phone_number_id, access_token, webhook_verify_token, display_name, app_id, app_secret } = req.body || {};
        if (!waba_id || !phone_number_id || !access_token || !webhook_verify_token) {
            return res.status(400).json({ error: 'waba_id, phone_number_id, access_token, webhook_verify_token all required' });
        }
        // account_id IS NULL is the platform default. There should only ever
        // be ONE such row — if it already exists, update; otherwise insert.
        const existing = await pool.query(`SELECT id FROM gas_whatsapp_configs WHERE account_id IS NULL LIMIT 1`);
        let row;
        if (existing.rows[0]) {
            const upd = await pool.query(`
                UPDATE gas_whatsapp_configs
                   SET waba_id = $1, phone_number_id = $2, access_token = $3,
                       webhook_verify_token = $4, display_name = COALESCE($5, display_name),
                       app_id = COALESCE($6, app_id), app_secret = COALESCE($7, app_secret),
                       is_active = true, updated_at = NOW()
                 WHERE id = $8
                RETURNING id, waba_id, phone_number_id, display_name, is_active
            `, [waba_id, phone_number_id, access_token, webhook_verify_token, display_name || null, app_id || null, app_secret || null, existing.rows[0].id]);
            row = upd.rows[0];
        } else {
            const ins = await pool.query(`
                INSERT INTO gas_whatsapp_configs
                    (account_id, waba_id, phone_number_id, access_token,
                     webhook_verify_token, display_name, app_id, app_secret,
                     is_active, notes, created_at, updated_at)
                VALUES (NULL, $1, $2, $3, $4, $5, $6, $7, true, 'Platform default — GAS support number', NOW(), NOW())
                RETURNING id, waba_id, phone_number_id, display_name, is_active
            `, [waba_id, phone_number_id, access_token, webhook_verify_token, display_name || 'GAS Travel', app_id || null, app_secret || null]);
            row = ins.rows[0];
        }
        res.json({ success: true, config: row });
    } catch (e) {
        console.error('[whatsapp platform-default]', e.message);
        res.status(500).json({ error: e.message });
    }
});

// List WhatsApp configs visible to the caller. Master sees all rows;
// account admin sees only their own. Used by the Settings UI to show
// "Connected" state vs. "Connect WhatsApp" CTA.
app.get('/api/whatsapp/configs', async (req, res) => {
    try {
        const user = await authenticateUser(req, res);
        if (!user) return;
        let rows;
        if (user.role === 'master_admin') {
            rows = await pool.query(`
                SELECT c.id, c.account_id, c.waba_id, c.phone_number_id,
                       c.display_name, c.display_phone_number, c.is_active,
                       c.created_at, c.updated_at,
                       a.name as account_name, a.business_name as account_business
                FROM gas_whatsapp_configs c
                LEFT JOIN accounts a ON a.id = c.account_id
                ORDER BY c.account_id NULLS LAST, c.id`);
        } else {
            const callerAccountId = user.id || user.accountId;
            rows = await pool.query(`
                SELECT id, account_id, waba_id, phone_number_id, display_name,
                       display_phone_number, is_active, created_at, updated_at
                FROM gas_whatsapp_configs
                WHERE account_id = $1
                ORDER BY id`, [callerAccountId]);
        }
        res.json({ success: true, configs: rows.rows });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

// Step 1: Redirect user to Facebook OAuth
app.get('/api/oauth/facebook/start', async (req, res) => {
  try {
    const accountId = req.query.account_id;
    if (!accountId) return res.status(400).json({ error: 'account_id required' });

    const FACEBOOK_APP_ID = process.env.FACEBOOK_APP_ID;
    const REDIRECT_URI = 'https://admin.gas.travel/api/oauth/facebook/callback';
    
    // Permissions needed for posting to pages. pages_read_engagement was
    // in the earlier scope list but no code path actually READS engagement
    // (no /insights, /reactions or /comments calls anywhere). Meta rejects
    // any permission the reviewer can't see being used, so we request only
    // what we demonstrably use: list pages + publish posts. Add
    // pages_read_engagement back once the engagement-read feature (cron +
    // UI showing likes/comments per post) is built. Steve 2026-08-18.
    const scopes = 'pages_manage_posts,pages_show_list';
    
    // Store account_id in state parameter so we know who's connecting
    const state = Buffer.from(JSON.stringify({ account_id: accountId })).toString('base64');
    
    const authUrl = `https://www.facebook.com/v22.0/dialog/oauth?` +
      `client_id=${FACEBOOK_APP_ID}` +
      `&redirect_uri=${encodeURIComponent(REDIRECT_URI)}` +
      `&scope=${scopes}` +
      `&state=${state}` +
      `&response_type=code`;
    
    res.redirect(authUrl);
  } catch (error) {
    console.error('Facebook OAuth start error:', error);
    res.status(500).json({ error: 'Failed to start Facebook OAuth' });
  }
});

// Step 2: Facebook redirects back with auth code
app.get('/api/oauth/facebook/callback', async (req, res) => {
  try {
    const { code, state, error: fbError } = req.query;
    
    if (fbError) {
      console.error('Facebook OAuth error:', fbError);
      return res.redirect('/gas-admin.html?fb_error=' + encodeURIComponent(fbError));
    }
    
    if (!code || !state) {
      return res.redirect('/gas-admin.html?fb_error=missing_params');
    }
    
    // Decode state to get account_id
    const stateData = JSON.parse(Buffer.from(state, 'base64').toString());
    const accountId = stateData.account_id;
    
    const FACEBOOK_APP_ID = process.env.FACEBOOK_APP_ID;
    const FACEBOOK_APP_SECRET = process.env.FACEBOOK_APP_SECRET;
    const REDIRECT_URI = 'https://admin.gas.travel/api/oauth/facebook/callback';
    
    // Exchange code for short-lived user access token
    const tokenResponse = await fetch(
      `https://graph.facebook.com/v22.0/oauth/access_token?` +
      `client_id=${FACEBOOK_APP_ID}` +
      `&redirect_uri=${encodeURIComponent(REDIRECT_URI)}` +
      `&client_secret=${FACEBOOK_APP_SECRET}` +
      `&code=${code}`
    );
    const tokenData = await tokenResponse.json();
    
    if (tokenData.error) {
      console.error('Facebook token error:', tokenData.error);
      return res.redirect('/gas-admin.html?fb_error=' + encodeURIComponent(tokenData.error.message));
    }
    
    const shortLivedToken = tokenData.access_token;
    
    // Exchange for long-lived user token (60 days)
    const longLivedResponse = await fetch(
      `https://graph.facebook.com/v22.0/oauth/access_token?` +
      `grant_type=fb_exchange_token` +
      `&client_id=${FACEBOOK_APP_ID}` +
      `&client_secret=${FACEBOOK_APP_SECRET}` +
      `&fb_exchange_token=${shortLivedToken}`
    );
    const longLivedData = await longLivedResponse.json();
    
    if (longLivedData.error) {
      console.error('Facebook long-lived token error:', longLivedData.error);
      return res.redirect('/gas-admin.html?fb_error=token_exchange_failed');
    }
    
    const longLivedUserToken = longLivedData.access_token;
    
    // Get user's pages
    const pagesResponse = await fetch(
      `https://graph.facebook.com/v22.0/me/accounts?access_token=${longLivedUserToken}&fields=id,name,access_token,category,picture`
    );
    const pagesData = await pagesResponse.json();
    
    if (!pagesData.data || pagesData.data.length === 0) {
      return res.redirect('/gas-admin.html?fb_error=no_pages');
    }
    
    // Store all pages as connections (page tokens are long-lived when derived from long-lived user token)
    for (const page of pagesData.data) {
      // Check if connection already exists
      const existing = await pool.query(
        'SELECT id FROM turbine_connections WHERE account_id = $1 AND platform = $2 AND page_id = $3',
        [accountId, 'facebook', page.id]
      );
      
      if (existing.rows.length > 0) {
        // Update existing
        await pool.query(
          `UPDATE turbine_connections SET 
            access_token = $1, page_name = $2, platform_username = $3, 
            status = 'active', updated_at = NOW()
          WHERE id = $4`,
          [page.access_token, page.name, page.name, existing.rows[0].id]
        );
      } else {
        // Insert new
        await pool.query(
          `INSERT INTO turbine_connections (account_id, platform, platform_user_id, platform_username, access_token, page_id, page_name, status)
          VALUES ($1, $2, $3, $4, $5, $6, $7, 'active')`,
          [accountId, 'facebook', page.id, page.name, page.access_token, page.id, page.name]
        );
      }
    }
    
    console.log(`✅ Facebook connected for account ${accountId}: ${pagesData.data.length} page(s)`);
    
    // Redirect back to Turbine Connections with success
    res.redirect('/gas-admin.html?fb_success=true&fb_pages=' + pagesData.data.length);
    
  } catch (error) {
    console.error('Facebook OAuth callback error:', error);
    res.redirect('/gas-admin.html?fb_error=' + encodeURIComponent(error.message));
  }
});

// POST to a Facebook page (standalone - outside campaigns)
app.post('/api/turbines/post/facebook', async (req, res) => {
  try {
    const { connection_id, message, link } = req.body;
    
    const conn = await pool.query(
      'SELECT * FROM turbine_connections WHERE id = $1 AND platform = $2',
      [connection_id, 'facebook']
    );
    
    if (conn.rows.length === 0) return res.status(404).json({ error: 'Connection not found' });
    
    const { page_id, access_token } = conn.rows[0];
    
    // Post to Facebook Page
    const postBody = { access_token };
    if (message) postBody.message = message;
    if (link) postBody.link = link;
    
    const fbResponse = await fetch(`https://graph.facebook.com/v22.0/${page_id}/feed`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(postBody)
    });
    
    const fbData = await fbResponse.json();
    
    if (fbData.error) {
      console.error('Facebook post error:', fbData.error);
      return res.status(400).json({ error: fbData.error.message });
    }
    
    console.log(`✅ Posted to Facebook page ${page_id}: ${fbData.id}`);
    res.json({ success: true, post_id: fbData.id });
    
  } catch (error) {
    console.error('Error posting to Facebook:', error);
    res.status(500).json({ error: 'Failed to post' });
  }
});

// =====================================================
// BOOKING CM FAILURE MANAGEMENT
// =====================================================

// Get all unresolved CM failures
app.get('/api/admin/cm-failures', async (req, res) => {
  try {
    const result = await pool.query(`
      SELECT f.*, b.guest_first_name, b.guest_last_name, b.guest_email, b.check_in, b.check_out, 
             b.total_price, b.property_id, b.room_id, a.name as account_name
      FROM booking_cm_failures f
      LEFT JOIN bookings b ON f.booking_id = b.id
      LEFT JOIN accounts a ON f.account_id = a.id
      WHERE f.resolved = false
      ORDER BY f.created_at DESC
    `);
    res.json({ success: true, failures: result.rows });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Get failure count (for notification badge)
app.get('/api/admin/cm-failures/count', async (req, res) => {
  try {
    const result = await pool.query(`SELECT COUNT(*) as count FROM booking_cm_failures WHERE resolved = false`);
    res.json({ success: true, count: parseInt(result.rows[0].count) });
  } catch (error) {
    res.json({ success: false, count: 0 });
  }
});

// Mark failure as resolved
app.put('/api/admin/cm-failures/:id/resolve', async (req, res) => {
  try {
    await pool.query(`
      UPDATE booking_cm_failures SET resolved = true, resolved_at = NOW(), resolved_by = $1 WHERE id = $2
    `, [req.body.resolved_by || 'admin', req.params.id]);
    res.json({ success: true });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// Retry CM push for a failed booking
app.post('/api/admin/cm-failures/:id/retry', async (req, res) => {
  try {
    const failure = await pool.query(`SELECT * FROM booking_cm_failures WHERE id = $1`, [req.params.id]);
    if (!failure.rows.length) return res.json({ success: false, error: 'Failure not found' });
    
    const f = failure.rows[0];
    const booking = await pool.query(`SELECT * FROM bookings WHERE id = $1`, [f.booking_id]);
    if (!booking.rows.length) return res.json({ success: false, error: 'Booking not found' });
    
    // TODO: Implement retry logic per adapter (hostaway, beds24, etc)
    res.json({ success: false, error: 'Retry not yet implemented - please push manually via CM' });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// =====================================================
// WEEKLY REVIEW AUTO-SYNC
// Syncs reviews from all connected Hostaway & Beds24 accounts once per week
// =====================================================

async function syncAllReviews() {
  console.log('📝 [Review Sync] Starting weekly review sync for all accounts...');
  try {
    // Get all active Hostaway connections
    const hostawayConns = await pool.query(
      `SELECT * FROM gas_sync_connections WHERE adapter_code = 'hostaway' AND status = 'active'`
    );
    
    for (const conn of hostawayConns.rows) {
      try {
        console.log(`📝 [Review Sync] Syncing Hostaway reviews for account ${conn.account_id}...`);
        // Call the existing sync function internally
        const axios = require('axios');
        await axios.post(`http://localhost:${PORT}/api/hostaway/sync-reviews`, {
          connectionId: conn.id,
          accountId: conn.account_id
        });
        console.log(`✅ [Review Sync] Hostaway reviews synced for account ${conn.account_id}`);
      } catch (e) {
        console.log(`⚠️ [Review Sync] Failed for Hostaway account ${conn.account_id}: ${e.message}`);
      }
    }
    
    // Get all active Beds24 connections
    const beds24Conns = await pool.query(
      `SELECT * FROM gas_sync_connections WHERE adapter_code = 'beds24' AND status = 'active'`
    );
    
    for (const conn of beds24Conns.rows) {
      try {
        console.log(`📝 [Review Sync] Syncing Beds24 reviews for account ${conn.account_id}...`);
        const axios = require('axios');
        await axios.post(`http://localhost:${PORT}/api/beds24/sync-reviews`, {
          connectionId: conn.id,
          accountId: conn.account_id
        });
        console.log(`✅ [Review Sync] Beds24 reviews synced for account ${conn.account_id}`);
      } catch (e) {
        console.log(`⚠️ [Review Sync] Failed for Beds24 account ${conn.account_id}: ${e.message}`);
      }
    }
    
    console.log(`📝 [Review Sync] Complete. Processed ${hostawayConns.rows.length} Hostaway + ${beds24Conns.rows.length} Beds24 connections.`);
  } catch (error) {
    console.error('❌ [Review Sync] Error:', error.message);
  }
}

function startReviewSyncScheduler() {
  // Run weekly - every 7 days (604800000ms)
  const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
  
  // Run first sync 5 minutes after startup, then weekly
  setTimeout(() => {
    syncAllReviews();
    setInterval(syncAllReviews, WEEK_MS);
  }, 5 * 60 * 1000);
  
  console.log('📝 Review auto-sync scheduled: weekly for all connected accounts');
}

// Daily Hostaway availability sync - pulls full 365 days for all connected accounts
async function syncAllHostawayAvailability() {
  console.log('📅 Starting daily Hostaway availability sync for all accounts...');
  
  try {
    // Get all active Hostaway connections via GasSync
    const connections = await pool.query(`
      SELECT gc.id, gc.account_id, gc.external_account_id, gc.credentials, gc.access_token
      FROM gas_sync_connections gc
      WHERE gc.adapter_code = 'hostaway' AND gc.sync_enabled = true AND gc.status = 'connected'
    `);
    
    if (connections.rows.length === 0) {
      console.log('📅 No active Hostaway connections found');
      return;
    }
    
    console.log(`📅 Found ${connections.rows.length} Hostaway connections to sync`);
    
    for (const conn of connections.rows) {
      try {
        // Get fresh Hostaway token from GasSync connection credentials
        const credentials = typeof conn.credentials === 'string' 
          ? JSON.parse(conn.credentials) 
          : conn.credentials || {};
        
        let token = conn.access_token;
        if (!token && credentials.accountId && credentials.apiKey) {
          const tokenResponse = await axios.post(
            'https://api.hostaway.com/v1/accessTokens',
            `grant_type=client_credentials&client_id=${credentials.accountId}&client_secret=${credentials.apiKey}`,
            { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
          );
          token = tokenResponse.data?.access_token;
          if (token) {
            await pool.query('UPDATE gas_sync_connections SET access_token = $1 WHERE id = $2', [token, conn.id]);
          }
        }
        
        if (!token) {
          console.log(`  ❌ Could not get Hostaway token for account ${conn.account_id}`);
          continue;
        }
        
        // Get rooms for this account
        const roomsResult = await pool.query(`
          SELECT bu.id as room_id, bu.hostaway_listing_id, bu.name
          FROM bookable_units bu
          JOIN properties p ON bu.property_id = p.id
          WHERE p.account_id = $1 AND bu.hostaway_listing_id IS NOT NULL
        `, [conn.account_id]);
        
        if (roomsResult.rows.length === 0) {
          console.log(`  ⚠️ No Hostaway rooms for account ${conn.account_id}`);
          continue;
        }
        
        const today = new Date().toISOString().split('T')[0];
        const endDate = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        let totalDays = 0;
        
        for (const room of roomsResult.rows) {
          try {
            await new Promise(resolve => setTimeout(resolve, 700)); // Rate limit
            
            const response = await axios.get(`https://api.hostaway.com/v1/listings/${room.hostaway_listing_id}/calendar`, {
              headers: { 'Authorization': `Bearer ${token}`, 'Cache-control': 'no-cache' },
              params: { startDate: today, endDate: endDate }
            });
            
            if (response.data.status === 'success' && response.data.result) {
              for (const day of response.data.result) {
                const isAvailable = day.isAvailable === 1 || day.isAvailable === true;
                const isBlocked = day.status === 'blocked' || day.isBlocked === 1;
                const minStay = day.minimumStay || 1;
                const price = day.price || null;
                
                await pool.query(`
                  INSERT INTO room_availability (room_id, date, price, cm_price, direct_price, is_available, is_blocked, min_stay, source, updated_at)
                  VALUES ($1, $2, $3, $3, $3, $4, $5, $6, 'hostaway_daily_sync', NOW())
                  ON CONFLICT (room_id, date)
                  DO UPDATE SET
                    price = CASE WHEN $3 IS NOT NULL THEN $3 ELSE room_availability.price END,
                    cm_price = $3,
                    direct_price = COALESCE(room_availability.direct_price, $3),
                    is_available = $4,
                    is_blocked = $5,
                    min_stay = $6,
                    source = 'hostaway_daily_sync',
                    updated_at = NOW()
                `, [room.room_id, day.date, price, isAvailable, isBlocked, minStay]);
                
                totalDays++;
              }
              console.log(`  ✓ ${room.name}: ${response.data.result.length} days synced`);
            }
          } catch (roomError) {
            console.error(`  ✗ Error syncing ${room.name}:`, roomError.response?.data || roomError.message);
            if (roomError.response?.status === 429) {
              await new Promise(resolve => setTimeout(resolve, 10000));
            }
          }
        }
        
        console.log(`📅 Account ${conn.account_id}: ${totalDays} availability records updated`);
      } catch (connError) {
        console.error(`📅 Error syncing account ${conn.account_id}:`, connError.message);
      }
    }
    
    console.log('📅 Daily Hostaway availability sync complete');
  } catch (error) {
    console.error('📅 Hostaway availability sync error:', error.message);
  }
}

function startHostawayAvailabilitySyncScheduler() {
  const DAY_MS = 24 * 60 * 60 * 1000;

  // Run first sync 10 minutes after startup, then daily
  setTimeout(() => {
    syncAllHostawayAvailability();
    setInterval(syncAllHostawayAvailability, DAY_MS);
  }, 10 * 60 * 1000);

  console.log('📅 Hostaway availability sync scheduled: daily for all connected accounts');
}

// Daily Hostfully availability sync - pulls full 365 days for all connected accounts
async function syncAllHostfullyAvailability() {
  console.log('📅 Starting daily Hostfully availability sync for all accounts...');

  try {
    const connections = await pool.query(`
      SELECT gc.id, gc.account_id, gc.credentials
      FROM gas_sync_connections gc
      WHERE gc.adapter_code = 'hostfully' AND gc.sync_enabled = true AND gc.status = 'connected'
    `);

    if (connections.rows.length === 0) {
      console.log('📅 No active Hostfully connections found');
      return;
    }

    console.log(`📅 Found ${connections.rows.length} Hostfully connections to sync`);

    for (const conn of connections.rows) {
      try {
        const credentials = typeof conn.credentials === 'string'
          ? JSON.parse(conn.credentials || '{}')
          : (conn.credentials || {});

        const apiKey = credentials.apiKey;
        const agencyUid = credentials.agencyUid;

        if (!apiKey) {
          console.log(`  ❌ No Hostfully API key for connection ${conn.id}`);
          continue;
        }

        const { HostfullyAdapter } = require('./gas-sync/adapters/hostfully-adapter');
        const adapter = new HostfullyAdapter({ apiKey, agencyUid });

        // Get all linked room types for this connection
        const roomTypes = await pool.query(`
          SELECT rt.id, rt.external_id, rt.gas_room_id, rt.name
          FROM gas_sync_room_types rt
          JOIN gas_sync_properties sp ON rt.sync_property_id = sp.id
          WHERE sp.connection_id = $1 AND rt.gas_room_id IS NOT NULL
        `, [conn.id]);

        if (roomTypes.rows.length === 0) {
          console.log(`  ⚠️ No linked Hostfully rooms for connection ${conn.id}`);
          continue;
        }

        const today = new Date().toISOString().split('T')[0];
        const endDate = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
        let totalDays = 0;

        for (const room of roomTypes.rows) {
          try {
            await new Promise(resolve => setTimeout(resolve, 500)); // Rate limit

            const calendarResult = await adapter.getPropertyCalendar(room.external_id, today, endDate);

            if (!calendarResult.success || !Array.isArray(calendarResult.data)) {
              console.error(`  ✗ ${room.name}: ${calendarResult.error || 'No calendar data'}`);
              continue;
            }

            for (const day of calendarResult.data) {
              if (!day.date) continue;

              const price = day.price || null;
              const isAvailable = day.isAvailable === true && !['BLOCKED', 'BOOKED', 'BOOKING', 'BLOCK'].includes(day.status);
              const minStay = day.minStay || 1;
              const maxStay = day.maxStay || null;

              await pool.query(`
                INSERT INTO room_availability (room_id, date, price, cm_price, direct_price, is_available, is_blocked, min_stay, cm_min_stay, max_stay, source, updated_at)
                VALUES ($1, $2, $3, $3, $3, $4, $5, $6, $6, $7, 'hostfully_daily_sync', NOW())
                ON CONFLICT (room_id, date)
                DO UPDATE SET
                  price = CASE WHEN $3 IS NOT NULL THEN $3 ELSE room_availability.price END,
                  cm_price = CASE WHEN $3 IS NOT NULL THEN $3 ELSE room_availability.cm_price END,
                  direct_price = COALESCE($3, room_availability.direct_price),
                  is_available = $4,
                  is_blocked = $5,
                  min_stay = $6,
                  cm_min_stay = $6,
                  max_stay = $7,
                  source = 'hostfully_daily_sync',
                  updated_at = NOW()
              `, [room.gas_room_id, day.date, price, isAvailable, !isAvailable, minStay, maxStay]);

              totalDays++;
            }
            console.log(`  ✓ ${room.name}: ${calendarResult.data.length} days synced`);
          } catch (roomError) {
            console.error(`  ✗ Error syncing ${room.name}:`, roomError.message);
          }
        }

        await pool.query('UPDATE gas_sync_connections SET last_sync_at = NOW() WHERE id = $1', [conn.id]);
        console.log(`📅 Hostfully connection ${conn.id}: ${totalDays} availability records updated`);
      } catch (connError) {
        console.error(`📅 Error syncing Hostfully connection ${conn.id}:`, connError.message);
      }
    }

    console.log('📅 Daily Hostfully availability sync complete');
  } catch (error) {
    console.error('📅 Hostfully availability sync error:', error.message);
  }
}

function startHostfullyAvailabilitySyncScheduler() {
  const DAY_MS = 24 * 60 * 60 * 1000;

  // Run first sync 15 minutes after startup, then daily
  setTimeout(() => {
    syncAllHostfullyAvailability();
    setInterval(syncAllHostfullyAvailability, DAY_MS);
  }, 15 * 60 * 1000);

  console.log('📅 Hostfully availability sync scheduled: daily for all connected accounts');
}

