// GET /api/partner/websites/:websiteId/pages — list all pages for a website
app.get('/api/partner/websites/:websiteId/pages', async (req, res) => {
  try {
    const auth = await validatePartnerApiKey(req);
    if (!auth.valid) {
      return res.status(401).json({ success: false, error: auth.error });
    }

    const { websiteId } = req.params;

    // Verify website belongs to this partner's account
    const ws = await pool.query(
      'SELECT id FROM deployed_sites WHERE id = $1 AND account_id = $2',
      [websiteId, auth.partnerId]
    );
    if (ws.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'Website not found' });
    }

    const result = await pool.query(
      `SELECT ps.id, ps.page_slug, ps.parent_slug, ps.page_title, ps.menu_visible, ps.menu_order, ps.enabled,
              COALESCE(wp.is_published, false) as is_published,
              ps.created_at, ps.updated_at
       FROM page_sections ps
       LEFT JOIN website_pages wp ON wp.website_id = ps.website_id AND wp.slug = ps.page_slug
       WHERE ps.website_id = $1 AND ps.account_id = $2
       ORDER BY ps.menu_order, ps.page_title`,
      [websiteId, auth.partnerId]
    );

    res.json({ success: true, pages: result.rows });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

// Ensure a custom page slug is registered in website_settings.custom-pages.pages[]
// so the WordPress sync plugin (gas-booking) creates the matching WP page.
//
// The page-create / Section Builder flow only writes to page_sections; the WP
// sync iterates custom-pages.pages[]. Pages created via the Section Builder
// were invisible to WordPress until this helper was added — Walnut Canyon
// "free-guide-landing-page" 2026-05-22 trap.
//
// Idempotent: re-runs do nothing if the slug is already registered.
// Slugs handled by the WP plugin's built-in pages_config map — these have
// dedicated templates (template-about.php etc.) and must NEVER appear in
// custom-pages.pages[] or the WP sync will create duplicate pages.
const STANDARD_PAGE_SLUGS = new Set([
  'about','rooms','book-now','gallery','dining','properties','offers',
  'special-offers','blog','attractions','contact','terms','privacy',
  'reviews','home','checkout','room'
]);

async function ensureCustomPageRegistered({ deployedSiteId, accountId, slug, title, visibility = 'menu', parent = '', externalUrl = null }) {
  if (!deployedSiteId || !slug || !title) return;
  if (STANDARD_PAGE_SLUGS.has(slug)) return; // built-in slug — managed by pages_config map
  // Load current custom-pages row (if any)
  const existing = await pool.query(
    `SELECT settings FROM website_settings WHERE deployed_site_id = $1 AND section = 'custom-pages'`,
    [deployedSiteId]
  );
  let settings = { pages: [] };
  if (existing.rows.length > 0 && existing.rows[0].settings) {
    settings = existing.rows[0].settings;
    if (typeof settings.pages === 'string') {
      try { settings.pages = JSON.parse(settings.pages); } catch (_) { settings.pages = []; }
    }
    if (!Array.isArray(settings.pages)) settings.pages = [];
  }
  if (settings.pages.find(p => p && p.slug === slug)) return; // already registered
  settings.pages.push({ slug, title, parent: parent || '', visibility: visibility || 'menu', external_url: externalUrl || null });
  if (existing.rows.length > 0) {
    await pool.query(
      `UPDATE website_settings SET settings = $1, updated_at = NOW() WHERE deployed_site_id = $2 AND section = 'custom-pages'`,
      [JSON.stringify(settings), deployedSiteId]
    );
  } else {
    await pool.query(
      `INSERT INTO website_settings (deployed_site_id, account_id, section, settings, sync_source, updated_at)
       VALUES ($1, $2, 'custom-pages', $3, 'gas', NOW())`,
      [deployedSiteId, accountId || null, JSON.stringify(settings)]
    );
  }
}

// Admin — fully delete a custom page everywhere it lives:
//   - website_settings.custom-pages.pages[] (the registry)
//   - website_settings.page-custom-{slug} (per-page settings)
//   - page_sections (the section content)
//   - WordPress page + menu item (via plugin REST call)
//
// Previously deleteCustomPage() in admin only removed from the registry,
// leaving orphan rows + an orphaned WP page that the next sync would re-create.
// This endpoint runs the four cleanups atomically.
app.delete('/api/deployed-sites/:id/custom-pages/:slug', async (req, res) => {
  try {
    const deployedSiteId = parseInt(req.params.id);
    const slug = String(req.params.slug || '').toLowerCase().replace(/[^a-z0-9-]/g, '');
    if (!deployedSiteId || !slug) return res.status(400).json({ success: false, error: 'site_id + slug required' });

    const siteResult = await pool.query(
      'SELECT id, account_id, site_url FROM deployed_sites WHERE id = $1',
      [deployedSiteId]
    );
    if (siteResult.rows.length === 0) return res.status(404).json({ success: false, error: 'Site not found' });
    const site = siteResult.rows[0];

    // 1. Remove from custom-pages registry
    const cp = await pool.query(
      `SELECT settings FROM website_settings WHERE deployed_site_id = $1 AND section = 'custom-pages'`,
      [deployedSiteId]
    );
    if (cp.rows[0]?.settings) {
      const s = cp.rows[0].settings;
      let pages = typeof s.pages === 'string' ? JSON.parse(s.pages) : (s.pages || []);
      pages = pages.filter(p => p && p.slug !== slug);
      s.pages = pages;
      await pool.query(
        `UPDATE website_settings SET settings = $1, updated_at = NOW() WHERE deployed_site_id = $2 AND section = 'custom-pages'`,
        [JSON.stringify(s), deployedSiteId]
      );
    }

    // 2. Delete per-page settings row
    await pool.query(
      `DELETE FROM website_settings WHERE deployed_site_id = $1 AND section = $2`,
      [deployedSiteId, 'page-custom-' + slug]
    );

    // 3. Delete page_sections row
    await pool.query(
      `DELETE FROM page_sections WHERE website_id = $1 AND page_slug = $2`,
      [deployedSiteId, slug]
    );

    // 4. Tell WordPress to delete the page + menu item. Best-effort — if the
    // WP call fails, the GAS-side delete still went through and the WP sync
    // (which now reads the registry) won't re-create the page.
    let wpResult = { success: false };
    if (site.site_url) {
      try {
        const siteHost = new URL(site.site_url).origin;
        const resp = await fetch(`${siteHost}/wp-json/gas-booking/v1/delete-page`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ slug })
        });
        wpResult = await resp.json().catch(() => ({ success: false }));
      } catch (e) {
        console.warn('[delete custom-page] WP delete call failed:', e.message);
      }
    }

    res.json({ success: true, slug, wp: wpResult });
  } catch (e) {
    console.error('[delete custom-page]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /api/partner/websites/:websiteId/pages — create a new page
app.post('/api/partner/websites/:websiteId/pages', async (req, res) => {
  try {
    const auth = await validatePartnerApiKey(req);
    if (!auth.valid) {
      return res.status(401).json({ success: false, error: auth.error });
    }

    const { websiteId } = req.params;
    const { page_slug, parent_slug, page_title, menu_visible, menu_order, sections, enabled } = req.body;

    if (!page_slug || !page_title) {
      return res.status(400).json({ success: false, error: 'page_slug and page_title are required' });
    }

    // Verify website belongs to this partner's account
    const ws = await pool.query(
      'SELECT id FROM deployed_sites WHERE id = $1 AND account_id = $2',
      [websiteId, auth.partnerId]
    );
    if (ws.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'Website not found' });
    }

    const result = await pool.query(
      `INSERT INTO page_sections (account_id, website_id, page_slug, parent_slug, page_title, menu_visible, menu_order, sections, enabled)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       RETURNING *`,
      [
        auth.partnerId,
        websiteId,
        page_slug,
        parent_slug || null,
        page_title,
        menu_visible || 'main_menu',
        menu_order != null ? menu_order : 50,
        JSON.stringify(sections || []),
        enabled != null ? enabled : true
      ]
    );

    // Atomically register the slug in website_settings.custom-pages so the WP
    // sync plugin picks it up. Without this, sections-only pages are orphaned
    // (saved in GAS but never created on the WordPress side).
    await ensureCustomPageRegistered({
      deployedSiteId: parseInt(websiteId),
      accountId: auth.partnerId,
      slug: page_slug,
      title: page_title,
      visibility: 'menu',
      parent: parent_slug || ''
    }).catch(e => console.warn('[pages POST] custom-pages register skipped:', e.message));

    res.json({ success: true, page: result.rows[0] });
  } catch (error) {
    if (error.code === '23505') {
      return res.status(409).json({ success: false, error: 'A page with this slug already exists for this website' });
    }
    res.status(500).json({ success: false, error: error.message });
  }
});

