// GET /api/public/website/:blogId/page-sections/:slug — public, no auth
app.get('/api/public/website/:blogId/page-sections/:slug', async (req, res) => {
  try {
    const { blogId, slug } = req.params;

    // Look up deployed_sites by WordPress blog_id to get the website_id
    const ds = await pool.query(
      'SELECT id FROM deployed_sites WHERE blog_id = $1 LIMIT 1',
      [blogId]
    );
    if (ds.rows.length === 0) {
      return res.json({ success: false, sections: null });
    }

    const websiteId = ds.rows[0].id;

    let result = await pool.query(
      `SELECT page_title, sections, enabled FROM page_sections
       WHERE website_id = $1 AND page_slug = $2 AND enabled = true`,
      [websiteId, slug]
    );

    // Slug-normalisation fallback. WP collapses repeated dashes in post_name
    // (so "Foo  Bar" → "foo-bar"), but page_slug in our DB can carry the raw
    // double-dash variant ("foo--bar") when the operator typed "Foo - Bar".
    // Try a regex match that collapses dash-runs on both sides.
    if (result.rows.length === 0) {
      result = await pool.query(
        `SELECT page_title, sections, enabled FROM page_sections
         WHERE website_id = $1 AND regexp_replace(page_slug, '-+', '-', 'g') = regexp_replace($2, '-+', '-', 'g') AND enabled = true
         LIMIT 1`,
        [websiteId, slug]
      );
    }

    if (result.rows.length === 0) {
      // Fallback: check website_settings for sb-sections (pages not yet migrated to page_sections)
      const sectionKeys = ['page-' + slug, 'page-custom-' + slug];
      for (const sectionKey of sectionKeys) {
        const wsResult = await pool.query(
          `SELECT settings FROM website_settings WHERE deployed_site_id = $1 AND section = $2`,
          [websiteId, sectionKey]
        );
        if (wsResult.rows.length > 0) {
          const ws = wsResult.rows[0].settings || {};
          if (ws['sb-sections'] && ws['sb-mode'] === 'sections') {
            let sections = ws['sb-sections'];
            if (typeof sections === 'string') {
              try { sections = JSON.parse(sections); } catch(e) { sections = []; }
            }
            if (Array.isArray(sections) && sections.length > 0) {
              return res.json({ success: true, page_title: ws['title-en'] || '', sections: sections });
            }
          }
        }
      }
      // Final fallback (Steve 2026-07-10) — Sparks now save their sections
      // in the same shape as page_sections via the Section Builder. If the
      // slug matches a published Spark on this site's account, serve its
      // blocks under this endpoint so the theme's gas_render_page_sections
      // helper renders them exactly like a page_sections row. Zero theme
      // changes required.
      const accountRow = await pool.query(
        `SELECT account_id FROM deployed_sites WHERE id = $1`, [websiteId]
      );
      const accountId = accountRow.rows[0]?.account_id;
      if (accountId) {
        const sparkR = await pool.query(
          `SELECT title, blocks FROM sparks
            WHERE account_id = $1 AND slug = $2 AND is_published = true
            LIMIT 1`, [accountId, slug]);
        const sp = sparkR.rows[0];
        if (sp && Array.isArray(sp.blocks) && sp.blocks.length > 0) {
          return res.json({ success: true, page_title: sp.title || '', sections: sp.blocks });
        }
      }
      return res.json({ success: false, sections: null });
    }

    const page = result.rows[0];
    res.json({
      success: true,
      page_title: page.page_title,
      sections: page.sections || []
    });
  } catch (error) {
    res.json({ success: false, sections: null });
  }
});

// ─── GAS Pro Site Builder ────────────────────────────────────────────

// GET /api/pro-builder/sites/:blog_id/pages — fetch WordPress pages for a site
app.get('/api/pro-builder/sites/:blog_id/pages', async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.json({ success: false, error: 'Authentication required' });
    }
    const token = authHeader.split(' ')[1];
    const session = await pool.query(`
      SELECT s.account_id, a.role FROM account_sessions s
      JOIN accounts a ON s.account_id = a.id
      WHERE s.token = $1 AND s.expires_at > NOW()
    `, [token]);
    if (session.rows.length === 0) {
      return res.json({ success: false, error: 'Authentication required' });
    }

    const blogId = parseInt(req.params.blog_id);
    const userAccountId = session.rows[0].account_id;
    const userRole = session.rows[0].role;

    // Look up site from deployed_sites
    const site = await pool.query(
      'SELECT ds.*, a.subscription_tier FROM deployed_sites ds JOIN accounts a ON ds.account_id = a.id WHERE ds.blog_id = $1',
      [blogId]
    );
    if (site.rows.length === 0) {
      return res.json({ success: false, error: 'Site not found' });
    }

    const siteRow = site.rows[0];

    // Non-master users can only access their own account's sites
    if (userRole !== 'master_admin' && siteRow.account_id !== userAccountId) {
      return res.json({ success: false, error: 'Access denied — this site belongs to a different account' });
    }

    if (!['pro', 'bespoke'].includes(siteRow.subscription_tier)) {
      return res.json({ success: false, error: 'Pro or Bespoke subscription required' });
    }

    // Get license key for this account
    const license = await pool.query(
      "SELECT license_key FROM plugin_licenses WHERE account_id = $1 AND status = 'active' LIMIT 1",
      [siteRow.account_id]
    );
    const licenseKey = license.rows.length > 0 ? license.rows[0].license_key : '';

    // Build site URL — prefer custom_domain over site_url so live custom-domain
    // multisites (e.g. www.hebdenbridgehostel.org) don't 301-downgrade the
    // downstream proBuilderManagePage POST for menu-state enrichment.
    const siteUrl = _proBuilderCanonicalSiteUrl(siteRow);
    if (!siteUrl) return res.json({ success: false, error: 'Site has no URL configured' });

    // Fetch pages from WordPress REST API
    const wpRes = await fetch(`${siteUrl}/wp-json/wp/v2/pages?per_page=50&orderby=menu_order&order=asc`, {
      headers: licenseKey ? { 'X-GAS-License': licenseKey } : {}
    });

    if (!wpRes.ok) {
      return res.json({ success: false, error: `WordPress API returned ${wpRes.status}` });
    }

    const pages = await wpRes.json();
    const pageList = pages.map(p => ({
      id: p.id,
      title: p.title?.rendered || 'Untitled',
      slug: p.slug,
      status: p.status,
      link: p.link,
      menu_order: p.menu_order,
      template: p.template || '',
      in_menu: false,
      menu_parent_page_id: 0
    }));

    // Fetch menu state and merge into pages
    try {
      const menuData = await proBuilderManagePage(siteUrl, licenseKey, { action: 'get_menu' });
      if (menuData.success && menuData.items) {
        // Build menu_item_id → object_id map for resolving parent
        const menuItemToPageId = {};
        menuData.items.forEach(mi => { menuItemToPageId[mi.menu_item_id] = mi.object_id; });

        menuData.items.forEach(mi => {
          const page = pageList.find(p => p.id === mi.object_id);
          if (page) {
            page.in_menu = true;
            page.menu_parent_page_id = mi.parent ? (menuItemToPageId[mi.parent] || 0) : 0;
          }
        });
      }
    } catch (menuErr) {
      // Menu fetch failed — pages still return without menu data
    }

    res.json({ success: true, blog_id: blogId, site_url: siteUrl, pages: pageList });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// ─── Pro Builder: Section Parser Helper ───────────────────────────────
const containerBlocks = ['cover', 'columns', 'column', 'group', 'buttons', 'query', 'post-template'];
const topLevelBlocks = ['cover', 'columns', 'group', 'shortcode', 'heading', 'paragraph', 'image', 'buttons', 'spacer', 'html', 'query', 'latest-posts', 'search', 'post-template', 'separator', 'list', 'quote', 'table', 'video', 'embed', 'gallery'];

function parseSections(rawContent) {
  const sections = [];
  const blockRegex = /<!-- (\/?)wp:(\S+?)(?:\s+(\{.*?\}))? (?:\/)?-->/g;
  let match;
  let idx = 0;
  let depth = 0;
  let currentSection = null; // tracks container block we're inside at depth 0

  while ((match = blockRegex.exec(rawContent)) !== null) {
    const isClosing = match[1] === '/';
    const blockType = match[2];

    if (isClosing) {
      if (containerBlocks.includes(blockType)) {
        depth--;
        // If we just closed the top-level container, record its end boundary
        if (depth === 0 && currentSection) {
          currentSection.end = match.index + match[0].length;
          currentSection.raw_markup = rawContent.substring(currentSection.start, currentSection.end);
          sections.push(currentSection);
          currentSection = null;
        }
      } else if (depth === 0 && currentSection && currentSection.type === blockType) {
        // Closing a non-container top-level block (heading, paragraph, shortcode, image, spacer)
        currentSection.end = match.index + match[0].length;
        currentSection.raw_markup = rawContent.substring(currentSection.start, currentSection.end);
        sections.push(currentSection);
        currentSection = null;
      }
      continue;
    }

    // Opening tag
    if (depth === 0 && topLevelBlocks.includes(blockType)) {
      let attrs = {};
      try { if (match[3]) attrs = JSON.parse(match[3]); } catch (e) {}
      currentSection = {
        index: idx++,
        type: blockType,
        label: blockType.charAt(0).toUpperCase() + blockType.slice(1),
        attrs: attrs,
        start: match.index,
        end: 0,
        raw_markup: ''
      };

      // Self-closing blocks (<!-- wp:spacer {...} /-->) have no closing tag
      if (match[0].includes('/-->')) {
        currentSection.end = match.index + match[0].length;
        currentSection.raw_markup = rawContent.substring(currentSection.start, currentSection.end);
        sections.push(currentSection);
        currentSection = null;
        continue;
      }

      // Non-container blocks: find their closing tag immediately
      if (!containerBlocks.includes(blockType)) {
        // Keep currentSection open, the closing tag loop above will close it
      }
    }

    if (containerBlocks.includes(blockType)) {
      depth++;
    }
  }

  return sections;
}

// Shared auth + site lookup for pro-builder endpoints
async function proBuilderAuth(req) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return { error: 'Authentication required' };
  }
  const token = authHeader.split(' ')[1];
  const session = await pool.query(`
    SELECT s.account_id, a.role FROM account_sessions s
    JOIN accounts a ON s.account_id = a.id
    WHERE s.token = $1 AND s.expires_at > NOW()
  `, [token]);
  if (session.rows.length === 0) {
    return { error: 'Authentication required' };
  }
  return { accountId: session.rows[0].account_id, role: session.rows[0].role };
}

// 2026-08-13 — HTTP URL construction for pro-builder plugin calls.
// Prefers custom_domain when set (Hebden: www.hebdenbridgehostel.org)
// because nginx has a canonical-domain 301 redirect from site_url →
// custom_domain, and Node's fetch downgrades POST→GET on redirects
// so push-template + manage-page + push-css all returned 404 rest_no_route
// (WP routes only accept POST). Falls back to site_url when no custom
// domain is configured. Do NOT use this for DB lookups (WHERE site_url = $1)
// per feedback_custom_domain_vs_site_url_lookup_key.md.
function _proBuilderCanonicalSiteUrl(siteRow) {
  const raw = (siteRow.custom_domain || siteRow.site_url || siteRow.domain || '').trim();
  if (!raw) return '';
  const host = raw.replace(/^https?:\/\//i, '').replace(/\/+$/, '');
  return 'https://' + host;
}

async function proBuilderFetchContent(blogId, pageId) {
  const site = await pool.query(
    'SELECT ds.*, a.subscription_tier FROM deployed_sites ds JOIN accounts a ON ds.account_id = a.id WHERE ds.blog_id = $1',
    [blogId]
  );
  if (site.rows.length === 0) return { error: 'Site not found' };

  const siteRow = site.rows[0];
  const siteUrl = _proBuilderCanonicalSiteUrl(siteRow);
  if (!siteUrl) return { error: 'Site has no URL configured' };

  const license = await pool.query(
    "SELECT license_key FROM plugin_licenses WHERE account_id = $1 AND status = 'active' LIMIT 1",
    [siteRow.account_id]
  );
  const licenseKey = license.rows.length > 0 ? license.rows[0].license_key : '';

  // Retry transient network failures up to 3 times. Some hosts (Hostinger,
  // shared hosting behind WAF) intermittently drop or reset Railway's
  // outbound requests; a quick retry usually succeeds. Explicit User-Agent
  // set in case the upstream blocks empty UAs.
  const url = `${siteUrl}/wp-json/gas/v1/page-content/${pageId}?api_key=${encodeURIComponent(licenseKey)}&_t=${Date.now()}`;
  const fetchOptions = {
    signal: AbortSignal.timeout(15000),
    headers: { 'User-Agent': 'GAS-ProBuilder/1.0 (admin.gas.travel)' }
  };
  let wpRes = null;
  let lastErr = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      wpRes = await fetch(url, fetchOptions);
      break;
    } catch (e) {
      lastErr = e;
      console.log(`[proBuilderFetchContent] attempt ${attempt} failed for blog ${blogId} page ${pageId}:`, e.message, e.cause?.code || '');
      if (attempt < 3) await new Promise(r => setTimeout(r, 500 * attempt));
    }
  }
  if (!wpRes) return { error: `Fetch to WordPress failed after 3 retries: ${lastErr?.message || 'unknown'}${lastErr?.cause?.code ? ' (' + lastErr.cause.code + ')' : ''}` };
  if (!wpRes.ok) return { error: `WordPress API returned ${wpRes.status}` };

  const pageData = await wpRes.json();
  if (!pageData.success) return { error: pageData.error || 'Failed to fetch page content' };

  return { siteUrl, licenseKey, rawContent: pageData.raw_content || '', pageData };
}

async function proBuilderPushContent(siteUrl, licenseKey, pageId, newContent) {
  const pushRes = await fetch(`${siteUrl}/wp-json/gas/v1/push-template`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      api_key: licenseKey,
      block_markup: newContent,
      mode: 'replace_all_content',
      page_id: pageId
    }),
    signal: AbortSignal.timeout(30000)
  });
  return pushRes.json();
}

// Shared site lookup for pro-builder endpoints — returns { siteRow, siteUrl, licenseKey } or throws
async function proBuilderSiteLookup(blogId) {
  const site = await pool.query(
    'SELECT ds.*, a.subscription_tier FROM deployed_sites ds JOIN accounts a ON ds.account_id = a.id WHERE ds.blog_id = $1',
    [blogId]
  );
  if (site.rows.length === 0) throw new Error('Site not found');
  const siteRow = site.rows[0];
  if (!['pro', 'bespoke'].includes(siteRow.subscription_tier)) throw new Error('Pro or Bespoke subscription required');

  const license = await pool.query(
    "SELECT license_key FROM plugin_licenses WHERE account_id = $1 AND status = 'active' LIMIT 1",
    [siteRow.account_id]
  );
  const licenseKey = license.rows.length > 0 ? license.rows[0].license_key : '';
  const siteUrl = _proBuilderCanonicalSiteUrl(siteRow);

  return { siteRow, siteUrl, licenseKey };
}

// Helper: call plugin manage-page endpoint
async function proBuilderManagePage(siteUrl, licenseKey, actionPayload) {
  const res = await fetch(`${siteUrl}/wp-json/gas/v1/manage-page`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ api_key: licenseKey, ...actionPayload }),
    signal: AbortSignal.timeout(15000)
  });
  return res.json();
}

// GET /api/pro-builder/sites/:blog_id/pages/:page_id — fetch single page content
app.get('/api/pro-builder/sites/:blog_id/pages/:page_id', async (req, res) => {
  try {
    const auth = await proBuilderAuth(req);
    if (auth.error) return res.json({ success: false, error: auth.error });

    const blogId = parseInt(req.params.blog_id);
    const pageId = parseInt(req.params.page_id);

    const content = await proBuilderFetchContent(blogId, pageId);
    if (content.error) return res.json({ success: false, error: content.error });

    const sections = parseSections(content.rawContent);

    res.json({
      success: true,
      blog_id: blogId,
      page_id: pageId,
      title: content.pageData.title || 'Untitled',
      slug: content.pageData.slug,
      sections: sections,
      raw_content: content.rawContent
    });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// PUT /api/pro-builder/sites/:blog_id/pages/:page_id/sections/:index — replace a section
app.put('/api/pro-builder/sites/:blog_id/pages/:page_id/sections/:index', async (req, res) => {
  try {
    const auth = await proBuilderAuth(req);
    if (auth.error) return res.json({ success: false, error: auth.error });

    const frozenCheck = await checkSiteFrozenByBlogId(req.params.blog_id);
    if (frozenCheck.frozen) return res.json({ success: false, error: 'This site is frozen. Unfreeze it before making changes.' });

    const blogId = parseInt(req.params.blog_id);
    const pageId = parseInt(req.params.page_id);
    const sectionIndex = parseInt(req.params.index);
    const { markup } = req.body;

    if (typeof markup !== 'string') {
      return res.json({ success: false, error: 'markup is required' });
    }

    const content = await proBuilderFetchContent(blogId, pageId);
    if (content.error) return res.json({ success: false, error: content.error });

    const sections = parseSections(content.rawContent);
    if (sectionIndex < 0 || sectionIndex >= sections.length) {
      return res.json({ success: false, error: 'Section index out of range' });
    }

    const section = sections[sectionIndex];

    // Backup full page content before editing section
    await pool.query(
      `INSERT INTO page_content_backups (blog_id, page_id, content, action, section_type, section_index, created_by)
       VALUES ($1, $2, $3, 'edit', $4, $5, $6)`,
      [blogId, pageId, content.rawContent, section.type || null, sectionIndex, auth.userId || null]
    );

    const newContent = content.rawContent.substring(0, section.start) + markup + content.rawContent.substring(section.end);
    console.log(`[ProBuilder SAVE] blogId=${blogId} pageId=${pageId} sectionIndex=${sectionIndex} type=${section.type} markupLen=${markup.length} newContentLen=${newContent.length}`);

    const pushResult = await proBuilderPushContent(content.siteUrl, content.licenseKey, pageId, newContent);
    console.log(`[ProBuilder SAVE] pushResult:`, JSON.stringify(pushResult));
    res.json(pushResult);
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// DELETE /api/pro-builder/sites/:blog_id/pages/:page_id/sections/:index — delete a section
app.delete('/api/pro-builder/sites/:blog_id/pages/:page_id/sections/:index', async (req, res) => {
  try {
    const auth = await proBuilderAuth(req);
    if (auth.error) return res.json({ success: false, error: auth.error });

    const frozenCheck = await checkSiteFrozenByBlogId(req.params.blog_id);
    if (frozenCheck.frozen) return res.json({ success: false, error: 'This site is frozen. Unfreeze it before making changes.' });

    const blogId = parseInt(req.params.blog_id);
    const pageId = parseInt(req.params.page_id);
    const sectionIndex = parseInt(req.params.index);

    const content = await proBuilderFetchContent(blogId, pageId);
    if (content.error) return res.json({ success: false, error: content.error });

    const sections = parseSections(content.rawContent);
    if (sectionIndex < 0 || sectionIndex >= sections.length) {
      return res.json({ success: false, error: 'Section index out of range' });
    }

    const section = sections[sectionIndex];

    // Backup full page content before deleting section
    await pool.query(
      `INSERT INTO page_content_backups (blog_id, page_id, content, action, section_type, section_index, created_by)
       VALUES ($1, $2, $3, 'delete', $4, $5, $6)`,
      [blogId, pageId, content.rawContent, section.type || null, sectionIndex, auth.userId || null]
    );

    console.log(`[ProBuilder DELETE] blogId=${blogId} pageId=${pageId} sectionIndex=${sectionIndex} type=${section.type} totalSections=${sections.length} rawLen=${content.rawContent.length} start=${section.start} end=${section.end}`);
    // Remove section and any surrounding whitespace
    let before = content.rawContent.substring(0, section.start);
    let after = content.rawContent.substring(section.end);
    const newContent = (before.replace(/\s+$/, '') + '\n\n' + after.replace(/^\s+/, '')).trim();
    console.log(`[ProBuilder DELETE] newContent length=${newContent.length} pushing to ${content.siteUrl}`);

    const pushResult = await proBuilderPushContent(content.siteUrl, content.licenseKey, pageId, newContent);
    console.log(`[ProBuilder DELETE] pushResult:`, JSON.stringify(pushResult));
    res.json(pushResult);
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// POST /api/pro-builder/sites/:blog_id/pages/:page_id/reorder — move a section
app.post('/api/pro-builder/sites/:blog_id/pages/:page_id/reorder', async (req, res) => {
  try {
    const auth = await proBuilderAuth(req);
    if (auth.error) return res.json({ success: false, error: auth.error });

    const frozenCheck = await checkSiteFrozenByBlogId(req.params.blog_id);
    if (frozenCheck.frozen) return res.json({ success: false, error: 'This site is frozen. Unfreeze it before making changes.' });

    const blogId = parseInt(req.params.blog_id);
    const pageId = parseInt(req.params.page_id);
    const { from, to } = req.body;

    if (typeof from !== 'number' || typeof to !== 'number') {
      return res.json({ success: false, error: 'from and to indices are required' });
    }

    const content = await proBuilderFetchContent(blogId, pageId);
    if (content.error) return res.json({ success: false, error: content.error });

    const sections = parseSections(content.rawContent);
    if (from < 0 || from >= sections.length || to < 0 || to >= sections.length || from === to) {
      return res.json({ success: false, error: 'Invalid section indices' });
    }

    // Backup full page content before reordering
    await pool.query(
      `INSERT INTO page_content_backups (blog_id, page_id, content, action, section_type, section_index, created_by)
       VALUES ($1, $2, $3, 'reorder', NULL, NULL, $4)`,
      [blogId, pageId, content.rawContent, auth.userId || null]
    );

    // Extract all section markups in order, then rearrange
    const sectionMarkups = sections.map(s => s.raw_markup);
    const [moved] = sectionMarkups.splice(from, 1);
    sectionMarkups.splice(to, 0, moved);

    const newContent = sectionMarkups.join('\n\n');

    const pushResult = await proBuilderPushContent(content.siteUrl, content.licenseKey, pageId, newContent);
    res.json(pushResult);
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// POST /api/pro-builder/sites/:blog_id/push-css — push custom CSS to WordPress theme
app.post('/api/pro-builder/sites/:blog_id/push-css', async (req, res) => {
  try {
    const auth = await proBuilderAuth(req);
    if (auth.error) return res.json({ success: false, error: auth.error });

    const blogId = parseInt(req.params.blog_id);
    const { css } = req.body;

    // Get site row + license key. Prefer custom_domain over site_url — POST
    // on Hebden (live custom domain) 301-redirects on the apex which drops
    // the body, silently swallowing the CSS. Same fix pattern as commits
    // e60b1e78 (save) and 908a80d8 (insert).
    const siteResult = await pool.query(
      `SELECT ds.* FROM deployed_sites ds WHERE ds.blog_id = $1 LIMIT 1`,
      [blogId]
    );
    if (siteResult.rows.length === 0) return res.json({ success: false, error: 'Site not found' });

    const siteRow = siteResult.rows[0];
    const wpUrl = _proBuilderCanonicalSiteUrl(siteRow);
    if (!wpUrl) return res.json({ success: false, error: 'Site has no URL configured' });
    const license_key = siteRow.license_key;

    const wpRes = await fetch(`${wpUrl}/wp-json/gas/v1/push-css`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ api_key: license_key, css: css || '' })
    });
    const wpData = await wpRes.json();
    res.json(wpData);
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

