// POST /api/page-templates — create new template (master admin only)
app.post('/api/page-templates', async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.json({ success: false, error: 'Authentication required' });
    }
    const token = authHeader.split(' ')[1];
    const session = await pool.query(`
      SELECT s.account_id, a.role FROM account_sessions s
      JOIN accounts a ON s.account_id = a.id
      WHERE s.token = $1 AND s.expires_at > NOW()
    `, [token]);
    if (session.rows.length === 0 || session.rows[0].role !== 'master_admin') {
      return res.json({ success: false, error: 'Master admin access required' });
    }

    const { name, category, description, tier, template_type, elementor_json, block_markup, preview_image, sort_order } = req.body;

    if (!name || !category || (!elementor_json && !block_markup)) {
      return res.json({ success: false, error: 'name, category, and either elementor_json or block_markup are required' });
    }

    const result = await pool.query(`
      INSERT INTO gas_templates (name, category, description, tier, template_type, elementor_json, block_markup, preview_image, sort_order)
      VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) RETURNING *
    `, [name, category, description || null, tier || 'standard', template_type || 'section',
        elementor_json ? JSON.stringify(elementor_json) : null, block_markup || null, preview_image || null, sort_order || 0]);

    res.json({ success: true, data: result.rows[0] });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// PUT /api/page-templates/:id — update template (master admin only)
app.put('/api/page-templates/:id', async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.json({ success: false, error: 'Authentication required' });
    }
    const token = authHeader.split(' ')[1];
    const session = await pool.query(`
      SELECT s.account_id, a.role FROM account_sessions s
      JOIN accounts a ON s.account_id = a.id
      WHERE s.token = $1 AND s.expires_at > NOW()
    `, [token]);
    if (session.rows.length === 0 || session.rows[0].role !== 'master_admin') {
      return res.json({ success: false, error: 'Master admin access required' });
    }

    const { name, category, description, tier, template_type, elementor_json, preview_image, sort_order } = req.body;
    const fields = [];
    const params = [];

    if (name !== undefined) { params.push(name); fields.push(`name = $${params.length}`); }
    if (category !== undefined) { params.push(category); fields.push(`category = $${params.length}`); }
    if (description !== undefined) { params.push(description); fields.push(`description = $${params.length}`); }
    if (tier !== undefined) { params.push(tier); fields.push(`tier = $${params.length}`); }
    if (template_type !== undefined) { params.push(template_type); fields.push(`template_type = $${params.length}`); }
    if (elementor_json !== undefined) { params.push(JSON.stringify(elementor_json)); fields.push(`elementor_json = $${params.length}`); }
    if (preview_image !== undefined) { params.push(preview_image); fields.push(`preview_image = $${params.length}`); }
    if (sort_order !== undefined) { params.push(sort_order); fields.push(`sort_order = $${params.length}`); }

    if (fields.length === 0) {
      return res.json({ success: false, error: 'No fields to update' });
    }

    fields.push('updated_at = NOW()');
    params.push(req.params.id);

    const result = await pool.query(
      `UPDATE gas_templates SET ${fields.join(', ')} WHERE id = $${params.length} RETURNING *`,
      params
    );

    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Template not found' });
    }

    res.json({ success: true, data: result.rows[0] });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// DELETE /api/page-templates/:id — soft delete (master admin only)
app.delete('/api/page-templates/:id', async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.json({ success: false, error: 'Authentication required' });
    }
    const token = authHeader.split(' ')[1];
    const session = await pool.query(`
      SELECT s.account_id, a.role FROM account_sessions s
      JOIN accounts a ON s.account_id = a.id
      WHERE s.token = $1 AND s.expires_at > NOW()
    `, [token]);
    if (session.rows.length === 0 || session.rows[0].role !== 'master_admin') {
      return res.json({ success: false, error: 'Master admin access required' });
    }

    const result = await pool.query(
      'UPDATE gas_templates SET active = false, updated_at = NOW() WHERE id = $1 RETURNING id, name',
      [req.params.id]
    );

    if (result.rows.length === 0) {
      return res.json({ success: false, error: 'Template not found' });
    }

    res.json({ success: true, data: result.rows[0] });
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

// POST /api/page-templates/:id/push — push template to a WordPress site via GAS plugin
app.post('/api/page-templates/:id/push', async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.json({ success: false, error: 'Authentication required' });
    }
    const token = authHeader.split(' ')[1];
    const session = await pool.query(`
      SELECT s.account_id, a.role FROM account_sessions s
      JOIN accounts a ON s.account_id = a.id
      WHERE s.token = $1 AND s.expires_at > NOW()
    `, [token]);
    if (session.rows.length === 0) {
      return res.json({ success: false, error: 'Authentication required' });
    }

    const { account_id, site_url, blog_id, mode, page_id, position, page_title, page_slug, add_to_menu, raw_block_markup } = req.body;

    // TEMP DIAGNOSTIC: log button-href shape so the next push lets us
    // identify where `href="https//foo"` (missing colon) is being
    // generated. The Pro Builder safety net (commit aded0ccc) auto-
    // repairs the malformation before it reaches WordPress, so this is
    // purely for tracing — remove once root cause is found.
    if (typeof raw_block_markup === 'string' && raw_block_markup) {
      const badHrefs = raw_block_markup.match(/href=["'](?:https?)\/\/(?!\/)[^"']{0,80}/gi);
      if (badHrefs && badHrefs.length) {
        console.warn(`[page-templates push] malformed href(s) seen in raw_block_markup for blog_id=${blog_id} page_id=${page_id}:`, JSON.stringify(badHrefs));
      }
    }

    // Site protection — block pushes to frozen sites
    if (blog_id) {
      const frozenCheck = await checkSiteFrozenByBlogId(blog_id);
      if (frozenCheck.frozen) {
        return res.json({ success: false, error: 'This site is frozen. Unfreeze it before making changes.' });
      }
    }

    // Template ID 0 = custom-built section (raw markup provided directly)
    let tpl = null;
    if (req.params.id !== '0') {
      const template = await pool.query(
        'SELECT * FROM gas_templates WHERE id = $1 AND active = true',
        [req.params.id]
      );
      if (template.rows.length === 0) {
        return res.json({ success: false, error: 'Template not found' });
      }
      tpl = template.rows[0];
    }

    let resolvedUrl = site_url;
    let resolvedAccountId = account_id;

    // Allow blog_id as alternative to site_url + account_id.
    // Prefer custom_domain over site_url — for live custom-domain multisites
    // like www.hebdenbridgehostel.org, site_url still points at the pre-cutover
    // host, which 301-redirects to the canonical www. Node fetch follows the
    // 301 but downgrades POST → GET, so the plugin sees no route (404 as
    // "Failed to insert section"). Same fix as _proBuilderCanonicalSiteUrl
    // for the save endpoint (commit e60b1e78).
    if (blog_id && (!site_url || !account_id)) {
      const siteRow = await pool.query('SELECT * FROM deployed_sites WHERE blog_id = $1', [blog_id]);
      if (siteRow.rows.length === 0) {
        return res.json({ success: false, error: 'Site not found for blog_id' });
      }
      resolvedUrl = _proBuilderCanonicalSiteUrl(siteRow.rows[0]);
      resolvedAccountId = siteRow.rows[0].account_id;
    }

    if (!resolvedUrl || !resolvedAccountId) {
      return res.json({ success: false, error: 'site_url and account_id (or blog_id) are required' });
    }

    // Look up license key for this account
    const license = await pool.query(
      "SELECT license_key FROM plugin_licenses WHERE account_id = $1 AND status = 'active' LIMIT 1",
      [resolvedAccountId]
    );
    if (license.rows.length === 0) {
      return res.json({ success: false, error: 'No active license found for this account' });
    }

    let cleanUrl = resolvedUrl.replace(/\/$/, '');
    if (!cleanUrl.startsWith('http')) { cleanUrl = 'https://' + cleanUrl; }
    const apiKey = license.rows[0].license_key;

    // Call the WordPress plugin endpoint
    const pushResponse = await fetch(`${cleanUrl}/wp-json/gas/v1/push-template`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        api_key: apiKey,
        template_json: tpl ? (tpl.elementor_json || null) : null,
        block_markup: tpl ? (tpl.block_markup || null) : (raw_block_markup || null),
        mode: mode || 'push_to_existing',
        page_id,
        position: position || 'bottom',
        page_title,
        page_slug,
        add_to_menu: add_to_menu || false
      }),
      signal: AbortSignal.timeout(30000)
    });

    const pushData = await pushResponse.json();
    res.json(pushData);
  } catch (error) {
    res.json({ success: false, error: error.message });
  }
});

