    //                           product pre-attached
    //   offer_buy_standalone  — the existing standalone shop checkout
    // Defaults chosen so operators upgrading existing products keep the
    // current behaviour (standalone available; add-to-stay opt-in).
    await pool.query(`ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS offer_add_to_stay    BOOLEAN DEFAULT true`);
    await pool.query(`ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS offer_book_with_room BOOLEAN DEFAULT false`);
    await pool.query(`ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS offer_buy_standalone BOOLEAN DEFAULT true`);
    await pool.query(`CREATE INDEX IF NOT EXISTS idx_shop_products_crm ON shop_products(account_id, is_crm_upsell) WHERE is_crm_upsell = true`);

    // Section-Builder blocks — same JSON shape as sparks.blocks / page_sections.
