    await pool.query(`ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS included_nights_per_unit INTEGER`);
    await pool.query(`ALTER TABLE upsells ADD COLUMN IF NOT EXISTS included_nights_per_unit INTEGER`);

