// PUBLIC endpoint for WordPress plugins to fetch reviews
app.get('/api/public/client/:clientId/reviews', async (req, res) => {
    try {
        const { clientId } = req.params;
        const { property_id, min_rating, limit } = req.query;
        
        // Get account - try by id first (numeric), then by account_code
        let accountId;
        const numericId = parseInt(clientId);
        
        if (!isNaN(numericId)) {
            const accountResult = await pool.query('SELECT id FROM accounts WHERE id = $1', [numericId]);
            if (accountResult.rows.length > 0) {
                accountId = accountResult.rows[0].id;
            }
        }
        
        if (!accountId) {
            const accountResult = await pool.query('SELECT id FROM accounts WHERE account_code = $1', [clientId]);
            if (accountResult.rows.length > 0) {
                accountId = accountResult.rows[0].id;
            }
        }
        
        if (!accountId) {
            return res.json({ success: true, reviews: [] });
        }
        
        let query = `
            SELECT r.*, p.name as property_name
            FROM reviews r
            JOIN properties p ON r.property_id = p.id
            WHERE p.account_id = $1 AND r.is_public = true
        `;
        const params = [accountId];
        let paramIndex = 2;
        
        if (property_id) {
            query += ` AND r.property_id = $${paramIndex}`;
            params.push(property_id);
            paramIndex++;
        }
        
        if (min_rating) {
            query += ` AND r.rating >= $${paramIndex}`;
            params.push(parseFloat(min_rating));
            paramIndex++;
        }
        
        const reviewLimit = Math.min(parseInt(limit) || 50, 100);
        query += ` ORDER BY r.review_date DESC NULLS LAST, r.created_at DESC LIMIT ${reviewLimit}`;
        
        const reviewsResult = await pool.query(query, params);

        // Speed pass — reviews change slowly (new OTA reviews sync
        // hourly-daily); 30s cache + 60s SWR gives instant repeat
        // visits without hiding fresh reviews for long.
        res.set('Cache-Control', 'public, max-age=30, stale-while-revalidate=60');
        res.json({
            success: true,
            reviews: reviewsResult.rows.map(r => ({
                id: r.id,
                property_id: r.property_id,
                property_name: r.property_name,
                guest_name: r.guest_name,
                guest_country: r.guest_country,
                rating: r.rating,
                comment: r.comment,
                review_date: r.review_date,
                source: r.source || r.channel_name
            })),
            total: reviewsResult.rows.length
        });
        
    } catch (error) {
        console.error('Public reviews error:', error);
        res.json({ success: true, reviews: [] });
    }
});

// GET /api/app-settings/:app - Get app display settings (blog, attractions, reviews, properties)
app.get('/api/app-settings/:app', async (req, res) => {
    try {
        const { app } = req.params;
        const validApps = ['blog', 'attractions', 'reviews', 'properties', 'shop'];
        
        if (!validApps.includes(app)) {
            return res.status(400).json({ success: false, error: 'Invalid app name' });
        }
        
        // Ensure table exists
        await pool.query(`
            CREATE TABLE IF NOT EXISTS app_settings (
                id SERIAL PRIMARY KEY,
                account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
                app_name VARCHAR(50) NOT NULL,
                settings JSONB DEFAULT '{}',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(account_id, app_name)
            )
        `);
        
        const accountId = req.query.account_id || req.user?.account_id || 1;
        
        const result = await pool.query(
            `SELECT settings FROM app_settings WHERE account_id = $1 AND app_name = $2`,
            [accountId, app]
        );
        
        if (result.rows.length > 0) {
            const s = result.rows[0].settings || {};
            res.json({ success: true, colors: s.colors || {}, fonts: s.fonts || {}, ...s });
        } else {
            // Return defaults
            const defaults = {
                blog: { accent: '#667eea', bg: '#ffffff', card_bg: '#ffffff', text: '#1a1a1a', text_secondary: '#666666', category_bg: '#e0e7ff', category_text: '#4338ca' },
                attractions: { accent: '#f59e0b', bg: '#ffffff', card_bg: '#ffffff', text: '#1a1a1a', text_secondary: '#666666', category_bg: '#fef3c7', category_text: '#92400e' },
                reviews: { accent: '#667eea', bg: '#ffffff', card_bg: '#ffffff', text: '#1e293b', text_secondary: '#64748b', star: '#fbbf24' }
            };
            res.json({ success: true, colors: defaults[app] });
        }
    } catch (error) {
        console.error('Error getting app settings:', error);
        res.status(500).json({ success: false, error: 'Failed to get settings' });
    }
});

// PUT /api/app-settings/:app - Save app display settings
app.put('/api/app-settings/:app', async (req, res) => {
    try {
        const { app } = req.params;
        const { colors, fonts } = req.body;
        const validApps = ['blog', 'attractions', 'reviews', 'properties', 'shop'];
        
        if (!validApps.includes(app)) {
            return res.status(400).json({ success: false, error: 'Invalid app name' });
        }
        
        // Ensure table exists
        await pool.query(`
            CREATE TABLE IF NOT EXISTS app_settings (
                id SERIAL PRIMARY KEY,
                account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
                app_name VARCHAR(50) NOT NULL,
                settings JSONB DEFAULT '{}',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(account_id, app_name)
            )
        `);
        
        const accountId = req.body.account_id || req.query.account_id || req.user?.account_id || 1;

        // Build settings JSONB from all body keys except account_id
        const { account_id: _ignored, ...settingsPayload } = req.body;
        settingsPayload.colors = colors;
        settingsPayload.fonts = fonts || {};

        const result = await pool.query(
            `INSERT INTO app_settings (account_id, app_name, settings, updated_at)
             VALUES ($1, $2, $3, NOW())
             ON CONFLICT (account_id, app_name)
             DO UPDATE SET settings = $3, updated_at = NOW()
             RETURNING *`,
            [accountId, app, settingsPayload]
        );

        // Bust the per-site transients so the WordPress plugin picks up the
        // change immediately rather than waiting up to 5 minutes for the
        // transient (set in plugins/gas-{app}/{app}.php :: get_colors/get_fonts).
        try {
          const sitesRes = await pool.query(
            'SELECT site_url, blog_id FROM deployed_sites WHERE account_id = $1 AND blog_id IS NOT NULL AND site_url IS NOT NULL',
            [accountId]
          );
          // Cached HTML paths to bust per app — colour changes only render after SuperCache flushes.
          const pagePathsByApp = { blog: ['blog'], attractions: ['attractions'], reviews: ['reviews'], properties: ['rooms', 'book-now'], shop: ['shop'] };
          const paths = pagePathsByApp[app] || [];
          for (const site of sitesRes.rows) {
            for (const tk of [`gas_${app}_colors`, `gas_${app}_fonts`]) {
              fetch('https://sites.gas.travel/gas-api.php', {
                method: 'POST',
                headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'flush_transient', site_url: site.site_url, transient_key: tk })
              }).catch(() => {});
            }
            if (paths.length) {
              fetch('https://sites.gas.travel/gas-api.php', {
                method: 'POST',
                headers: { 'X-API-Key': 'gas-deploy-2024-secure-key', 'Content-Type': 'application/json' },
                body: JSON.stringify({ action: 'flush_page_cache', site_url: site.site_url, paths })
              }).catch(() => {});
            }
          }
        } catch (e) {
          console.log('[app-settings] transient flush skipped:', e.message);
        }

        res.json({ success: true, message: 'Settings saved', settings: result.rows[0] });
    } catch (error) {
        console.error('Error saving app settings:', error);
        res.status(500).json({ success: false, error: 'Failed to save settings' });
    }
});

