// PUT /api/admin/shop/orders/:id/status — update order status
app.put('/api/admin/shop/orders/:id/status', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });

    const orderId = parseInt(req.params.id);
    const clientId = req.query.client_id || req.body.client_id || decoded.accountId || decoded.id;
    const { status } = req.body;

    const validStatuses = ['pending', 'processing', 'fulfilled', 'cancelled'];
    if (!validStatuses.includes(status)) return res.status(400).json({ success: false, error: 'Invalid status. Must be: ' + validStatuses.join(', ') });

    const updates = { status };
    if (status === 'fulfilled') updates.fulfilled_at = new Date();

    const result = await pool.query(
      `UPDATE shop_orders SET status = $1, fulfilled_at = ${status === 'fulfilled' ? 'NOW()' : 'fulfilled_at'}, updated_at = NOW()
       WHERE id = $2 AND account_id = $3 RETURNING *`,
      [status, orderId, clientId]
    );
    if (!result.rows.length) return res.status(404).json({ success: false, error: 'Order not found' });

    res.json({ success: true, order: result.rows[0] });
  } catch (error) {
    console.error('Shop order status update error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// =============================================================================
// Phase 1 Guest Entity — admin endpoints
//
// GET    /api/admin/guests           paginated list, search by name/email
// GET    /api/admin/guests/:id       full detail + bookings + comms + docs
// PATCH  /api/admin/guests/:id       update notes / language / opt-in
//
// Scoping: master_admin sees all (or filters by ?account_id=N); every other
// role is locked to their own account.
// =============================================================================

app.get('/api/admin/guests', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });

    const isMaster = decoded.role === 'master_admin';
    const filterAccountId = req.query.account_id ? parseInt(req.query.account_id) : null;
    // 2026-07-22 Steve — CRM data leak. Was:
    //   const scopedAccountId = isMaster ? filterAccountId : (decoded.accountId || decoded.id);
    // Then `if (scopedAccountId) push WHERE g.account_id = $N`. Which meant
    // a master admin who didn't pass account_id got NO WHERE clause and
    // every guest across every account came back — Steve hit this while
    // logged in viewing Hebden's Guests screen and saw non-Hebden names.
    // Fix: master must always pass account_id explicitly; anything else
    // falls back to the session account. Never return cross-account data.
    let scopedAccountId;
    if (isMaster) {
      if (!filterAccountId) {
        return res.status(400).json({ success: false, error: 'account_id required (master admin must pass an account explicitly)' });
      }
      scopedAccountId = filterAccountId;
    } else {
      scopedAccountId = decoded.accountId || decoded.id;
      // Non-master trying to peek at another account — refuse.
      if (filterAccountId && filterAccountId !== scopedAccountId) {
        return res.status(403).json({ success: false, error: 'Forbidden' });
      }
    }
    if (!scopedAccountId) {
      return res.status(400).json({ success: false, error: 'Could not resolve account scope' });
    }

    const q = (req.query.q || '').trim();
    const page = Math.max(1, parseInt(req.query.page) || 1);
    const perPage = Math.min(100, Math.max(1, parseInt(req.query.per_page) || 25));
    const offset = (page - 1) * perPage;

    const where = [];
    const params = [];
    params.push(scopedAccountId);
    where.push(`g.account_id = $${params.length}`);
    if (q) {
      params.push(`%${q.toLowerCase()}%`);
      const i = params.length;
      where.push(`(lower(g.email) LIKE $${i} OR lower(g.first_name) LIKE $${i} OR lower(g.last_name) LIKE $${i} OR lower(coalesce(g.first_name,'') || ' ' || coalesce(g.last_name,'')) LIKE $${i})`);
    }
    const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

    const listSql = `
      SELECT g.id, g.account_id, a.name AS account_name, g.email, g.first_name, g.last_name,
             g.phone, g.country, g.total_bookings, g.total_spent_cents, g.last_stay_at,
             g.recognised_at, g.last_seen_at, g.opt_in_status,
             g.stripe_identity_verified, g.created_at
      FROM guests g
      LEFT JOIN accounts a ON a.id = g.account_id
      ${whereSql}
      ORDER BY g.last_seen_at DESC NULLS LAST, g.id DESC
      LIMIT $${params.length + 1} OFFSET $${params.length + 2}
    `;
    const countSql = `SELECT COUNT(*)::int AS total FROM guests g ${whereSql}`;
    const [list, count] = await Promise.all([
      pool.query(listSql, [...params, perPage, offset]),
      pool.query(countSql, params)
    ]);

    res.json({
      success: true,
      guests: list.rows,
      total: count.rows[0].total,
      page, per_page: perPage,
      has_more: offset + list.rows.length < count.rows[0].total
    });
  } catch (error) {
    console.error('Guests list error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

app.get('/api/admin/guests/:id', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const isMaster = decoded.role === 'master_admin';
    const guestId = parseInt(req.params.id);

    const guestRow = await pool.query(
      `SELECT g.*, a.name AS account_name FROM guests g
       LEFT JOIN accounts a ON a.id = g.account_id WHERE g.id = $1`,
      [guestId]
    );
    if (!guestRow.rows[0]) return res.status(404).json({ success: false, error: 'Guest not found' });
    const guest = guestRow.rows[0];
    if (!isMaster && guest.account_id !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    // Don't leak the magic-link secret to the admin UI — it's a token-signing key.
    delete guest.magic_link_secret;

    const [bookings, comms, docs, extras] = await Promise.all([
      pool.query(
        `SELECT id, group_booking_id, property_id, bookable_unit_id, arrival_date, departure_date,
                num_adults, num_children, status, payment_status, grand_total, currency, created_at
           FROM bookings WHERE guest_id = $1 ORDER BY arrival_date DESC NULLS LAST, id DESC LIMIT 50`,
        [guestId]
      ),
      pool.query(
        `SELECT id, booking_id, channel, direction, event_type, subject, status,
                sent_at, opened_at, clicked_at, created_at
           FROM guest_communications WHERE guest_id = $1
           ORDER BY created_at DESC LIMIT 100`,
        [guestId]
      ),
      pool.query(
        `SELECT id, booking_id, document_type, status, verification_method,
                verified_at, created_at
           FROM guest_documents WHERE guest_id = $1 ORDER BY created_at DESC`,
        [guestId]
      ),
      pool.query(
        `SELECT id, booking_id, source_type, source_id, name, qty, unit_price, currency, status, created_at
           FROM booking_extras WHERE guest_id = $1 ORDER BY created_at DESC`,
        [guestId]
      )
    ]);

    res.json({
      success: true,
      guest,
      bookings: bookings.rows,
      communications: comms.rows,
      documents: docs.rows,
      extras: extras.rows
    });
  } catch (error) {
    console.error('Guest detail error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

app.patch('/api/admin/guests/:id', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const isMaster = decoded.role === 'master_admin';
    const guestId = parseInt(req.params.id);

    const existing = await pool.query('SELECT account_id FROM guests WHERE id = $1', [guestId]);
    if (!existing.rows[0]) return res.status(404).json({ success: false, error: 'Guest not found' });
    if (!isMaster && existing.rows[0].account_id !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    // Whitelist of writable fields. Email + account_id intentionally NOT
    // editable — they're identity. Stats columns are derived. Magic-link
    // secret is rotated through a dedicated endpoint when we add one.
    const allowed = ['notes', 'language', 'tags', 'phone', 'first_name', 'last_name',
                     'address', 'city', 'postcode', 'country', 'date_of_birth', 'opt_in_status'];
    const sets = [];
    const params = [guestId];
    for (const key of allowed) {
      if (req.body[key] !== undefined) {
        params.push(req.body[key]);
        sets.push(`${key} = $${params.length}`);
      }
    }
    if (!sets.length) return res.json({ success: true, updated: false });

    sets.push('updated_at = NOW()');
    const updateSql = `UPDATE guests SET ${sets.join(', ')} WHERE id = $1 RETURNING *`;
    const r = await pool.query(updateSql, params);
    delete r.rows[0].magic_link_secret;
    res.json({ success: true, updated: true, guest: r.rows[0] });
  } catch (error) {
    console.error('Guest update error:', error);
    res.status(500).json({ success: false, error: error.message });
  }
});

// =============================================================================
// Phase 1 Guest Entity — ID & compliance policy + co-traveller invites
//
// id_policy is JSONB on accounts. Schema-default keys:
//   require_guest_id              master switch
//   collect_at                    'pre_arrival' | 'on_arrival'
//   verification_mode             'manual' | 'stripe_identity'
//   required_documents            ['passport', 'driving_licence', ...]
//   full_number_required          collect full doc number, not just last4
//   required_id_countries         restrict to property countries (empty = all)
//   stripe_identity_enabled       allow the Request Stripe Identity action
//   require_id_for_lead_only      lead guest only, or every co-traveller
//   retention_days_post_stay      auto-delete after this many days post-stay
// =============================================================================

app.get('/api/admin/accounts/:id/id-policy', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const accountId = parseInt(req.params.id);
    const isMaster = decoded.role === 'master_admin';
    if (!isMaster && accountId !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }
    const r = await pool.query('SELECT id_policy FROM accounts WHERE id = $1', [accountId]);
    if (!r.rows[0]) return res.status(404).json({ success: false, error: 'Account not found' });
    res.json({ success: true, id_policy: r.rows[0].id_policy });
  } catch (err) {
    console.error('id-policy get error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

app.put('/api/admin/accounts/:id/id-policy', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const accountId = parseInt(req.params.id);
    const isMaster = decoded.role === 'master_admin';
    if (!isMaster && accountId !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    // Whitelist incoming keys — we only persist the documented schema keys.
    const allowed = ['require_guest_id', 'collect_at', 'verification_mode',
                     'required_documents', 'full_number_required',
                     'required_id_countries', 'stripe_identity_enabled',
                     'require_id_for_lead_only', 'retention_days_post_stay'];
    const policy = {};
    for (const k of allowed) {
      if (req.body[k] !== undefined) policy[k] = req.body[k];
    }

    const r = await pool.query(
      `UPDATE accounts SET id_policy = id_policy || $2::jsonb, updated_at = NOW()
        WHERE id = $1 RETURNING id_policy`,
      [accountId, JSON.stringify(policy)]
    );
    res.json({ success: true, id_policy: r.rows[0].id_policy });
  } catch (err) {
    console.error('id-policy update error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// Invite a co-traveller to a booking. Creates / recognises a guest for the
// invited email, links them to the booking with role='co_traveller', and
// emails a magic link to the same /your-stay portal.
app.post('/api/admin/bookings/:id/invite-co-traveller', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Authentication required' });
    const isMaster = decoded.role === 'master_admin';
    const bookingId = parseInt(req.params.id);
    const { email, first_name, last_name } = req.body || {};
    if (!email) return res.status(400).json({ success: false, error: 'email is required' });

    const bk = await pool.query(
      `SELECT b.id, b.guest_id, b.arrival_date, p.account_id, p.name AS property_name
         FROM bookings b LEFT JOIN properties p ON p.id = b.property_id
         WHERE b.id = $1`,
      [bookingId]
    );
    if (!bk.rows[0]) return res.status(404).json({ success: false, error: 'Booking not found' });
    const booking = bk.rows[0];
    if (!isMaster && booking.account_id !== (decoded.accountId || decoded.id)) {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    const recog = await recogniseGuest(pool, {
      accountId: booking.account_id,
      email, firstName: first_name, lastName: last_name
    });
    if (!recog) return res.status(400).json({ success: false, error: 'Could not resolve invited guest' });

    // Add to booking_guests as co_traveller, idempotent on (booking_id, guest_id).
    const inviteToken = require('crypto').randomBytes(16).toString('hex');
    await pool.query(
      `INSERT INTO booking_guests (booking_id, guest_id, role, invited_at, invite_token, email, first_name, last_name)
       VALUES ($1, $2, 'co_traveller', NOW(), $3, $4, $5, $6)
       ON CONFLICT DO NOTHING`,
      [bookingId, recog.guestId, inviteToken, email, first_name || null, last_name || null]
    );

    // Sign a magic-link token bound to the new guest + this booking.
    const guestRow = await pool.query('SELECT magic_link_secret FROM guests WHERE id = $1', [recog.guestId]);
    const magicToken = signGuestToken({
      guestId: recog.guestId,
      bookingId,
      purpose: GUEST_TOKEN_PURPOSES.CO_TRAVELLER_INVITE,
      secret: guestRow.rows[0].magic_link_secret
    });
    const portalUrl = `${req.protocol}://${req.get('host')}/your-stay.html#${magicToken}`;

    const result = await sendEmail({
      to: email,
      subject: `You've been added to a booking at ${booking.property_name || 'a property'}`,
      html: `<!DOCTYPE html><html><body style="font-family:-apple-system,BlinkMacSystemFont,sans-serif;line-height:1.6;color:#333;max-width:600px;margin:0 auto;padding:40px 20px;">
        <h2>Hi ${first_name || 'there'},</h2>
        <p>You've been added as a co-traveller on a booking. Use the link below to confirm your details and (if requested) upload your ID — it'll save time on arrival.</p>
        <p><a href="${portalUrl}" style="display:inline-block;background:#3b82f6;color:white;padding:14px 28px;text-decoration:none;border-radius:8px;font-weight:500;">Open your details</a></p>
        <p style="color:#666;font-size:13px;">This link is private to you. It expires in 30 days.</p>
      </body></html>`,
      context: {
        guestId: recog.guestId,
        bookingId,
        eventType: 'co_traveller_invite',
        accountId: booking.account_id
      }
    });

    if (!result.success) return res.status(502).json({ success: false, error: result.error });
    res.json({ success: true, sent_to: email, guest_id: recog.guestId });
  } catch (err) {
    console.error('invite-co-traveller error:', err);
    res.status(500).json({ success: false, error: err.message });
  }
});

// GET /api/admin/shop/settings — shop config for account
