app.post('/api/public/forms/:account/:slug/submit', express.json(), async (req, res) => {
  try {
    const accountId = parseInt(req.params.account);
    const slug = String(req.params.slug).toLowerCase();
    const data = req.body || {};

    // Honeypot — bots fill the hidden 'website' field, real users won't see it.
    if (data._hp || data.website_url) {
      return res.json({ success: true, action: 'show_message', message: 'Thank you!' });  // silent reject
    }

    const formRes = await pool.query(
      'SELECT * FROM lead_forms WHERE account_id = $1 AND slug = $2 AND active = true',
      [accountId, slug]
    );
    if (!formRes.rows.length) return res.status(404).json({ success: false, error: 'Form not found' });
    const form = formRes.rows[0];

    if (!data.email) return res.status(400).json({ success: false, error: 'Email is required' });

    // Save submission first — never lose a lead even if the CRM push fails.
    const subRes = await pool.query(
      `INSERT INTO lead_form_submissions (form_id, account_id, data, ip, user_agent, referrer)
       VALUES ($1, $2, $3, $4, $5, $6) RETURNING id`,
      [form.id, accountId, data,
       req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.ip || null,
       req.headers['user-agent'] || null,
       req.headers['referer'] || null]
    );
    const submissionId = subRes.rows[0].id;
    await pool.query('UPDATE lead_forms SET submission_count = submission_count + 1 WHERE id = $1', [form.id]);

    // Push to CRM (best-effort — record success/failure on the submission row).
    if (form.crm_connection_id) {
      const connRes = await pool.query('SELECT * FROM crm_connections WHERE id = $1 AND account_id = $2 AND active = true', [form.crm_connection_id, accountId]);
      if (connRes.rows.length) {
        const conn = connRes.rows[0];
        const pushResult = await crmPush(conn, { tag_or_list_id: form.crm_tag_or_list_id }, {
          email: data.email,
          first_name: data.first_name || data.fname || '',
          last_name: data.last_name || data.lname || '',
          phone: data.phone || '',
          custom: data
        });
        await pool.query(
          'UPDATE lead_form_submissions SET crm_pushed = $1, crm_pushed_at = NOW(), crm_response = $2, crm_error = $3 WHERE id = $4',
          [pushResult.ok, pushResult.response ? JSON.stringify(pushResult.response) : null, pushResult.error || null, submissionId]
        );
      }
    }

    // Merge-tag dictionary built from submitted fields. {{first_name}} is
    // derived from name/full_name if not directly supplied. Unknown tags are
    // left as-is so unfilled placeholders are visible (not silently blank).
    const tags = {};
    for (const [k, v] of Object.entries(data || {})) {
      if (v && typeof v !== 'object') tags[String(k).toLowerCase()] = String(v);
    }
    if (!tags.first_name && tags.name) tags.first_name = String(tags.name).trim().split(/\s+/)[0] || '';
    if (!tags.first_name && tags.full_name) tags.first_name = String(tags.full_name).trim().split(/\s+/)[0] || '';
    const subst = (str) => String(str || '').replace(/\{\{\s*([a-z0-9_]+)\s*\}\}/gi, (m, key) => {
      const k = key.toLowerCase();
      return tags[k] !== undefined ? String(tags[k]) : m;
    });

    // Auto-respond to submitter — fires when a freebie is configured.
    // Falls back to sensible default copy if subject/body left blank so an
    // uploaded PDF is never lost to "owner forgot to write the email".
    if (form.freebie_file_url && data.email) {
      const linkHtml = `<a href="${form.freebie_file_url}" style="display:inline-block;padding:12px 24px;background:#10b981;color:#fff;text-decoration:none;border-radius:6px;font-weight:600;">Download your guide</a>`;
      const subject = subst(form.autorespond_subject || `Your ${form.title || 'free guide'} is ready`);
      let bodyHtml = subst(form.autorespond_body_html || `<p>Hi {{first_name}},</p><p>Thanks for completing the form — here's your download:</p><p>{{download_link}}</p>`);
      bodyHtml = bodyHtml.includes('{{download_link}}')
        ? bodyHtml.replace(/\{\{download_link\}\}/g, linkHtml)
        : `${bodyHtml}<p style="margin-top:20px;">${linkHtml}</p>`;
      try {
        await sendEmail({ to: data.email, subject, html: bodyHtml });
        console.log(`[lead-form ${slug}] auto-respond sent to ${data.email}`);
      } catch (e) { console.error('[lead-form] auto-respond email failed:', e.message); }
    }

    // Owner notification — copy of every submission to the configured email.
    if (form.notify_email) {
      let rows = '';
      Object.entries(data).forEach(([k, v]) => {
        if (k.startsWith('_')) return; // skip honeypot + meta fields
        const display = v && typeof v === 'object' ? (v.url || JSON.stringify(v)) : String(v ?? '');
        rows += `<tr><td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;font-weight:600;color:#374151;width:180px;">${k}</td><td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;color:#475569;">${display}</td></tr>`;
      });
      const notifyHtml = `<div style="font-family:sans-serif;max-width:600px;margin:0 auto;">
        <h2 style="color:#1e293b;margin:0 0 16px;">New ${form.title || 'Lead Form'} Submission</h2>
        <table style="width:100%;border-collapse:collapse;background:#fff;border-radius:8px;overflow:hidden;border:1px solid #e5e7eb;">${rows}</table>
        <p style="color:#94a3b8;font-size:0.8rem;margin-top:16px;">Submitted via GAS Lead Form • #${submissionId}</p>
      </div>`;
      try {
        await sendEmail({ to: form.notify_email, subject: `New ${form.title || 'Lead Form'} Submission`, html: notifyHtml });
      } catch (e) { console.error('[lead-form] owner notify failed:', e.message); }
    }

    // Phase 4 — resolve the origin site from the referrer so the contact
    // gets first-touch site attribution. If we can't identify the site
    // (embed on a non-registered domain, missing referer header) we
    // silently insert NULL — the record still lands as before.
    let originSiteId = null;
    try {
      const ref = req.headers['referer'];
      if (ref) {
        const host = new URL(ref).host.replace(/^www\./, '');
        const r = await pool.query(
          `SELECT id FROM deployed_sites
            WHERE custom_domain = $1
               OR site_url LIKE $2
               OR site_url LIKE $3
            LIMIT 1`,
          [host, `%//${host}%`, `%://${host}/%`]
        );
        if (r.rows[0]) originSiteId = r.rows[0].id;
      }
    } catch (_) { /* silent — NULL site fallback */ }

    // GAS Actions emission — upsert the submitter into contacts so any
    // workflow listening for spark.form_submitted or newsletter.signup
    // can fire. Best-effort: failures here never break the form response.
    try {
      const upR = await pool.query(`
        INSERT INTO contacts (account_id, source, email, first_name, last_name, full_name, phone, deployed_site_id)
        VALUES ($1, 'spark_form', $2, $3, $4, $5, $6, $7)
        ON CONFLICT (account_id, lower(email))
        DO UPDATE SET
          first_name = COALESCE(contacts.first_name, EXCLUDED.first_name),
          last_name = COALESCE(contacts.last_name, EXCLUDED.last_name),
          full_name = COALESCE(contacts.full_name, EXCLUDED.full_name),
          phone = COALESCE(contacts.phone, EXCLUDED.phone),
          -- deployed_site_id intentionally NOT touched here — first-touch wins.
          updated_at = NOW()
        RETURNING id
      `, [
        accountId,
        String(data.email).toLowerCase(),
        data.first_name || data.fname || (data.name ? String(data.name).trim().split(/\s+/)[0] : null),
        data.last_name || data.lname || null,
        data.full_name || data.name || null,
        data.phone || null,
        originSiteId
      ]).catch(() => null);
      const contactId = upR?.rows?.[0]?.id || null;
      if (contactId) {
        // Phase 1 unification: every contact gets a global traveller_id
        // and a recomputed traveller_property_links row for this account.
        // Failure here never breaks the form response (best-effort).
        await syncTravellerForContact(contactId).catch(() => {});
        await emitRecipeEvent(accountId, 'spark.form_submitted', { contact_id: contactId, form_slug: slug, submission_id: submissionId }).catch(() => {});
        await emitRecipeEvent(accountId, 'newsletter.signup', { contact_id: contactId, submission_id: submissionId }).catch(() => {});
      }
    } catch (e) { console.warn('[lead-form] gas-action emit skipped:', e.message); }

    res.json({
      success: true,
      action: form.post_submit_action || 'show_message',
      message: form.success_message || 'Thank you!',
      redirect_url: form.redirect_url || null,
      file_url: form.freebie_file_url || null
    });
  } catch (e) {
    console.error('Form submit error:', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /api/webhooks/stripe-shop — handle shop payment completion
app.post('/api/webhooks/stripe-shop', express.raw({ type: 'application/json' }), async (req, res) => {
  try {
    // Parse event — verify signature if secret is set
    const webhookSecret = process.env.STRIPE_SHOP_WEBHOOK_SECRET;
    let event;

    if (webhookSecret) {
      const sig = req.headers['stripe-signature'];
      const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from(req.body);
      event = stripe.webhooks.constructEvent(rawBody, sig, webhookSecret);
    } else {
      console.warn('[SHOP] WARNING: STRIPE_SHOP_WEBHOOK_SECRET not set — skipping signature verification');
      event = JSON.parse(Buffer.isBuffer(req.body) ? req.body.toString('utf8') : req.body);
    }

    console.log('[SHOP] Webhook event:', event.type);

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;
      const orderId = session.metadata?.gas_order_id;
      const accountId = session.metadata?.gas_account_id;
      const sessionType = session.metadata?.type;

      // Add-to-stay session (Marie / Lehmann 2026-07-10) — guest without
      // a card on file paid for an upsell via Checkout. Flip the pending
      // booking_extras row to 'paid', log a payment_transactions row,
      // fire the Beds24 sync + confirmation email. Idempotent — a second
      // fire finds the row already 'paid' and no-ops.
      if (sessionType === 'add_to_stay') {
        const bookingId = parseInt(session.metadata.gas_booking_id, 10);
        const extraId = parseInt(session.metadata.gas_extra_id, 10);
        const productId = parseInt(session.metadata.gas_product_id, 10);
        if (!bookingId || !extraId) { console.warn('[SHOP add_to_stay] missing metadata'); return res.json({ received: true }); }
        const upd = await pool.query(
          `UPDATE booking_extras
             SET status = 'paid', updated_at = NOW()
           WHERE id = $1 AND booking_id = $2 AND status <> 'paid'
           RETURNING id, unit_price, currency, name`,
          [extraId, bookingId]
        );
        if (!upd.rows[0]) {
          console.log('[SHOP add_to_stay] extra already paid or missing:', extraId);
          return res.json({ received: true });
        }
        const extra = upd.rows[0];
        await pool.query(
          `INSERT INTO payment_transactions
             (booking_id, account_id, transaction_type, amount, currency,
              payment_gateway, gateway_transaction_id, status, description, created_at)
           VALUES ($1, $2, 'charge', $3, $4, 'stripe', $5, 'completed', $6, NOW())`,
          [bookingId, parseInt(accountId, 10) || null, extra.unit_price, String(extra.currency || 'USD').toUpperCase(),
           session.payment_intent || session.id, `Add to stay · ${extra.name}`]
        );
        if (typeof syncBeds24PaymentItem === 'function') {
          Promise.resolve(syncBeds24PaymentItem(bookingId)).catch(e => console.warn('[add-to-stay webhook beds24]', e.message));
        }
        // Guest confirmation email — best effort.
        try {
          const bR = await pool.query(
            `SELECT b.guest_email, b.guest_first_name, p.account_id
               FROM bookings b JOIN properties p ON p.id = b.property_id
              WHERE b.id = $1`, [bookingId]);
          const bk = bR.rows[0];
          if (bk?.guest_email) {
            const cur = String(extra.currency || 'USD').toUpperCase();
            const amt = parseFloat(extra.unit_price).toFixed(2);
            sendEmail({
              to: bk.guest_email,
              subject: `Payment received: ${extra.name}`,
              html: `<div style="font-family:sans-serif;max-width:520px;">
                <h2>Thanks ${(bk.guest_first_name || 'there').replace(/[<>]/g, '')},</h2>
                <p>We've received your <strong>${cur} ${amt}</strong> payment for <strong>${extra.name.replace(/[<>]/g, '')}</strong>. It's now added to your stay.</p>
              </div>`,
              accountId: bk.account_id
            }).catch(() => {});
          }
        } catch (_) { /* nothing to do */ }
        return res.json({ received: true, add_to_stay_extra_id: extraId });
      }

      if (!orderId) { console.warn('[SHOP] No order ID in session metadata'); return res.json({ received: true }); }

      // Update order status
      const orderResult = await pool.query(
        `UPDATE shop_orders SET status = 'processing', payment_status = 'paid', stripe_payment_intent_id = $1, updated_at = NOW()
         WHERE id = $2 AND payment_status != 'paid' RETURNING *`,
        [session.payment_intent, orderId]
      );

      if (!orderResult.rows.length) {
        console.log('[SHOP] Order already processed or not found:', orderId);
        return res.json({ received: true });
      }
      const order = orderResult.rows[0];

      // Spark funnel: emit `purchased` event + back-fill contact_id on
      // every earlier event from this session so Marie sees the whole
      // journey on the contact's timeline. Best-effort; a failure here
      // never blocks fulfilment.
      try {
        if (order.spark_id) {
          // Match / create a contact for the buyer's email so we can
          // stitch the anonymous session's earlier events to a person.
          let contactId = null;
          if (order.customer_email) {
            const cR = await pool.query(
              `SELECT id FROM contacts WHERE account_id = $1 AND LOWER(email) = LOWER($2) LIMIT 1`,
              [accountId, order.customer_email]
            );
            if (cR.rows[0]) {
              contactId = cR.rows[0].id;
            } else {
              const nameParts = (order.customer_name || '').split(' ');
              const inserted = await pool.query(
                `INSERT INTO contacts (account_id, source, email, first_name, last_name, full_name)
                 VALUES ($1, 'shop', $2, $3, $4, $5) RETURNING id`,
                [accountId, order.customer_email.toLowerCase(), nameParts[0] || null, nameParts.slice(1).join(' ') || null, order.customer_name || null]
              );
              contactId = inserted.rows[0].id;
            }
          }
          // Back-fill contact_id on the whole session's earlier events.
          if (contactId && order.spark_session_id) {
            await pool.query(
              `UPDATE spark_events SET contact_id = $1
                 WHERE session_id = $2 AND account_id = $3 AND contact_id IS NULL`,
              [contactId, order.spark_session_id, accountId]
            );
          }
          // Emit the purchased event.
          await pool.query(
            `INSERT INTO spark_events (account_id, spark_id, event_type, session_id, contact_id, metadata)
             VALUES ($1, $2, 'purchased', $3, $4, $5::jsonb)`,
            [accountId, order.spark_id, order.spark_session_id, contactId,
             JSON.stringify({ order_id: order.id, order_number: order.order_number, total: parseFloat(order.total), currency: order.currency })]
          );
        }
      } catch (attrErr) {
        console.warn('[spark purchased attribution]', attrErr.message);
      }

      // Atomic inventory decrement
      const orderItems = await pool.query('SELECT * FROM shop_order_items WHERE order_id = $1', [orderId]);
      for (const item of orderItems.rows) {
        if (item.product_id) {
          await pool.query(
            `UPDATE shop_products SET stock_quantity = GREATEST(0, COALESCE(stock_quantity, 0) - $1), updated_at = NOW()
             WHERE id = $2 AND stock_tracking = true`,
            [item.quantity, item.product_id]
          );
        }
      }

      // Create booking if order has accommodation
      let shopBooking = null;
      const accomItem = orderItems.rows.find(i => i.accommodation_details);
      if (accomItem && accomItem.accommodation_details) {
        const ad = typeof accomItem.accommodation_details === 'string' ? JSON.parse(accomItem.accommodation_details) : accomItem.accommodation_details;
        const eventProduct = await pool.query('SELECT property_id, currency FROM shop_products WHERE id = $1', [accomItem.product_id]);
        const propertyId = eventProduct.rows[0]?.property_id;
        if (propertyId && ad.room_id && ad.check_in && ad.check_out) {
          try {
            const nameParts = (order.customer_name || '').split(' ');
            const firstName = nameParts[0] || 'Guest';
            const lastName = nameParts.slice(1).join(' ') || '';
            const bookingClient = await pool.connect();
            try {
              shopBooking = await createShopBooking(bookingClient, {
                propertyId, roomId: ad.room_id,
                arrivalDate: ad.check_in, departureDate: ad.check_out,
                numGuests: ad.guests || 2,
                guestFirstName: firstName, guestLastName: lastName,
                guestEmail: order.customer_email, guestPhone: order.customer_phone || '',
                roomPrice: ad.subtotal, currency: eventProduct.rows[0]?.currency || order.currency,
                shopOrderId: order.id
              });
              // Link booking to order
              await pool.query('UPDATE shop_orders SET booking_id = $1 WHERE id = $2', [shopBooking.id, order.id]);
              // Upgrade soft reservation blocks from 'pending_payment' to 'booking'
              await pool.query(
                "UPDATE room_availability SET source = 'booking' WHERE room_id = $1 AND date >= $2 AND date < $3 AND source = 'pending_payment'",
                [ad.room_id, ad.check_in, ad.check_out]
              );
              console.log('[SHOP] Booking created:', shopBooking.id, 'linked to order:', order.id);
            } finally {
              bookingClient.release();
            }
          } catch (bookingErr) {
            console.error('[SHOP] Error creating booking from order:', bookingErr.message);
          }
        }
      }

      // Get account info for emails
      const acc = await pool.query('SELECT name, email FROM accounts WHERE id = $1', [accountId]);
      const accountName = acc.rows[0]?.name || 'Shop';
      const operatorEmail = acc.rows[0]?.email;

      // Gift certificate fulfilment — for each line item whose product is a
      // gift_certificate, create a vouchers row with the paid amount as
      // initial+current balance, generate a unique code, and email the BUYER
      // a "ready to send" notification with a tokenised manage link. The buyer
      // chooses when to email the recipient (or to print the cert and hand it
      // over). The intended-recipient details from the buy form are pre-filled
      // on the manage page but not auto-fired.
      const buyerCerts = [];
      try {
        for (const item of orderItems.rows) {
          if (!item.product_id) continue;
          const prodRes = await pool.query(
            'SELECT id, product_type, currency, gift_expiry_months FROM shop_products WHERE id = $1',
            [item.product_id]
          );
          const prod = prodRes.rows[0];
          if (!prod || prod.product_type !== 'gift_certificate') continue;

          const meta = item.gift_metadata
            ? (typeof item.gift_metadata === 'string' ? JSON.parse(item.gift_metadata) : item.gift_metadata)
            : {};
          const recipientEmail = meta.recipient_email || null;
          const recipientName = meta.recipient_name || null;
          const senderName = meta.sender_name || order.customer_name || '';
          const senderEmail = order.customer_email;
          const messageText = meta.message || meta.recipient_message || '';
          const certCurrency = prod.currency || order.currency || 'EUR';
          const expiryMonths = prod.gift_expiry_months || 12;
          const expiresAt = expiryMonths > 0
            ? new Date(Date.now() + expiryMonths * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
            : null;

          const qty = parseInt(item.quantity) || 1;
          for (let i = 0; i < qty; i++) {
            const code = await generateUniqueGiftCode();
            const certName = `Gift Certificate — ${certCurrency} ${parseFloat(item.unit_price).toFixed(2)}`;
            const insRes = await pool.query(`
              INSERT INTO vouchers (
                user_id, code, name, voucher_type,
                discount_type, discount_value,
                initial_balance, current_balance, currency,
                recipient_name, recipient_email, recipient_message,
                sender_name, sender_email,
                expires_at, linked_shop_order_id,
                applies_to, max_uses, uses_count, active
              ) VALUES (
                $1, $2, $3, 'gift_certificate',
                'fixed', $4,
                $4, $4, $5,
                $6, $7, $8,
                $9, $10,
                $11, $12,
                'all', NULL, 0, true
              ) RETURNING id
            `, [
              accountId, code, certName,
              parseFloat(item.unit_price),
              certCurrency,
              recipientName, recipientEmail, messageText || null,
              senderName || null, senderEmail || null,
              expiresAt, order.id
            ]);
            buyerCerts.push({
              cert_id: insRes.rows[0].id,
              code,
              amount: parseFloat(item.unit_price),
              currency: certCurrency,
              expiresAt,
              recipientEmail, recipientName, senderName, message: messageText
            });
          }
        }

        // One email to the buyer summarising every certificate purchased, each
        // with a manage-page link (signed token) where they can preview, print,
        // or send to the recipient.
        if (buyerCerts.length > 0) {
          const certBlocks = await Promise.all(buyerCerts.map(async (c) => {
            const token = signGiftCertToken(c.cert_id, order.customer_email);
            const manageUrl = `https://admin.gas.travel/api/public/gift-cert/${encodeURIComponent(c.code)}?token=${token}`;
            const qrDataUrl = await QRCode.toDataURL(manageUrl, { width: 160, margin: 1 });
            return `
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px;margin-bottom:16px">
                <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px">
                  <div>
                    <p style="margin:0 0 4px;color:#64748b;font-size:12px;letter-spacing:1px;text-transform:uppercase">Gift Certificate</p>
                    <p style="margin:0 0 8px;font-size:22px;font-weight:700;color:#047857">${c.currency} ${c.amount.toFixed(2)}</p>
                    <p style="margin:0 0 4px;font-family:'SFMono-Regular',Consolas,monospace;font-size:14px;letter-spacing:1.5px;color:#1e293b">${c.code}</p>
                    ${c.recipientName ? `<p style="margin:8px 0 0;font-size:13px;color:#475569">For: ${c.recipientName}${c.recipientEmail ? ` &lt;${c.recipientEmail}&gt;` : ''}</p>` : ''}
                    ${c.expiresAt ? `<p style="margin:4px 0 0;font-size:12px;color:#94a3b8">Valid until ${new Date(c.expiresAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</p>` : ''}
                  </div>
                  <img src="${qrDataUrl}" alt="QR" style="width:90px;height:90px;flex-shrink:0">
                </div>
                <div style="margin-top:14px;text-align:center">
                  <a href="${manageUrl}" style="display:inline-block;padding:10px 20px;background:#10b981;color:#fff;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px">View, Print, or Send</a>
                </div>
              </div>`;
          }));

          const buyerHtml = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:'Segoe UI',Arial,sans-serif;color:#334155;max-width:600px;margin:0 auto;padding:20px;background:#f8fafc">
            <div style="background:#fff;border-radius:16px;padding:24px;margin-bottom:16px">
              <h1 style="margin:0 0 8px;color:#047857;font-size:22px">Your gift ${buyerCerts.length > 1 ? 'certificates are' : 'certificate is'} ready</h1>
              <p style="margin:0;color:#64748b;font-size:14px">Order ${order.order_number} · ${accountName}</p>
            </div>
            ${certBlocks.join('')}
            <p style="text-align:center;color:#64748b;font-size:13px;margin:20px 0 0">Click <strong>View, Print, or Send</strong> to preview the certificate, print it, or email it to the recipient when you're ready.</p>
          </body></html>`;

          try {
            await sendEmail({
              to: order.customer_email,
              subject: `Your gift ${buyerCerts.length > 1 ? 'certificates' : 'certificate'} from ${accountName}`,
              html: buyerHtml,
              replyTo: operatorEmail || undefined
            });
            console.log('[SHOP] Gift cert buyer email sent — certs:', buyerCerts.length);
          } catch (mailErr) {
            console.error('[SHOP] Gift cert buyer email failed:', mailErr.message);
          }
        }
      } catch (giftErr) {
        console.error('[SHOP] Gift certificate fulfilment failed:', giftErr.message);
      }

      const curr = order.currency || 'EUR';
      const itemsHtml = orderItems.rows.map(i =>
        `<tr><td style="padding:8px 12px;border-bottom:1px solid #e2e8f0">${i.product_name}</td>` +
        `<td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;text-align:center">${i.quantity}</td>` +
        `<td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;text-align:right">${curr} ${parseFloat(i.unit_price).toFixed(2)}</td>` +
        `<td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;text-align:right">${curr} ${parseFloat(i.total).toFixed(2)}</td></tr>`
      ).join('');

      // Customer confirmation email
      const customerHtml = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:'Segoe UI',Arial,sans-serif;color:#334155;max-width:600px;margin:0 auto;padding:20px">
        <div style="text-align:center;padding:24px 0;border-bottom:3px solid #10b981">
          <h1 style="margin:0;color:#10b981;font-size:24px">Order Confirmed</h1>
          <p style="margin:8px 0 0;color:#64748b">Thank you for your purchase!</p>
        </div>
        <div style="padding:24px 0">
          <p style="margin:0 0 4px"><strong>Order:</strong> ${order.order_number}</p>
          <p style="margin:0 0 4px"><strong>Date:</strong> ${new Date(order.created_at).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
          <p style="margin:0 0 16px"><strong>Name:</strong> ${order.customer_name || order.customer_email}</p>
          <table style="width:100%;border-collapse:collapse;margin-bottom:16px">
            <thead><tr style="background:#f8fafc">
              <th style="padding:8px 12px;text-align:left;font-size:12px;text-transform:uppercase;color:#64748b">Product</th>
              <th style="padding:8px 12px;text-align:center;font-size:12px;text-transform:uppercase;color:#64748b">Qty</th>
              <th style="padding:8px 12px;text-align:right;font-size:12px;text-transform:uppercase;color:#64748b">Price</th>
              <th style="padding:8px 12px;text-align:right;font-size:12px;text-transform:uppercase;color:#64748b">Total</th>
            </tr></thead>
            <tbody>${itemsHtml}</tbody>
          </table>
          <div style="text-align:right;padding:12px;background:#f0fdf4;border-radius:8px">
            <span style="font-size:1.2rem;font-weight:700;color:#10b981">${curr} ${parseFloat(order.total).toFixed(2)}</span>
          </div>
          ${shopBooking ? `
          <div style="margin-top:24px;padding:16px;background:#eff6ff;border-radius:8px;border:1px solid #bfdbfe">
            <h3 style="margin:0 0 8px;color:#1d4ed8;font-size:16px">Accommodation Booking</h3>
            <p style="margin:0 0 4px"><strong>Booking Ref:</strong> GAS-${shopBooking.id}</p>
            <p style="margin:0 0 4px"><strong>Room:</strong> ${accomItem.accommodation_details?.room_name || 'Room'}</p>
            <p style="margin:0 0 4px"><strong>Check-in:</strong> ${new Date(shopBooking.arrival_date).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
            <p style="margin:0 0 4px"><strong>Check-out:</strong> ${new Date(shopBooking.departure_date).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
          </div>` : ''}
        </div>
        <div style="padding:16px 0;border-top:1px solid #e5e7eb;text-align:center;color:#94a3b8;font-size:12px">
          <p>${accountName}</p>
        </div>
      </body></html>`;

      await sendEmail({
        to: order.customer_email,
        subject: `Order Confirmation ${order.order_number} — ${accountName}`,
        html: customerHtml
      });

      // Operator notification email
      if (operatorEmail) {
        const operatorHtml = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:'Segoe UI',Arial,sans-serif;color:#334155;max-width:600px;margin:0 auto;padding:20px">
          <div style="text-align:center;padding:24px 0;border-bottom:3px solid #3b82f6">
            <h1 style="margin:0;color:#3b82f6;font-size:24px">New Shop Order</h1>
            <p style="margin:8px 0 0;color:#64748b">${order.order_number}</p>
          </div>
          <div style="padding:24px 0">
            <p><strong>Customer:</strong> ${order.customer_name || '-'} (${order.customer_email})</p>
            ${order.customer_phone ? `<p><strong>Phone:</strong> ${order.customer_phone}</p>` : ''}
            <p><strong>Total:</strong> ${curr} ${parseFloat(order.total).toFixed(2)}</p>
            <table style="width:100%;border-collapse:collapse;margin:16px 0">
              <thead><tr style="background:#f8fafc">
                <th style="padding:8px 12px;text-align:left;font-size:12px;text-transform:uppercase;color:#64748b">Product</th>
                <th style="padding:8px 12px;text-align:center;font-size:12px">Qty</th>
                <th style="padding:8px 12px;text-align:right;font-size:12px">Total</th>
              </tr></thead>
              <tbody>${orderItems.rows.map(i =>
                `<tr><td style="padding:8px 12px;border-bottom:1px solid #e2e8f0">${i.product_name}</td>` +
                `<td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;text-align:center">${i.quantity}</td>` +
                `<td style="padding:8px 12px;border-bottom:1px solid #e2e8f0;text-align:right">${curr} ${parseFloat(i.total).toFixed(2)}</td></tr>`
              ).join('')}</tbody>
            </table>
            <p style="text-align:center;margin-top:24px"><a href="https://admin.gas.travel/gas-admin.html" style="display:inline-block;padding:10px 24px;background:#3b82f6;color:#fff;border-radius:20px;text-decoration:none">View in GAS Admin</a></p>
          </div>
        </body></html>`;

        await sendEmail({
          to: operatorEmail,
          subject: `New Order ${order.order_number} — ${curr} ${parseFloat(order.total).toFixed(2)}`,
          html: operatorHtml
        });
      }

      console.log('[SHOP] Order paid and emails sent:', order.order_number);
    }

    if (event.type === 'checkout.session.expired') {
      const session = event.data.object;
      const orderId = session.metadata?.gas_order_id;
      if (orderId) {
        // Cancel the order
        await pool.query(
          "UPDATE shop_orders SET status = 'cancelled', payment_status = 'expired', updated_at = NOW() WHERE id = $1 AND payment_status = 'unpaid'",
          [orderId]
        );
        // Unblock soft reservations — release room_availability rows marked as pending_payment
        const expiredItems = await pool.query('SELECT * FROM shop_order_items WHERE order_id = $1', [orderId]);
        for (const item of expiredItems.rows) {
          if (item.accommodation_details) {
            const ad = typeof item.accommodation_details === 'string' ? JSON.parse(item.accommodation_details) : item.accommodation_details;
            if (ad.room_id && ad.check_in && ad.check_out) {
              await pool.query(
                "DELETE FROM room_availability WHERE room_id = $1 AND date >= $2 AND date < $3 AND source = 'pending_payment'",
                [ad.room_id, ad.check_in, ad.check_out]
              );
              console.log('[SHOP] Released soft reservation for room', ad.room_id, 'dates', ad.check_in, '-', ad.check_out);
            }
          }
        }
        console.log('[SHOP] Checkout expired, order cancelled:', orderId);
      }
    }

    res.json({ received: true });
  } catch (error) {
    console.error('[SHOP] Webhook error:', error);
    res.status(400).json({ error: error.message });
  }
});

console.log('✅ Shop ecommerce endpoints loaded (inc. checkout + webhook)');

// ═══════════════════════════════════════════════════════════════════════
// BIKE STORAGE — Stripe webhook (C.4 of the TTLock build)
//
// Each operator running bike storage registers
//   https://admin.gas.travel/api/webhooks/stripe-bike-storage
// in their own Stripe dashboard. On checkout.session.completed for a
// session with metadata.gas_kind='bike_storage' we flip the booking row
// from pending → confirmed + paid + stamp the payment ids, then send a
// confirmation email. Phase D will hang TTLock period-passcode
// generation off the SAME hook so the access code is in the guest's
// inbox by the time they walk to the cabinet.
//
// Idempotent: re-firing the same event is a no-op because the UPDATE
// only matches `payment_status != 'paid'`.
// ═══════════════════════════════════════════════════════════════════════
app.post('/api/webhooks/stripe-bike-storage', express.raw({ type: 'application/json' }), async (req, res) => {
  try {
    const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY || 'sk_test_dummy');
    const webhookSecret = process.env.STRIPE_BIKE_STORAGE_WEBHOOK_SECRET;
    let event;
    if (webhookSecret) {
      const sig = req.headers['stripe-signature'];
      const rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.from(req.body);
      event = stripe.webhooks.constructEvent(rawBody, sig, webhookSecret);
    } else {
      console.warn('[BIKE-STORAGE] WARNING: STRIPE_BIKE_STORAGE_WEBHOOK_SECRET not set — skipping signature verification');
      event = JSON.parse(Buffer.isBuffer(req.body) ? req.body.toString('utf8') : req.body);
    }
    console.log('[BIKE-STORAGE] Webhook event:', event.type);

    if (event.type !== 'checkout.session.completed') {
      // We only care about completed sessions for now. Other event types
      // (payment_intent.failed etc.) can be added later when the UX needs
      // them — today the booking row just stays 'pending' until a paid
      // event lands or the cleanup cron expires it.
      return res.json({ received: true });
    }

    const session = event.data.object;
    // gas_kind covers both 'bike_storage' (Flow A standalone) and
    // 'bike_storage_linked' (Flow C standalone-attached-to-existing-
    // booking). Both go through this same webhook + mint passcodes.
    if (!['bike_storage', 'bike_storage_linked'].includes(session.metadata?.gas_kind)) {
      // Not ours — could be a shop / room booking using the same Stripe
      // account. Acknowledge so Stripe doesn't retry, but don't touch the
      // booking row.
      return res.json({ received: true, skipped: 'not bike_storage' });
    }
    // Multi-cabinet: gas_booking_ids is a comma-separated list of all
    // bookings created in the same session. Fall back to gas_booking_id
    // for any older session that pre-dated the multi-cabinet rollout.
    const idsRaw = session.metadata?.gas_booking_ids || session.metadata?.gas_booking_id || '';
    const bookingIdsAll = String(idsRaw).split(',').map(s => parseInt(s.trim())).filter(Boolean);
    if (!bookingIdsAll.length) {
      console.warn('[BIKE-STORAGE] No gas_booking_id(s) in session metadata');
      return res.json({ received: true });
    }
    const bookingId = bookingIdsAll[0]; // primary, for logs + email subject

    // Atomic transition pending → confirmed across ALL bookings in this
    // session. The `payment_status != 'paid'` guard makes retries safe.
    const updated = await pool.query(
      `UPDATE bookings
         SET status = 'confirmed',
             payment_status = 'paid',
             stripe_payment_intent_id = $1,
             stripe_charge_id = $2,
             confirmed_time = NOW(),
             updated_at = NOW()
       WHERE id = ANY($3::int[]) AND payment_status != 'paid'
       RETURNING id, property_id, bookable_unit_id, arrival_date, departure_date,
                 nights_count, total_amount, currency,
                 guest_first_name, guest_last_name, guest_email`,
      [session.payment_intent || null, session.id || null, bookingIdsAll]
    );
    if (!updated.rows.length) {
      console.log('[BIKE-STORAGE] Bookings already paid or not found:', bookingIdsAll.join(','));
      return res.json({ received: true });
    }
    const b = updated.rows[0]; // primary used for email metadata
    const allBookings = updated.rows;
    // bookings has no account_id column — resolve via property.
    const acctRow = await pool.query(`SELECT account_id FROM properties WHERE id = $1`, [b.property_id]);
    b.account_id = acctRow.rows[0]?.account_id || null;

    // Pull every allocated cabinet's info for the consolidated email.
    const unitInfo = await pool.query(
      `SELECT bu.id, bu.name AS unit_name, bu.ttlock_lock_id, p.name AS property_name
         FROM bookable_units bu
         JOIN properties p ON p.id = bu.property_id
        WHERE bu.id = ANY($1::int[])`,
      [allBookings.map(x => x.bookable_unit_id)]
    );
    const unitsByBookable = new Map(unitInfo.rows.map(u => [u.id, u]));
    const unit = unitsByBookable.get(b.bookable_unit_id); // primary, used downstream

    // One consolidated confirmation email covering all allocated cabinets.
    // Code emails follow per-cabinet via the helper below so each cabinet
    // has its own forwardable confirmation (useful for the "+ a friend"
    // multi-cabinet case — guest forwards the right code to the right person).
    const symbol = (b.currency === 'GBP') ? '£' : (b.currency === 'EUR' ? '€' : (b.currency === 'USD' ? '$' : ''));
    const totalPaidAll = allBookings.reduce((s, x) => s + parseFloat(x.total_amount || 0), 0);
    const cabinetsRows = allBookings.map(x => {
      const u = unitsByBookable.get(x.bookable_unit_id);
      return `<div><strong>${u?.unit_name || 'Cabinet'}:</strong> ${x.arrival_date instanceof Date ? x.arrival_date.toISOString().slice(0,10) : x.arrival_date} → ${x.departure_date instanceof Date ? x.departure_date.toISOString().slice(0,10) : x.departure_date}</div>`;
    }).join('');
    try {
      await sendEmail({
        to: [b.guest_email],
        accountId: b.account_id,
        subject: allBookings.length > 1
          ? `Your ${allBookings.length} bike storage cabinets at ${unit?.property_name || 'the hostel'} are confirmed`
          : `Your bike storage at ${unit?.property_name || 'the hostel'} is confirmed`,
        html: `
          <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#1e293b;">
            <h2 style="margin:0 0 16px;color:#0f172a;">✓ Booking confirmed</h2>
            <p style="line-height:1.6;">Hi ${b.guest_first_name || 'there'},</p>
            <p style="line-height:1.6;">Your bike storage at <strong>${unit?.property_name || ''}</strong> is reserved.</p>
            <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;margin:20px 0;">
              ${cabinetsRows}
              <div style="margin-top:8px;color:#64748b;font-size:0.9rem;">Pickup from 10:00 · return by 18:00</div>
              <div style="margin-top:8px;"><strong>Total paid:</strong> ${symbol}${totalPaidAll.toFixed(2)} ${b.currency}</div>
            </div>
            <p style="line-height:1.6;">Your <strong>individual access code${allBookings.length > 1 ? 's' : ''}</strong> will arrive in ${allBookings.length > 1 ? 'separate emails' : 'a separate email'} shortly. Each code works for the whole rental window and stops working automatically afterwards.</p>
            <p style="line-height:1.6;color:#64748b;font-size:0.9rem;margin-top:24px;">A reminder that bikes are stored at your own risk. The cabinets are CCTV-monitored and each has electric points for charging e-bikes — please don't bring bikes or chargers inside the hostel.</p>
          </div>
        `
      });
      console.log('[BIKE-STORAGE] Consolidated confirmation email sent for', allBookings.length, 'booking(s) primary', bookingId);
    } catch (emailErr) {
      // Don't fail the webhook — Stripe would retry and we don't want
      // to flip the booking again. Just log so the operator can resend.
      console.error('[BIKE-STORAGE] Confirmation email failed:', emailErr.message);
    }

    // Phase D — TTLock period passcode generation. Loop over every booking
    // in this session and mint a code per cabinet. Helper handles its own
    // error paths: missing lock pairing, TTLock API failure, owner-notify
    // emails. None of these failure modes failure the webhook.
    for (const ab of allBookings) {
      try {
        await _mintBikeStoragePasscodeForBooking(ab.id);
      } catch (passErr) {
        console.error('[BIKE-STORAGE] Passcode loop crashed for booking', ab.id, '—', passErr.message);
        await pool.query(
          `UPDATE bookings SET sync_errors = COALESCE(sync_errors, '') || $1, updated_at = NOW() WHERE id = $2`,
          [`[ttlock] passcode loop error: ${passErr.message.slice(0, 200)}\n`, ab.id]
        ).catch(() => {});
      }
    }

    res.json({ received: true, booking_ids: bookingIdsAll });
  } catch (e) {
    console.error('[BIKE-STORAGE] Webhook error:', e.message);
    res.status(400).json({ error: e.message });
  }
});

console.log('✅ Bike storage Stripe webhook loaded');

// Shared helper: given a bike_storage booking id, mint the TTLock period
// passcode, stamp it on the booking, email the guest the code, and notify
// the owner on failure. Used by the upsell-spawned companion path (where
// the parent booking's payment flow handles Stripe, so the standalone
// bike-storage webhook never fires). The standalone webhook keeps its
// own inline mint block for now — same logic, separate copy.
async function _mintBikeStoragePasscodeForBooking(bookingId) {
  try {
    const bRow = await pool.query(
      `SELECT b.id, b.bookable_unit_id, b.arrival_date, b.departure_date,
              b.guest_first_name, b.guest_last_name, b.guest_email,
              b.access_code, b.property_id,
              bu.name AS unit_name, bu.ttlock_lock_id,
              p.name AS property_name, p.timezone, p.account_id
         FROM bookings b
         JOIN bookable_units bu ON bu.id = b.bookable_unit_id
         JOIN properties p ON p.id = b.property_id
        WHERE b.id = $1`,
      [bookingId]
    );
    const b = bRow.rows[0];
    if (!b) {
      console.warn('[BIKE-STORAGE helper] booking not found:', bookingId);
      return { ok: false, error: 'booking not found' };
    }
    if (b.access_code) {
      console.log('[BIKE-STORAGE helper] booking', bookingId, 'already has access_code, skipping');
      return { ok: true, skipped: 'already minted' };
    }
    if (!b.ttlock_lock_id) {
      console.warn('[BIKE-STORAGE helper] booking', bookingId, 'unit', b.bookable_unit_id, 'has no ttlock_lock_id — manual handover');
      await pool.query(
        `UPDATE bookings SET sync_errors = COALESCE(sync_errors, '') || $1, updated_at = NOW() WHERE id = $2`,
        [`[ttlock] no lock paired on unit — manual handover required\n`, bookingId]
      ).catch(() => {});
      return { ok: false, error: 'no lock paired' };
    }

    const tz = b.timezone || 'UTC';
    function tzLocalToUtcMs(yyyyMmDd, hhmm) {
      const naive = new Date(`${yyyyMmDd}T${hhmm}:00Z`).getTime();
      const tzString = new Date(naive).toLocaleString('en-US', { timeZone: tz, hour12: false });
      const tzDate = new Date(tzString);
      const offset = tzDate.getTime() - naive;
      return naive - offset;
    }
    const arr = b.arrival_date instanceof Date
      ? b.arrival_date.toISOString().slice(0, 10)
      : String(b.arrival_date).slice(0, 10);
    const dep = b.departure_date instanceof Date
      ? b.departure_date.toISOString().slice(0, 10)
      : String(b.departure_date).slice(0, 10);
    const startTime = tzLocalToUtcMs(arr, '10:00');
    const endTime = tzLocalToUtcMs(dep, '18:00');

    const result = await createTTLockPeriodPasscode({
      accountId: b.account_id,
      lockId: b.ttlock_lock_id,
      startTime, endTime,
      name: `${b.guest_first_name || 'Guest'} ${b.guest_last_name || ''} (#${bookingId})`,
    });

    if (!result.ok) {
      console.error('[BIKE-STORAGE helper] Passcode mint failed for booking', bookingId, '—', result.error);
      await pool.query(
        `UPDATE bookings SET sync_errors = COALESCE(sync_errors, '') || $1, updated_at = NOW() WHERE id = $2`,
        [`[ttlock] passcode mint failed: ${result.error}\n`, bookingId]
      ).catch(() => {});
      const ownerRow = await pool.query(`SELECT email FROM accounts WHERE id = $1`, [b.account_id]);
      const ownerEmail = ownerRow.rows[0]?.email;
      if (ownerEmail) {
        try {
          await sendEmail({
            to: [ownerEmail, 'development@gas.travel'],
            accountId: b.account_id,
            subject: `⚠️ Bike storage code needed — ${b.unit_name} (booking #${bookingId})`,
            html: `<p>Automatic TTLock passcode mint failed for booking #${bookingId}.</p>
                   <p>Guest: ${b.guest_first_name || ''} ${b.guest_last_name || ''} (${b.guest_email})<br>
                   Cabinet: ${b.unit_name} (lock ID ${b.ttlock_lock_id})<br>
                   From: ${arr} 10:00 — Until: ${dep} 18:00</p>
                   <p>Please mint a code in the TTLock app and email the guest.</p>
                   <p style="color:#991b1b;">Error: ${result.error}</p>`
          });
        } catch (notifyErr) {
          console.error('[BIKE-STORAGE helper] Owner notification failed:', notifyErr.message);
        }
      }
      return result;
    }

    await pool.query(
      `UPDATE bookings SET access_code = $1, updated_at = NOW() WHERE id = $2`,
      [result.keyboardPwd, bookingId]
    );
    console.log('[BIKE-STORAGE helper] Passcode minted for booking', bookingId);

    // CRM trigger — if the account has an active bike_storage.code_minted
    // workflow, let it own the guest email (custom copy, merge fields, per-
    // account branding). Only fall back to the hardcoded default below when
    // no workflow is bound, so no client ever misses the code while they're
    // still building their template. Never both — one code = one email.
    let workflowHandled = false;
    try {
      const wfR = await pool.query(
        `SELECT 1 FROM workflows
          WHERE account_id = $1 AND source = 'gas' AND is_active = true
            AND trigger_type = 'bike_storage.code_minted'
          LIMIT 1`,
        [b.account_id]
      );
      if (wfR.rows.length) {
        const contactId = await _resolveOrCreateContactForGuest(b.account_id, {
          guest_email:      b.guest_email,
          guest_first_name: b.guest_first_name,
          guest_last_name:  b.guest_last_name,
        });
        if (contactId) {
          await emitRecipeEvent(b.account_id, 'bike_storage.code_minted', {
            contact_id: contactId,
            booking_id: bookingId,
          });
          workflowHandled = true;
          console.log('[BIKE-STORAGE helper] CRM workflow fired for booking', bookingId);
        } else {
          console.warn('[BIKE-STORAGE helper] Contact resolve failed for booking', bookingId, '— falling back to default email');
        }
      }
    } catch (wfErr) {
      console.error('[BIKE-STORAGE helper] Workflow dispatch failed for booking', bookingId, '—', wfErr.message, '— falling back to default email');
    }

    const fmtUk = (s) => {
      try {
        const d = new Date(s + 'T00:00:00Z');
        return d.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
      } catch (_) { return s; }
    };
    if (!workflowHandled) try {
      await sendEmail({
        to: [b.guest_email],
        accountId: b.account_id,
        subject: `Your bike storage access code — ${b.unit_name}`,
        html: `
          <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#1e293b;">
            <h2 style="margin:0 0 16px;color:#0f172a;">🔐 Your access code</h2>
            <p>Hi ${b.guest_first_name || 'there'},</p>
            <p>Here's the code for <strong>${b.unit_name}</strong> at <strong>${b.property_name || ''}</strong>:</p>
            <div style="background:#f8fafc;border:2px solid #10b981;border-radius:12px;padding:24px;margin:20px 0;text-align:center;">
              <div style="font-family:'SF Mono',monospace;font-size:2.4rem;font-weight:700;letter-spacing:0.15em;">${result.keyboardPwd}</div>
              <div style="font-size:0.85rem;color:#64748b;margin-top:8px;">Punch this into the cabinet keypad</div>
            </div>
            <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;margin:16px 0;">
              <div><strong>Valid from:</strong> ${fmtUk(arr)} 10:00</div>
              <div><strong>Valid until:</strong> ${fmtUk(dep)} 18:00</div>
            </div>
            <p style="font-size:0.9rem;color:#64748b;">The code stops working automatically at the end of your rental window.</p>
          </div>
        `
      });
    } catch (emailErr) {
      console.error('[BIKE-STORAGE helper] Passcode email failed:', emailErr.message);
    }
    return result;
  } catch (e) {
    console.error('[BIKE-STORAGE helper] crashed for booking', bookingId, '—', e.message);
    await pool.query(
      `UPDATE bookings SET sync_errors = COALESCE(sync_errors, '') || $1, updated_at = NOW() WHERE id = $2`,
      [`[ttlock] helper error: ${e.message.slice(0, 200)}\n`, bookingId]
    ).catch(() => {});
    return { ok: false, error: e.message };
  }
}

// Admin helper for the Pro Builder "Bike Storage Booking" App. Returns
// properties under the caller's account that have at least one
// unit_role='bike_storage' bookable_unit configured. The Pro Builder
// property picker uses this so operators can only pick properties where
// the feature is actually set up — no dead links.
app.get('/api/admin/bike-storage/properties', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const accountId = parseInt(req.query.account_id) || decoded.accountId || decoded.id;
    const r = await pool.query(
      `SELECT p.id, p.name, COUNT(bu.id)::int AS unit_count
       FROM properties p
       JOIN bookable_units bu ON bu.property_id = p.id
       WHERE p.account_id = $1
         AND bu.unit_role = 'bike_storage'
         AND bu.status = 'available'
       GROUP BY p.id, p.name
       ORDER BY p.name`,
      [accountId]
    );
    res.json({ success: true, properties: r.rows });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// Pro Builder upgrade application — operator on standard tier clicks
// the "🎨 Edit Pro Builder" button on a deployed site, sees an
// explanation modal, submits the application. Notifies the GAS team
// via the master inbox so we can follow up. No DB table yet — the
// inbox row IS the audit trail.
app.post('/api/admin/pro-builder/apply', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const { deployed_site_id, current_tier, note } = req.body || {};
    if (!deployed_site_id) return res.status(400).json({ success: false, error: 'deployed_site_id required' });
    const site = (await pool.query(
      `SELECT ds.id, ds.site_url, ds.site_name, ds.slug, ds.subscription_tier,
              a.id AS account_id, a.name AS account_name, a.email AS account_email
       FROM deployed_sites ds
       LEFT JOIN accounts a ON a.id = ds.account_id
       WHERE ds.id = $1`,
      [parseInt(deployed_site_id)]
    )).rows[0];
    if (!site) return res.status(404).json({ success: false, error: 'Site not found' });
    // Honour scope — caller must own the site or be master_admin
    if (site.account_id !== (decoded.accountId || decoded.id) && decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Not your site' });
    }
    await sendMasterNotification({
      title: `Pro Builder application — ${site.site_name || site.slug}`,
      severity: 'info',
      body:
        `Account: ${site.account_name || ('#' + site.account_id)} (${site.account_email || 'no email'})\n` +
        `Site: ${site.site_url}\n` +
        `Current tier: ${current_tier || site.subscription_tier || 'standard'}\n` +
        (note ? `\nOperator note:\n${note}\n` : '') +
        `\nFollow up with the operator to discuss Pro Builder + Instant Website Pro pricing.`,
      metadata: {
        kind: 'pro_builder_application',
        deployed_site_id: site.id,
        account_id: site.account_id,
        current_tier: current_tier || site.subscription_tier || 'standard',
      }
    });
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// ═══════════════════════════════════════════════════════════════════════
// SMART LOCKS — admin helpers powering Apps → Smart Locks page.
// Multi-vendor framing (provider field on every endpoint) so RemoteLock /
// future vendors slot in without re-shaping these routes.
//
// Endpoints:
//   GET  /api/admin/smart-locks/pairings        list all paired bookable_units for the account
//   GET  /api/admin/smart-locks/properties      list account's properties (for the pair-modal property picker)
//   GET  /api/admin/smart-locks/units           list bookable_units on a property (for the pair-modal unit picker)
//   POST /api/admin/smart-locks/pair            attach a lock to a bookable_unit
//   POST /api/admin/smart-locks/test-code       mint a short-lived passcode for physical verification
// ═══════════════════════════════════════════════════════════════════════

// All paired locks across the account, with bookable_unit + property name
// so the UI can show "Lock bikeShedLock_3 → Bike Shed Store 3 (IOU Hebden)".
app.get('/api/admin/smart-locks/pairings', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const accountId = parseInt(req.query.account_id) || decoded.accountId || decoded.id;
    const r = await pool.query(
      `SELECT bu.id AS bookable_unit_id, bu.name AS unit_name,
              bu.ttlock_lock_id, bu.remotelock_device_id,
              bu.unit_role,
              p.id AS property_id, p.name AS property_name,
              CASE
                WHEN bu.ttlock_lock_id IS NOT NULL THEN 'ttlock'
                WHEN bu.remotelock_device_id IS NOT NULL THEN 'remotelock'
              END AS provider,
              COALESCE(bu.ttlock_lock_id::text, bu.remotelock_device_id) AS lock_id
       FROM bookable_units bu
       JOIN properties p ON p.id = bu.property_id
       WHERE p.account_id = $1
         AND (bu.ttlock_lock_id IS NOT NULL OR bu.remotelock_device_id IS NOT NULL)
       ORDER BY p.name, bu.name`,
      [accountId]
    );
    res.json({ success: true, pairings: r.rows });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// All properties on the account — used by pair modal's property dropdown.
app.get('/api/admin/smart-locks/properties', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const accountId = parseInt(req.query.account_id) || decoded.accountId || decoded.id;
    const r = await pool.query(
      `SELECT id, name FROM properties WHERE account_id = $1 ORDER BY name`,
      [accountId]
    );
    res.json({ success: true, properties: r.rows });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// All bookable_units on a property — used by pair modal's unit dropdown.
// Includes the current ttlock_lock_id (if any) so the UI can flag "this
// unit already has a lock paired — picking will replace it".
app.get('/api/admin/smart-locks/units', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const propertyId = parseInt(req.query.property_id);
    if (!propertyId) return res.status(400).json({ success: false, error: 'property_id required' });
    // Verify the property belongs to the caller's account
    const own = await pool.query(
      `SELECT 1 FROM properties WHERE id = $1 AND account_id = $2`,
      [propertyId, decoded.accountId || decoded.id]
    );
    // Master admin can read any property
    if (!own.rows.length && decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Not your property' });
    }
    const r = await pool.query(
      `SELECT id, name, unit_role, ttlock_lock_id, remotelock_device_id
       FROM bookable_units
       WHERE property_id = $1
       ORDER BY name`,
      [propertyId]
    );
    res.json({ success: true, units: r.rows });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET the access-code policy for a property (defaults to 'remotelock_random'
// when the column is NULL — safe fallback for pre-Phase-2 properties).
app.get('/api/admin/properties/:id/access-code-policy', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const r = await pool.query('SELECT access_code_policy FROM properties WHERE id = $1', [parseInt(req.params.id, 10)]);
    if (!r.rows[0]) return res.status(404).json({ success: false, error: 'Property not found' });
    res.json({ success: true, policy: r.rows[0].access_code_policy || 'remotelock_random' });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});
// PUT to set the policy. Body: { policy: 'remotelock_random'|'phone_last4'|'manual' }
app.put('/api/admin/properties/:id/access-code-policy', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const { policy } = req.body || {};
    const allowed = ['remotelock_random', 'phone_last4', 'manual'];
    if (!allowed.includes(policy)) {
      return res.status(400).json({ success: false, error: 'policy must be one of ' + allowed.join(', ') });
    }
    const own = await pool.query('SELECT account_id FROM properties WHERE id = $1', [parseInt(req.params.id, 10)]);
    if (!own.rows[0]) return res.status(404).json({ success: false, error: 'Property not found' });
    if (own.rows[0].account_id !== (decoded.accountId || decoded.id) && decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Not your property' });
    }
    await pool.query('UPDATE properties SET access_code_policy = $1 WHERE id = $2', [policy, parseInt(req.params.id, 10)]);
    res.json({ success: true });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

// Pair a lock to a bookable_unit. Writes bookable_units.ttlock_lock_id
// (BIGINT) or bookable_units.remotelock_device_id (VARCHAR, UUID-style)
// depending on provider. Each physical lock lives on exactly one unit,
// so we detach the same lock id from any other row before writing.
app.post('/api/admin/smart-locks/pair', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const { provider, lock_id, bookable_unit_id } = req.body || {};
    if (!provider || !lock_id || !bookable_unit_id) {
      return res.status(400).json({ success: false, error: 'provider, lock_id, bookable_unit_id required' });
    }
    if (!['ttlock', 'remotelock'].includes(provider)) {
      return res.status(400).json({ success: false, error: `Provider '${provider}' not yet supported` });
    }
    // Verify the unit belongs to the caller's account
    const ownRow = await pool.query(
      `SELECT bu.id, p.account_id
       FROM bookable_units bu
       JOIN properties p ON p.id = bu.property_id
       WHERE bu.id = $1`,
      [parseInt(bookable_unit_id)]
    );
    if (!ownRow.rows.length) return res.status(404).json({ success: false, error: 'Unit not found' });
    const ownerAccountId = ownRow.rows[0].account_id;
    if (ownerAccountId !== (decoded.accountId || decoded.id) && decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Not your unit' });
    }
    if (provider === 'ttlock') {
      // Detach from any other unit first (see comment above).
      await pool.query(
        `UPDATE bookable_units SET ttlock_lock_id = NULL, updated_at = NOW()
         WHERE ttlock_lock_id = $1 AND id != $2`,
        [parseInt(lock_id), parseInt(bookable_unit_id)]
      );
      await pool.query(
        `UPDATE bookable_units SET ttlock_lock_id = $1, updated_at = NOW() WHERE id = $2`,
        [parseInt(lock_id), parseInt(bookable_unit_id)]
      );
    } else {
      // remotelock — lock_id is RemoteLock's device UUID (stringly typed)
      const deviceId = String(lock_id);
      await pool.query(
        `UPDATE bookable_units SET remotelock_device_id = NULL, updated_at = NOW()
         WHERE remotelock_device_id = $1 AND id != $2`,
        [deviceId, parseInt(bookable_unit_id)]
      );
      await pool.query(
        `UPDATE bookable_units SET remotelock_device_id = $1, updated_at = NOW() WHERE id = $2`,
        [deviceId, parseInt(bookable_unit_id)]
      );
    }
    res.json({ success: true });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// Mint a short-lived passcode the operator can punch into the physical
// lock to verify wiring. Same primitive whichever provider is used —
// dispatches on `provider` so a single UI button can cover TTLock +
// RemoteLock (and any future adapter).
app.post('/api/admin/smart-locks/test-code', async (req, res) => {
  try {
    const user = await authenticateUser(req, res); if (!user) return;
    const { provider, lock_id, duration_minutes } = req.body || {};
    if (!provider || !lock_id) return res.status(400).json({ success: false, error: 'provider + lock_id required' });
    const dur = Math.min(60, Math.max(1, parseInt(duration_minutes) || 5));
    const startTime = Date.now();
    const endTime = startTime + dur * 60 * 1000;
    if (provider === 'ttlock') {
      const accountId = resolveTTLockAccountId(user, req);
      const result = await createTTLockPeriodPasscode({
        accountId,
        lockId: parseInt(lock_id),
        startTime, endTime,
        name: `GAS test code (${user.email || 'admin'})`,
      });
      if (!result.ok) return res.json({ success: false, error: result.error });
      return res.json({ success: true, code: result.keyboardPwd, expires_at: new Date(endTime).toISOString() });
    }
    if (provider === 'remotelock') {
      const accountId = _resolveRemotelockAccountId(user, req);
      // Backdate the start by 60s so the code is live the instant
      // RemoteLock finishes syncing the guest to the physical K5 —
      // without the buffer the operator would race clock skew between
      // RemoteLock, the G2 gateway, and the lock's own RTC (Steve
      // saw this 2026-07-08 — PIN 7185 rejected at 1:35:00 BST when
      // its window opened at 1:35:26 BST). Test window widened to 10
      // min so operators have time to walk from desk to lock.
      const rlStart = startTime - 60 * 1000;
      const rlEnd = startTime + Math.max(dur, 10) * 60 * 1000;
      const result = await createRemoteLockAccessCode({
        accountId,
        deviceId: String(lock_id),
        startTime: rlStart,
        endTime: rlEnd,
        name: `GAS test code (${user.email || 'admin'})`,
      });
      if (!result.ok) return res.json({ success: false, error: result.error });
      return res.json({ success: true, code: result.code, expires_at: new Date(rlEnd).toISOString() });
    }
    res.status(400).json({ success: false, error: `Provider '${provider}' not yet supported` });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// ─── Bike Storage Rate (property-level) ────────────────────────────────
// Single editable rate for all bike_storage cabinets on a property. The
// public widget already reads bookable_units.base_price from the first
// cabinet, and the upsell row's price snapshot is updated in lockstep
// when companion_bookable_unit_id points at a bike_storage cabinet.
app.get('/api/admin/smart-locks/bike-storage-rate', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const propertyId = parseInt(req.query.property_id);
    if (!propertyId) return res.status(400).json({ success: false, error: 'property_id required' });
    const own = await pool.query(`SELECT 1 FROM properties WHERE id = $1 AND account_id = $2`, [propertyId, decoded.accountId || decoded.id]);
    if (!own.rows.length && decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Not your property' });
    }
    const r = await pool.query(
      `SELECT MIN(base_price) AS min_rate, MAX(base_price) AS max_rate,
              COUNT(*) AS cabinet_count, MAX(currency) AS currency
         FROM bookable_units
        WHERE property_id = $1 AND unit_role = 'bike_storage'`,
      [propertyId]
    );
    const row = r.rows[0];
    res.json({
      success: true,
      property_id: propertyId,
      cabinet_count: parseInt(row.cabinet_count) || 0,
      daily_rate: row.min_rate != null ? parseFloat(row.min_rate) : null,
      mixed_rates: row.min_rate != null && row.max_rate != null && parseFloat(row.min_rate) !== parseFloat(row.max_rate),
      currency: row.currency || 'GBP'
    });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

app.put('/api/admin/smart-locks/bike-storage-rate', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'Auth required' });
    const propertyId = parseInt(req.body.property_id);
    const dailyRate = parseFloat(req.body.daily_rate);
    if (!propertyId || !(dailyRate >= 0)) {
      return res.status(400).json({ success: false, error: 'property_id and non-negative daily_rate required' });
    }
    const own = await pool.query(`SELECT 1 FROM properties WHERE id = $1 AND account_id = $2`, [propertyId, decoded.accountId || decoded.id]);
    if (!own.rows.length && decoded.role !== 'master_admin') {
      return res.status(403).json({ success: false, error: 'Not your property' });
    }
    const u = await pool.query(
      `UPDATE bookable_units
          SET base_price = $1, updated_at = NOW()
        WHERE property_id = $2 AND unit_role = 'bike_storage'
        RETURNING id`,
      [dailyRate, propertyId]
    );
    // Sync any upsell rows pointing at one of these cabinets so the
    // upsell-card price stays in lockstep with the standalone widget.
    const cabinetIds = u.rows.map(r => r.id);
    if (cabinetIds.length > 0) {
      await pool.query(
        `UPDATE upsells SET price = $1, updated_at = NOW()
          WHERE companion_bookable_unit_id = ANY($2::int[])`,
        [dailyRate, cabinetIds]
      );
    }
    res.json({ success: true, updated_cabinets: u.rowCount });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// Manual trigger for the auto-charge cron — useful when you can't wait
// for the next hourly tick (e.g. arrival tomorrow, balance overdue, just
// shipped a cron-query fix). Fire-and-forget, returns immediately.
// MUST stay above the /api/* catch-all below or it 404s.
app.post('/api/admin/cron/auto-charge-balances/run', async (req, res) => {
    // Sync mode: await the function + report the top-level outcome so we can
    // see if it silently no-ops. Added 2026-07-17 after Charles House / Vo
    // Rental incidents where the setImmediate version reported "kicked off"
    // but nothing was actually charged and no error surfaced.
    if (req.query.sync === '1' || req.body?.sync === true) {
        try {
            // First, run the SAME query the function uses to prove the pool works.
            const preflightQ = await pool.query(`
                SELECT COUNT(*)::int AS n FROM (
                    SELECT DISTINCT ON (b.id) b.id
                    FROM bookings b
                    JOIN properties p ON p.id = b.property_id
                    JOIN accounts a ON a.id = p.account_id
                    JOIN deposit_rules dr ON dr.id = COALESCE(
                        b.deposit_rule_id,
                        (SELECT dr2.id FROM deposit_rules dr2
                          WHERE dr2.is_active = true
                            AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                          ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC LIMIT 1))
                    LEFT JOIN payment_configurations pc ON (pc.property_id = b.property_id OR (pc.property_id IS NULL AND pc.account_id = p.account_id)) AND pc.provider = 'stripe' AND pc.is_enabled = true
                    WHERE dr.is_active = true
                      AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
                      AND b.stripe_payment_method_id IS NOT NULL
                      AND b.payment_status != 'paid'
                      AND b.balance_amount > 0
                      AND b.status NOT IN ('cancelled', 'rejected')
                      AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
                      AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date <= CURRENT_DATE
                      AND b.arrival_date >= CURRENT_DATE
                    ORDER BY b.id
                ) sub
            `);
            const preflightCount = preflightQ.rows[0]?.n;

            const started = Date.now();
            const fnResult = await processAutoChargePayments();
            const ms = Date.now() - started;
            return res.json({
                success: true,
                mode: 'sync',
                preflight_query_row_count: preflightCount,
                fn_return_value: fnResult === undefined ? 'undefined' : fnResult,
                duration_ms: ms,
                message: 'If preflight_query_row_count > 0 but duration_ms < 100, the fn is short-circuiting internally despite the pool seeing rows.'
            });
        } catch (e) {
            console.error('[AUTO-CHARGE manual sync]', e);
            return res.status(500).json({ success: false, mode: 'sync', error: e.message, stack: e.stack });
        }
    }
    setImmediate(() => processAutoChargePayments().catch(e => console.error('[AUTO-CHARGE manual]', e)));
    res.json({ success: true, mode: 'async', message: 'auto-charge run kicked off — watch Railway logs for [AUTO-CHARGE] output' });
});

// Diagnostic — runs the SAME query + per-booking charge attempt as
// processAutoChargePayments, but SYNCHRONOUSLY and returns per-booking
// outcomes as JSON. Use when the cron is silently no-op'ing to see
// exactly which booking fails where. Master admin only.
// Added 2026-07-17 after Charles House / Desi Kirilova + Vo Rental /
// Jose incidents where the cron reported success but zero bookings
// were charged.
app.post('/api/admin/cron/auto-charge-balances/diagnose', async (req, res) => {
    try {
        const decoded = await extractAccountFromToken(req);
        if (!decoded || decoded.role !== 'master_admin') return res.status(403).json({ error: 'Master admin only' });

        const q = await pool.query(`
            SELECT DISTINCT ON (b.id)
                b.id AS booking_id, p.account_id, b.property_id,
                b.guest_first_name, b.guest_last_name, b.guest_email,
                b.arrival_date, b.grand_total, b.deposit_amount, b.balance_amount,
                b.stripe_payment_method_id, b.stripe_payment_intent_id, b.stripe_customer_id,
                b.stripe_setup_intent_id, b.payment_status, b.currency,
                COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14) AS effective_days_before,
                COALESCE(p.stripe_secret_key, a.stripe_secret_key) AS stripe_secret_key,
                p.currency AS property_currency, p.name AS property_name,
                a.email AS owner_email,
                pc.credentials AS payment_config_credentials,
                dr.id AS deposit_rule_id,
                (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date AS trigger_date
            FROM bookings b
            JOIN properties p ON p.id = b.property_id
            JOIN accounts a ON a.id = p.account_id
            JOIN deposit_rules dr ON dr.id = COALESCE(
                b.deposit_rule_id,
                (SELECT dr2.id FROM deposit_rules dr2
                  WHERE dr2.is_active = true
                    AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                  ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC LIMIT 1))
            LEFT JOIN payment_configurations pc ON (pc.property_id = b.property_id OR (pc.property_id IS NULL AND pc.account_id = p.account_id)) AND pc.provider = 'stripe' AND pc.is_enabled = true
            WHERE dr.is_active = true
              AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
              AND b.stripe_payment_method_id IS NOT NULL
              AND b.payment_status != 'paid'
              AND b.balance_amount > 0
              AND b.status NOT IN ('cancelled', 'rejected')
              AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
              AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date <= CURRENT_DATE
              AND b.arrival_date >= CURRENT_DATE
            ORDER BY b.id, b.arrival_date
        `);

        const bookings = q.rows;
        const outcomes = [];

        for (const b of bookings) {
            const outcome = {
                booking_id: b.booking_id,
                guest: [b.guest_first_name, b.guest_last_name].filter(Boolean).join(' '),
                property: b.property_name,
                account_id: b.account_id,
                balance: b.balance_amount,
                currency: b.currency,
                arrival: b.arrival_date,
                trigger_date: b.trigger_date,
                has_pm: !!b.stripe_payment_method_id,
                has_customer: !!b.stripe_customer_id,
                has_stripe_key_via_config: !!(b.payment_config_credentials?.secret_key),
                has_stripe_key_via_account: !!b.stripe_secret_key,
                stage: 'start',
                error: null
            };
            try {
                const stripeKey = b.payment_config_credentials?.secret_key || b.stripe_secret_key || process.env.STRIPE_SECRET_KEY;
                if (!stripeKey) { outcome.stage = 'no_stripe_key'; outcome.error = 'No Stripe secret key resolvable for this booking'; outcomes.push(outcome); continue; }
                outcome.stage = 'stripe_key_ok';

                const stripeClient = require('stripe')(stripeKey);
                const chargeCurrency = (b.currency || b.property_currency || 'eur').toLowerCase();

                outcome.stage = 'resolving_customer';
                const cust = await resolveStripeCustomerForBooking(stripeClient, b, pool);
                outcome.customer_source = cust.source;
                outcome.customer_id = cust.customerId;
                outcome.stage = 'customer_ok';

                outcome.stage = 'previewing_only';
                outcome.would_charge_amount = toStripeAmount(b.balance_amount, chargeCurrency);
                outcome.would_charge_currency = chargeCurrency;
                outcome.would_use_pm = b.stripe_payment_method_id;
                outcome.stage = 'ready_to_charge (dry-run — no PI created by diagnose endpoint)';
            } catch (e) {
                outcome.error = e.message;
            }
            outcomes.push(outcome);
        }

        res.json({ success: true, count: bookings.length, outcomes });
    } catch (e) {
        console.error('[AUTO-CHARGE diagnose]', e);
        res.status(500).json({ success: false, error: e.message });
    }
});

// Public: short-stay enquiry — fires when the widget warning says the
// guest's selected nights are below the room's min stay. Creates an
// inbox_message for the operator + emails them so they can choose to
// accept the under-min stay manually (operator replies to guest direct
// or pushes an override booking via admin). No min-stay change is made
// on this endpoint — it's a request, not an approval.
app.post('/api/public/short-stay-enquiry', async (req, res) => {
    try {
        const { client_id, unit_id, check_in, check_out, adults, children, guest_name, guest_email, guest_phone, message } = req.body || {};
        if (!client_id || !unit_id || !check_in || !check_out || !guest_name || !guest_email) {
            return res.status(400).json({ success: false, error: 'client_id, unit_id, check_in, check_out, guest_name, guest_email required' });
        }
        // Validate email format
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(guest_email).trim())) {
            return res.status(400).json({ success: false, error: 'Invalid email' });
        }
        const accountId = parseInt(client_id);
        // Resolve the room + property for context in the enquiry email
        const ctx = await pool.query(`
            SELECT bu.id AS unit_id, bu.name AS unit_name,
                   p.id AS property_id, p.name AS property_name,
                   a.id AS account_id, a.name AS account_name, a.email AS owner_email
              FROM bookable_units bu
              JOIN properties p ON bu.property_id = p.id
              JOIN accounts a ON p.account_id = a.id
             WHERE bu.id = $1 AND a.id = $2
             LIMIT 1
        `, [parseInt(unit_id), accountId]);
        if (ctx.rows.length === 0) return res.status(404).json({ success: false, error: 'Unit not found for this client' });
        const { unit_name, property_name, owner_email, account_name } = ctx.rows[0];
        const nights = Math.max(1, Math.ceil((new Date(check_out) - new Date(check_in)) / (1000*60*60*24)));
        const subj = `Short-stay enquiry: ${nights}-night stay at ${unit_name}`;
        const bodyText =
            `Guest:     ${guest_name}\n` +
            `Email:     ${guest_email}\n` +
            `Phone:     ${guest_phone || '—'}\n\n` +
            `Property:  ${property_name}\n` +
            `Unit:      ${unit_name}\n` +
            `Dates:     ${check_in} → ${check_out} (${nights} ${nights===1?'night':'nights'})\n` +
            `Guests:    ${adults || 1} adults, ${children || 0} children\n\n` +
            (message ? `Message:\n${message}\n\n` : '') +
            `To accept: reply to the guest at ${guest_email}, or create the booking manually in GAS Admin with a min-stay override.`;
        // Master inbox
        await sendMasterNotification({
            title: subj,
            body: bodyText,
            severity: 'info',
            metadata: { kind: 'short_stay_enquiry', account_id: accountId, unit_id: ctx.rows[0].unit_id, guest_email }
        });
        // Operator inbox (under their account)
        await pool.query(
            `INSERT INTO inbox_messages
                (account_id, channel, from_name, from_email, subject, body, direction, status, category, created_at, metadata)
             VALUES ($1, 'enquiry', $2, $3, $4, $5, 'inbound', 'unread', 'short_stay_enquiry', NOW(), $6)`,
            [accountId, guest_name, guest_email, subj, bodyText, JSON.stringify({ unit_id: ctx.rows[0].unit_id, check_in, check_out, nights, adults, children, phone: guest_phone || null })]
        );
        // Email the operator if we have an address on file
        if (owner_email) {
            try {
                await sendEmail({
                    to: owner_email,
                    subject: subj,
                    html: `<p>Hi,</p><p>A guest has asked whether you'd accept a stay below the rate plan's minimum:</p><pre style="background:#f3f4f6;padding:1rem;border-radius:6px;white-space:pre-wrap;font-family:ui-monospace,monospace;">${bodyText.replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}</pre><p>Reply to the guest at <a href="mailto:${guest_email}">${guest_email}</a> if you'd like to accept.</p><p>— GAS</p>`
                });
            } catch (e) {
                console.warn('[short-stay-enquiry] owner email send failed:', e.message);
            }
        }
        res.json({ success: true });
    } catch (e) {
        console.error('[short-stay-enquiry] error:', e);
        res.status(500).json({ success: false, error: e.message });
    }
});

// ============================================
// ENIGMA CARD VAULT INTEGRATION
// ============================================

// Helper: Get Enigma OAuth2 access token
async function getEnigmaAccessToken() {
  const clientId = process.env.ENIGMA_CLIENT_ID;
  const clientSecret = process.env.ENIGMA_CLIENT_SECRET;
  const authUrl = process.env.ENIGMA_AUTH_URL || 'https://api-auth.enigmavault.io';
  
  if (!clientId || !clientSecret) {
    throw new Error('Enigma Vault credentials not configured');
  }
  
  const response = await fetch(`${authUrl}/oauth2/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `grant_type=client_credentials&client_id=${clientId}&client_secret=${clientSecret}&scope=io.enigmavault/cardvault`
  });
  
  if (!response.ok) {
    const err = await response.text();
    throw new Error(`Enigma auth failed: ${response.status} - ${err}`);
  }
  
  const data = await response.json();
  return data.access_token;
}

// Helper: Log Enigma usage for billing
async function logEnigmaUsage(accountId, propertyId, bookingId, action, apiCalls = 1, details = {}) {
  try {
    // Cost per API call based on Lite tier overage ($0.08/request)
    const enigmaCost = apiCalls * 0.08;
    // Fee charged to owner - configurable, default $0.50 per card capture, $1.00 per charge
    const feeRates = { form_request: 0, card_capture: 0.50, card_search: 0, card_charge: 1.00, cvv_capture: 0.25 };
    const feeCharged = feeRates[action] || 0;
    
    await pool.query(`
      INSERT INTO enigma_usage_log (account_id, property_id, booking_id, action, api_calls, enigma_cost, fee_charged, details)
      VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
    `, [accountId, propertyId, bookingId, action, apiCalls, enigmaCost, feeCharged, JSON.stringify(details)]);
  } catch (err) {
    console.error('Failed to log Enigma usage:', err.message);
  }
}


// Global error handler - ALWAYS return JSON, never HTML
app.use((err, req, res, next) => {
  console.error('Global error handler:', err.message);
  console.error('Request:', req.method, req.url);
  if (err.stack) console.error(err.stack);
  res.status(err.status || 500).json({
    success: false,
    error: err.message || 'Internal server error',
    path: req.url
  });
});
// SYNC SCHEDULER
// ============================================
function startTieredSyncScheduler() {
  // Run every 15 minutes (900000ms)
  const SYNC_INTERVAL = 15 * 60 * 1000;
  
  console.log('⏰ [Tiered Sync] Scheduler started - runs every 15 minutes');
  
  // Run first sync after 30 seconds (let server fully start)
  setTimeout(() => {
    runTieredSync();
  }, 30000);
  
  // Then run every 15 minutes
  setInterval(() => {
    runTieredSync();
  }, SYNC_INTERVAL);
}

// =========================================================
// AUTO-CHARGE BALANCE PAYMENTS BEFORE ARRIVAL
// =========================================================

// Resolve the Stripe customer for a booking, in strict order of preference:
//   1. bookings.stripe_customer_id (cached, no Stripe call)
//   2. PaymentIntent.customer (existing PI from booking)
//   3. SetupIntent.customer  (existing SI from deferred-charge bookings)
//   4. PaymentMethod.customer (PM already attached to a customer)
//   5. Create a new customer + attach PM (last resort)
// Persists the resolved customer back to bookings.stripe_customer_id so
// subsequent runs hit the cached path. Throws with a precise reason string
// if nothing works — the caller's outer catch records the failure properly
// (DB + email + Slack). No silent skips, ever.
async function resolveStripeCustomerForBooking(stripeClient, booking, pool) {
    const bookingId = booking.booking_id || booking.id;
    const reasons = [];

    if (booking.stripe_customer_id) {
        return { customerId: booking.stripe_customer_id, source: 'cached' };
    }

    if (booking.stripe_payment_intent_id) {
        try {
            const pi = await stripeClient.paymentIntents.retrieve(booking.stripe_payment_intent_id);
            if (pi.customer) {
                await pool.query('UPDATE bookings SET stripe_customer_id=$1 WHERE id=$2 AND stripe_customer_id IS NULL', [pi.customer, bookingId]).catch(() => {});
                return { customerId: pi.customer, source: 'payment_intent' };
            }
            reasons.push(`PI ${booking.stripe_payment_intent_id} has no customer`);
        } catch (e) {
            reasons.push(`PI retrieve failed: ${e.message}`);
        }
    }

    if (booking.stripe_setup_intent_id) {
        try {
            const si = await stripeClient.setupIntents.retrieve(booking.stripe_setup_intent_id);
            if (si.customer) {
                await pool.query('UPDATE bookings SET stripe_customer_id=$1 WHERE id=$2 AND stripe_customer_id IS NULL', [si.customer, bookingId]).catch(() => {});
                return { customerId: si.customer, source: 'setup_intent' };
            }
            reasons.push(`SI ${booking.stripe_setup_intent_id} has no customer`);
        } catch (e) {
            reasons.push(`SI retrieve failed: ${e.message}`);
        }
    }

    if (booking.stripe_payment_method_id) {
        try {
            const pm = await stripeClient.paymentMethods.retrieve(booking.stripe_payment_method_id);
            if (pm.customer) {
                await pool.query('UPDATE bookings SET stripe_customer_id=$1 WHERE id=$2 AND stripe_customer_id IS NULL', [pm.customer, bookingId]).catch(() => {});
                return { customerId: pm.customer, source: 'payment_method' };
            }
            reasons.push(`PM ${booking.stripe_payment_method_id} has no customer attached`);
        } catch (e) {
            reasons.push(`PM retrieve failed: ${e.message}`);
        }
    }

    // Last resort — create a new customer and attach the PM.
    if (booking.stripe_payment_method_id) {
        try {
            const guestName = [booking.guest_first_name, booking.guest_last_name].filter(Boolean).join(' ');
            const customer = await stripeClient.customers.create({
                name: guestName,
                email: booking.guest_email,
                payment_method: booking.stripe_payment_method_id,
                metadata: { booking_id: String(bookingId) }
            });
            await pool.query('UPDATE bookings SET stripe_customer_id=$1 WHERE id=$2 AND stripe_customer_id IS NULL', [customer.id, bookingId]).catch(() => {});
            return { customerId: customer.id, source: 'created' };
        } catch (e) {
            reasons.push(`customer create failed: ${e.message}`);
        }
    }

    throw new Error(`Could not resolve Stripe customer for booking ${bookingId}. Tried: ${reasons.join(' | ') || 'no PI/SI/PM on booking'}`);
}

// OTA booking detector — used by both auto-charge crons AND the manual
// charge endpoint AND the admin "Take payment now" button gating.
//
// Only booking_source is inspected. api_source is the ROUTING platform
// (channex, beds24 CM) which is NOT a payment signal by itself —
// bookings coming through Channex from a direct-website channel are
// chargeable by GAS. The real OTA name lives in booking_source.
//
// Sources listed here are ones where GAS never collects: OTA owns
// payment (they pre-collect or pass a virtual card that only works
// on-property). Excludes:
//   - true OTAs: expedia, booking, airbnb, vrbo, hostelworld, agoda,
//                marriott, hotelbeds, hrs, tripadvisor, trivago,
//                tablethotels, hostvana
//   - channel-manager-as-source (imports without original OTA name):
//     beds24 (10k+ estate rows, 0 with cards), hostfully (1.5k, 0 cards)
// CHARGEABLE (not in this set):
//   - direct, rezintel, googleads, enquiry, channex (reserved for
//     Channex-direct), (null)
const _OTA_SOURCES = new Set([
  'expedia','booking','booking.com','airbnb','agoda','vrbo','hostelworld',
  'marriott','hotelbeds','hrs','tripadvisor','trivago','tablethotels','trip',
  'hostvana','beds24','hostfully'
]);
function _isOtaBooking(b) {
  const bs = String(b?.booking_source || '').toLowerCase().trim();
  return !!bs && _OTA_SOURCES.has(bs);
}
// SQL fragment for cron queries — matches _isOtaBooking exactly.
const _CRON_EXCLUDE_OTA_SQL = `
  AND (b.booking_source IS NULL OR LOWER(b.booking_source) NOT IN ('expedia','booking','booking.com','airbnb','agoda','vrbo','hostelworld','marriott','hotelbeds','hrs','tripadvisor','trivago','tablethotels','trip','hostvana','beds24','hostfully'))`;

// Square auto-charge branch — added 2026-08-16 to close the gap where
// Casa Magnolia balances would never auto-collect (cron was Stripe-only).
// Mirrors processAutoChargePayments' Stripe path but calls Square's
// POST /v2/payments with the saved ccof_XXX card_id. Self-contained so
// the Stripe path stays byte-for-byte untouched (no regression risk).
async function _processAutoChargeSquareBranch() {
    if (String(process.env.AUTO_CHARGE_PAUSED || '').toLowerCase() === 'true') return; // outer already logged
    const result = await pool.query(`
        SELECT DISTINCT ON (b.id)
            b.id as booking_id,
            p.account_id,
            b.property_id,
            b.guest_first_name,
            b.guest_last_name,
            b.guest_email,
            b.arrival_date,
            b.grand_total,
            b.deposit_amount,
            b.balance_amount,
            b.square_card_id,
            b.square_customer_id,
            b.square_location_id,
            b.square_payment_id,
            b.payment_status,
            b.currency,
            COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14) AS effective_days_before,
            p.currency as property_currency,
            p.name as property_name,
            a.email as owner_email,
            a.square_environment,
            dr.id as deposit_rule_id,
            (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date AS trigger_date
        FROM bookings b
        JOIN properties p ON p.id = b.property_id
        JOIN accounts a ON a.id = p.account_id
        JOIN deposit_rules dr ON dr.id = COALESCE(
            b.deposit_rule_id,
            (
                SELECT dr2.id FROM deposit_rules dr2
                WHERE dr2.is_active = true
                  AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC
                LIMIT 1
            )
        )
        WHERE a.square_status = 'active'
          AND dr.is_active = true
          AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
          AND b.square_card_id IS NOT NULL
          AND b.payment_status != 'paid'
          AND b.balance_amount > 0
          AND b.status NOT IN ('cancelled', 'rejected')
          AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
          AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date <= CURRENT_DATE
          AND b.arrival_date >= CURRENT_DATE
          ${_CRON_EXCLUDE_OTA_SQL}
        ORDER BY b.id, b.arrival_date
    `);

    if (result.rows.length === 0) {
        console.log('[AUTO-CHARGE SQUARE] No Square balances due');
        return;
    }
    console.log(`[AUTO-CHARGE SQUARE] Found ${result.rows.length} Square bookings to charge`);

    for (const booking of result.rows) {
        const guestName = [booking.guest_first_name, booking.guest_last_name].filter(Boolean).join(' ');
        const chargeCurrency = (booking.currency || booking.property_currency || 'USD').toUpperCase();

        try {
            // Three-belt ledger idempotency — same shape as the Stripe path.
            // (a) prior auto-charge on this booking, (b) ledger already covers
            // grand_total, (c) any Square charge in the last 24h.
            const priorAuto = await pool.query(
                `SELECT id, gateway_transaction_id, amount, created_at
                   FROM payment_transactions
                  WHERE booking_id = $1
                    AND payment_gateway = 'square'
                    AND status IN ('completed','succeeded')
                    AND transaction_type IN ('balance','payment')
                    AND (description LIKE 'Auto-charge balance%' OR description LIKE 'Balance payment%')
                  LIMIT 1`,
                [booking.booking_id]
            );
            if (priorAuto.rows.length > 0) {
                const p = priorAuto.rows[0];
                console.warn(`[AUTO-CHARGE SQUARE] SKIP booking ${booking.booking_id} — already auto-charged (tx ${p.id} sq=${p.gateway_transaction_id} ${p.amount} ${p.created_at.toISOString()})`);
                continue;
            }
            const priorSumRes = await pool.query(
                `SELECT COALESCE(SUM(amount), 0)::numeric AS paid
                   FROM payment_transactions
                  WHERE booking_id = $1
                    AND payment_gateway = 'square'
                    AND status IN ('completed','succeeded')
                    AND transaction_type IN ('deposit','balance','payment','charge','capture')`,
                [booking.booking_id]
            );
            const alreadyPaid = parseFloat(priorSumRes.rows[0]?.paid || 0);
            const grandTotal  = parseFloat(booking.grand_total || 0);
            if (grandTotal > 0 && alreadyPaid + 0.01 >= grandTotal) {
                console.warn(`[AUTO-CHARGE SQUARE] SKIP booking ${booking.booking_id} — ledger shows ${alreadyPaid} paid vs grand_total ${grandTotal}. Refusing double-charge.`);
                continue;
            }
            const recentRes = await pool.query(
                `SELECT id, gateway_transaction_id, amount, created_at
                   FROM payment_transactions
                  WHERE booking_id = $1
                    AND payment_gateway = 'square'
                    AND status IN ('completed','succeeded')
                    AND transaction_type IN ('deposit','balance','payment','charge','capture')
                    AND created_at > NOW() - INTERVAL '24 hours'
                  ORDER BY created_at DESC LIMIT 1`,
                [booking.booking_id]
            );
            if (recentRes.rows.length > 0) {
                const r = recentRes.rows[0];
                console.warn(`[AUTO-CHARGE SQUARE] SKIP booking ${booking.booking_id} — Square charge tx ${r.id} sq=${r.gateway_transaction_id} amount=${r.amount} fired ${r.created_at.toISOString()} (< 24h). Refusing same-day double-tap.`);
                continue;
            }

            // Compute outstanding from the ledger, not from booking.balance_amount
            // (same defensive logic as the Stripe path — Mornington Rose shape).
            const outstanding = Math.max(
                0,
                Math.round((grandTotal - alreadyPaid) * 100) / 100
            );
            if (outstanding <= 0.005) {
                console.log(`[AUTO-CHARGE SQUARE] SKIP booking ${booking.booking_id} — outstanding ${outstanding.toFixed(2)}`);
                continue;
            }

            const accessToken = await refreshSquareTokenIfNeeded(booking.account_id);
            if (!accessToken) {
                console.warn(`[AUTO-CHARGE SQUARE] SKIP booking ${booking.booking_id} — no Square access token for account ${booking.account_id}`);
                continue;
            }
            const locationId = booking.square_location_id || (await getSquareLocationForAccount(booking.account_id))?.id;
            if (!locationId) {
                console.warn(`[AUTO-CHARGE SQUARE] SKIP booking ${booking.booking_id} — no square_location_id`);
                continue;
            }
            const sq = (booking.square_environment === 'production')
                ? { apiBase: 'https://connect.squareup.com' }
                : { apiBase: 'https://connect.squareupsandbox.com' };

            const amountMinor = Math.round(outstanding * 100);
            const idempotencyKey = `auto-square-${booking.booking_id}-${new Date().toISOString().slice(0,10)}`;

            console.log(`[AUTO-CHARGE SQUARE] booking ${booking.booking_id} charging ${chargeCurrency} ${outstanding.toFixed(2)} (grand ${grandTotal} - paid ${alreadyPaid}) via card ${booking.square_card_id}`);

            const payResp = await fetch(`${sq.apiBase}/v2/payments`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${accessToken}`,
                    'Content-Type': 'application/json',
                    'Square-Version': '2024-12-18',
                },
                body: JSON.stringify({
                    source_id: booking.square_card_id,
                    customer_id: booking.square_customer_id || undefined,
                    location_id: locationId,
                    idempotency_key: idempotencyKey.slice(0, 45),
                    amount_money: { amount: amountMinor, currency: chargeCurrency },
                    autocomplete: true,
                    note: `Auto balance charge · GAS booking ${booking.booking_id} · ${guestName} · arrival ${booking.arrival_date}`,
                    reference_id: `gas-balance-${booking.booking_id}`,
                }),
            });
            const payBody = await payResp.json();

            if (!payResp.ok || payBody?.payment?.status !== 'COMPLETED') {
                const firstErr = payBody?.errors?.[0] || {};
                const errCode = firstErr.code || 'UNKNOWN';
                const errDetail = firstErr.detail || `HTTP ${payResp.status}`;
                // Terminal card-level errors → mark balance_failed + notify.
                // Transient (5xx, rate limit, connection) → leave alone; next
                // hourly tick will retry.
                const terminalCodes = new Set([
                    'CARD_DECLINED','CVV_FAILURE','INVALID_CARD','INVALID_EXPIRATION',
                    'CARD_NOT_SUPPORTED','INSUFFICIENT_FUNDS','VERIFY_CVV_FAILURE',
                    'VERIFY_AVS_FAILURE','GENERIC_DECLINE','CARD_TOKEN_USED','CARD_TOKEN_EXPIRED',
                    'INVALID_ACCOUNT','ADDRESS_VERIFICATION_FAILURE','TRANSACTION_LIMIT'
                ]);
                const isTerminal = terminalCodes.has(errCode);

                await pool.query(
                    "UPDATE bookings SET last_charge_error = $2, last_charge_error_code = $3, last_charge_error_at = NOW(), updated_at = NOW()"
                    + (isTerminal ? ", payment_status = 'balance_failed'" : '')
                    + " WHERE id = $1",
                    [booking.booking_id, String(errDetail).slice(0, 1000), errCode]
                ).catch(() => {});

                if (!isTerminal) {
                    console.warn(`[AUTO-CHARGE SQUARE] Transient err on booking ${booking.booking_id} (${errCode}) — leaving payment_status; next tick will retry`);
                    continue;
                }

                console.error(`[AUTO-CHARGE SQUARE] TERMINAL failure booking ${booking.booking_id}: ${errCode} — ${errDetail}`);

                // Owner + Slack notifications (same shape as the Stripe path).
                try {
                    if (booking.owner_email) {
                        await sendEmail({
                            to: [booking.owner_email, 'development@gas.travel'],
                            subject: `Balance Payment Failed — ${guestName} — ${booking.property_name || 'Booking #' + booking.booking_id}`,
                            html: `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
                                <h2 style="color:#dc2626;">Balance Payment Failed (Square)</h2>
                                <p>An automatic balance payment could not be charged:</p>
                                <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Guest</td><td style="padding:8px;border:1px solid #e5e7eb;">${guestName} (${booking.guest_email})</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Property</td><td style="padding:8px;border:1px solid #e5e7eb;">${booking.property_name || '-'}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Booking Ref</td><td style="padding:8px;border:1px solid #e5e7eb;">#${booking.booking_id}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Amount</td><td style="padding:8px;border:1px solid #e5e7eb;">${chargeCurrency} ${outstanding.toFixed(2)}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Check-in</td><td style="padding:8px;border:1px solid #e5e7eb;">${booking.arrival_date}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Error</td><td style="padding:8px;border:1px solid #e5e7eb;color:#dc2626;">${errCode} — ${errDetail}</td></tr>
                                </table>
                                <p style="color:#6b7280;font-size:13px;">You can manually collect this balance in Square, or send a new capture link from GAS Admin.</p>
                            </div>`
                        });
                    }
                } catch (emailErr) {
                    console.error('[AUTO-CHARGE SQUARE] Could not send owner failure email:', emailErr.message);
                }
                if (process.env.SLACK_WEBHOOK_URL) {
                    try {
                        await axios.post(process.env.SLACK_WEBHOOK_URL, {
                            text: `❌ *Balance Payment Failed (Square)*\nBooking #${booking.booking_id} — ${guestName}\nProperty: ${booking.property_name || '-'}\nAmount: ${chargeCurrency} ${outstanding.toFixed(2)}\nCheck-in: ${booking.arrival_date}\nError: ${errCode} — ${errDetail}`
                        });
                    } catch (_) {}
                }
                continue;
            }

            // Success path.
            const payment = payBody.payment;
            await pool.query(`
                UPDATE bookings
                SET payment_status = 'paid',
                    balance_amount = 0,
                    balance_paid_at = NOW(),
                    square_payment_id = COALESCE(square_payment_id, $2),
                    updated_at = NOW()
                WHERE id = $1
            `, [booking.booking_id, payment.id]);

            // Cascade booking_extras 'reserved' → 'paid' (same as Stripe path).
            try {
                const upd = await pool.query(
                    `UPDATE booking_extras SET status = 'paid', updated_at = NOW()
                     WHERE booking_id = $1 AND status = 'reserved'`,
                    [booking.booking_id]
                );
                if (upd.rowCount > 0) console.log(`[AUTO-CHARGE SQUARE extras] Flipped ${upd.rowCount} extras → paid for booking ${booking.booking_id}`);
            } catch (extraErr) {
                console.error(`[AUTO-CHARGE SQUARE extras] booking ${booking.booking_id}:`, extraErr.message);
            }

            // Ledger row. Idempotent via ON CONFLICT DO NOTHING against the
            // gateway_transaction_id. If Square returned the same payment.id
            // on a retry (idempotency_key match), this row won't duplicate.
            try {
                await pool.query(`
                    INSERT INTO payment_transactions (
                        booking_id, account_id, transaction_type, amount, currency,
                        payment_gateway, gateway_transaction_id, status,
                        payment_method_type, completed_at, description
                    ) VALUES ($1, $2, 'balance', $3, $4, 'square', $5, 'completed', 'card', NOW(), $6)
                    ON CONFLICT DO NOTHING
                `, [
                    booking.booking_id, booking.account_id,
                    outstanding, chargeCurrency,
                    payment.id,
                    `Auto-charge balance · trigger ${booking.trigger_date} · days_before ${booking.effective_days_before}`
                ]);
            } catch (ledgerErr) {
                console.error(`[AUTO-CHARGE SQUARE ledger] booking ${booking.booking_id} sq=${payment.id}:`, ledgerErr.message);
            }

            console.log(`[AUTO-CHARGE SQUARE] Successfully charged booking ${booking.booking_id} - ${guestName} sq=${payment.id}`);
        } catch (chargeErr) {
            console.error(`[AUTO-CHARGE SQUARE] Booking ${booking.booking_id} threw:`, chargeErr.message);
            await pool.query(
                `UPDATE bookings SET last_charge_error = $2, last_charge_error_code = 'exception', last_charge_error_at = NOW(), updated_at = NOW() WHERE id = $1`,
                [booking.booking_id, String(chargeErr.message || '').slice(0, 1000)]
            ).catch(() => {});
        }
    }
}

// Expedia VCC auto-charge — Charles House Aug 2026 driver. Fires on
// Channex-imported OTA bookings marked ota_payment_collect='ota' from
// their check-in date onwards. The card on file is a VCC funded by
// Expedia (Path B in Steve's terminology), so charges are near-certain
// to succeed (unlike guest-card decline pattern on Hotel Collect).
//
// Only fires on Stripe-backed accounts (not Stripe Connect specifically —
// the Channex clone already ran and the pm_ lives on the client's own
// Stripe account either way). Hotel Collect bookings are excluded here;
// they stay manual because the guest's real card often declines and
// Barbara needs to send a fresh-card link on failure (existing flow).
async function _processAutoChargeExpediaVCCBranch() {
    if (String(process.env.AUTO_CHARGE_PAUSED || '').toLowerCase() === 'true') return;
    const result = await pool.query(`
        SELECT DISTINCT ON (b.id)
            b.id as booking_id,
            p.account_id,
            b.property_id,
            b.guest_first_name,
            b.guest_last_name,
            b.guest_email,
            b.arrival_date,
            b.grand_total,
            b.deposit_amount,
            b.balance_amount,
            b.stripe_payment_method_id,
            b.stripe_customer_id,
            b.payment_status,
            b.currency,
            b.booking_source,
            b.card_last4,
            b.card_brand,
            b.ota_charge_amount_minor,
            COALESCE(p.stripe_secret_key, a.stripe_secret_key) as stripe_secret_key,
            pc.credentials as payment_config_credentials,
            p.currency as property_currency,
            p.name as property_name,
            a.email as owner_email
        FROM bookings b
        JOIN properties p ON p.id = b.property_id
        JOIN accounts a ON a.id = p.account_id
        LEFT JOIN payment_configurations pc ON (pc.property_id = b.property_id OR (pc.property_id IS NULL AND pc.account_id = p.account_id)) AND pc.provider = 'stripe' AND pc.is_enabled = true
        WHERE b.ota_payment_collect = 'ota'
          AND b.channex_booking_id IS NOT NULL
          AND b.stripe_payment_method_id IS NOT NULL
          AND b.payment_status != 'paid'
          AND b.balance_amount > 0
          AND b.status NOT IN ('cancelled', 'rejected')
          AND b.arrival_date <= CURRENT_DATE          -- Expedia rule: charge ON check-in date or after
          AND b.arrival_date >= CURRENT_DATE - INTERVAL '30 days'   -- don't churn ancient rows
        ORDER BY b.id, b.arrival_date
    `);

    if (result.rows.length === 0) {
        console.log('[AUTO-CHARGE EXPEDIA-VCC] No Expedia VCC balances due');
        return;
    }
    console.log(`[AUTO-CHARGE EXPEDIA-VCC] Found ${result.rows.length} bookings to charge`);

    for (const booking of result.rows) {
        const guestName = [booking.guest_first_name, booking.guest_last_name].filter(Boolean).join(' ');
        const chargeCurrency = (booking.currency || booking.property_currency || 'GBP').toLowerCase();

        try {
            // Three-belt idempotency (same shape as Stripe branch).
            const priorAuto = await pool.query(
                `SELECT id, gateway_transaction_id, amount, created_at
                   FROM payment_transactions
                  WHERE booking_id = $1
                    AND payment_gateway = 'stripe'
                    AND status IN ('completed','succeeded')
                    AND transaction_type IN ('balance','payment')
                    AND (description LIKE 'Auto-charge Expedia VCC%' OR description LIKE 'Auto-charge balance%')
                  LIMIT 1`,
                [booking.booking_id]
            );
            if (priorAuto.rows.length > 0) {
                const p = priorAuto.rows[0];
                console.warn(`[AUTO-CHARGE EXPEDIA-VCC] SKIP booking ${booking.booking_id} — already auto-charged (tx ${p.id} pi=${p.gateway_transaction_id} ${p.amount} ${p.created_at.toISOString()})`);
                continue;
            }
            const priorSumRes = await pool.query(
                `SELECT COALESCE(SUM(amount), 0)::numeric AS paid
                   FROM payment_transactions
                  WHERE booking_id = $1
                    AND payment_gateway = 'stripe'
                    AND status IN ('completed','succeeded')
                    AND transaction_type IN ('deposit','balance','payment','charge','capture')`,
                [booking.booking_id]
            );
            const alreadyPaid = parseFloat(priorSumRes.rows[0]?.paid || 0);
            const grandTotal = parseFloat(booking.grand_total || 0);
            if (grandTotal > 0 && alreadyPaid + 0.01 >= grandTotal) {
                console.warn(`[AUTO-CHARGE EXPEDIA-VCC] SKIP booking ${booking.booking_id} — ledger already covers grand_total (${alreadyPaid} vs ${grandTotal})`);
                continue;
            }
            const recentRes = await pool.query(
                `SELECT id, gateway_transaction_id, amount, created_at
                   FROM payment_transactions
                  WHERE booking_id = $1
                    AND payment_gateway = 'stripe'
                    AND status IN ('completed','succeeded')
                    AND transaction_type IN ('deposit','balance','payment','charge','capture')
                    AND created_at > NOW() - INTERVAL '24 hours'
                  ORDER BY created_at DESC LIMIT 1`,
                [booking.booking_id]
            );
            if (recentRes.rows.length > 0) {
                const r = recentRes.rows[0];
                console.warn(`[AUTO-CHARGE EXPEDIA-VCC] SKIP booking ${booking.booking_id} — Stripe charge tx ${r.id} pi=${r.gateway_transaction_id} amount=${r.amount} fired ${r.created_at.toISOString()} (< 24h ago)`);
                continue;
            }

            // Charge amount — prefer ota_charge_amount_minor (Channex's
            // meta.payment_charge = net VCC amount after Expedia commission).
            // Falls back to grand_total for legacy rows without the minor
            // column populated. Both cases still subtract prior payments
            // via alreadyPaid so we never over-charge across retries.
            const otaChargeMinor = parseInt(booking.ota_charge_amount_minor || 0);
            const otaChargeGross = otaChargeMinor > 0 ? otaChargeMinor / 100 : grandTotal;
            const outstanding = Math.max(
                0,
                Math.round((otaChargeGross - alreadyPaid) * 100) / 100
            );
            if (outstanding <= 0.005) {
                console.log(`[AUTO-CHARGE EXPEDIA-VCC] SKIP booking ${booking.booking_id} — outstanding ${outstanding}`);
                continue;
            }

            const stripeKey = booking.payment_config_credentials?.secret_key || booking.stripe_secret_key || process.env.STRIPE_SECRET_KEY;
            if (!stripeKey) {
                console.warn(`[AUTO-CHARGE EXPEDIA-VCC] SKIP booking ${booking.booking_id} — no Stripe key`);
                continue;
            }
            const stripeClient = require('stripe')(stripeKey);
            const idempotencyKey = `auto-expvcc-${booking.booking_id}-${new Date().toISOString().slice(0,10)}`;

            console.log(`[AUTO-CHARGE EXPEDIA-VCC] booking ${booking.booking_id} charging ${chargeCurrency.toUpperCase()} ${outstanding.toFixed(2)} · card ${booking.card_brand || '?'} ****${booking.card_last4 || '????'}`);

            const paymentIntent = await stripeClient.paymentIntents.create({
                amount: toStripeAmount(outstanding, chargeCurrency),
                currency: chargeCurrency,
                customer: booking.stripe_customer_id || undefined,
                payment_method: booking.stripe_payment_method_id,
                confirm: true,
                off_session: true,
                description: `Auto-charge Expedia VCC · booking ${booking.booking_id} · ${guestName} · check-in ${booking.arrival_date}`,
                metadata: {
                    booking_id: String(booking.booking_id),
                    account_id: String(booking.account_id),
                    type: 'expedia_vcc',
                    source: booking.booking_source || 'expedia',
                }
            }, { idempotencyKey });

            if (paymentIntent.status !== 'succeeded') {
                throw new Error(`PaymentIntent status: ${paymentIntent.status}. PI: ${paymentIntent.id}, last_payment_error: ${paymentIntent.last_payment_error?.message || 'none'}`);
            }

            await pool.query(`
                UPDATE bookings
                SET payment_status = 'paid',
                    balance_amount = 0,
                    balance_paid_at = NOW(),
                    stripe_payment_intent_id = COALESCE(stripe_payment_intent_id, $2),
                    stripe_charge_id = COALESCE(stripe_charge_id, $3),
                    updated_at = NOW()
                WHERE id = $1
            `, [booking.booking_id, paymentIntent.id, paymentIntent.latest_charge || null]);

            try {
                await pool.query(`
                    INSERT INTO payment_transactions (
                        booking_id, account_id, transaction_type, amount, currency,
                        payment_gateway, gateway_transaction_id, status,
                        payment_method_type, completed_at, description
                    ) VALUES ($1, $2, 'balance', $3, $4, 'stripe', $5, 'completed', 'card', NOW(), $6)
                    ON CONFLICT DO NOTHING
                `, [
                    booking.booking_id, booking.account_id,
                    outstanding, chargeCurrency.toUpperCase(),
                    paymentIntent.id,
                    `Auto-charge Expedia VCC · check-in ${booking.arrival_date}`
                ]);
            } catch (ledgerErr) {
                console.error(`[AUTO-CHARGE EXPEDIA-VCC ledger] booking ${booking.booking_id} pi=${paymentIntent.id}:`, ledgerErr.message);
            }

            console.log(`[AUTO-CHARGE EXPEDIA-VCC] Successfully charged booking ${booking.booking_id} - ${guestName} pi=${paymentIntent.id}`);
        } catch (chargeErr) {
            console.error(`[AUTO-CHARGE EXPEDIA-VCC] booking ${booking.booking_id}:`, chargeErr.message);
            const errCode = chargeErr.code || chargeErr.raw?.code || chargeErr.raw?.decline_code || null;
            const errType = chargeErr.type || chargeErr.raw?.type || null;
            const terminalCodes = new Set([
                'card_declined', 'expired_card', 'insufficient_funds',
                'authentication_required', 'incorrect_cvc', 'processing_error',
                'invalid_account', 'currency_not_supported'
            ]);
            const isTerminal = errCode ? terminalCodes.has(errCode)
                : (errType === 'StripeCardError' || errType === 'card_error');
            await pool.query(
                "UPDATE bookings SET last_charge_error = $2, last_charge_error_code = $3, last_charge_error_at = NOW(), updated_at = NOW()"
                + (isTerminal ? ", payment_status = 'balance_failed'" : '')
                + " WHERE id = $1",
                [booking.booking_id, String(chargeErr.message || '').slice(0, 1000), errCode || errType || 'unknown']
            ).catch(() => {});
            if (isTerminal && booking.owner_email) {
                try {
                    await sendEmail({
                        to: [booking.owner_email, 'development@gas.travel'],
                        subject: `Expedia VCC charge failed — ${guestName} — ${booking.property_name || 'Booking #' + booking.booking_id}`,
                        html: `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
                            <h2 style="color:#dc2626;">Expedia VCC charge failed</h2>
                            <p>An automatic charge on an Expedia Collect VCC could not be completed:</p>
                            <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Guest</td><td style="padding:8px;border:1px solid #e5e7eb;">${guestName}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Property</td><td style="padding:8px;border:1px solid #e5e7eb;">${booking.property_name || '-'}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Booking</td><td style="padding:8px;border:1px solid #e5e7eb;">#${booking.booking_id}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Amount</td><td style="padding:8px;border:1px solid #e5e7eb;">${chargeCurrency.toUpperCase()} ${outstanding.toFixed(2)}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Card</td><td style="padding:8px;border:1px solid #e5e7eb;">${booking.card_brand || '?'} ****${booking.card_last4 || '????'}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Error</td><td style="padding:8px;border:1px solid #e5e7eb;color:#dc2626;">${chargeErr.message}</td></tr>
                            </table>
                            <p style="color:#6b7280;font-size:13px;">Log into Expedia Partner Central for this booking and check the VCC status / charge window. You can retry manually from GAS Admin → Bookings → Take Payment.</p>
                        </div>`
                    });
                } catch (emailErr) {
                    console.error('[AUTO-CHARGE EXPEDIA-VCC email]', emailErr.message);
                }
            }
        }
    }
}

// Chase-until-paid reminder cron. Steve 2026-08-17. Runs hourly; each
// chased booking re-sends every 48h up to 5 times, then auto-stops.
// Started manually by the admin "Send capture link" endpoint. Auto-stops
// silently when payment lands or the booking's arrival passes.
//
// Group bookings: only the LEADER (MIN(id) per group_booking_id) is picked
// so the guest gets ONE reminder for the whole group — not one per room.
// The send-endpoint already sets chase state on all group rows so the
// silent stop conditions (paid, past arrival) apply uniformly.
async function processPaymentChaseReminders() {
    if (String(process.env.PAYMENT_CHASE_PAUSED || '').toLowerCase() === 'true') {
        console.log('[CHASE] paused via PAYMENT_CHASE_PAUSED env var');
        return;
    }

    // Silent auto-stops before we look for due rows.
    try {
        await pool.query(`
            UPDATE bookings
               SET payment_chase_status = 'paid'
             WHERE payment_chase_status = 'chasing'
               AND payment_status IN ('paid','deposit_paid')
        `);
        await pool.query(`
            UPDATE bookings
               SET payment_chase_status = 'stopped'
             WHERE payment_chase_status = 'chasing'
               AND arrival_date <= CURRENT_DATE
        `);
    } catch (e) {
        console.warn('[CHASE] auto-stop update failed:', e.message);
    }

    // Due rows — leader-only for groups; cap at 5 sends.
    let due;
    try {
        due = await pool.query(`
            SELECT b.id, b.group_booking_id, b.guest_id, b.guest_email, b.guest_first_name,
                   b.currency, b.arrival_date, b.property_id, b.balance_amount,
                   b.grand_total, b.deposit_paid,
                   b.payment_chase_send_count
              FROM bookings b
             WHERE b.payment_chase_status = 'chasing'
               AND COALESCE(b.payment_chase_send_count, 0) < 5
               AND (b.payment_chase_last_sent_at IS NULL
                    OR NOW() - b.payment_chase_last_sent_at >= INTERVAL '48 hours')
               AND (b.group_booking_id IS NULL
                    OR b.id = (SELECT MIN(id) FROM bookings WHERE group_booking_id = b.group_booking_id))
             LIMIT 200
        `);
    } catch (e) {
        console.error('[CHASE] due-query failed:', e.message);
        return;
    }

    if (due.rows.length === 0) return;
    console.log(`[CHASE] ${due.rows.length} due reminder(s)`);

    for (const b of due.rows) {
        try {
            if (!b.guest_id || !b.guest_email) {
                await pool.query(`UPDATE bookings SET payment_chase_status='stopped' WHERE id=$1`, [b.id]);
                continue;
            }

            // Extra context — property + account for signature / mailto
            const ctxQ = await pool.query(
                `SELECT p.name AS property_name, p.contact_email AS property_contact_email,
                        p.account_id, a.reply_to_email AS account_reply_to, a.email AS account_email
                   FROM properties p LEFT JOIN accounts a ON a.id = p.account_id
                  WHERE p.id = $1`, [b.property_id]);
            const ctx = ctxQ.rows[0] || {};

            // Group total (same shape as the send endpoint)
            let balance = parseFloat(b.balance_amount || 0);
            let groupSize = 1;
            if (b.group_booking_id) {
                const gr = await pool.query(
                    `SELECT COALESCE(balance_amount, GREATEST(grand_total - COALESCE(deposit_paid, 0), 0)) AS bal
                       FROM bookings WHERE group_booking_id = $1`, [b.group_booking_id]);
                if (gr.rows.length > 0) {
                    balance = gr.rows.reduce((s, r) => s + parseFloat(r.bal || 0), 0);
                    groupSize = gr.rows.length;
                }
            }
            balance = balance.toFixed(2);
            const isGroup = groupSize > 1;
            const currency = b.currency || 'GBP';
            const propertyName = ctx.property_name || 'your stay';
            const sendCount = (b.payment_chase_send_count || 0) + 1;

            // Token
            const guestQ = await pool.query('SELECT magic_link_secret FROM guests WHERE id = $1', [b.guest_id]);
            if (!guestQ.rows[0]) {
                await pool.query(`UPDATE bookings SET payment_chase_status='stopped' WHERE id=$1`, [b.id]);
                continue;
            }
            const token = signGuestToken({
                guestId: b.guest_id,
                bookingId: b.id,
                purpose: GUEST_TOKEN_PURPOSES.CAPTURE_CARD,
                secret: guestQ.rows[0].magic_link_secret
            });
            const baseUrl = process.env.GAS_API_BASE_URL || 'https://admin.gas.travel';
            const captureUrl = `${baseUrl}/card-capture.html#${token}`;

            const bookingsTeamEmail = ctx.property_contact_email || ctx.account_reply_to || ctx.account_email || null;
            const alreadyPaidBlock = bookingsTeamEmail
              ? `<p style="font-size:13px;color:#666;margin-top:20px;">If you have already paid another way, please <a href="mailto:${bookingsTeamEmail}?subject=${encodeURIComponent('Booking payment already made — ' + propertyName)}&body=${encodeURIComponent('Hi,\n\nI have already paid for my booking at ' + propertyName + ' by another method. Please stop the reminder emails.\n\nGuest: ' + (b.guest_first_name || '') + '\nBooking reference: GAS-' + b.id + '\n\nThanks.')}" style="color:#0ea5e9;">click here to contact the booking team</a>.</p>`
              : '';
            const intro = isGroup
              ? `<p>This is a friendly reminder — in order to confirm your booking of <strong>${groupSize} rooms</strong> at <strong>${propertyName}</strong>, could you please follow this link to enter your credit card details.</p>
                 <p>The total of <strong>${currency} ${balance}</strong> will be charged to confirm your booking.</p>`
              : `<p>This is a friendly reminder — please add your card details for your upcoming stay at <strong>${propertyName}</strong>.</p>
                 <p>The balance of <strong>${currency} ${balance}</strong> will be charged before your arrival.</p>`;
            const subject = isGroup
              ? `Reminder: please confirm your booking at ${propertyName}`
              : `Reminder: payment details for your stay at ${propertyName}`;
            const buttonLabel = isGroup ? '💳 Enter card to confirm booking' : '💳 Add my card';
            const signOff = `<p style="margin-top:32px;">Regards,<br>Bookings Manager<br><strong>${propertyName}</strong></p>`;

            const emailR = await sendEmail({
                to: b.guest_email,
                subject,
                html: `<!DOCTYPE html><html><body style="font-family:-apple-system,BlinkMacSystemFont,sans-serif;line-height:1.6;color:#333;max-width:600px;margin:0 auto;padding:40px 20px;">
                    <p>Dear ${b.guest_first_name || 'Guest'},</p>
                    ${intro}
                    <p style="margin: 24px 0;"><a href="${captureUrl}" style="display:inline-block;background:#059669;color:white;padding:14px 28px;text-decoration:none;border-radius:8px;font-weight:500;">${buttonLabel}</a></p>
                    <p style="color:#666;font-size:13px;">Your card details go directly to our secure payment processor — the property never sees or stores your card number.</p>
                    ${alreadyPaidBlock}
                    ${signOff}
                    </body></html>`,
                context: {
                    guestId: b.guest_id,
                    bookingId: b.id,
                    eventType: 'card_capture_link_chase',
                    accountId: ctx.account_id
                }
            });
            if (!emailR.success) {
                console.warn(`[CHASE] send failed booking=${b.id}:`, emailR.error);
                continue;
            }

            // Bump chase state on the leader + all group siblings so
            // send_count caps uniformly across the group.
            await pool.query(`
                UPDATE bookings
                   SET payment_chase_last_sent_at = NOW(),
                       payment_chase_send_count   = COALESCE(payment_chase_send_count, 0) + 1,
                       payment_chase_status       = CASE
                           WHEN COALESCE(payment_chase_send_count, 0) + 1 >= 5 THEN 'stopped'
                           ELSE payment_chase_status END
                 WHERE id = $1
                    OR (group_booking_id IS NOT NULL
                        AND group_booking_id = (SELECT group_booking_id FROM bookings WHERE id = $1))
            `, [b.id]);
            console.log(`[CHASE] sent ${sendCount}/5 to ${b.guest_email} for booking ${b.id}${isGroup ? ` (group of ${groupSize})` : ''}`);
        } catch (e) {
            console.error(`[CHASE] booking ${b.id} failed:`, e.message);
        }
    }
}

async function processAutoChargePayments() {
    // Emergency kill switch — Steve 2026-08-02. Set Railway env var
    // AUTO_CHARGE_PAUSED=true to halt auto-charging estate-wide instantly.
    // Use if a bug like the Janet Emery / Rebecca Dean shape is suspected
    // and you need to pause charges while diagnosing. Unset the var (or set
    // to anything other than 'true') to resume.
    if (String(process.env.AUTO_CHARGE_PAUSED || '').toLowerCase() === 'true') {
        console.warn('[AUTO-CHARGE] PAUSED via AUTO_CHARGE_PAUSED env var — skipping run');
        return;
    }
    console.log('[AUTO-CHARGE] Running balance payment check...');

    // ─── SQUARE BRANCH (added 2026-08-16) ────────────────────────────────
    // Runs BEFORE the Stripe branch so both fire on each cron tick.
    // Fully independent — Stripe code below is untouched. Casa Magnolia is
    // the only Square account today; adding this closes the gap where
    // Square deposits saved a card via the 08-16 fix but no cron ever
    // charged the balance.
    try {
        await _processAutoChargeSquareBranch();
    } catch (sqBranchErr) {
        console.error('[AUTO-CHARGE SQUARE] Branch threw, continuing to Stripe:', sqBranchErr.message);
    }

    // ─── EXPEDIA VCC BRANCH (added 2026-08-17) ───────────────────────────
    // Fires on Channex-imported bookings where ota_payment_collect='ota'
    // (Expedia Collect via VCC — Expedia's own money, funded card). Trigger
    // is the check-in date (Expedia's rule: "charge on the guest's check-in
    // date"), not the standard deposit_rules balance_due_days. Hotel Collect
    // (ota_payment_collect='property') stays manual — those cards are the
    // guest's real personal cards and decline more often (Emma Hope shape).
    try {
        await _processAutoChargeExpediaVCCBranch();
    } catch (vccErr) {
        console.error('[AUTO-CHARGE EXPEDIA-VCC] Branch threw, continuing to Stripe:', vccErr.message);
    }

    try {
        // Match bookings whose trigger date is today OR earlier. The original
        // strict-equality version left bookings stranded any time the cron
        // missed a day (deploy gap, DB outage, Stripe key not yet on the
        // booking) — Lehmann's Travis Biddinger booking 202504 sat overdue
        // 13 days post-trigger until Steve flagged it 2026-06-10. Catch-up
        // with `<=` lets the next run pull every backlog item.
        // Still idempotent: balance_amount > 0 + balance_paid_at IS NULL
        // means once charged, the row drops out of the match set.
        //
        // Original comment: "Match bookings whose trigger date is exactly today. No catch-up:
        // a missed daily run still results in a permanent skip, but operator
        // can manually charge via scripts/manual-charge-balance.js. Catch-up
        // logic is intentionally NOT in this hot-fix because deploying it
        // would auto-charge already-overdue bookings without explicit
        // operator approval.
        //
        // Days-before priority: balance_due_days (the field the UI saves) is
        // the user's intent. auto_charge_days_before is a legacy column that
        // defaulted to 14 and was rarely synced to the UI value — use it
        // only as a last-resort fallback.
        //
        // payment_method filter: card_guarantee uses Enigma (not Stripe),
        // pay_at_property and bank_transfer are out-of-band — none of those
        // should be auto-charged via Stripe regardless of which fields are
        // populated.
        // Rule resolution: prefer the booking's pinned deposit_rule_id (set
        // at booking creation by the rate-aware resolveDepositRule helper).
        // Fall back to the property-or-account default for legacy bookings
        // that pre-date the populate-at-creation fix — and use DISTINCT ON
        // so a multi-rule property never produces duplicate result rows for
        // the same booking.
        //
        // Owner intent: the existence of a basic-mode deposit_rule with a
        // populated balance IS the consent to auto-charge. The legacy
        // dr.auto_charge_balance boolean was a redundant second gate that
        // defaulted to false on rule creation, silently disarming the cron
        // for any account that didn't tick a non-obvious UI toggle. Removed
        // 2026-06-18 — the payment_method NOT IN (...) filter below already
        // excludes card-guarantee / pay-at-property / bank-transfer / enigma.
        //   - schedule_mode != 'schedule' (multi-tier schedules are owned by
        //     processScheduledTierPayments — this cron handles basic mode only)
        const result = await pool.query(`
            SELECT DISTINCT ON (b.id)
                b.id as booking_id,
                p.account_id,
                b.property_id,
                b.guest_first_name,
                b.guest_last_name,
                b.guest_email,
                b.arrival_date,
                b.grand_total,
                b.deposit_amount,
                b.balance_amount,
                b.stripe_payment_method_id,
                b.stripe_payment_intent_id,
                b.stripe_customer_id,
                b.payment_status,
                b.currency,
                COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14) AS effective_days_before,
                dr.auto_charge_balance,
                COALESCE(p.stripe_secret_key, a.stripe_secret_key) as stripe_secret_key,
                b.stripe_setup_intent_id,
                p.currency as property_currency,
                p.name as property_name,
                a.email as owner_email,
                pc.credentials as payment_config_credentials,
                dr.id as deposit_rule_id,
                (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date AS trigger_date
            FROM bookings b
            JOIN properties p ON p.id = b.property_id
            JOIN accounts a ON a.id = p.account_id
            JOIN deposit_rules dr ON dr.id = COALESCE(
                b.deposit_rule_id,
                (
                    SELECT dr2.id FROM deposit_rules dr2
                    WHERE dr2.is_active = true
                      AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                    ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC
                    LIMIT 1
                )
            )
            LEFT JOIN payment_configurations pc ON (pc.property_id = b.property_id OR (pc.property_id IS NULL AND pc.account_id = p.account_id)) AND pc.provider = 'stripe' AND pc.is_enabled = true
            WHERE dr.is_active = true
            AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
            AND b.stripe_payment_method_id IS NOT NULL
            AND b.payment_status != 'paid'
            AND b.balance_amount > 0
            AND b.status NOT IN ('cancelled', 'rejected')
            AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
            AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date <= CURRENT_DATE
            AND b.arrival_date >= CURRENT_DATE
            ${_CRON_EXCLUDE_OTA_SQL}
            ORDER BY b.id, b.arrival_date
        `);

        if (result.rows.length === 0) {
            console.log('[AUTO-CHARGE] No balance payments due today');
            return;
        }

        console.log(`[AUTO-CHARGE] Found ${result.rows.length} bookings to charge`);

        for (const booking of result.rows) {
            // Hoist ledger-derived values so they're accessible AFTER the
            // inner idempotency try-block. Bug caught 2026-08-17 (Tracey /
            // Cotswolds GAS-223885 natasha Jenkins) — previously declared
            // with `const` inside the try block, then referenced outside
            // at the outstanding-amount compute → ReferenceError swallowed
            // by the outer catch, booking marked with last_charge_error
            // "alreadyPaid is not defined" and no charge ever attempted.
            let alreadyPaid = 0;
            let grandTotal = parseFloat(booking.grand_total || 0);
            try {
                // Ledger-based idempotency check (Steve 2026-07-31 — B531014
                // Rebecca Dean triple-charge incident). The date-scoped Stripe
                // idempotency key below is ONLY safe within a single calendar
                // day. If `balance_amount` gets reset > 0 by another actor
                // (Beds24 sync, manual booking edit, another cron) after a
                // successful auto-charge, the next day's cron sees the reset
                // and fires again with a fresh idempotency key — creating a
                // NEW real Stripe charge. WHERE clauses on balance_amount /
                // payment_status alone can't protect against this because the
                // reset happens BETWEEN cron runs.
                //
                // The payment_transactions ledger is the source of truth for
                // "did this booking already receive an auto-charge?". Check
                // it first; if we've already succeeded once, skip regardless
                // of what booking.balance_amount currently says.
                try {
                    // (a) Prior auto-charge for THIS booking — Rebecca Dean shape
                    //     (two successive auto-charge runs on different days).
                    const priorAuto = await pool.query(
                        `SELECT id, gateway_transaction_id, amount, created_at
                           FROM payment_transactions
                          WHERE booking_id = $1
                            AND payment_gateway = 'stripe'
                            AND status IN ('completed','succeeded')
                            AND transaction_type IN ('balance','payment')
                            AND (description LIKE 'Auto-charge balance%' OR description LIKE 'Balance payment%')
                          LIMIT 1`,
                        [booking.booking_id]
                    );
                    if (priorAuto.rows.length > 0) {
                        const p = priorAuto.rows[0];
                        console.warn(`[AUTO-CHARGE] SKIP booking ${booking.booking_id} — already auto-charged (tx ${p.id} pi=${p.gateway_transaction_id} ${p.amount} ${p.created_at.toISOString()}). booking.balance_amount=${booking.balance_amount} looks stale — someone reset it.`);
                        continue;
                    }
                    // (b) Ledger already covers the booking — Janet Emery shape
                    //     (Steve 2026-08-02, B552760 Cotswolds Bear's Cabin). Guest
                    //     was charged the FULL £581 at booking time as a "deposit"
                    //     (empty description), then the auto-charge cron fired 30
                    //     min later and charged £581 AGAIN — because path (a) only
                    //     matches prior AUTO-CHARGES, not prior deposits. Broaden:
                    //     sum every successful stripe payment on this booking. If
                    //     the total already covers the grand_total (rounded to 1c),
                    //     the booking is fully paid — never fire.
                    const priorSumRes = await pool.query(
                        `SELECT COALESCE(SUM(amount), 0)::numeric AS paid
                           FROM payment_transactions
                          WHERE booking_id = $1
                            AND payment_gateway = 'stripe'
                            AND status IN ('completed','succeeded')
                            AND transaction_type IN ('deposit','balance','payment','charge','capture')`,
                        [booking.booking_id]
                    );
                    alreadyPaid = parseFloat(priorSumRes.rows[0]?.paid || 0);
                    // grandTotal already hoisted above from booking.grand_total
                    if (grandTotal > 0 && alreadyPaid + 0.01 >= grandTotal) {
                        console.warn(`[AUTO-CHARGE] SKIP booking ${booking.booking_id} — ledger shows ${alreadyPaid} already paid vs grand_total ${grandTotal}. booking.balance_amount=${booking.balance_amount} is stale. Not firing to avoid Janet Emery-shape double-charge.`);
                        continue;
                    }
                    // (c) Rapid-refire guard. If ANY successful stripe charge on
                    //     this booking landed in the last 24 hours, refuse to
                    //     fire. Steve 2026-08-02 — auto-charge is meant to fire
                    //     N days BEFORE arrival (typically 14-30d), never on the
                    //     same day the deposit was taken. When it does, something
                    //     upstream (bad grand_total, corrupted balance_amount)
                    //     has slipped past (a) and (b). This last belt trusts the
                    //     observation "we charged this card in the last day" and
                    //     stops the double-tap regardless of what the field values
                    //     currently say. Matches Steve's mental model: 'when the
                    //     total is hit, nothing more to charge' — we saw a charge,
                    //     don't fire another same-day.
                    const recentRes = await pool.query(
                        `SELECT id, gateway_transaction_id, amount, created_at
                           FROM payment_transactions
                          WHERE booking_id = $1
                            AND payment_gateway = 'stripe'
                            AND status IN ('completed','succeeded')
                            AND transaction_type IN ('deposit','balance','payment','charge','capture')
                            AND created_at > NOW() - INTERVAL '24 hours'
                          ORDER BY created_at DESC LIMIT 1`,
                        [booking.booking_id]
                    );
                    if (recentRes.rows.length > 0) {
                        const r = recentRes.rows[0];
                        console.warn(`[AUTO-CHARGE] SKIP booking ${booking.booking_id} — stripe charge tx ${r.id} pi=${r.gateway_transaction_id} amount=${r.amount} fired ${r.created_at.toISOString()} (< 24h ago). Refusing to double-tap the same card same-day.`);
                        continue;
                    }
                } catch (idemErr) {
                    // If the idempotency check itself fails, be paranoid and
                    // skip — don't fall through to a charge attempt on a
                    // possibly-already-charged booking.
                    console.error(`[AUTO-CHARGE] Idempotency check failed for booking ${booking.booking_id}, skipping to be safe:`, idemErr.message);
                    continue;
                }

                // Get Stripe key: payment_configurations > property > account > env
                const stripeKey = booking.payment_config_credentials?.secret_key || booking.stripe_secret_key || process.env.STRIPE_SECRET_KEY;
                if (!stripeKey) {
                    console.log(`[AUTO-CHARGE] No Stripe key for booking ${booking.booking_id}, skipping`);
                    continue;
                }
                const stripeClient = require('stripe')(stripeKey);
                const guestName = [booking.guest_first_name, booking.guest_last_name].filter(Boolean).join(' ');
                const chargeCurrency = (booking.currency || booking.property_currency || 'eur').toLowerCase();

                // Resolve Stripe customer (cached → PI → SI → PM → create). Throws if
                // unresolvable so the outer catch records the failure properly.
                const customerResult = await resolveStripeCustomerForBooking(stripeClient, booking, pool);
                const stripeCustomerId = customerResult.customerId;
                console.log(`[AUTO-CHARGE] Booking ${booking.booking_id} customer ${stripeCustomerId} (source: ${customerResult.source})`);

                // Idempotency key: per booking per day. If the cron runs
                // twice in one day (server restart inside the 24h window),
                // Stripe returns the same PaymentIntent rather than charging
                // the customer twice. Cross-day protection is the ledger
                // check at the top of this loop iteration.
                const idempotencyKey = `auto-charge-${booking.booking_id}-${new Date().toISOString().slice(0, 10)}`;
                // Compute the outstanding amount FROM THE LEDGER, not from
                // booking.balance_amount. balance_amount is a snapshot taken
                // at booking creation and never recalculates when extras or
                // taxes get added later — Mornington Rose 2026-08-04, Paul
                // Childerhose / Keith Hanlan / Simon Fisher all under-charged
                // by £33.90 because MAT + HST were added to grand_total AFTER
                // the deposit/balance split was set. grand_total minus the
                // real paid sum is always the correct outstanding number.
                // Cap at 0 so a stale balance_amount that's greater than
                // (grand_total - paid) can never over-charge either.
                const _outstanding = Math.max(
                    0,
                    Math.round((parseFloat(booking.grand_total || 0) - alreadyPaid) * 100) / 100
                );
                if (_outstanding <= 0.005) {
                    console.log(`[AUTO-CHARGE] SKIP booking ${booking.booking_id} — outstanding £${_outstanding.toFixed(2)} (grand ${booking.grand_total} - paid ${alreadyPaid})`);
                    continue;
                }
                console.log(`[AUTO-CHARGE] booking ${booking.booking_id} charging £${_outstanding.toFixed(2)} (grand ${booking.grand_total} - paid ${alreadyPaid}). Stored balance_amount was ${booking.balance_amount}${(Math.abs(_outstanding - parseFloat(booking.balance_amount || 0)) > 0.01 ? ' [STALE — using ledger-derived value]' : '')}`);
                const paymentIntent = await stripeClient.paymentIntents.create({
                    amount: toStripeAmount(_outstanding, chargeCurrency),
                    currency: chargeCurrency,
                    customer: stripeCustomerId,
                    payment_method: booking.stripe_payment_method_id,
                    confirm: true,
                    off_session: true,
                    description: `Balance payment for booking ${booking.booking_id} - ${guestName} - Check-in ${booking.arrival_date}`,
                    metadata: {
                        booking_id: String(booking.booking_id),
                        account_id: String(booking.account_id),
                        type: 'balance_payment',
                        trigger_date: String(booking.trigger_date || ''),
                        days_before: String(booking.effective_days_before || '')
                    }
                }, { idempotencyKey });

                // Any non-succeeded status (requires_action, processing,
                // requires_payment_method, canceled) must surface to the
                // outer catch so the failure is recorded + the owner is
                // notified. Silently skipping is what caused the 2026-05-21
                // incident — see incident report in commit message.
                if (paymentIntent.status !== 'succeeded') {
                    throw new Error(`PaymentIntent status: ${paymentIntent.status} (expected succeeded). PI: ${paymentIntent.id}, last_payment_error: ${paymentIntent.last_payment_error?.message || paymentIntent.last_payment_error?.code || 'none'}`);
                }

                await pool.query(`
                    UPDATE bookings
                    SET payment_status = 'paid',
                        balance_amount = 0,
                        balance_paid_at = NOW(),
                        stripe_payment_intent_id = COALESCE(stripe_payment_intent_id, $2),
                        stripe_charge_id = COALESCE(stripe_charge_id, $3),
                        updated_at = NOW()
                    WHERE id = $1
                `, [booking.booking_id, paymentIntent.id, paymentIntent.latest_charge || null]);

                // Cascade booking_extras (upsells like cleaning/linen fees, pet
                // fees, add-on activities) from status='reserved' → 'paid'.
                // These extras are billed as part of grand_total which is now
                // fully collected; leaving them 'reserved' misled operators
                // (Tracey / Cotswolds Aviva Rauchverger GAS-260425 2026-07-18:
                // booking was fully paid but Reserved extras panel showed the
                // cleaning fee as unpaid). Non-fatal — failure logs loudly.
                try {
                    const upd = await pool.query(
                        `UPDATE booking_extras SET status = 'paid', updated_at = NOW()
                         WHERE booking_id = $1 AND status = 'reserved'`,
                        [booking.booking_id]
                    );
                    if (upd.rowCount > 0) console.log(`[AUTO-CHARGE extras] Flipped ${upd.rowCount} reserved extras → paid for booking ${booking.booking_id}`);
                } catch (extraErr) {
                    console.error(`[AUTO-CHARGE extras] Failed to update extras for booking ${booking.booking_id}:`, extraErr.message);
                }

                // Write to the payment_transactions ledger so the booking view's
                // Payment Ledger + Refund button can see this charge. Skipped
                // this write until 2026-07-17 — the auto-charge cron would
                // succeed silently and the ledger showed "No transactions" for
                // every balance charge, blocking refunds and hiding overpayments
                // from operators. Idempotent via ON CONFLICT on the PI id.
                try {
                    await pool.query(`
                        INSERT INTO payment_transactions (
                            booking_id, account_id, transaction_type, amount, currency,
                            payment_gateway, gateway_transaction_id, status,
                            payment_method_type, completed_at, description
                        ) VALUES ($1, $2, 'balance', $3, $4, 'stripe', $5, 'completed', 'card', NOW(), $6)
                        ON CONFLICT DO NOTHING
                    `, [
                        booking.booking_id, booking.account_id,
                        booking.balance_amount,
                        (booking.currency || booking.property_currency || 'GBP').toUpperCase(),
                        paymentIntent.id,
                        `Auto-charge balance · trigger ${booking.trigger_date} · days_before ${booking.effective_days_before}`
                    ]);
                } catch (ledgerErr) {
                    // Non-fatal — the booking is already marked paid, this just means
                    // the ledger row didn't land. Log loud so a follow-up cron can heal.
                    console.error(`[AUTO-CHARGE ledger] Failed to insert ledger row for booking ${booking.booking_id} pi=${paymentIntent.id}:`, ledgerErr.message);
                }

                console.log(`[AUTO-CHARGE] Successfully charged balance for booking ${booking.booking_id} - ${guestName} pi=${paymentIntent.id}`);

                // Push the payment back to Beds24 so its invoice shows the
                // balance as paid — otherwise the operator sees GAS=paid but
                // Beds24 still shows the balance outstanding (Robert Del
                // Grande GAS-370497 pattern, Steve 2026-07-25 audit).
                // 2026-08-06 — was setImmediate + console.warn. When the push
                // failed (Diane Crawford B243181 5 Aug 07:16), the failure
                // rotated out of Railway logs in 24h and left zero DB trace.
                // Now: awaited so failures land in sync_errors via the helper's
                // own persist logic, AND the cron log shows the outcome. A
                // failed push still doesn't fail the successful Stripe charge
                // — we've already inserted the ledger row and marked paid —
                // but the failure is now visible to operators immediately.
                if (typeof syncBeds24PaymentItem === 'function') {
                    try {
                        const syncResult = await syncBeds24PaymentItem(booking.booking_id);
                        if (syncResult && syncResult.success === false) {
                            console.warn(`[AUTO-CHARGE beds24 sync] booking ${booking.booking_id}: push completed with failures — see bookings.sync_errors`);
                        }
                    } catch (syncErr) {
                        console.warn(`[AUTO-CHARGE beds24 sync] booking ${booking.booking_id} threw: ${syncErr.message}`);
                    }
                }

            } catch (chargeErr) {
                console.error(`[AUTO-CHARGE] Failed to charge booking ${booking.booking_id}:`, chargeErr.message);

                // 2026-08-05 — distinguish transient errors (network blips,
                // Stripe 5xx, rate limits) from terminal card failures.
                // Diane Crawford B243181 flipped balance_failed on a
                // transient blip and never self-healed even though the card
                // was perfectly chargeable — cron caught, marked failed,
                // moved on. New behaviour:
                //   • Terminal errors (card_declined, expired_card,
                //     insufficient_funds, authentication_required) → flip
                //     to balance_failed as before + email owner.
                //   • Transient errors (StripeConnectionError, 5xx,
                //     rate_limit_error, generic network) → leave
                //     payment_status alone so the NEXT hourly cron tick
                //     retries automatically. No owner email — self-heals.
                // Either way, persist the error message + code + timestamp
                // so we can see what actually happened (was losing this in
                // console.error / Railway log buffer scroll).
                const terminalCodes = new Set([
                    'card_declined', 'expired_card', 'insufficient_funds',
                    'authentication_required', 'incorrect_cvc', 'processing_error',
                    'stolen_card', 'lost_card', 'card_not_supported',
                    'invalid_account', 'currency_not_supported'
                ]);
                const errCode = chargeErr.code || chargeErr.raw?.code || chargeErr.raw?.decline_code || null;
                const errType = chargeErr.type || chargeErr.raw?.type || null;
                const isTerminal = errCode ? terminalCodes.has(errCode)
                    : (errType === 'StripeCardError' || errType === 'card_error');
                await pool.query(
                    "UPDATE bookings SET last_charge_error = $2, last_charge_error_code = $3, last_charge_error_at = NOW(), updated_at = NOW()"
                    + (isTerminal ? ", payment_status = 'balance_failed'" : '')
                    + " WHERE id = $1",
                    [booking.booking_id, String(chargeErr.message || '').slice(0, 1000), errCode || errType || 'unknown']
                ).catch(() => {});
                if (!isTerminal) {
                    console.warn(`[AUTO-CHARGE] Transient err on booking ${booking.booking_id} (${errType || 'unknown'}) — payment_status left as-is; next cron tick will retry`);
                    continue;
                }

                // Email notification to property owner
                try {
                    const ownerEmail = booking.owner_email;
                    if (ownerEmail) {
                        await sendEmail({
                            to: [ownerEmail, 'development@gas.travel'],
                            subject: `Balance Payment Failed — ${guestName} — ${booking.property_name || 'Booking #' + booking.booking_id}`,
                            html: `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
                                <h2 style="color:#dc2626;">Balance Payment Failed</h2>
                                <p>An automatic balance payment could not be charged:</p>
                                <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Guest</td><td style="padding:8px;border:1px solid #e5e7eb;">${guestName} (${booking.guest_email})</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Property</td><td style="padding:8px;border:1px solid #e5e7eb;">${booking.property_name || '-'}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Booking Ref</td><td style="padding:8px;border:1px solid #e5e7eb;">#${booking.booking_id}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Balance Amount</td><td style="padding:8px;border:1px solid #e5e7eb;">${chargeCurrency.toUpperCase()} ${parseFloat(booking.balance_amount).toFixed(2)}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Check-in</td><td style="padding:8px;border:1px solid #e5e7eb;">${booking.arrival_date}</td></tr>
                                    <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Error</td><td style="padding:8px;border:1px solid #e5e7eb;color:#dc2626;">${chargeErr.message}</td></tr>
                                </table>
                                <p style="color:#6b7280;font-size:13px;">You can manually charge this balance from GAS Admin → Bookings → Payment Schedule, or contact the guest directly.</p>
                            </div>`
                        });
                        console.log(`[AUTO-CHARGE] Failure notification sent to ${ownerEmail}`);
                    }
                } catch (emailErr) {
                    console.error(`[AUTO-CHARGE] Could not send failure email:`, emailErr.message);
                }

                // Slack notification
                if (process.env.SLACK_WEBHOOK_URL) {
                    try {
                        await axios.post(process.env.SLACK_WEBHOOK_URL, {
                            text: `❌ *Balance Payment Failed*\nBooking #${booking.booking_id} — ${guestName}\nProperty: ${booking.property_name || '-'}\nBalance: ${chargeCurrency.toUpperCase()} ${parseFloat(booking.balance_amount).toFixed(2)}\nCheck-in: ${booking.arrival_date}\nError: ${chargeErr.message}`
                        });
                    } catch (slackErr) { /* ignore */ }
                }
            }
        }

    } catch (err) {
        // Rethrow so runCronIfDue records last_status='error' + last_error text
        // in cron_state. The daily payment digest surfaces stale/errored crons
        // in its heartbeat panel. Prior behaviour swallowed the error, letting
        // a broken query (2026-07-17: DISTINCT ON / ORDER BY mismatch) silently
        // no-op every hourly run for weeks with cron_state still saying
        // last_status='success'. Never again.
        console.error('[AUTO-CHARGE] Error in processAutoChargePayments:', err);
        throw err;
    }
}

// ── Payment Schedule: Multi-tier auto-charge job ──
async function processScheduledTierPayments() {
    console.log('[TIER-CHARGE] Running scheduled tier payment check...');
    try {
        // Find pending tiers due today
        // Multi-tier cron — handles schedule_mode='schedule' only. The JOIN
        // to deposit_rules is scoped via b.deposit_rule_id when set (so
        // retry/max-attempts come from the rule actually applied to the
        // booking), with the legacy property-or-account default as fallback
        // for pre-2026-05-31 bookings whose deposit_rule_id is NULL.
        const result = await pool.query(`
            SELECT
                bps.id as tier_id, bps.tier_order, bps.amount, bps.percentage, bps.booking_id,
                b.guest_first_name, b.guest_last_name, b.guest_email, b.arrival_date,
                b.stripe_payment_method_id, b.stripe_payment_intent_id, b.stripe_setup_intent_id,
                b.stripe_customer_id,
                b.currency, b.property_id, b.grand_total,
                p.account_id, p.name as property_name, p.currency as property_currency,
                a.name as account_name,
                pc.credentials as payment_config_credentials,
                COALESCE(p.stripe_secret_key, a.stripe_secret_key) as stripe_secret_key,
                dr.auto_charge_retry, dr.max_retry_attempts
            FROM booking_payment_schedule bps
            JOIN bookings b ON b.id = bps.booking_id
            JOIN properties p ON p.id = b.property_id
            JOIN accounts a ON a.id = p.account_id
            LEFT JOIN payment_configurations pc ON (pc.property_id = b.property_id OR (pc.property_id IS NULL AND pc.account_id = p.account_id)) AND pc.provider = 'stripe' AND pc.is_enabled = true
            LEFT JOIN deposit_rules dr ON dr.id = COALESCE(
                b.deposit_rule_id,
                (
                    SELECT dr2.id FROM deposit_rules dr2
                    WHERE dr2.is_active = true
                      AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                    ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC
                    LIMIT 1
                )
            )
            WHERE bps.status = 'pending'
            AND bps.due_date <= CURRENT_DATE
            AND b.stripe_payment_method_id IS NOT NULL
            AND b.status NOT IN ('cancelled', 'rejected')
            ORDER BY bps.due_date ASC, bps.tier_order ASC
        `);

        // Also find failed tiers eligible for retry — same rule scoping.
        const retryResult = await pool.query(`
            SELECT
                bps.id as tier_id, bps.tier_order, bps.amount, bps.percentage, bps.booking_id, bps.retry_count,
                b.guest_first_name, b.guest_last_name, b.guest_email, b.arrival_date,
                b.stripe_payment_method_id, b.stripe_payment_intent_id, b.stripe_setup_intent_id,
                b.stripe_customer_id,
                b.currency, b.property_id, b.grand_total,
                p.account_id, p.name as property_name, p.currency as property_currency,
                a.name as account_name,
                pc.credentials as payment_config_credentials,
                COALESCE(p.stripe_secret_key, a.stripe_secret_key) as stripe_secret_key,
                dr.auto_charge_retry, dr.max_retry_attempts
            FROM booking_payment_schedule bps
            JOIN bookings b ON b.id = bps.booking_id
            JOIN properties p ON p.id = b.property_id
            JOIN accounts a ON a.id = p.account_id
            LEFT JOIN payment_configurations pc ON (pc.property_id = b.property_id OR (pc.property_id IS NULL AND pc.account_id = p.account_id)) AND pc.provider = 'stripe' AND pc.is_enabled = true
            JOIN deposit_rules dr ON dr.id = COALESCE(
                b.deposit_rule_id,
                (
                    SELECT dr2.id FROM deposit_rules dr2
                    WHERE dr2.is_active = true
                      AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                    ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC
                    LIMIT 1
                )
            )
            WHERE bps.status = 'failed'
            AND bps.due_date <= CURRENT_DATE
            AND dr.auto_charge_retry = true
            AND bps.retry_count < COALESCE(dr.max_retry_attempts, 3)
            AND b.stripe_payment_method_id IS NOT NULL
            AND b.status NOT IN ('cancelled', 'rejected')
        `);

        const allTiers = [...result.rows, ...retryResult.rows];

        if (allTiers.length === 0) {
            console.log('[TIER-CHARGE] No scheduled tier payments due today');
            return;
        }

        console.log(`[TIER-CHARGE] Found ${result.rows.length} pending + ${retryResult.rows.length} retry tiers to charge`);

        for (const tier of allTiers) {
            try {
                const stripeKey = (tier.payment_config_credentials?.secret_key)
                    || tier.stripe_secret_key || process.env.STRIPE_SECRET_KEY;
                if (!stripeKey) {
                    console.log(`[TIER-CHARGE] No Stripe key for booking ${tier.booking_id} tier ${tier.tier_order}, skipping`);
                    continue;
                }
                const stripeClient = require('stripe')(stripeKey);
                const guestName = [tier.guest_first_name, tier.guest_last_name].filter(Boolean).join(' ');
                const chargeCurrency = (tier.currency || tier.property_currency || 'eur').toLowerCase();

                // Resolve Stripe customer (cached → PI → SI → PM → create). Throws if
                // unresolvable so the outer catch records the failure properly.
                const customerResult = await resolveStripeCustomerForBooking(stripeClient, tier, pool);
                const stripeCustomerId = customerResult.customerId;
                console.log(`[TIER-CHARGE] Booking ${tier.booking_id} tier ${tier.tier_order} customer ${stripeCustomerId} (source: ${customerResult.source})`);

                // Idempotency key: per tier per day. Protects against duplicate
                // charges if the cron fires twice within the same calendar day
                // (e.g. server restart inside the window). Stripe will return
                // the original PaymentIntent rather than creating a new charge.
                const tierIdempotencyKey = `tier-charge-${tier.tier_id}-${new Date().toISOString().slice(0, 10)}`;
                const paymentIntent = await stripeClient.paymentIntents.create({
                    // JPY-aware: scheduled tier charge cron — multiplying
                    // by 100 for JPY/KRW etc. would attempt to charge
                    // 100x the true amount on the saved card. Mountain
                    // Holidays Nest evidence 2026-06-02.
                    amount: toStripeAmount(tier.amount, chargeCurrency),
                    currency: chargeCurrency,
                    customer: stripeCustomerId,
                    payment_method: tier.stripe_payment_method_id,
                    confirm: true,
                    off_session: true,
                    description: `Scheduled payment tier ${tier.tier_order} (${tier.percentage}%) for booking ${tier.booking_id} - ${guestName}`,
                    metadata: { booking_id: String(tier.booking_id), account_id: String(tier.account_id), type: `tier_${tier.tier_order}` }
                }, { idempotencyKey: tierIdempotencyKey });

                // Any non-succeeded status (requires_action, processing,
                // requires_payment_method, canceled) must surface to the
                // outer catch so the failure is recorded + the owner is
                // notified. Silently skipping is what caused the 2026-05-21
                // incident — see incident report in commit message.
                if (paymentIntent.status !== 'succeeded') {
                    throw new Error(`PaymentIntent status: ${paymentIntent.status} (expected succeeded). PI: ${paymentIntent.id}, last_payment_error: ${paymentIntent.last_payment_error?.message || paymentIntent.last_payment_error?.code || 'none'}`);
                }

                // Mark tier as charged
                await pool.query(`
                    UPDATE booking_payment_schedule
                    SET status = 'charged', stripe_payment_intent_id = $1, charged_at = NOW(), error_message = NULL
                    WHERE id = $2
                `, [paymentIntent.id, tier.tier_id]);

                // Log transaction
                await pool.query(`
                    INSERT INTO payment_transactions (booking_id, transaction_type, amount, currency, status, gateway_transaction_id, payment_gateway)
                    VALUES ($1, $2, $3, $4, 'completed', $5, 'stripe')
                `, [tier.booking_id, `tier_${tier.tier_order}`, tier.amount, chargeCurrency, paymentIntent.id]);

                // Check if all tiers now charged
                const remaining = await pool.query(`
                    SELECT COUNT(*) as cnt FROM booking_payment_schedule
                    WHERE booking_id = $1 AND status NOT IN ('charged', 'rolled_up')
                `, [tier.booking_id]);

                if (parseInt(remaining.rows[0].cnt) === 0) {
                    await pool.query(`UPDATE bookings SET payment_status = 'paid', balance_amount = 0, balance_paid_at = NOW() WHERE id = $1`, [tier.booking_id]);
                } else {
                    await pool.query(`UPDATE bookings SET payment_status = 'partial_paid' WHERE id = $1`, [tier.booking_id]);
                }

                console.log(`[TIER-CHARGE] ✓ Charged tier ${tier.tier_order} (${tier.percentage}% = ${tier.amount}) for booking ${tier.booking_id}`);

            } catch (chargeErr) {
                console.error(`[TIER-CHARGE] ✗ Failed tier ${tier.tier_order} for booking ${tier.booking_id}:`, chargeErr.message);

                // Mark tier as failed
                await pool.query(`
                    UPDATE booking_payment_schedule
                    SET status = 'failed', error_message = $1, retry_count = retry_count + 1
                    WHERE id = $2
                `, [chargeErr.message, tier.tier_id]).catch(() => {});

                // Update booking status
                await pool.query(`UPDATE bookings SET payment_status = 'tier_failed' WHERE id = $1`, [tier.booking_id]).catch(() => {});

                // ── Failed payment notification: email to property owner ──
                try {
                    const guestName = [tier.guest_first_name, tier.guest_last_name].filter(Boolean).join(' ');
                    const ownerEmailResult = await pool.query(`SELECT email FROM accounts WHERE id = $1`, [tier.account_id]);
                    const ownerEmail = ownerEmailResult.rows[0]?.email;
                    if (ownerEmail) {
                        await sendEmail({
                            to: [ownerEmail, 'development@gas.travel'],
                            subject: `⚠️ Scheduled Payment Failed — ${guestName} — ${tier.property_name}`,
                            html: `
                                <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
                                    <h2 style="color:#dc2626;">⚠️ Scheduled Payment Failed</h2>
                                    <p>A scheduled payment tier could not be charged:</p>
                                    <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Guest</td><td style="padding:8px;border:1px solid #e5e7eb;">${guestName} (${tier.guest_email})</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Property</td><td style="padding:8px;border:1px solid #e5e7eb;">${tier.property_name}</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Booking Ref</td><td style="padding:8px;border:1px solid #e5e7eb;">#${tier.booking_id}</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Tier</td><td style="padding:8px;border:1px solid #e5e7eb;">${tier.tier_order} of schedule (${tier.percentage}%)</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Amount</td><td style="padding:8px;border:1px solid #e5e7eb;">${tier.amount} ${(tier.currency || tier.property_currency || 'EUR').toUpperCase()}</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Check-in</td><td style="padding:8px;border:1px solid #e5e7eb;">${tier.arrival_date}</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Error</td><td style="padding:8px;border:1px solid #e5e7eb;color:#dc2626;">${chargeErr.message}</td></tr>
                                        <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Retry</td><td style="padding:8px;border:1px solid #e5e7eb;">${tier.auto_charge_retry ? `Will retry (attempt ${(tier.retry_count || 0) + 1} of ${tier.max_retry_attempts || 3})` : 'No auto-retry — manual action required'}</td></tr>
                                    </table>
                                    <p style="color:#6b7280;font-size:13px;">You can manually charge this tier from GAS Admin → Bookings → Payment Schedule.</p>
                                </div>
                            `
                        });
                        console.log(`[TIER-CHARGE] Failure notification sent to ${ownerEmail}`);
                    }
                } catch (emailErr) {
                    console.log(`[TIER-CHARGE] Could not send failure email:`, emailErr.message);
                }

                // ── Failed payment notification: Slack webhook ──
                if (process.env.SLACK_WEBHOOK_URL) {
                    try {
                        const guestName = [tier.guest_first_name, tier.guest_last_name].filter(Boolean).join(' ');
                        await require('axios').post(process.env.SLACK_WEBHOOK_URL, {
                            text: `❌ *Scheduled Payment Failed*\nBooking #${tier.booking_id} — ${guestName}\nProperty: ${tier.property_name}\nTier ${tier.tier_order} (${tier.percentage}%) — ${tier.amount} ${(tier.currency || 'EUR').toUpperCase()}\nError: ${chargeErr.message}`
                        });
                    } catch (slackErr) { /* ignore */ }
                }
            }
        }

    } catch (err) {
        console.error('[TIER-CHARGE] Error in processScheduledTierPayments:', err);
    }
}

// ── 2-day-ahead ATTENTION DEPOSIT DUE warning ──
// Hourly scan for any auto-charge (basic-mode balance OR scheduled-tier)
// that will fire in exactly 2 days. One email per booking/tier, idempotent
// via *_warning_sent_at columns. Gives Steve + the property owner time to
// disable a rule / cancel / contact the guest before money moves.
async function processBalanceChargeWarnings() {
    console.log('[WARN-2D] Scanning for charges firing in 2 days...');
    try {
        const platformAlertEmail = process.env.PLATFORM_ALERT_EMAIL || 'development@gas.travel';

        // Basic-mode bookings whose two-step balance cron will fire on (today + 2).
        // Same JOIN/COALESCE/filters as processAutoChargePayments so we never
        // warn about a charge that won't actually happen.
        const basicRows = await pool.query(`
            SELECT DISTINCT ON (b.id)
                b.id as booking_id,
                b.guest_first_name, b.guest_last_name, b.guest_email,
                b.arrival_date, b.balance_amount, b.currency,
                b.stripe_payment_method_id,
                p.id as property_id, p.name as property_name, p.currency as property_currency,
                p.account_id,
                a.email as owner_email,
                dr.id as rule_id, dr.balance_due_days, dr.deposit_percentage,
                (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date AS trigger_date
            FROM bookings b
            JOIN properties p ON p.id = b.property_id
            JOIN accounts a ON a.id = p.account_id
            JOIN deposit_rules dr ON dr.id = COALESCE(
                b.deposit_rule_id,
                (
                    SELECT dr2.id FROM deposit_rules dr2
                    WHERE dr2.is_active = true
                      AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                    ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC
                    LIMIT 1
                )
            )
            WHERE dr.is_active = true
              AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
              AND b.stripe_payment_method_id IS NOT NULL
              AND b.payment_status != 'paid'
              AND b.balance_amount > 0
              AND b.status NOT IN ('cancelled', 'rejected')
              AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
              AND b.balance_warning_sent_at IS NULL
              AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date = (CURRENT_DATE + INTERVAL '2 days')::date
            ORDER BY b.id
        `);

        // Multi-tier rows due in exactly 2 days.
        const tierRows = await pool.query(`
            SELECT
                bps.id as tier_id, bps.tier_order, bps.percentage, bps.amount, bps.due_date,
                b.id as booking_id,
                b.guest_first_name, b.guest_last_name, b.guest_email,
                b.arrival_date, b.currency,
                p.id as property_id, p.name as property_name, p.currency as property_currency,
                p.account_id,
                a.email as owner_email
            FROM booking_payment_schedule bps
            JOIN bookings b ON b.id = bps.booking_id
            JOIN properties p ON p.id = b.property_id
            JOIN accounts a ON a.id = p.account_id
            WHERE bps.status = 'pending'
              AND bps.warning_sent_at IS NULL
              AND b.stripe_payment_method_id IS NOT NULL
              AND b.status NOT IN ('cancelled', 'rejected')
              AND bps.due_date = (CURRENT_DATE + INTERVAL '2 days')::date
            ORDER BY b.id, bps.tier_order
        `);

        const total = basicRows.rows.length + tierRows.rows.length;
        if (total === 0) {
            console.log('[WARN-2D] No charges due in 2 days');
            return;
        }
        console.log(`[WARN-2D] ${basicRows.rows.length} balance + ${tierRows.rows.length} tier charges due in 2 days`);

        for (const row of basicRows.rows) {
            try {
                const guestName = [row.guest_first_name, row.guest_last_name].filter(Boolean).join(' ');
                const ccy = (row.currency || row.property_currency || 'EUR').toUpperCase();
                const arrival = row.arrival_date instanceof Date ? row.arrival_date.toISOString().slice(0, 10) : String(row.arrival_date).slice(0, 10);
                const trigger = row.trigger_date instanceof Date ? row.trigger_date.toISOString().slice(0, 10) : String(row.trigger_date).slice(0, 10);
                const recipients = [platformAlertEmail];
                if (row.owner_email && row.owner_email !== platformAlertEmail) recipients.unshift(row.owner_email);

                await sendEmail({
                    to: recipients,
                    subject: `ATTENTION DEPOSIT DUE — ${guestName} — ${row.property_name || 'Booking #' + row.booking_id}`,
                    html: `
                        <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
                            <h2 style="color:#b45309;">⚠️ ATTENTION: Balance auto-charge in 2 days</h2>
                            <p>This is a 48-hour heads-up. The balance for this booking is scheduled to be charged automatically to the guest's saved card on <strong>${trigger}</strong>.</p>
                            <p>If anything's wrong (amount, card, refund request, cancellation, rule mis-configured), act before that date.</p>
                            <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Guest</td><td style="padding:8px;border:1px solid #e5e7eb;">${guestName} (${row.guest_email || ''})</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Property</td><td style="padding:8px;border:1px solid #e5e7eb;">${row.property_name || '-'}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Booking Ref</td><td style="padding:8px;border:1px solid #e5e7eb;">#${row.booking_id}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Amount to be charged</td><td style="padding:8px;border:1px solid #e5e7eb;font-size:18px;color:#b45309;font-weight:bold;">${ccy} ${parseFloat(row.balance_amount).toFixed(2)}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Charge date</td><td style="padding:8px;border:1px solid #e5e7eb;">${trigger}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Arrival</td><td style="padding:8px;border:1px solid #e5e7eb;">${arrival}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Rule applied</td><td style="padding:8px;border:1px solid #e5e7eb;">#${row.rule_id} (${row.deposit_percentage}% deposit, balance ${row.balance_due_days || 'n/a'} days before arrival)</td></tr>
                            </table>
                            <p style="color:#6b7280;font-size:13px;">If this charge should NOT fire, disable auto-charge on the rule in GAS Admin → Property Settings → Payments, or refund/cancel the booking before ${trigger}.</p>
                        </div>
                    `
                });
                await pool.query('UPDATE bookings SET balance_warning_sent_at = NOW() WHERE id = $1', [row.booking_id]);
                console.log(`[WARN-2D] ✉ Sent balance warning for booking ${row.booking_id} (${ccy} ${row.balance_amount})`);
            } catch (e) {
                console.error(`[WARN-2D] Failed sending balance warning for ${row.booking_id}:`, e.message);
            }
        }

        for (const row of tierRows.rows) {
            try {
                const guestName = [row.guest_first_name, row.guest_last_name].filter(Boolean).join(' ');
                const ccy = (row.currency || row.property_currency || 'EUR').toUpperCase();
                const due = row.due_date instanceof Date ? row.due_date.toISOString().slice(0, 10) : String(row.due_date).slice(0, 10);
                const arrival = row.arrival_date instanceof Date ? row.arrival_date.toISOString().slice(0, 10) : String(row.arrival_date).slice(0, 10);
                const recipients = [platformAlertEmail];
                if (row.owner_email && row.owner_email !== platformAlertEmail) recipients.unshift(row.owner_email);

                await sendEmail({
                    to: recipients,
                    subject: `ATTENTION DEPOSIT DUE — ${guestName} — ${row.property_name || 'Booking #' + row.booking_id} (Tier ${row.tier_order})`,
                    html: `
                        <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
                            <h2 style="color:#b45309;">⚠️ ATTENTION: Scheduled tier charge in 2 days</h2>
                            <p>This is a 48-hour heads-up. A scheduled payment tier on this booking will be auto-charged on <strong>${due}</strong>.</p>
                            <p>If anything's wrong (amount, card, refund, cancellation, schedule mis-configured), act before that date.</p>
                            <table style="width:100%;border-collapse:collapse;margin:16px 0;">
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Guest</td><td style="padding:8px;border:1px solid #e5e7eb;">${guestName} (${row.guest_email || ''})</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Property</td><td style="padding:8px;border:1px solid #e5e7eb;">${row.property_name || '-'}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Booking Ref</td><td style="padding:8px;border:1px solid #e5e7eb;">#${row.booking_id}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Tier</td><td style="padding:8px;border:1px solid #e5e7eb;">${row.tier_order} (${row.percentage}%)</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Amount to be charged</td><td style="padding:8px;border:1px solid #e5e7eb;font-size:18px;color:#b45309;font-weight:bold;">${ccy} ${parseFloat(row.amount).toFixed(2)}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Charge date</td><td style="padding:8px;border:1px solid #e5e7eb;">${due}</td></tr>
                                <tr><td style="padding:8px;border:1px solid #e5e7eb;font-weight:bold;">Arrival</td><td style="padding:8px;border:1px solid #e5e7eb;">${arrival}</td></tr>
                            </table>
                            <p style="color:#6b7280;font-size:13px;">If this charge should NOT fire, edit/disable the schedule tier in GAS Admin → Bookings → Payment Schedule before ${due}.</p>
                        </div>
                    `
                });
                await pool.query('UPDATE booking_payment_schedule SET warning_sent_at = NOW() WHERE id = $1', [row.tier_id]);
                console.log(`[WARN-2D] ✉ Sent tier warning for booking ${row.booking_id} tier ${row.tier_order} (${ccy} ${row.amount})`);
            } catch (e) {
                console.error(`[WARN-2D] Failed sending tier warning for ${row.tier_id}:`, e.message);
            }
        }
    } catch (err) {
        console.error('[WARN-2D] Error in processBalanceChargeWarnings:', err);
    }
}

// Daily morning digest of platform-wide auto-charge state. Lands every 24h
// at development@gas.travel so a missed/failed/silenced cron is visible
// within a day instead of the 15-day silence caught 2026-06-18.
//
// Sections: charges scheduled today, succeeded yesterday, failed yesterday,
// upcoming next 48h. Plus cron heartbeat from cron_state so a dead cron
// shows itself in the digest even when no bookings are eligible.
async function processDailyPaymentDigest(opts = {}) {
    const { previewOnly = false } = opts;
    try {
        const digestEmail = process.env.PAYMENT_DIGEST_EMAIL || 'development@gas.travel';

        // Cron pulse — show every cron in cron_state and when it last ran.
        // A "due" cron whose last_completed_at is older than the interval
        // is a red flag.
        const pulse = await pool.query(`
            SELECT name, interval_seconds, last_completed_at, last_status, last_error, run_count
              FROM cron_state ORDER BY name`);

        // Scheduled to fire today — same filter as processAutoChargePayments
        // but with trigger_date = today specifically.
        const scheduledToday = await pool.query(`
            SELECT b.id AS booking_id, b.guest_first_name, b.guest_last_name,
                   b.balance_amount, b.currency, b.arrival_date, p.name AS property_name,
                   p.account_id, a.name AS account_name
              FROM bookings b
              JOIN properties p ON p.id = b.property_id
              JOIN accounts a ON a.id = p.account_id
              JOIN deposit_rules dr ON dr.id = COALESCE(b.deposit_rule_id,
                (SELECT dr2.id FROM deposit_rules dr2
                  WHERE dr2.is_active = true
                    AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                  ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC LIMIT 1))
             WHERE dr.is_active = true
               AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
               AND b.stripe_payment_method_id IS NOT NULL
               AND b.payment_status != 'paid' AND b.balance_amount > 0
               AND b.status NOT IN ('cancelled','rejected')
               AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
               AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date = CURRENT_DATE
             ORDER BY p.account_id, b.id`);

        // Successfully charged in the previous 24h — pulled from the
        // payment_transactions table (single source of truth for money
        // movement). Covers auto-charges, manual admin charges, guest
        // direct-book captures, deposit + balance + capture types.
        // Previous query only counted deferred balance charges
        // (balance_paid_at > deposit_paid_at + 1 day) so same-day full
        // payments and manual charges were invisible. Steve 2026-07-14.
        const succeeded = await pool.query(`
            SELECT pt.id AS tx_id, pt.booking_id, pt.transaction_type,
                   pt.amount, pt.currency, pt.created_at AS charged_at,
                   pt.gateway_transaction_id, pt.payment_gateway,
                   b.guest_first_name, b.guest_last_name,
                   b.arrival_date,
                   p.name AS property_name, a.name AS account_name
              FROM payment_transactions pt
              LEFT JOIN bookings b ON b.id = pt.booking_id
              LEFT JOIN properties p ON p.id = b.property_id
              LEFT JOIN accounts a ON a.id = p.account_id
             WHERE pt.created_at >= NOW() - INTERVAL '24 hours'
               AND pt.status IN ('completed','succeeded','captured')
               AND pt.transaction_type IN ('deposit','balance','charge','capture','payment')
               AND pt.amount > 0
               AND pt.payment_gateway IN ('stripe','channex')
             ORDER BY pt.created_at DESC`);

        // Failures in the last 24h
        const failed = await pool.query(`
            SELECT b.id AS booking_id, b.guest_first_name, b.guest_last_name,
                   b.balance_amount, b.currency, b.arrival_date, b.updated_at,
                   p.name AS property_name, a.name AS account_name
              FROM bookings b
              JOIN properties p ON p.id = b.property_id
              JOIN accounts a ON a.id = p.account_id
             WHERE b.payment_status = 'balance_failed'
               AND b.updated_at >= NOW() - INTERVAL '24 hours'
             ORDER BY b.updated_at DESC`);

        // Coming up next 48h
        const upcoming = await pool.query(`
            SELECT b.id AS booking_id, b.guest_first_name, b.guest_last_name,
                   b.balance_amount, b.currency, b.arrival_date,
                   p.name AS property_name, a.name AS account_name,
                   (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date AS trigger_date
              FROM bookings b
              JOIN properties p ON p.id = b.property_id
              JOIN accounts a ON a.id = p.account_id
              JOIN deposit_rules dr ON dr.id = COALESCE(b.deposit_rule_id,
                (SELECT dr2.id FROM deposit_rules dr2
                  WHERE dr2.is_active = true
                    AND (dr2.property_id = b.property_id OR (dr2.property_id IS NULL AND dr2.account_id = p.account_id))
                  ORDER BY (dr2.property_id IS NOT NULL) DESC, dr2.created_at DESC LIMIT 1))
             WHERE dr.is_active = true
               AND (dr.schedule_mode IS NULL OR dr.schedule_mode != 'schedule')
               AND b.stripe_payment_method_id IS NOT NULL
               AND b.payment_status != 'paid' AND b.balance_amount > 0
               AND b.status NOT IN ('cancelled','rejected')
               AND (b.payment_method IS NULL OR b.payment_method NOT IN ('card_guarantee','pay_at_property','bank_transfer','enigma'))
               AND (b.arrival_date - INTERVAL '1 day' * COALESCE(dr.balance_due_days, dr.auto_charge_days_before, 14))::date BETWEEN (CURRENT_DATE + INTERVAL '1 day')::date AND (CURRENT_DATE + INTERVAL '2 days')::date
             ORDER BY trigger_date, b.id`);

        const fmtMoney = (amt, ccy) => `${(ccy || 'GBP').toUpperCase()} ${parseFloat(amt || 0).toFixed(2)}`;
        const fmtDate = (d) => d ? (d instanceof Date ? d : new Date(d)).toISOString().slice(0,10) : '-';
        const row = (cells) => `<tr>${cells.map(c => `<td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${c}</td>`).join('')}</tr>`;

        const section = (title, rows, columns) => {
            if (rows.length === 0) return `<h3 style="margin:24px 0 8px;color:#475569;">${title}</h3><p style="color:#94a3b8;margin:0;">None</p>`;
            const headers = columns.map(c => `<th style="text-align:left;padding:6px 10px;border-bottom:2px solid #cbd5e1;font-size:12px;text-transform:uppercase;color:#64748b;">${c}</th>`).join('');
            return `<h3 style="margin:24px 0 8px;color:#475569;">${title} (${rows.length})</h3><table style="width:100%;border-collapse:collapse;font-size:14px;"><thead><tr>${headers}</tr></thead><tbody>${rows.join('')}</tbody></table>`;
        };

        const pulseRows = pulse.rows.map(r => {
            const ageMin = r.last_completed_at ? Math.round((Date.now() - new Date(r.last_completed_at).getTime()) / 60000) : null;
            const overdue = r.last_completed_at && ageMin > (r.interval_seconds / 60) * 1.5;
            const statusColour = r.last_status === 'error' ? '#b91c1c' : (overdue ? '#b45309' : '#047857');
            const statusText = r.last_status === 'error' ? `ERROR: ${(r.last_error || '').slice(0,140)}` : (overdue ? `STALE — last ran ${ageMin}min ago (interval ${Math.round(r.interval_seconds/60)}min)` : 'OK');
            return row([r.name, `${ageMin != null ? ageMin + ' min ago' : 'never'}`, `<span style="color:${statusColour};font-weight:600;">${statusText}</span>`, r.run_count]);
        });

        const html = `
            <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:780px;margin:0 auto;color:#0f172a;">
                <h2 style="color:#0f172a;border-bottom:3px solid #635bff;padding-bottom:8px;">GAS Daily Payment Digest — ${fmtDate(new Date())}</h2>
                <p style="color:#64748b;">Auto-charge cron health + last 24 hours of platform payment activity.</p>

                <h3 style="margin:24px 0 8px;color:#475569;">Cron heartbeat</h3>
                <table style="width:100%;border-collapse:collapse;font-size:14px;">
                    <thead><tr>
                        <th style="text-align:left;padding:6px 10px;border-bottom:2px solid #cbd5e1;font-size:12px;text-transform:uppercase;color:#64748b;">Cron</th>
                        <th style="text-align:left;padding:6px 10px;border-bottom:2px solid #cbd5e1;font-size:12px;text-transform:uppercase;color:#64748b;">Last run</th>
                        <th style="text-align:left;padding:6px 10px;border-bottom:2px solid #cbd5e1;font-size:12px;text-transform:uppercase;color:#64748b;">Health</th>
                        <th style="text-align:left;padding:6px 10px;border-bottom:2px solid #cbd5e1;font-size:12px;text-transform:uppercase;color:#64748b;">Runs</th>
                    </tr></thead>
                    <tbody>${pulseRows.join('')}</tbody>
                </table>

                ${section('🔴 Failures in last 24 hours — NEEDS ACTION',
                    failed.rows.map(r => row([`#${r.booking_id}`, `${r.guest_first_name||''} ${r.guest_last_name||''}`, r.account_name, fmtMoney(r.balance_amount, r.currency), fmtDate(r.arrival_date)])),
                    ['Booking','Guest','Account','Balance','Arrival'])}

                ${section('🟢 Charged successfully in last 24 hours',
                    succeeded.rows.map(r => row([
                        r.booking_id ? `#${r.booking_id}` : '-',
                        `${r.guest_first_name||''} ${r.guest_last_name||''}`.trim() || '-',
                        r.account_name || '-',
                        `<span style="text-transform:capitalize;padding:2px 8px;background:#e0e7ff;border-radius:999px;font-size:12px;">${r.transaction_type}</span>`,
                        fmtMoney(r.amount, r.currency),
                        r.gateway_transaction_id ? `<code style="font-size:11px;color:#64748b;">${r.gateway_transaction_id.slice(0,24)}</code>` : '-'
                    ])),
                    ['Booking','Guest','Account','Type','Amount','TX'])}

                ${section('🟠 Scheduled to auto-charge today',
                    scheduledToday.rows.map(r => row([`#${r.booking_id}`, `${r.guest_first_name||''} ${r.guest_last_name||''}`, r.account_name, fmtMoney(r.balance_amount, r.currency), fmtDate(r.arrival_date)])),
                    ['Booking','Guest','Account','Balance','Arrival'])}

                ${section('🟡 Upcoming auto-charges (next 48 hours)',
                    upcoming.rows.map(r => row([`#${r.booking_id}`, `${r.guest_first_name||''} ${r.guest_last_name||''}`, r.account_name, fmtMoney(r.balance_amount, r.currency), fmtDate(r.trigger_date)])),
                    ['Booking','Guest','Account','Balance','Trigger'])}

                <p style="margin-top:32px;color:#94a3b8;font-size:12px;">Auto-generated by processDailyPaymentDigest. To stop receiving, change PAYMENT_DIGEST_EMAIL.</p>
            </div>`;

        const allClear = failed.rows.length === 0 && scheduledToday.rows.length === 0;
        const subject = failed.rows.length > 0
            ? `🔴 GAS Payments — ${failed.rows.length} failure${failed.rows.length>1?'s':''} in last 24h`
            : (scheduledToday.rows.length > 0
                ? `GAS Payments — ${scheduledToday.rows.length} charge${scheduledToday.rows.length>1?'s':''} scheduled today`
                : 'GAS Payments — All clear');

        if (previewOnly) {
            return { subject, html, counts: { failed: failed.rows.length, succeeded: succeeded.rows.length, scheduledToday: scheduledToday.rows.length, upcoming: upcoming.rows.length } };
        }
        await sendEmail({ to: [digestEmail], subject, html });
        console.log(`[DIGEST] Sent payment digest to ${digestEmail} — failed:${failed.rows.length} succeeded:${succeeded.rows.length} today:${scheduledToday.rows.length} upcoming:${upcoming.rows.length}`);
    } catch (err) {
        console.error('[DIGEST] processDailyPaymentDigest:', err);
        throw err;  // let runCronIfDue record the failure
    }
}

// GET /api/admin/bookings/:id/diagnose
// Master-only. One-shot dump of everything relevant to a booking:
// the row, its availability_calendar footprint, any beds24_outbox
// entries for the same room in overlapping dates, sync state.
// Steve 2026-07-14 — GAS-294592 not showing on calendar + not pushed
// to Beds24.
app.get('/api/admin/bookings/:id/diagnose', async (req, res) => {
  try {
    const decoded = await requireMasterAdmin(req, res);
    if (!decoded) return;
    const bookingId = parseInt(req.params.id, 10);
    if (!bookingId) return res.json({ success: false, error: 'invalid booking id' });

    const booking = await pool.query(
      `SELECT b.*, p.name AS property_name, p.account_id, a.name AS account_name,
              bu.name AS room_name
         FROM bookings b
    LEFT JOIN properties p ON p.id = b.property_id
    LEFT JOIN accounts a ON a.id = p.account_id
    LEFT JOIN bookable_units bu ON bu.id = b.room_id
        WHERE b.id = $1`,
      [bookingId]
    );
    if (!booking.rows[0]) return res.json({ success: false, error: 'booking not found' });
    const b = booking.rows[0];

    // Availability_calendar rows spanning the stay dates for this room.
    const cal = await pool.query(
      `SELECT date, source, units_consumed, booking_id, notes
         FROM availability_calendar
        WHERE room_id = $1
          AND date >= $2 AND date < $3
        ORDER BY date`,
      [b.room_id, b.arrival_date, b.departure_date]
    );

    // Beds24 sync connection on this account
    const conn = await pool.query(
      `SELECT id, adapter_code, status, last_sync_at, last_error, credentials
         FROM gas_sync_connections
        WHERE account_id = $1 AND adapter_code IN ('beds24','beds24-marketplace')
        ORDER BY id DESC LIMIT 1`,
      [b.account_id]
    );

    // Beds24 outbox entries touching this room's arrival window
    let outbox = { rows: [] };
    try {
      outbox = await pool.query(
        `SELECT id, kind, room_id, start_date, end_date, status, attempts, last_error, created_at, sent_at
           FROM beds24_outbox
          WHERE room_id = $1
            AND (start_date <= $3 AND end_date >= $2)
          ORDER BY id DESC LIMIT 20`,
        [b.room_id, b.arrival_date, b.departure_date]
      );
    } catch (e) { outbox = { rows: [], error: e.message }; }

    res.json({
      success: true,
      booking: {
        id: b.id,
        reference: 'GAS-' + b.id,
        source: b.booking_source,
        status: b.status,
        payment_status: b.payment_status,
        guest: (b.guest_first_name || '') + ' ' + (b.guest_last_name || ''),
        arrival: b.arrival_date,
        departure: b.departure_date,
        account_id: b.account_id,
        account_name: b.account_name,
        property_id: b.property_id,
        property_name: b.property_name,
        room_id: b.room_id,
        room_name: b.room_name,
        beds24_booking_id: b.beds24_booking_id || null,
        created_at: b.created_at
      },
      availability_calendar: {
        rows_found: cal.rows.length,
        expected_nights: Math.round((new Date(b.departure_date) - new Date(b.arrival_date)) / 86400000),
        entries: cal.rows
      },
      beds24_connection: conn.rows[0] || null,
      beds24_outbox: {
        entries: outbox.rows,
        error: outbox.error || null
      }
    });
  } catch (e) {
    console.error('[booking diagnose]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

