// Persistent cron scheduler. The old setTimeout(5min) + setInterval(60min)
// pattern was unreliable on Railway: with frequent redeploys the process
// rarely stayed alive long enough for the hourly tick to fire, so balance
// auto-charges silently stopped running (15+ days of zero attempts caught
// 2026-06-18 — Lehmann + Mornington Rose bookings sat overdue).
//
// New pattern: every 2 minutes we ask the DB "is this cron due?" — i.e. has
// it been >= interval_seconds since last_completed_at. If yes, mark running,
// invoke, record outcome. Surviving across restarts because the schedule
// state lives in cron_state, not in the process.
//
// All three functions are idempotent — same booking on the same day returns
// the original Stripe PaymentIntent rather than double-charging.
async function runCronIfDue(name, intervalSeconds, fn) {
    const now = Date.now();
    const state = await pool.query(
        'SELECT last_completed_at, last_started_at, last_status FROM cron_state WHERE name = $1',
        [name]
    ).then(r => r.rows[0]).catch(() => null);

    if (state) {
        // Skip if another instance is mid-run (within a 30-minute stuck threshold)
        if (state.last_status === 'running' && state.last_started_at) {
            const sinceStart = now - state.last_started_at.getTime();
            if (sinceStart < 30 * 60 * 1000) return;
            console.log(`[CRON ${name}] previous run stuck ${Math.round(sinceStart/60000)}m — overriding`);
        }
        if (state.last_completed_at) {
            const sinceLast = now - state.last_completed_at.getTime();
            if (sinceLast < intervalSeconds * 1000) return; // not due yet
        }
    }

    await pool.query(`
        INSERT INTO cron_state (name, interval_seconds, last_started_at, last_status)
        VALUES ($1, $2, NOW(), 'running')
        ON CONFLICT (name) DO UPDATE SET
            interval_seconds = $2,
            last_started_at = NOW(),
            last_status = 'running',
            updated_at = NOW()
    `, [name, intervalSeconds]).catch(() => {});

    console.log(`[CRON ${name}] starting`);
    try {
        await fn();
        await pool.query(`
            UPDATE cron_state
               SET last_completed_at = NOW(),
                   last_status = 'success',
                   last_error = NULL,
                   run_count = run_count + 1,
                   updated_at = NOW()
             WHERE name = $1
        `, [name]).catch(() => {});
        console.log(`[CRON ${name}] success`);
    } catch (e) {
        await pool.query(`
            UPDATE cron_state
               SET last_completed_at = NOW(),
                   last_status = 'error',
                   last_error = $2,
                   run_count = run_count + 1,
                   updated_at = NOW()
             WHERE name = $1
        `, [name, String(e.message || e).slice(0, 1000)]).catch(() => {});
        console.error(`[CRON ${name}] FAILED:`, e.message);
    }
}

// Channex outbox drain. Replaces the old setInterval-based worker in
// gas-sync/channex-outbox.js:startChannexOutboxWorker (which died
// silently on Railway redeploy). Each tick loops drain() until the
// queue is empty OR a 45-second budget elapses — whichever comes
// first. Under normal load a healthy queue drains to zero every run;
// during a backlog (like the 1.4M rows on Charles House 2026-07-20)
// each tick chews through as many batches as fits in 45s and picks up
// where it left off on the next tick.
async function processChannexOutbox() {
    const { drain } = require('./gas-sync/channex-outbox');
    const deadline = Date.now() + 45 * 1000;
    let totalDrained = 0;
    let totalBatches = 0;
    let passes = 0;
    while (Date.now() < deadline) {
        const { drained, batches } = await drain(pool);
        totalDrained += drained;
        totalBatches += batches;
        passes++;
        if (drained === 0) break; // nothing left OR everything backed off
    }
    if (totalDrained > 0) {
        console.log(`[processChannexOutbox] passes=${passes} drained=${totalDrained} batches=${totalBatches}`);
    }
}

// Beds24 outbox drain. Mirror of processChannexOutbox above — same
// setInterval-death anti-pattern was in gas-sync/beds24-outbox.js's
// startBeds24OutboxWorker. Loop drain() with a 45s per-tick budget;
// registered at 60s interval so the 2-min fireDueCrons poll drives it.
async function processBeds24Outbox() {
    const { drain } = require('./gas-sync/beds24-outbox');
    const deadline = Date.now() + 45 * 1000;
    let totalDrained = 0;
    let totalBatches = 0;
    let passes = 0;
    while (Date.now() < deadline) {
        const { drained, batches } = await drain(pool);
        totalDrained += drained;
        totalBatches += batches;
        passes++;
        if (drained === 0) break;
    }
    if (totalDrained > 0) {
        console.log(`[processBeds24Outbox] passes=${passes} drained=${totalDrained} batches=${totalBatches}`);
    }
}

// =====================================================
// CHANNEX WRITE-BACK DAILY DIGEST — Steve 2026-07-28 after $1000
// double-booking. Runs once every 24h and emails a per-account health
// summary so Steve knows every day that the write-back is alive. Also
// exposed on-demand via GET /api/admin/channex/writeback-health.
//
// Per Channex-connected account, the last 24h:
//   - bookings received (via webhook OR direct GAS book)
//   - outbox rows: succeeded / failed / still-pending
//   - oldest pending row age (= worst-case double-booking window right now)
//   - config drift: sync_enabled=false while status=connected
//
// Loud alert (RED) fires when ANY connection has failures OR pending
// rows > 5 min old. Green summary when all clear.
// =====================================================
async function buildChannexWriteBackHealth() {
  const rows = await pool.query(`
    WITH conns AS (
      SELECT c.id AS connection_id, c.account_id, c.status, c.sync_enabled,
             a.name AS account_name, c.external_account_name
        FROM gas_sync_connections c
        LEFT JOIN accounts a ON a.id = c.account_id
       WHERE c.adapter_code = 'channex'
    ),
    bookings_24h AS (
      SELECT c.connection_id, COUNT(DISTINCT b.id)::int AS bookings_created
        FROM conns c
        JOIN gas_sync_room_types gsrt ON gsrt.connection_id = c.connection_id
        JOIN bookings b ON b.bookable_unit_id = gsrt.gas_room_id
       WHERE b.created_at >= NOW() - INTERVAL '24 hours'
       GROUP BY c.connection_id
    ),
    outbox_24h AS (
      SELECT connection_id,
             COUNT(*) FILTER (WHERE status = 'succeeded')::int AS ok,
             COUNT(*) FILTER (WHERE status = 'failed')::int AS failed,
             COUNT(*) FILTER (WHERE status = 'pending')::int AS pending,
             MAX(EXTRACT(EPOCH FROM (NOW() - created_at))) FILTER (WHERE status = 'pending')::int AS oldest_pending_sec
        FROM gas_channex_outbox
       WHERE created_at >= NOW() - INTERVAL '24 hours'
       GROUP BY connection_id
    )
    SELECT c.*, COALESCE(b.bookings_created, 0) AS bookings_created,
           COALESCE(o.ok, 0) AS pushed_ok,
           COALESCE(o.failed, 0) AS pushed_failed,
           COALESCE(o.pending, 0) AS pushed_pending,
           COALESCE(o.oldest_pending_sec, 0) AS oldest_pending_sec
      FROM conns c
      LEFT JOIN bookings_24h b ON b.connection_id = c.connection_id
      LEFT JOIN outbox_24h o ON o.connection_id = c.connection_id
     ORDER BY c.account_id
  `);
  const summary = { total_accounts: rows.rows.length, healthy: 0, config_drift: 0, has_failures: 0, has_stuck_pending: 0 };
  const accounts = rows.rows.map(r => {
    const configDrift = r.status === 'connected' && !r.sync_enabled;
    const hasFailures = r.pushed_failed > 0;
    const hasStuck = r.oldest_pending_sec > 300; // > 5 min old
    const healthy = !configDrift && !hasFailures && !hasStuck;
    if (healthy) summary.healthy++;
    if (configDrift) summary.config_drift++;
    if (hasFailures) summary.has_failures++;
    if (hasStuck) summary.has_stuck_pending++;
    return {
      account_id: r.account_id, account_name: r.account_name || r.external_account_name || '?',
      connection_id: r.connection_id, status: r.status, sync_enabled: r.sync_enabled,
      bookings_created_24h: r.bookings_created,
      pushed_ok: r.pushed_ok, pushed_failed: r.pushed_failed, pushed_pending: r.pushed_pending,
      oldest_pending_sec: r.oldest_pending_sec,
      healthy, config_drift: configDrift, has_failures: hasFailures, has_stuck_pending: hasStuck,
    };
  });
  return { summary, accounts, generated_at: new Date().toISOString() };
}

async function processChannexWriteBackDigest() {
  try {
    const health = await buildChannexWriteBackHealth();
    const anyRed = health.summary.config_drift + health.summary.has_failures + health.summary.has_stuck_pending > 0;
    const emoji = anyRed ? '🔴' : '🟢';
    const subject = `${emoji} Channex Write-Back Daily — ${health.summary.healthy}/${health.summary.total_accounts} healthy`;
    const rowsHtml = health.accounts.map(a => {
      const flag = a.healthy ? '🟢' : (a.config_drift || a.has_failures ? '🔴' : '🟡');
      const issues = [
        a.config_drift ? 'sync_enabled=false' : null,
        a.has_failures ? `${a.pushed_failed} failed` : null,
        a.has_stuck_pending ? `stuck ${Math.round(a.oldest_pending_sec / 60)}m` : null,
      ].filter(Boolean).join(', ') || '—';
      return `<tr>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${flag}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${a.account_id}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${a.account_name}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;">${a.bookings_created_24h}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;">${a.pushed_ok}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;color:${a.pushed_failed ? '#dc2626' : '#111'};">${a.pushed_failed}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;color:${a.has_stuck_pending ? '#dc2626' : '#111'};">${a.pushed_pending}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;color:${a.healthy ? '#059669' : '#dc2626'};">${issues}</td>
      </tr>`;
    }).join('');
    const html = `<div style="font-family:Arial,sans-serif;max-width:900px;margin:0 auto;">
      <h2 style="color:${anyRed ? '#dc2626' : '#059669'};">${emoji} Channex Write-Back Health — last 24h</h2>
      <p><strong>${health.summary.healthy}</strong> of <strong>${health.summary.total_accounts}</strong> accounts healthy.
         Config drift: <strong>${health.summary.config_drift}</strong>.
         Failures: <strong>${health.summary.has_failures}</strong>.
         Stuck pending: <strong>${health.summary.has_stuck_pending}</strong>.</p>
      ${anyRed ? '<p style="color:#dc2626;font-weight:bold;">🚨 Action required — see red rows below. Double-booking risk on any account with failures or stuck pending.</p>' : '<p style="color:#059669;">All write-backs firing cleanly. Nothing to do.</p>'}
      <table style="width:100%;border-collapse:collapse;font-size:0.9rem;margin-top:1rem;">
        <thead><tr style="background:#f8fafc;">
          <th style="padding:8px 10px;text-align:left;">​</th>
          <th style="padding:8px 10px;text-align:left;">Acct</th>
          <th style="padding:8px 10px;text-align:left;">Name</th>
          <th style="padding:8px 10px;text-align:right;">Bookings 24h</th>
          <th style="padding:8px 10px;text-align:right;">Pushed OK</th>
          <th style="padding:8px 10px;text-align:right;">Failed</th>
          <th style="padding:8px 10px;text-align:right;">Pending</th>
          <th style="padding:8px 10px;text-align:left;">Issues</th>
        </tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>
      <p style="color:#94a3b8;font-size:0.85rem;margin-top:1.5rem;">
        On-demand JSON: <a href="https://admin.gas.travel/api/admin/channex/writeback-health">https://admin.gas.travel/api/admin/channex/writeback-health</a><br>
        Generated ${health.generated_at}
      </p>
    </div>`;
    await sendEmail({ to: ['rezintelhelp@gmail.com', 'development@gas.travel'], subject, html });
    console.log(`[channex-writeback-digest] sent — ${health.summary.healthy}/${health.summary.total_accounts} healthy, redFlag=${anyRed}`);
  } catch (e) {
    console.error('[channex-writeback-digest]', e.message);
  }
}

app.get('/api/admin/channex/writeback-health', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded || decoded.role !== 'master_admin') return res.status(403).json({ success: false, error: 'Master admin only' });
    const health = await buildChannexWriteBackHealth();
    res.json({ success: true, ...health });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// =====================================================
// COMMS HEALTH DIGEST — Steve 2026-08-02 (Lehmann silent workflow incident).
// Lehmann's wf42/wf43 (welcome + upsell) silently flipped is_active=false at
// 16 Jul 15:00 UTC on a Marie save — no comms fired for 17 days. Same
// footgun would hit Steve's own gîtes (wf47/48 = door codes) on any careless
// save. This digest catches silent regressions early: any account that took
// bookings but sent no emails, any workflow_run failure, any guest comm
// failure. Same daily-email pattern as the Channex + Hostfully digests.
// =====================================================
async function buildCommsHealth() {
  // Only report on accounts that have at least one workflow OR sent comms in
  // the last 30 days. Everyone else is silent by design and would just add
  // noise to the digest.
  const rows = await pool.query(`
    WITH active_accts AS (
      SELECT DISTINCT account_id FROM workflows
      UNION
      SELECT DISTINCT b.property_id AS account_id
        FROM guest_communications gc
        JOIN bookings b ON b.id = gc.booking_id
       WHERE gc.created_at > NOW() - INTERVAL '30 days'
    ),
    accts AS (
      SELECT a.id AS account_id, a.name AS account_name
        FROM accounts a
       WHERE a.id IN (
         SELECT account_id FROM workflows
         UNION
         SELECT p.account_id
           FROM guest_communications gc
           JOIN bookings b ON b.id = gc.booking_id
           JOIN properties p ON p.id = b.property_id
          WHERE gc.created_at > NOW() - INTERVAL '30 days'
       )
    ),
    wf_counts AS (
      SELECT account_id,
             COUNT(*)::int AS wf_total,
             COUNT(*) FILTER (WHERE is_active = true)::int AS wf_active,
             COUNT(*) FILTER (WHERE is_active = true AND trigger_type LIKE 'booking.%')::int AS wf_active_booking_trg
        FROM workflows GROUP BY account_id
    ),
    bookings_24h AS (
      SELECT p.account_id, COUNT(*)::int AS bookings_created
        FROM bookings b
        JOIN properties p ON p.id = b.property_id
       WHERE b.created_at >= NOW() - INTERVAL '24 hours'
         AND b.status IN ('confirmed','pending')
       GROUP BY p.account_id
    ),
    runs_24h AS (
      SELECT account_id,
             COUNT(*) FILTER (WHERE status = 'sent')::int AS runs_sent,
             COUNT(*) FILTER (WHERE status = 'failed')::int AS runs_failed,
             COUNT(*) FILTER (WHERE status = 'skipped')::int AS runs_skipped
        FROM workflow_runs
       WHERE created_at >= NOW() - INTERVAL '24 hours'
       GROUP BY account_id
    ),
    comms_24h AS (
      SELECT p.account_id,
             COUNT(*) FILTER (WHERE gc.status = 'sent')::int AS comms_sent,
             COUNT(*) FILTER (WHERE gc.status = 'failed')::int AS comms_failed
        FROM guest_communications gc
        LEFT JOIN bookings b ON b.id = gc.booking_id
        LEFT JOIN properties p ON p.id = b.property_id
       WHERE gc.created_at >= NOW() - INTERVAL '24 hours'
         AND gc.direction = 'outbound'
       GROUP BY p.account_id
    )
    SELECT a.account_id, a.account_name,
           COALESCE(w.wf_total, 0)               AS wf_total,
           COALESCE(w.wf_active, 0)              AS wf_active,
           COALESCE(w.wf_active_booking_trg, 0)  AS wf_active_booking_trg,
           COALESCE(b.bookings_created, 0)       AS bookings_created,
           COALESCE(r.runs_sent, 0)              AS runs_sent,
           COALESCE(r.runs_failed, 0)            AS runs_failed,
           COALESCE(r.runs_skipped, 0)           AS runs_skipped,
           COALESCE(c.comms_sent, 0)             AS comms_sent,
           COALESCE(c.comms_failed, 0)           AS comms_failed
      FROM accts a
      LEFT JOIN wf_counts w  ON w.account_id = a.account_id
      LEFT JOIN bookings_24h b ON b.account_id = a.account_id
      LEFT JOIN runs_24h r   ON r.account_id = a.account_id
      LEFT JOIN comms_24h c  ON c.account_id = a.account_id
     ORDER BY a.account_id
  `);

  const summary = { total_accounts: rows.rows.length, healthy: 0,
                    silent_with_bookings: 0, all_inactive: 0,
                    has_failed_runs: 0, has_failed_sends: 0 };
  const accounts = rows.rows.map(r => {
    // Red flags. Order matters — most severe first for the digest badge.
    // silent_with_bookings is the Lehmann incident shape exactly: bookings
    // came in, we had workflows configured, but zero booking-triggered ones
    // were active so nothing fired. all_inactive is the same shape without
    // the "we took bookings today" filter (still worth flagging so you notice
    // during a quiet week).
    const hasWorkflows        = r.wf_total > 0;
    const allInactive         = hasWorkflows && r.wf_active === 0;
    const silentWithBookings  = r.bookings_created > 0 && r.wf_active_booking_trg === 0 && hasWorkflows;
    const hasFailedRuns       = r.runs_failed > 0;
    const hasFailedSends      = r.comms_failed > 0;
    const anyRed = silentWithBookings || hasFailedRuns || hasFailedSends;
    const healthy = !anyRed && !allInactive;
    if (healthy) summary.healthy++;
    if (silentWithBookings) summary.silent_with_bookings++;
    if (allInactive) summary.all_inactive++;
    if (hasFailedRuns) summary.has_failed_runs++;
    if (hasFailedSends) summary.has_failed_sends++;
    return {
      account_id: r.account_id, account_name: r.account_name,
      workflows_total: r.wf_total, workflows_active: r.wf_active, workflows_active_booking_triggered: r.wf_active_booking_trg,
      bookings_created_24h: r.bookings_created,
      runs_sent_24h: r.runs_sent, runs_failed_24h: r.runs_failed, runs_skipped_24h: r.runs_skipped,
      comms_sent_24h: r.comms_sent, comms_failed_24h: r.comms_failed,
      healthy, silent_with_bookings: silentWithBookings, all_inactive: allInactive,
      has_failed_runs: hasFailedRuns, has_failed_sends: hasFailedSends,
    };
  });
  return { summary, accounts, generated_at: new Date().toISOString() };
}

async function processCommsDigest() {
  try {
    const health = await buildCommsHealth();
    const anyRed = health.summary.silent_with_bookings + health.summary.has_failed_runs + health.summary.has_failed_sends > 0;
    const anyAmber = health.summary.all_inactive > 0;
    const emoji = anyRed ? '🔴' : (anyAmber ? '🟡' : '🟢');
    const subject = `${emoji} Comms Health Daily — ${health.summary.healthy}/${health.summary.total_accounts} healthy`;
    const rowsHtml = health.accounts.map(a => {
      const flag = a.silent_with_bookings || a.has_failed_runs || a.has_failed_sends ? '🔴'
                 : a.all_inactive ? '🟡'
                 : '🟢';
      const issues = [
        a.silent_with_bookings ? `${a.bookings_created_24h} bookings but no active booking-workflow` : null,
        a.all_inactive          ? 'all workflows inactive' : null,
        a.has_failed_runs       ? `${a.runs_failed_24h} run failures` : null,
        a.has_failed_sends      ? `${a.comms_failed_24h} send failures` : null,
      ].filter(Boolean).join(', ') || '—';
      const colorFail = (n) => n > 0 ? '#dc2626' : '#111';
      const colorGood = a.healthy ? '#059669' : '#dc2626';
      return `<tr>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${flag}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${a.account_id}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;">${a.account_name || ''}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;">${a.bookings_created_24h}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;">${a.workflows_active}/${a.workflows_total}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;">${a.runs_sent_24h}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;color:${colorFail(a.runs_failed_24h)};">${a.runs_failed_24h}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;">${a.comms_sent_24h}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;text-align:right;color:${colorFail(a.comms_failed_24h)};">${a.comms_failed_24h}</td>
        <td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;color:${colorGood};">${issues}</td>
      </tr>`;
    }).join('');
    const html = `<div style="font-family:Arial,sans-serif;max-width:1000px;margin:0 auto;">
      <h2 style="color:${anyRed ? '#dc2626' : (anyAmber ? '#b45309' : '#059669')};">${emoji} Comms Health — last 24h</h2>
      <p><strong>${health.summary.healthy}</strong> of <strong>${health.summary.total_accounts}</strong> accounts healthy.
         Silent-with-bookings: <strong>${health.summary.silent_with_bookings}</strong>.
         All workflows inactive: <strong>${health.summary.all_inactive}</strong>.
         Run failures: <strong>${health.summary.has_failed_runs}</strong>.
         Send failures: <strong>${health.summary.has_failed_sends}</strong>.</p>
      ${anyRed ? '<p style="color:#dc2626;font-weight:bold;">🚨 Action required — guests may not be receiving welcome / upsell / door-code emails. Check red rows.</p>'
        : anyAmber ? '<p style="color:#b45309;">Amber rows have all workflows off — safe today but nothing will fire when bookings come in.</p>'
        : '<p style="color:#059669;">All workflows firing cleanly. Nothing to do.</p>'}
      <table style="width:100%;border-collapse:collapse;font-size:0.9rem;margin-top:1rem;">
        <thead><tr style="background:#f8fafc;">
          <th style="padding:8px 10px;text-align:left;">​</th>
          <th style="padding:8px 10px;text-align:left;">Acct</th>
          <th style="padding:8px 10px;text-align:left;">Name</th>
          <th style="padding:8px 10px;text-align:right;">Bookings 24h</th>
          <th style="padding:8px 10px;text-align:right;">WFs Active/Total</th>
          <th style="padding:8px 10px;text-align:right;">Runs Sent</th>
          <th style="padding:8px 10px;text-align:right;">Runs Failed</th>
          <th style="padding:8px 10px;text-align:right;">Comms Sent</th>
          <th style="padding:8px 10px;text-align:right;">Comms Failed</th>
          <th style="padding:8px 10px;text-align:left;">Issues</th>
        </tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>
      <p style="color:#94a3b8;font-size:0.85rem;margin-top:1.5rem;">
        On-demand JSON: <a href="https://admin.gas.travel/api/admin/comms/health">https://admin.gas.travel/api/admin/comms/health</a><br>
        Generated ${health.generated_at}
      </p>
    </div>`;
    await sendEmail({ to: ['rezintelhelp@gmail.com', 'development@gas.travel'], subject, html });
    console.log(`[comms-digest] sent — ${health.summary.healthy}/${health.summary.total_accounts} healthy, redFlag=${anyRed}, amber=${anyAmber}`);
  } catch (e) {
    console.error('[comms-digest]', e.message);
  }
}

app.get('/api/admin/comms/health', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded || decoded.role !== 'master_admin') return res.status(403).json({ success: false, error: 'Master admin only' });
    const health = await buildCommsHealth();
    res.json({ success: true, ...health });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// =====================================================
// CONTRACTS — Steve 2026-08-03 (Phase 1 shipped). E-signature +
// deposit link + bank details for long-stay bookings (French cure,
// villas, corporate lets, etc.).
//
// - contract_templates: reusable HTML with {{merge}} tokens
// - contract_instances: one per booking, holds sign state + audit
// - account_contract_settings: per-account landlord + IBAN
//
// Legal foundation: eIDAS Simple Electronic Signature. We capture
// signature drawing (PNG dataURL) + typed "Lu et approuvé" (or EN
// equiv) + IP + user agent + timestamp. Sufficient for tenancy
// contracts in EU/UK/US.
//
// PDF generation: attempted via puppeteer-core + @sparticuz/chromium
// on Railway. If chromium install fails at runtime, we fall back to
// storing the signed HTML and letting the guest print-to-PDF in the
// browser. Either way the signed HTML is stored, auditable, and
// emailed to both parties.
// =====================================================

// Merge {{path.to.value}} tokens in an HTML template against a full
// context object hydrated from booking + guest + property + room +
// account + account_contract_settings + contract_instance-specific
// values (sign URL, deposit URL, expiry date).
async function contractsHydrateContext(pool, bookingId, contractInstance = null) {
  const b = await pool.query(`
    SELECT b.*, p.name AS prop_name, p.address AS prop_address,
           p.city AS prop_city, p.country AS prop_country, p.owner_id AS prop_owner_id,
           p.guest_info AS prop_guest_info,
           bu.name AS unit_name, bu.description AS unit_description,
           bu.max_guests AS unit_max_guests, bu.bedrooms AS unit_bedrooms,
           bu.bathrooms AS unit_bathrooms, bu.size_sqm AS unit_size_sqm,
           bu.amenities AS unit_amenities, bu.guest_info AS unit_guest_info,
           p.account_id AS acc_id, a.name AS acc_name, a.email AS acc_email
      FROM bookings b
      LEFT JOIN bookable_units bu ON bu.id = b.bookable_unit_id
      LEFT JOIN properties p ON p.id = b.property_id
      LEFT JOIN accounts a ON a.id = p.account_id
     WHERE b.id = $1`, [bookingId]);
  if (!b.rows[0]) throw new Error('booking not found');
  const bk = b.rows[0];

  // Fallback chain for landlord fields — owner > account settings > empty.
  // Owner is the "bailleur" for legal purposes; account settings only used
  // when the operator hasn't set up owners yet (solo-owner case).
  const acctS = await pool.query(`SELECT * FROM account_contract_settings WHERE account_id = $1`, [bk.acc_id]);
  const acct = acctS.rows[0] || {};
  let owner = null;
  if (bk.prop_owner_id) {
    const oR = await pool.query(`SELECT * FROM property_owners WHERE id = $1 AND is_active = true`, [bk.prop_owner_id]);
    owner = oR.rows[0] || null;
  }
  const pick = (field) => (owner && owner[field] != null && owner[field] !== '' ? owner[field]
                       : (acct[field] != null && acct[field] !== '' ? acct[field] : ''));
  // Owner uses a leaner column set than account_contract_settings ("name"
  // instead of "landlord_name"). Map to the same keys the template expects.
  const settings = {
    landlord_name: (owner && owner.name) || acct.landlord_name || '',
    landlord_company: (owner && owner.company) || acct.landlord_company || '',
    landlord_address: (owner && owner.address) || acct.landlord_address || '',
    landlord_postcode: (owner && owner.postcode) || acct.landlord_postcode || '',
    landlord_city: (owner && owner.city) || acct.landlord_city || '',
    landlord_country: (owner && owner.country) || acct.landlord_country || '',
    landlord_phone: (owner && owner.phone) || acct.landlord_phone || '',
    landlord_email: (owner && owner.email) || acct.landlord_email || '',
    landlord_siret: (owner && owner.siret) || acct.landlord_siret || '',
    tourist_let_reg: (owner && owner.tourist_let_reg) || acct.tourist_let_reg || '',
    iban: (owner && owner.iban) || acct.iban || '',
    bic: (owner && owner.bic) || acct.bic || '',
    bank_account_name: (owner && owner.bank_account_name) || acct.bank_account_name || '',
    default_security_deposit: (owner && owner.default_security_deposit != null ? owner.default_security_deposit
                              : acct.default_security_deposit),
    default_cleaning_fee: (owner && owner.default_cleaning_fee != null ? owner.default_cleaning_fee
                          : acct.default_cleaning_fee),
    default_tourist_tax_per_person_per_night: (owner && owner.default_tourist_tax_per_person_per_night != null
                                              ? owner.default_tourist_tax_per_person_per_night
                                              : acct.default_tourist_tax_per_person_per_night),
  };

  const arrivalDate = bk.arrival_date ? new Date(bk.arrival_date) : null;
  const departureDate = bk.departure_date ? new Date(bk.departure_date) : null;
  const nights = arrivalDate && departureDate
    ? Math.round((departureDate - arrivalDate) / 86400000)
    : bk.nights_count || 0;

  const fmtDate = (d, lang = 'fr') => d ? new Intl.DateTimeFormat(lang === 'fr' ? 'fr-FR' : 'en-GB', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
  }).format(d) : '';

  const currency = bk.currency || 'EUR';
  const fmtMoney = (amt) => amt != null && !isNaN(parseFloat(amt))
    ? `${parseFloat(amt).toFixed(2)} ${currency === 'EUR' ? '€' : currency}` : '';

  const baseUrl = process.env.PUBLIC_URL || 'https://admin.gas.travel';
  const signUrl = contractInstance?.sign_token
    ? `${baseUrl}/contract/sign/${contractInstance.sign_token}` : '';
  const depositUrl = contractInstance?.sign_token
    ? `${baseUrl}/contract/pay/${contractInstance.sign_token}` : '';

  // Public room URL — prefer the operator's own domain if they've set a
  // custom_domain, else the auto-generated site_url. No dates or guests —
  // info page only so the guest can't accidentally re-book on top of
  // themselves. Falls back to empty if no deployed site.
  let roomPublicUrl = '';
  try {
    const ds = await pool.query(
      `SELECT custom_domain, site_url FROM deployed_sites
        WHERE account_id = $1
          AND (property_id = $2 OR property_ids @> to_jsonb($2::int))
        ORDER BY id LIMIT 1`,
      [bk.acc_id, bk.property_id]
    );
    let host = '';
    if (ds.rows[0]) {
      host = ds.rows[0].custom_domain || ds.rows[0].site_url || '';
    }
    if (!host) {
      const anyDs = await pool.query(
        `SELECT custom_domain, site_url FROM deployed_sites
          WHERE account_id = $1 ORDER BY id LIMIT 1`, [bk.acc_id]);
      if (anyDs.rows[0]) host = anyDs.rows[0].custom_domain || anyDs.rows[0].site_url || '';
    }
    if (host && bk.bookable_unit_id) {
      const h = host.startsWith('http') ? host : `https://${host}`;
      roomPublicUrl = `${h.replace(/\/$/, '')}/room/?unit_id=${bk.bookable_unit_id}`;
    }
  } catch (_) { /* soft-fail — link just won't render */ }

  return {
    booking: {
      id: bk.id,
      reference: `GAS-${bk.id}`,
      arrival_date: fmtDate(arrivalDate, 'fr'),
      arrival_date_en: fmtDate(arrivalDate, 'en'),
      departure_date: fmtDate(departureDate, 'fr'),
      departure_date_en: fmtDate(departureDate, 'en'),
      nights: nights,
      weeks: nights > 0 ? Math.round(nights / 7) : 0,
      num_adults: bk.num_adults || 1,
      num_children: bk.num_children || 0,
      total_guests: bk.total_guests || (bk.num_adults || 1) + (bk.num_children || 0),
      grand_total: fmtMoney(bk.grand_total),
      grand_total_raw: bk.grand_total,
      deposit_amount: fmtMoney(bk.deposit_amount),
      deposit_amount_raw: bk.deposit_amount,
      balance_amount: fmtMoney(bk.balance_amount),
      balance_amount_raw: bk.balance_amount,
      currency,
      special_requests: bk.special_requests || '',
    },
    guest: {
      title: bk.guest_title || '',
      first_name: bk.guest_first_name || '',
      last_name: bk.guest_last_name || '',
      full_name: [bk.guest_first_name, bk.guest_last_name].filter(Boolean).join(' '),
      email: bk.guest_email || '',
      phone: bk.guest_phone || '',
      address: bk.guest_address || '',
      city: bk.guest_city || '',
      postcode: bk.guest_postcode || '',
      country: bk.guest_country || '',
    },
    property: {
      name: bk.prop_name || '',
      address: bk.prop_address || '',
      city: bk.prop_city || '',
      country: bk.prop_country || '',
    },
    room: {
      name: bk.unit_name || '',
      description: bk.unit_description || '',
      max_guests: bk.unit_max_guests || '',
      bedrooms: bk.unit_bedrooms || '',
      bathrooms: bk.unit_bathrooms || '',
      size: bk.unit_size_sqm ? `${bk.unit_size_sqm} m²` : '',
      public_url: roomPublicUrl,
    },
    account: {
      name: bk.acc_name || '',
      email: bk.acc_email || '',
    },
    landlord: {
      name: settings.landlord_name || bk.acc_name || '',
      company: settings.landlord_company || '',
      address: settings.landlord_address || '',
      postcode: settings.landlord_postcode || '',
      city: settings.landlord_city || '',
      country: settings.landlord_country || '',
      phone: settings.landlord_phone || '',
      email: settings.landlord_email || bk.acc_email || '',
      siret: settings.landlord_siret || '',
      tourist_let_reg: settings.tourist_let_reg || '',
      iban: settings.iban || '',
      bic: settings.bic || '',
      bank_account_name: settings.bank_account_name || '',
      signature: (owner && owner.signature_data_url) || acct.signature_data_url || '',
    },
    contract: {
      sign_url: signUrl,
      deposit_url: depositUrl,
      today: fmtDate(new Date(), 'fr'),
      today_en: fmtDate(new Date(), 'en'),
    },
    security_deposit: fmtMoney(settings.default_security_deposit),
    cleaning_fee: fmtMoney(settings.default_cleaning_fee),
    // Taxe de séjour — rate + computed total for this booking. Tax is
    // typically paid on arrival in cash, so it's shown separately and NOT
    // rolled into grand_total. If Steve later moves this into the taxes
    // module we swap the source here without touching the template.
    tourist_tax: settings.default_tourist_tax_per_person_per_night != null
      ? `${parseFloat(settings.default_tourist_tax_per_person_per_night).toFixed(2)} €` : '',
    tourist_tax_total: (() => {
      const rate = parseFloat(settings.default_tourist_tax_per_person_per_night);
      const adults = parseInt(bk.num_adults, 10) || 0;
      if (!rate || !adults || !nights) return '';
      return `${(rate * adults * nights).toFixed(2)} €`;
    })(),
    tourist_tax_breakdown: (() => {
      const rate = parseFloat(settings.default_tourist_tax_per_person_per_night);
      const adults = parseInt(bk.num_adults, 10) || 0;
      if (!rate || !adults || !nights) return '';
      return `${adults} adulte${adults > 1 ? 's' : ''} × ${nights} nuit${nights > 1 ? 's' : ''} × ${rate.toFixed(2)} €`;
    })(),
    // Guest info (parking, keys, wifi, check-in etc.) — room-first
    // fallback to property-level. Templates use {{guest_info.parking.text}}
    // etc. Same shape available to pre-arrival workflows so ONE edit in
    // the Guest Info Editor updates the contract AND the pre-arrival email.
    guest_info: contractsMergeGuestInfo(bk.prop_guest_info, bk.unit_guest_info),
  };
}

// Substitute {{path.to.value}} tokens in an HTML template with values
// from a nested context object. Missing tokens render as empty string.
// Also supports {{#path.to.value}}…{{/path.to.value}} conditional blocks
// (show inner content only when the path resolves to a truthy value).
// Nested blocks not supported — keep templates flat.
function contractsRenderTemplate(html, ctx) {
  const resolve = (path) => {
    let cur = ctx;
    for (const seg of path.split('.')) {
      if (cur == null) return null;
      cur = cur[seg];
    }
    return cur;
  };
  // Pass 1 — conditional blocks {{#path}}…{{/path}}. Remove the block
  // entirely if the path is falsy/empty; keep inner content otherwise.
  const blockRe = /\{\{#\s*([\w.]+)\s*\}\}([\s\S]*?)\{\{\/\s*\1\s*\}\}/g;
  let out = html.replace(blockRe, (_, path, inner) => {
    const v = resolve(path);
    const truthy = v != null && v !== '' && v !== false && v !== 0 && v !== '0';
    return truthy ? inner : '';
  });
  // Pass 2 — simple {{a.b.c}} substitution
  out = out.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, path) => {
    const v = resolve(path);
    return v == null ? '' : String(v);
  });
  return out;
}

// POST /api/admin/bookings/:id/contract-preview — { template_id }
// Returns the FILLED HTML for a booking + template pair without touching
// the DB. Powers the operator preview modal before hitting Send.
app.post('/api/admin/bookings/:id/contract-preview', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const bookingId = parseInt(req.params.id, 10);
    const templateId = parseInt(req.body?.template_id, 10);
    if (!bookingId || !templateId) return res.status(400).json({ success: false, error: 'booking_id + template_id required' });
    const b = await pool.query(`SELECT b.id, b.guest_email, b.guest_first_name, b.guest_last_name, p.account_id FROM bookings b LEFT JOIN properties p ON p.id = b.property_id WHERE b.id = $1`, [bookingId]);
    if (!b.rows[0]) return res.status(404).json({ success: false, error: 'booking not found' });
    if (decoded.role !== 'master_admin' && decoded.id !== b.rows[0].account_id) {
      return res.status(403).json({ success: false, error: 'forbidden' });
    }
    const t = await pool.query(`SELECT id, name, html_body, language FROM contract_templates WHERE id = $1 AND (account_id = $2 OR account_id IS NULL) AND is_active = true`, [templateId, b.rows[0].account_id]);
    if (!t.rows[0]) return res.status(404).json({ success: false, error: 'template not found or not accessible for this account' });
    const ctx = await contractsHydrateContext(pool, bookingId, { sign_token: 'PREVIEW' });
    const filledHtml = contractsRenderTemplate(t.rows[0].html_body, ctx);
    res.json({
      success: true,
      template_name: t.rows[0].name,
      template_language: t.rows[0].language,
      guest_email: b.rows[0].guest_email,
      guest_name: [b.rows[0].guest_first_name, b.rows[0].guest_last_name].filter(Boolean).join(' '),
      filled_html: filledHtml,
    });
  } catch (e) {
    console.error('[contract-preview]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /api/admin/bookings/:id/send-contract — { template_id }
// Merges the template with booking + property + landlord data,
// stores the filled HTML + a unique sign_token, emails the guest.
app.post('/api/admin/bookings/:id/send-contract', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const bookingId = parseInt(req.params.id, 10);
    const templateId = parseInt(req.body?.template_id, 10);
    if (!bookingId || !templateId) return res.status(400).json({ success: false, error: 'booking_id + template_id required' });

    const b = await pool.query(`
      SELECT b.id, b.guest_email, b.guest_first_name, b.guest_last_name,
             p.account_id, b.currency
        FROM bookings b LEFT JOIN properties p ON p.id = b.property_id
       WHERE b.id = $1`, [bookingId]);
    if (!b.rows[0]) return res.status(404).json({ success: false, error: 'booking not found' });
    const accountId = b.rows[0].account_id;
    if (decoded.role !== 'master_admin' && decoded.id !== accountId) {
      return res.status(403).json({ success: false, error: 'forbidden' });
    }
    if (!b.rows[0].guest_email) return res.status(400).json({ success: false, error: 'booking has no guest email' });

    const t = await pool.query(`
      SELECT id, name, html_body, language
        FROM contract_templates
       WHERE id = $1
         AND (account_id = $2 OR account_id IS NULL)
         AND is_active = true`, [templateId, accountId]);
    if (!t.rows[0]) return res.status(404).json({ success: false, error: 'template not found or not accessible for this account' });
    const template = t.rows[0];

    // Generate a unique sign token
    const signToken = require('crypto').randomBytes(24).toString('hex');
    const partialInstance = { sign_token: signToken };
    const ctx = await contractsHydrateContext(pool, bookingId, partialInstance);
    const filledHtml = contractsRenderTemplate(template.html_body, ctx);

    const ins = await pool.query(`
      INSERT INTO contract_instances
        (template_id, booking_id, account_id, sign_token, filled_html,
         status, guest_email, sent_at, created_at, updated_at)
      VALUES ($1, $2, $3, $4, $5, 'sent', $6, NOW(), NOW(), NOW())
      RETURNING id, sign_token, sent_at`,
      [template.id, bookingId, accountId, signToken, filledHtml, b.rows[0].guest_email]);

    const baseUrl = process.env.PUBLIC_URL || 'https://admin.gas.travel';
    const signUrl = `${baseUrl}/contract/sign/${signToken}`;
    const guestName = [b.rows[0].guest_first_name, b.rows[0].guest_last_name].filter(Boolean).join(' ') || 'there';
    const isFr = template.language === 'fr';

    // BCC the landlord on the outgoing "please sign" email so the operator
    // has a record in their own inbox of what was sent and when — useful
    // when a guest claims they never received the email. Owner email first
    // (that's the actual bailleur), account email as fallback.
    let landlordBcc = ctx?.landlord?.email || '';
    if (!landlordBcc) {
      const acc = await pool.query(`SELECT email FROM accounts WHERE id = $1`, [accountId]);
      landlordBcc = acc.rows[0]?.email || '';
    }

    // Property snippet for subject + body — guest / operator can tell at a
    // glance which booking this contract is for without opening it. Falls
    // back to just the name if there's no city.
    const propName = ctx?.property?.name || '';
    const propCity = ctx?.property?.city || '';
    const propSnippet = [propName, propCity].filter(Boolean).join(' — ');
    const arrivalStr = ctx?.booking?.arrival_date || '';

    try {
      await sendEmail({
        to: b.rows[0].guest_email,
        bcc: landlordBcc || undefined,
        accountId,
        bookingId,
        // Logs to guest_communications → shows in the Comms tab of the
        // booking modal + the guest's CRM record.
        context: {
          accountId, bookingId,
          eventType: 'contract_sent',
          autoCreateGuest: true,
          metadata: {
            contract_id: ins.rows[0].id,
            template_id: template.id,
            sign_url: signUrl,
            property: propSnippet,
          },
        },
        subject: isFr
          ? `Votre contrat de location${propSnippet ? ' — ' + propSnippet : ''} — merci de le signer`
          : `Your rental contract${propSnippet ? ' — ' + propSnippet : ''} — please sign`,
        html: `
          <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px;">
            <h2 style="color:#111;">${isFr ? 'Bonjour' : 'Hi'} ${guestName.replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]))},</h2>
            ${propSnippet ? `<p style="background:#f8fafc; border-left:3px solid #059669; padding:10px 14px; margin:16px 0; color:#334155;"><strong>${propSnippet.replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]))}</strong>${arrivalStr ? '<br><span style="font-size:0.9em; color:#64748b;">' + (isFr ? 'Arrivée / Check-in : ' : 'Check-in: ') + arrivalStr.replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c])) + '</span>' : ''}</p>` : ''}
            <p>${isFr
              ? "Merci pour votre réservation. Pour la confirmer, merci de signer le contrat en ligne et de régler l'acompte via le lien ci-dessous."
              : 'Thank you for your booking. To confirm it, please sign the contract online and pay the deposit via the link below.'}</p>
            <p style="text-align:center; margin: 24px 0;">
              <a href="${signUrl}" style="background:#059669; color:white; padding:12px 24px; border-radius:8px; text-decoration:none; font-weight:600; display:inline-block;">
                ${isFr ? 'Signer le contrat →' : 'Sign contract →'}
              </a>
            </p>
            <p style="color:#64748b; font-size:0.85rem;">${isFr
              ? 'Ce lien est unique et sécurisé. Si vous avez des questions, répondez simplement à cet email.'
              : 'This link is unique and secure. Reply to this email with any questions.'}</p>
          </div>`,
      });
    } catch (mailErr) {
      console.warn('[send-contract] email failed:', mailErr.message);
      // Non-fatal — contract is created, operator can copy the signUrl manually
    }

    res.json({ success: true, contract_id: ins.rows[0].id, sign_url: signUrl, sign_token: signToken });
  } catch (e) {
    console.error('[send-contract]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /contract/sign/:token/deposit-intent — creates a Stripe PaymentIntent
// on the account's connected Stripe (direct charge via `stripeAccount`).
// Public: token is the auth. Returns { client_secret, publishable_key,
// stripe_account, amount, currency }. The sign page calls this once, then
// stripe.confirmCardPayment() runs entirely client-side — no redirect.
app.post('/contract/sign/:token/deposit-intent', async (req, res) => {
  try {
    const token = String(req.params.token || '').replace(/[^A-Fa-f0-9]/g, '');
    if (!token) return res.status(400).json({ success: false, error: 'invalid token' });
    const r = await pool.query(`SELECT * FROM contract_instances WHERE sign_token = $1`, [token]);
    const c = r.rows[0];
    if (!c) return res.status(404).json({ success: false, error: 'contract not found' });
    if (c.signed_at) return res.status(400).json({ success: false, error: 'already signed' });
    if (c.deposit_status === 'paid') return res.status(400).json({ success: false, error: 'deposit already paid' });

    // Resolve deposit amount from owner > account_contract_settings, and
    // currency from the booking. This matches the same fallback chain the
    // template already uses so the guest sees exactly what's on the contract.
    const bk = await pool.query(`
      SELECT b.currency, b.deposit_amount, p.owner_id, p.account_id
        FROM bookings b LEFT JOIN properties p ON p.id = b.property_id
       WHERE b.id = $1`, [c.booking_id]);
    if (!bk.rows[0]) return res.status(404).json({ success: false, error: 'booking not found' });
    const currency = (bk.rows[0].currency || 'EUR').toLowerCase();

    let depositAmount = null;
    if (bk.rows[0].owner_id) {
      const o = await pool.query(`SELECT default_security_deposit FROM property_owners WHERE id = $1 AND is_active = true`, [bk.rows[0].owner_id]);
      depositAmount = o.rows[0]?.default_security_deposit ?? null;
    }
    if (depositAmount == null) {
      const s = await pool.query(`SELECT default_security_deposit FROM account_contract_settings WHERE account_id = $1`, [bk.rows[0].account_id]);
      depositAmount = s.rows[0]?.default_security_deposit ?? null;
    }
    depositAmount = parseFloat(depositAmount);
    if (!depositAmount || depositAmount <= 0) return res.status(400).json({ success: false, error: 'no deposit configured' });

    const acct = await pool.query(`SELECT stripe_account_id FROM accounts WHERE id = $1`, [c.account_id]);
    const stripeAcct = acct.rows[0]?.stripe_account_id || null;
    if (!stripeAcct) return res.status(400).json({ success: false, error: 'stripe not connected for this account' });

    const intent = await stripe.paymentIntents.create({
      amount: toStripeAmount(depositAmount, currency.toUpperCase()),
      currency,
      description: `Deposit — contract ${c.id} (booking ${c.booking_id})`,
      metadata: { contract_id: c.id, booking_id: c.booking_id, kind: 'contract_deposit' },
    }, { stripeAccount: stripeAcct });

    await pool.query(
      `UPDATE contract_instances
          SET deposit_payment_intent_id = $1, deposit_amount = $2, deposit_currency = $3,
              deposit_status = 'pending_card', updated_at = NOW()
        WHERE id = $4`,
      [intent.id, depositAmount, currency.toUpperCase(), c.id]);

    res.json({
      success: true,
      client_secret: intent.client_secret,
      publishable_key: process.env.STRIPE_PUBLISHABLE_KEY || '',
      stripe_account: stripeAcct,
      amount: depositAmount,
      currency: currency.toUpperCase(),
    });
  } catch (e) {
    console.error('[deposit-intent]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET /contract/sign/:token — public signing page. No auth. Renders
// the filled HTML preview + signature pad + consent + payment button.
app.get('/contract/sign/:token', async (req, res) => {
  try {
    const token = String(req.params.token || '').replace(/[^A-Fa-f0-9]/g, '');
    if (!token) return res.status(400).send('invalid token');
    const r = await pool.query(`SELECT * FROM contract_instances WHERE sign_token = $1`, [token]);
    if (!r.rows[0]) return res.status(404).send('contract not found');
    const c = r.rows[0];
    // Mark opened (first view only)
    if (!c.opened_at) {
      await pool.query(`UPDATE contract_instances SET opened_at = NOW(), status = CASE WHEN status = 'sent' THEN 'opened' ELSE status END WHERE id = $1`, [c.id]).catch(() => {});
    }
    // Resolve deposit amount + Stripe availability so the page can decide
    // whether to show the card path at all. Owner-first fallback (matches
    // the template rendering path).
    const bkD = await pool.query(`SELECT b.currency, p.owner_id, p.account_id FROM bookings b LEFT JOIN properties p ON p.id = b.property_id WHERE b.id = $1`, [c.booking_id]);
    let depositAmount = 0;
    let currencySym = '€';
    let currencyCode = 'EUR';
    let stripeAvailable = false;
    if (bkD.rows[0]) {
      currencyCode = (bkD.rows[0].currency || 'EUR').toUpperCase();
      currencySym = currencyCode === 'EUR' ? '€' : (currencyCode === 'GBP' ? '£' : (currencyCode === 'USD' ? '$' : currencyCode));
      if (bkD.rows[0].owner_id) {
        const oR = await pool.query(`SELECT default_security_deposit FROM property_owners WHERE id = $1 AND is_active = true`, [bkD.rows[0].owner_id]);
        depositAmount = parseFloat(oR.rows[0]?.default_security_deposit || 0);
      }
      if (!depositAmount) {
        const sR = await pool.query(`SELECT default_security_deposit FROM account_contract_settings WHERE account_id = $1`, [bkD.rows[0].account_id]);
        depositAmount = parseFloat(sR.rows[0]?.default_security_deposit || 0);
      }
      const aR = await pool.query(`SELECT stripe_account_id FROM accounts WHERE id = $1`, [c.account_id]);
      stripeAvailable = !!aR.rows[0]?.stripe_account_id;
    }
    const showDeposit = depositAmount > 0;
    const showCard = showDeposit && stripeAvailable;
    const depositLabel = depositAmount ? depositAmount.toFixed(2) + ' ' + currencySym : '';

    // Serve either the sign form OR (if already signed) a read-only view.
    const alreadySigned = !!c.signed_at;
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    res.send(`<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Contract — sign</title>
${showCard ? '<script src="https://js.stripe.com/v3/"></script>' : ''}
<style>
  body { font-family: -apple-system, Segoe UI, Arial, sans-serif; max-width: 900px; margin: 0 auto; padding: 24px; color:#111; background:#f8fafc; }
  .card { background:white; border-radius:12px; padding:32px; box-shadow: 0 2px 8px rgba(0,0,0,0.05); margin-bottom:16px; }
  .contract-body { font-size: 0.95rem; line-height: 1.55; }
  .sig-wrap { border: 2px dashed #d1d5db; border-radius:8px; padding:8px; background:#fafafa; }
  canvas { display:block; width: 100%; height: 180px; touch-action: none; background:white; border-radius:6px; }
  .btn { background:#059669; color:white; border:none; padding: 12px 24px; border-radius:8px; font-weight:600; cursor:pointer; font-size: 1rem; }
  .btn-secondary { background:#6b7280; }
  .btn:disabled { background:#9ca3af; cursor:not-allowed; }
  input[type=text] { width:100%; padding:10px; border:1px solid #d1d5db; border-radius:6px; font-size:1rem; box-sizing:border-box; }
  label { display:block; margin: 12px 0 4px; font-weight:500; }
  .signed-banner { background: #d1fae5; border: 1px solid #86efac; padding: 12px 16px; border-radius:8px; color:#065f46; font-weight:600; margin-bottom:16px; }
  .pay-choice { border: 1px solid #e5e7eb; border-radius:8px; padding:14px 16px; margin: 10px 0; cursor:pointer; background:#fafafa; }
  .pay-choice.selected { border-color:#059669; background:#ecfdf5; }
  .pay-choice input[type=radio] { margin-right: 10px; }
  #card-element { padding: 12px; border:1px solid #d1d5db; border-radius:6px; background:white; }
</style></head><body>
  ${alreadySigned ? `<div class="signed-banner">✓ This contract has been signed on ${new Date(c.signed_at).toLocaleString()}. A copy has been emailed to you.</div>` : ''}
  <div class="card contract-body">${c.filled_html}</div>
  ${alreadySigned ? '' : `
  <div class="card">
    <h3 style="margin-top:0;">Sign the contract</h3>
    <p style="color:#64748b; font-size:0.9rem;">Draw your signature below with your finger or mouse. This has the same legal effect as a wet-ink signature under eIDAS SES.</p>
    <div class="sig-wrap">
      <canvas id="pad"></canvas>
    </div>
    <div style="margin-top:8px; display:flex; gap:8px;">
      <button class="btn btn-secondary" type="button" onclick="clearSig()">Clear</button>
    </div>
    <label for="typedName">Type your full name to confirm (equivalent to "Lu et approuvé"):</label>
    <input type="text" id="typedName" placeholder="e.g. John Smith">
    <label style="font-weight:normal; margin-top:16px;">
      <input type="checkbox" id="consent"> I agree to sign this contract electronically and confirm the details above are correct.
    </label>

    ${showDeposit ? `
    <h4 style="margin-top:24px; margin-bottom:8px;">Dépôt de garantie / Deposit — ${depositLabel}</h4>
    ${showCard ? `
    <label class="pay-choice selected" id="choice-card-lbl">
      <input type="radio" name="pm" value="card" id="pm-card" checked>
      💳 Régler par carte maintenant / Pay by card now
    </label>` : `
    <div style="padding:10px; background:#fef3c7; border:1px solid #fde68a; border-radius:6px; font-size:0.85rem;">Card payment not yet available — please use bank transfer.</div>`}
    <label class="pay-choice ${!showCard ? 'selected' : ''}" id="choice-bank-lbl">
      <input type="radio" name="pm" value="bank" id="pm-bank" ${!showCard ? 'checked' : ''}>
      🏦 Je paierai par virement bancaire / Pay by bank transfer
    </label>
    ${showCard ? `
    <div id="card-wrap" style="margin-top:12px;">
      <label for="card-element" style="font-weight:500;">Card details</label>
      <div id="card-element"></div>
      <div id="card-errors" style="color:#dc2626; margin-top:6px; font-size:0.85rem;"></div>
    </div>` : ''}
    ` : ''}

    <div style="margin-top:20px; text-align:right;">
      <button class="btn" id="submitBtn" onclick="submitSig()" disabled>Sign contract</button>
    </div>
    <div id="msg" style="margin-top:12px; color:#dc2626; font-weight:600;"></div>
  </div>
  <script>
    const canvas = document.getElementById('pad');
    const ctx = canvas.getContext('2d');
    function resizeCanvas() { const r = canvas.getBoundingClientRect(); canvas.width = r.width * (window.devicePixelRatio||1); canvas.height = r.height * (window.devicePixelRatio||1); ctx.scale(window.devicePixelRatio||1, window.devicePixelRatio||1); ctx.lineWidth = 2; ctx.lineCap='round'; ctx.strokeStyle='#111'; }
    resizeCanvas(); window.addEventListener('resize', resizeCanvas);
    let drawing = false; let hasStrokes = false;
    const getPos = (e) => { const r = canvas.getBoundingClientRect(); const t = e.touches ? e.touches[0] : e; return { x: t.clientX - r.left, y: t.clientY - r.top }; };
    const start = (e) => { e.preventDefault(); drawing = true; hasStrokes = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); updateBtn(); };
    const move  = (e) => { if (!drawing) return; e.preventDefault(); const p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); };
    const end   = (e) => { drawing = false; };
    canvas.addEventListener('mousedown', start); canvas.addEventListener('mousemove', move); canvas.addEventListener('mouseup', end); canvas.addEventListener('mouseleave', end);
    canvas.addEventListener('touchstart', start); canvas.addEventListener('touchmove', move); canvas.addEventListener('touchend', end);
    function clearSig() { ctx.clearRect(0,0,canvas.width,canvas.height); hasStrokes = false; updateBtn(); }
    function updateBtn() {
      const ok = hasStrokes && document.getElementById('typedName').value.trim().length > 1 && document.getElementById('consent').checked;
      document.getElementById('submitBtn').disabled = !ok;
    }
    document.getElementById('typedName').addEventListener('input', updateBtn);
    document.getElementById('consent').addEventListener('change', updateBtn);

    // Payment method choice + Stripe Elements (only rendered when card path
    // is available). Elements are lazily created — we don't hit Stripe.js
    // until the guest has actually chosen the card option.
    let stripe = null; let cardElement = null; let depositIntent = null;
    const showCard = ${showCard ? 'true' : 'false'};
    async function ensureStripeMounted() {
      if (!showCard || cardElement) return;
      const iResp = await fetch('/contract/sign/${token}/deposit-intent', { method: 'POST' });
      const iJson = await iResp.json();
      if (!iJson.success) throw new Error(iJson.error || 'could not init payment');
      depositIntent = iJson;
      stripe = Stripe(iJson.publishable_key, { stripeAccount: iJson.stripe_account });
      const elements = stripe.elements();
      cardElement = elements.create('card', { hidePostalCode: false });
      cardElement.mount('#card-element');
      cardElement.on('change', (ev) => {
        document.getElementById('card-errors').textContent = ev.error ? ev.error.message : '';
      });
    }
    function refreshPmUi() {
      const cardChecked = document.getElementById('pm-card') && document.getElementById('pm-card').checked;
      const bankChecked = document.getElementById('pm-bank') && document.getElementById('pm-bank').checked;
      const cardLbl = document.getElementById('choice-card-lbl');
      const bankLbl = document.getElementById('choice-bank-lbl');
      if (cardLbl) cardLbl.classList.toggle('selected', !!cardChecked);
      if (bankLbl) bankLbl.classList.toggle('selected', !!bankChecked);
      const cardWrap = document.getElementById('card-wrap');
      if (cardWrap) cardWrap.style.display = cardChecked ? '' : 'none';
      if (cardChecked) ensureStripeMounted().catch(e => { document.getElementById('msg').textContent = 'Payment init failed: ' + e.message; });
    }
    ['pm-card','pm-bank'].forEach(id => { const el = document.getElementById(id); if (el) el.addEventListener('change', refreshPmUi); });
    if (showCard) ensureStripeMounted().catch(() => {});

    async function submitSig() {
      const btn = document.getElementById('submitBtn'); const msg = document.getElementById('msg');
      btn.disabled = true; btn.textContent = 'Working…'; msg.textContent = '';
      try {
        const chosen = (document.querySelector('input[name=pm]:checked') || {}).value || null;
        let paymentIntentId = null;
        if (chosen === 'card') {
          if (!depositIntent) await ensureStripeMounted();
          const cardResult = await stripe.confirmCardPayment(depositIntent.client_secret, { payment_method: { card: cardElement } });
          if (cardResult.error) throw new Error(cardResult.error.message);
          if (cardResult.paymentIntent.status !== 'succeeded') throw new Error('Payment status: ' + cardResult.paymentIntent.status);
          paymentIntentId = cardResult.paymentIntent.id;
        }
        const r = await fetch('/contract/sign/${token}/submit', {
          method: 'POST', headers: {'Content-Type':'application/json'},
          body: JSON.stringify({
            signature_data_url: canvas.toDataURL('image/png'),
            typed_name: document.getElementById('typedName').value.trim(),
            consent: true,
            payment_method: chosen,
            payment_intent_id: paymentIntentId,
          }),
        });
        const j = await r.json();
        if (!j.success) throw new Error(j.error || 'sign failed');
        window.location.reload();
      } catch (e) {
        msg.textContent = 'Error: ' + e.message;
        btn.disabled = false; btn.textContent = 'Sign contract';
      }
    }
  </script>`}
</body></html>`);
  } catch (e) {
    console.error('[contract sign page]', e);
    res.status(500).send('server error');
  }
});

// POST /contract/sign/:token/submit — captures signature + audit trail,
// stamps signature into stored HTML, marks signed, emails both parties.
// Body: { signature_data_url, typed_name, consent, payment_method?,
//         payment_intent_id? }. payment_method='card' means the client
// already confirmed the intent client-side — server verifies status is
// 'succeeded' on the connected account before flagging deposit_paid.
// payment_method='bank' just records intent; operator marks paid later.
app.post('/contract/sign/:token/submit', async (req, res) => {
  try {
    const token = String(req.params.token || '').replace(/[^A-Fa-f0-9]/g, '');
    const { signature_data_url, typed_name, consent, payment_method, payment_intent_id } = req.body || {};
    if (!token || !signature_data_url || !typed_name || !consent) {
      return res.status(400).json({ success: false, error: 'signature, typed name, and consent required' });
    }
    if (!/^data:image\/png;base64,/.test(signature_data_url)) {
      return res.status(400).json({ success: false, error: 'invalid signature format' });
    }
    const r = await pool.query(`SELECT * FROM contract_instances WHERE sign_token = $1`, [token]);
    if (!r.rows[0]) return res.status(404).json({ success: false, error: 'contract not found' });
    const c = r.rows[0];
    if (c.signed_at) return res.json({ success: true, already_signed: true, signed_at: c.signed_at });

    // Deposit flow: verify the Stripe PaymentIntent on the connected account
    // before marking paid. Bank path only requires the tick — operator confirms
    // funds landed later via admin.
    let depositStatusNext = c.deposit_status || 'not_required';
    let depositPaidAt = null;
    let pmChosen = null;
    if (payment_method === 'card') {
      if (!payment_intent_id) return res.status(400).json({ success: false, error: 'payment_intent_id required for card path' });
      const acct = await pool.query(`SELECT stripe_account_id FROM accounts WHERE id = $1`, [c.account_id]);
      const stripeAcct = acct.rows[0]?.stripe_account_id || null;
      if (!stripeAcct) return res.status(400).json({ success: false, error: 'stripe not connected' });
      try {
        const pi = await stripe.paymentIntents.retrieve(payment_intent_id, { stripeAccount: stripeAcct });
        if (pi.status !== 'succeeded') return res.status(400).json({ success: false, error: `payment not succeeded (status: ${pi.status})` });
        depositStatusNext = 'paid';
        depositPaidAt = new Date();
        pmChosen = 'card';
      } catch (piErr) {
        return res.status(400).json({ success: false, error: `payment verification failed: ${piErr.message}` });
      }
    } else if (payment_method === 'bank') {
      depositStatusNext = 'pending_bank';
      pmChosen = 'bank';
    }

    const ip = req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.socket.remoteAddress || null;
    const ua = req.headers['user-agent'] || null;

    // Stamp signature + audit footer into stored HTML so the record is
    // self-contained and provable without external lookups.
    const auditFooter = `
      <hr style="margin-top:32px; border:none; border-top:1px solid #e5e7eb;">
      <div style="margin-top:16px; padding:12px 16px; background:#f0fdf4; border:1px solid #86efac; border-radius:8px; font-family:Arial,sans-serif;">
        <div style="font-weight:600; color:#065f46; margin-bottom:8px;">✓ Contract signed electronically</div>
        <div style="font-size:0.85rem; color:#065f46;">
          <div><strong>Signature:</strong></div>
          <img src="${signature_data_url}" alt="signature" style="max-width:280px; max-height:120px; background:white; border:1px solid #d1fae5; border-radius:4px; padding:4px; margin:6px 0;">
          <div><strong>Typed confirmation:</strong> ${String(typed_name).replace(/[<>&"]/g, ch => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[ch]))}</div>
          <div><strong>Signed at:</strong> ${new Date().toISOString()}</div>
          <div><strong>IP:</strong> ${ip || '(unknown)'}</div>
          <div><strong>User agent:</strong> ${String(ua || '').replace(/[<>&"]/g, ch => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[ch])).slice(0,200)}</div>
          <div style="margin-top:8px; font-size:0.75rem; color:#065f46; opacity:0.7;">This audit trail is stored immutably and can be reproduced on demand for legal evidence purposes (eIDAS Simple Electronic Signature).</div>
        </div>
      </div>`;
    // Append a deposit note into the signed HTML so the emailed copy shows
    // which path the guest took (paid by card vs pay by bank later).
    let depositNote = '';
    if (pmChosen === 'card' && depositPaidAt) {
      depositNote = `
      <div style="margin-top:8px; padding:12px 16px; background:#eff6ff; border:1px solid #bfdbfe; border-radius:8px; font-family:Arial,sans-serif;">
        <div style="font-weight:600; color:#1e3a8a;">💳 Deposit paid by card</div>
        <div style="font-size:0.85rem; color:#1e3a8a;">Ref: ${String(payment_intent_id).replace(/[<>&"]/g, '')} · ${new Date().toISOString()}</div>
      </div>`;
    } else if (pmChosen === 'bank') {
      depositNote = `
      <div style="margin-top:8px; padding:12px 16px; background:#fefce8; border:1px solid #fde68a; border-radius:8px; font-family:Arial,sans-serif;">
        <div style="font-weight:600; color:#78350f;">🏦 Deposit to be paid by bank transfer</div>
        <div style="font-size:0.85rem; color:#78350f;">Please transfer the deposit to the bank details shown above quoting your surname + arrival date.</div>
      </div>`;
    }
    const signedHtml = c.filled_html + auditFooter + depositNote;

    await pool.query(`
      UPDATE contract_instances
         SET signature_data_url = $1,
             signature_typed_name = $2,
             signature_ip = $3,
             signature_ua = $4,
             signed_at = NOW(),
             status = 'signed',
             filled_html = $5,
             payment_method = $7,
             deposit_status = $8,
             deposit_paid_at = $9,
             updated_at = NOW()
       WHERE id = $6`,
      [signature_data_url, typed_name, ip, ua, signedHtml, c.id, pmChosen, depositStatusNext, depositPaidAt]);

    // On card + paid, promote a pending booking to confirmed. Never touch
    // other statuses ('blocked' / 'cancelled' etc.) — auto-flip is only safe
    // for the pending → confirmed transition.
    if (pmChosen === 'card' && depositStatusNext === 'paid') {
      await pool.query(`UPDATE bookings SET status = 'confirmed', updated_at = NOW() WHERE id = $1 AND status = 'pending'`, [c.booking_id]).catch(e => console.warn('[contract submit booking status]', e.message));
    }

    // Email both landlord (via account) and guest with the signed contract HTML
    try {
      const acc = await pool.query(`SELECT email FROM accounts WHERE id = $1`, [c.account_id]);
      const landlordEmail = acc.rows[0]?.email || null;
      const attachmentHtml = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;">${signedHtml}</body></html>`;
      const recipients = [c.guest_email, landlordEmail].filter(Boolean);
      for (const to of recipients) {
        // Only pass booking context on the guest send so the sign event lands
        // once in guest_communications (against the guest, not the landlord).
        const isGuest = to === c.guest_email;
        await sendEmail({
          to,
          subject: 'Signed contract — copy for your records',
          html: `<p>The rental contract has been signed. A full copy is below.</p>${attachmentHtml}`,
          ...(isGuest ? {
            accountId: c.account_id, bookingId: c.booking_id,
            context: {
              accountId: c.account_id, bookingId: c.booking_id,
              eventType: pmChosen === 'card' && depositStatusNext === 'paid'
                ? 'contract_signed_deposit_paid'
                : (pmChosen === 'bank' ? 'contract_signed_bank_pending' : 'contract_signed'),
              autoCreateGuest: true,
              metadata: {
                contract_id: c.id, payment_method: pmChosen || null,
                deposit_status: depositStatusNext,
                deposit_amount: c.deposit_amount || null,
                payment_intent_id: payment_intent_id || null,
              },
            },
          } : {}),
        }).catch(e => console.warn('[contract signed email]', to, e.message));
      }
    } catch (mailErr) {
      console.warn('[contract signed email wiring]', mailErr.message);
    }

    res.json({ success: true, signed_at: new Date().toISOString() });
  } catch (e) {
    console.error('[contract submit]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET /api/admin/bookings/:id/contract-status — latest contract instance for
// this booking (or null). Used by the booking view modal badge.
app.get('/api/admin/bookings/:id/contract-status', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const bookingId = parseInt(req.params.id, 10);
    const r = await pool.query(`
      SELECT ci.id, ci.sign_token, ci.status, ci.sent_at, ci.opened_at, ci.signed_at,
             ci.deposit_status, ci.deposit_amount, ci.deposit_currency,
             ci.deposit_paid_at, ci.payment_method, ci.account_id, ci.guest_email
        FROM contract_instances ci
       WHERE ci.booking_id = $1
       ORDER BY ci.id DESC LIMIT 1`, [bookingId]);
    const c = r.rows[0] || null;
    if (c && decoded.role !== 'master_admin' && decoded.id !== c.account_id) {
      return res.status(403).json({ success: false, error: 'forbidden' });
    }
    res.json({ success: true, contract: c });
  } catch (e) {
    console.error('[contract-status]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// POST /api/admin/contracts/:id/mark-deposit-paid — operator confirms the
// bank transfer landed. Flips deposit_status=paid + promotes booking pending
// → confirmed (same rule as card auto-flip: never touch other statuses).
app.post('/api/admin/contracts/:id/mark-deposit-paid', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const contractId = parseInt(req.params.id, 10);
    const r = await pool.query(`SELECT id, account_id, booking_id, deposit_status FROM contract_instances WHERE id = $1`, [contractId]);
    const c = r.rows[0];
    if (!c) return res.status(404).json({ success: false, error: 'contract not found' });
    if (decoded.role !== 'master_admin' && decoded.id !== c.account_id) {
      return res.status(403).json({ success: false, error: 'forbidden' });
    }
    await pool.query(`UPDATE contract_instances SET deposit_status = 'paid', deposit_paid_at = COALESCE(deposit_paid_at, NOW()), updated_at = NOW() WHERE id = $1`, [contractId]);
    await pool.query(`UPDATE bookings SET status = 'confirmed', updated_at = NOW() WHERE id = $1 AND status = 'pending'`, [c.booking_id]);
    res.json({ success: true });
  } catch (e) {
    console.error('[mark-deposit-paid]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET /api/admin/contracts/templates?account_id=… — list templates
// visible to the caller. Master sees all; account users see their
// own + platform templates (account_id IS NULL).
app.get('/api/admin/contracts/templates', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const accountId = decoded.role === 'master_admin'
      ? (parseInt(req.query.account_id, 10) || null)
      : decoded.id;
    let r;
    if (accountId) {
      r = await pool.query(`
        SELECT id, account_id, name, description, language, is_active,
               created_at, updated_at
          FROM contract_templates
         WHERE (account_id = $1 OR account_id IS NULL)
           AND is_active = true
         ORDER BY account_id NULLS LAST, id`, [accountId]);
    } else {
      r = await pool.query(`
        SELECT id, account_id, name, description, language, is_active,
               created_at, updated_at
          FROM contract_templates
         WHERE is_active = true
         ORDER BY account_id NULLS LAST, id`);
    }
    res.json({ success: true, templates: r.rows });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET /api/admin/bookings/:id/contracts — list contract instances
// for this booking so the booking view can show status.
app.get('/api/admin/bookings/:id/contracts', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const bookingId = parseInt(req.params.id, 10);
    if (!bookingId) return res.status(400).json({ success: false, error: 'invalid booking id' });
    const r = await pool.query(`
      SELECT ci.id, ci.template_id, ci.status, ci.guest_email,
             ci.sent_at, ci.opened_at, ci.signed_at, ci.deposit_paid_at,
             ci.sign_token,
             ct.name AS template_name, ct.language AS template_language
        FROM contract_instances ci
        LEFT JOIN contract_templates ct ON ct.id = ci.template_id
       WHERE ci.booking_id = $1
       ORDER BY ci.id DESC`, [bookingId]);
    res.json({ success: true, contracts: r.rows });
  } catch (e) {
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET /api/admin/accounts/:accountId/property-owners
// List all active property owners on this account. Powers the dropdown
// on the property edit page + the standalone Owners admin list.
app.get('/api/admin/accounts/:accountId/property-owners', async (req, res) => {
  try {
    const decoded = await extractAccountFromToken(req);
    if (!decoded) return res.status(401).json({ success: false, error: 'auth required' });
    const accountId = parseInt(req.params.accountId, 10);
    if (!Number.isFinite(accountId)) return res.status(400).json({ success: false, error: 'invalid account id' });
    if (decoded.role !== 'master_admin' && decoded.id !== accountId) {
      return res.status(403).json({ success: false, error: 'forbidden' });
    }
    const r = await pool.query(`
      SELECT o.*, (SELECT COUNT(*)::int FROM properties p WHERE p.owner_id = o.id) AS property_count
        FROM property_owners o
       WHERE o.account_id = $1
       ORDER BY o.is_active DESC, o.name`, [accountId]);
    res.json({ success: true, owners: r.rows });
  } catch (e) {
    console.error('[property-owners list]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

// GET /api/admin/property-owners/:id — single owner. Powers the edit
// modal so master admin doesn't need an account context set first
